[850] = { ["id"] = 850, ["name"] = "Kolkar Leaders", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["mapID"] = 10, ["description"] = "The centaurs have plagued the tauren for years. And recently, the Kolkar centaurs of the Barrens have grown into a real threat. Normally they were disorganized in these lands, but new leaders have risen among them. Rallying them. To preserve our holdings here, these centaur leaders must be destroyed. Bring me the head of Barak Kodobane. He camps west of these Forgotten Pools. Defeat him, then return to me.", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["rewardItems"] = { 5022 }, ["rewardChoices"] = { 59551, 59552, 59553, 131218 }, ["starts"] = { { ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552, ["mapID"] = 10 }, { ["npcID"] = 34841, ["x"] = 0.38, ["y"] = 0.464, ["mapID"] = 10 } }, ["ends"] = { { ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552, ["mapID"] = 10 }, { ["npcID"] = 34841, ["x"] = 0.38, ["y"] = 0.464, ["mapID"] = 10 } }, ["coords"] = { ["x"] = 0.378, ["y"] = 0.552, ["source"] = "quest_giver", ["mapID"] = 10 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 13, ["flags"] = 0 } } },
