[11208] = { ["id"] = 11208, ["name"] = "Delivery for Drazzit", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 11208 }, ["series"] = { 27348 }, ["description"] = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket? If you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve .", ["objectivesText"] = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket. Progress: Yes?", ["rewardXP"] = 260, ["rewardItems"] = { 33163 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 23797, ["x"] = 0.535, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 23572, ["x"] = 0.422, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["sourceQuests"] = { 27347, 27348 } },
