[13206] = { ["id"] = 13206, ["name"] = "Disarmament", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 206, ["mapID"] = 117, ["storyline"] = { 13206 }, ["description"] = "We must discover the secret to these savages' weapons! If you'd have seen how easily they cut through my companions, you'd understand my sense of urgency. Scour the place. Gather all of their arms that you can carry.", ["objectivesText"] = "Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to her inside Utgarde Keep . Progress: What have you got there, <class>?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 43513, 44374, 44375, 44376, 44377, 44400, 44401, 44402, 44403 }, ["starts"] = { { ["npcID"] = 24137 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 23780, ["x"] = 0.785, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 206 } }, ["questGiverID"] = 24137, ["questType"] = "dungeon" },
