[14127] = { ["id"] = 14127, ["name"] = "Return of the Highborne?", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 14127 }, ["series"] = { 14128 }, ["description"] = "The wax seal on these orders has been freshly broken. You can't read the carefully-penned night elven script, but a small hand-drawn map indicates the nearby ruins. Underneath the map, written in a different language entirely, are a series of runes penned in a metallic, shimmering ink. Ag'tor will no doubt want to see this important piece of intelligence.", ["objectivesText"] = "Deliver the Scout's Orders to Ag'tor Bloodfist at the rear gate to Orgrimmar. Progress: You found something on one of the bodies, you say? Give it here!", ["rewardGold"] = 280900, ["rewardXP"] = 555, ["rewardItems"] = { 47039, 47040 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 8576, ["x"] = 0.268, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 47039 } },
[14407] = { ["id"] = 14407, ["name"] = "Azshara Blues", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["description"] = "Hey! I'm glad I caught you. I come on behalf of my master, Kalec . He requires your aid. Find him under the bridge in the slums as soon as you can!", ["rewardGold"] = 52500, ["rewardXP"] = 370, ["starts"] = { { ["npcID"] = 36999, ["x"] = 0.594, ["y"] = 0.506, ["mapID"] = 76 } }, ["ends"] = { { ["npcID"] = 35867, ["x"] = 0.554, ["y"] = 0.52, ["mapID"] = 76 } }, ["coords"] = { ["x"] = 0.594, ["y"] = 0.506, ["source"] = "quest_giver", ["mapID"] = 76 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 500, ["name"] = "Azshara", ["orderIndex"] = 52, ["flags"] = 0 } } },
[14428] = { ["id"] = 14428, ["name"] = "Amberwind's Journal", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 14428 }, ["series"] = { 14429, 14430 }, ["description"] = "If my sources are trustworthy, Lorekeeper Amberwind is overseeing the Alliance investigation of the ruins to the east. I have not yet probed the extent of her abilities: I'm hoping you can give me a full report by engaging her in combat and destroying her. With a title like 'Lorekeeper,' I'm guessing Amberwind will have a journal on her that'll tell us exactly what those night elves are up to. Fetch that journal for me. No need to run back; use their own scrying stones to contact me remotely.", ["objectivesText"] = "Slay Lorekeeper Amberwind at the Darnassian Base Camp and retrieve her journal. Progress: <Andorel's distorted face appears within the scrying stone.> <name>, have you made contact? What can you tell me?", ["rewardXP"] = 740, ["rewardItems"] = { 49356 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 36596, ["x"] = 0.425, ["y"] = 0.237 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 36596, ["x"] = 0.425, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.237 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questTurnInID"] = 36596, ["questType"] = "standard" },
[14429] = { ["id"] = 14429, ["name"] = "Arcane De-Construction", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["storyline"] = { 14429 }, ["series"] = { 14428, 14430 }, ["description"] = "Arcane constructs are creatures spawned of pure mana and intellect. In the right hands, a construct allows its user to quickly assimilate vast riches of arcane knowledge. But they're dangerous, <name>. So intelligent! So powerful! So very vulnerable to external tampering... Let's teach these amateurs a lesson and use their own magic against them. Slay Apprentices and collect their runestones for me. Contact me via the lower scrying stone when you're done.", ["objectivesText"] = "Slay Apprentice Investigators and Apprentice Illuminators to collect 10 Attuned Runestones . Progress: <Andorel's image is blurry and indistinct. He squints at you and taps against the glass of the scrying stone.> <name>, is that you? The resolution on this stone is terrible. What kind of hardware are they using?", ["rewardXP"] = 740, ["rewardItems"] = { 49359 }, ["starts"] = { { ["x"] = 0.495, ["y"] = 0.287, ["mapID"] = 76, ["objectID"] = 196832 } }, ["ends"] = { { ["x"] = 0.495, ["y"] = 0.287, ["mapID"] = 76, ["objectID"] = 196832 } }, ["coords"] = { ["mapID"] = 76, ["x"] = 0.495, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16 } }, ["questType"] = "standard", ["sourceQuests"] = { 14428 } },
[14464] = { ["id"] = 14464, ["name"] = "Lightning Strike Assassination", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["description"] = "The base of the tower is patrolled by the Captain's elite guards. So here's what we're going to do: we're going to grapple straight up to the top, slice-and-dice the VIPs, and bail out using my portable low-altitude parachute . I'll rig the tower to explode behind us. You be sure to grab Captain Grunwald's head for Chawg . Got it? Do NOT accept this mission unless you are prepared for UNMITIGATED BADASSERY. Is that clear?", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["rewardItems"] = { 49540 }, ["rewardChoices"] = { 53425, 53412, 131360 }, ["starts"] = { { ["npcID"] = 36729, ["x"] = 0.12, ["y"] = 0.682, ["mapID"] = 76 } }, ["ends"] = { { ["npcID"] = 36730, ["x"] = 0.14, ["y"] = 0.648, ["mapID"] = 76 } }, ["coords"] = { ["x"] = 0.12, ["y"] = 0.682, ["source"] = "quest_giver", ["mapID"] = 76 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["sourceQuests"] = { 14462 }, ["questLines"] = { { ["id"] = 500, ["name"] = "Azshara", ["orderIndex"] = 80, ["flags"] = 0 } } },
[24441] = { ["id"] = 24441, ["name"] = "Thunderhorn Totem", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1638, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24456, 24457, 24523, 24524, 24540, 24550, 44498 }, ["description"] = "There is more work to be done. We must create a new totem to cleanse the Thunderhorn Well. You must gather the claws of the predators of the Mulgore plains. Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws , then return to me. You will find the prairie stalkers and flatland cougars to the east and west.", ["objectivesText"] = "Collect 6 Stalker Claws and 6 Cougar Claws . Progress: <name>, do you have the claws I sent you to gather? The Thunderhorn Water Well grows more tainted with each passing hour!", ["rewardXP"] = 200, ["rewardItems"] = { 4801, 4802 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["sourceQuests"] = { 24440 }, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7 },
[24455] = { ["id"] = 24455, ["name"] = "Rapid Deployment", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["description"] = "You will be reporting for active duty immediately. Captain Desoto is overseeing deployment just down the ramp at the rocket launch station. Make us rich, soldier. Dismissed!", ["rewardXP"] = 370, ["starts"] = { { ["npcID"] = 36749, ["x"] = 0.294, ["y"] = 0.576, ["mapID"] = 76 } }, ["ends"] = { { ["npcID"] = 36956, ["x"] = 0.58, ["y"] = 0.522, ["mapID"] = 76 } }, ["coords"] = { ["x"] = 0.294, ["y"] = 0.576, ["source"] = "quest_giver", ["mapID"] = 76 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["sourceQuests"] = { 14478 }, ["questLines"] = { { ["id"] = 500, ["name"] = "Azshara", ["orderIndex"] = 41, ["flags"] = 0 } } },
[24523] = { ["id"] = 24523, ["name"] = "Wildmane Totem", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24524, 24540, 24550, 44498 }, ["description"] = "There is but one water well left to cleanse, named after the Wildmane clan. For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha. Find the alphas to the north, then return to me when your hunt is finished. Alphas often wander around the base of our mighty city, Thunder Bluff.", ["objectivesText"] = "Collect 4 Prairie Alpha Teeth from Prairie Wolf Alphas. Progress: <name>. Do you have the teeth I asked for?", ["rewardXP"] = 200, ["rewardItems"] = { 4803 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["sourceQuests"] = { 20441 }, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["db2QuestSortName"] = "Epic" },
[24740] = { ["id"] = 24740, ["name"] = "Volcanic Activity", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 490, ["mapID"] = 78, ["description"] = "Welcome. I'm Williden Marshal , and my sister and I run this expedition of explorers and scientists. You have a moment? I don't like the look of those elementals on that volcano, . We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage. Show them that their new neighbors aren't to be trifled with. And bring back the ash that they leave behind... we might as well do a little science while we're at it.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 11829 }, ["starts"] = { { ["npcID"] = 9270, ["x"] = 0.55, ["y"] = 0.622, ["mapID"] = 78 } }, ["ends"] = { { ["npcID"] = 9270, ["x"] = 0.55, ["y"] = 0.622, ["mapID"] = 78 } }, ["coords"] = { ["x"] = 0.55, ["y"] = 0.622, ["source"] = "quest_giver", ["mapID"] = 78 }, ["mapCandidates"] = { ["npc"] = { 78 }, ["zone"] = { 490 } }, ["questType"] = "standard", ["sourceQuests"] = { 24911, 28525, 28526 }, ["questLines"] = { { ["id"] = 512, ["name"] = "Un'Goro Crater", ["orderIndex"] = 1, ["flags"] = 0 } } },
[24854] = { ["id"] = 24854, ["name"] = "Finding Stormclaw", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 490, ["mapID"] = 78, ["description"] = "Zen'Aliri been studyin' the ways of the druid, . Hopefully one day, Zen'Aliri join the Druids of the Talon, and soar over this crater as a storm crow. But for now, my mentor says I stay here and wait. So Zen'Aliri waits. I know another druid who might be able to use your help. His name is Garl Stormclaw , and he's somewhere to the east of here, studying reagents. Maybe you go talk to him?", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["npcID"] = 38269, ["x"] = 0.556, ["y"] = 0.606, ["mapID"] = 78 } }, ["ends"] = { { ["npcID"] = 38274, ["x"] = 0.71, ["y"] = 0.766, ["mapID"] = 78 } }, ["coords"] = { ["x"] = 0.556, ["y"] = 0.606, ["source"] = "quest_giver", ["mapID"] = 78 }, ["mapCandidates"] = { ["npc"] = { 78 }, ["zone"] = { 490 } }, ["questType"] = "standard", ["nextQuests"] = { 24719 } },
[25218] = { ["id"] = 25218, ["name"] = "Undersea Inflation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["series"] = { 25216, 25217, 25359, 25456 }, ["description"] = "Fine! Fine. You argued me into it. You can help. I'm leaking air worse than a zeppelin stuffed with quilboar! My air valve must have come loose somewhere in the trench. I brought spare air balloons - make yourself useful and go fill one up, will ya? And find my valve! I'll need that too. I bet the crabs snatched it up... pinchy, greedy little things.", ["objectivesText"] = "Fill one of Sambino's Air Balloons and find his Lost Air Valve. Progress: If only air weren't so darn floaty! Or if only those water breathing spells came with stylish helmets! Either would do nicely.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 54608, 54611, 54614, 55171, 55186, 62281 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 39882, ["x"] = 0.642, ["y"] = 0.347 } }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 39882, ["x"] = 0.642, ["y"] = 0.347 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.347 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard", ["sourceQuests"] = { 25216 }, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 54, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 205 },
[25234] = { ["id"] = 25234, ["name"] = "In the Rear With the Gear", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25234 }, ["description"] = "Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better. Kill the slave drivers along the road to our south and nearby slaves should make a break for it. Search the packs they leave behind for anything valuable, and destroy anything you can't carry.", ["objectivesText"] = "Collect 36 Twilight Supplies left behind from freed Twilight Slaves. Progress: Have you created some havoc down there, <name>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 52568, 57383, 57384, 57385 }, ["rewardChoices"] = { 57385, 57384, 57383 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39427, ["x"] = 0.316, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39427, ["x"] = 0.316, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25584 }, ["db2QuestSortName"] = "Engine of Innovation" },
[25274] = { ["id"] = 25274, ["name"] = "Signed in Blood", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25276, 25597, 25653, 25915, 25923, 25928 }, ["description"] = "You're here at last, <name>. Just in time as well. News of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer. If you're to infiltrate the cult, the time is now. We will need recruitment papers -- signed in blood by a referring Twilight member. Lure one of the new recruits away from the group and hit them with this blackjack . If you're lucky, you'll be able to steal his recruitment papers. Bring them back to me and we'll do our best to alter them.", ["objectivesText"] = "Lure a Twilight Recruit away from the group and take his Twilight Recruitment Papers . Progress: Did you get the papers?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 52683, 52685, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39621, ["x"] = 0.414, ["y"] = 0.403 } 