[25276] = { ["id"] = 25276, ["name"] = "Your New Identity", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25274, 25597, 25653, 25915, 25923, 25928 }, ["description"] = "There. Not my best work, but certainly not my worst. You will be known as \"<name>damus\" among the cultists. These papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors. Go to the proving grounds and show these to Condenna the Pitiless . She's separating the wheat from the chaff. Show her what you're made of.", ["objectivesText"] = "Speak to Condenna the Pitiless at the Training Grounds in Hyjal. Progress: You will address me with the respect I am due, recruit.", ["rewardGold"] = 68700, ["rewardXP"] = 2060, ["rewardItems"] = { 52693 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39621, ["x"] = 0.414, ["y"] = 0.403 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39442, ["x"] = 0.458, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver"