[25321] = { ["id"] = 25321, ["name"] = "Twilight Captivity", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25320, 25324, 25325, 25424, 25430, 25578 }, ["description"] = "I'd been scouting behind enemy lines for nearly a day when they caught me. This attack on our frontlines is not what it appears, <name>. I'll give you all the details, but first let's find a way to get me out of here. Only the overseers carry keys to these cages. From what I recall, they're in the middle of the crater, in the thick of it. See if you can get a key off of one of them.", ["objectivesText"] = "Obtain a Twilight Overseer's Key at the Twilight Command Post in Hyjal. Progress: The key, <name>. Did you get it?", ["rewardGold"] = 103050, ["rewardXP"] = 3085, ["rewardItems"] = { 53139, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40096, ["x"] = 0.445, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40096, ["x"] = 0.445, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25320 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25328] = { ["id"] = 25328, ["name"] = "Gar'gol's Gotta Go", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["description"] = "<Kristoff cranes his neck, trying to look you in the eye.> Listen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both. They've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key! <Kristoff flails his limbs, helplessly.>", ["objectivesText"] = "Get the Rusted Skull Key from Gar'gol's Personal Treasure Chest. Progress: Key? Now? Please?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 6657, 52789 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39640, ["x"] = 0.272, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39640, ["x"] = 0.272, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25272 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25358] = { ["id"] = 25358, ["name"] = "Nerve Tonic", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 25358 }, ["description"] = "How am I feelin', you ask? Well, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good! My nerves are gettin' the best of me, to be honest. If you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...", ["objectivesText"] = "Mack wants you to collect 5 Sunken Cargo in Kelp'thar Forest . Progress: Were ya able to grab some supplies, <race>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 52973, 52974, 53053, 54345, 54639, 55186 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 40983, ["x"] = 0.571, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 40983, ["x"] = 0.571, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["sourceQuests"] = { 25602 } },
[25372] = { ["id"] = 25372, ["name"] = "Aessina's Miracle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25830, 25842 }, ["description"] = "<The finger-like branches of one of Nordu 's burning limbs part, revealing an untouched, glimmering seed.> This is the Heart of the Forest . The seed of life. Take this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old. Thank you, <race>. My time is done.", ["objectivesText"] = "Take the Heart of the Forest to Hamuul Runetotem at the Grove of Aessina in Mount Hyjal . Progress: I am at my wit's end, <name>! Aessina is silent. Have you found something? What is this?", ["rewardGold"] = 13740, ["rewardXP"] = 515, ["rewardItems"] = { 56057, 57264, 57265, 57266, 57267, 65661, 65662 }, ["rewardChoices"] = { 57267, 57266, 57265, 57264 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41381, ["x"] = 0.2745, [