[25377] = { ["id"] = 25377, ["name"] = "The Horde's Hoard", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 25377 }, ["description"] = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks. Scanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck. You cannot help but wonder what the scaly, serpentine figure on the map might represent....", ["objectivesText"] = "You must defeat Akasha to obtain the Horde Chest Key which you must then use to open the Sunken Horde Chest . Progress: This slightly encrusted lock might still be functional.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 53054, 54345, 54639, 55186, 59788 }, ["rewardChoices"] = { 59788 }, ["ends"] = { { ["npcID"] = 202759, ["x"] = 0.579, ["y"] = 0.352, ["mapID"] = 201 } }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 53053 } },
[25385] = { ["id"] = 25385, ["name"] = "Save the Wee Animals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25392 }, ["description"] = "Help us, <class>! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet. They have wet little noses! If you don't save them, I don't want to even THINK about it. <She slaps her palms over her eyes.> I'm not thinking!", ["objectivesText"] = "Go into the Inferno and rescue any combination of 10 Panicked Bunnies or Terrified Squirrels. Progress: Did you save the wee animals? And their wee little friends?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 30632, 53060, 60854, 71076, 104297 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39930, ["x"] = 0.322667, ["y"] = 0.424667 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39930, ["x"] = 0.322667, ["y"] = 0.424667 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.322667, ["y"] = 0.424667 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25578 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 40, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25388] = { ["id"] = 25388, ["name"] = "Crate of Crab Meat", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 25388 }, ["description"] = "This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship. Adarrah would surely welcome such a find, considering the ordeal she's had to endure.", ["objectivesText"] = "Take the Crate of Crab Meat to Adarrah in Smuggler's Scar. Progress: What have you got there, <name>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 30632, 53053, 53061, 54345, 54639, 55186, 68609 }, ["starts"] = { { ["x"] = 0.496, ["y"] = 0.408, ["mapID"] = 201, ["objectID"] = 202871 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["sourceQuests"] = { 25587 } },
[25389] = { ["id"] = 25389, ["name"] = "A Taste For Tail", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["description"] = "It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry. I hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach. If you come across any lobster types, I would happily pay you what coin I have with me for their tails.", ["objectivesText"] = "Adarrah wants you to bring her 4 Clacksnap Tails . Progress: Oh, please tell me you were able to find me some food, <class>.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 53073, 54345, 54639, 55186 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["sourceQuests"] = { 25598 }, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 201 },
[25390] = { ["id"] = 25390, ["name"] = "A Girl's Best Friend", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["description"] = "Let's just get it out in the open. I'm no stranger to love, <name>. Over the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion. I've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go. At least I used to... When I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", ["objectivesText"] = "Adarrah wants you to recover 6 Adarrah's Keepsakes . Progress: Well, <race>? Were you able to recover my valuables?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 47500, 53053, 53074, 54345, 54639, 55186, 59792, 59793, 59794 }, ["rewardChoices"] = { 59793, 59794, 59792 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["sourceQuests"] = { 25598 }, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 201 },
[25408] = { ["id"] = 25408, ["name"] = "Seeds of Their Demise", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25404, 25411, 25412, 25428, 25443 }, ["description"] = "We will decimate the Twilight's Hammer by corrupting and subverting them. Seeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower. My little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", ["objectivesText"] = "Collect 8 Bileberries . Progress: Has the local flora been giving you a hard time? <Blackhorn grins disturbingly.>", ["rewardXP"] = 4115, ["rewardItems"] = { 53102, 57323, 57324, 57325 }, ["rewardChoices"] = { 57325, 57324, 57323 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 