[25419] = { ["id"] = 25419, ["name"] = "Lady La-La's Medallion", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 25419 }, ["description"] = "Dozens of crude gold links make up this heavy chain. Dangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion. You wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.", ["objectivesText"] = "Collect the 5 Medallion Fragments from Gilblin Collectors and combine them to create Lady La-La's Medallion .", ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 55186, 55187, 55188, 59782, 59783, 59784 }, ["rewardChoices"] = { 59784, 59783, 59782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 55186 } },
[25428] = { ["id"] = 25428, ["name"] = "Black Heart of Flame", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25404, 25408, 25411, 25412, 25443 }, ["description"] = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him. The ritual is simple: take this charred branch , tap it on the ground three times, and utter his name aloud. You must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", ["objectivesText"] = "Use the Charred Branch within The Inferno to Summon Thol'embaar. Kill him and take the Black Heart of Thol'embaar . Progress: Tell me! Have you fought Thol'embaar yet? I am living vicariously through you, <race>. Do not disappoint!", ["rewardXP"] = 4115, ["rewardItems"] = { 53454, 53464, 57320, 57321, 57322, 60223, 60975, 65661, 65662, 67145 }, ["rewardChoices"] = { 57321, 57320, 57322 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.413, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25412, 25443 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 47, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25467] = { ["id"] = 25467, ["name"] = "Kliklak's Craw", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 25467 }, ["description"] = "You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible. It clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk. A well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.", ["objectivesText"] = "Obtain the Corroded Key from Kliklak to unlock the Half-buried Footlocker in the Kelp'thar Forest . Progress: The footlocker's keyhole is encrusted with barnacles, but may still be operable.", ["rewardGold"] = 561800, ["rewardXP"] = 4115, ["rewardItems"] = { 54344, 54345, 55186, 59798 }, ["rewardChoices"] = { 59798 }, ["ends"] = { { ["npcID"] = 202859, ["x"] = 0.466, ["y"] = 0.475, ["mapID"] = 201 } }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 54345 } },
[25472] = { ["id"] = 25472, ["name"] = "The Flameseer's Staff", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25323, 25464 }, ["description"] = "A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces. It was an ancient bone staff that granted its wielder power over the elements of fire. Its fragments litter the area around us. Find them and bring them to Malfurion. Perhaps the artifact's power will still be of use.", ["objectivesText"] = "Obtain 8 Bone Staff Fragments. Progress: Yes, <name>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 54461 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39869, ["x"] = 0.476, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39857, ["x"] = 0.476, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25317 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25491] = { ["id"] = 25491, ["name"] = "Durable Seeds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25491 }, ["series"] = { 25382, 25462, 25490, 25940 }, ["description"] = "This land has been scourged by fire, but it may yet renew itself. Some seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.", ["objectivesText"] = "Gather 10 Hyjal Seedlings from piles of Scorched Soil. Progress: I suspect life still struggles beneath the ash. What were you able to find?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 54574, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.5015 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25490 }, ["db2QuestSortName"] = "Engine of Innovation" },
[25493] = { ["id"] = 25493, ["name"] = "Fresh Bait", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25507, 25510 }, ["description"] = "I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake. Freeing Tortolla from his bonds will not be easy. But we will take it one step at a time. Head into the Flamewake and collect for me heaps of core hound entrails . I will explain why later. And beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.", ["objectivesText"] = "Collect 4 heaps of Core Hound Entrails . Progress: Have you collected the innards? Core hounds are not native to this part of the world, they accompanied Twilight's Hammer from the nether regions of the earth. Do not trouble yourself over their elimination.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 54609, 57351, 57352, 57353, 65661, 65662 }, ["rewardChoices"] = { 57352, 57351, 57353 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.5015 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25490 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 51, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25494] = { ["id"] = 25494, ["name"] = "A Champion's Collar", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25294 }, ["description"] = "This little guy is a true menace now, isn't he? We're going to have to give him a nice spiked collar if he's going to be a fighting pup. The basilisk matriarch has made her lair off of the road to Winterspring. Bring me her spiked hide and we'll fashion a collar for our little killer here.", ["objectivesText"] = "Obtain the Spiked Basilisk Hide from the Spinescale Matriarch. Progress: Did you get it?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 54610 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39406, ["x"] = 0.683333, ["y"] = 0.447333 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39406, ["x"] = 0.683333, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.447333 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25294 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 97, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25503] = { ["id"] = 25503, ["name"] = "Blackfin's Booty", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["storyline"] = { 25503 }, ["description"] = "<A torn page precedes the latest entry, which reads:> Our self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end. I can't take it anymore! I've buried the treasure and fed the map to Blackfin. That should keep my cousin's grubby little mitts off of our precious heirlooms!", ["objectivesText"] = "You must slay the orca, Blackfin, to retrieve Gilblingle's Map . Progress: You've discovered Gilblingle's family treasure!", ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 54640, 55186, 59779, 59780, 59781 }, ["rewardChoices"] = { 59781, 59780, 59779 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.52, ["mapID"] = 201 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.52, ["mapID"] = 201 } }, ["coords"] = { ["mapID"] = 201, ["x"] = 0.511, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 54639 } },
[25507] = { ["id"] = 25507, ["name"] = "Hell's Shells", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25493, 25510 }, ["description"] = "Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer. Nemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient. Go into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.", ["objectivesText"] = "Use the Heap of Core Hound Innards near Nemesis to distract him. Collect a Nemesis Shell Fragment . Progress: Nemesis is a molten ball of fury protected by a stony shell of pure hatred. His time will come.", ["rewardGold"] = 117960, ["rewardXP"] = 4115, ["rewardItems"] = { 54744, 54745, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] 