[25599] = { ["id"] = 25599, ["name"] = "Cindermaul, the Portal Master", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25600 }, ["description"] = "Twilight's Hammer is using these corridors, and others like them, to move supplies from the elemental planes up into Azeroth. In order to seal these passages off, we're going to need to know how they're constructed. Find for me the Tome of Openings , used by the elementals to open gates between the planes. Cindermaul the Portal Master should have one. You'll have to kill him. Careful! He's probably got some tricks up his sleeve...", ["objectivesText"] = "Slay Cindermaul and locate the Tome of Openings . Progress: The tome! Have you found it?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 55136 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40834, ["x"] = 0.262, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40834, ["x"] = 0.262, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25575, 25576, 25577 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 35, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25602] = { ["id"] = 25602, ["name"] = "Can't Start a Fire Without a Spark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["description"] = "Mack's still out of it, and I fear we may lose him if I can't get this fire started. With the wood being soaked, we'll need something special to get it going. There's an abandoned camp nearby with a barrel of explosives in it. There's no way I can recover it on my own. Would you mind hauling it back for us? For Mack?", ["objectivesText"] = "Get the Keg of Gunpowder from Budd's Dig. Progress: Did you get the explosives from the camp, <class>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 55143, 55186 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 39884, ["x"] = 0.572, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39884, ["x"] = 0.572, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["sourceQuests"] = { 25598 }, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 201 },
[25656] = { ["id"] = 25656, ["name"] = "Scrambling for Eggs", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25655, 25731 }, ["description"] = "There's a pattern to these Wormwing attacks. While groups make a showy assault on the shrine itself, others swoop into the nearby nests and make off with eggs from all the flying creatures of Hyjal. These animals are under our protection. Before we find out why the Wormwing are doing this, it's up to us to rescue as many eggs as we can from their talons.", ["objectivesText"] = "Gather 8 Hyjal Eggs . Progress: <Thisalee is cleaning her nails with a dagger. She looks up at you expectantly.>", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 55189, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25578 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 59, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25664] = { ["id"] = 25664, ["name"] = "A Prayer and a Wing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25663, 25665, 25985, 27874 }, ["description"] = "A winged visage? Could it be...? <name>, there's no time to waste. You may have been speaking to Aviana herself, trying to return to us. I'll need something from Aviana's past to reach out to her. High atop the ridge overlooking this shrine, you'll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he's been mad with grief. Go to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.", ["objectivesText"] = "Use the Enormous Bird Call at one of Blaithe's Nests perched atop the Rim of the World. Kill Blaithe and gather one of his Ancient Feathers . Progress: Don't trouble yourself over Blaithe's condition. Grief robbed that creature of a soul epochs ago. He was but a shell of his former self, a beast of pure rage.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 44338, 44339, 44340, 44341, 55210, 55211, 57339, 57340, 57341, 65661, 65662 }, ["rewardChoices"] = { 57341, 57340, 57339 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25663, 25665 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 61, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25732] = { ["id"] = 25732, ["name"] = "A Bone to Pick", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["series"] = { 25651, 25657, 25670, 25743, 27699 }, ["description"] = "We did it! Gnaws is down, and I have our shiney! That's good news. Darn shiney is cursed treasure - makes everyone who touches it a skeleton. That's bad news. These cursed pirates say the Gilblin King has the secret to remove the hex. That's good news. I can't step foot outside the reef or I'll be cursed forever. That's bad news.", ["objectivesText"] = "Budd wants you to collect the Pewter Pounder from King Gurboggle at Gurboggle's Ledge. Progress: So, <race>... You gunna remove this curse, or what?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 55186, 55805 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 46458, ["x"] = 0.584, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 46458, ["x"] = 0.584, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["sourceQuests"] = { 25670 }, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 34, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 201 },
[25758] = { ["id"] = 25758, ["name"] = "A Gap in Their Armor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25761 }, ["description"] = "Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose. Those Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating! Run out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.", ["objectivesText"] = "Gather 8 Twilight Armor Plates . Progress: Did you get a hold of some plates? Did you have to kill anyone to get them? I hope so.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 55809, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25740 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 63, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[25761] = { ["id"] = 25761, ["name"] = "Disassembly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25758 }, ["description"] = "We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath. Take my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor. Once they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!", ["objectivesText"] = "Use Thisalee's Shiv to awaken and kill 3 Twilight Juggernauts . The shiv can be used multiple times to tear down a Juggernaut's armor. Progress: Oh good. You're still alive.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 55883, 57312, 57313, 57314, 57315, 65661, 65662 }, ["rewardChoices"] = { 57314, 57313, 57312, 57315 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] 