[25776] = { ["id"] = 25776, ["name"] = "Sethria's Demise", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25795, 25807 }, ["description"] = "While you've been raiding Sethria 's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself. Everyone agreed to my plan... provided YOU spearhead the attack. Take this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!", ["objectivesText"] = "Slay the dragon Sethria . Once she reveals her true form, you will need to use the signal rocket to call in reinforcements! Progress: If a minor dragon like Sethria can cause us so many problems, I hate to see what else Twilight's Hammer has in store...", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 56003 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 25761, 25764 }, ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 68, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
