[26096] = { ["id"] = 26096, ["name"] = "Scalding Shrooms", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["description"] = "We think that we have a use for the merciless ones that your friend from the cave delivered to us. But I need a preservative for it. Down below in the Scalding Chasm are some mushrooms with the properties that I need. Bring some back up to me and I'll see what I can do.", ["objectivesText"] = "Collect 5 Scalding Shrooms . Progress: I heard that you had an unpleasant encounter with putting one of the demons on your head. I can assure you that they are now all quite dead.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 56571, 56810, 57102 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41639, ["x"] = 0.503, ["y"] = 0.5805 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41639, ["x"] = 0.503, ["y"] = 0.5805 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5805 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["sourceQuests"] = { 25987, 25988 }, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 204 },
[26111] = { ["id"] = 26111, ["name"] = "... It Will Come", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["series"] = { 26072, 26130, 26140 }, ["description"] = "I now imbue you with the energies of the corrupting faceless. Swim down to my luring totem in the trench to the northeast. Release the energies through it. Bring back the brain of their leader. Call forth to Ick'thys the Unfathomable... it will come!", ["objectivesText"] = "Obtain the Brain of the Unfathomable . Progress: Do you have it, <name>? With the Unfathomable's brain, we still may yet be able to communicate with L'ghorek, the dying ancient one in front of us.", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardItems"] = { 56822, 59617, 59618, 59619, 68833 }, ["rewardChoices"] = { 59618, 59619, 59617 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41600, ["x"] = 0.503, ["y"] = 0.5805 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41600, ["x"] = 0.503, ["y"] = 0.5805 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5805 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["sourceQuests"] = { 26072, 26096 }, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 204 },
[26140] = { ["id"] = 26140, ["name"] = "Communing with the Ancient", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["series"] = { 26072, 26111, 26130 }, ["description"] = "Place the dead merciless one upon your head to pose as one of their slaves. Enter L'ghorek . Commune with the ancient.", ["objectivesText"] = "Deliver the Brain of the Unfathomable to L'ghorek in the Cerebrillum inside of L'ghorek in Vashj'ir. Progress: I SENSE... SOMETHING. COME CLOSER....", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 53048, 56822 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41600, ["x"] = 0.503, ["y"] = 0.5805 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 42197, ["x"] = 0.385, ["y"] = 0.449 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5805 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["sourceQuests"] = { 26130 }, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 34, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 204 },
[26141] = { ["id"] = 26141, ["name"] = "Runestones of Binding", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["series"] = { 26142, 26143, 26154 }, ["description"] = "ON THE OTHER... SIDE OF... MY CHAMBER THERE... ARE... CANDIDATES FOR ASCENSION. WE WILL NEED... THEIR... RUNESTONES OF BINDING... TO CREATE A... MEANS OF CONTROLLING... A BOUND ELEMENTAL.", ["objectivesText"] = "Collect 7 Runestones of Binding . Progress: DO... YOU HAVE... ALL THAT IS... REQUIRED?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 56571, 57096, 57102 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 42197, ["x"] = 0.385, ["y"] = 0.449 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 42197, ["x"] = 0.385, ["y"] = 0.449 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.449 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["sourceQuests"] = { 26140 }, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 35, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 204 },
[26194] = { ["id"] = 26194, ["name"] = "Defending the Rift", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["description"] = "The whispers of the elements are crowding my thoughts, ... The Throne of Tides is under siege! I cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him. Nazgrim will escort me to the depths where I can commune directly with Neptulon. I must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides. May the spirits see us through, .", ["rewardGold"] = 412200, ["rewardXP"] = 6175, ["rewardChoices"] = { 59601, 59602, 59603 }, ["starts"] = { { ["npcID"] = 41600, ["x"] = 0.426, ["y"] = 0.378, ["mapID"] = 204 } }, ["ends"] = { { ["npcID"] = 44540, ["x"] = 0.696, ["y"] = 0.344, ["mapID"] = 204 } }, ["coords"] = { ["x"] = 0.426, ["y"] = 0.378, ["source"] = "quest_giver", ["mapID"] = 204 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["sourceQuests"] = { 26182 }, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 42, ["flags"] = 0 } } },
[26259] = { ["id"] = 26259, ["name"] = "Blood of the Earthwarder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["description"] = "When Deathwing escaped to Deepholm , his corruption was extreme, but perhaps not yet absolute. The cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power. What if a trace of the Earthwarder's essence remains? After all, Neltharion was the aspect of earth before he was the aspect of death. Gather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.", ["objectivesText"] = "Gather 5 samples of Blood of Neltharion from Living Blood at Deathwing's Fall. Progress: You return, <name>. Did you obtain the blood?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 41611, 55699, 59062, 61490, 61491, 61492 }, ["rewardChoices"] = { 61492, 61491, 61490 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26255 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 44, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26296] = { ["id"] = 26296, ["name"] = "Evidence Collection", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["mapID"] = 52, ["storyline"] = { 26296 }, ["description"] = "The material of this bandana is identical to the material found at the Furlbrow murder scene. You should collect more red bandanas as evidence and return what you find to Captain Alpert .", ["objectivesText"] = "Collect 6 Red Bandanas . Progress: Red bandanas ?!", ["rewardXP"] = 740, ["rewardItems"] = { 58117, 58118, 58921, 58922, 58923, 131505 }, ["rewardChoices"] = { 58923, 58922, 58921, 131505 }, ["starts"] = { { ["x"] = 0.426, ["y"] = 0.694, ["mapID"] = 52 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 42425, ["x"] = 0.42, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 40 } }, ["questType"] = "standard", ["sourceQuests"] = { 26292 }, ["startItems"] = { 58117 } },
[26297] = { ["id"] = 26297, ["name"] = "The Dawning of a New Day", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["mapID"] = 52, ["description"] = "It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, . Go to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.", ["rewardGold"] = 280900, ["rewardXP"] = 555, ["rewardItems"] = { 248801 }, ["starts"] = { { ["npcID"] = 42425, ["x"] = 0.42, ["y"] = 0.64, ["mapID"] = 52 } }, ["ends"] = { { ["npcID"] = 42425, ["x"] = 0.42, ["y"] = 0.64, ["mapID"] = 52 } }, ["coords"] = { ["x"] = 0.42, ["y"] = 0.64, ["source"] = "quest_giver", ["mapID"] = 52 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 40 } }, ["questType"] = "standard", ["sourceQuests"] = { 26295 }, ["questLines"] = { { ["id"] = 421, ["name"] = "Westfall", ["orderIndex"] = 18, ["flags"] = 0 } } },
[26354] = { ["id"] = 26354, ["name"] = "Captain Sanders' Hidden Treasure", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["storyline"] = { 26354 }, ["series"] = { 26353, 26355, 26356 }, ["description"] = "The clue to the treasure reads: Good work, matey! Now ye need to head due east. East up the bluffs, east to the road. Look for the ol' chimney ruins near the side of the road. There you'll find an old barrel with your next clue.", ["objectivesText"] = "Find the old barrel near the ruined chimney and search it for your next clue. Progress: This looks like the right barrel.", ["rewardGold"] = 280900, ["rewardXP"] = 370, ["rewardItems"] = { 1358, 2842, 3342, 3343 }, ["starts"] = { { ["x"] = 0.259, ["y"] = 0.478, ["mapID"] = 52, ["objectID"] = 307330 } }, ["ends"] = { { ["x"] = 0.259, ["y"] = 0.478, ["mapID"] = 52, ["objectID"] = 307330 } }, ["coords"] = { ["mapID"] = 52, ["x"] = 0.259, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard", ["sourceQuests"] = { 26353 } },
[26355] = { ["id"] = 26355, ["name"] = "Captain Sanders' Hidden Treasure", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["storyline"] = { 26355 }, ["series"] = { 26353, 26354, 26356 }, ["description"] = "Searching through the barrel you discover another piece of parchment. This one reads: Now from this here barrel, face ye North. Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs. If ye poke around that jug , ye just might find what you're lookin' for.", ["objectivesText"] = "Search the empty jug next to the windmill for the next clue. Progress: There's a clue sticking out of the empty jug .", ["rewardGold"] = 280900, ["rewardXP"] = 370, ["rewardItems"] = { 1361, 2842, 3342, 3343 }, ["starts"] = { { ["x"] = 0.405, ["y"] = 0.478, ["mapID"] = 52, ["objectID"] = 307307 } }, ["ends"] = { { ["x"] = 0.405, ["y"] = 0.478, ["mapID"] = 52, ["objectID"] = 307307 } }, ["coords"] = { ["mapID"] = 52, ["x"] = 0.405, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard", ["sourceQuests"] = { 26354 } },
[26394] = { ["id"] = 26394, ["name"] = "Continue to Stormwind", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 26394 }, ["series"] = { 26393, 26395, 26396 }, ["description"] = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric. You won't get there faster any other way. If that sounds acceptable, then just speak to me again when you're ready for the ride. I'll charge you a little, but trust me; it'll be worth it!", ["objectivesText"] = "Buy a gryphon ride from the gryphon master Bartlett the Brave , then bring Argus' Note to Osric Strang , in the shop Limited Immunity, in the Old Town of Stormwind. Progress: You've been traveling, eh? Have you been anywhere interesting?", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["rewardItems"] = { 58364 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 42983, ["x"] = 0.417, ["y"] = 0.645 }, { ["mapID"] = 37, ["npcID"] = 43000, ["x"] = 0.818, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1323, ["x"] = 0.77, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.417, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 26393 } },
[26395] = { ["id"] = 26395, ["name"] = "Dungar Longdrink", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 84, ["storyline"] = { 26395 }, ["series"] = { 26393, 26394, 26396 }, ["description"] = "<name>, I gathered into this crate everything Argus asked for. Can you take it to him? If you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him. Dungar Longdrink is our gryphon master, over in the trade district. Speak with Dungar, then get this crate to Argus as fast as you can. We don't want our fighting men and women in Goldshire to go without fresh equipment!", ["objectivesText"] = "Bring Osric's Crate to Dungar Longdrink the gryphon master. Progress: Is that sweat on your brow, lad? You've been running too much. Next time, take a gryphon!", ["rewardXP"] = 50, ["rewardItems"] = { 16115 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 1323, ["x"] = 0.77, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 352, ["x"] = 0.618, ["y"] = 0.728667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.77, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 26394 } },
[26410] = { ["id"] = 26410, ["name"] = "Explosive Bonding Compound", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26411, 26413, 26484, 27135, 27931 }, ["description"] = "This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count! We know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment? My heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.", ["objectivesText"] = "Collect 5 Quartzite Resin . Progress: It won't take much resin. Those rock flayers are pretty dangerous though.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 58501 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26409 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26427] = { ["id"] = 26427, ["name"] = "Without a Captain or Crew", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26249 }, ["description"] = "Not sure who you're with, but you don't look like one of... them. I'm not sure what happened. I slept through supper and woke up to a ship full of dead people and murderers. Not sure if you want to kill me or not, but I'll spare you the trouble. <Moody points to a wound in his stomach. His insides are not where they should be.> I can keep steering the ship for a while longer. You don't die from a gut wound immediately. Just bring me some rope and some rum... no, whiskey.", ["objectivesText"] = "Bring First Mate Moody a Bottle of Whiskey and a Spool of Rope . Progress: You have what I asked for?", ["rewardGold"] = 103050, ["rewardXP"] = 3085, ["rewardItems"] = { 58798, 58806, 61484, 61495, 61500 }, ["rewardChoices"] = { 61495, 61500, 61484 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43082, ["x"] = 0.62815, ["y"] = 0.45905 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43082, ["x"] = 0.62815, ["y"] = 0.45905 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.62815, ["y"] = 0.45905 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26249 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 38, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26437] = { ["id"] = 26437, ["name"] = "Making Things Crystal Clear", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26312, 26313, 26314, 26315, 26326, 26328, 26375, 26376, 26377, 26426, 26436, 26437, 26438, 26439, 26440, 26441, 26507, 26575, 26576, 26577, 26578, 26579, 26580, 26581, 26582, 26583, 26584, 26585, 26656, 26657, 26658, 26659, 26750, 26752, 26827, 26828, 26829, 26831, 26832, 26833, 26869, 26871, 26875, 26971 }, ["description"] = "Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us. I do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself. Bring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.", ["objectivesText"] = "Collect 8 Chalky Crystal Formations . Progress: Have you done this favor that I asked of you? Did you bring the crystals?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 58845 }, ["starts"] = { { ["x"] = 0.344, ["y"] = 0.344, ["mapID"] = 207, ["npcID"] = 42469 } }, ["ends"] = { { ["x"] = 0.344, ["y"] = 0.344, ["mapID"] = 207, ["npcID"] = 42469 } }, ["coords"] = { ["mapID"] = 207, ["x"] = 0.344, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5042 } }, ["questGiverID"] = 42469, ["questTurnInID"] = 42469, ["questType"] = "standard", ["sourceQuests"] = { 26436 }, ["questLines"] = { { ["id"] = 544, ["name"] = "Deepholm, The Stone Throne", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26502] = { ["id"] = 26502, ["name"] = "Thunder Stones", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26500, 26564 }, ["description"] = "To the north lies the Fractured Front. That is where most of the heavy fighting is happening. Go into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults. When you have enough, take them to Clay Mudaxle . Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.", ["objectivesText"] = "Collect 12 Thunder Stones . Progress: <The older Earthen has cracks where the others do not, clearly ancient.> What are you supposed to be? Some kind of fleshy mistake? Cursed is what you are! <Clay spits dust.> Make yourself useful or get off of my front!", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 58886 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43160, ["x"] = 0.282, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43169, ["x"] = 0.246, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26500 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26507] = { ["id"] = 26507, ["name"] = "Petrified Delicacies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26312, 26313, 26314, 26315, 26326, 26328, 26375, 26376, 26377, 26426, 26436, 26437, 26438, 26439, 26440, 26441, 26507, 26575, 26576, 26577, 26578, 26579, 26580, 26581, 26582, 26583, 26584, 26585, 26656, 26657, 26658, 26659, 26750, 26752, 26827, 26828, 26829, 26831, 26832, 26833, 26869, 26871, 26875, 26971 }, ["description"] = "Petrified bats. Elementals of that size are picky. You're not likely to find anything better easily. To the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory. I must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.", ["objectivesText"] = "Gather 12 Petrified Stone Bats for Pebble . Progress: < Pebble starts to look up at you, eyes glowing faintly, growing rounder and larger every moment.>", ["rewardXP"] = 4115, ["rewardItems"] = { 58959 }, ["starts"] = { { ["x"] = 0.344, ["y"] = 0.344, ["mapID"] = 207, ["npcID"] = 42469 } }, ["ends"] = { { ["x"] = 0.344, ["y"] = 0.344, ["mapID"] = 207, ["npcID"] = 42469 } }, ["coords"] = { ["mapID"] = 207, ["x"] = 0.344, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5042 } }, ["questGiverID"] = 42469, ["questTurnInID"] = 42469, ["questType"] = "standard", ["sourceQuests"] = { 26441 }, ["questLines"] = { { ["id"] = 544, ["name"] = "Deepholm, The Stone Throne", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26625] = { ["id"] = 26625, ["name"] = "Troggzor the Earthinator", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26499, 26501, 26537, 27932, 27933, 27934, 27935, 27936 }, ["description"] = "You have to put an end to this now! Go back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.", ["objectivesText"] = "Obtain the Earthinator's Cudgel . Progress: Is he dead? Do you have the cudgel?", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardItems"] = { 59144, 61457, 61458, 61459 }, ["rewardChoices"] = { 61459, 61458, 61457 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43168, ["x"] = 0.245, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43168, ["x"] = 0.245, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26537, 26564, 26591 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[26766] = { ["id"] = 26766, ["name"] = "Big Game, Big Bait", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26768, 26771, 26857, 26876 }, ["description"] = "We're only going to get one shot at capturing Abyssion, <name>. Let's make it count. We'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf. To lure the stone matriarch, we're going to need to gather sufficient bait. Take this knife and carve 5 sides of basilisk meat. That ought to be enough even for her appetite.", ["objectivesText"] = "Use Mylra's Knife to obtain 5 Sides of Basilisk Meat from dead Jadecrest Basilisks. Progress: Did you obtain the meat?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 0, 60297, 60382 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44010, ["x"] = 0.645, ["y"] = 0.821 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44010, ["x"] = 0.645, ["y"] = 0.821 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.821 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 27061 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 52, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[27047] = { ["id"] = 27047, ["name"] = "Motes", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27047 }, ["description"] = "Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much. As a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?", ["objectivesText"] = "Recover 10 Motes of Painite. Progress: Painite is one of the most valuable materials to us, particularly due to our inability to reach most of the deposits on our own.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 60791, 177698, 178874, 178880, 178881, 178882, 178883, 185717, 189544, 190189, 190341, 190343, 190344, 190345, 190346, 190348, 190351, 190352, 190353, 190354, 190355, 190356, 190358, 190359, 190360, 190361, 190363, 190364, 190366, 190368, 190369, 190371, 190372, 190605, 190632, 190633, 190634, 192423, 192424, 192425, 192427, 192429, 192430, 192440, 192450, 192451, 195210 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26709 } },
[27048] = { ["id"] = 27048, ["name"] = "Underground Economy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27048 }, ["description"] = "Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits. Use these bombs to blow out chunks from the bigger formations. I've got a nasty habit of packin' the explosives a bit thick. Mind the kick.", ["objectivesText"] = "Use Ricket's Tickers to gather 3 Deep Alabaster Crystals , 3 Deep Celestite Crystals , 3 Deep Amethyst Crystals , and 3 Deep Garget Crystals. Progress: Boom?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 65504, 65507, 65508, 65510, 65514 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44968, ["x"] = 0.612, ["y"] = 0.262 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44968, ["x"] = 0.612, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26709 } },
[27051] = { ["id"] = 27051, ["name"] = "Through Persistence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27051 }, ["description"] = "The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse. Hunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.", ["objectivesText"] = "Retrieve a Bag of Verlok Miracle-Grow from the Verloks upon the Crimson Expanse. Progress: Have you done as I've asked of you? We must weed out the whatever growth agent remains within their possession.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 38626, 60767, 60768 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44973, ["x"] = 0.595, ["y"] = 0.14 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44973, ["x"] = 0.595, ["y"] = 0.14 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.14 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26709 } },
[27135] = { ["id"] = 27135, ["name"] = "Something that Burns", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26410, 26411, 26413, 26484, 27931 }, ["description"] = "Alright, we need something that's going to make the compound go, \"Boom\"! I'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental! Here, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.", ["objectivesText"] = "Obtain the Burning Heart . Progress: You have the heart yet?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 60834, 60837 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26409 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[27176] = { ["id"] = 27176, ["name"] = "A Strange Disc", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27179, 27196, 27511 }, ["description"] = "The etching around the surface of this object indicates that it is of ancient origins, and yet no signs of wear can be detected. A hole on its edge, full of splintered wood, indicates that it is meant to be put atop a wooden staff of some sort. Before showing this to Doctor Jones, you should find the other piece.", ["objectivesText"] = "Obtain the Sultan's Staff , then use the Elaborate Disc to create the Shaft of the Stars . Progress: Yes, <name>?", ["rewardGold"] = 169800, ["rewardXP"] = 1030, ["rewardItems"] = { 60859, 60865, 60868, 65887, 65888, 65889, 166846 }, ["rewardChoices"] = { 65889, 65888, 65887 }, ["starts"] = { { ["x"] = 0.648, ["y"] = 0.295, ["mapID"] = 249, ["objectID"] = 205266 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 45180, ["x"] = 0.645, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27141, 28112 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 49, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27179] = { ["id"] = 27179, ["name"] = "Field Work", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27176, 27196, 27511 }, ["description"] = "This unfortunate pygmy was in the wrong place at the wrong time. As you ponder his bad luck, you take notice of the symbols covering his shield - far too elaborate for pygmy scrawl. Confident that Doctor Jones will find such objects of interest, you set out to find more fragments like this one.", ["objectivesText"] = "Collect 10 Ancient Tablet Fragments. Progress: What'dya have there, friend?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60860 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 45186, ["x"] = 0.646, ["y"] = 0.286 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 45180, ["x"] = 0.645, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27141, 28112 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 48, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27303] = { ["id"] = 27303, ["name"] = "Mercy for the Bound", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 26293, 26294, 26311, 26324, 26335, 26337, 26358, 26361, 26372, 26374, 26388, 26538, 26539, 26540, 26549, 26608, 26619, 26621, 26622, 26784, 26786, 26788, 26798, 26830, 26840, 27177, 27178, 27299, 27300, 27301, 27302, 27303, 27338, 27341, 27366, 27376, 27377, 27378, 27379, 27380, 27433, 27468, 27485, 27486, 27490, 27491, 27492, 27493, 27494, 27495, 27496, 27497, 27498, 27499, 27500, 27501, 27502, 27503, 27504, 27505, 27506, 27507, 27508, 27509, 27514, 27515, 27516, 27537, 27538, 27545, 27564, 27576, 27583, 27584, 27586, 27588, 27590, 27606, 27607, 27608, 27609, 27610, 27611, 27621, 27622, 27636, 27637, 27638, 27639, 27640, 27641, 27642, 27643, 27644, 27645, 27646, 27647, 27648, 27649, 27650, 27651, 27652, 27653, 27654, 27655, 27657, 27658, 27659, 27660, 27661, 27662, 27688, 27689, 27690, 27695, 27696, 27700, 27701, 27702, 27703, 27719, 27720, 27742, 27743, 27744, 27745, 27747, 27750, 27751, 27752, 27753, 27754, 27784, 27786, 27787, 27788, 27798, 27803, 27804, 27805, 27806, 27807, 27808, 27809, 27810, 27811, 27812, 27813, 27814, 27815, 27816, 27817, 27861, 27862, 27863, 27864, 27865, 27866, 27867, 27868, 27929, 27945, 27947, 27951, 27954, 27955, 27999, 28041, 28043, 28090, 28091, 28092, 28093, 28094, 28097, 28101, 28103, 28104, 28107, 28108, 28109, 28123, 28133, 28171, 28173, 28175, 28176, 28191, 28211, 28212, 28215, 28233, 28234, 28238, 28241, 28242, 28243, 28244, 28247, 28248, 28249, 28280, 28281, 28282, 28294, 28346, 28377, 28378, 28379, 28407, 28408, 28409, 28410, 28411, 28413, 28583, 28584, 28586, 28588, 28589, 28590, 28591, 28592, 28593, 28594, 28595, 28596, 28597, 28598, 28599, 28655, 28712, 28758, 28832, 28849, 28885 }, ["series"] = { 27301 }, ["description"] = "It goes without saying that I had no desire to stay here, but there were materials we needed for the ritual... I delayed to secure them, and that is what lead to my capture. I will return to the circle, but I would be indebted to you if you would finish what I could not. We need hearts from the bound fire elementals that the Twilight's Hammer enslave in the western portion of the encampment. The elementals are without hope, but in this sacrifice they can extract their revenge. Find me at camp.", ["objectivesText"] = "Gather 5 Fleshburner Hearts . Progress: Did you recover the hearts?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60981, 60982, 63784, 63785, 63786 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 45362, ["x"] = 0.442, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 45386, ["x"] = 0.438, ["y"] = 0.112 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["sourceQuests"] = { 27301 }, ["questLines"] = { { ["id"] = 546, ["name"] = "Twilight Highlands", ["orderIndex"] = 146, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 241 },
[27357] = { ["id"] = 27357, ["name"] = "The Captive Bride", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["description"] = "Of course! Lakota Windsong ! Why didn't I think of this before? Arnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again. She has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["starts"] = { { ["npcID"] = 45277 } }, ["ends"] = { { ["npcID"] = 45442, ["x"] = 0.39, ["y"] = 0.258, ["mapID"] = 64 } }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questGiverID"] = 45277, ["questType"] = "standard", ["sourceQuests"] = { 27320, 27325, 27327 }, ["questLines"] = { { ["id"] = 521, ["name"] = "Thousand Needles", ["orderIndex"] = 85, ["flags"] = 0 } } },
[27358] = { ["id"] = 27358, ["name"] = "The Captive Bride", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["description"] = "Lakota Windsong ! Why did I not think of this before? Arnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again. She must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["starts"] = { { ["npcID"] = 45278 } }, ["ends"] = { { ["npcID"] = 45442, ["x"] = 0.39, ["y"] = 0.258, ["mapID"] = 64 } }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questGiverID"] = 45278, ["questType"] = "standard", ["sourceQuests"] = { 27321, 27326, 27328 }, ["questLines"] = { { ["id"] = 521, ["name"] = "Thousand Needles", ["orderIndex"] = 86, ["flags"] = 0 } } },
[27385] = { ["id"] = 27385, ["name"] = "Uncle Carlin", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 27367, 27368, 27369, 27370, 27371, 27372, 27373, 27381, 27382, 27383, 27384, 27385, 27386, 27387, 27388, 27389, 27390, 27391, 27392, 27448, 27455, 27459, 27460, 27461, 27462, 27463, 27464, 27465, 27466, 27487, 27488, 27489, 27522, 27524, 27526, 27527, 27551, 27612, 27613, 27614, 27615, 27616, 27617, 27618, 27619, 27620 }, ["series"] = { 27384, 27386, 27392 }, ["description"] = "I'm going to play with dolly, but I don't want to play with daddy's sword after all. You'd better keep it. Even better, can you give it to my uncle Carlin? I'm not sure where he is, but sometimes I hear him crying. It sounds like he's nearby, to the north. I hope he's not crying for me! <name>, will you find my uncle and tell him I'm alright? If you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam! That story's so funny!", ["objectivesText"] = "Return to Carlin Redpath at Crown Guard Tower in Eastern Plaguelands . Progress: Any news of my Pammy?", ["rewardXP"] = 260, ["rewardItems"] = { 60987 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 10926, ["x"] = 0.324667, ["y"] = 0.836 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 11063, ["x"] = 0.355, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.324667, ["y"] = 0.836 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["sourceQuests"] = { 27384, 27392 }, ["questLines"] = { { ["id"] = 406, ["name"] = "Eastern Plaguelands", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 23 },
[27386] = { ["id"] = 27386, ["name"] = "A Strange Historian", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 27367, 27368, 27369, 27370, 27371, 27372, 27373, 27381, 27382, 27383, 27384, 27385, 27386, 27387, 27388, 27389, 27390, 27391, 27392, 27448, 27455, 27459, 27460, 27461, 27462, 27463, 27464, 27465, 27466, 27487, 27488, 27489, 27522, 27524, 27526, 27527, 27551, 27612, 27613, 27614, 27615, 27616, 27617, 27618, 27619, 27620 }, ["series"] = { 27384, 27385, 27392 }, ["description"] = "That sword belonged to Joseph Redpath, Pamela's father - though you probably already knew that. I wish Joseph could again be with his daughter, but it cannot be so. His soul was twisted by the Scourge, and he became a monster. Pamela's fate is sealed, but perhaps we can change Joseph's fate. A strange gnome arrived here at this tower not long ago. Her name is Chromie . Take that sword to her. I have a feeling she will be able to help us.", ["objectivesText"] = "Bring Joseph's Hunting Blade to Chromie . Progress: There is something timely about your visit. You're not from the future, are you?", ["rewardXP"] = 260, ["rewardItems"] = { 60987 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 11063, ["x"] = 0.355, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 10667, ["x"] = 0.352, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["sourceQuests"] = { 27385 }, ["questLines"] = { { ["id"] = 406, ["name"] = "Eastern Plaguelands", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 23 },
