[27549] = { ["id"] = 27549, ["name"] = "By the Light of the Stars", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27541 }, ["description"] = "Look at this, <name>. <Harrison holds up the dead scout's goggles.> I tightened the clamp in the middle and crimped the wires on the edges. They may not be the most comfortable, but they should hold together. If I've translated your tablets correctly, there's something hidden here - a final piece to our puzzle. I hope your spectacles hold the key. Let me know what you find!", ["objectivesText"] = "Collect 7 Suspended Starlight . Progress: So? Find anything interesting?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 53010, 61376, 61509 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 45296, ["x"] = 0.498667, ["y"] = 0.423333 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 45296, ["x"] = 0.498667, ["y"] = 0.423333 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.498667, ["y"] = 0.423333 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27511, 27517,