[27624] = { ["id"] = 27624, ["name"] = "After the Fall", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27431, 27517, 27669, 28602 }, ["description"] = "Aww, that was nothin', really. Those statues were teetering as it was - just needed a little push is all. How about you go and sort through that rubble? I've got a feeling we're close to getting this all sorted out.", ["objectivesText"] = "Collect the Orb of the Morning Star , the Orb of the Evening Star , Orb of the North Star and the Orb of the Shooting Star . Progress: Find anything interesting, <name>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 61044, 61975, 61976, 61977 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 45296, ["x"] = 0.498667, ["y"] = 0.423333 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 45296, ["x"] = 0.498667, ["y"] = 0.423333 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.498667, ["y"] = 0.423333 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27431 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 57, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27706] = { ["id"] = 27706, ["name"] = "The Scepter of Orsis", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27595, 27602, 27623 }, ["description"] = "The chest below unlocks with a loud click as you insert the two stones into the plaque. Obtain the scepter and bring it back to General Ammantep .", ["objectivesText"] = "Obtain the Scepter of Orsis from the Sacred Receptacle. Progress: You're back, <name>!", ["rewardGold"] = 103050, ["rewardXP"] = 3085, ["rewardItems"] = { 62267, 65806, 65807, 65808 }, ["rewardChoices"] = { 65807, 65806, 65808 }, ["starts"] = { { ["x"] = 0.396, ["y"] = 0.454, ["mapID"] = 249, ["objectID"] = 205874 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 45772, ["x"] = 0.452, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27623 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27839] = { ["id"] = 27839, ["name"] = "Ancient Weapons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27839 }, ["series"] = { 28201 }, ["description"] = "Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories. King Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors. My scouts report that the Neferset are about to move a major shipment of looted weapons south of here. I've instructed the laborers you recruited to assist you. Call upon them with this horn when you find the smugglers and recover the weapons.", ["objectivesText"] = "Retrieve the Ancient Tol'vir Armaments . Progress: You've returned, <name>. How did the operation go?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 62533, 62534, 65834, 65835, 65836 }, ["rewardChoices"] = { 65836, 65835, 65834 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 46134, ["x"] = 0.373, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 46134, ["x"] = 0.373, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 28201 } },
