[27928] = { ["id"] = 27928, ["name"] = "A Favor for the Furrier", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27926, 27941, 28132, 29809 }, ["description"] = "The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him. Before building up his... ehh... workforce, he dealt in the furs of animals. He is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts. The dried oasis to the east is said to be home to a rare breed of coyote. Their furs would make a very thoughtful gift.", ["objectivesText"] = "Collect 5 Desert Coyote Pelts . Progress: Were you successful in your hunt?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 62776, 65865, 65866, 65867 }, ["rewardChoices"] = { 65867, 65866, 65865 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27926 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 65, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27938] = { ["id"] = 27938, ["name"] = "The Middle Fragment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26791, 26792, 26835, 26836, 27937 }, ["description"] = "I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar . Keep the fragment safe, <name>. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible! Know that you are always welcome here.", ["objectivesText"] = "Recover the Middle Fragment of the World Pillar . Progress: You've returned. Did you recover the middle fragment?", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardItems"] = { 60575, 61395, 61396, 61397 }, ["rewardChoices"] = { 61397, 61396, 61395 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44204, ["x"] = 0.279, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42573, ["x"] = 0.495333, ["y"] = 0.533333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.279, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 27937 }, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 31, ["flags"] = 0 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[27941] = { ["id"] = 27941, ["name"] = "Fashionism", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27926, 27928, 28132, 29809 }, ["description"] = "We have a strict policy among our ranks, one that we take most seriously. Our troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful! We call it, Fashionism. We've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty. You should find plenty of the poor fellows east of here, at the Ruins of Ammon.", ["objectivesText"] = "Belloc Brightblade wants you to collect 10 Trooper Uniforms . Progress: Were you able to recover the uniforms we need?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 62789, 65858, 65859, 65860 }, ["rewardChoices"] = { 65860, 65859, 65858 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27928 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 67, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27942] = { ["id"] = 27942, ["name"] = "Idolatry", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27939, 27943, 27950 }, ["description"] = "Zhere is somezhink I need handled, <race>. My most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings! I haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual. I vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce! Dismissed!", ["objectivesText"] = "Commander Schnottz wants you to collect 8 Well-preserved Idols . Progress: Haff you brought me zhe idols, <race>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 25568, 25569, 25570, 62792 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.811 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27939 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 68, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[27943] = { ["id"] = 27943, ["name"] = "Angered Spirits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27939, 27942, 27950 }, ["description"] = "Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery. He did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence. It is of key importance in zhe ritual I vill be attemptink. Vhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material. Zhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.", ["objectivesText"] = "Commander Schnottz wants you to use the L.P.A.C. to collect 5 Furious Spectral Essences . Progress: Vell, little man? Vere you successful?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 7734, 10507, 18588, 62793, 62794, 77589, 86570, 124382, 137663 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.811 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27939 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 69, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[28105] = { ["id"] = 28105, ["name"] = "Kavem the Callous", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "Kavem was cruel enough before the Neferset signed up with Deathwing. His pleasure in deriving pain now borders on the insane. It is he who now holds the keys to our shackles. He dwells in the building next to us, to my right. Find him and take the key from him. Do not hesitate or show him mercy. He will slit your throat and think nothing of it.", ["objectivesText"] = "Obtain the Neferset Key from Kavem the Callous. Progress: You're back. Do you have the key?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 62817, 65819, 65820, 65821 }, ["rewardChoices"] = { 65820, 65819, 65821 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 46872, ["x"] = 0.596, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 46872, ["x"] = 0.596, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27922 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[28141] = { ["id"] = 28141, ["name"] = "Relics of the Sun King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28141 }, ["description"] = "The Seal of the Sun King serves as a defense mechanism for Ramkahen. When the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders. They attacked this holy site on their way west and robbed it of the relics which once provided its power. Recover the relics for us. Without them we are powerless to defend against attacks from the desert.", ["objectivesText"] = "Obtain 4 Relics of the Sun King . Progress: Did you succeed?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 63081 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47715, ["x"] = 0.53, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47715, ["x"] = 0.53, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 28112 } },
[28200] = { ["id"] = 28200, ["name"] = "The Element of Supplies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28200 }, ["description"] = "You'll notice that we're slightly ill prepared for battle. The tol'vir tribes had never seen any sort of major confrontation for thousands of years. All the combat protocols that the titans programmed into our ancestors are still there, though. Some are part of our instincts, some get passed on as tradition. But none of this can compensate for lack of supplies. We need weapons. We need armor. The best armor is lined with the skin of the riverbed crocolisks nearby. Help us gather some.", ["objectivesText"] = "Collect 20 Hardened Crocolisk Hides . Progress: I am glad to see you don't think you're above this sort of task.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 63256, 65837, 65838, 65839, 65840 }, ["rewardChoices"] = { 65839, 65838, 65837, 65840 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48012, ["x"] = 0.373, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48012, ["x"] = 0.373, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 27631 } },
[28350] = { ["id"] = 28350, ["name"] = "Master Trapper", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27990, 28187, 28193, 28195, 28267, 28269, 28273, 28274 }, ["description"] = "One thing about me that you might not know, <name>... I come from a long line of trappers. My father taught me, as his taught him, to master the art of trapping creatures in a most merciful manner. As any master trapper will tell you, the most important ingredient in an effective trap is the bait. So let's start there. Fill this bucket with the meat scraps from almost any wild creature in Uldum .", ["objectivesText"] = "Sullah wants you to collect 5 Meat Scraps from the wildlife in Uldum . Progress: Have you got enough to fill my bucket, <name>?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 63541 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48431, ["x"] = 0.466667, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48431, ["x"] = 0.466667, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.466667, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 28274 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 82, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[28483] = { ["id"] = 28483, ["name"] = "Bleeding the Enemy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "I will not lie to you, <name>. We face a tremendous challenge ahead of us. As you go behind the enemy lines into Neferset City, I want you to bring back the insignia of any Neferset scum you defeat. It will be a boon to our armies to know that you've dealt a crushing blow to the enemy.", ["objectivesText"] = "Obtain 10 Neferset Insignia . Progress: It is good to see you once more, <name>.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 64352 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48564, ["x"] = 0.52, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48564, ["x"] = 0.52, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 28623 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 44, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[28488] = { ["id"] = 28488, ["name"] = "Beneath the Surface", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28488 }, ["description"] = "Among the other precious gemstones hidden deep out of our reach in the Crumbling Depths, there are enormous ruby crystal clusters . They are infused with terrible energy. It will not be easy to obtain such a thing, for they are well guarded. But you, you are stubborn and brave. I think this is something you can do. Within the Crumbling Depths, look to where the tunnels end abruptly in stone. The clusters are found in those passages when they are to be found at all. Should you find one, return to me.", ["objectivesText"] = "Recover an Enormous Ruby Crystal Cluster . Progress: These crystals are of great value, particularly to Gorsik. I shall have a heavy sway over him if I come into possession of one. I wish this to be so.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 64404, 64494 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 26709 } },
[28498] = { ["id"] = 28498, ["name"] = "The Secret of Nahom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "There is an old story about Nahom. It speaks of how a powerful prophet named Atulhet held off troves of enemies by channeling the power of the sun through this very temple. Most believe the tale to be just a legend, but that power... would certainly be useful to us now. The vile Neferset have ransacked Atulhet's tomb. They've taken any artifacts of power and shattered the tablets that encode his memories. Go to the Tombs of the Precursors to the east and retrieve any fragments that you find.", ["objectivesText"] = "Obtain 8 Atulhet's Record Fragments . Progress: Did you find them, <name>? Were they salvageable?", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 64642 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48761, ["x"] = 0.672, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48761, ["x"] = 0.672, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 28561 }, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 32, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[28779] = { ["id"] = 28779, ["name"] = "A Long Way from Home", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5035, ["storyline"] = { 28779 }, ["description"] = "I've a feeling I was able to escape my captors because, frankly, there is nowhere to go. Stranded on these platforms, they are bound to find me sooner or later. Unless... It is said that the heart of an elemental noble can grant whoever holds it the characteristics of that element. Which, in the case of air, would be most useful during a downward trip. Bring me Grand Vizier Ertan's heart so I can use its magic to land safely on the shoreline of Uldum.", ["objectivesText"] = "Obtain Grand Vizier Ertan's Heart . Progress: You'd best not suggest I ride with you on... whatever that thing is you flew in on.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 65660, 66898, 66899, 66900 }, ["starts"] = { { ["npcID"] = 49943 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5035 } }, ["questGiverID"] = 49943, ["questType"] = "dungeon", ["sourceQuests"] = { 28845 } },
[28815] = { ["id"] = 28815, ["name"] = "Twilight Documents", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5088, ["storyline"] = { 28815 }, ["series"] = { 28814 }, ["description"] = "We've tailed one of the Twilight's Hammer operatives here. He goes by the name of Millhouse Manastorm. We have reason to believe he's carrying important documents. This is as far as we can safely go, however, without neglecting our duty to defend the Temple of Earth's inner perimeter. Track down Manastorm and retrieve the documents from him.", ["objectivesText"] = "Obtain the Twilight Documents . Progress: These appear to be the right documents.", ["rewardGold"] = 137400, ["rewardXP"] = 8230, ["rewardItems"] = { 65734 }, ["starts"] = { { ["npcID"] = 50048 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5088 } }, ["questGiverID"] = 50048, ["questType"] = "dungeon" },
[28853] = { ["id"] = 28853, ["name"] = "Kill the Courier", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4950, ["storyline"] = { 28853 }, ["description"] = "Thank you, <class>, for braving the horrors of this dark and terrible place. The bowels of Grim Batol are the heart of Cho'gall's war machine. If we are to stop his machinations throughout the Highlands, we must learn all we can from these depths. Seek out Drahga Shadowburner within. He is Cho'gall's runner, the link between here and the Bastion of Twilight. We must learn the secrets he carries.", ["objectivesText"] = "Kill Drahga Shadowburner and grab his Missive to Cho'gall . Progress: What have you discovered, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 66927, 66936, 66937, 66938 }, ["starts"] = { { ["x"] = 0.5, ["y"] = 0.5, ["mapID"] = 293, ["npcID"] = 50385 } }, ["ends"] = { { ["x"] = 0.5, ["y"] = 0.5, ["mapID"] = 293, ["npcID"] = 50385 } }, ["coords"] = { ["mapID"] = 293, ["x"] = 0.5, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4950 } }, ["questGiverID"] = 50385, ["questTurnInID"] = 50385, ["questType"] = "dungeon" },
[29091] = { ["id"] = 29091, ["name"] = "Freedom Movement", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["mapID"] = 10, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17 } }, ["questType"] = "standard" },
[29246] = { ["id"] = 29246, ["name"] = "Relieving the Pain", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29246 }, ["description"] = "The Arch Druid has an immense tolerance for pain. I've treated burn victims that spend twenty-two hours a day screaming in pain, and their burns weren't even half as bad as what Hamuul has suffered. Nevertheless, I can sense that he is in greater discomfort than normal today. Bring me the hearts of the large fire elementals to the southeast. I can use them to prepare a soothing salve for our patient.", ["objectivesText"] = "Obtain 4 Flame-Wreathed Hearts from Seething Firelords. Progress: These hearts will give us exactly what Hamuul needs to rest.", ["rewardGold"] = 137400, ["rewardXP"] = 4385, ["rewardItems"] = { 69678 }, ["rewardCurrencies"] = { { ["id"] = 416, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 29198 }, ["db2QuestSortName"] = "Engine of Innovation" },
[29247] = { ["id"] = 29247, ["name"] = "Treating the Wounds", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29247 }, ["description"] = "We have an ample supply of medical supplies here at the Sanctuary, but we mustn't lose sight of the fact that we are at war. Hamuul isn't the only person who has need of bandages. The fiery behemoths that roam Sethria's Roost wear flame-resistant wrappings that will serve Hamuul as ably as any bandage. Bring me those wrappings, and I will prepare them for use on the Arch Druid.", ["objectivesText"] = "Obtain 4 Sulfur-Laced Wrappings from Fiery Behemoths in Sethria's Roost. Progress: There are some who say that the sulfur in those wrappings has curative properties. Personally, I am unconvinced, but I am willing to endure the smell on the off-chance that it does.", ["rewardGold"] = 137400, ["rewardXP"] = 4385, ["rewardItems"] = { 69677 }, ["rewardCurrencies"] = { { ["id"] = 416, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 29198 }, ["db2QuestSortName"] = "Engine of Innovation" },
[29248] = { ["id"] = 29248, ["name"] = "Releasing the Pressure", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29248 }, ["description"] = "Having been burned so badly, Arch Druid Hamuul is suffering from edema - swelling of the body's tissues. It takes a great deal of his attendants' effort to keep his swelling down enough for him to breathe. Normally, to reduce this swelling, we make cuts in his flesh, but he is weak, <name>. I cannot cut him today. I need your help. Flamewaker scales will aid with the swelling, but you need a lot of them.", ["objectivesText"] = "Obtain 100 Flamewaker Scales . Progress: Do you have the scales? I hesitate to cut the Arch Druid again, but we must relieve the swelling somehow.", ["rewardGold"] = 137400, ["rewardXP"] = 4385, ["rewardItems"] = { 69679 }, ["rewardCurrencies"] = { { ["id"] = 416, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 29198 }, ["db2QuestSortName"] = "Engine of Innovation" },
[29274] = { ["id"] = 29274, ["name"] = "Hounds of Shannox", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5733, ["storyline"] = { 29274 }, ["description"] = "On the Firelands' largest island, our troops have been having trouble against Shannox, the flamewaker hunter. Not only does he have impeccable aim, but he keeps trained hounds that give our troops no end of trouble. Tholo, in all his wisdom, thinks it would be a good idea to study the biology of these hounds. I, of course, agree with Tholo. You will find several hounds in the Molten Flow, beneath the Furnace. We will need their ashes to study.", ["objectivesText"] = "Obtain 6 small piles of Houndbone Ash . Progress: Any information we can get will be instrumental in helping our men defeat Shannox.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69816 }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.612, ["mapID"] = 338, ["npcID"] = 52478 } }, ["ends"] = { { ["x"] = 0.42, ["y"] = 0.612, ["mapID"] = 338, ["npcID"] = 52478 } }, ["coords"] = { ["mapID"] = 338, ["x"] = 0.42, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questGiverID"] = 52478, ["questTurnInID"] = 52478, ["questType"] = "standard", ["sourceQuests"] = { 29272 } },
[29288] = { ["id"] = 29288, ["name"] = "Starting Young", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5733, ["storyline"] = { 29288 }, ["description"] = "Our scouts are bringing back reports of fire hawk hatchlings all over the peak... their eggs must have hatched very recently. Better yet, it seems that they're extremely docile. I know it may sound a strange and perhaps unsavory request, but if you were able to bring some of those hatchlings back to me, I might be able to train them to aid us in our war efforts. Are you willing?", ["objectivesText"] = "Recover 5 Fire Hawk Hatchlings . Progress: I can't make up my mind on how to regard these creatures. They act like much like other avians, but they are very obviously native to this fiery place. I wonder why Ragnaros and his minions have not made attempts to rally them against us...", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 60854, 69845 }, ["starts"] = { { ["x"] = 0.346, ["y"] = 0.564, ["mapID"] = 338, ["npcID"] = 52491 } }, ["ends"] = { { ["x"] = 0.346, ["y"] = 0.564, ["mapID"] = 338, ["npcID"] = 52491 } }, ["coords"] = { ["mapID"] = 338, ["x"] = 0.346, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questGiverID"] = 52491, ["questTurnInID"] = 52491, ["questType"] = "standard", ["sourceQuests"] = { 29265 } },
[38901] = { ["id"] = 38901, ["name"] = "The Felsmiths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["series"] = { 38798 }, ["description"] = "Ye have a knack with this felslate, <lad/lass>. Best ship ye off to someone who knows the stuff better than I. The Illidari have a knack with all things demonic, really, and I've heard about a few miners who've set up shop out near the demons in Suramar. Pay 'em a visit. See what they have to teach ye.", ["objectivesText"] = "Report to Felsmith Nal'ryssa in Suramar.", ["rewardXP"] = 175, ["rewardItems"] = { 109076 }, ["starts"] = { { ["x"] = 0.462, ["y"] = 0.264, ["mapID"] = 627, ["npcID"] = 93189 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93189, ["questType"] = "standard", ["sourceQuests"] = { 38795, 38796, 38797 }, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 685 },
[38904] = { ["id"] = 38904, ["name"] = "Return to the Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611 }, ["series"] = { 39654, 41052, 42814, 42815 }, ["description"] = "Fear not, <name>. I'm angry, but I don't chase my own death. We will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry! Take my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.", ["objectivesText"] = "Take Saurfang's spare mount to the Broken Shore and fight alongside him to restore your honor.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["x"] = 0.75, ["y"] = 0.462, ["mapID"] = 627, ["npcID"] = 93773 } }, ["ends"] = { { ["x"] = 0.75, ["y"] = 0.462, ["mapID"] = 627, ["npcID"] = 93773 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.75, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93773, ["questTurnInID"] = 93773, ["questType"] = "standard", ["sourceQuests"] = { 41052 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[38907] = { ["id"] = 38907, ["name"] = "Keepers of the Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38911, 39316, 39491, 39496, 39733 }, ["description"] = "The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion. However, we have been betrayed from within and must now ask for your aid. A great relic, the Hammer of Khaz'goroth, was stolen from our people by the vile drogbar. We need your help in recovering it.", ["objectivesText"] = "Meet Mayla Highmountain at Thunder Totem in Highmountain . Progress: We must be swift. I was overlong in finding you.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 140192 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97666, ["x"] = 0.513333, ["y"] = 0.656 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97666, ["x"] = 0.513333, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.513333, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 97666, ["questType"] = "standard", ["sourceQuests"] = { 39733 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38909] = { ["id"] = 38909, ["name"] = "Get to High Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region. Please, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area. We will rally the survivors here and follow as quickly as we can.", ["objectivesText"] = "Bring Jale Rivermane to Thunder Totem. Progress: Have you had any luck with the Rivermane?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 246937 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 93805, ["questType"] = "standard", ["sourceQuests"] = { 39027 }, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38910] = { ["id"] = 38910, ["name"] = "Rocs vs Eagles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38913, 39318, 39321 }, ["description"] = "High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley. There is no way to break this curse once it has taken hold. We will take to the skies and do battle with the rocs, but we need your help on the ground. Head north through Darkfeather Valley and release any eagles that you find. Every eagle you save is one less roc we must kill later.", ["objectivesText"] = "Save 7 Captive Great Eagles .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39318 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38911] = { ["id"] = 38911, ["name"] = "The Rivermane Tribe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 39316, 39491, 39496, 39733 }, ["description"] = "What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz'goroth in the hands of the barbaric drogbar. Even now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. We need a hero. Please, go to Earthmother's Bounty and lend what aid you can.", ["objectivesText"] = "Meet Jale Rivermane at Earthmother's Bounty.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.548, ["y"] = 0.632, ["mapID"] = 652, ["npcID"] = 93826 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 93826, ["questType"] = "standard", ["sourceQuests"] = { 38907 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38912] = { ["id"] = 38912, ["name"] = "The Bloodtotem Tribe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe-- Oakin Ironbull --whom you rescued at Riverbend. Use that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz'goroth. Be on your guard, <name>.", ["objectivesText"] = "Meet Oakin Ironbull at Cliff's Edge.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 109076 }, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.63, ["mapID"] = 652, ["npcID"] = 93826 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 93826, ["questType"] = "standard", ["sourceQuests"] = { 38909 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38913] = { ["id"] = 38913, ["name"] = "The Skyhorn Tribe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38910, 39318, 39321 }, ["description"] = "The Skyhorn people are some of the greatest pathfinders and hunters this world has ever known. They are a proud people, but should be willing to listen to reason. If the roads feel unsafe, you may ask any flight master in Highmountain to fly you there. Please, $p, go to their leader Lasan and remind him that only together, we are Highmountain .", ["objectivesText"] = "Meet Lasan Skyhorn at Skyhorn.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.63, ["mapID"] = 652, ["npcID"] = 93826 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 93826, ["questType"] = "standard", ["sourceQuests"] = { 38909 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38914] = { ["id"] = 38914, ["name"] = "Secrets of Highmountain", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38914 }, ["description"] = "Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor. To this end I have sent word for one of your allies to join us. When you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.", ["objectivesText"] = "Speak with Spiritwalker Ebonhorn in Thunder totem.", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[38915] = { ["id"] = 38915, ["name"] = "Battle of Snowblind Mesa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground. What is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle. Meet us at Snowblind Mesa and let us take the fight to Dargrul together.", ["objectivesText"] = "Journey to Snowblind Mesa.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.54, ["y"] = 0.628, ["mapID"] = 652, ["npcID"] = 108434 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 108434, ["questType"] = "standard", ["sourceQuests"] = { 39387, 39456, 39580 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38916] = { ["id"] = 38916, ["name"] = "Secrets of Highmountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Mayla's father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz'goroth. I have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain. She needs only our help to realize it herself. Will you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.", ["objectivesText"] = "Meet Spiritwalker Ebonhorn at the southern bluff of Thunder Totem.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94571, ["x"] = 0.448, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 98825, ["questType"] = "standard", ["sourceQuests"] = { 39992 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[38922] = { ["id"] = 38922, ["name"] = "Littlefur", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["series"] = { 38246 }, ["description"] = "Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath. My nephew and I tried to leave against the Chieftain's wishes. The clan wrested him from me, and would have torn me apart if I did not flee. He is trapped in the village, and I fear the worst. Great <class>, please save him. I am too old and too weak to do it myself.", ["objectivesText"] = "Speak to Littlefur at Smolderhide Thicket.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93890, ["x"] = 0.484, ["y"] = 0.845 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93581, ["x"] = 0.469333, ["y"] = 0.845333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.845 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38142 }, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 2, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
