[38932] = { ["id"] = 38932, ["name"] = "Equipment Blueprint: Bilge Pump", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38932 }, ["description"] = "This appears to be a blueprint for some sort of naval equipment. We should take it back to our Shipyard and see if someone can decipher it.", ["objectivesText"] = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard. Progress: Those look like some equipment blueprints!", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 125787, 126950, 126951, 128256, 128264, 128265 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 }, { ["mapID"] = 525, ["npcID"] = 94801, ["x"] = 0.4, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["startItems"] = { 126950 } },
[38933] = { ["id"] = 38933, ["name"] = "Logistical Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 39756, 42811, 42812 }, ["description"] = "I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles. Lord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.", ["objectivesText"] = "Speak to Lord Grayson Shadowbreaker .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.737, ["y"] = 0.196, ["mapID"] = 24, ["npcID"] = 91866 } }, ["ends"] = { { ["x"] = 0.737, ["y"] = 0.196, ["mapID"] = 24, ["npcID"] = 91866 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.737, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 91866, ["questTurnInID"] = 91866, ["questType"] = "standard", ["sourceQuests"] = { 38566 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[38934] = { ["id"] = 38934, ["name"] = "Silas' Secret Stash", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 6, ["zoneID"] = 5861, ["storyline"] = { 38934 }, ["description"] = "A great Darkmoon prize do you now seek, but be ye warned, it is not for the meek. Your very first clue to send you on this caper, you will find printed on the back of this paper.", ["objectivesText"] = "Find Silas' Secret Stash .", ["rewardGold"] = 1024800, ["rewardXP"] = 300, ["rewardItems"] = { 109076, 122238, 124669, 124670, 124671, 124674, 126925, 126926, 126927, 126928, 126929, 126930, 126931, 127141, 127143, 127144, 127145, 127146, 127147, 127148 }, ["starts"] = { { ["x"] = 0.525, ["y"] = 0.887, ["mapID"] = 407, ["npcID"] = 55103 } }, ["ends"] = { { ["x"] = 0.525, ["y"] = 0.887, ["mapID"] = 407, ["npcID"] = 55103 } }, ["coords"] = { ["mapID"] = 407, ["x"] = 0.525, ["y"] = 0.887 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questGiverID"] = 55103, ["questTurnInID"] = 55103, ["questType"] = "standard", ["startItems"] = { 126930 } },
[38935] = { ["id"] = 38935, ["name"] = "His Name Was... Stormstout", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 38935 }, ["series"] = { 29907, 29908, 29909, 29911, 29912, 29940, 32018, 32019, 49539, 49557 }, ["description"] = "The land is ripe with rumors of an unusual pandaren monk whose power was matched only for his appetite for brew. He was traveling with his young niece who's mouth seems to get them into a lot of trouble. The locals say these two were headed to the Valley of the Four Winds . You should meet him! Just... watch out for that right hook.", ["objectivesText"] = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 56133, ["x"] = 0.6065, ["y"] = 0.46575 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.6065, ["y"] = 0.46575 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard", ["nextQuests"] = { 29907 } },
[38936] = { ["id"] = 38936, ["name"] = "The Road to Kun-Lai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6006, ["mapID"] = 379, ["storyline"] = { 38936 }, ["series"] = { 30457, 31254, 31255, 49541, 49559 }, ["description"] = "Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing. They need your help if they are to survive! To reach Kun-Lai Summit, travel to the Valley of the Four Winds and look for the Highroad Grummle that can be found at the base of the Veiled Stair along the northeastern border. They can guide you the rest of the way.", ["objectivesText"] = "Travel through the Veiled Stair to Binan Village.", ["rewardGold"] = 13740, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 59073, ["x"] = 0.722, ["y"] = 0.918 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.918 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[38938] = { ["id"] = 38938, ["name"] = "Unbearable", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38938 }, ["series"] = { 38885 }, ["description"] = "Not far away, a bear cub looks to be in some distress. Perhaps you should investigate? See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(38938)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(38938))\");", ["objectivesText"] = "Investigate the Shivering Ashmaw Cub in southern Val'sharah .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
