[38944] = { ["id"] = 38944, ["name"] = "Sew It Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below. Threads imbued with magic? Something demonically-tinged? Ugh, I hope it's not FURS again. You're an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!", ["objectivesText"] = "Obtain 10 Shal'dorei Silk . You can find Shal'dorei Silk on humanoids within the Broken Isles, obtain some from a fellow adventurer, or you may visit the Auction House and buy some. Progress: I wouldn't mind working with some cashmere...", ["rewardXP"] = 1415, ["rewardItems"] = { 124437 }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questTurnInID"] = 93542, ["questType"] = "standard", ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38945] = { ["id"] = 38945, ["name"] = "This Should Be Simple... Right?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38946 }, ["description"] = "I have plenty of silk patterns that we can put this cloth to work on. Help me to prepare the materials, <name>. We're going to put this cloth to good use and make you a new robe.", ["objectivesText"] = "Craft a Handcrafted Silkweave Robe on Tanithria 's Finishing Bench. You can find the pattern in your tailoring pattern list. You can find the materials for the pattern in her shop. Progress: We're back in business again. How exciting!", ["rewardXP"] = 1415, ["rewardItems"] = { 126992, 126993, 127286, 127287, 127289, 127291, 127293, 127294 }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questTurnInID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38944 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38946] = { ["id"] = 38946, ["name"] = "Consult the Locals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38945 }, ["description"] = "Whoever wove this fabric CAN'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material. Head on down to Azsuna and try to find a tailor. We need to sew if we're going to do any real tailoring.", ["objectivesText"] = "Find a tailor in Azsuna.", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38945 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[38947] = { ["id"] = 38947, ["name"] = "Runic Catgut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38948, 38949, 38950 }, ["description"] = "Let me guess... thread troubles? Mm-hm. I suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they'll accept. Shal'dorei silk has a bit of ley energy woven right into it. You need something that's learned to coexist with the ley energies of this land. I'm talking about owlcats, my good friend! They have what you need. You'll find them amongst the ruins of Llothien.", ["objectivesText"] = "Obtain 3 pieces of Runic Catgut . Progress: They are quite remarkable creatures, really. I used to keep one as a pet and mount... but that was a lifetime ago.", ["rewardXP"] = 1415, ["rewardItems"] = { 127037, 127039 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 38946 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[38948] = { ["id"] = 38948, ["name"] = "Hard Times", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38947, 38949, 38950 }, ["description"] = "When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me. Unfortunately, I've run into streak of bad luck, and I'm ashamed to say that I no longer have my patterns. The naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.", ["objectivesText"] = "Obtain a Stained Silken Robe and a set of Hatecoil Wristwraps . Progress: What've you got in your hands, there?", ["rewardXP"] = 1415, ["rewardItems"] = { 127038, 127039 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 38946 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[38949] = { ["id"] = 38949, ["name"] = "So You Think You Can Sew", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38947, 38948, 38950 }, ["description"] = "Very good, I think we're ready to begin. < Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.> Let's prepare our materials and make the robe and bracers that you so rightfully deserve!", ["objectivesText"] = "Craft a Rune-Threaded Silkweave Robe and a set of Rune-Threaded Silkweave Bracers at Lyndras ' Finishing Table. You can find the patterns in your tailoring pattern list. Progress: You're pretty lucky to have found me.", ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 126987, 126994, 127343, 127344, 127345 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38947, 38948 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[38950] = { ["id"] = 38950, ["name"] = "The Wayward Tailor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38947, 38948, 38949 }, ["description"] = "Might I ask a favor, <name>? As I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I've also heard good things about their tailoring shop. I have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me. < Lyndras looks at you with hopeful apprehension.>", ["objectivesText"] = "Speak to Lalla Brightweave in Dalaran, and ask her to summon Lyndras . Progress: Did you find a tailor yet?", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 93967, ["questType"] = "standard", ["sourceQuests"] = { 38949 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38951] = { ["id"] = 38951, ["name"] = "A Needle Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38952, 38953 }, ["description"] = "This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking. I do know where you can get better needles. The sprites of Val'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need. I hate to be such a prickler stickler, but these needles really will make a difference.", ["objectivesText"] = "Obtain 150 Spritethorns . Progress: Your friend thinks these needles will make a difference?", ["rewardGold"] = 28090, ["rewardXP"] = 1415, ["rewardItems"] = { 81404, 87399, 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052, 108439, 127042, 198609 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 93967, ["questType"] = "standard", ["sourceQuests"] = { 38950 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38952] = { ["id"] = 38952, ["name"] = "Meticulous Precision", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38951, 38953 }, ["description"] = "The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it's got a ninety-degree crook in it! I have no desire to sew around a corner. Tiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she'll straighten them out.", ["objectivesText"] = "Bring the Spritethorns to Tiffany Cartier in Dalaran. Progress: What's this, <name>?", ["rewardXP"] = 1415, ["rewardItems"] = { 127043 }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38951 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38953] = { ["id"] = 38953, ["name"] = "Advanced Needlework", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38951, 38952 }, ["description"] = "You've already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method. That's where our needles come in. Here, I'll show you how to improve the process of these patterns.", ["objectivesText"] = "Make an Embroidered Silkweave Robe on Tanithria's Finishing Bench. You will need to gather the materials in her shop. Progress: Keep your eye on your needlework. Don't lose focus now.", ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 126987, 126992, 126993, 126994, 127037, 127290, 127292, 127359, 127360, 127382 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38952 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38954] = { ["id"] = 38954, ["name"] = "Where's Lyndras?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38955 }, ["description"] = "That's strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face. Perhaps we should track him down.", ["objectivesText"] = "Find Lyndras .", ["rewardGold"] = 20220, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38953 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38955] = { ["id"] = 38955, ["name"] = "Sew Far, Sew Good", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38954 }, ["description"] = "Your tailoring skill really is impressive and, although I don't have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag. Follow my lead, <name>.", ["objectivesText"] = "Craft a Silkweave Bag. You will need to gather materials inside the Dalaran tailoring shop. Progress: There's nothing quite like a new bag.", ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 127035, 127037, 127290, 127361, 127681 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38954 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38956] = { ["id"] = 38956, ["name"] = "Where's Lyndras Again?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Oh dear. He had just promised you that he wouldn't wander off, and then he did it again! I'm starting to think that this Lyndras character might be a bit too impetuous for my tastes. Please, go find him, before he gets into any more trouble.", ["objectivesText"] = "Find Lyndras in Dalaran.", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38955 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38957] = { ["id"] = 38957, ["name"] = "Taking Inspiration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "I wish I had more patterns to share, but my notebook was lost along with my shop. We'll need to come up with some patterns on our own. I've been thinking about the leather breeches that the Stormheim vrykul wear. They're certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive. If I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.", ["objectivesText"] = "Obtain 6 Runed Breeches . Progress: I'm looking forward to this.", ["rewardXP"] = 1415, ["rewardItems"] = { 126991, 127044 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38956 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38958] = { ["id"] = 38958, ["name"] = "The Right Color", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "Your assistance, <name>, if you have a moment. I've been attempting to reproduce a pattern for footwear that I spotted a while back, but I'm having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn't look right. The color I'm looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?", ["objectivesText"] = "Obtain 10 Helsquid Ink . Progress: I'm quite close to completing these slippers.", ["rewardXP"] = 1415, ["rewardItems"] = { 116271, 126988, 127046 }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93525 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93525 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93525, ["questTurnInID"] = 93525, ["questType"] = "standard", ["sourceQuests"] = { 38956 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38959] = { ["id"] = 38959, ["name"] = "Left Behind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn't much more I can do save for teaching you what little I remember. If my memory still serves true, you're just missing a good pattern for some gloves and a hood. The first thing I need you to do is grab a few things from where you first met me. Here's what I need...", ["objectivesText"] = "Gather Lyndras' Pinking Shears , his Box of Measuring Tools and his Threading Needles from where you first met him in Azsuna. Progress: I had no clue I'd be magically teleported here, otherwise I would have gathered my things myself.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 74603, 74604, 74605, 88397, 131916, 135525, 135526, 135527, 179508, 179513, 179517, 179532, 179537, 179547, 181405, 181426, 181427, 181428, 181429, 181455, 181477, 181479, 181541, 181735, 181736, 182136, 182657, 182769, 183487, 183488, 184378, 184381, 184382, 184383, 184384, 184519, 204388 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38958 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38960] = { ["id"] = 38960, ["name"] = "Lining Them Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Since you're heading to Azsuna, you may as well gather some lining for our projects. The bears of Azsuna are known for how soft, yet durable their fur is. Hunt them in the woods around Llothien and bring their fur back with you.", ["objectivesText"] = "Gather 15 Bear Furs . Progress: Don't take them for easy prey. They're as vicious as they are cunning.", ["rewardXP"] = 1415, ["rewardItems"] = { 104320, 127047, 128827, 133576, 135538 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 38958 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38961] = { ["id"] = 38961, ["name"] = "Eye of Azshara: The Depraved Nightfallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "In order to craft the gloves, we'll require a special item. This will be no easy task to recover it, <name>. The naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world. The creature's heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful. I need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.", ["objectivesText"] = "Go to the Eye of Azshara, defeat the Wrath of Azshara and recover the Heart of the Storm . Progress: What were you able to find?", ["rewardXP"] = 1415, ["rewardItems"] = { 126989, 127048 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 93967, ["questType"] = "dungeon", ["sourceQuests"] = { 38963 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38962] = { ["id"] = 38962, ["name"] = "The Path to Suramar City", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth. Unfortunately from what I've heard, they've sided with the demons and anyone opposed to them is to be killed on sight. You must find a way to move safely within the confines of their city if we're to continue our research.", ["objectivesText"] = "Assist the nightfallen of Suramar until you discover a way to move safely amongst the elves of Suramar City.", ["rewardXP"] = 6140, ["rewardItems"] = { 2996, 2997, 4339, 41510, 53643, 114821, 127004, 127022, 127027, 136269, 140326, 140327, 140328, 140329, 147768 }, ["rewardCurrencies"] = { { ["id"] = 1155, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questTurnInID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38966 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38963] = { ["id"] = 38963, ["name"] = "The Final Lesson?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Now that we have everything we need, let's work on the hood. After we're finished, we'll move onto the gloves.", ["objectivesText"] = "Create a Handcrafted Silkweave Hood on Tanithria's Finishing Bench. You will need to gather the materials in her shop. Progress: Come now, <name>. Let us sew.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 126990, 127037, 127290, 127363, 127364, 127367, 127681, 135538 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38959, 38960 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38964] = { ["id"] = 38964, ["name"] = "Where's Lyndras Now?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Lyndras couldn't have gone very far. I mean, we're floating a thousand feet over the sea. I heard some commotion across the way this morning near the alchemy shop. I pray that wasn't Lyndras. Could you please go over there and make sure?", ["objectivesText"] = "Go the alchemy shop across the street.", ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questTurnInID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38961 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38965] = { ["id"] = 38965, ["name"] = "Assault on Violet Hold: Into the Hold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions. Perhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody. Go into Violet Hold and find out what happened to Lyndras .", ["objectivesText"] = "Go into Violet Hold and find out what happened to Lyndras . Progress: Did you discover what happened to Lyndras ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135556, 141184 }, ["starts"] = { { ["x"] = 0.652, ["y"] = 0.674, ["mapID"] = 627, ["npcID"] = 96444 } }, ["ends"] = { { ["x"] = 0.652, ["y"] = 0.674, ["mapID"] = 627, ["npcID"] = 96444 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.652, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 96444, ["questTurnInID"] = 96444, ["questType"] = "dungeon", ["sourceQuests"] = { 39667 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38966] = { ["id"] = 38966, ["name"] = "Secret Silkweaving Methods", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Okay, done mourning! Let's look through his stuff. < Tanithria takes a moment to leaf through Lyndras' journal. Her eyes open wide.> Our friend has been keeping secrets from us. Look at this! Every single one of the recipes he's taught us can be improved. Let's start simple, with some bracers. I can supply most of the materials, but you'll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.", ["objectivesText"] = "Craft some Masterwork Silkweave Bracers . You will need to gather materials from the Dalaran tailoring shop and blacksmithing shop. Progress: These patterns are fascinating. I never knew you could get this kind of result out of simple silks.", ["rewardXP"] = 6140, ["rewardItems"] = { 124437, 127037, 127368, 127370, 127372, 127373, 127382, 127680 }, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questTurnInID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38965 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[38967] = { ["id"] = 38967, ["name"] = "The Nightborne Connection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Now that you're able to disguise yourself, you should go to Suramar City and try to find this guild of tailors. Good luck, <name>, and try not to get caught.", ["objectivesText"] = "Speak with Leyweaver Tytallo in Suramar.", ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38962 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[38968] = { ["id"] = 38968, ["name"] = "Proof of Loyalty", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38970, 39602, 39605, 39667 }, ["description"] = "<Tytallo listens as you recount what happened with Lyndras.> I see. You sound almost... sympathetic to the wretch. The nightfallen are liars and thieves. ALL of them. Lyndras included. I will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity? If you want to get on my good side, do not return until you are covered in the blood of the withered .", ["objectivesText"] = "Slay 25 withered within Suramar. Progress: If you wish to earn my tutelage, you must first prove that you are on our side.", ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 38967 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[38969] = { ["id"] = 38969, ["name"] = "Master of Silkweave", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training. We're going to need to see how talented you are. Craft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.", ["objectivesText"] = "Purchase a Shal'dorei Mannequin from Leyweaver Mithrogane, then craft an entire set of silkweave armor and place them on the mannequin. Progress: If you wish to learn what we're about to teach you, you need a solid foundation.", ["rewardXP"] = 6140, ["rewardItems"] = { 124437, 127037, 127265, 127266, 127681 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93971, ["x"] = 0.402, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93971, ["x"] = 0.402, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 38962 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[38970] = { ["id"] = 38970, ["name"] = "The Queen's Grace Loom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 39602, 39605, 39667 }, ["description"] = "Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made. You are prepared, <name>, to learn about working with Imbued Silkweave. Use the teleportation crystal behind me, and speak with Azayna, the leader of our order.", ["objectivesText"] = "Use the Teleportation Crystal in the Leyweavers' Hall, then speak with Leyweaver Azayna. Progress: Return once you've spoken with Azayna.", ["rewardXP"] = 6140, ["rewardItems"] = { 124437, 127022, 127023, 127025, 127027, 127277, 127278, 127279, 127280 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 38969 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[38971] = { ["id"] = 38971, ["name"] = "Exotic Textiles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "I'm risking my life and career to be here, tailor. I've been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance. I simply must see this cloth for myself. I don't wish to disrupt Azayna's pact with the demons, but you - you can attack the demons without drawing attention to our guild. I'm particularly interested in a particular demon's set of robes. Bring me a scrap, and I'll teach you what I know.", ["objectivesText"] = "Obtain the Fel Inscribed Shroud . Progress: Probably better that you fight the thing, anyhow. I'm useless with a weapon.", ["rewardXP"] = 6140, ["rewardItems"] = { 127281 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93978, ["x"] = 0.266, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93978, ["x"] = 0.266, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 38970 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[38974] = { ["id"] = 38974, ["name"] = "Halls of Valor: The Right Question", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 634, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "One might ask what a leyweaver is doing standing over a dead vrykul's body. But such questions only stir up trouble. Instead let us ask what can be learned from those who have passed on. A question like that promotes progress. I assume you're here to learn from me, the pattern for Imbued Silkweave pants, yes? If that's true, then I'll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides. Bring me his loincloth and I will teach you my pattern.", ["objectivesText"] = "Defeat Hymdall in the Halls of Valor and recover his loincloth. Progress: Asking the right questions will get you far.", ["rewardXP"] = 6140, ["rewardItems"] = { 135575 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93977, ["x"] = 0.655, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93977, ["x"] = 0.655, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7672 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 38971 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 31, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[38975] = { ["id"] = 38975, ["name"] = "Inspire Me!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe. I'll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you've learned along your tailoring journey.", ["objectivesText"] = "Craft a Brown Linen Robe, a White Woolen Dress, a Simple Black Dress, a Frostwoven Robe, and a Spiritmend Robe while standing near Leyweaver Mithrogane . If you do not know a pattern, you can learn it from tailoring trainers in major cities. Progress: I never turn down the opportunity to learn a new robe pattern.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 2320, 2321, 2324, 2325, 2589, 2592, 2996, 2997, 4338, 4339, 6238, 6787, 8343, 10053, 33470, 38426, 41510, 41515, 53010, 53643, 54486 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93976, ["x"] = 0.402, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93976, ["x"] = 0.402, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 38970 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 32, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
