[38989] = { ["id"] = 38989, ["name"] = "Your Orders, General?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 525, ["storyline"] = { 38989 }, ["description"] = "General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands. For the Horde!", ["objectivesText"] = "Go to the Tanaan Planning Map in Tanaan Jungle .", ["ends"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[38990] = { ["id"] = 38990, ["name"] = "The Call of Icecrown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 38990 }, ["description"] = "<A powerful presence again touches your thoughts.> I have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, <name>, will be the hand of our vengeance! Use the Death Gate to return to Acherus and I shall reveal your role in this.", ["objectivesText"] = "Use your Death Gate ability to travel to Icecrown and obtain the Blades of the Fallen Prince . Progress: It is time to begin, <name>.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 118006, 124124, 127009, 127991, 128292, 128293, 128318, 128402, 128403, 128848, 132510, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["ends"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.728, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 101441, ["questTurnInID"] = 101441, ["questType"] = "standard", ["sourceQuests"] = { 40715, 43962, 44401 }, ["questLines"] = { { ["id"] = 168, ["name"] = "The Blades of the Fallen Prince", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 168, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[38992] = { ["id"] = 38992, ["name"] = "Mograine's Oath", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38992 }, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39000] = { ["id"] = 39000, ["name"] = "We Don't Need No Library Card", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39000 }, ["series"] = { 39003, 39024 }, ["description"] = "If history is any indication, Gul'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves. As you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul'dan's lieutenants. They're dangerous, so don't read any of them. Not even the pictures. <Khadgar shudders.> ESPECIALLY the pictures.", ["objectivesText"] = "Collect 33 Tomes of Chaos from bosses in Hellfire Citadel. Progress: What about those books, <name>?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 71141, 127115 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "raid", ["sourceQuests"] = { 37841, 39024 } },
[39003] = { ["id"] = 39003, ["name"] = "Cooking the Books", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39003 }, ["series"] = { 39000, 39024 }, ["description"] = "<name>, we've got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can't just burn them. Cordana will know what to do. Take these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.", ["objectivesText"] = "Deliver Gul'dan's Library of Chaos to Cordana at Zangarra and ensure they are destroyed. Progress: <Khadgar smiles.> So, how is Cordana doing? Is all well at my tower?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 119348 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["sourceQuests"] = { 39000 } },
[39004] = { ["id"] = 39004, ["name"] = "Darkness Incarnate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39004 }, ["description"] = "We have one final task before us, <name>. We must defeat Gul'dan and unravel his plans for this world. I have no reward to offer you - I have given you everything I can. Come. When you and your allies are ready, we march on Hellfire Citadel... and end this.", ["objectivesText"] = "Hunt down and engage Gul'dan within the Hellfire Citadel. Progress: We must thwart Gul'dan!", ["rewardGold"] = 2547000, ["rewardItems"] = { 127785 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "raid", ["sourceQuests"] = { 37839, 37840 } },
[39011] = { ["id"] = 39011, ["name"] = "Black Rook Invasion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39011 }, ["description"] = "Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply. We're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?", ["objectivesText"] = "Kill 7 Black Rook Assassins in Bradensbrook.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[39015] = { ["id"] = 39015, ["name"] = "Grumpy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39015 }, ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128354, 133577 }, ["starts"] = { { ["npcID"] = 92738, ["x"] = 0.386, ["y"] = 0.656, ["mapID"] = 641 } }, ["ends"] = { { ["npcID"] = 92738, ["x"] = 0.386, ["y"] = 0.656, ["mapID"] = 641 } }, ["coords"] = { ["x"] = 0.386, ["y"] = 0.656, ["source"] = "quest_giver", ["mapID"] = 641 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[39017] = { ["id"] = 39017, ["name"] = "Rise to the Occasion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 39017 }, ["description"] = "The Lich King made a wise choice in giving you that weapon, . You've proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.", ["objectivesText"] = "Speak with Highlord Darion Mograine within Acherus.", ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[39018] = { ["id"] = 39018, ["name"] = "Call of the Archmage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 39018 }, ["description"] = "Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.", ["objectivesText"] = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", ["rewardGold"] = 84900, ["rewardXP"] = 2735, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 83823, ["x"] = 0.852, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
