[39020] = { ["id"] = 39020, ["name"] = "A Burning Path Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = true, ["event"] = "Outland Timewalking Dungeon Event", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39020 }, ["description"] = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Follow the blazing star, and walk the paths it reveals.", ["rewardItems"] = { 22921, 23572, 32092, 33844, 33857, 35348, 86574, 122338, 122339, 122340, 122341, 127853, 129747, 129922, 129923, 129926, 129929, 129938, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129965, 133511, 133542, 133543, 164258, 226193, 226194, 247820 }, ["rewardCurrencies"] = { { ["id"] = 1129, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
[39021] = { ["id"] = 39021, ["name"] = "A Frozen Path Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = true, ["event"] = "Northrend Timewalking Dungeon Event", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39021 }, ["description"] = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Follow the chill star, and walk the paths it reveals.", ["rewardItems"] = { 43102, 44113, 44151, 46007, 122338, 122339, 122340, 122341, 127853, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129946, 129952, 129954, 129955, 129965, 133511, 133542, 133543, 226193, 226194, 247820, 247821 }, ["rewardCurrencies"] = { { ["id"] = 1129, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
