[39025] = { ["id"] = 39025, ["name"] = "Grasp of the Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer. He keeps thinking of the hammer as a weapon instead of a tool of creation. Even so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic. You might have power enough to break these fists. Can you help?", ["objectivesText"] = "Rescue Jale Rivermane , Warbrave Oro , and Oakin Ironbull . Progress: How are the captives? Did you find them alive?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 42104 }, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39026] = { ["id"] = 39026, ["name"] = "The Drogbar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "It wasn't enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left. Please champion, prove to my people that you are the hero I foresaw. Slay enough of these Stoneraiders that it breaks their resolve.", ["objectivesText"] = "Slay 8 Drogbar in Riverbend. Progress: The drogbar were supposed to be our allies against the Burning Legion.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 87399, 130904, 131736 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 42104 }, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39027] = { ["id"] = 39027, ["name"] = "Dargrul and the Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "We are about to follow a drogbar into a cave, something we warn our children never to do. Even so, several of our warbraves have already followed Dargrul inside. Come, join us in battle and let us reclaim the Hammer of Khaz'goroth.", ["objectivesText"] = "Confront Dargrul the Underking. Progress: This is a hard day.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121722, 130287, 130288, 130289, 130290 }, ["rewardChoices"] = { 121722, 130287, 130288, 130289, 130290 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4155, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39043 }, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
