[39029] = { ["id"] = 39029, ["name"] = "Defend The Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39029 }, ["objectivesText"] = "Defend The Temple", ["rewardGold"] = 404400, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 200 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defend The Temple", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39032] = { ["id"] = 39032, ["name"] = "A Summons from Saylanna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39032 }, ["description"] = "Sprites have always been mischievous creatures, but lately their mischief has turned to violence. One of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds. The Lunarwing Shallows lie to the south. You will find Saylanna there.", ["objectivesText"] = "Seek out Saylanna Riverbreeze in the Lunarwing Shallows.", ["rewardGold"] = 119340, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[39033] = { ["id"] = 39033, ["name"] = "The Time to Strike", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39033 }, ["description"] = "This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.", ["objectivesText"] = "Complete 5 Objectives in Apexis-yielding areas. Progress: Ah, the unmistakable hum of crystals when the Apexis star shines....", ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 1500 }, { ["id"] = 823, ["amount"] = 5000 }, { ["id"] = 824, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
[39034] = { ["id"] = 39034, ["name"] = "Emissary of War", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39034 }, ["description"] = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture deep into caverns and strongholds to prove your worth.", ["objectivesText"] = "Complete 4 dungeons on Mythic difficulty. Progress: Be bold, <name>, and you may win many friends on this day.", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 127854, 226194, 234731, 247820, 250117 }, ["rewardChoices"] = { 127854 }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
[39040] = { ["id"] = 39040, ["name"] = "A Call to Battle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["event"] = "Battleground Bonus Event", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39040 }, ["description"] = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", ["objectivesText"] = "Win 4 Battleground matches.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 137642 }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
