[39042] = { ["id"] = 39042, ["name"] = "The Very Best", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["event"] = "Pet Battle Bonus Event", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39042 }, ["description"] = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets.", ["rewardItems"] = { 92738, 98112, 98114, 122457 }, ["rewardChoices"] = { 122457 }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
[39043] = { ["id"] = 39043, ["name"] = "Bitestone Enclave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids. I need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there. Buy us the time we need to gather our strength.", ["objectivesText"] = "Slay drogbar in the Bitestone Enclave. Progress: Highmountain stands!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138783 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4155, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39025, 39026 }, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39047] = { ["id"] = 39047, ["name"] = "Call of the Illidari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<name>, Altruis requests that you meet him at Krasus' Landing at once. <Kor'vas leans in close, her voice an urgent whisper.> You must hurry. The Legion has eyes everywhere.", ["objectivesText"] = "Speak to Altruis the Sufferer at Krasus' Landing.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["npcID"] = 99343 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99343, ["questType"] = "standard", ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39049] = { ["id"] = 39049, ["name"] = "Eye On the Prize", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38759, 39050, 40379 }, ["description"] = "This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts. I have a different idea... There is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion. Better yet, you will gain its power by ripping it from its smoking corpse.", ["objectivesText"] = "Kill Inquisitor Baleful and take his power. Progress: <name>. I would salute, but I am in the middle of a ritual.", ["rewardGold"] = 365520, ["rewardXP"] = 1430, ["rewardItems"] = { 71083, 128944, 128945, 128946, 128947, 128948, 128949, 128958, 129192, 129195, 132243, 133580, 190456, 201989 }, ["starts"] = { { ["x"] = 0.339, ["y"] = 0.7, ["mapID"] = 672, ["npcID"] = 94410 } }, ["ends"] = { { ["x"] = 0.339, ["y"] = 0.7, ["mapID"] = 672, ["npcID"] = 94410 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.339, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 94410, ["questTurnInID"] = 94410, ["questType"] = "standard", ["sourceQuests"] = { 40378 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[39050] = { ["id"] = 39050, ["name"] = "Meeting With the Queen", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38759, 39049, 40379 }, ["description"] = "We can use some of that essence to complete my ritual. You'll be able to spy upon the Legion leaders and see what they're planning. Use the nether crucible and complete the ritual.", ["objectivesText"] = "Complete the ritual to spy upon the Legion leaders. Progress: If we don't know what they're planning, we're at a disadvantage fighting them.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.606, ["mapID"] = 672, ["npcID"] = 93759 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.606, ["mapID"] = 672, ["npcID"] = 93759 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.388, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 93759, ["questTurnInID"] = 93759, ["questType"] = "standard", ["sourceQuests"] = { 38759, 39049, 40379 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[39051] = { ["id"] = 39051, ["name"] = "By Any Means", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7777, ["mapID"] = 723, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "We need to figure out what rock Varedis is hiding under - the only way we're going to do that is by getting inside this prison. Do what you must.", ["objectivesText"] = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis. Progress: A truly impressive display.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 53265, 53267, 53292, 62178, 62179, 62180, 127830, 128832, 131398 }, ["starts"] = { { ["x"] = 0.653, ["y"] = 0.669, ["mapID"] = 627, ["npcID"] = 94902 } }, ["ends"] = { { ["x"] = 0.653, ["y"] = 0.669, ["mapID"] = 627, ["npcID"] = 94902 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.653, ["y"] = 0.669 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7777 } }, ["questGiverID"] = 94902, ["questTurnInID"] = 94902, ["questType"] = "standard", ["sourceQuests"] = { 40819 }, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1494, ["db2PoiUiMapID"] = 723 },
[39054] = { ["id"] = 39054, ["name"] = "Shipbuilding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 525, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38435, 38436, 38444, 38445, 39055, 39082, 39276 }, ["description"] = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, <class>, and then destroy the evidence. Let me know when you are done.", ["objectivesText"] = "Learn the blueprints and destroy the evidence. Progress: You memorize those blueprints yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39082 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39055] = { ["id"] = 39055, ["name"] = "Ship Shape", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 38435, 38436, 38444, 38445, 39054, 39082, 39276 }, ["description"] = "Now that we have the blueprints, let's get started on our first ship, a transport! Speak to me when you are ready to begin construction.", ["objectivesText"] = "Speak with Yanas to begin construction on a transport ship. Once complete, add it to your collection of ships. Progress: Get that ship started yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 95002, ["x"] = 0.298, ["y"] = 0.106 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 95002, ["x"] = 0.298, ["y"] = 0.106 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.106 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39276 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39056] = { ["id"] = 39056, ["name"] = "Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39404, 39655, 39674, 39675, 39676 }, ["description"] = "We have come a long way in a short time on this shipyard, <name>. Now it's time to run our first naval mission and control the seas of Draenor! I will need to setup shop from a high vantage point to plan out these seafaring missions. Meet me near the shipyard entrance and we can get started.", ["objectivesText"] = "Find Merreck Vonder in your Shipyard and complete a Naval Mission. Progress: Finish a naval mission yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260, 128353, 128373 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39422 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39057] = { ["id"] = 39057, ["name"] = "Command of the Seas", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39057 }, ["series"] = { 39697 }, ["description"] = "Gul'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we're going to need more than just a couple of transport ships. We must build an arsenal. We need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!", ["objectivesText"] = "Upgrade to a Level 2 shipyard.", ["rewardGold"] = 238680, ["rewardXP"] = 1365, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["sourceQuests"] = { 37841, 39024 } },
[39058] = { ["id"] = 39058, ["name"] = "Critters of Draenor", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39058 }, ["description"] = "I love collecting pets, and I've picked up a few unusual pets here in Draenor. What would you say to a battle? If you can defeat my humble team, I think we'll both learn a few new tricks.", ["objectivesText"] = "Defeat Erris the Collector in a pet battle.", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 116429, 122535 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39059] = { ["id"] = 39059, ["name"] = "To Catch a Banshee", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["description"] = "The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane. It seems he may have a lead on Sylvanas' location. He's set up a camp near the base of the mountain. We've run into some troubles, though. It looks like the Horde may have homed in on our position. We could use your help. You can take my gryphon. Just speak to me when you're ready to leave.", ["objectivesText"] = "Meet with Genn Greymane in Greywatch.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94346, ["x"] = 0.6, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39855 }, ["nextQuests"] = { 39060, 39061 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39060] = { ["id"] = 39060, ["name"] = "Combustible Contagion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39061, 39062, 39063, 39092, 39122, 39472 }, ["description"] = "It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention. Yesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch. Seek out their caches and destroy them, before the blight overtakes us!", ["objectivesText"] = "Burn the Forsaken Blight Caches near Greywatch. Progress: Have the caches been taken care of?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127295 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39059 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39061] = { ["id"] = 39061, ["name"] = "Whispers from the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39062, 39063, 39092, 39122, 39472 }, ["description"] = "We still have little knowledge of the Horde's activities in the region, but I'm hoping you can help change that. Lately the woods have been crawling with Sylvanas' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here. While you're on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas' objective in the area.", ["objectivesText"] = "Collect the Forsaken Scouting Orders from Dread-Rider Stalkers and Dread-Rider Plaguebringers near Greywatch. Progress: What have you found?", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 127285 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39059 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39062] = { ["id"] = 39062, ["name"] = "To Skold-Ashil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39063, 39092, 39122, 39472 }, ["description"] = "We have her now! According to these reports, Sylvanas' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down. I had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after. Meanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!", ["objectivesText"] = "Meet with Commander Lorna Crowley in Crowley's Overlook.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 14370 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93779, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39060, 39061, 39472 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39063] = { ["id"] = 39063, ["name"] = "Shielded Secrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39092, 39122, 39472 }, ["description"] = "It's obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don't know what they're after. We think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. Go into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.", ["objectivesText"] = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93779, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95921, ["x"] = 0.605, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39062 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39067] = { ["id"] = 39067, ["name"] = "Upgrading The Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39068 }, ["description"] = "You have been doing a great job out there commander. However, we are going to need more experience and resources to upgrade this shipyard. Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", ["objectivesText"] = "Collect 1000 garrison resources , 1000 gold and complete 15 naval missions. Progress: Finding success on these new naval missions?", ["rewardXP"] = 685, ["rewardItems"] = { 127270 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39665 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39068] = { ["id"] = 39068, ["name"] = "Naval Domination", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39067 }, ["description"] = "Our naval domination continues! However, we are going to need even more experience and resources to take this shipyard to the next level. Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!", ["objectivesText"] = "Collect 2500 garrison resources , 2500 gold and complete 25 naval treasure missions. Progress: Gather those resources yet? I am ready to get this upgrade started!", ["rewardXP"] = 685, ["rewardItems"] = { 127267, 128391 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39067 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
