[39092] = { ["id"] = 39092, ["name"] = "Becoming the Ascendant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39063, 39122, 39472 }, ["description"] = "Our course is now clear. We must enter the vault and prevent Sylvanas from obtaining the power to create more Val'kyr. The entrance is barred, which is likely what has kept her out so far, but you may have already uncovered the key to this barrier. You must become the next ascendant. Complete the rites as depicted on the shields and take down the barrier to the vault. I will send word to Greymane of our findings - he will wish to confront Sylvanas himself.", ["objectivesText"] = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 95921, ["x"] = 0.605, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95804, ["x"] = 0.622, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39063 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
