[39117] = { ["id"] = 39117, ["name"] = "Shriek No More", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "Papa loved this village. He'd never hear of leaving, even in these dread times. Before he died, he told me what attacked him: a monstrous falcon we call Rotbeak. You're fighting these undead, aren't you? Will you avenge my father? If so, you can find the beast northwest of here, patrolling our western route to the sea.", ["objectivesText"] = "Find Rotbeak along the Bradensbrook, and collect the beast's head. Progress: Papa always said the only way he'd leave here would be feet-first. I wish he'd been wrong.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127411, 129168, 130009, 133812, 245615 }, ["rewardChoices"] = { 129168, 130009 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94117, ["x"] = 0.37, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 94117, ["x"] = 0.37, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38643 }, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
