[39122] = { ["id"] = 39122, ["name"] = "Ending the New Beginning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39472 }, ["description"] = "The Banshee Queen is here! I'd recognize those tainted arrows anywhere. This is the moment we have been fighting for. Sylvanas will answer for her crimes against Varian Wrynn and the Alliance! To arms!", ["objectivesText"] = "Confront Sylvanas in the Vault of Eyir.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393 }, ["rewardChoices"] = { 129258, 129259, 129260, 129346, 129347, 129348 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 95804, ["x"] = 0.622, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95932, ["x"] = 0.714, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39092 }, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39123] = { ["id"] = 39123, ["name"] = "Lion Stalkin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "The hills are crawlin' with lions that stalk their prey from afar. These big cats will pounce at anything that catches their eye, including |5<race>. While most would fall to such a formidable predator, anyone in my huntin' party would be able to best those beasts. Prove you've got what it takes by taking down a few of those stalkers.", ["objectivesText"] = "Hunt Pinerock Stalkers and Prowlers in Pinerock Basin.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40170 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[39124] = { ["id"] = 39124, ["name"] = "Moose Shootin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "Highmountain is home to wildlife that can't be hunted anywhere else in the world. Tell me, <name>, have you ever laid eyes on a moose before? The roaming Elderhorn may look like gentle giants, but only a fool would underestimate their strength. They should prove to be a good challenge, even for someone as experienced as you.", ["objectivesText"] = "Hunt Pinerock Elderhorn in Pinerock Basin. Progress: Ya can't be huntin' Elderhorn if you're lingerin' around camp.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40170 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39125] = { ["id"] = 39125, ["name"] = "Demon Destroyer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39125 }, ["description"] = "The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel. I have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way. The gods will surely smile upon you if you thwart the advances of Legion.", ["objectivesText"] = "Slay Doomcaller , Sneermaw , and Grinchain", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 128305 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[39127] = { ["id"] = 39127, ["name"] = "Beyond the Wall", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 39127 }, ["series"] = { 30814, 31695, 49542, 49560 }, ["description"] = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes . It sounds like they are going after the root of the yaungol invasion. The pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", ["objectivesText"] = "Speak with Taran Zhu at the Longying Outpost in Townlong Steppes .", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["ends"] = { { ["mapID"] = 388, ["npcID"] = 60688, ["x"] = 0.712, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 388, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 388 }, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[39129] = { ["id"] = 39129, ["name"] = "Ill Tempered", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39129 }, ["description"] = "<Prying the lid off the scroll case reveals a plan by the Iron Horde to use large fish in the oceans around Draenor to interfere with Alliance and Horde naval power. Incredibly, the plan seems to have already worked on smaller sharks, but only up to a point.>", ["objectivesText"] = "Take the Shark Brainwashing Plans to your garrison shipwright. Provided item:", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 127663, 127682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard", ["startItems"] = { 127682 } },
[39131] = { ["id"] = 39131, ["name"] = "Possessions of Power", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39131 }, ["description"] = "Echoes of a thousand worlds swirl in the palm of your hand. Its true value lies in the eye of the beholder.", ["objectivesText"] = "Seek those who may offer insight into the origins of the shard.", ["rewardGold"] = 202200, ["rewardXP"] = 740, ["rewardItems"] = { 127684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39133] = { ["id"] = 39133, ["name"] = "No Time to Talk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39133, 39134 }, ["description"] = "Dargrul has sent his pets to do battle with us. We need to crush these elementals before their rage swarms into Thunder Totem.", ["objectivesText"] = "Destroy 8 Enraged Ambershard . Progress: We will all be honorary masons if this keeps up much longer.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38909 }, ["questLines"] = { { ["id"] = 5916, ["name"] = "Crystal Calamity", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39134] = { ["id"] = 39134, ["name"] = "Wrathshard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39133, 39134 }, ["description"] = "The Underking has used the Hammer of Khaz'goroth to render the mountainside into a weapon against us. The hammer is a tool for creation, not a weapon for his amusement! Even now, his crystal servant, Wrathshard , is driving these elementals out of the mountain down upon my people. We must hold the bridge against this onslaught. Enter the cave, find Wrathshard , and send him back to his master in pieces.", ["objectivesText"] = "Slay Wrathshard . Progress: Dargrul always was a vile creature. I never realized to what extent until he got his hands on that hammer.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121677, 121678, 121679, 121680, 130299, 130300, 130301, 130302 }, ["rewardChoices"] = { 121677, 121678, 121679, 121680, 130299, 130300, 130301, 130302 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38909 }, ["questLines"] = { { ["id"] = 5916, ["name"] = "Crystal Calamity", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39138] = { ["id"] = 39138, ["name"] = "March Forth and Conquer", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39138 }, ["description"] = "You should make sure that we do not lose momentum, Highlord. There is still much to be done in Azsuna. We have a map of the island set up near the front of the sanctum. Meet me there and you can delegate your forces to handle important tasks in the area.", ["objectivesText"] = "Use the Command Map to send your followers on three missions to Azsuna.", ["rewardGold"] = 15400, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39147] = { ["id"] = 39147, ["name"] = "6.2 Tanaan - PTR - Unlock Tanaan Debug", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39147 }, ["rewardGold"] = 616000, ["rewardXP"] = 50, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39149] = { ["id"] = 39149, ["name"] = "A Village in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "Another outsider? Some bloke named Jarod just went off to our village down the road claiming he might be able to help us with our problem. If you're here to help as well, then you best speak to the Mayor. Just know this is a bad time, and he's got an itchy trigger finger.", ["objectivesText"] = "Speak to Mayor Heathrow at Bradensbrook.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94594, ["x"] = 0.512, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92619, ["x"] = 0.424, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39151] = { ["id"] = 39151, ["name"] = "Forging the Artifact", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39151 }, ["description"] = "We've certainly got our work cut out for us, but not to worry. There's nae weapon in existence that ye can't improve, legendary ones included! This anvil's only powerful enough to imbue your artifact once before we'll need something better, but that'll have to do fer now.", ["objectivesText"] = "Use Valgar's anvil to imbue your artifact with a new power.", ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39153] = { ["id"] = 39153, ["name"] = "Dreadwake's Dilemma", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39154, 39155, 39385 }, ["description"] = "The situation has taken a dire turn, <name>. We were unprepared for Greymane's sudden assault, with only a token force left behind at Dreadwake's Landing, and we are paying the toll. The beach is now swarming with worgen infiltrators, and if the cannons breach our defenses, they will likely swarm in on us. We're spread too thin here to take the fight to them, but you could change that. Wipe them out.", ["objectivesText"] = "Kill 10 Greywatch Saboteurs or Infiltrators in Greymane's Offensive.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38872 }, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39154] = { ["id"] = 39154, ["name"] = "To Skold-Ashil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39153, 39155, 39385 }, ["description"] = "Thanks to your initiative, <class>, the situation at Dreadwake's Landing is under control. We have no time to rest on our laurels, however - Sylvanas's mission must still be carried out. The dark rangers are heading up operations in Skold-Ashil from the tower overlooking the river junction. Seek them out there, and see if you can aid in completing this task.", ["objectivesText"] = "Meet with the dark rangers in Ranger's Foothold, outside of Skold-Ashil.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 14370 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94227, ["x"] = 0.568, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38873, 39153, 39385 }, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39155] = { ["id"] = 39155, ["name"] = "Becoming the Ascendant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39153, 39154, 39385 }, ["description"] = "It would seem that the engravings depict a rite of ascension, which allows the shieldmaidens to enter the vault. I believe we can use this to our advantage. You must become the next ascendant. Go to the temple and perform the rites. Should you need to wade through the corpses of the shieldmaidens to do so, then so be it. Find me when you have completed this task, and we will take the vault for the Horde!", ["objectivesText"] = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 95611, ["x"] = 0.608, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94228, ["x"] = 0.630667, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38878 }, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39175] = { ["id"] = 39175, ["name"] = "Gems of the Apexis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 39175 }, ["series"] = { 39176, 39177, 39195 }, ["description"] = "Listen, boss. I know you're a jewelcrafter. It's OK, I totally understand - I like money, too! I heard some of them bird fellas talking about some new gem-cuttin' device they got up in Tanaan. I'd be interested in checkin' it out myself, but I've got this whole shipyard mess to deal with right now.", ["objectivesText"] = "Find Sun-Sage Chakkis in Tanaan Jungle.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78466, ["x"] = 0.488, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 525, 534 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[39176] = { ["id"] = 39176, ["name"] = "Mastery Of Taladite", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39176 }, ["series"] = { 39175, 39177, 39195 }, ["description"] = "You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes. I've been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak. What I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.", ["objectivesText"] = "Find the Apexis Gemcutting Construct.", ["rewardXP"] = 1365, ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94605, ["x"] = 0.258, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39177] = { ["id"] = 39177, ["name"] = "Ruined Construct", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39177 }, ["series"] = { 39175, 39176, 39195 }, ["description"] = "<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.> <A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>", ["objectivesText"] = "Repair the Apexis Gemcutter Construct by inserting 1000 Apexis Crystals.", ["rewardItems"] = { 127760, 127761, 127762, 127763, 127764, 127765, 127771, 127772, 127773, 127774, 127775 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 94605, ["x"] = 0.258, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 39176 } },
[39178] = { ["id"] = 39178, ["name"] = "Moose on the Loose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "There's been chatter around the hunters' lodge about a crazed moose that is terrorizing the basin. I've never laid eyes on the beast myself, but they say its antlers are illuminated with magic. Where other lesser hunters have tried and failed, you will prevail, and collect me a one-of-a-kind trophy!", ["objectivesText"] = "Collect the antlers of the cursed ancient spirit, Morashu. Progress: I'm looking forward to hanging the antlers of an ancient spirit within the walls of the hunters' lodge!", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 127767, 141647 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94101, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94101, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "group", ["sourceQuests"] = { 39124 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39179] = { ["id"] = 39179, ["name"] = "Bloodstone Bandit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39389, 40218, 41759, 41767 }, ["description"] = "Something of personal value has been taken from me, and my work here cannot continue until I get it back. To most it would appear to be an ordinary stone, but it is so much more than a simple rock - it lives and breathes! The nearby naga have been snatching anything with any sort of magical significance, my stone included. Fortunately, they do not know how to access its power. Return my stone to me, and I will consider your request for help.", ["objectivesText"] = "Recover Kira's Bloodstone from Narashi Spitescale. Progress: Have you recovered my Bloodstone yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127710, 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 41759 }, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39180] = { ["id"] = 39180, ["name"] = "Warchief's Command: Zangarmarsh!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 9716, 9718, 9720, 39181 }, ["description"] = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition. Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body. The expedition's leader, Ysiel Windsinger , has asked us to direct volunteers to her outpost. Report to her at the Cenarion Refuge in eastern Zangarmarsh . Take the main path to the west and it will lead you directly there.", ["objectivesText"] = "Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh .", ["rewardGold"] = 200, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17841, ["x"] = 0.784, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["nextQuests"] = { 9716 }, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 102 },
