[39182] = { ["id"] = 39182, ["name"] = "Warchief's Command: Terokkar Forest!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 9957, 9960, 9961, 9968, 9978, 9979, 9990, 10112, 39188 }, ["description"] = "We have lost contact with the druids of the Cenarion Thicket The Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened. The thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", ["objectivesText"] = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 18446, ["x"] = 0.442, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard", ["nextQuests"] = { 9968 }, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 108 },
[39188] = { ["id"] = 39188, ["name"] = "Hero's Call: Terokkar Forest!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["series"] = { 9957, 9960, 9961, 9968, 9978, 9979, 9990, 10112, 39182 }, ["description"] = "We have lost contact with the druids of the Cenarion Thicket The King has commanded any able bodies of the Alliance to venture into Terokkar Forest and discover what has happened. The thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", ["objectivesText"] = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.261, ["y"] = 0.383, ["mapID"] = 84, ["objectID"] = 206111 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 18446, ["x"] = 0.442, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard", ["nextQuests"] = { 9968 }, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 108 },
[39189] = { ["id"] = 39189, ["name"] = "Warchief's Command: Nagrand!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 39189 }, ["description"] = "We have lost contact with the druids of the Cenarion Thicket The Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened. The thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.", ["objectivesText"] = "Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.", ["rewardGold"] = 10500, ["rewardXP"] = 260, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3518 } }, ["questType"] = "standard" },
[39190] = { ["id"] = 39190, ["name"] = "DEPRECATED", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39190 }, ["description"] = "The Knights of the Ebon Blade are ready. Place your hand upon the Orb of Command and Acherus will move to its new resting place. We await your orders, Highlord.", ["objectivesText"] = "Christen the Order of the Silver Hand using the Libram of the Order in Light's Hope Sanctum.", ["rewardGold"] = 462000, ["rewardXP"] = 300, ["rewardItems"] = { 94219, 128823, 128868, 209353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39191] = { ["id"] = 39191, ["name"] = "Legacy of the Icebreaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 39191 }, ["description"] = "The greatest warrior should wield the greatest weapons. Long ago a great king, Magnar Icebreaker, wielded weapons crafted from a scale of the mightiest dragon in the land. He should be here, but he is not. Instead he languishes in his tomb. His son, Hruthnir, is here. He will lead you to the tomb. If Magnar can be saved, do so. Either way, return with his weapons.", ["objectivesText"] = "Deal with Magnar Icebreaker. Progress: You have done well. You will bring many victories to these Halls.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 40579, 43949, 44417 }, ["questLines"] = { { ["id"] = 217, ["name"] = "Legacy of the Icebreaker", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 217, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[39195] = { ["id"] = 39195, ["name"] = "Gems of the Apexis", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 534, ["storyline"] = { 39195 }, ["series"] = { 39175, 39176, 39177 }, ["description"] = "Commander! I've noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable. I overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named \"Chakkis.\" Just thought you might be interested.", ["objectivesText"] = "Find Sun-Sage Chakkis in Tanaan Jungle.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["npcID"] = 77209 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 94686, ["x"] = 0.258, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 7078 } }, ["questGiverID"] = 77209, ["questType"] = "standard", ["sourceQuests"] = { 38445 } },
[39196] = { ["id"] = 39196, ["name"] = "Warchief's Command: Nagrand!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["description"] = "The Warchief has asked for any able bodied champions of the Horde to ride to the aid of Garadar. The home of the Mag'har, lies to the south, in Nagrand . Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake. Report to Captain Kroghan there and offer him what assistance you can. Garadar must not fall!", ["objectivesText"] = "Speak with Captain Kroghan at Garadar in Nagrand .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18090, ["x"] = 0.554, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard", ["nextQuests"] = { 9888 }, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 107 },
