[39198] = { ["id"] = 39198, ["name"] = "Warchief's Command: Blade's Edge Mountains!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3522, ["mapID"] = 105, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 10486, 10487, 10488 }, ["description"] = "The Warchief is calling for champions to put an end to the ogre threat in Blade's Edge Mountains . Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Gor'drek know of our plight. Any help he can spare would be most welcome.", ["objectivesText"] = "Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Gor'drek .", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 105, ["npcID"] = 18248, ["x"] = 0.518, ["y"] = 0.578 }, { ["mapID"] = 105, ["npcID"] = 21117, ["x"] = 0.522, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 105, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 105 }, ["zone"] = { 3522 } }, ["questType"] = "standard", ["nextQuests"] = { 10486 }, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 105 },
