[39201] = { ["id"] = 39201, ["name"] = "Warchief's Command: Netherstorm!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 10183, 10186, 11036, 11037, 11040, 11042, 39202 }, ["description"] = "The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours. The Warchief feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael'thas. Area 52 can be reached by following the northeastern road of Blade's Edge Mountains until you see the world crumbling away into the Twisting Nether.", ["objectivesText"] = "Report to Rocket-Chief Fuselage at Area 52.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 19570, ["x"] = 0.326, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard", ["nextQuests"] = { 10186 }, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 109 },
