[39203] = { ["id"] = 39203, ["name"] = "Warchief's Command: Dragonblight!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 11996, 11999, 12005 }, ["description"] = "The Warchief wishes to reinforce the Horde's presence at Agmar's Hammer in the Dragonblight . The fortress is a vital staging point for our assault on Icecrown and pivotal to containing the chaotic magic energies being released throughout the land. Report to Archmage Aethas Sunreaver.", ["objectivesText"] = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", ["rewardGold"] = 10500, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26471, ["x"] = 0.38, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["nextQuests"] = { 11999 }, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[39204] = { ["id"] = 39204, ["name"] = "Hero's Call: Dragonblight!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 11995, 12000, 12004, 12439, 12440 }, ["description"] = "Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart. Those skilled in fighting dragons and undead are greatly welcome. Those willing to answer the call should report to Archmage Modera at Stars' Rest in Dragonblight .", ["objectivesText"] = "Speak with the Image of Archmage Modera at Stars' Rest.", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.261, ["y"] = 0.383, ["mapID"] = 84, ["objectID"] = 206111 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26673, ["x"] = 0.29, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["nextQuests"] = { 12000 }, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[39206] = { ["id"] = 39206, ["name"] = "Warchief's Command: Grizzly Hills!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 12257, 12468, 12487, 12488 }, ["description"] = "We've received a request for help from our base in the Grizzly Hills . Go to see Conqueror Krenna . She's attempting to secure all of the natural resources. Just watch your back around her. The word is that she's aggressive even for an orc. You can reach her by traveling east from Dragonblight.", ["objectivesText"] = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills .", ["rewardGold"] = 10500, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.47, ["mapID"] = 25, ["objectID"] = 206109 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26860, ["x"] = 0.206, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["nextQuests"] = { 12468 }, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets" },
[39207] = { ["id"] = 39207, ["name"] = "Hero's Call: Grizzly Hills!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 12292, 12293, 12294, 12295, 12511 }, ["description"] = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills . All in hopes of finding an alternate route into Icecrown. Lieutenant Dumont , stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", ["objectivesText"] = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills .", ["rewardGold"] = 10500, ["rewardXP"] = 260, ["starts"] = { { ["x"] = 0.261, ["y"] = 0.383, ["mapID"] = 84, ["objectID"] = 206111 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26875, ["x"] = 0.318, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["nextQuests"] = { 12292 }, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets" },
[39208] = { ["id"] = 39208, ["name"] = "Zul'Drak", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 39208 }, ["series"] = { 12630, 12883, 12884, 12902, 49534, 49552 }, ["description"] = "Our death knight allies in Zul'Drak are in need of heroes to aid them in securing the troll lands from the Scourge. Those willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.", ["objectivesText"] = "Report to Stefan Vadu at Ebon Watch in Zul'Drak . Progress: What have you got there, <race>?", ["rewardGold"] = 5350, ["rewardXP"] = 690, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 28518, ["x"] = 0.232, ["y"] = 0.574667 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.232, ["y"] = 0.574667 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard" },
[39209] = { ["id"] = 39209, ["name"] = "Sholazar Basin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3711, ["mapID"] = 119, ["storyline"] = { 39209 }, ["series"] = { 12489, 12521, 39212, 49535, 49553 }, ["description"] = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin . His expedition has not been heard from since. Monte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either. Volunteers are needed to mount an expedition to find the missing expedition. Monte's flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin .", ["objectivesText"] = "Speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin .", ["rewardGold"] = 140450, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 119, ["npcID"] = 27987, ["x"] = 0.396, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 119, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 119 }, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[39210] = { ["id"] = 39210, ["name"] = "The Magical Kingdom of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 2817, ["mapID"] = 127, ["storyline"] = { 39210 }, ["series"] = { 12790, 12791, 12794, 12796 }, ["description"] = "The Kirin Tor have moved their city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. They believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest. When you arrive, seek out Archmage Celindra .", ["objectivesText"] = "Report to Archmage Celindra at The Violet Gate in Dalaran .", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2817 } }, ["questType"] = "standard", ["nextQuests"] = { 12790 } },
[39212] = { ["id"] = 39212, ["name"] = "Sholazar Basin", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3711, ["mapID"] = 119, ["storyline"] = { 39212 }, ["series"] = { 12489, 12521, 39209, 49535, 49553 }, ["description"] = "Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin . His expedition has not been heard from since. Monte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn't returned, either. Archmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot .", ["objectivesText"] = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin . When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin .", ["rewardGold"] = 140450, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 119, ["npcID"] = 27987, ["x"] = 0.396, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 119, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 119 }, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[39214] = { ["id"] = 39214, ["name"] = "The Eye of Odyn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "It is time to begin the war in Azeroth. We have prepared a tool for you to direct your warriors and your own operations from here. It is called the Eye of Odyn. If you will follow me, I will take you to it, and someone that will help you use it.", ["objectivesText"] = "Go to the Eye of Odyn.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.596, ["y"] = 0.837, ["mapID"] = 695, ["npcID"] = 100622 } }, ["ends"] = { { ["x"] = 0.596, ["y"] = 0.837, ["mapID"] = 695, ["npcID"] = 100622 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.596, ["y"] = 0.837 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 100622, ["questTurnInID"] = 100622, ["questType"] = "standard", ["sourceQuests"] = { 39191, 40043, 41105 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
