[39225] = { ["id"] = 39225, ["name"] = "Maw of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["storyline"] = { 39225 }, ["description"] = "Falling into the heart of the mausoleum in Auchindoun, Teron'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. No longer recognizable as an orc, Teron'gor gave up his old name and has taken on the mantle of Gorefiend.", ["objectivesText"] = "Defeat Gorefiend in Hellfire Citadel .", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 136350, 140618, 140619, 140620, 140621, 246936, 249400, 254267, 254579 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.567, ["mapID"] = 590, ["npcID"] = 89753 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.567, ["mapID"] = 590, ["npcID"] = 89753 } }, ["coords"] = { ["mapID"] = 590, ["x"] = 0.402, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 89753, ["questTurnInID"] = 89753, ["questType"] = "raid" },
[39228] = { ["id"] = 39228, ["name"] = "Temple of Tyranny", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["storyline"] = { 39228 }, ["description"] = "Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her. Purge this Eredar of darkness.", ["objectivesText"] = "Defeat Tyrant Velhari in Hellfire Citadel .", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.567, ["mapID"] = 590, ["npcID"] = 89753 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.567, ["mapID"] = 590, ["npcID"] = 89753 } }, ["coords"] = { ["mapID"] = 590, ["x"] = 0.402, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 89753, ["questTurnInID"] = 89753, ["questType"] = "raid" },
[39231] = { ["id"] = 39231, ["name"] = "Destructor's Rise", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["storyline"] = { 39231 }, ["description"] = "We believed we were done with Mannoroth, at least for a time. But Gul'dan is more powerful than we had predicted. Mannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.", ["objectivesText"] = "Defeat Mannoroth in Hellfire Citadel .", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.567, ["mapID"] = 590, ["npcID"] = 89753 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.567, ["mapID"] = 590, ["npcID"] = 89753 } }, ["coords"] = { ["mapID"] = 590, ["x"] = 0.402, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 89753, ["questTurnInID"] = 89753, ["questType"] = "raid" },
