[39236] = { ["id"] = 39236, ["name"] = "Let's Get To Work", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39241, 39242 }, ["description"] = "Now that the shipyard is complete, we need to get busy making ships! Solog ran off to the dry docks, why don't you meet him down there? He said he had a plan.", ["objectivesText"] = "Meet Solog at the dry docks.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 }, { ["mapID"] = 525, ["npcID"] = 97096, ["x"] = 0.415, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 38259 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39241] = { ["id"] = 39241, ["name"] = "Shipbuilding", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39236, 39242 }, ["description"] = "The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there. Let's make sure these don't fall back into the hands of the Iron Horde. Memorize these blueprints, <class>, and then destroy the evidence. Let me know when you are done.", ["objectivesText"] = "Learn the blueprints and destroy the evidence. Progress: You memorize those blueprints yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127268 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39236 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39242] = { ["id"] = 39242, ["name"] = "Ship Shape", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 37889, 37890, 37934, 37935, 39236, 39241 }, ["description"] = "You want to take the fight to Gul'dan? You need a transport! Speak to me when you are ready to begin construction.", ["objectivesText"] = "Speak with Solog to begin construction on a transport ship. Once complete, add it to your collection of ships. Progress: Get that ship started yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39241 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39243] = { ["id"] = 39243, ["name"] = "Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39401 }, ["description"] = "You're a natural at this, <name>. You've got the salt in your veins. Now it's time to run our first naval mission and control the seas of Draenor! You will want a high vantage point to plan out these seafaring missions. I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.", ["objectivesText"] = "Find Rolash Wavechaser at your shipyard and complete a Naval Mission. Progress: Finish a naval mission yet?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 128373 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39423 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39245] = { ["id"] = 39245, ["name"] = "Upgrading The Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39246 }, ["description"] = "You have been doing a great job out there commander. However, we are going to need more experience and resources to upgrade this shipyard. Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!", ["objectivesText"] = "Collect 1000 garrison resources , 1000 gold and combat 15 naval missions. Progress: Finding success on these new naval missions?", ["rewardXP"] = 685, ["rewardItems"] = { 127270 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39676 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
