[39260] = { ["id"] = 39260, ["name"] = "The Black Gate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["storyline"] = { 39260 }, ["description"] = "We've heard rumors that one o' the strongest eredar might enter this world through the Black Gate soon. If these rumors are to be believed, it could even be Archimonde the Defiler. If he arrives unchallenged, Draenor itself is likely to fall.", ["objectivesText"] = "Defeat Archimonde in Hellfire Citadel .", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.326, ["mapID"] = 582, ["npcID"] = 89763 } }, ["ends"] = { { ["x"] = 0.341, ["y"] = 0.326, ["mapID"] = 582, ["npcID"] = 89763 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.341, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 89763, ["questTurnInID"] = 89763, ["questType"] = "raid" },
[39261] = { ["id"] = 39261, ["name"] = "Call of the Illidari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<name>, Kayn requests that you meet him at Krasus' Landing at once. <Kor'vas leans in close, her voice an urgent whisper.> You must hurry. The Legion has eyes everywhere.", ["objectivesText"] = "Speak to Kayn Sunfury at Krasus' Landing.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 140192, 227669 }, ["starts"] = { { ["npcID"] = 99343 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99343, ["questType"] = "standard", ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39262] = { ["id"] = 39262, ["name"] = "Give Me Sight Beyond Sight", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39495, 39515, 39516, 39663 }, ["description"] = "Jace Darkweaver swears that for a split second he sensed a demonic presence up and behind us. He took some of our forces up to the cave just to the southeast to investigate. They found nothing in the cave, but he is certain that something is amiss. Would you lend him your guidance, and more importantly, your spectral sight?", ["objectivesText"] = "Speak with Jace Darkweaver and then use your Spectral Sight ability to scan the cave for hidden demons. Progress: <name>, we need you to scan the cave with your spectral sight. We must know if there are Legion forces magically hidden within.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 6802, 128944, 128945, 128946, 128947, 128948, 128949, 128958, 129192, 129195, 132243, 133580 }, ["starts"] = { { ["x"] = 0.605, ["y"] = 0.447, ["mapID"] = 672, ["npcID"] = 93127 } }, ["ends"] = { { ["x"] = 0.605, ["y"] = 0.447, ["mapID"] = 672, ["npcID"] = 93127 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.605, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 93127, ["questTurnInID"] = 93127, ["questType"] = "standard", ["sourceQuests"] = { 38813 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[39272] = { ["id"] = 39272, ["name"] = "Poisoned Crops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["description"] = "After driving us from the farmland and infesting our crops with insects, the drogbar placed wicked totems that further poison our harvest. I can only hope that if you destroy them, we'll be able to heal the land using Jale's water magic. Thank you for coming to help us, <name>. We are but simple farmers and fishermen, and have little prowess in combat.", ["objectivesText"] = "Destroy the drogbar Poison Idols . Progress: The crops must be rid of this poison!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95191, ["x"] = 0.436, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95191, ["x"] = 0.436, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38911 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
