[39276] = { ["id"] = 39276, ["name"] = "Strange Tools", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["description"] = "We are well on our way to building our first ship, but unfortunately, I am not the orc for the job. I have no idea how to work with these human tools. Your shipwright, Yanas Seastrike , is going to take over from here on out. I will be here at the dry docks if you need anything from me.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["npcID"] = 94429, ["x"] = 0.298, ["y"] = 0.106, ["mapID"] = 539 }, { ["npcID"] = 94429, ["x"] = 0.408, ["y"] = 0.702, ["mapID"] = 525 } }, ["ends"] = { { ["npcID"] = 95002, ["x"] = 0.298, ["y"] = 0.106, ["mapID"] = 539 } }, ["coords"] = { ["x"] = 0.298, ["y"] = 0.106, ["source"] = "quest_giver", ["mapID"] = 525 }, ["mapCandidates"] = { ["npc"] = { 525, 539 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39054 } },
[39277] = { ["id"] = 39277, ["name"] = "Spray and Prey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39487, 39488, 39489, 39498, 39661, 42104 }, ["description"] = "The Bug Sprayer you recovered from Ormgul the Pestilent seems like it could give us an advantage against the drogbar and their insects. Spray the Drogbar with their own alchemy and watch their insects turn against them.", ["objectivesText"] = "Use the Bug Sprayer on drogbar in Whitewater Wash. Progress: For this group of drogbar to turn against us after so many years of peace...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127988, 130291, 130292, 130293, 130294, 133820, 141634, 141635, 141636, 141637 }, ["rewardChoices"] = { 130291, 130292, 130293, 130294, 141634, 141635, 141636, 141637 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95956, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95956, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39496 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39278] = { ["id"] = 39278, ["name"] = "The Missing Manifest", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 39278 }, ["description"] = "The water-proofed manifest contains some form of code for the most part, hiding the contents of the actual manifest. In the corner is a hastily scrawled note for a Mr. Knuckles. \"Shipment attacked, got away but boat is sinking. Get here before they do.\" There are coordinates after that which lead to the sunken boat. Mr. Knuckles is definitely the kind of person you want owing you a favor, not the other way around.", ["objectivesText"] = "Find Mr. Knuckles' missing shipment. Progress: Whatchoo got there?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 119093, 127669, 127989, 128027 }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83888, ["x"] = 0.538, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard", ["startItems"] = { 127989 } },
