[39292] = { ["id"] = 39292, ["name"] = "Ashran Dominance", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 39292 }, ["description"] = "The Alliance refuse to back down in Ashran . Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", ["objectivesText"] = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade .", ["rewardXP"] = 200, ["rewardItems"] = { 126924 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8485 } }, ["questType"] = "standard" },
