[39299] = { ["id"] = 39299, ["name"] = "Black Marketeering", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 39299 }, ["description"] = "Ya did us a real solid today, <name>. Boss Goya says you're big stuff in dese parts and we should keep an eye on --- uh, I mean we should be good buds. She's sent a repre... repre... del-e-g... um, a Black Market person to your garrison. Go say hi and stuff, and make sure to speak loudly when you plan what you're gonna do next.", ["objectivesText"] = "Speak with Zhang Yeoh in your garrison.", ["rewardItems"] = { 127989 }, ["rewardCurrencies"] = { { ["id"] = 824, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 550, ["npcID"] = 83888, ["x"] = 0.538, ["y"] = 0.15 } }, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 83888, ["x"] = 0.538, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questTurnInID"] = 83888, ["questType"] = "standard", ["sourceQuests"] = { 39278 } },
[39305] = { ["id"] = 39305, ["name"] = "Empty Nest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "I've taken an inventory of the eggs you recovered. Some among the bunch may still have a chance to hatch. They will need to be returned to an empty nest, and with any luck, an eagle will claim the eggs as her own and watch over them once again. There is a nest just outside the entrance, on a rocky ledge above the cave. Be careful, <name>. The eggs are very delicate.", ["objectivesText"] = "Place the eagle eggs in the empty nest above the eastern entrance to Rockcrawler Chasm. Progress: If there's any hope for those eggs hatching, they'll need to be returned to their nest.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128757, 129277, 141605, 257723 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40070, 40071, 42425 }, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
