[39313] = { ["id"] = 39313, ["name"] = "Bring the Reinforcements", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39313 }, ["description"] = "Greetings, Commander! With all of the fighting concentrated here in Tanaan, we've got the breathing room to divert some of our resources from nearby outposts to help make headway. Just let me know which reinforcements to call, and I'll get them here on the double!", ["objectivesText"] = "Talk to Angar Steelbellow and choose which reinforcements to bring to Tanaan. Progress: Which allies should I call for?", ["rewardGold"] = 127350, ["rewardXP"] = 4100, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90963, ["x"] = 0.58, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90963, ["x"] = 0.58, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 38445 } },
[39315] = { ["id"] = 39315, ["name"] = "Bring the Reinforcements", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39315 }, ["description"] = "Hey there, Commander. You know, with all of the fighting concentrated here in Tanaan, we've got plenty of extra supplies just sitting around in our nearby outposts. You just give me the order and I'll make sure some of them get sent our way!", ["objectivesText"] = "Talk to Fraggs and choose which reinforcements to bring to Tanaan.", ["rewardGold"] = 127350, ["rewardXP"] = 4100, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90993, ["x"] = 0.598, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90993, ["x"] = 0.598, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 37935 } },
[39316] = { ["id"] = 39316, ["name"] = "Trapped Tauren", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 38911, 39491, 39496, 39733 }, ["description"] = "The drogbar just rounded up those of us that they could and led them to a cave near here. If you act quickly, I think they can still be saved. I know not what purpose they have for capturing our people. I shudder to think of it... in the deep places, the darkness rules.", ["objectivesText"] = "Free the captured Rivermane tauren. Progress: They slew many of my brothers and sisters, but at least some managed to escape. Others, however, we captured.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39496 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39317] = { ["id"] = 39317, ["name"] = "Siege of Crawliac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["description"] = "Defend the bluffs!", ["rewardGold"] = 404400, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 200 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Break the harpy assault on Skyhorn!" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 20, ["objectID"] = 94983 }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 10, ["objectID"] = 94986 }, { ["orderIndex"] = 3, ["type"] = 0, ["amount"] = 20, ["objectID"] = 95174 }, { ["orderIndex"] = 4, ["type"] = 0, ["amount"] = 10, ["objectID"] = 95204 } } },
[39318] = { ["id"] = 39318, ["name"] = "Nursing the Wounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38910, 38913, 39321 }, ["description"] = "I know why Mayla sent you. But as you have seen, the drogbar are not the only threat to Highmountain . I will not send forces to support until we deal with the minions of High Crawliac. If you want to help, find my shaman. He was supposed to be dispersing these fires that are ravaging my village. He was last seen heading for his spirit lodge to the south just before these Cinderwitches descended on us.", ["objectivesText"] = "Find Windmaster Julan and help extinguish the fires on Skyhorn. Progress: These harpies are all over the place!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38913 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39321] = { ["id"] = 39321, ["name"] = "The Three", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38910, 38913, 39318 }, ["description"] = "When High Crawliac seized control of the harpies she placed 3 powerful and deadly witches in charge of the covens under her command. These witches must die. Feel up for the challenge? Head into the Haglands behind me and find these three evil creatures. We will cover you from the air and give your prey no sky to retreat. Look for us higher up the mountain, should you survive.", ["objectivesText"] = "Slay Ragi the Hexxer , Agara Deathsong , and Ugla the Hag . Progress: Many Skyhorn have fallen to the witchcraft of these hags.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 52913, 52959, 121664, 121665, 121666, 121667, 130303, 130304, 130305, 130306, 131832 }, ["rewardChoices"] = { 121664, 121665, 121666, 121667, 130303, 130304, 130305, 130306 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38910 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39322] = { ["id"] = 39322, ["name"] = "The Witchqueen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 39387 }, ["description"] = "The time has come to assault High Crawliac , the Witchqueen. You should know that one does not become queen of the harpies through kindness. This creature has killed, betrayed, and tormented countless tauren, harpies, kobolds, and anything else she had to in order to secure her position as queen. Come, friend, let us finish this.", ["objectivesText"] = "Slay High Crawliac , the Witchqueen. Progress: Without a queen, it will take the harpies many years before they can organize in such numbers again.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133092, 133093, 133094, 133095, 133096, 133097, 133098, 133099, 133100, 133102, 133103, 133104, 133105, 133106, 133107, 133108, 133109, 133110, 133111, 133113 }, ["rewardChoices"] = { 133092, 133093, 133094, 133095, 133096, 133097, 133098, 133099, 133100, 133102, 133103, 133105, 133106, 133107, 133108, 133109, 133110, 133111, 133113 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39321, 39429 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39323] = { ["id"] = 39323, ["name"] = "Moozy's Sojourn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39323, 39572, 42590 }, ["series"] = { 39572 }, ["description"] = "My son! They took him! My wife and I split up to look for him. She went upriver and I went downriver. Leave me, please, and find Moozy... I might be okay... If you find Moozy, please bring him to my wife upriver.", ["objectivesText"] = "Find Moozy downriver in Whitewater Wash.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96083, ["x"] = 0.402, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96083, ["x"] = 0.402, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 96083, ["questType"] = "standard", ["sourceQuests"] = { 39272, 39490, 39491 }, ["questLines"] = { { ["id"] = 5914, ["name"] = "Moozy's Family Reunion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39325] = { ["id"] = 39325, ["name"] = "Get Your Mix On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39326 }, ["description"] = "Let's see... potion stains on your tabard, crushed herbs on your boots... I know a fellow alchemist when I see one! We will do good work together, the two of us. I trust you're not averse to learning new tricks. Be sure to use my state-of-the-art alchemy table. I built her myself!", ["objectivesText"] = "Deucus Valdera in Dalaran wants you to craft some new potions. Merchant Patricia Egan in the alchemy shop can help you learn how. Progress: I hope you're making good use of my alchemy table. It's my pride and joy!", ["rewardGold"] = 20220, ["rewardXP"] = 1415, ["rewardItems"] = { 3371, 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127898, 127899, 127900, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127917, 127930, 127932, 127933, 128209, 128304 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39326] = { ["id"] = 39326, ["name"] = "Missing Shipments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39325 }, ["description"] = "Now that we've gotten to know each other, perhaps you can lend me a hand. My weekly supply shipment was lost when my longtime courier--you know, old whatsername--was shot out of the sky over the shores of Azsuna. Surely a hardy sort like you could retrieve my lost goods.", ["objectivesText"] = "Alchemist Deucus Valdera in Dalaran wants you to locate supplies lost near the water in Azsuna. Progress: I say, I do hope you were able to locate my lost supplies. How are we to build trust between us if you won't do everything I ask?", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128355, 128356, 128357 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39325 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39327] = { ["id"] = 39327, ["name"] = "There's a Scribe for That", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39328, 39329, 39330, 39390, 39566 }, ["description"] = "Fine! I admit, even my considerable intellect can't translate the strange tome you discovered. No doubt the water smears made it illegible. Say, one of those dimwitted scribes down the block owes me a favor. This sort of busywork is just his cup of tea.", ["objectivesText"] = "Bring the Runewritten Tome to Professor Pallin in Dalaran. Progress: I don't have time to translate tomes! That's what lesser professions are for.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128290, 128291, 128304 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39390 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39328] = { ["id"] = 39328, ["name"] = "Ancient Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39329, 39330, 39390, 39566 }, ["description"] = "The tome contains a wealth of ancient vrykul recipes! Why, I could be the first alchemist in untold ages to craft one! How fortunate for you, friend <name>, that you are here to bear witness to my greatness! Awful kind of that Svena person to die and leave her book for us, eh? Silly vrykul...", ["objectivesText"] = "Observe Deucus Valdera as he attempts one of the vrykul recipes.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39327 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39329] = { ["id"] = 39329, ["name"] = "A Dormant Burner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["description"] = "I've heard that someone over in the engineering shop is selling a burner that might be usable. You could likely negotiate a fairer price than I could! The shop is just across the street. I'll make a note on your map for you.", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39328 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39330] = { ["id"] = 39330, ["name"] = "Ley Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39328, 39329, 39390, 39566 }, ["description"] = "The leyflame burner you brought me is useless! This is why I never trust an engineer... The burner needs to be charged in areas that resonate with ley energy before it can be used to craft our newfound alchemy recipes. Lucky for us, Azsuna is rich with such power.", ["objectivesText"] = "Travel to key locations in Azsuna and use the Depleted Leyflame Burner to collect ley energy.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128329 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39329 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39331] = { ["id"] = 39331, ["name"] = "Eye of Azshara: Put a Cork in It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39332 }, ["description"] = "A thought occurred to me recently, <name>. The naga have been known to hoard all manner of potions, so they might have the sort of corks we need. In my educated opinion, I believe the best place to start searching is around the Eye of Azshara! Try not to waste your time in there dealing with the naga's goings on, just look for some replacement corks.", ["objectivesText"] = "Go to the Eye of Azshara and retrieve the Advanced Corks for Deucus Valdera in Dalaran. Progress: The sooner we get my supplies back, the quicker we can get back to real work.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127873, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128335 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "dungeon", ["sourceQuests"] = { 39330 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39332] = { ["id"] = 39332, ["name"] = "Furbolg Firewater", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39331 }, ["description"] = "Oh! I recognize these corks you brought me, <name>. I recently acquired several from a furbolg tribe in Val'sharah. They need sturdy corks to keep a tight seal on that potent firewater they brew. We need more firewater potions--the corks would make an ideal addition to our alchemy table!", ["objectivesText"] = "Acquire skins of Smolderhide Firewater from the furbolg camp in Val'sharah. Bring them back to Deucus Valdera in Dalaran so he can make use of the corks. Progress: Did you find more firewater potions? I bet it's tempting to take a swig!", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128335 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39331 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39333] = { ["id"] = 39333, ["name"] = "An Imprecise Burette", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39342 }, ["description"] = "Here are your burettes. Should you ever be in the need of anything else, don't hesitate to ask. < Ms. Xiulan holds up the hair and continues to chuckle to herself.>", ["objectivesText"] = "Bring the Uncalibrated Malloric Burettes to Deucus in Dalaran. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128676 }, ["starts"] = { { ["x"] = 0.708, ["y"] = 0.198, ["mapID"] = 628, ["npcID"] = 101492 } }, ["ends"] = { { ["x"] = 0.708, ["y"] = 0.198, ["mapID"] = 628, ["npcID"] = 101492 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.708, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101492, ["questTurnInID"] = 101492, ["questType"] = "standard", ["sourceQuests"] = { 39342 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["startItems"] = { 127872 } },
[39334] = { ["id"] = 39334, ["name"] = "Thanks for Flasking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39430 }, ["description"] = "Here is your flask, good as new. A fair trade for those potions. Be a little more careful with your breakables next time!", ["objectivesText"] = "Take the repaired Dual-Chambered Mixing Flask to Deucus Valdera in Dalaran. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128516 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 92242, ["questType"] = "standard", ["sourceQuests"] = { 39430 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39335] = { ["id"] = 39335, ["name"] = "Neltharion's Lair: Potent Powder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39336 }, ["description"] = "I've heard rumors that the ancient drogbar collected powder from the residue of dragon's breath. If it's true that Neltharion's Lair lies somewhere below us, it seems a likely source. Go there and try to find a replacement for my powder.", ["objectivesText"] = "Acquire Precipitating Powder in Neltharion's Lair and bring it to Deucus Valdera in Dalaran. Progress: What have we here?", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127874, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "dungeon", ["sourceQuests"] = { 39430 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39336] = { ["id"] = 39336, ["name"] = "We Need More Powder!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39335 }, ["description"] = "The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes. There are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!", ["objectivesText"] = "Obtain Katterin's Alchemy Kit from Katterin the Blistered in Stormheim. Progress: Let's hope you find the powder we need...", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128345 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39335 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39337] = { ["id"] = 39337, ["name"] = "Forlorn Filter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39338, 39431, 44112 }, ["description"] = "Next on the list of things to replace are my filters. Now I'm sure you've concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions. The elves at the Temple of Elune in Val'sharah use Shaldorei silk to craft their robes. Perhaps they'd be willing to part with some for my filters.", ["objectivesText"] = "Speak with a Temple Priestess at the Temple of Elune to see if you can acquire some Shaldorei Silk. Progress: A pile of tattered shaldorei silk lay on the chest.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39336 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39338] = { ["id"] = 39338, ["name"] = "Return the Filter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39337, 39431, 44112 }, ["description"] = "What was torn has now been mended. I hope you put this Shaldorei silk to good use. Now, run along.", ["objectivesText"] = "Return the Mended Shaldorei Silk to Deucus Valdera in Dalaran. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128518 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.704667, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 93974, ["questType"] = "standard", ["sourceQuests"] = { 44112 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39339] = { ["id"] = 39339, ["name"] = "A Fragile Crucible", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39340, 39341 }, ["description"] = "I have customers asking for alchemist stones, but I'm unable to make any until I replace my crucible. In order to create a new one, we'll need a few things, but first we'll need a proper container. Something that can be augmented to withstand a demon's breath. There's a place in Suramar which the Legion has occupied. There surely must be a device there we can take that will be suitable for our needs.", ["objectivesText"] = "Bring the Fragile Demonsbreath Crucible to Deucus Valdera in Dalaran. Progress: I trust you're strong enough to handle a few demons?", ["rewardXP"] = 6140, ["rewardItems"] = { 28725, 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128681 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39338 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39340] = { ["id"] = 39340, ["name"] = "Lining the Crucible", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39339, 39341 }, ["description"] = "The first step in making this crucible useful is to restore the lining of its interior. That's going to require supplies you'll either gather yourself or obtain through trade with fellow adventurers. Felwort and yseralline seeds are familiar to herbalists. Felhide is obtained through skinning. Blood of Sargeras can be found all over the Broken Isles.", ["objectivesText"] = "Gather 1 Blood of Sargeras , 1 Felhide , 2 Felwort , and 100 Yseralline Seeds . Progress: Restoring the lining of the crucible is no simple task, <name>.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128681 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39338 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39341] = { ["id"] = 39341, ["name"] = "Vault of the Wardens: Demon's Bile", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39339, 39340 }, ["description"] = "The key to a crucible like this is that it must be bathed in the foulest of fel energy. I hate to say it, but the most efficient method of accomplishing such a feat is to subject it to the bile of a demon. Yes, I said the bile of a demon. Ready to get to work? In the Vault of the Wardens, such a demon exists. An imp mother by the name of Grimoira . The door to her room is sealed by an invisible lock. I'd suggest bringing some Skaggldrynk with you. Use it when you get to her door.", ["objectivesText"] = "Craft a Skaggldrynk , then go to the Vault of the Wardens and bathe the crucible in the bile of Grimoira .", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127877, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128679, 136723 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "dungeon", ["sourceQuests"] = { 39339, 39340 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39342] = { ["id"] = 39342, ["name"] = "The Price of the Black Market", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39333 }, ["description"] = "I may have what you're looking for, burettes you say? Not a very common item. For that, I require a moderate favor. Nothing too big, just a few things really. A silver hair from a high-ranking archmage... the blood of a titan, and, oh... some wine and cheese. What?! I have appetites that need satiating.", ["objectivesText"] = "Collect a Silver Hair of Khadgar , a Blood of Sargeras , 5 Kaldorei Ginger Wine and 5 Moist Azsunian Feta . Progress: Don't take too long now. Who knows who else may be in the market for your precious burettes.", ["rewardXP"] = 6140, ["rewardItems"] = { 116268, 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128764, 128833, 136723 }, ["starts"] = { { ["x"] = 0.708, ["y"] = 0.198, ["mapID"] = 628, ["npcID"] = 101492 } }, ["ends"] = { { ["x"] = 0.708, ["y"] = 0.198, ["mapID"] = 628, ["npcID"] = 101492 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.708, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101492, ["questTurnInID"] = 101492, ["questType"] = "standard", ["sourceQuests"] = { 39344 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39343] = { ["id"] = 39343, ["name"] = "Vault of the Wardens: Bendy Glass Tubes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "You find tubing formed from a bendable sort of glass. It appears as though Grimoira was using it to suck out the insides of her victims. Its magical properties, however, would seem ideal for use on an advanced alchemy table.", ["objectivesText"] = "Bring the Bendy Glass Tubes to Deucus Valdera in Dalaran. Provided item:", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127877, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.5, ["mapID"] = 678 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.5, ["mapID"] = 678 } }, ["coords"] = { ["mapID"] = 678, ["x"] = 0.4, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 39339, 39340 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["startItems"] = { 127877 } },
[39344] = { ["id"] = 39344, ["name"] = "Going Underground", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "We're so close to replacing all my equipment, <name>. In order to make flasks again, we need to be able to precisely measure each ingredient. For that, we need to replace my burette assembly. Unfortunately, burettes aren't easy to come by. We may be able to procure some though through other means by... <Deucus looks around and beckons you closer.> Going underground, so to say. As in, the Black Market. Go see Ms. Xiulan . Mum's the word.", ["objectivesText"] = "See Ms. Xiulan about acquiring some new burettes for Deucus.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39343 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 127878 } },
[39345] = { ["id"] = 39345, ["name"] = "Calibration Experts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 42081 }, ["series"] = { 39346, 39645 }, ["description"] = "It will take the cooperation of several highly skilled sorts to calibrate these burettes for a variety of substances. Chemist Emmara is an old friend from the Undercity who has helped me with similar endeavors. Thunder Bluff smells like a barn to me, but Jana Winterhoof is an alchemist with exacting standards. And while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair.", ["objectivesText"] = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128676 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39333 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39347] = { ["id"] = 39347, ["name"] = "Channeling Our Efforts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "While it's no secret my time is more valuable than... well, anyone's, I fear I must step in and help to replace my decoction conduit. You will also play a crucial part in this, <name>, as my liaison with the blacksmiths. The thought of getting soot on my robes curls my toes. Here's a list of what we'll need done. Meanwhile I'll be out gathering the rest of what's needed.", ["objectivesText"] = "Talk to Alard Schmied about the list of things you need done. Provided item:", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136823 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39346 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39348] = { ["id"] = 39348, ["name"] = "Halls of Valor: The Prime Ingredient", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39349, 39350, 39351 }, ["description"] = "This first ingredient can only be obtained by visiting the next realm. Fortunately for us, there's a gate in Stormheim that can take you there. In the Halls of Valor, there is a sand that's used for polishing their architecture. Eternity Sand , it's called. I'll need an ample amount of it as the base for the new glass. This ingredient won't be easy to work with either. I'll need something to keep me going, you know, keep my stamina up.", ["objectivesText"] = "Retrieve the Eternity Sand from Heroic: Halls of Valor, craft a Flask of Ten Thousand Scars and return both items to Alard in Dalaran. Progress: What a sight the Halls of Valor must be. You'll have to tell me about them sometime after your return.", ["rewardXP"] = 6140, ["rewardItems"] = { 3371, 124101, 124102, 124103, 124105, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136784 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.45, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "dungeon", ["sourceQuests"] = { 39347 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39349] = { ["id"] = 39349, ["name"] = "Black Rook Hold: Heavy, But Helpful", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39348, 39350, 39351 }, ["description"] = "The next ingredient on the list will supposedly add strength to the mix, according to Deucus. I've heard of it before, but haven't really used it. It's called Sabelite Sulfate , and it's said the elves of Black Rook Hold use it in their blacksmithing. Something like that won't just be lying around. You may have to delve deep into the hold to find it. And due to its weight, I may need a concoction of yours to compensate, something to give me a bit more strength.", ["objectivesText"] = "Retrieve some Sabelite Sulfate from Heroic: Black Rook Hold, craft a Flask of the Countless Armies and return both items to Alard in Dalaran. Progress: I hope Deucus was right about these ingredients. This'll be the first time I'm making something like this.", ["rewardXP"] = 6140, ["rewardItems"] = { 3371, 124101, 124102, 124103, 124105, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136812 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.45, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "dungeon", ["sourceQuests"] = { 39347 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39350] = { ["id"] = 39350, ["name"] = "Maw of Souls: A Hope in Helheim", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39348, 39349, 39351 }, ["description"] = "For this last ingredient, well... <Alard begins pondering for a moment, then nods his head.> Yes, that's the only way. For this last one, you'll need to go to the land of the damned, Helheim. Well, not there exactly, but aboard the boat that ferries the dead across the Maw of Souls. Upon that boat may be the final ingredient we need. It's called Dragur Dust . Keep an eye out for it. Also, one needs to be quick when adding this ingredient. I'll need something to heighten my reflexes.", ["objectivesText"] = "Retrieve a crate of Dragur Dust from Heroic: Maw of Souls, craft a Flask of the Seventh Demon and return both items to Alard in Dalaran. Progress: Were you able to board the ship? Did you find the dust?", ["rewardXP"] = 6140, ["rewardItems"] = { 3371, 124102, 124103, 124104, 124105, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136819 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.45, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "dungeon", ["sourceQuests"] = { 39347 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39351] = { ["id"] = 39351, ["name"] = "The Emerald Nightmare: Rage Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39348, 39349, 39350 }, ["description"] = "Now that we have all the ingredients assembled, we need one last thing. The fire of my forges burn hot, but not hot enough to work these ingredients into glass. For that, we need more heat. The heat of a dragon, to be exact. I'm aware of one that has emerged from the Emerald Dream in a corrupted state. Corrupted or not, a dragon's heart burns with enough heat to melt the strongest of materials. Bring me its heart and you'll have your conduit.", ["objectivesText"] = "Travel to the Emerald Nightmare and acquire Nythendra's Heart . Bring it to Alard in Dalaran. Progress: I'm getting the mixture ready now. As soon as you return with the heart, I'll begin the construction.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136820 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.45, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "raid", ["sourceQuests"] = { 39348, 39349, 39350 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 31, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
