[39371] = { ["id"] = 39371, ["name"] = "Witches of the Sky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39371 }, ["objectivesText"] = "Cleanse the Witchwood", ["rewardGold"] = 547696, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 200 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cleanse the Witchwood", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39372] = { ["id"] = 39372, ["name"] = "Witch of the Wood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "You saved me at Riverbend not long ago. It is the reason I vouched for you as emissary to this tribe, and the only reason you're alive here now. I consider my debt to you paid. You must prove yourself to the Bloodtotem chieftain before he will speak with you. Within the forest is the Witch of the Wood , a harpy mother who recently descended into this territory. If you are able to defeat her and show her carcass to the Bloodtotem, they might allow you an audience with Torok.", ["objectivesText"] = "Defeat the Witch of the Wood .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38912 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39373] = { ["id"] = 39373, ["name"] = "Hags of a Feather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The drogbar you freed me from were unusually aggressive. The tribe in the nearby caves seems to be apart from the rest of them, but that didn't stop the Bloodtotem from going on the offensive just in case, capturing some of their number. That move left the woods exposed to the harpies, however. Your help dealing with these witches would not go unnoticed by Torok. Bring back their feathers as proof of death.", ["objectivesText"] = "Collect 50 Hag Feathers from Witchwood Hags in the Witchwood. Progress: Your size belies your strength, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128380 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38912 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39374] = { ["id"] = 39374, ["name"] = "An Audience with Torok", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "I should warn you that Torok is easily displeased and is hateful of outsiders. Be on your guard. We will seek an audience with him at his tent at the Cliff's Edge. As the Rivermane Emissary here, I am afforded some protection against aggression, but they have made no such promises about you.", ["objectivesText"] = "Speak with Torok Bloodtotem. Progress: I just hope the Bloodtotem don't cut us down for demanding their chieftain's time.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39372, 39373, 39873 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
