[39381] = { ["id"] = 39381, ["name"] = "Rock Troll in a Hard Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people. Let me know when you are ready to go, and I can take us to a safe place quickly.", ["objectivesText"] = "Speak with Navarrogg to meet him at a safe location.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.414, ["y"] = 0.823, ["mapID"] = 653, ["npcID"] = 96286 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 96286, ["questType"] = "standard", ["sourceQuests"] = { 39860 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39383] = { ["id"] = 39383, ["name"] = "Dishonored", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 38382, 39384 }, ["description"] = "Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius. During the great war, it was he who led the slaughter of many of my dearest friends. The last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.", ["objectivesText"] = "Slay Xandris the Dishonored .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95395, ["x"] = 0.61, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95396, ["x"] = 0.628, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38382 }, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39384] = { ["id"] = 39384, ["name"] = "The Corruptor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 38382, 39383 }, ["description"] = "Xandris has been slain, but there are others that must be dealt with if my grove is to be saved. During the great war, Kagraxxis took great pleasure in corrupting the lands he once called home. Were it not for the foolish mercy of my fellow druids, I would have slain him myself. Find the demon and bring justice upon him. I must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.", ["objectivesText"] = "Slay Kagraxxis the Corruptor . Progress: Kagraxxis must be slain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 12844, 57374, 57375, 57376, 57377, 57378, 57379, 206576 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95396, ["x"] = 0.628, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91650, ["x"] = 0.65, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39383 }, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39385] = { ["id"] = 39385, ["name"] = "A Gift for Greymane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39153, 39154, 39155 }, ["description"] = "It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It's likely they intend to use them on the walls of Dreadwake's Landing. If these could be rigged to Greymane's ship, it could make for a decisive end to his assault on the outpost.", ["objectivesText"] = "Plant 3 Gilnean Heavy Explosives onto the hull of Greymane's ship and detonate them at a safe distance. Progress: <insert>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128287, 129225, 129226, 129227, 129228, 132762, 132763, 132764, 132765 }, ["rewardChoices"] = { 129225, 129226, 129227, 129228, 132762, 132763, 132764, 132765 }, ["starts"] = { { ["x"] = 0.576, ["y"] = 0.719, ["mapID"] = 634, ["objectID"] = 243454 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38872 }, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39386] = { ["id"] = 39386, ["name"] = "Procuring a Prototype", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["series"] = { 39656, 39670 }, ["description"] = "If Addie's going to be a more permanent member of the huntin' party, then she'll need some specialty gear for someone her size. My munitions expert should have some ideas about what kind of weapon would best suit a gnome. Stop by his camp and let him know that I'll be needin' a prototype soon.", ["objectivesText"] = "Find Razik Gazbolt at Icepine Point.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39178, 40228 }, ["nextQuests"] = { 39670 }, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39387] = { ["id"] = 39387, ["name"] = "The Skies of Highmountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 39322 }, ["description"] = "When you are ready, join me at the base of Thunder Totem. I would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla. Together, we are Highmountain !", ["objectivesText"] = "Speak with Lasan Skyhorn at the base of Thunder Totem. Progress: Have you had any luck with Lasan?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 141394, 246937, 257401 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 95410, ["questType"] = "standard", ["sourceQuests"] = { 39322 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750 },
[39388] = { ["id"] = 39388, ["name"] = "Moonclaw's Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39388 }, ["description"] = "Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius. Still, there is much about these satyrs that I wish to tell you. This information would be most valuable to you. Please meet me in my den before departing.", ["objectivesText"] = "Meet Thaon Moonclaw in his den.", ["rewardGold"] = 238680, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[39389] = { ["id"] = 39389, ["name"] = "It Hungers for Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 40218, 41759, 41767 }, ["description"] = "Bloodstones contain a great deal of power that can only be awakened once they are fed. Yet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better. There's an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.", ["objectivesText"] = "Let the Bloodstone feed on the blood of demons. Progress: Has the Bloodstone been sated yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39179 }, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39390] = { ["id"] = 39390, ["name"] = "A Mysterious Text", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39328, 39329, 39330, 39566 }, ["description"] = "You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.", ["objectivesText"] = "Bring the Runewritten Tome to Deucus Valdera in Dalaran. Progress: You found something down in Azsuna, <name>? Do share. It's so rare for something interesting to walk through the door of my quiet little shop.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128224, 128290, 128304 }, ["starts"] = { { ["x"] = 0.449, ["y"] = 0.521, ["mapID"] = 630, ["objectID"] = 243392 } }, ["ends"] = { { ["x"] = 0.449, ["y"] = 0.521, ["mapID"] = 630, ["objectID"] = 243392 } }, ["coords"] = { ["mapID"] = 630, ["x"] = 0.449, ["y"] = 0.521 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39566 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39391] = { ["id"] = 39391, ["name"] = "Pet Rocks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me. If they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can't muster the strength to find them. If you find them, it would be much appreciated.", ["objectivesText"] = "Find Navarrogg 's pets. Progress: These beasts are not terribly bright, but they are loyal in their way.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39381 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39392] = { ["id"] = 39392, ["name"] = "Bear Huntin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf's beard. But if the fur doesn't kill ya, the maul will. Some lesser hunters have been a meal for those bears. Show me you're more than a snack and bring me back a few of those bristlefur pelts .", ["objectivesText"] = "Collect 4 Bristlefur Pelts within the Fields of An'she. Progress: Procuring a few Bristlefur Pelts should help sell me on your huntin' skills.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128286 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40170 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
