[39394] = { ["id"] = 39394, ["name"] = "The Cipher of Damnation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 38462, 38561, 39394 }, ["description"] = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy. Gul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", ["objectivesText"] = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", ["rewardGold"] = 509400, ["rewardXP"] = 1365, ["rewardItems"] = { 124551, 128225, 128309, 128320 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92120, ["x"] = 0.625, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93658, ["x"] = 0.626, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 38462 }, ["questLines"] = { { ["id"] = 124, ["name"] = "Gul'dan Finale", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534 },
