[39401] = { ["id"] = 39401, ["name"] = "Destroying the Competition", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39243 }, ["description"] = "One battle does not win the war, Commander. That Transport isn't gonna hold up long against this Iron Horde navy. We are going to need another ship. Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers. We should construct one of these ships immediately!", ["objectivesText"] = "Construct a Destroyer in your Shipyard and send it on a naval mission. Progress: What is the status of the Destroyer?", ["rewardItems"] = { 126900, 127269 }, ["rewardCurrencies"] = { { ["id"] = 824, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39243 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
