[39405] = { ["id"] = 39405, ["name"] = "Stories of Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39405 }, ["description"] = "The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. If Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. The answer to her involvement likely lies within the remaining text.", ["objectivesText"] = "Collect 8 verses of Ashilvara from Priestesses of Eyir in Skold-Ashil. Progress: This appears to be the last verse.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 126946 }, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.642, ["mapID"] = 634, ["objectID"] = 251571 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94228, ["x"] = 0.630667, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39154 }, ["startItems"] = { 128324 } },
[39417] = { ["id"] = 39417, ["name"] = "Rating Razik", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39417 }, ["series"] = { 39859, 40170, 40216, 40217 }, ["description"] = "Hemet is expecting an update on how my munitions research and development is going. I'm sure you'll be happy to tell my boss that my latest creation worked flawlessly! You can find him at his camp near the hunters' lodge.", ["objectivesText"] = "Find Hemet Nesingwary at his Highmountain retreat.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39656 }, ["nextQuests"] = { 39859, 40170 } },
[39419] = { ["id"] = 39419, ["name"] = "Hex-a-Gone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39419 }, ["description"] = "The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them. The Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.", ["objectivesText"] = "Slay Hexweaver Akara . Progress: Hexweaver Akara must be slain if the Skyhorn wish to gain the upper hand.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94522, ["x"] = 0.472, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94522, ["x"] = 0.472, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39422] = { ["id"] = 39422, ["name"] = "Shipyard Report", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39422 }, ["description"] = "Commander! We have received reports from the shipyard that things are getting serious. Can you head back to Lunarfall and check in with Merreck? Every ship we build gives us another advantage over Gul'dan's new Horde.", ["objectivesText"] = "Return to your shipyard in Lunarfall.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90309, ["x"] = 0.585, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 534, 539 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 38445 }, ["nextQuests"] = { 39056 } },
[39423] = { ["id"] = 39423, ["name"] = "Shipyard Report", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 39423 }, ["description"] = "Commander! We have received reports from the shipyard that things are getting serious. Can you head back to Frostwall and check in with Rolosh? Every ship we build gives us another advantage over Gul'dan's new Horde.", ["objectivesText"] = "Return to your shipyard in Frostwall.", ["rewardGold"] = 17630, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 90481, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 37935 }, ["nextQuests"] = { 39243 } },
[39424] = { ["id"] = 39424, ["name"] = "Everything!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39424 }, ["objectivesText"] = "Feltotem vanquished Felshard shattered Trap disabled", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 63862, 63863, 63864, 142054, 147467, 206974 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Feltotem vanquished", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Felshard shattered", ["amount"] = 17, ["type"] = 2, ["objectID"] = 243539, ["orderIndex"] = 2 }, { ["text"] = "Trap disabled", ["amount"] = 13, ["type"] = 0, ["objectID"] = 96361, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[39425] = { ["id"] = 39425, ["name"] = "Stonedark Crystal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now. I'm sure one of the Feltotem has it. If you find it, please return it to me.", ["objectivesText"] = "Find Navarrogg 's Stonedark Focus . Progress: I have power over the earth without my crystal, but my power is much greater with it than without.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128343 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39381 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39426] = { ["id"] = 39426, ["name"] = "Blood Debt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive. Torok and his Bloodtotem will suffer for what they have done to us. Let's pay them a visit before they can mount an attack against the cave of my people.", ["objectivesText"] = "Defeat Torok Bloodtotem at Torok's Bluff. Progress: Drogbar are not violent by nature, despite our size. But the Bloodtotem crossed us, and they pay the debt in blood.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133114, 133115, 133116, 133117, 133118, 133119, 133120, 133121, 133122, 133124, 246937, 257722 }, ["rewardChoices"] = { 133114, 133115, 133116, 133117, 133118, 133119, 133120, 133121, 133122, 133124 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 95421, ["questType"] = "standard", ["sourceQuests"] = { 39391, 39425, 39588 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39427] = { ["id"] = 39427, ["name"] = "The Eagle Spirit's Blessing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39427, 40385, 41542 }, ["description"] = "The spear is linked to a spirit called Ohn'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge. If you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.", ["objectivesText"] = "Receive the Eagle Spirit's blessing at Spiritwatch Point in Highmountain. Progress: We've done it!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["x"] = 0.71, ["y"] = 0.5, ["mapID"] = 627, ["npcID"] = 104382 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 110821, ["x"] = 0.599, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questGiverID"] = 104382, ["questType"] = "standard", ["sourceQuests"] = { 41542 }, ["questLines"] = { { ["id"] = 220, ["name"] = "Talonclaw", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 220, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39429] = { ["id"] = 39429, ["name"] = "Assaulting the Haglands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["description"] = "Proceed on foot into the Haglands and slay any harpies you find. Quell their numbers! We will provide air support and force your prey to the ground where you can deal with them. Show these witches the fury of your... well... your \"you.\"", ["objectivesText"] = "Slay 8 Crawliac Harpies and 6 Skywhisker Loyalists in the Haglands. Progress: It has been many years since we have had to enter the Haglands in force.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38910 }, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39430] = { ["id"] = 39430, ["name"] = "Flasking for a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39334 }, ["description"] = "You know, this mixing flask didn't suffer terrible damage. I'm positive it can just be repaired. I'm no expert in glass repair, but I've heard of someone who is--a tauren by the name of Barm Stonebreaker . He's a smith by trade, but those who know him say he was born to work glass. Those tauren don't work for free, so you may be in for some work yourself.", ["objectivesText"] = "Seek out Barm Stonebreaker at the Ironhorn Enclave in Highmountain. Progress: You're looking for help? I hope you have something to offer my people in return, <race>.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128515, 136673, 136674, 136675 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39332 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[39431] = { ["id"] = 39431, ["name"] = "Mending the Filter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39337, 39338, 44112 }, ["description"] = "Bringing back the cloth in such a manner would not be beneficial to Deucus. Perhaps there's a tailor here in Val'sharah who'd be willing to mend it for you. The priestess who helped you earlier may know of such a person.", ["objectivesText"] = "Try to find the whereabouts of a tailor in Val'sharah who can help you mend the silk.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128517 }, ["starts"] = { { ["x"] = 0.542, ["y"] = 0.547, ["mapID"] = 641, ["objectID"] = 249211 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.704667, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39337 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39432] = { ["id"] = 39432, ["name"] = "Unknowable Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39432 }, ["description"] = "The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.", ["objectivesText"] = "Collect a Fel-Corrupted Apexis Fragment from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle . Progress: This is simply the beginning of what you must do to save what remains of the Arakkoa.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128346 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
[39433] = { ["id"] = 39433, ["name"] = "Unseen Influence", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39433 }, ["description"] = "The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.", ["objectivesText"] = "Collect 10 Fel-Corrupted Apexis Fragments from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle . Progress: I fear even your help may not be enough to avert the doom of the Arakkoa.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 93730, 119093, 124093, 124094, 124095, 124099, 128315, 128346, 128502, 128503 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 95424, ["x"] = 0.591, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.591, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "group" },
