[39437] = { ["id"] = 39437, ["name"] = "Deep in the Cavern", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["description"] = "We're getting tired of those murlocs. They skitter around the cavern like they own it. They stole some of our most precious relics and got their fishy fins all over them. Kill a few of them so they know they don't run things around here.", ["objectivesText"] = "Slay 8 murlocs in Stonedark Cavern. Progress: Slippery little critters, aren't they?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.616, ["mapID"] = 659, ["npcID"] = 95799 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.616, ["mapID"] = 659, ["npcID"] = 95799 } }, ["coords"] = { ["mapID"] = 659, ["x"] = 0.523, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 95799, ["questTurnInID"] = 95799, ["questType"] = "standard", ["sourceQuests"] = { 39440 }, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659 },
[39438] = { ["id"] = 39438, ["name"] = "Guhruhlruhlruh", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["description"] = "The murlocs are usually pretty scared of us, but some bigger one led them into our cavern and they're getting too brave. Kill their leader. I think its name is something like \" Guhruhlruhlruh .\"", ["objectivesText"] = "Defeat Guhruhlruhlruh . Progress: Can you pronounce murloc names? I never can.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 130295, 130296, 130297, 130298, 130313, 130314, 130315, 130316 }, ["rewardChoices"] = { 130295, 130296, 130297, 130298, 130313, 130314, 130315, 130316 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.616, ["mapID"] = 659, ["npcID"] = 95799 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.616, ["mapID"] = 659, ["npcID"] = 95799 } }, ["coords"] = { ["mapID"] = 659, ["x"] = 0.523, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 95799, ["questTurnInID"] = 95799, ["questType"] = "standard", ["sourceQuests"] = { 39440 }, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659 },
[39439] = { ["id"] = 39439, ["name"] = "Stonedark Relics", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["series"] = { 39440 }, ["description"] = "The murlocs managed to steal some of our sacred relics and carry them down into the lower cavern. While we warm up, do you think you could go find them?", ["objectivesText"] = "Recover the Chain of Resistance, Wheel of Fortitude , and Rod of Bearing . Progress: We have possessed these relics for generations until the murlocs put their fishy flippers on them.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128697, 128703, 128704 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.616, ["mapID"] = 659, ["npcID"] = 95799 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.616, ["mapID"] = 659, ["npcID"] = 95799 } }, ["coords"] = { ["mapID"] = 659, ["x"] = 0.523, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 95799, ["questTurnInID"] = 95799, ["questType"] = "standard", ["sourceQuests"] = { 39440 }, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659 },
[39440] = { ["id"] = 39440, ["name"] = "You Lift, Brul?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["series"] = { 39439 }, ["description"] = "Do you even lift? If you can carry these weights to the statue of Liftbrul and back, maybe we can talk.", ["objectivesText"] = "Carry the weights to the statue of Liftbrul and return to Damrul the Stronk . Progress: Those arms fallin' off?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.515, ["y"] = 0.623, ["mapID"] = 659, ["npcID"] = 95799 } }, ["ends"] = { { ["x"] = 0.515, ["y"] = 0.623, ["mapID"] = 659, ["npcID"] = 95799 } }, ["coords"] = { ["mapID"] = 659, ["x"] = 0.515, ["y"] = 0.623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 95799, ["questTurnInID"] = 95799, ["questType"] = "standard", ["sourceQuests"] = { 40229 }, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659 },
