[39445] = { ["id"] = 39445, ["name"] = "Assault on the Fel Forge", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["storyline"] = { 39445 }, ["description"] = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan. A strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", ["objectivesText"] = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", ["rewardGold"] = 929400, ["rewardXP"] = 1365, ["starts"] = { { ["x"] = 0.5, ["y"] = 0.44, ["mapID"] = 534 } }, ["ends"] = { { ["x"] = 0.5, ["y"] = 0.44, ["mapID"] = 534 } }, ["coords"] = { ["mapID"] = 534, ["x"] = 0.5, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6723 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Iron Horde Forces Thwarted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } } },
