[39455] = { ["id"] = 39455, ["name"] = "Cave of the Blood Trial", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "All Bloodtotem and distinguished guests must go through a trial of blood in the cavern beneath this outpost. I hope it's a good sign that they wish you to participate in this rite of passage. You will need to show proof of your deeds, defeat a Warmonger in single combat, then perform sacrifice at an altar deep in the cavern.", ["objectivesText"] = "Place the Witch of the Wood's carcass on the altar and defeat a Warmonger in single combat. Progress: Are you afraid of the dark?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 95256, ["questType"] = "standard", ["sourceQuests"] = { 39374 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 653 },
[39456] = { ["id"] = 39456, ["name"] = "Unexpected Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 750, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "You have gained my trust. Not all drogbar are as violent as the savages led by Dargrul the Underking, nor are all tauren as bloodthirsty as the Bloodtotem. You may tell Mayla Highmountain that she has our support. The cavern we call home is yours to explore freely as well, <name>.", ["objectivesText"] = "Speak with Mayla Highmountain at Thunder Totem. Progress: Has Torok agreed to join us?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140336, 141395 }, ["starts"] = { { ["x"] = 0.396, ["y"] = 0.538, ["mapID"] = 659, ["npcID"] = 95392 } }, ["ends"] = { { ["x"] = 0.396, ["y"] = 0.538, ["mapID"] = 659, ["npcID"] = 95392 } }, ["coords"] = { ["mapID"] = 659, ["x"] = 0.396, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 95392, ["questTurnInID"] = 95392, ["questType"] = "standard", ["sourceQuests"] = { 40229 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750 },
