[39487] = { ["id"] = 39487, ["name"] = "Crystal Fury", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39488, 39489, 39498, 39661, 42104 }, ["description"] = "A drogbar stonecaster known as Gelmogg entered our sacred water caverns and aims to draw its power into himself. We must destroy him before he gets too powerful. He is in the upper caverns.", ["objectivesText"] = "Slay Gelmogg . Progress: The drogbar used to control only earthen magic, but it seems they've found a way to draw power from other sources.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133070, 133071, 133073, 133074, 133075, 133076, 133077, 133079, 133081, 133082, 133084, 133085, 133086, 133087, 133088, 133090, 246937, 264477 }, ["rewardChoices"] = { 133070, 133071, 133073, 133074, 133075, 133076, 133077, 133079, 133081, 133082, 133084, 133085, 133086, 133087, 133088, 133090 }, ["starts"] = { { ["npcID"] = 96038 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 96038, ["questType"] = "standard", ["sourceQuests"] = { 39488, 39489 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39488] = { ["id"] = 39488, ["name"] = "Balance of Elements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39487, 39489, 39498, 39661, 42104 }, ["description"] = "The drogbar place their foul crystals in our cave to absorb the magic within, and then they collect them when they are saturated with power. We must recover the crystals so the magic might dissipate and be suffused back into the waters, or else the drogbar will find ways to corrupt the magic to their own purposes.", ["objectivesText"] = "Recover 10 Empowered Crystals . Progress: I believe the drogbar are learning stronger magic now that they have possession of the Hammer of Khaz'goroth.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128393 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 96520, ["questType"] = "standard", ["sourceQuests"] = { 39661 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39489] = { ["id"] = 39489, ["name"] = "Invading Spelunkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39487, 39488, 39498, 39661, 42104 }, ["description"] = "The drogbar and their earthen furies have overrun the cavern. They're perverting the magic within and destroying the elementals that have forever dwelled in this place. Let's work together to remove them from this sacred cave.", ["objectivesText"] = "Slay 7 Drogbar Manathirsters or Violent Crageaters . Progress: We must cleanse the cavern of the drogbar.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 96520, ["questType"] = "standard", ["sourceQuests"] = { 39661 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39490] = { ["id"] = 39490, ["name"] = "Infestation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["description"] = "Those bugs are destroying our crops and attack any of us who get near them. Would you exterminate some of those vile creatures?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 95191, ["x"] = 0.436, ["y"] = 0.598, ["mapID"] = 650 } }, ["ends"] = { { ["npcID"] = 95191, ["x"] = 0.436, ["y"] = 0.598, ["mapID"] = 650 } }, ["coords"] = { ["x"] = 0.436, ["y"] = 0.598, ["source"] = "quest_giver", ["mapID"] = 650 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["sourceQuests"] = { 38911 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } } },
[39491] = { ["id"] = 39491, ["name"] = "Ormgul the Pestilent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 38911, 39316, 39496, 39733 }, ["description"] = "We've lived at peace with the drogbar for years--our tribe even more than the others. But we were betrayed in our last trade with them at Riverbend. They usually supply us with potent alchemy to prevent insects from infesting our fields. This time, led by Ormgul, they have attacked the crops that sustain us all. Ormgul the Pestilent is the one who brought the infection to our farmland. Destroy him, and bring me whatever he uses to attract the bugs to our land.", ["objectivesText"] = "Slay Ormgul the Pestilent and acquire his Bug Sprayer . Progress: The Rivermane are a peaceful tribe. We provide the others with food and healing in exchange for protection and equipment. When pressed, however, I am willing to put my magic to more violent use.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121656, 121657, 121658, 121659, 121727, 121729, 121731, 128397 }, ["rewardChoices"] = { 121656, 121657, 121658, 121659, 121727, 121729, 121731 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38911 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, [