[39495] = { ["id"] = 39495, ["name"] = "Hidden No More", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39515, 39516, 39663 }, ["description"] = "Now that you've uncovered the demons, I can sense them, too. Specifically, I sense a very powerful fel lord deeper in the cave. You need to grab his power while you still can. If you can deal with their leader, we will take care of the rest of his forces in that cave.", ["objectivesText"] = "Kill Fel Lord Caza and take his fel power.", ["rewardGold"] = 365520, ["rewardXP"] = 1430, ["rewardItems"] = { 128946, 201989 }, ["starts"] = { { ["x"] = 0.64, ["y"] = 0.523, ["mapID"] = 672, ["npcID"] = 96436 } }, ["ends"] = { { ["x"] = 0.64, ["y"] = 0.523, ["mapID"] = 672, ["npcID"] = 96436 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.64, ["y"] = 0.523 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 96436, ["questTurnInID"] = 96436, ["questType"] = "standard", ["sourceQuests"] = { 39262 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[39496] = { ["id"] = 39496, ["name"] = "The Flow of the River", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 38911, 39316, 39491, 39733 }, ["description"] = "We can leave Farmer Maya in charge of the farmland now that the greatest threat has been reduced. But we aren't out of hot water just yet, <name>. The fisheries are just as important as our fields, and they are in even greater danger than the farm if what Angler Creel says is true.", ["objectivesText"] = "Meet with Angler Creel in Whitewater Wash.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 245409 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39272, 39490, 39491 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39498] = { ["id"] = 39498, ["name"] = "High Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 39277, 39487, 39488, 39489, 39661, 42104 }, ["description"] = "Riverbend! Is that what the Underking said? That is my home and the place where we store our winter supplies. We must make it there at all speed and warn them. Meet me there.", ["objectivesText"] = "Speak with Jale Rivermane at Riverbend.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 59776, 59777, 59778, 141396 }, ["starts"] = { { ["npcID"] = 96038 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97662, ["x"] = 0.484, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 96038, ["questType"] = "standard", ["sourceQuests"] = { 39487 }, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39499] = { ["id"] = 39499, ["name"] = "Well of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["storyline"] = { 39499 }, ["description"] = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", ["objectivesText"] = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Normal difficulty. Progress: Did you manage to find any of those Soul Remnants I mentioned?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 128416 }, ["starts"] = { { ["npcID"] = 95659 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questGiverID"] = 95659, ["questType"] = "raid" },
