[39502] = { ["id"] = 39502, ["name"] = "The Fel Spire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["storyline"] = { 39502 }, ["description"] = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", ["objectivesText"] = "Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Normal difficulty. Progress: Have you been to the top of the Citadel so that I can send you to the top of the Citadel?", ["rewardGold"] = 339600, ["rewardXP"] = 1365, ["rewardItems"] = { 128419 }, ["starts"] = { { ["npcID"] = 95659 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questGiverID"] = 95659, ["questType"] = "raid", ["sourceQuests"] = { 39499 } },
