[39509] = { ["id"] = 39509, ["name"] = "Bloodied Blades of Zeth'Gol", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39509 }, ["description"] = "Them Bleeding Hollow orcs do blood magic - like voodoo but it hurt more. They cut their own flesh. Most of 'em carry curved ritual blades for carvin' themselves up. Bring me them blades, commander. We can turn their power against 'em.", ["objectivesText"] = "Collect 25 Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth'Gol. Progress: Watch your back in Bleeding Hollow lands. They fight dirty. 'Course, we fight dirtier.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128428 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39510] = { ["id"] = 39510, ["name"] = "A Little Wetwork", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39510 }, ["description"] = "What be left of the Iron Horde is comin' to Tanaan through Ironhold Harbor. If we knew who was comin' and when, we could use our shipyard to cause some chaos. Go to Ironhold Harbor and fish up some intelligence!", ["objectivesText"] = "Collect 15 Iron Horde Naval Manifests from forces in Ironhold Harbor. Progress: Whatcha learn for us, commander?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128429 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39511] = { ["id"] = 39511, ["name"] = "Blood of Fallen Brothers", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39511 }, ["description"] = "Orcs that drink Gul'dan's poison turn into fel beasts. Soulless savages. Lady Liadrin an' the Blood Knights think maybe there be a way back. They be wantin' samples of blood from freshly turned orcs. Get their blood, <name>! You be findin' fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden is where you find the most.", ["objectivesText"] = "Collect 20 Vials of Fel Blood from fel orcs throughout Tanaan Jungle . Progress: You bleed 'em dry, commander?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128431 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39512] = { ["id"] = 39512, ["name"] = "Secrets of the Shadow Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39512 }, ["description"] = "Gul'dan be growin' his Shadow Council like a spider spin a web. But some of this new blood, they not so smart. They write down the secrets but don't burn 'em. Catch his minions out in the open and bring their secrets back to me! You find them workin' with the arakkoa in da Ruins of Kra'nak or atop the Throne of Kil'jaeden.", ["objectivesText"] = "Collect 20 Shadow Council Missives from shadow council representatives in the Ruins of Kra'nak or the Throne of Kil'jaeden. Progress: You find anything, commander?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128432 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39513] = { ["id"] = 39513, ["name"] = "Disarming Sha'naar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39513 }, ["description"] = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals used to channel their magics. Now demons be lootin' the place. We gotta keep those crystals out of demonic hands, commander! Attack the mines behind the temple and grab them crystals.", ["objectivesText"] = "Collect 8 Unrefined Draenic Crystals from the mines located within the Temple of Sha'naar in Tanaan Jungle . Progress: What you find up there, commander?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128433 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39514] = { ["id"] = 39514, ["name"] = "Harnessing Their Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39514 }, ["description"] = "Ol' Grommash Hellscream found a way to weaponize the gronn. Vol'jin wants to know how. Travel to the Iron Front and kill one of them big beasties, then bring back its war harness. You might be needin' help.", ["objectivesText"] = "Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle . Progress: Did you break one?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128434 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39515] = { ["id"] = 39515, ["name"] = "Vengeance Will Be Mine!", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39495, 39516, 39663 }, ["description"] = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be. Quickly, <name>, teach us what you have learned.", ["objectivesText"] = "Teach the Vengeance specialization to your assembled demon hunters. Progress: We await your instruction, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["starts"] = { { ["x"] = 0.605, ["y"] = 0.447, ["mapID"] = 672, ["npcID"] = 93127 } }, ["ends"] = { { ["x"] = 0.605, ["y"] = 0.447, ["mapID"] = 672, ["npcID"] = 93127 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.605, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 93127, ["questTurnInID"] = 93127, ["questType"] = "standard", ["sourceQuests"] = { 40051 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
