[39519] = { ["id"] = 39519, ["name"] = "Demonslayer of Tanaan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39519 }, ["description"] = "Look to the north, <class>. The sky is turning a sickly green. Gul'dan's summoning portals are not yet at full strength, but already the stench of demon is on the wind. Slay them, <name>. Destroy as many beasts as you can before they find a way to Azeroth. The Temple of Sha'naar is infested, as is the Throne of Kil'jaeden, although you may find others wandering about the jungle.", ["objectivesText"] = "Slay 20 demons in Tanaan Jungle . Progress: How many demons were slain by your capable hands?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 824, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39526] = { ["id"] = 39526, ["name"] = "Pressing the Attack", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39526 }, ["description"] = "We got Gul'dan's minions on the run, commander! If you be feelin' it, we should put some pressure on some of his other strongholds as well.", ["objectivesText"] = "Complete 2 bonus objective areas within Tanaan Jungle . Progress: How goes the fight?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 }, { ["id"] = 824, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96014, ["x"] = 0.616, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39529] = { ["id"] = 39529, ["name"] = "Tooth and Claw", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39529 }, ["description"] = "Beyond the meager shelter of these fortress walls, the jungle closes in. Can you feel it? That is the untamed wilderness, <class>, calling forth our primal instincts. There is no better way to feel alive than to court death. Join me in the hunt, <name>! Collect teeth from the wild beasts. The ravagers in Thornmire, the raptors in Zorammarsh - even the sea creatures along the strand and the little podling plants themselves all have teeth. Bring them to me!", ["objectivesText"] = "Collect 100 Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle . Progress: I trust the hunt goes well?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 124099, 128438, 194369 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39531] = { ["id"] = 39531, ["name"] = "7.0 Highmountain - Treasure 00x - Steamy Romance Novel", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39532] = { ["id"] = 39532, ["name"] = "Bringing Down the Iron Horde", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39532 }, ["description"] = "Ever since the fall of Blackrock Foundry, Gul'dan has been turning the Iron Horde into... something worse. The orcs who once flocked to Grommash's banner, through either fear or thirst for revenge, are now embracing the fel. Wade into the battlefields of Tanaan and lay waste to Gul'dan's forces. Orc or fel orc makes no difference. Gut what remains of the Iron Horde!", ["objectivesText"] = "Slay 25 Iron Horde orcs in Tanaan Jungle . Progress: Feel no remorse for the fallen, <name>. They made their choice.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 824, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 93396, ["x"] = 0.596, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39533] = { ["id"] = 39533, ["name"] = "Nogginclobber Arena", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39565] = { ["id"] = 39565, ["name"] = "Rumble in the Jungle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39565 }, ["description"] = "Dem fancy cat-men gotta be shown who is da boss 'round dese parts. Kill all their champions, and ya will earn da respect of all creatures in da jungle. Y'gonna need dese totems to draw dem out.", ["objectivesText"] = "Defeat the three arena champions of Fangri'la. Progress: No lie mon - if I'd had money on you coming back in one piece, I'd be out that money right now.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 46725, 124093, 124094, 124095, 124099, 128346, 137663 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 92805, ["x"] = 0.552, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 92805, ["x"] = 0.552, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39566] = { ["id"] = 39566, ["name"] = "The Search for Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39328, 39329, 39330, 39390 }, ["description"] = "While you were out gallivanting, did you notice any lost relics around Azsuna? My sources tell me there are treasures to be found. These rumors merit investigation!", ["objectivesText"] = "Look for ancient relics on the shoreline of Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39326 }, ["nextQuests"] = { 39390 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39567] = { ["id"] = 39567, ["name"] = "Bloodied Blades of Zeth'Gol", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39567 }, ["description"] = "The Bleeding Hollow clan is infamous for their blood rituals. The brutes carve sigils into their flesh and create potions from the blood of their strongest warriors. The curved ceremonial blades they use have a power all their own. Gather some of these for me. We will deprive them of these weapons and learn something about our enemy at the same time.", ["objectivesText"] = "Collect 25 Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth'Gol. Progress: We draenei have had little contact with the Bleeding Hollow before this war. They were an insular clan living in one of the most hostile parts of Draenor.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128428 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39568] = { ["id"] = 39568, ["name"] = "A Little Wetwork", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39568 }, ["description"] = "The shattered remnants of the Iron Horde pour into Tanaan through Ironhold Harbor. If we knew more about their fleet we could dispatch countermeasures from your shipyard in Shadowmoon. Perhaps you could gather some naval intelligence for our cause?", ["objectivesText"] = "Collect 15 Iron Horde Naval Manifests from forces in Ironhold Harbor. Progress: The Prophet said it was always wise to know one's enemy before engaging.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128429 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39569] = { ["id"] = 39569, ["name"] = "Breaking Their Fel Bonds", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39569 }, ["description"] = "Gul'dan's fel poison turns already ferocious orcs into hateful, vicious creatures with no soul. But were he here to guide us, Prophet Velen wouldn't give up on the whole race. If you could find samples of their blood, maybe we can reverse the process? You'll find fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden are the most densely populated.", ["objectivesText"] = "Collect 20 Vials of Fel Blood from fel orcs throughout Tanaan Jungle . Progress: Were you able to secure some blood samples? I will not inquire as to your methods, commander.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128431 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39570] = { ["id"] = 39570, ["name"] = "Secrets of the Shadow Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39570 }, ["description"] = "Gul'dan has been building a spy network for himself - the so-called \"Shadow Council\". As they struggle to control Tanaan, the Shadow Council has grown careless. Their members are out in the open, recruiting arakkoa at the Ruins of Kra'nak or summoning demons at the Throne of Kil'jaeden. Find members of the Shadow Council and acquire any intelligence they were foolish enough not to destroy!", ["objectivesText"] = "Collect 20 Shadow Council Missives from Shadow Council representatives in the Ruins of Kra'nak or the Throne of Kil'jaeden. Progress: What have you learned?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128432 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39571] = { ["id"] = 39571, ["name"] = "Disarming Sha'naar", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39571 }, ["description"] = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals to power our arcane devices. Sadly, the temple is lost to us - we have been betrayed by the Sargerei. <name>, it is imperative that you venture into those mines and secure those crystals before the Sargerei use them in their demonic rituals. If you must kill our former brothers and sisters, so be it.", ["objectivesText"] = "Collect 8 Unrefined Draenic Crystals from the mines located within the Temple of Sha'naar in Tanaan Jungle . Progress: That temple was once a place of peace and solitude. I fear it is forever corupted.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128433 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39572] = { ["id"] = 39572, ["name"] = "Moozy's Adventure", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39323, 39572, 42590 }, ["series"] = { 39323 }, ["description"] = "<Moozy is floating down the river and must be reunited with his mother.>", ["objectivesText"] = "Bring Moozy to Sella Waterwise at Whitewater Wash.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 62913, 121724 }, ["rewardChoices"] = { 121724 }, ["starts"] = { { ["x"] = 0.375, ["y"] = 0.642, ["mapID"] = 650, ["npcID"] = 95130 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96084, ["x"] = 0.4, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 95130, ["questType"] = "standard", ["sourceQuests"] = { 39323 }, ["questLines"] = { { ["id"] = 5914, ["name"] = "Moozy's Family Reunion", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39573] = { ["id"] = 39573, ["name"] = "Harnessing Their Power", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39573 }, ["description"] = "We have always believed that the primal creatures of Draenor could not be tamed. And yet, the Iron Horde found a way to weaponize the gronn. It would be to our advantage to learn how. Venture to the Iron Front, slay a Wargronn, and retrieve its harness. You may want to find help.", ["objectivesText"] = "Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle . Progress: Exarch Maladaar reports that the battlefield is in chaos. Were you able to persevere?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128434 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39574] = { ["id"] = 39574, ["name"] = "Pressing the Attack", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39574 }, ["description"] = "Gul'dan's minions are on the run, commander! If you have the strength, now would be an opportune time to press forward and assault some of his other strongholds.", ["objectivesText"] = "Complete 2 bonus objective areas within Tanaan Jungle . Progress: Be wary of the jungle, commander.", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 }, { ["id"] = 824, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39575] = { ["id"] = 39575, ["name"] = "The Path of Huln", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Armies are vital to the success of a war. But so are symbols. For our people, few things make for a better symbol than the blessings of our most eldest ancestors. Mayla must walk the Path of Huln. The path is dangerous, and she may only bring two people with her: a spiritwalker to guide her and a champion to protect her. Will you be the champion?", ["objectivesText"] = "Follow Spiritwalker Ebonhorn on the Path of Huln.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94571, ["x"] = 0.448, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94571, ["x"] = 0.448, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 94571, ["questType"] = "standard", ["sourceQuests"] = { 38916 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657 },
[39576] = { ["id"] = 39576, ["name"] = "Echoes of Deathwing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39576 }, ["objectivesText"] = "Explore the Vault", ["rewardGold"] = 567400, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 200 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Explore the Vault", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657 },
[39577] = { ["id"] = 39577, ["name"] = "An Ancient Secret", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 657, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Before Mayla may be pronounced High Chieftain, there is one more vision she must see. I wish to show you as well. It is an ancient secret, handed down along the Highmountain bloodline. I ask for your discretion in keeping it that way.", ["objectivesText"] = "Assist Spiritwalker Ebonhorn in Neltharion's Vault.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.49, ["y"] = 0.725, ["mapID"] = 657, ["npcID"] = 99190 } }, ["ends"] = { { ["x"] = 0.49, ["y"] = 0.725, ["mapID"] = 657, ["npcID"] = 99190 } }, ["coords"] = { ["mapID"] = 657, ["x"] = 0.49, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 99190, ["questTurnInID"] = 99190, ["questType"] = "standard", ["sourceQuests"] = { 39578 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657 },
[39578] = { ["id"] = 39578, ["name"] = "Titanic Showdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 657, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The tale of Huln did not end with him acquiring the Hammer of Khaz'goroth. No. For that part, we must venture deeper into this cavern. A final brazier awaits us ahead. Come, let us see what happened next.", ["objectivesText"] = "Find and aid the spirit of Huln Highmountain .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121660, 121661, 121662, 121663, 130312 }, ["rewardChoices"] = { 121660, 121661, 121662, 121663, 130312 }, ["starts"] = { { ["x"] = 0.493, ["y"] = 0.541, ["mapID"] = 657, ["npcID"] = 108069 } }, ["ends"] = { { ["x"] = 0.493, ["y"] = 0.541, ["mapID"] = 657, ["npcID"] = 108069 } }, ["coords"] = { ["mapID"] = 657, ["x"] = 0.493, ["y"] = 0.541 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 108069, ["questTurnInID"] = 108069, ["questType"] = "standard", ["sourceQuests"] = { 40219 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657 },
[39579] = { ["id"] = 39579, ["name"] = "The Backdoor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "This will take Mayla some time to adjust to. That being said, we should return to Thunder Totem. Just south of here is a tunnel that should take us through the old drogbar slave enclave and then to an opening beyond. We keep a small Skyhorn outpost there to watch and ensure nothing enters or leaves this vault without us knowing about it. They should be able to fly us back.", ["objectivesText"] = "Escape the Vault.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 133129, 133136, 133137, 133138, 133139, 133141, 133142, 133143, 133144, 133146, 245456, 246937 }, ["rewardChoices"] = { 133129, 133136, 133137, 133138, 133139, 133141, 133142, 133143, 133144, 133146 }, ["starts"] = { { ["x"] = 0.612, ["y"] = 0.72, ["mapID"] = 657, ["npcID"] = 96270 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 108305, ["x"] = 0.474, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 96270, ["questType"] = "standard", ["sourceQuests"] = { 39577 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[39580] = { ["id"] = 39580, ["name"] = "The High Chieftain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "I understand what Ebonhorn has been trying to tell me for a while now. Our people do not need a hammer, we need a leader. One willing to stand against any threat, even if they are terrified to do so. And between you and me, I am definitely terrified, but resolved. Let us return to Thunder Totem and prepare ourselves for war.", ["objectivesText"] = "Speak with Mayla Highmountain at Thunder Totem.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 141397 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 108305, ["x"] = 0.474, ["y"] = 0.846 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 108305, ["x"] = 0.474, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 108305, ["questType"] = "standard", ["sourceQuests"] = { 39579 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 652 },
[39581] = { ["id"] = 39581, ["name"] = "Demonslayer of Tanaan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39581 }, ["description"] = "Demons! Hate 'em! Gul'dan is spinning up more summoning portals with each passing hour. There's only one way to stem the tide, <name>. < Parvink smashes her gauntleted fist against her open palm.> Smash 'em! The Temple of Sha'naar is a good place to start, or head up to the Throne of Kil'jaeden if you're looking for a real challenge.", ["objectivesText"] = "Slay 20 demons in Tanaan Jungle . Progress: < Parvink looks at some hatch marks she scribbled on a scrap of paper.> I'm up to 17 demons killed today. You?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 824, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39582] = { ["id"] = 39582, ["name"] = "Tooth and Claw", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39582 }, ["description"] = "These wimps lugging wood around the jungle keep talking about how dangerous it is. You know, between the ravager den to the south or the raptors that stalk Zorammarsh - hey, even the beach creatures or podlings have teeth! What do you say you and I do a little hunting? Collect teeth from wild beasts. The bigger the beast, the more teeth. Meet me back here and we'll compare our haul!", ["objectivesText"] = "Collect 100 Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle . Progress: Ready to compare notes?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 111987, 124099, 128438, 194369 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39586] = { ["id"] = 39586, ["name"] = "Bringing Down the Iron Horde", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 39586 }, ["description"] = "Ever since we humiliated 'em at Blackrock Foundry, the Iron Horde has been on the run. Gul'dan is converting them all into fel orcs, but I ain't scared. A bloodlusting orc is twice as strong but twice as stupid. Hey! Let's wade into the battlefields of Tanaan and lay waste to as many orcs as we can. Orc or fel orc - doesn't matter to me.", ["objectivesText"] = "Slay 25 Iron Horde orcs in Tanaan Jungle .", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 824, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 96147, ["x"] = 0.578, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard" },
[39588] = { ["id"] = 39588, ["name"] = "They Will Pay With Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The tauren go too far. I did not escape their outpost for fear that they would attack the cave and slaughter my people. It looks like they planned to do it all along. Slay some of the Feltotem. Thin the herd.", ["objectivesText"] = "Slay 10 Feltotem Tauren. Progress: These tauren have always been bloodthirsty. The Highmountain chieftain has barely been able to stop them killing all of us.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39381 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39590] = { ["id"] = 39590, ["name"] = "Ahead of the Game", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38331, 39591, 39595 }, ["description"] = "The watcher Yotnar keeps the vault, and he is a fickle one. Challengers come from far and wide seeking the trials, but the watcher chooses not to see. If you wish to catch his eye, show him you are worth being seen. Some of these challengers await in camps throughout the Valley of the Sword. Bring their heads to Yotnar, so that he may see them, and you.", ["objectivesText"] = "Collect the heads of the Gutspill, Rumblehoof, and Felskorn champions in Valley of the Sword. Progress: An ironic gift you bring me, challenger.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128508, 128509 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 96254, ["questType"] = "standard", ["sourceQuests"] = { 38331 }, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39591] = { ["id"] = 39591, ["name"] = "A Trial of Valor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38331, 39590, 39595 }, ["description"] = "To seek the Aegis of Aggramar, a champion must complete three great trials before riding into glorious battle through the Gates of Valor. Here you will find the knowledge of the trials you must seek out, as well as the first challenge you must face. Above us, adorning the central plateau, you will find the archive for the Trial of Valor. Seek it out, and learn where your path leads.", ["objectivesText"] = "Power up the archive device and view the holographic record for the Trial of Valor in the Terrace of the Watchers.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021, 142533, 142534, 143506, 143510, 143514, 143518, 246936, 249400, 254267, 254579 }, ["starts"] = { { ["x"] = 0.467, ["y"] = 0.444, ["mapID"] = 634, ["objectID"] = 243836 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39590 }, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39592] = { ["id"] = 39592, ["name"] = "A Trial of Will", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Upon the highest point of the plateau above, you will find the archive device for the Trial of Will. Seek it out to learn what awaits you in Thorim's Peak. Be on your guard, outsider. The one called Skovald has left behind many of his army, and they will no doubt be unfriendly.", ["objectivesText"] = "Power up the archive device and view the holographic record for the Trial of Will in the Terrace of the Watchers.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.467, ["y"] = 0.444, ["mapID"] = 634, ["objectID"] = 243836 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39590 }, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39593] = { ["id"] = 39593, ["name"] = "The Shattered Watcher", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "When your adversary - the one called Skovald- completed his first trial, he used his ill-begotten powers to sunder my physical body. I cannot allow a contender to pass through the vault while I remain unwhole. His forces have no doubt scattered my pieces through the plateau which they currently desecrate. Bring them back to me, so that I may properly guide your trial.", ["objectivesText"] = "Collect the pieces of Yotnar's body from the Terrace of the Watchers. Progress: Have you managed to find them all?", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 121560, 128493, 128495, 128496, 128497, 129316 }, ["rewardChoices"] = { 121560, 129316 }, ["starts"] = { { ["x"] = 0.467, ["y"] = 0.444, ["mapID"] = 634, ["objectID"] = 243836 } }, ["ends"] = { { ["x"] = 0.467, ["y"] = 0.444, ["mapID"] = 634, ["objectID"] = 243836 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.467, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39590 }, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39594] = { ["id"] = 39594, ["name"] = "A Trial of Might", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "I owe you my gratitude for helping make me whole again, outsider. It is clear that you are worthy to take on the trials. Go now into the vault. There you will find the archive for the first trial you must undertake. I will meet you inside.", ["objectivesText"] = "Activate the archive device to learn about the Trial of Might.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96258, ["x"] = 0.464, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39591, 39592, 39593 }, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39595] = { ["id"] = 39595, ["name"] = "Blood and Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39595 }, ["series"] = { 38331, 39590, 39591 }, ["description"] = "The challengers gathered in the Valley of the Sword have brought with them offerings to the watchers of the vault. It might be a good idea to take some of these offerings with you to help in appeasing Yotnar .", ["objectivesText"] = "Collect 7 Challenger's Tributes from Valley of the Sword. Progress: What is this you bring? You honor me, outsider.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128511, 128512 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 }, { ["mapID"] = 634, ["npcID"] = 96258, ["x"] = 0.464, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 128512 } },
