[39601] = { ["id"] = 39601, ["name"] = "I Sunk Your Battleship", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["description"] = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde. We have heard reports from Tanaan that a new Alliance faction can supply us with the plans to build battleships. Head out there as soon as you can and investigate!", ["objectivesText"] = "Meet Vindicator Krethos at Lion's Watch in Tanaan Jungle. Progress: Any luck with those battleship plans?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127269, 128373, 128492 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 90974, ["x"] = 0.584, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 534, 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39665 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 534 },
[39602] = { ["id"] = 39602, ["name"] = "Where's Lyndras: Sewer Sleuthing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39605, 39667 }, ["description"] = "Linzy said that Lyndras escaped down into the sewers of Dalaran. Surely there must be a clue down there as to his whereabouts. Hopefully he hasn't caused any more commotion amongst the citizens of Dalaran.", ["objectivesText"] = "Search the sewers for clues as to where Lyndras has gone.", ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["ends"] = { { ["x"] = 0.352, ["y"] = 0.342, ["mapID"] = 627, ["npcID"] = 93542 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.352, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93542, ["questTurnInID"] = 93542, ["questType"] = "standard", ["sourceQuests"] = { 38964 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 20, ["flags"] = 0 } } },
