[39606] = { ["id"] = 39606, ["name"] = "Treasures of Deathwing", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39606 }, ["description"] = "Neltharion's Vault? Well why didn't that spiritwalker just say so? When we were jumpin' into the cavern I thought I saw a chamber up high that might have what we are after. Have a look around this place while I see if I can't find a way up.", ["objectivesText"] = "Defend Brann Bronzebeard.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2VignetteID"] = 1413, ["db2VignetteName"] = "Treasures of Deathwing" },
[39614] = { ["id"] = 39614, ["name"] = "Fish Out of Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["description"] = "The drogbar are on a rampage! They're smashing everything they can find and are throwing fish to the shore. Worst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.", ["objectivesText"] = "Return 8 Whitewater Carp to the river. Progress: We used to supply the drogbar with most of their food between our fish and crops. What will the fools eat now?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 245457 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39496 }, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39645] = { ["id"] = 39645, ["name"] = "Calibration Experts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39345, 39346 }, ["description"] = "It will take the cooperation of several highly skilled sorts to calibrate these burettes. Myshalla Streambreeze in Feralas has demonstrated admirable attention to detail. I loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision. And while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.", ["objectivesText"] = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127878, 127915, 128209, 128676 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.328, ["mapID"] = 627, ["npcID"] = 92458 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92458, ["questTurnInID"] = 92458, ["questType"] = "standard", ["sourceQuests"] = { 39333 }, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
