[39648] = { ["id"] = 39648, ["name"] = "Where Are the Children?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 6, ["zoneID"] = 6720, ["storyline"] = { 39648 }, ["description"] = "The children have gone missing! That horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them! Our scouts have spotted him over in Frostfire Ridge .", ["objectivesText"] = "Save 6 Kidnapped Children. Progress: Thank you for all the help! Their families will be so happy to see them.", ["rewardGold"] = 312800, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.44, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 96451, ["questTurnInID"] = 96451, ["questType"] = "standard" },
[39649] = { ["id"] = 39649, ["name"] = "Menacing Grumplings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 6, ["zoneID"] = 6720, ["storyline"] = { 39649 }, ["description"] = "The grumplings are horrid creatures. They're the ones doin' the dirty work for Grumpus. If you're able to remove the threat I'm sure rescuing the children won't be much of a problem.", ["objectivesText"] = "Kill 8 Grumplings . Progress: Well that was fast! Grumpus is gonna have a hard time continuing his work without his minions. Take these. I had them specially crafted to withstand any climate. You never know what you'll run into out here in Draenor!", ["rewardGold"] = 341600, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128632, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.44, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 96451, ["questTurnInID"] = 96451, ["questType"] = "standard" },
[39651] = { ["id"] = 39651, ["name"] = "Grumpus", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 6, ["zoneID"] = 6720, ["storyline"] = { 39651 }, ["description"] = "One of Draenor's oldest stories is the legend of Grumpus . The story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions. But Grumpus is no legend, he's real and he's taken our children! Please, you have to slay him!", ["objectivesText"] = "Slay Grumpus .", ["rewardGold"] = 312800, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675, 144339 }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.44, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 96451, ["questTurnInID"] = 96451, ["questType"] = "group" },
[39652] = { ["id"] = 39652, ["name"] = "Where Dragons Rule", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes. She has gathered our brood at the top of Thorim's Peak to prepare for a counterattack. Would you join us?", ["objectivesText"] = "Speak to Vethir to fly to the top of Thorim's Peak.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132799, 132800, 132802, 132803, 132804, 132805, 132806, 132808, 132810, 132811, 132813, 132814, 132815, 132816, 132817, 132819, 141399 }, ["rewardChoices"] = { 132799, 132800, 132802, 132803, 132804, 132805, 132806, 132808, 132810, 132811, 132813, 132814, 132815, 132816, 132817, 132819 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.816667 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38413, 38414, 40568 }, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] =