[39654] = { ["id"] = 39654, ["name"] = "Odyn and the Valarjar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["series"] = { 38904, 41052, 42814, 42815 }, ["description"] = "Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself. I will take you to Odyn now, follow me.", ["objectivesText"] = "Follow Danica to see Odyn .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.297, ["mapID"] = 695, ["npcID"] = 93823 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.297, ["mapID"] = 695, ["npcID"] = 93823 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.59, ["y"] = 0.297 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 93823, ["questTurnInID"] = 93823, ["questType"] = "standard", ["sourceQuests"] = { 38904, 42815 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[39655] = { ["id"] = 39655, ["name"] = "If At First You Fail, Try Again!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39056, 39404, 39674, 39675, 39676 }, ["description"] = "Looks like that Submarine had a bit more firepower than we thought! They used First Strike to hit us before we even saw it coming. Losing ships is a part of naval battles, Commander. Luckily, we were prepared for this exact sort of situation. Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer. Head back here when the ship is complete, we will have a new mission ready for you.", ["objectivesText"] = "Meet Yanas Seastrike at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission. Progress: Get that replacement Destroyer built?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260 }, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39404 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39656] = { ["id"] = 39656, ["name"] = "Wolf Pack Attack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["series"] = { 39386, 39670 }, ["description"] = "It's time to attack the pack! I've preloaded the hand cannon. All you have to do is point and shoot. The critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders. Happy hunting!", ["objectivesText"] = "Shoot the Critter Hand Cannon near wolf packs so that they scatter, allowing the packleaders to be singled out. Progress: The critter hand cannon is loaded and ready for use! Just aim for one of the packs nearby. The packleaders should be easy to kill once the howlers are distracted.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128651, 131933 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39670 }, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
