[39663] = { ["id"] = 39663, ["name"] = "On Felbat Wings", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39495, 39515, 39516 }, ["description"] = "It is time. We have dealt the Legion's forces a crippling blow from which they will never recover. Quickly, let us mount up and take the fight to Tyranna's command center.", ["objectivesText"] = "Grab a felbat from Illidari Whitemoon and fly up to the Fel Hammer.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["starts"] = { { ["x"] = 0.605, ["y"] = 0.447, ["mapID"] = 672, ["npcID"] = 93127 } }, ["ends"] = { { ["x"] = 0.605, ["y"] = 0.447, ["mapID"] = 672, ["npcID"] = 93127 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.605, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 93127, ["questTurnInID"] = 93127, ["questType"] = "standard", ["sourceQuests"] = { 39515, 39516 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[39665] = { ["id"] = 39665, ["name"] = "A True Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39666 }, ["description"] = "Yes! Those are the blueprints I misplaced when I was fishing last week. These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships. This should let us break the naval blocade and expand our control of the Draenor seas.", ["objectivesText"] = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission. Progress: Get that equipment installed?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128256, 128260, 128264, 128265, 128373 }, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.108 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39666 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39666] = { ["id"] = 39666, ["name"] = "Equipping Our Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259, 39054, 39055, 39056, 39067, 39068, 39082, 39404, 39601, 39655, 39665, 39666 }, ["series"] = { 39665 }, ["description"] = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war. Find Salty Jorren down at the docks, he should be able to help us out.", ["objectivesText"] = "Meet Salty Jorren at the docks. Progress: Yes?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 126900, 127882, 127884, 128260, 128274 }, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 93822, ["x"] = 0.282, ["y"] = 0.111 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 93812, ["x"] = 0.286, ["y"] = 0.108 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.111 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 39655 }, ["questLines"] = { { ["id"] = 140, ["name"] = "Docks Intro and Shipyard Tutorial - Alliance", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 539 },
[39667] = { ["id"] = 39667, ["name"] = "Where's Lyndras: Leyflame Larceny", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605 }, ["description"] = "The guards here must have seen Lyndras come through. The trail of ley dust isn't exactly hard to miss either. Perhaps one of the guards knows what became of Lyndras.", ["objectivesText"] = "Ask the Violet Hold guards about Lyndras.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.562, ["y"] = 0.684, ["mapID"] = 627, ["objectID"] = 243899 } }, ["ends"] = { { ["x"] = 0.562, ["y"] = 0.684, ["mapID"] = 627, ["objectID"] = 243899 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.562, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 39605 }, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[39668] = { ["id"] = 39668, ["name"] = "What Horrible Presents!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Feast of Winter Veil", ["expansion"] = 6, ["zoneID"] = 6720, ["storyline"] = { 39668 }, ["description"] = "That mean old Grumpus has amassed a collection of odd gifts. He's deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable. Take this spirit bomb . Toss it on some of Grumpus's unusual gifts and take them out for good! We're in this together, <name>. Now go and save the spirit of the holiday!", ["objectivesText"] = "Destroy 5 Unusual Gifts . Progress: Wow. Those were some nasty presents. You might want to, uh... wash up. Who knows what those were made of.", ["rewardGold"] = 312800, ["rewardXP"] = 1365, ["rewardItems"] = { 21524, 21525, 34085, 34087, 70923, 108635, 128312, 128314, 128315, 128658, 128659, 128665, 128666, 128667, 128668, 128669, 128670, 128671, 128675 }, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["ends"] = { { ["x"] = 0.44, ["y"] = 0.516, ["mapID"] = 582, ["npcID"] = 96451 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.44, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questGiverID"] = 96451, ["questTurnInID"] = 96451, ["questType"] = "standard" },
[39670] = { ["id"] = 39670, ["name"] = "Critter Scatter Shot", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["series"] = { 39386, 39656 }, ["description"] = "The howlers in these hills travel in packs. Three against one isn't a fight I want to pick. Luckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo... Snatch me some rabbits from the meadow south of here, and I'll let you be the first to try out the hand cannon.", ["objectivesText"] = "Catch rabbits in Sunfrost Glade. Progress: Have you snatched the rabbits yet?", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 128655 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39386 }, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39674] = { ["id"] = 39674, ["name"] = "If At First You Fail, Try Again!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39056, 39404, 39655, 39675, 39676 }, ["description"] = "Looks like that Submarine had a bit more firepower than we thought! They used First Strike to hit us before we even saw it coming. Losing ships is a part of naval battles, Commander. Luckily, we were prepared for this exact sort of situation. Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer. Head back here when the ship is complete, we will have a new mission ready for you.", ["objectivesText"] = "Meet Solog Roark at the dry docks and build another Destroyer. Once the Destroyer is complete, send it on a new mission. Progress: Get that replacement Destroyer built?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39401 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39675] = { ["id"] = 39675, ["name"] = "Equipping Our Fleet", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39056, 39404, 39655, 39674, 39676 }, ["description"] = "Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war. Find Kronk Rustspark down at the docks, he should be able to help us out.", ["objectivesText"] = "Meet Kronk Rustspark at the docks. Progress: Find Kronk?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 128274 }, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94801, ["x"] = 0.4, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39674 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39676] = { ["id"] = 39676, ["name"] = "A True Naval Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 38567, 38568, 38570, 38571, 38572, 38573, 38574, 39236, 39241, 39242, 39243, 39245, 39246, 39401, 39604, 39674, 39675, 39676 }, ["series"] = { 39056, 39404, 39655, 39674, 39675 }, ["description"] = "Yes! Those are the blueprints I misplaced when I was fishing last week. These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships. This should let us break the naval blockade and expand our control of the Draenor seas.", ["objectivesText"] = "Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission. Progress: Get that equipment installed?", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 127882, 128256, 128264, 128265, 128373 }, ["rewardCurrencies"] = { { ["id"] = 1101, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 94801, ["x"] = 0.4, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 94789, ["x"] = 0.418, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard", ["sourceQuests"] = { 39675 }, ["questLines"] = { { ["id"] = 139, ["name"] = "Docks Intro and Shipyard Tutorial - Horde", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 525 },
[39680] = { ["id"] = 39680, ["name"] = "Between the Hammer...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39726, 39729, 44449 }, ["description"] = "<name>, I fear that my spirit will remain bound to this place unless I am made whole again. Long ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled. I need that hammer back if I am to be at peace.", ["objectivesText"] = "Bring Saris' Hammer back to his shop. Progress: Any luck retrieving my hammer?", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 128745, 137680 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39702 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39681] = { ["id"] = 39681, ["name"] = "The Properties of Leystone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38499 }, ["description"] = "I've never seen anything like this \"leystone\" ore. It's light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium. Let's try making something with it. How about a nice pair of gauntlets?", ["objectivesText"] = "Observe Alard as he attempts to work with the leystone ore.", ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.446, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "standard", ["sourceQuests"] = { 38499 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39682] = { ["id"] = 39682, ["name"] = "Grand Theft Felbat", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["series"] = { 38723, 40253 }, ["description"] = "You heard what Maiev said. We need to get out of here. There is an elevator shaft at the far end of these caverns. Let us make our way there.", ["objectivesText"] = "Ride a felbat to the upper vault.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128945, 132243 }, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.728, ["mapID"] = 677, ["npcID"] = 96665 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.728, ["mapID"] = 677, ["npcID"] = 96665 } }, ["coords"] = { ["mapID"] = 677, ["x"] = 0.508, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 96665, ["questTurnInID"] = 96665, ["questType"] = "standard", ["sourceQuests"] = { 38723, 40253 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678 },
[39683] = { ["id"] = 39683, ["name"] = "Forged in Fire", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. Somehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long. The demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining. I believe that person could be you, <name>.", ["objectivesText"] = "Kill Immolanth and take his power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 201989 }, ["starts"] = { { ["x"] = 0.41, ["y"] = 0.471, ["mapID"] = 678, ["npcID"] = 96675 } }, ["ends"] = { { ["x"] = 0.41, ["y"] = 0.471, ["mapID"] = 678, ["npcID"] = 96675 } }, ["coords"] = { ["mapID"] = 678, ["x"] = 0.41, ["y"] = 0.471 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 96675, ["questTurnInID"] = 96675, ["questType"] = "standard", ["sourceQuests"] = { 39682 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678 },
[39684] = { ["id"] = 39684, ["name"] = "Beam Me Up", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "To the east is an intricate prison chamber designed to contain the beholder, Glazer . It began malfunctioning shortly after the breach. You will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer 's impenetrable shield. Hurry. Altruis went ahead to assist the others, but we are losing the fight.", ["objectivesText"] = "Break Glazer 's shield.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 132243 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.474, ["mapID"] = 678, ["npcID"] = 97643 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.474, ["mapID"] = 678, ["npcID"] = 97643 } }, ["coords"] = { ["mapID"] = 678, ["x"] = 0.413, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 97643, ["questTurnInID"] = 97643, ["questType"] = "standard", ["sourceQuests"] = { 39682 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678 },
[39685] = { ["id"] = 39685, ["name"] = "Frozen in Time", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul'dan's forces have breached the walls, it's proving rather... inconvenient. Many of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don't have the means to take it down. However, we might be able to reactivate the room's containment field. Go join up with Kayn. Do whatever it takes to seal that chamber!", ["objectivesText"] = "Activate the Countermeasures in the Vault of Ice.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 127853, 128949, 132243, 133315, 226193, 226194, 232877, 247820, 247821 }, ["rewardChoices"] = { 128949, 133315 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.474, ["mapID"] = 678, ["npcID"] = 97643 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.474, ["mapID"] = 678, ["npcID"] = 97643 } }, ["coords"] = { ["mapID"] = 678, ["x"] = 0.413, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 97643, ["questTurnInID"] = 97643, ["questType"] = "standard", ["sourceQuests"] = { 39682 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678 },
[39686] = { ["id"] = 39686, ["name"] = "All The Way Up", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "Kor'vas went ahead to meet up with Kayn and Altruis. Step onto the elevator when it arrives, and meet them in the Hall of Judgment above.", ["objectivesText"] = "Ride the elevator to the Hall of Judgment.", ["rewardGold"] = 309800, ["rewardXP"] = 145, ["rewardItems"] = { 2411, 12050, 12051, 25470, 25474, 25948, 25949, 25951, 26009, 26023, 26035, 31725, 49927, 52920, 52937, 52965, 61463, 61464, 61465, 66898, 66899, 66900, 66915, 66917, 66921, 81552, 81553, 81554, 81555, 81556, 81557, 81834, 81835, 81836, 81837, 81838, 88384, 90546, 90547, 90622, 112595, 112596, 112597, 112598, 131273, 131835, 132243, 140255, 142054, 153726, 153747, 153773, 153792, 153814, 153830, 153835, 153856, 153859, 153889, 153891, 153892, 153893, 153934, 153944, 153959, 153960, 153961, 153973, 153983, 154005, 154024, 154025, 154035, 154036, 160513, 170514, 170515, 170516, 170517, 170518, 170519, 170520, 170521, 170522, 170523, 170524, 170525, 170526, 170527, 170528, 170529, 170530, 170531, 170532, 170533, 170534, 170535, 170536, 170537, 173340, 173341, 173342, 173343, 175588, 179768, 179887, 180924, 180925, 180926, 180927, 181912, 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 191984, 191986, 191988, 191989, 191990, 191991, 191992, 191994, 191995, 191996, 191998, 191999, 192002, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192015, 192037, 194522, 197943, 198542, 231839, 245707, 245708, 245709, 245710, 247234, 254878 }, ["starts"] = { { ["x"] = 0.411, ["y"] = 0.471, ["mapID"] = 678, ["npcID"] = 96675 } }, ["ends"] = { { ["x"] = 0.411, ["y"] = 0.471, ["mapID"] = 678, ["npcID"] = 96675 } }, ["coords"] = { ["mapID"] = 678, ["x"] = 0.411, ["y"] = 0.471 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 96675, ["questTurnInID"] = 96675, ["questType"] = "standard", ["sourceQuests"] = { 39683, 39684, 39685, 40254 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679 },
[39688] = { ["id"] = 39688, ["name"] = "Between Us and Freedom", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39694, 40253, 40254, 40255, 40373, 95215 }, ["description"] = "The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.", ["objectivesText"] = "Kill Bastillax and take his power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 201989 }, ["starts"] = { { ["x"] = 0.245, ["y"] = 0.562, ["mapID"] = 679, ["npcID"] = 97644 } }, ["ends"] = { { ["x"] = 0.245, ["y"] = 0.562, ["mapID"] = 679, ["npcID"] = 97644 } }, ["coords"] = { ["mapID"] = 679, ["x"] = 0.245, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 97644, ["questTurnInID"] = 97644, ["questType"] = "standard", ["sourceQuests"] = { 40373 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679 },
[39689] = { ["id"] = 39689, ["name"] = "Illidari, We Are Leaving", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39694, 40253, 40254, 40255, 40373, 95215 }, ["description"] = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms. However, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion. I only ask that you come with me. Further instructions await you on the other side.", ["objectivesText"] = "Speak to Archmage Khadgar .", ["rewardXP"] = 145, ["starts"] = { { ["npcID"] = 97978 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 97978, ["questType"] = "standard", ["sourceQuests"] = { 39688, 40255 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677 },
