[39697] = { ["id"] = 39697, ["name"] = "Master vs. Commander", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 525, ["storyline"] = { 39697 }, ["series"] = { 39057 }, ["description"] = "I've been doing a little digging - or whatever you call digging in naval terms. Snorkeling? Gul'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul'dan's hands, it could be catastrophic. Scramble the fleet, <name>! Hunt down his infamous flagship, \"The Master's Call,\" and steal that map before they complete their mission. Hurry!", ["objectivesText"] = "Complete the legendary shipyard missions until you defeat the Master's Call and acquire a Draenic Sea Chart . Progress: I hope the Master's Call hasn't sent too many of your ships to the bottom of the sea...?", ["rewardGold"] = 169800, ["rewardXP"] = 1365, ["rewardItems"] = { 128693 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 92213, ["x"] = 0.408, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7078 } }, ["questType"] = "standard", ["sourceQuests"] = { 39057 } },
[39698] = { ["id"] = 39698, ["name"] = "Making the Rounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 1, ["storyline"] = { 38307, 39698, 39801, 44701 }, ["series"] = { 39801 }, ["description"] = "As you can see, we have spared no expense in showing our support of your great quest. Final preparations are being made - come, walk with me.", ["objectivesText"] = "Follow Lady Sylvanas Windrunner and prepare her ship to set sail. Progress: As soon as preparations are complete, we set out for Stormheim .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 96686, ["x"] = 0.614, ["y"] = 0.093 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 96686, ["x"] = 0.614, ["y"] = 0.093 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.093 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 38307 }, ["questLines"] = { { ["id"] = 130, ["name"] = "Greymane's Gambit", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 130, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[39699] = { ["id"] = 39699, ["name"] = "Ironhorn Leysmithing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38563 }, ["description"] = "I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares. There is also a technique in how you hammer such quantities of leystone that I will instruct you on. Use our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.", ["objectivesText"] = "Gather scrap metal around the Ironhorn Enclave. Then use the Greenhoof's Anvil and Forge to craft a Scrapmetal Handguard , a Scrapmetal Palmplate , a Scrapmetal Cuffplate , and 1 Scrapmetal Fingerplates . Progress: I'm waiting, outsider.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124402, 124403, 124404, 124405, 124406, 124407, 124408, 124409, 124410, 124411, 124436, 124462, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38514 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39702] = { ["id"] = 39702, ["name"] = "Legend of Black Rook Hold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["description"] = "<name>, have you heard of Saris Swifthammer ? He was a legendary blacksmith amongst the elves of Black Rook Hold. I wonder if any of his research still exists. I want you to travel there and see if you can discover anything about Saris, or see if he left anything we can research here at my shop.", ["objectivesText"] = "Go to Black Rook Hold and search for Saris Swifthammer .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questType"] = "standard", ["sourceQuests"] = { 38523 }, ["nextQuests"] = { 39680, 39726 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39716] = { ["id"] = 39716, ["name"] = "Smashing Squashlings", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39716 }, ["description"] = "The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor. Now, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.", ["objectivesText"] = "Kill 6 Growing Squashlings .", ["rewardGold"] = 303800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["starts"] = { { ["npcID"] = 96705 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 96705, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[39718] = { ["id"] = 39718, ["name"] = "Paradise Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 627, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 41220 }, ["description"] = "Archmage Khadgar was planning an expedition to Azsuna - you should seek him out at Krasus' Landing in Dalaran immediately.", ["objectivesText"] = "Speak with Archmage Khadgar at Krasus' Landing in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 98613, ["x"] = 0.5891, ["y"] = 0.5379, ["mapID"] = 720 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98613, ["questType"] = "standard", ["nextQuests"] = { 41220 }, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 3, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39719] = { ["id"] = 39719, ["name"] = "Mutiny on the Boneship", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39719 }, ["description"] = "Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet. The Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor. Seek out Bonerender and defeat him, before he sails back into the mist once again.", ["objectivesText"] = "Kill Bonerender.", ["rewardGold"] = 312800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["starts"] = { { ["npcID"] = 96705 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 96705, ["questType"] = "group", ["db2LabelIDs"] = { 2764 } },
[39720] = { ["id"] = 39720, ["name"] = "Foul Fertilizer", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 39720 }, ["description"] = "The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked. The stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.", ["objectivesText"] = "Destroy 8 kegs of Dread Fertilizer .", ["rewardGold"] = 303800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["starts"] = { { ["npcID"] = 96705 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 96705, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[39721] = { ["id"] = 39721, ["name"] = "Culling the Crew", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 6, ["zoneID"] = 6719, ["storyline"] = { 39721 }, ["description"] = "If we're going to protect Draenor from the Bonefleet menace, we'll need to thin out the crew. See to a swift reduction in their numbers, and we might just push them back into the sea for another year.", ["objectivesText"] = "Destroy 12 Boneship crew members.", ["rewardGold"] = 309800, ["rewardXP"] = 1365, ["rewardItems"] = { 20397, 20398, 20399, 20411, 33226, 62675, 86125, 104316, 120150, 128658, 128660, 128661, 128662, 128663, 128664, 128794, 128807 }, ["starts"] = { { ["npcID"] = 96705 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 96705, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[39726] = { ["id"] = 39726, ["name"] = "...And the Anvil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39729, 44449 }, ["description"] = "If you truly wish to see my work then you'll have to go and retrieve it as my shop has been raided of everything I've made. The breastplates of the Black Rook soldiers were one of my greatest accomplishments. They're light, yet strong and offer great mobility Relinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.", ["objectivesText"] = "Gather 5 Black Rook Breastplates from the elves of Black Rook Hold. Progress: Have you acquired any breastplates?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 38711, 39015, 39044, 39076, 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 128751, 137680, 246951 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39702 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39729] = { ["id"] = 39729, ["name"] = "The Knowledge of Black Rook", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 44449 }, ["description"] = "You have honored me with your help and now I wish to return those favors to you. On that pedestal there is all my research. Take it with you and learn from it so you may carry on my legacy. Thank you again, <name>.", ["objectivesText"] = "Bring Saris' research back to Alard in Dalaran. Progress: Were you able to find him?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 128746, 137680 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 96763, ["questType"] = "standard", ["sourceQuests"] = { 39680, 39726 }, ["nextQuests"] = { 38564 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39731] = { ["id"] = 39731, ["name"] = "The Tranquil Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 39731 }, ["series"] = { 39861, 40122 }, ["description"] = "Archmage Khadgar sent word about Val'sharah not long ago. It sounds like he has good news. You should meet him on Krasus' Landing in Dalaran as soon as you are able.", ["objectivesText"] = "Speak to Archmage Khadgar on Krasus' Landing in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 93787, ["x"] = 0.5344, ["y"] = 0.7863, ["mapID"] = 24 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93787, ["questType"] = "standard", ["nextQuests"] = { 39861 }, ["db2AdventureMapPoiID"] = 4 },
[39733] = { ["id"] = 39733, ["name"] = "The Lone Mountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39733 }, ["series"] = { 38907, 38911, 39316, 39491, 39496 }, ["description"] = "Our sources tell us that a Highmountain tauren emissary has recently arrived in Dalaran. We don't know his intentions, but his people could be an invaluable contact in the region. Khadgar is greeting the emissary at Krasus' Landing in Dalaran - you should seek him out.", ["objectivesText"] = "Speak to Warbrave Oro at Krasus' Landing in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97666, ["x"] = 0.513333, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.513333, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["nextQuests"] = { 38907 }, ["db2AdventureMapPoiID"] = 8 },
[39735] = { ["id"] = 39735, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 84, ["storyline"] = { 39735 }, ["series"] = { 38035, 38052, 38206, 39800, 44700 }, ["description"] = "Sky Admiral Rogers has sent word for you to meet her in Dalaran. She should be waiting for you in the Violet Citadel. It sounded important.", ["objectivesText"] = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 96644, ["x"] = 0.185538, ["y"] = 0.462154 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.185538, ["y"] = 0.462154 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 6 },
[39741] = { ["id"] = 39741, ["name"] = "Into Our Ranks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42634 }, ["description"] = "I feel that we should quickly welcome Akama into our ranks. It's important that the others see him treated as one of us, rather than as an outsider. Kor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies. It is time to officially raise them up as champions.", ["objectivesText"] = "Recruit Akama and Kor'vas Bloodthorn as your champions.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.564, ["mapID"] = 720, ["npcID"] = 108571 } }, ["ends"] = { { ["x"] = 0.585, ["y"] = 0.564, ["mapID"] = 720, ["npcID"] = 108571 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.585, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108571, ["questTurnInID"] = 108571, ["questType"] = "standard", ["sourceQuests"] = { 42634 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[39742] = { ["id"] = 39742, ["name"] = "Vault of the Wardens", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 39742 }, ["objectivesText"] = "Repel the Legion attackers Normal Enemies Elite Enemies Boss Enemies Mephistos", ["rewardGold"] = 404400, ["rewardXP"] = 1145, ["rewardItems"] = { 132243, 246936, 249400, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["sourceQuests"] = { 38672 }, ["db2Objectives"] = { { ["text"] = "Repel the Legion attackers", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Normal Enemies", ["amount"] = 34, ["type"] = 0, ["objectID"] = 97969, ["orderIndex"] = 1 }, { ["text"] = "Elite Enemies", ["amount"] = 20, ["type"] = 0, ["objectID"] = 97970, ["orderIndex"] = 2 }, { ["text"] = "Boss Enemies", ["amount"] = 10, ["type"] = 0, ["objectID"] = 100326, ["orderIndex"] = 3 }, { ["text"] = "Mephistos", ["amount"] = 5, ["type"] = 0, ["objectID"] = 96783, ["orderIndex"] = 4 } } },
[39746] = { ["id"] = 39746, ["name"] = "A Ring Unbroken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 207, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 41335 }, ["description"] = "Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters. The elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. <name>, your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever. Join me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus' Landing here in Dalaran.", ["objectivesText"] = "Aid the shaman of the Earthen Ring at the Maelstrom. Stormcaller Mylra will fly you there from Krasus' Landing in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.471, ["y"] = 0.335, ["mapID"] = 627, ["npcID"] = 91731 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 7502 } }, ["questGiverID"] = 91731, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1572, ["db2PoiUiMapID"] = 725 },
[39756] = { ["id"] = 39756, ["name"] = "A Sound Plan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 38933, 42811, 42812 }, ["description"] = "The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back. Let's prove them wrong. We've been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault. Once you've had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast. We will end this madness for good. Light help us all.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 38933 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[39762] = { ["id"] = 39762, ["name"] = "Feltotem Warlock", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39763] = { ["id"] = 39763, ["name"] = "For Whom the Fel Tolls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 3, 9, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39790, 39817, 39830 }, ["description"] = "<Matthew eyes you up and down, growling slightly> You wish me to help you understand this rock? First you do something for me. The legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution. Bring me some cores and I'll give you the information you need.", ["objectivesText"] = "Obtain 10 Fel Energy Cores from Wyrmtongue Minions in Suramar. Bring them back to Matthew in Dalaran when you are finished. Progress: Have you acquired what I requested?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128813 }, ["starts"] = { { ["x"] = 0.472, ["y"] = 0.56, ["mapID"] = 628, ["npcID"] = 97360 } }, ["ends"] = { { ["x"] = 0.472, ["y"] = 0.56, ["mapID"] = 628, ["npcID"] = 97360 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.472, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 97360, ["questTurnInID"] = 97360, ["questType"] = "standard", ["sourceQuests"] = { 39790 }, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39764] = { ["id"] = 39764, ["name"] = "Shiny, But Deadly", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 654, ["storyline"] = { 39764, 39773, 39774 }, ["description"] = "Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds. Those mindless vermin made off with the soul chambers that house our demonic captives. The crystals may be shiny, but they're also deadly. If they are damaged in any way, the demons trapped within may escape. Head into the cave nearby and recover the soul chambers before it's too late.", ["objectivesText"] = "Collect Soul Chambers from kobolds within Mucksnout Den. Progress: Have you recovered the soul chambers yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128752 }, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.82, ["mapID"] = 654, ["npcID"] = 97094 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.82, ["mapID"] = 654, ["npcID"] = 97094 } }, ["coords"] = { ["mapID"] = 654, ["x"] = 0.518, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 97094, ["questTurnInID"] = 97094, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5922, ["name"] = "Mucksnout Den", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 654 },
[39765] = { ["id"] = 39765, ["name"] = "Wax On, Wax Off", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39768, 39769 }, ["description"] = "I've been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head! He's down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself. Kill one of their Skullcaptains and recover his Skull of Bossing Around , and they may let you into the cave.", ["objectivesText"] = "Recover the Skull of Bossing Around from the Bluewax Skullcaptain. Progress: The desecration...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128753 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39768] = { ["id"] = 39768, ["name"] = "Candle to the Grave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39765, 39769 }, ["description"] = "These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on. I can do nothing to stop them! Please rid this sacred burial ground of the kobold.", ["objectivesText"] = "Slay 7 Bluewax Graverobbers .", ["rewardGold"] = 273848, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39769] = { ["id"] = 39769, ["name"] = "The Gates of Wax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39765, 39768 }, ["description"] = "Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.", ["objectivesText"] = "Speak with the Bluewax Gatekeeper and see if he will let you in to meet the Candleking.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39765, 39768 }, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39771] = { ["id"] = 39771, ["name"] = "The Voice of Thunder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 726, ["storyline"] = { 39771, 43334, 43338 }, ["description"] = "The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm. Now you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans. Come! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!", ["objectivesText"] = "Travel to the Temple of the White Tiger and prove yourself worthy to wield the weapons of storm! Progress: We have trained our whole lives for this, <name>. We cannot fail.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.47, ["y"] = 0.83, ["mapID"] = 395, ["npcID"] = 96541 } }, ["ends"] = { { ["x"] = 0.47, ["y"] = 0.83, ["mapID"] = 395, ["npcID"] = 96541 } }, ["coords"] = { ["mapID"] = 395, ["x"] = 0.47, ["y"] = 0.83 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8046 } }, ["questGiverID"] = 96541, ["questTurnInID"] = 96541, ["questType"] = "standard", ["sourceQuests"] = { 43338 }, ["questLines"] = { { ["id"] = 266, ["name"] = "The Voice of Thunder", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 266, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[39772] = { ["id"] = 39772, ["name"] = "Can't Hold a Candle To You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39770, 40339, 40345 }, ["description"] = "Okay guess you can go say hi to Candleking now.", ["objectivesText"] = "Recover Oenia's Skull from the Candleking. Progress: Have you found my skull?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128756, 130275, 130283, 130284, 130285, 130286, 260698 }, ["rewardChoices"] = { 130275, 130283, 130284, 130285, 130286 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40345 }, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39773] = { ["id"] = 39773, ["name"] = "The Soulkeeper's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 654, ["storyline"] = { 39764, 39773, 39774 }, ["description"] = "Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst. Please find Uriah. He is the only one who knows how to trap the demons.", ["objectivesText"] = "Find Soulkeeper Uriah within Mucksnout Den.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.518, ["y"] = 0.82, ["mapID"] = 654, ["npcID"] = 97094 } }, ["ends"] = { { ["x"] = 0.518, ["y"] = 0.82, ["mapID"] = 654, ["npcID"] = 97094 } }, ["coords"] = { ["mapID"] = 654, ["x"] = 0.518, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 97094, ["questTurnInID"] = 97094, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5922, ["name"] = "Mucksnout Den", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 654 },
[39774] = { ["id"] = 39774, ["name"] = "Demon Detainment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39764, 39773, 39774 }, ["description"] = "The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail. I've seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I'll just need you to subdue them first.", ["objectivesText"] = "Weaken demons so Apprentice Rosalyn can trap them within a soul chamber. Progress: You must weaken the demons so I am able to trap them.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132087, 132088, 132089, 132090, 132091, 132092, 132093, 137663 }, ["rewardChoices"] = { 132087, 132088, 132089, 132090, 132091, 132092, 132093 }, ["starts"] = { { ["x"] = 0.3, ["y"] = 0.627, ["mapID"] = 654, ["npcID"] = 97846 } }, ["ends"] = { { ["x"] = 0.3, ["y"] = 0.627, ["mapID"] = 654, ["npcID"] = 97846 } }, ["coords"] = { ["mapID"] = 654, ["x"] = 0.3, ["y"] = 0.627 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 97846, ["questTurnInID"] = 97846, ["questType"] = "standard", ["sourceQuests"] = { 39764, 39773 }, ["questLines"] = { { ["id"] = 5922, ["name"] = "Mucksnout Den", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
