[39776] = { ["id"] = 39776, ["name"] = "Battle Worms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation. The drogbar are using worms to burrow their way to the surface and deploy their troops. I am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.", ["objectivesText"] = "Slay Naxa , Arxas , and Xist . Progress: Worms. Why did it have to be worms? I hate worms.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38915 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39777] = { ["id"] = 39777, ["name"] = "Buy Us Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["description"] = "We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers? I will direct my healers to get everyone that is unable to fight to safety.", ["objectivesText"] = "Slay 10 Mightstone drogbar. Progress: We need all the time you can buy us.", ["rewardGold"] = 176280, ["rewardXP"] = 1415, ["rewardItems"] = { 37271, 37393, 37425, 38212 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97344, ["x"] = 0.532, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97344, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38915 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39780] = { ["id"] = 39780, ["name"] = "The Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Mayla already chased the Underking into his cave. That is something we tell our children never to do. Reckless child, but hey, who wants to live forever? Let us join her in battle.", ["objectivesText"] = "Assault Dargrul the Underking.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121673, 121674, 121675, 121676, 130269, 130270, 130271, 130272, 245461, 246937 }, ["rewardChoices"] = { 121673, 121674, 121675, 121676, 130269, 130270, 130271, 130272 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40594 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39781] = { ["id"] = 39781, ["name"] = "Neltharion's Lair: Death to the Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 42454 }, ["description"] = "I will direct my people to clear a path through this rubble and assault Dargrul's forces directly. It will be a ruse. Navarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul. Muster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz'goroth before that villain brings the mountain down on top of us. We will provide the distraction you need to get a shot.", ["objectivesText"] = "Recover the Hammer of Khaz'goroth . Progress: The war continues.", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 128765, 141400 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 93846, ["questType"] = "dungeon", ["sourceQuests"] = { 39780 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1458, ["db2PoiUiMapID"] = 731 },
