[39786] = { ["id"] = 39786, ["name"] = "A Stone Cold Gamble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "The second target is a basilisk called Stonefang that lives off the bank of the nearby river. I put a bigger wager on him, so if you can take him out I'll make sure you get a cut. I'll need his jaw to verify the kill. Hurry, before those tauren get him first!", ["objectivesText"] = "Collect Stonefang's Jaw from Stonefang in Stonescar Gorge. Progress: Did you take him out?", ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138023, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "group", ["sourceQuests"] = { 39787, 39793 }, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 4, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39787] = { ["id"] = 39787, ["name"] = "Rigging the Wager", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "Care to help settle a bet, chum? Those tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn't be able to take out some of the biggest beasts in Stormheim . If you take em out before they do, I'll split the wager. Deal? The first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he's up pretty high, so you'll need a grapple gun to get there. I think there's one of them layin around here...", ["objectivesText"] = "Lure down and defeat Spitefeather to collect Spitefeather's Beak in the Stormtorn Foothills. Progress: You got my trophy yet?", ["rewardXP"] = 1415, ["rewardItems"] = { 127834, 132203, 138022, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "group", ["sourceQuests"] = { 39793 }, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 2, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39788] = { ["id"] = 39788, ["name"] = "The Runewood's Revenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "The Bonespeakers...they are corrupt... hungry for power. Cut them from my woods...", ["objectivesText"] = "Kill 8 Bonespeaker Runeaxes and 8 Bonespeaker Carvers in the Runewood. Progress: Has the corruption been removed?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39796 }, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39789] = { ["id"] = 39789, ["name"] = "Eating Into Our Business", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["series"] = { 39793 }, ["description"] = "Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you. As you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels. I can't take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.", ["objectivesText"] = "Kill 10 Duskpelt worg in Amberfall Mesa.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138111, 138123, 138125, 138127, 138128, 138129, 138130, 138131, 138133, 138135 }, ["rewardChoices"] = { 138127, 138129 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97258, ["x"] = 0.514, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39790] = { ["id"] = 39790, ["name"] = "Infernal Brimstone Theory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 2, 3, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39763, 39817, 39830 }, ["description"] = "I've gone through all the research ye gathered for me and I've come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes. But the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown. If we're wantin' to test this out, we'll have to get the help of some magic-users. Take this brimstone back and go see Matthew Rabis . He may know how to breathe life into it.", ["objectivesText"] = "Take the brimstone sample to Matthew Rabis in the Underbelly. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128852 }, ["starts"] = { { ["x"] = 0.462, ["y"] = 0.264, ["mapID"] = 627, ["npcID"] = 93189 } }, ["ends"] = { { ["x"] = 0.462, ["y"] = 0.264, ["mapID"] = 627, ["npcID"] = 93189 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.462, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93189, ["questTurnInID"] = 93189, ["questType"] = "standard", ["sourceQuests"] = { 38807 }, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39791] = { ["id"] = 39791, ["name"] = "Lay Them to Rest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "I would ask a favor, outsider. As you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well. Take this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.", ["objectivesText"] = "Use the Branch of the Runewood to send 8 weakened Restless Ancestors back to the earth.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 3456, 128772, 137663 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93446, ["x"] = 0.681, ["y"] = 0.485 }, { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38808, 38810 }, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39792] = { ["id"] = 39792, ["name"] = "A Stack of Racks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "So while we're waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I'm sure they'd be thankful to have more. I hear that musken ribs are the specialty here. The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out! Don't worry, I'm pretty sure there aren't any dragons over there...", ["objectivesText"] = "Collect 8 Meaty Racks of Musken Ribs from Stout Highland Runehorns in Jotunnwood. Progress: Aint nothin like some good old meaty musken ribs, eh pal?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 122577, 131811, 132203, 138020, 138111, 138123, 138125, 138126, 138127, 138129, 138131, 138133, 138134, 138135, 139773, 140216 }, ["rewardChoices"] = { 138125, 138133 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39787, 39793 }, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39793] = { ["id"] = 39793, ["name"] = "Only the Finest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["series"] = { 39789 }, ["description"] = "Say, you're a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I'm sure they'd appreciate it when they got back! I hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there. Why don't you go and fetch some? I'm sure them tauren would pay you handsomely!", ["objectivesText"] = "Collect 18 Patches of Fine Goat Hair from Silvertail Mountain Goats in Nastrondir. Progress: Make sure to get the good stuff!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138021, 138111, 138123, 138124, 138125, 138127, 138129, 138131, 138132, 138133, 138135 }, ["rewardChoices"] = { 138123, 138131 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39789 }, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39796] = { ["id"] = 39796, ["name"] = "To Haustvald", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate! It is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.", ["objectivesText"] = "Meet with Vydhar in the Runewood.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39804 }, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 2, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39799] = { ["id"] = 39799, ["name"] = "Our Next Move", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39832, 40714 }, ["description"] = "Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion! Under cover of this fog we've been able to send out scouting teams who've put together a fairly comprehensive map of the Broken Isles. Choose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.", ["objectivesText"] = "Select your order's first assault point.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403 }, ["starts"] = { { ["x"] = 0.506, ["y"] = 0.516, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.506, ["y"] = 0.516, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.506, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 39832 }, ["questLines"] = { { ["id"] = 170, ["name"] = "The Ebon Blade", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[39800] = { ["id"] = 39800, ["name"] = "Greymane's Gambit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["description"] = "The Skyfire is prepared to make way to Stormheim . Should we become engaged, I will require my best fighters on the front line. This includes you, .", ["rewardGold"] = 4000, ["rewardXP"] = 1770, ["rewardItems"] = { 121753, 121761 }, ["rewardChoices"] = { 121753, 121760, 121761, 121762, 139914, 139950, 139955, 139976 }, ["starts"] = { { ["npcID"] = 96663, ["x"] = 0.186, ["y"] = 0.508, ["mapID"] = 84 } }, ["ends"] = { { ["npcID"] = 90749, ["x"] = 0.336, ["y"] = 0.51, ["mapID"] = 634 } }, ["coords"] = { ["x"] = 0.186, ["y"] = 0.508, ["source"] = "quest_giver", ["mapID"] = 634 }, ["mapCandidates"] = { ["npc"] = { 84, 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38206 }, ["questLines"] = { { ["id"] = 131, ["name"] = "Greymane's Gambit", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 131, ["questLineOrder"] = 0 } } },
[39801] = { ["id"] = 39801, ["name"] = "The Splintered Fleet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 1, ["storyline"] = { 38307, 39698, 39801, 44701 }, ["series"] = { 39698 }, ["description"] = "Preparations have been made, and we are ready to set sail. We must strike out at once. Do not dally, or you will be left behind.", ["objectivesText"] = "Complete Sylvanas' mission to bring the fleet to Stormheim .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 139916, 139925, 139948, 139956, 139974, 139987, 140012, 140018, 246937, 253251 }, ["rewardChoices"] = { 139916, 139925, 139948, 139956, 139974, 139987, 140012, 140018 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 96686, ["x"] = 0.614, ["y"] = 0.093 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91473, ["x"] = 0.36, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.093 }, ["mapCandidates"] = { ["npc"] = { 1, 634 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 39698 }, ["questLines"] = { { ["id"] = 130, ["name"] = "Greymane's Gambit", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 130, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39803] = { ["id"] = 39803, ["name"] = "The Trials Continue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39804, 40568, 44922, 44940 }, ["description"] = "< Havi 's voice continues in your head as the raven stares on> If valor you seek, then to the bones you must speak! But first you must prepare!", ["objectivesText"] = "Meet with Havi in Valdisdall.", ["rewardGold"] = 6380, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97074, ["x"] = 0.48, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38624 }, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39804] = { ["id"] = 39804, ["name"] = "Speaking of Bones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 40568, 44922, 44940 }, ["description"] = "The Trial of Valor will be your next test, and test you it will! But only a fool fights on an empty stomach. Are you a fool, outsider? No? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.", ["objectivesText"] = "Help Havi butcher the moose and learn about your next trial.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39803 }, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
