[39817] = { ["id"] = 39817, ["name"] = "The Brimstone's Secret", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39763, 39790, 39830 }, ["description"] = "While you were gathering what I asked of you, I did a little testing on the brimstone. It reacted rather violently when I channeled onto it. Careful casting went into making the creature from whom you took this. Unless you have a host of demon spell-casters at your disposal, recreating such a creature would be impossible. That's all I have to tell you. Go now and leave me before my hunger takes over.", ["objectivesText"] = "Tell Mama Diggs what you learned from Matthew.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.472, ["y"] = 0.56, ["mapID"] = 628, ["npcID"] = 97360 } }, ["ends"] = { { ["x"] = 0.472, ["y"] = 0.56, ["mapID"] = 628, ["npcID"] = 97360 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.472, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 97360, ["questTurnInID"] = 97360, ["questType"] = "standard", ["sourceQuests"] = { 39763 }, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
