[39830] = { ["id"] = 39830, ["name"] = "Hellfire Citadel: Hellfire and Brimstone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 2, 3, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39763, 39790, 39817 }, ["description"] = "When Khadgar's group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself. Perhaps there's somethin' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.", ["objectivesText"] = "Gather a group and storm Hellfire Citadel once more. Defeat Archimonde and recover the Infernal Codex . Progress: Don't go alone, lad. That place is teemin' with demons.", ["rewardItems"] = { 136389 }, ["starts"] = { { ["x"] = 0.462, ["y"] = 0.264, ["mapID"] = 627, ["npcID"] = 93189 } }, ["ends"] = { { ["x"] = 0.462, ["y"] = 0.264, ["mapID"] = 627, ["npcID"] = 93189 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.462, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93189, ["questTurnInID"] = 93189, ["questType"] = "standard", ["sourceQuests"] = { 39817 }, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39832] = { ["id"] = 39832, ["name"] = "Plans and Preparations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39832, 40714 }, ["description"] = "Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential. Siouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.", ["objectivesText"] = "Speak to Siouxsie the Banshee .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.511, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93437, ["questTurnInID"] = 93437, ["questType"] = "standard", ["sourceQuests"] = { 38990, 40740, 40935, 40987 }, ["questLines"] = { { ["id"] = 170, ["name"] = "The Ebon Blade", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[39837] = { ["id"] = 39837, ["name"] = "An Unworthy Task", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39848, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "This place is Helheim , the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it. We should not be here. We must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.", ["objectivesText"] = "Search among the caged vrykul in Helheim for one who can help your escape.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["starts"] = { { ["x"] = 0.653, ["y"] = 0.469, ["mapID"] = 649, ["npcID"] = 97319 } }, ["ends"] = { { ["x"] = 0.653, ["y"] = 0.469, ["mapID"] = 649, ["npcID"] = 97319 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.653, ["y"] = 0.469 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 97319, ["questTurnInID"] = 97319, ["questType"] = "standard", ["sourceQuests"] = { 38818 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
