[39847] = { ["id"] = 39847, ["name"] = "Sign This", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39931 }, ["description"] = "Ah, a fellow scribe! You don't look too dim, so how 'bout you and I work together in an effort to discover what we can about the Broken Isles? (That's the big mass of islands we're floating over.) However! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we're in business.", ["objectivesText"] = "Sign Professor Pallin 's contract. Progress: Did you remember to cross your t's and dot your lower case j's?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129043, 129047, 129211, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "standard", ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39848] = { ["id"] = 39848, ["name"] = "A Desperate Bargain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "It looks like your friend didn't make it. A pity, but we must move on. You'll want to plead our case to Helya. She is the ruler here. I would accompany you, but I'm afraid I wouldn't help your case. Meet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.", ["objectivesText"] = "Confront Helya and ask to be freed from Helheim . Progress: <The air hangs silent as you approach.>", ["rewardGold"] = 79250, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.472, ["y"] = 0.325, ["mapID"] = 649, ["npcID"] = 97419 } }, ["ends"] = { { ["x"] = 0.472, ["y"] = 0.325, ["mapID"] = 649, ["npcID"] = 97419 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.472, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 97419, ["questTurnInID"] = 97419, ["questType"] = "standard", ["sourceQuests"] = { 38347 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[39849] = { ["id"] = 39849, ["name"] = "To Light the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "Helya must think her challenge unwinnable. We will show her different. I am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya's minions. I may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit. There is a kvaldir ship nearby. See if you can find one there.", ["objectivesText"] = "Collect a Helheim Waylight from Bloodbeard in Helheim . Progress: Were you able to secure the lantern?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128854, 129239, 129339, 247234, 254878 }, ["rewardChoices"] = { 129239, 129339 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["ends"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.466, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 97480, ["questTurnInID"] = 97480, ["questType"] = "standard", ["sourceQuests"] = { 39857 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[39850] = { ["id"] = 39850, ["name"] = "Sundered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit. Helya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free. Be careful, though. It is unlikely that Helya left your spirit fragments unguarded.", ["objectivesText"] = "Find and release the Fragment of Will, Fragment of Might, and Fragment of Valor in Helheim . Progress: Have you recovered your power?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 22829, 22832 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["ends"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.466, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 97480, ["questTurnInID"] = 97480, ["questType"] = "standard", ["sourceQuests"] = { 39849 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[39851] = { ["id"] = 39851, ["name"] = "Allies in Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39852, 39853, 39855, 39857 }, ["description"] = "Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us. Earlier, I had discovered several of them being tortured by the elemental forces of Helheim . You may think the dead can't drown, but with Helya's power, this is not the case. I could not release them then, but now that you possess the waylight, you may be able to. Seek them out and free them from an eternity of suffering!", ["objectivesText"] = "Release 8 Drowning Valkyra in Helheim . Progress: Once unbound, my Valkyra will throttle these wretched minions.", ["rewardGold"] = 79250, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["ends"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.466, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 97480, ["questTurnInID"] = 97480, ["questType"] = "standard", ["sourceQuests"] = { 39849 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[39853] = { ["id"] = 39853, ["name"] = "Victory is Eternal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39855, 39857 }, ["description"] = "There is no more cause for hesitation. Now is the time to strike. We will defeat this foul behemoth and meet Helya's bargain. The path out of Helheim awaits, outsider. Prepare yourself.", ["objectivesText"] = "Defeat Geir in the Eternal Battlefield in Helheim . Progress: Together, we can defeat this foe!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["ends"] = { { ["x"] = 0.466, ["y"] = 0.494, ["mapID"] = 649, ["npcID"] = 97480 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.466, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 97480, ["questTurnInID"] = 97480, ["questType"] = "standard", ["sourceQuests"] = { 39850, 39851 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[39855] = { ["id"] = 39855, ["name"] = "Paid in Lifeblood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 634, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39857 }, ["description"] = "We have fulfilled Helya's bargain. Now, we see if she will keep to her word. When you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now. I will follow your lead, outsider.", ["objectivesText"] = "Confront Helya and leave Helheim .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129188, 132824, 132825, 132826, 132827, 132828, 132829, 132830, 132831, 132832, 132834, 141401, 246937 }, ["rewardChoices"] = { 132824, 132825, 132826, 132827, 132828, 132829, 132830, 132831, 132832, 132834 }, ["starts"] = { { ["x"] = 0.462, ["y"] = 0.606, ["mapID"] = 649, ["npcID"] = 97558 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questGiverID"] = 97558, ["questType"] = "standard", ["sourceQuests"] = { 39853 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39857] = { ["id"] = 39857, ["name"] = "The Eternal Nemesis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39855 }, ["description"] = "<Helya's voice echoes in the sky above the altar> You say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? I cannot, so you must show me. Bring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.", ["objectivesText"] = "Return to Ashildir and inform her of Helya's challenge.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.342, ["y"] = 0.281, ["mapID"] = 649, ["objectID"] = 244559 } }, ["ends"] = { { ["x"] = 0.342, ["y"] = 0.281, ["mapID"] = 649, ["objectID"] = 244559 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.342, ["y"] = 0.281 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["sourceQuests"] = { 39848 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[39859] = { ["id"] = 39859, ["name"] = "Note-Eating Goats", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 40170, 40216, 40217 }, ["description"] = "I've followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales. But my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle! Hemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft! I have no hope of becoming a hunter if my manuscript isn't recovered.", ["objectivesText"] = "Recover Addie's manuscript from Sated Hillstriders within Pinerock Basin. Progress: I've been waitin' all day for Addie to finish her first draft. How hard can it be to write a few words about the greatest hunter who's ever lived?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128864, 130320, 160452 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94434, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39417, 40217 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39860] = { ["id"] = 39860, ["name"] = "Rite of Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 653, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Oakin Ironbull vouches for you. He's capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof. Before we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me. Enter the depths of the cave. Defeat whatever foe appears and return to me.", ["objectivesText"] = "Complete the Rite of Blood. Progress: Are you afraid of the dark?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121668, 121669, 121670, 121671, 121726, 121728, 121730 }, ["rewardChoices"] = { 121668, 121669, 121670, 121671, 121726, 121728, 121730 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.318, ["mapID"] = 653, ["npcID"] = 93836 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.318, ["mapID"] = 653, ["npcID"] = 93836 } }, ["coords"] = { ["mapID"] = 653, ["x"] = 0.591, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 93836, ["questTurnInID"] = 93836, ["questType"] = "standard", ["sourceQuests"] = { 39455 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 653 },
[39861] = { ["id"] = 39861, ["name"] = "Tying Up Loose Ends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39861 }, ["series"] = { 39731, 40122 }, ["description"] = "Malfurion Stormrage managed to make landfall in Val'sharah and has already taken care of things there. It seems our fortune is finally turning around! He's waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.", ["objectivesText"] = "Speak to Aludane Whitecloud at Krasus' Landing to secure a flight to Val'sharah . Speak to Malfurion Stormrage after you arrive in Lorlathil. Progress: Highlord <name>! You couldn't have arrived at a better time.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.701, ["y"] = 0.437, ["mapID"] = 627, ["npcID"] = 91172 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91462, ["x"] = 0.546, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 91172, ["questType"] = "standard", ["sourceQuests"] = { 39731 }, ["nextQuests"] = { 40122 } },
[39862] = { ["id"] = 39862, ["name"] = "The Siegebrul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["description"] = "Worms do not like battle or the surface. They only go where their master tells them. So, when in war, kill the master. Siegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north. Slay him.", ["objectivesText"] = "Slay Siegebrul Olgrul . Progress: Siegbrul Olgrul torments all who serve him. There are evil drogbar, and then there is this foul monster.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97301, ["x"] = 0.532, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97301, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 38915 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39864] = { ["id"] = 39864, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 1, ["storyline"] = { 39864 }, ["series"] = { 38307, 44701 }, ["description"] = "Nathanos Blightcaller , Champion of the Banshee Queen herself, sent for you in Dalaran. He should be waiting for you in the Violet Citadel. It sounded urgent.", ["objectivesText"] = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 96683, ["x"] = 0.612, ["y"] = 0.088 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.088 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 7 },
[39867] = { ["id"] = 39867, ["name"] = "I'm Not Lion!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "I've hunted many exotic beasts in my day, but I've never seen a lion like the one I encountered while scouting the basin. The beast's amber eyes locked on mine, luring me closer. I was helpless to this predator's enchanting gaze. It was only when the lion pounced did the stupor break. I've told Hemet of this magical beast, but he laughs. I'm not lying, <name>! The lion exists. If you find the beast, bring me a trophy of your kill, and I'll reward you handsomely.", ["objectivesText"] = "Collect a hunting trophy from the lion that Ellias claims to have seen in Pinerock Basin. Progress: I'll have the last laugh when Hemet sees proof that this magical lion exists!", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 57386, 57387, 57388, 128933, 131875, 133810 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95438, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95438, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "group", ["sourceQuests"] = { 39123 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39869] = { ["id"] = 39869, ["name"] = "Toll for the Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7812, ["mapID"] = 634, ["description"] = "As foretold, you have arrived... Helya is foolish to think I'll let her ferry me into Helheim. Odyn has already smiled upon me, my soul belongs in Valhallas. Make no mistake, I am not a prisoner. Before my death Odyn appeared to me in the form of a raven. He praised my battles in life and gave me a quest no vrykul could refuse. The Helerjar arrived... and I let them slay me. Prisoner-- nay, I am a liberator, sent by Odyn to free the souls of Valarjar.", ["rewardGold"] = 1213200, ["rewardXP"] = 2830, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7812 } }, ["questType"] = "dungeon" },
[39873] = { ["id"] = 39873, ["name"] = "I Have a Bad Feeling About This", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["description"] = "You have no reason to trust me. My cousins led by Dargrul have gone mad with power. But I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain , and that Torok and his Bloodtotem are going to be responsible. If you don't believe me, look for yourself at the northern side of Cliff's Edge.", ["objectivesText"] = "Investigate Navarrogg 's suspicions.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97667, ["x"] = 0.39, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97667, ["x"] = 0.39, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 97667, ["questType"] = "standard", ["sourceQuests"] = { 38912 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39874] = { ["id"] = 39874, ["name"] = "Some Enchanted Evening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39875, 39876, 39877 }, ["description"] = "Welcome! It's nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. Archmage Starsinger is in charge of the shop, but he's away on Kirin Tor business at the moment. He's a fine fellow... mostly. Your arrival is fortunate. We've run into a problem that we'd love to solve before the archmage returns. Interested in lending a hand?", ["objectivesText"] = "Speak to Ildine Sorrowspear inside the enchanting shop in Dalaran.", ["rewardXP"] = 1415, ["rewardItems"] = { 6217, 38682 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93531, ["questTurnInID"] = 93531, ["questType"] = "standard", ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39875] = { ["id"] = 39875, ["name"] = "The Last Few", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39874, 39876, 39877 }, ["description"] = "As you can see, <name>, we're hard at work producing enchants for the battle against the Legion. Since you're here, we could really use your help wrapping up one of our orders. If you could, acquire some vellums and start enchanting them with Versatility. Here, I'll teach you the formula.", ["objectivesText"] = "Create 2 Enchant Ring - Word of Versatility vellums for Ildine. You can acquire vellums from a scribe, or from the Auction House. Progress: Almost done enchanting those vellums?", ["rewardXP"] = 1415, ["rewardItems"] = { 38682, 124440, 128540 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.416, ["mapID"] = 627, ["npcID"] = 93530 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.416, ["mapID"] = 627, ["npcID"] = 93530 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93530, ["questTurnInID"] = 93530, ["questType"] = "standard", ["sourceQuests"] = { 39874 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39876] = { ["id"] = 39876, ["name"] = "Helping the Hunters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39874, 39875, 39877 }, ["description"] = "Now, while I continue to fill the rest of our orders, I'd really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna. He and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible. Thanks, <name>!", ["objectivesText"] = "Deliver the crate of vellums to Jace Darkweaver in Azsuna. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 137186 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.416, ["mapID"] = 627, ["npcID"] = 93530 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93530, ["questType"] = "standard", ["sourceQuests"] = { 39875 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39877] = { ["id"] = 39877, ["name"] = "In the Loop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39874, 39875, 39876 }, ["description"] = "We could use your help down here, <name>. Some of our hunters would benefit greatly from having those vellums applied to their rings right now. Here take a few. I'll give the rest to one of my other soldiers to hand out. My hunters probably won't stop to let you apply the enchants, so you'll just have to do your enchanting even if they're in the midst of battle.", ["objectivesText"] = "Use the enchanting vellums on 6 Demon Hunters at the Illidari Stand. Progress: There's no time to waste. We need to get these enchantments out to as many of my hunters as possible.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 123919, 124124, 130176, 130181, 130183, 132331, 132332, 132333, 137120, 137838, 137840, 137865 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39875 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39878] = { ["id"] = 39878, ["name"] = "Thunder Struck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 40048 }, ["description"] = "I've made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power. Seek out an enchanter named Twaintail and see if he will share his knowledge with us. Taurens are known for their sharing... right?", ["objectivesText"] = "Speak to Guron Twaintail in Thunder Totem.", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93531, ["questType"] = "standard", ["sourceQuests"] = { 39905 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39879] = { ["id"] = 39879, ["name"] = "Strong Like the Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39880, 39882, 39883, 39884, 39889 }, ["description"] = "There are many types of spirits in this world, <name>. Some benevolent, some troubled. They all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards. They are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I'll show you what I mean.", ["objectivesText"] = "Defeat Enraged Ambershards and collect 8 of their Ambershard Crystals. Bring them back to Guron in Thunder Totem. Progress: Crystals aren't the only thing the spirits respond to. There are others, but that is another tale for another time.", ["rewardXP"] = 1415, ["rewardItems"] = { 137193 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39878 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39880] = { ["id"] = 39880, ["name"] = "Waste Not", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39882, 39883, 39884, 39889 }, ["description"] = "While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste. I'd like you to retrieve our braves' armor and disenchant them into the components from which they were imbued. Bring me back the reagents so my tribe may use them to enchant new armor.", ["objectivesText"] = "Go to the Crystal Fissure and search for discarded armor. Disenchant the armor and bring back 15 Thunder Dust to Guron. Progress: To waste what we are given, is to laugh at the spirits who gave it to us to begin with.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 83726, 83727, 83728, 83729, 83730, 116394, 137195, 137196, 142054, 166846 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["sourceQuests"] = { 39878 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[39881] = { ["id"] = 39881, ["name"] = "Fey Enchantments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "The new dusts and crystals we've found in these lands are fascinating, as I'm sure you've already surmised. I'm positive we can expand their usefulness to more of our armor. I'd like you to go back out into the field and talk to a dryad in Val'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces. Her name is Nalamya . You'll find her near the Temple of Elune.", ["objectivesText"] = "Seek out Nalamya near the Temple of Elune in Val'sharah.", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93531, ["questType"] = "standard", ["sourceQuests"] = { 39883 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39882] = { ["id"] = 39882, ["name"] = "Darkheart Thicket: The Glamour Has Faded", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7673, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39883, 39884, 39889 }, ["description"] = "I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor. Arch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight. Before his betrayal, I gave him my book of enchantments to study. I would very much like it back. I trust you with this task, enchanter. Bring my book back to me.", ["objectivesText"] = "Kill Arch-Druid Glaidalis in the Darkheart Thicket and recover Nalamya's Book of Enchantments . Progress: If you're truly a friend in this war, then be my sword and strike down Glaidalis.", ["rewardXP"] = 1415, ["rewardItems"] = { 137211 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7673 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 39884, 39889 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39883] = { ["id"] = 39883, ["name"] = "Cloaked in Tradition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39882, 39884, 39889 }, ["description"] = "You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles. Here, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you. Perhaps it will serve to help the greater cause of defeating the Legion.", ["objectivesText"] = "Take Guron's Journal to Nalthanis in Dalaran. Progress: Welcome back, <name>. Did you make contact with the tauren?", ["rewardXP"] = 1415, ["rewardItems"] = { 129176 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questTurnInID"] = 98017, ["questType"] = "standard", ["sourceQuests"] = { 39879, 39880 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39884] = { ["id"] = 39884, ["name"] = "No Longer Worthy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39882, 39883, 39889 }, ["description"] = "The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter. Such behavior is intolerable... especially after all the help they've received from my folk and the others of this land. I want you to do me a favor, <name>. Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.", ["objectivesText"] = "Kill night elves within the grounds of Black Rook Hold and collect their Enchanted Raven Sigils . Disenchant the sigils and bring back 8 Raven Dust to Nalamya as proof of their defeat. Progress: Their behavior was so odd and sudden. It makes no sense why they'd turn their backs on us. Still, it's inexcusable.", ["rewardXP"] = 1415, ["rewardItems"] = { 137213, 137221 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39881 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39889] = { ["id"] = 39889, ["name"] = "Led Astray", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39882, 39883, 39884 }, ["description"] = "The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I've no doubt that the blame for their apathy rests heavily upon their commanders. I know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home. Go to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow . Let them be an example for those who can help, but wish to remain cowardly.", ["objectivesText"] = "Go to Black Rook Hold in Val'sharah and slay Trelan Shieldbreaker and Starlys Strongbow .", ["rewardGold"] = 30900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39881 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39891] = { ["id"] = 39891, ["name"] = "Cursed, But Convenient", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39907, 39916, 39918, 39920, 39921, 40130, 40169 }, ["description"] = "I need you to return to Azsuna at once, <name>. I've only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments. Go to her and see what you can learn at once.", ["objectivesText"] = "Find Enchantress Ilanya at the Crumbled Palace in Azsuna.", ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93531, ["questType"] = "standard", ["sourceQuests"] = { 39904 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39903] = { ["id"] = 39903, ["name"] = "An Enchanting Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39904, 40265 }, ["description"] = "The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders! Ildine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day! Investigating the home might uncover valuable knowledge, <name>.", ["objectivesText"] = "Investigate Tigrid's home in Stormheim.", ["rewardXP"] = 1415, ["rewardItems"] = { 124440, 128535, 128617, 128618, 128619, 128620, 128621, 128622, 129293, 137235 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93531, ["questType"] = "standard", ["sourceQuests"] = { 39883 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39904] = { ["id"] = 39904, ["name"] = "Halls of Valor: Revenge of the Enchantress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39903, 40265 }, ["description"] = "For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left. If you can recover my enchanting rod from the god-king's ghost, I will reward you in kind.", ["objectivesText"] = "Retrieve Tigrid's Enchanting Rod from the Halls of Valor and return it to her in Stormheim. Progress: The rod is an extension of me, and I of it. It would be nice to hold it once more.", ["rewardXP"] = 1415, ["rewardItems"] = { 124440, 128535, 128617, 128618, 128619, 128620, 128621, 128622, 129293, 137235 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40265 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39905] = { ["id"] = 39905, ["name"] = "Ringing True", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "While your presence here would continue to be of value to us, your master in Dalaran has called for you. I'd like to thank you again for all you've done for us. My hunters have been reminded that they're not alone in this war.", ["objectivesText"] = "Return to Nalthanis in Dalaran.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 90317, ["questType"] = "standard", ["sourceQuests"] = { 39877, 40048 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39906] = { ["id"] = 39906, ["name"] = "Prepping For Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39914 }, ["description"] = "To earn my mark, <class>, you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him. Before we go into battle together, I need your help as an enchanter to become stronger. I'm sure by now you have a bevy of enchantments in your repertoire. Make some for me so that I may become strong enough again to make a difference in this world.", ["objectivesText"] = "Craft an Enchant Cloak - Word of Strength vellum, an Enchant Ring - Word of Critical Strike vellum and an Enchant Ring - Word of Mastery vellum for Alynblaze . Progress: Once I have the power I need, we shall test both our strengths.", ["rewardXP"] = 1415, ["rewardItems"] = { 38682, 124440, 124441, 128537, 128539, 128545 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39891 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39907] = { ["id"] = 39907, ["name"] = "Elven Enchantments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39916, 39918, 39920, 39921, 40130, 40169 }, ["description"] = "You have earned the marks of my most trusted companions. You have also returned my love to me. I am fortunate to have met you, <name>. Now return to your master and let him know of what you have learned.", ["objectivesText"] = "Return to Nalthanis in Dalaran.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 107139, ["questType"] = "standard", ["sourceQuests"] = { 39910, 39914, 39918 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39910] = { ["id"] = 39910, ["name"] = "The Druid's Debt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "In order to grant you my mark, <class>, I must first be made strong enough to come to your aid should you need it. Within the ruins of Nar'thalas, my idols sit dormant. As I've said, I'm not strong enough to get them myself. But you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home. Find my idols and return them to me. Do this and I will grant you my mark.", ["objectivesText"] = "Find Merrus' Idol of the Paw , Idol of the Claw and Idol of the Moon and return them to him at the Crumbled Palace. Progress: Have you found them? Are they still intact?", ["rewardXP"] = 1415, ["rewardItems"] = { 137290, 137291, 137292 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98381, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98381, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39891 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39914] = { ["id"] = 39914, ["name"] = "Sentinel's Final Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39906 }, ["description"] = "Now that I'm stronger, it's time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill. His name is Fathom-Commander Eksis . He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows. I've finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.", ["objectivesText"] = "Slay Fathom-Commander Eksis . Return to Alynblaze at the Crumbled Palace when you are through. Progress: He will rue the day he ever set foot upon my homeland.", ["rewardXP"] = 1415, ["rewardItems"] = { 139494, 141912 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39906 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39916] = { ["id"] = 39916, ["name"] = "Turnabout Betrayal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39918, 39920, 39921, 40130, 40169 }, ["description"] = "Enchantress Ilanya remembers me? <The satyr pauses to wipe a tear away.> I made a fool's bargain ten millennia ago. I learned of the queen's alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals. Now the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.", ["objectivesText"] = "Defeat demons at the Felblaze Ingress. Take their Fel-crusted Runes and disenchant them into 5 Dust of Foul Lies . Return to where you met the Fallen Priestess when you are done. Progress: The death screams of the Legion bring me some semblance of joy.", ["rewardXP"] = 1415, ["rewardItems"] = { 129751, 137286 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40169 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39918] = { ["id"] = 39918, ["name"] = "The Absent Priestess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39920, 39921, 40130, 40169 }, ["description"] = "After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, <name>, I can at last return. Go and speak to Enchantress Ilanya . I will let her know that you are worthy of my mark.", ["objectivesText"] = "Return to Enchantress Ilanya at the Crumbled Palace in Azsuna.", ["rewardXP"] = 1415, ["rewardItems"] = { 69777 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98698, ["x"] = 0.399333, ["y"] = 0.362667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.399333, ["y"] = 0.362667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40130 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39920] = { ["id"] = 39920, ["name"] = "On Azure Wings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39921, 40130, 40169 }, ["description"] = "I have some exciting news of my own to report, <name>. Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose. One of the dragons, Kharmeera , is an enchanter who expressed interest in working with you to perfect some of our enchantments. I understand you were just down there working with the elves, but if you wouldn't mind returning, Kharmeera would enjoy working with you too.", ["objectivesText"] = "Speak to the dragon Kharmeera at Azurewing Repose in Azsuna.", ["rewardXP"] = 6140, ["rewardItems"] = { 69777 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 93531 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93531, ["questType"] = "standard", ["sourceQuests"] = { 39907 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39921] = { ["id"] = 39921, ["name"] = "Neltharion's Lair: Rod of Azure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39920, 40130, 40169 }, ["description"] = "Before we can begin though, there is a small favor I need to ask of you. I'm rather ashamed about this matter, to be honest, but it must be done in order for us to work together. When I was summoned to this land, I hadn't been given a chance to collect my things. Most importantly, I left behind my enchanting rod. Instead of retrieving it I believe it would be much simpler to reconstruct it. Here's what we'll need...", ["objectivesText"] = "Retrieve a Skystone Rod from Dargrul the Underking in Neltharion's Lair, a Radiant Zephyrite from Ozruk in The Stonecore and a pile of Ancient Arkhana from Scholomance. Progress: How goes the hunt for the rod components?", ["rewardXP"] = 6140, ["rewardItems"] = { 6218, 88566, 136615, 136616, 136617 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 39920 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39923] = { ["id"] = 39923, ["name"] = "Down to the Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings. According to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City. If you were to gather some friends and defeat these constructs, you could take their cores for us to study.", ["objectivesText"] = "Retrieve the Power Cores from Oldus, Or'ell, Olmoore, and Oll'ison. Bring them back to Kharmeera when you have all four. Progress: Remember to bring some friends with you, those constructs are incredibly powerful.", ["rewardXP"] = 6140, ["rewardItems"] = { 124442, 136622, 136623, 136624, 136625 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 39921 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 28, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39931] = { ["id"] = 39931, ["name"] = "Smashing Herbs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39847 }, ["description"] = "Now that the formalities are out of the way, let's have you do something actually useful. On the islands below, there's a plethora of new and exotic herbs that we've yet to experiment with. I'd like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I'll see what you've come up with.", ["objectivesText"] = "Obtain 20 Roseate Pigments and 2 Sallow Pigments . Pigments are obtained by milling herbs. Progress: Well? Do you have the pigments, or are you just wasting my time?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124103, 124124, 128304, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 137738, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39847 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39932] = { ["id"] = 39932, ["name"] = "Fish Ink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39933 }, ["description"] = "You know, herbs aren't the only ways to obtain ink. Other materials can be inkified. Slightly related! I've been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I. To do so, we'll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.", ["objectivesText"] = "Obtain 5 Mak'rana Oil, 5 Hatecoil Naga Oil, and 5 Salteye Oil , then combine them into a Piscine Pigment . Progress: My pigment?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129058, 129059, 129060, 129211, 136811, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39931 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39933] = { ["id"] = 39933, ["name"] = "The Card Shark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39932 }, ["description"] = "We have the pigment, but we still require one more ingredient. Visitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.", ["objectivesText"] = "Collect 10 Hearthstone Cards at the Legerdemain Lounge. Progress: The cards are just for reference, mostly...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129092, 129211, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39932 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39934] = { ["id"] = 39934, ["name"] = "Our New Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39935 }, ["description"] = "Have you seen those demon hunters yet? I'm not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them. Everybody needs glyphs, you know. Go see what you can discover about them. Azsuna is as good a place as any to start. Perhaps my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", ["objectivesText"] = "Go to Azsuna and find Allari the Souleater .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436, 174066 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39933 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39935] = { ["id"] = 39935, ["name"] = "The Price of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39934 }, ["description"] = "You wish to learn what it is to be a demon hunter? That may take some time. The first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them. Return to me when you are finished.", ["objectivesText"] = "Slay 15 demons at Illidari Strand. Progress: Have you seen enough?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39934 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39936] = { ["id"] = 39936, ["name"] = "Inscription of the Body", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39937, 39938, 39940, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do. Up to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.", ["objectivesText"] = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39935 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39937] = { ["id"] = 39937, ["name"] = "Opposites Repel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39938, 39940, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "There's a balance that must be struck, <name>, when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature. Fel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check. You are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.", ["objectivesText"] = "Collect 10 Ley Dust from the nightfallen and withered in the Ley-Ruins of Zarkhenar, then mix it into a Ley Pigment . Progress: Even though they are opposites, one can not exist without the other.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129105, 129211, 136821, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39936 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39938] = { ["id"] = 39938, ["name"] = "Containing the Demon Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39940, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "Now that we have all the essential pieces, let's begin the ritual. I'll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", ["objectivesText"] = "Assist Baric in completing the ritual.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98026, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39937 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39939] = { ["id"] = 39939, ["name"] = "Scribal Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "We do not simply fight the demons, <name>. We observe them. One of my best demon hunters, Zaria Shadowheart , is currently gathering intel on the demons in Felblaze Ingress. Go to her. She will teach you what she has learned from the demons invading that region.", ["objectivesText"] = "Find Zaria Shadowheart near the Felblaze Ingress in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39935 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39940] = { ["id"] = 39940, ["name"] = "Runes of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again. Study these runes.", ["objectivesText"] = "Study 8 Fel Power Runes .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39939, 40061 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[39941] = { ["id"] = 39941, ["name"] = "Control is Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "We demon hunters ritualistically remove our eyes in order to see the demons more clearly. Down below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check. Destroy his warding crystal, then slay him.", ["objectivesText"] = "Destroy the crystal protecting Overseer Felorax , then slay him.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39939 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
