[39943] = { ["id"] = 39943, ["name"] = "The Burdens of Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39941, 40058, 40059, 40060, 40063 }, ["description"] = "There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.", ["objectivesText"] = "Report back to Professor Pallin .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 }, { ["mapID"] = 630, ["npcID"] = 98026, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 97734, ["questType"] = "standard", ["sourceQuests"] = { 39938, 39940, 39941, 40060, 40063 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39944] = { ["id"] = 39944, ["name"] = "Mysterious Messages", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they're written in ancient vrykul, but I lent my codex to one of my students, so I'm unable to decipher them here. His name is Nicholo Swiftfuse , and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated. That is all.", ["objectivesText"] = "Deliver the tablets to Nicholo Swiftfuse in Stormheim.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39933 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39945] = { ["id"] = 39945, ["name"] = "Runes Within the Ruins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39946, 39947, 39951, 40052 }, ["description"] = "Unfortunately, Pallin's codex isn't complete. There are many symbols here that simply cannot be deciphered with what we've learned. Looks like we'll need to go and collect more tablets down in the area that the vrykul call Haustvald.", ["objectivesText"] = "Collect 10 Ancient Vrykul Rune Tablets within Haustvald. Progress: We need those tablets if we're to progress any further in deciphering their language.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129164, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39944 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39946] = { ["id"] = 39946, ["name"] = "Right Tool for the Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39945, 39947, 39951, 40052 }, ["description"] = "From what little I have been able to decipher, I know that the tablets are created using a special carving tool. If we had one of those tools, along with a complete codex, we could easily create our own tablet. That would also serve to prove that my deciphering of their language has been successful. Retrieve one of those tools for me, <name>.", ["objectivesText"] = "Acquire a Runic Bone Knife . Progress: The knife is the final key to my research. Any luck finding one?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 90347, 90348, 90349, 90350, 90351, 90352, 90353, 90354, 90355, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129169, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39944 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39947] = { ["id"] = 39947, ["name"] = "Not So Complex?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39945, 39946, 39951, 40052 }, ["description"] = "Alright, I believe I've finished adding the missing entries into the codex. And we have the machete... err, knife. All that's left is to make our own tablet and verify my other suspicion about these tablets: I believe that they're not just simple texts, but a sort of magical device.", ["objectivesText"] = "Assist Nicholo with the creation of a rune tablet.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129164, 129169, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39945, 39946 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39948] = { ["id"] = 39948, ["name"] = "The Ink Flows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39949, 39950 }, ["description"] = "<name>, I need you to make a quick delivery for me. Yes, I've learned by now that such trivial tasks are beneath your skills... but I'm rather busy right now and we both know my time is much more important than yours. Deliver these contracts to Raethan , the Guard Captain in Dalaran's Underbelly.", ["objectivesText"] = "Deliver the contracts to Raethan in the Underbelly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 40052 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39949] = { ["id"] = 39949, ["name"] = "Once a Scribe Like You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39948, 39950 }, ["description"] = "These sewers are something of a... \"settling place\" for many who can't cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract. His name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad. < Raethan hands you the contract.> This says he's stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.", ["objectivesText"] = "Kill Inkrot and obtain the Stolen Shadowruby . Progress: Did he give you much trouble?", ["rewardGold"] = 606600, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 129292, 139417, 139436 }, ["starts"] = { { ["x"] = 0.686, ["y"] = 0.596, ["mapID"] = 628, ["npcID"] = 97359 } }, ["ends"] = { { ["x"] = 0.686, ["y"] = 0.596, ["mapID"] = 628, ["npcID"] = 97359 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.686, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 97359, ["questTurnInID"] = 97359, ["questType"] = "standard", ["sourceQuests"] = { 39948 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[39950] = { ["id"] = 39950, ["name"] = "An Odd Trinket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39948, 39949 }, ["description"] = "Wait, <name>, before you leave... did you not notice this? < Raethan peels a small piece of paper from the bottom of the jewel.> This wasn't reported stolen. It appears to be a card of some kind. Must be a scribe thing. Perhaps it may be of some use to you.", ["objectivesText"] = "Give the Rotting Tarot Card to Professor Pallin . Progress: What's that you have there?", ["rewardGold"] = 238680, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034, 129177 }, ["starts"] = { { ["x"] = 0.686, ["y"] = 0.596, ["mapID"] = 628, ["npcID"] = 97359 } }, ["ends"] = { { ["x"] = 0.686, ["y"] = 0.596, ["mapID"] = 628, ["npcID"] = 97359 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.686, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 97359, ["questTurnInID"] = 97359, ["questType"] = "standard", ["sourceQuests"] = { 39949 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["startItems"] = { 129177 } },
