[39953] = { ["id"] = 39953, ["name"] = "Halls of Valor: Vision of Valor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39957 }, ["description"] = "I think it's time for another field trip, <name>. To the Halls of Valor! The Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.", ["objectivesText"] = "Retrieve 5 Valarjar Rune-Sigils from the Halls of Valor. Progress: Did you see any gods while you were there?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 131928, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "dungeon", ["sourceQuests"] = { 39943, 39950, 40052 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 40, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39954] = { ["id"] = 39954, ["name"] = "Mass Milling Techniques", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39955, 39956 }, ["description"] = "A number of my previous students have been vocal in their displeasure regarding milling. They find the process \"repetitive\", \"mindless\", and even \"painful\". Have they no respect for the time-honored traditions of inscription? I suppose you count yourself among their number. Am I right? Very well. You've been a fine student so far, so I suppose there's no harm. I have a book about mass milling somewhere around the shop here. Find it, and it's yours.", ["objectivesText"] = "Find The Masterful Miller's Manual in Dalaran's inscription shop. Progress: Try not to make too big a mess.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 124102, 124103, 124104, 124105, 124106, 128304, 129032, 129034, 136909, 136912, 136915, 136916, 136917, 136918, 136931 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questTurnInID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39933 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 33, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39955] = { ["id"] = 39955, ["name"] = "The Plot Thickens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 87, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39954, 39956 }, ["description"] = "Very well, I won't deny it. The Steamy Romance Novel is mine. I only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s! In fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge. Stop reading, student. You are dismissed. And give me my book back!", ["objectivesText"] = "Go to Ironforge and look for B. Spearshaker.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 97762, ["x"] = 0.765667, ["y"] = 0.091 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.765667, ["y"] = 0.091 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39961 }, ["nextQuests"] = { 39956 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 87 },
[39956] = { ["id"] = 39956, ["name"] = "The Legacy Passed On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39954, 39955 }, ["description"] = "I've lost my passion, scribe. I just can't get into the voice o' the characters anymore. Take a look at that unfinished book over there on the table. I can't seem to finish it. Maybe ye'll have an easier time with it.", ["objectivesText"] = "Complete the Unfinished Steamy Romance Novel. Progress: Dang-blasted writer's block!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 108649, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 97762, ["x"] = 0.765667, ["y"] = 0.091 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 97762, ["x"] = 0.765667, ["y"] = 0.091 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.765667, ["y"] = 0.091 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard", ["sourceQuests"] = { 39955 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 31, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 87 },
