"flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39958] = { ["id"] = 39958, ["name"] = "Skin Deep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40183 }, ["description"] = "Welcome, <name>. It's an honor to be working with someone of your caliber. In order for us to begin our work together, we'll first need to collect some materials. The Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We'll need scales to make mail armor with as well. Go and collect some materials for us so we may begin working.", ["objectivesText"] = "Acquire 20 Stonehide Leather and 5 Stormscales . If you are not a skinner, you may acquire them from the auction house or other players. Progress: I trust you gave the creatures a merciful death?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 139498, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
