[39961] = { ["id"] = 39961, ["name"] = "An Embarrassing Revelation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "This doesn't appear to be an inscription textbook at all... it's more of a steamy romance novel . The pages are just FILLED with tawdry tales of carnality. Could it have something to do with inscription? Either way, Professor Pallin should be confronted.", ["objectivesText"] = "Bring the Steamy Romance Novel to Professor Pallin .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["objectID"] = 244651 } }, ["ends"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["objectID"] = 244651 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.416, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 39933 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39962] = { ["id"] = 39962, ["name"] = "Trouble for Okuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8040, ["mapID"] = 630, ["storyline"] = { 39962 }, ["description"] = "Help! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard. I was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!", ["objectivesText"] = "Search for Okuna Longtusk.", ["rewardGold"] = 1213200, ["rewardXP"] = 2830, ["rewardItems"] = { 129054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8040 } }, ["questType"] = "dungeon" },
