[39983] = { ["id"] = 39983, ["name"] = "Huln's War - The Arrival", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39988, 39990, 39991, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes. Live his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.", ["objectivesText"] = "Defeat 25 Legion.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["ends"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["coords"] = { ["mapID"] = 652, ["x"] = 0.748, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questGiverID"] = 98825, ["questTurnInID"] = 98825, ["questType"] = "standard", ["sourceQuests"] = { 40520 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697 },
[39984] = { ["id"] = 39984, ["name"] = "Remnants of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "<The journal entry appears hastily written.> I do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed. Some have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return. In these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well. I do not know what will become of me. For now, I can only stay at my post and remain vigilant.", ["objectivesText"] = "Locate clues to discover the fate of Tideskorn Harbor.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.629, ["y"] = 0.484, ["mapID"] = 634, ["objectID"] = 244708 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[39985] = { ["id"] = 39985, ["name"] = "Khadgar's Discovery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 629, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39986, 39987, 40008, 40009, 40123, 44555 }, ["description"] = "Champion! Please come to the Violet Citadel immediately. I have made a discovery that I would like to share with you before the Council of Six.", ["objectivesText"] = "Speak with Archmage Khadgar in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140234 }, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.288, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["nextQuests"] = { 39986 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[39986] = { ["id"] = 39986, ["name"] = "Magic Message", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 627, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39987, 40008, 40009, 40123, 44555 }, ["description"] = "For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was. That barrier has come down. Since then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern. A spell, encrypted among the chaos. I have recreated the spell here. It's not dangerous, but beyond that... I have no idea what it does!", ["objectivesText"] = "Examine the Arcane Anomaly in Dalaran. Progress: Go ahead and take a look.", ["rewardGold"] = 50550, ["rewardXP"] = 1535, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054 }, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.288, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 39985, 44555 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[39987] = { ["id"] = 39987, ["name"] = "Trail of Echoes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 40008, 40009, 40123, 44555 }, ["description"] = "The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can. We should be able to find her by tracking her magical echoes, the same way I found her distress call. I can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself. My wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.", ["objectivesText"] = "Use Khadgar's Wand to find Arcane Echoes and track down First Arcanist Thalyssra . Progress: Who are you?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 131931, 136600, 136970, 140234, 141667, 142054 }, ["starts"] = { { ["x"] = 0.284, ["y"] = 0.483, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 39986 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[39988] = { ["id"] = 39988, ["name"] = "Huln's War - Stormrage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39990, 39991, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "< Eche'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>", ["objectivesText"] = "Meet Malfurion.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.279, ["y"] = 0.472, ["mapID"] = 697, ["npcID"] = 98794 } }, ["ends"] = { { ["x"] = 0.279, ["y"] = 0.472, ["mapID"] = 697, ["npcID"] = 98794 } }, ["coords"] = { ["mapID"] = 697, ["x"] = 0.279, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questGiverID"] = 98794, ["questTurnInID"] = 98794, ["questType"] = "standard", ["sourceQuests"] = { 40112 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697 },
[39989] = { ["id"] = 39989, ["name"] = "Keepers of the Hammer", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39989 }, ["description"] = "High Chieftain Ulan has requested your presence. We have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid. Our people have in our possession a great titan relic: the Hammer of Khaz'goroth. We intend to lend it to you for this task. When you are ready, join me at our stronghold of Thunder Totem in Highmountain .", ["objectivesText"] = "Meet the High-Chieftain at Thunder Totem in Highmountain .", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39990] = { ["id"] = 39990, ["name"] = "Huln's War - Reinforcements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39991, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed. But now, I ask for your help, Huln Highmountain . I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.", ["objectivesText"] = "Defend Malfurion. Progress: This shouldn't take long. Please do not allow them to interrupt my spell.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.278, ["y"] = 0.516, ["mapID"] = 697, ["npcID"] = 97892 } }, ["ends"] = { { ["x"] = 0.278, ["y"] = 0.516, ["mapID"] = 697, ["npcID"] = 97892 } }, ["coords"] = { ["mapID"] = 697, ["x"] = 0.278, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questGiverID"] = 97892, ["questTurnInID"] = 97892, ["questType"] = "standard", ["sourceQuests"] = { 39988 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697 },
[39991] = { ["id"] = 39991, ["name"] = "Blessing of Cenarius", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39991 }, ["series"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. Speak with him in the grove to the south. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(39991)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(39991))\");", ["objectivesText"] = "Meet with Cenarius.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39992] = { ["id"] = 39992, ["name"] = "Huln's War - The Nathrezim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "I am fully occupied here organizing my troops and planning for the battle to come. While I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain .", ["objectivesText"] = "Defeat Tichondrius .", ["rewardGold"] = 22600, ["rewardXP"] = 1415, ["rewardItems"] = { 130282, 130309, 246937, 257397 }, ["rewardChoices"] = { 130282, 130309 }, ["starts"] = { { ["x"] = 0.312, ["y"] = 0.524, ["mapID"] = 697, ["npcID"] = 97903 } }, ["ends"] = { { ["x"] = 0.312, ["y"] = 0.524, ["mapID"] = 697, ["npcID"] = 97903 } }, ["coords"] = { ["mapID"] = 697, ["x"] = 0.312, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questGiverID"] = 97903, ["questTurnInID"] = 97903, ["questType"] = "standard", ["sourceQuests"] = { 40388 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
