[40000] = { ["id"] = 40000, ["name"] = "A True Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["description"] = "I don't know why Hemet hunts with Razik. His contraptions are unreliable at best! A true hunter doesn't need gadgets to hunt. They rely on instinct, skill, and agility. So tell me, <name>, do you have the skills of a true hunter? Better yet, prove it. Take down some of the Bonebeak Hawks that circle the nearby meadow.", ["objectivesText"] = "Prove you're a worthy hunter by hunting Bonebeak Hawks in Sunfrost Glade. Progress: You can't be huntin' hawks if you're here chattin' at me.", ["rewardGold"] = 176280, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97974, ["x"] = 0.575333, ["y"] = 0.564667 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97974, ["x"] = 0.575333, ["y"] = 0.564667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.564667 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40001] = { ["id"] = 40001, ["name"] = "Knocking on Valor's Door", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40002, 40003, 40078 }, ["description"] = "The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness. Your dragon allies have come to Halls' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir . Free your dragon friend, champion, and wash the Felskorn from the Gates of Valor!", ["objectivesText"] = "Find Vethir in the Felskorn Camp.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40078 }, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40002] = { ["id"] = 40002, ["name"] = "A Familiar Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40001, 40003, 40078 }, ["description"] = "We had come to defend the Halls of Valor... I was taken from the sky... I cannot break free of my bindings. Find the jailer who made this cell... Set me free, friend...", ["objectivesText"] = "Collect the Jailer's Shard from Dravax and free Vethir from his prison. Progress: The jailer has... the key...", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 129106 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40001 }, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40003] = { ["id"] = 40003, ["name"] = "Stem the Tide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40001, 40002, 40078 }, ["description"] = "Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. If we wish to stem this tide, these portals must be destroyed. I will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!", ["objectivesText"] = "Use the Stormforged Horn to destroy the three Felbound Portals in Gates of Valor. Progress: The portals must be closed if we wish to stop Skovald's forces!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129161 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97986, ["x"] = 0.718, ["y"] = 0.7056 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40002 }, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40004] = { ["id"] = 40004, ["name"] = "Break the Spine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["description"] = "To lead his tainted forces, the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders. These demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. Take them down, and shatter the spine of Skovald's offensive!", ["objectivesText"] = "Defeat Garzareth , Karuas , Muorg and Ravathes in Gates of Valor. Progress: Are the leaders slain?", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97986, ["x"] = 0.718, ["y"] = 0.7056 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40002 }, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40005] = { ["id"] = 40005, ["name"] = "Stormheim's Salvation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40072 }, ["description"] = "It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor's edifice, summoned by the God-King himself! I cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat! For Stormheim !", ["objectivesText"] = "Defeat God-King Skovald in the Gates of Valor.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 246937 }, ["rewardChoices"] = { 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97986, ["x"] = 0.718, ["y"] = 0.7056 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97988, ["x"] = 0.702, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.7056 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40003, 40004 }, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
