[40008] = { ["id"] = 40008, ["name"] = "The Only Way Out is Through", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40009, 40123, 44555 }, ["description"] = "I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever. <Thalyssra lifts a delicate flask to her lips. Her eyes shimmer as she takes a sip.> If we push through, we may find shelter up ahead.", ["objectivesText"] = "Escort Thalyssra to safety. Progress: There is no turning back.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 39987 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40009] = { ["id"] = 40009, ["name"] = "Arcane Thirst", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40008, 40123, 44555 }, ["description"] = "My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there. <Thalyssra holds her flask aloft, gently shaking free the last precious drops.> I'm afraid I have been rather reckless today. Already, my senses are dulling. Without magic to feed upon, I will turn. Please... find me something to feed upon... anything...", ["objectivesText"] = "Enter Shal'Aran and find something to sate Thalyssra's thirst. Progress: <Thalyssra's eyes have dulled and her body is shaking uncontrollably.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054 }, ["rewardChoices"] = { 121804 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40123 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40010] = { ["id"] = 40010, ["name"] = "Tapping the Leylines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40010, 41028, 41138 }, ["series"] = { 41028 }, ["description"] = "The arcways were built to tap into the magical leylines beneath Suramar . As we learned to subsist on the Nightwell, the old facilities fell out of use. This chamber is clearly receiving power from elsewhere. There is only a trickle now, but if you can direct more leyline energy here it will help to sustain us. The closest source is to the north, near Anora Hollow.", ["objectivesText"] = "Explore Anora Hollow and find the Ley Station there.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40956 }, ["questLines"] = { { ["id"] = 155, ["name"] = "Feeding Shal'Aran", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 155, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40011] = { ["id"] = 40011, ["name"] = "Oculeth's Workshop", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "We need to make contact with Chief Telemancer Oculeth , the man who developed Suramar 's teleportation network. Oculeth had a workshop in old Suramar , from the age before the Sundering. He may be taking refuge there. <Thalyssra presses a small coin into your palm.> If you find him, show him this. Hopefully you see him before he sees you...", ["objectivesText"] = "Give the First Arcanist's Token to Chief Telemancer Oculeth . Progress: If we are to put up any resistance against the combined forces of the Legion and the Grand Magistrix, we must secure a means of traversing the region quickly.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 10506, 69777, 129039, 132883, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42229 }, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40012] = { ["id"] = 40012, ["name"] = "An Old Ally", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40326, 41702, 41704, 41760 }, ["description"] = "I was on my way to Ambervale in hopes of finding an old colleague. Arcanist Kel'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them. When one of his subjects escaped and ran amok in the royal gardens, Kel'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled. If Kel'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.", ["objectivesText"] = "Find Arcanist Kel'danath's hideout in Ambervale.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136600, 136970, 140349, 141668, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 97140, ["questType"] = "standard", ["sourceQuests"] = { 42229 }, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40013] = { ["id"] = 40013, ["name"] = "Aethril Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40014 }, ["description"] = "This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Aethril Sample to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 43200, ["rewardXP"] = 1415, ["rewardItems"] = { 129117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["startItems"] = { 129117 } },
[40014] = { ["id"] = 40014, ["name"] = "Spayed by the Spade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40013 }, ["description"] = "The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together. I suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts. Still, it looks like this bloom has been damaged. I need undamaged parts if I'm to be sure.", ["objectivesText"] = "Obtain a Pristine Pistil and a Stainless Stamen . Progress: It may seem wrong to remove these most... \"intimate\" flower parts, but do not fret. They will grow back. Much like the parts of a troll.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129128, 129131 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40013 }, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40015] = { ["id"] = 40015, ["name"] = "Ragged Strips of Silk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40016 }, ["description"] = "Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered. The feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?", ["objectivesText"] = "Speak with Kuhuine Tenderstride about aethril and the withered. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 129117, 129135 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40014 }, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["startItems"] = { 129135 } },
[40016] = { ["id"] = 40016, ["name"] = "Desperation Breeds Ingenuity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40015 }, ["description"] = "I believe we may be able to use this clue to our advantage, <name>. The withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.", ["objectivesText"] = "Obtain 6 Chewed Aethril Stems from Withered in Azsuna. Progress: I am glad you continue to come to my shop, <name>. I am useless with a weapon. We need adventurers like you to solve cases like this.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 129135, 129153 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40015 }, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40017] = { ["id"] = 40017, ["name"] = "A Slip of the Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["description"] = "As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction. You may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.", ["objectivesText"] = "Speak with Kuhuine Tenderstride about the quick-reproducing property of aethril.", ["rewardGold"] = 259748, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 129135 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40016 }, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40018] = { ["id"] = 40018, ["name"] = "Dreamleaf Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40019 }, ["description"] = "The herb is brilliantly green, paper-thin, and somewhat sticky. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Dreamleaf Sample to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129118 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["startItems"] = { 129118 } },
[40019] = { ["id"] = 40019, ["name"] = "An Empathetic Herb", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40018 }, ["description"] = "Something is different about this dreamleaf, though. It is less than pure. I have a theory. The wilds of Val'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight. I need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.", ["objectivesText"] = "Obtain 15 Healthy Dreamleaf and 5 Blight-Infested Dreamleaf . Progress: Those poor plants...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 129150, 129151, 136708 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40018 }, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40020] = { ["id"] = 40020, ["name"] = "Twisted to Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40021 }, ["description"] = "The corruption has completely taken this herb. This blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what's really going on here.", ["objectivesText"] = "Find someone in Lorlathil to teach you about the blight's effects on herbs. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129136 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 40019 }, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["startItems"] = { 129136 } },
[40021] = { ["id"] = 40021, ["name"] = "One Dead Plant is One Too Many", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40020 }, ["description"] = "We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it's corruption has gone TOO FAR! Satyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!", ["objectivesText"] = "Slay 20 satyrs within Val'sharah. Progress: Exact your bloody vengeance, <class>. Show them the might of an herbalist.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129136 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 40020 }, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40022] = { ["id"] = 40022, ["name"] = "Choked by Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40023 }, ["description"] = "Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight. You should bring it to Wildcrafter Osme in Lorlathil. He won't be happy.", ["objectivesText"] = "Bring the Blight-Choked Herb to Wildcrafter Osme in Val'sharah. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 129141 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 40021 }, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["startItems"] = { 129141 } },
[40023] = { ["id"] = 40023, ["name"] = "The Last Straw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40022 }, ["description"] = "We cannot falter in our crusade against this corruption, <name>. It is our duty as heroes. As herbalists. As hero-balists. Slaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala'nir, in the northeast. Find Tur'xoran 's summoning stone, and place this herb in front of it. Then... rip off his head. Do it for the plants.", ["objectivesText"] = "Use Tur'xoran 's Summoning Stone to summon and slay Tur'xoran . Progress: <The druid seethes.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "group", ["sourceQuests"] = { 40022 }, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40024] = { ["id"] = 40024, ["name"] = "Foxflower Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["description"] = "Something about this herb catches your eye... and your nose. Your herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.", ["objectivesText"] = "Obtain 20 samples of Foxflower , then bring them to Kuhuine Tenderstride in Dalaran. Progress: <The tauren sniffs the air.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124103, 129119 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129119 } },
[40025] = { ["id"] = 40025, ["name"] = "Teeny Bite Marks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["series"] = { 40026 }, ["description"] = "This herb has been chewed by some of the local wildlife. What kind of animal would eat foxflower? A bear? Perhaps your trainer in Dalaran will know.", ["objectivesText"] = "Bring the Nibbled Foxflower Stem to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129137 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40024 }, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129137 } },
[40026] = { ["id"] = 40026, ["name"] = "Chase the Culprit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["series"] = { 40025 }, ["description"] = "This is a powerful herb, <name>. Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency. I'm intrigued. What kind of animal would eat foxflower? A moose? You should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.", ["objectivesText"] = "Find out what creature has been eating Foxflower, then chase it and catch 12 Chewed Foxflower Bits . Progress: Did you find out what was eating the foxflower? Was it a goat? A beaver? A nightsaber?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 95416, 124103, 124124, 129137, 129220, 129278 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40025 }, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40028] = { ["id"] = 40028, ["name"] = "The Pied Picker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["description"] = "As you finish gathering the foxflower, a particular part of the bloom catches your eye. One of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from. Your herbalism trainer would be interested in seeing this.", ["objectivesText"] = "Bring the Foxflower Scent Gland to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129278 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40026 }, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129278 } },
[40029] = { ["id"] = 40029, ["name"] = "Fjarnskaggl Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["description"] = "To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed. Your herbalism trainer in Dalaran will want to see some more samples of this.", ["objectivesText"] = "Bring 20 Fjarnskaggl to Kuhuine Tenderstride in Dalaran. Progress: What do you have there, herbalist?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124104, 129120 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129120 } },
[40030] = { ["id"] = 40030, ["name"] = "Ram's-Horn Trowel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40031 }, ["description"] = "The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist. Apparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past. Perhaps she might be interested in seeing the tools that the vrykul use to harvest it.", ["objectivesText"] = "Bring the Ram's-Horn Trowel to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 259748, ["rewardXP"] = 1415, ["rewardItems"] = { 129138 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40029 }, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129138 } },
[40031] = { ["id"] = 40031, ["name"] = "Vrykul Herblore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40030 }, ["description"] = "<Kuhuine studies the trowel further.> This is a standard digging tool. There is not much to be learned here, except... ...this DOES suggest that the vrykul are still actively gathering this herb. The vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.", ["objectivesText"] = "Find three vrykul Herbology books in Stormheim. Progress: Any luck finding those books, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 129138, 129200, 129201, 129202 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40030 }, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40032] = { ["id"] = 40032, ["name"] = "The Missing Page", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40033 }, ["description"] = "\"...the Cairn of the Sea, a place long-known to be beloved by the gods. He placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\" This may be related to the books you brought back to your herbalism trainer.", ["objectivesText"] = "Bring the Runed Journal Page to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124104, 129135, 129142 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40031 }, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129142 } },
[40033] = { ["id"] = 40033, ["name"] = "Fjarnskaggl", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40032 }, ["description"] = "There! It seems that there was a vrykul herbalist, Torgus , who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors. <Kuhuine shrugs.> It's worth a shot, though without knowing what you're getting into, you may want to bring friends with you.", ["objectivesText"] = "Bring 20 Fjarnskaggl to the Wind-Worn Cairn in Stormheim, then earn the Blessing of Fjarnskaggl.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 137021 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "group", ["sourceQuests"] = { 40032 }, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40034] = { ["id"] = 40034, ["name"] = "Starlight Rosedust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40035 }, ["description"] = "Despite all your training, the rose disintegrated in your hand. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Starlight Rosedust to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 43200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 124105, 129121, 129158 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["startItems"] = { 129121 } },
[40035] = { ["id"] = 40035, ["name"] = "The Gentlest Touch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40034 }, ["description"] = "Sadly, I don't have any special techniques that can help you here. You'll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.", ["objectivesText"] = "Attempt to harvest 15 more Starlight Roses.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40034 }, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40036] = { ["id"] = 40036, ["name"] = "Jeweled Spade Handle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40037 }, ["description"] = "An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off. Your herbalism trainer may be interested in seeing this.", ["objectivesText"] = "Bring the Jeweled Spade Handle to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124105, 129140 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40035 }, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["startItems"] = { 129140 } },
[40037] = { ["id"] = 40037, ["name"] = "The Spade's Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40036 }, ["description"] = "Did you notice the script along the base of the handle, <name>? It says \"Herbalist Tharillon,\" in the writing of the nightborne. The handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often. I would start my search for it in Suramar.", ["objectivesText"] = "Find the Broken Herbalist's Blade . Progress: How goes your search?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124105, 129140, 129155 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40036 }, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40038] = { ["id"] = 40038, ["name"] = "Insane Ramblings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40039 }, ["description"] = "Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye: \"thinks knows how to gather herbs steal my blade slit THROAT when I just need a bit more mana maybe aethril, yes...\" Your herbalism trainer may be interested in seeing this.", ["objectivesText"] = "Bring the Scribbled Ramblings to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129143 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40037 }, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["startItems"] = { 129143 } },
[40039] = { ["id"] = 40039, ["name"] = "Tharillon's Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40038 }, ["description"] = "He mentions your name... his blade... aethril... I'd say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he's looking for aethril, he's probably in Azsuna somewhere. Tharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won't go without a fight.", ["objectivesText"] = "Bring 20 piles of Starlight Rosedust to Azsuna, use them to taunt Herbalist Tharillon out of hiding, then search him for information about herbalism. Progress: May the Earthmother walk with you, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124105, 129143, 129158, 129209 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "group", ["sourceQuests"] = { 40038 }, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40040] = { ["id"] = 40040, ["name"] = "Felwort Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40040, 40041, 40042 }, ["description"] = "This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Felwort Sample to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129122 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 257, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129122 } },
[40041] = { ["id"] = 40041, ["name"] = "Felwort Analysis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40040, 40041, 40042 }, ["description"] = "I sent felwort samples to some of my fellow herbalists, but haven't heard back from them yet. Could you please follow up with them and collect their analyses. Ryno Bloomfield is currently working in Un'goro Crater. Dani Earthtouch is researching Freya's influence in Sholazar Basin. Finally, Lohor has been working in the overgrown portion of Gorgrond.", ["objectivesText"] = "Collect Ryno Bloomfield's Analysis , Dani Earthtouch's Analysis , and Lohor's Analysis . Progress: Thank you for your willingness to travel, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 63206, 63207, 104113, 110560, 119093, 129212, 129213, 129214, 129929, 140192 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "standard", ["sourceQuests"] = { 40014, 40019, 40024, 40029, 40035, 40040 }, ["questLines"] = { { ["id"] = 257, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40042] = { ["id"] = 40042, ["name"] = "The Emerald Nightmare: Felwort Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40040, 40041, 40042 }, ["description"] = "I have a theory on how we can better harvest this felwort, <name>. You see, sometimes in order to understand how something comes into being, you have to work backwards. I've recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now. If you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.", ["objectivesText"] = "Travel to the Emerald Nightmare and cleanse Cenarius of his affliction. Bring back anything you discover to Kuhuine in Dalaran. Progress: I hope you bring some friends with you on this journey, for this may be your greatest lesson.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129289, 136413 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.338, ["mapID"] = 627, ["npcID"] = 92464 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.429, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92464, ["questTurnInID"] = 92464, ["questType"] = "raid", ["sourceQuests"] = { 40016, 40021, 40026, 40031, 40037, 40041 }, ["questLines"] = { { ["id"] = 257, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40043] = { ["id"] = 40043, ["name"] = "The Hunter of Heroes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 40043 }, ["description"] = "Helya has made a mockery of my order by creating her own \"helarjar\", powerful undead tasked with hunting down heroic warriors and taking their souls before my val'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago. He has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.", ["objectivesText"] = "Deal with Vigfus Bladewind's warband and claim his blades. Progress: Ah, you have returned...", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128288, 128289, 128908, 128910, 137663 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 40579, 43949, 44417 }, ["questLines"] = { { ["id"] = 215, ["name"] = "Hunter of Heroes", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 215, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[40044] = { ["id"] = 40044, ["name"] = "Shadows in the Mists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time. The ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade. So tell me, how kind is your soul?", ["objectivesText"] = "Defeat Captain Sten , Sigrid , Kjell and Halvir in Helmouth Shallows.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129350, 132770, 132771, 132772, 132773 }, ["rewardChoices"] = { 129350, 132770, 132771, 132772, 132773 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39984 }, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40045] = { ["id"] = 40045, ["name"] = "Nature vs. Nurture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "I appreciate murloc-kind far too much to tell you to go kill all the adults. What we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. Bring him to talk to the murloc tadpoles. He'll get them on our side.", ["objectivesText"] = "Talk to 10 Swamprock Tadpoles . Progress: Getting the support of the tadpoles is very important for our mission.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40244 }, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40046] = { ["id"] = 40046, ["name"] = "Scavenging the Shallows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions. They bring them here to transport to Helya, though the mists obscure any indications of how. You seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.", ["objectivesText"] = "Search the Shipwreck Debris in Helmouth Shallows for Havi 's clue. Progress: Have you found answers, or more questions?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129174 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39984 }, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40047] = { ["id"] = 40047, ["name"] = "I'll Huff, I'll Puff...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities. There are a lot of pufferfish around in the water, and I think that they could be a good resource for him. Kill a few and collect their eggs for Murky.", ["objectivesText"] = "Collect 5 Pufferfish Eggs . Progress: Pufferfish have this impressive ability of... exploding. They could be a powerful tool for Murky.", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 129183 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40244 }, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40048] = { ["id"] = 40048, ["name"] = "Strings of the Puppet Masters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39878 }, ["description"] = "I understand you were just here to deliver the vellums, but we could use your skills as a <class>. Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy's camp. The stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons. I would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.", ["objectivesText"] = "Acquire a Rune of Dominance from the demons at Legion Camp: Chaos. Progress: Have you found any runes yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 137185 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39876 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
