[40051] = { ["id"] = 40051, ["name"] = "Fel Secrets", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38725, 40222 }, ["description"] = "The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent. But there's only enough to enact one of the rituals. After that, the book will be consumed. It's up to you to choose which secrets we want to use against the Burning Legion.", ["objectivesText"] = "Read the Tome of Fel Secrets to choose between the Havoc and Vengeance specializations. Progress: Have you made up your mind?", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["starts"] = { { ["x"] = 0.605, ["y"] = 0.448, ["mapID"] = 672, ["npcID"] = 99045 } }, ["ends"] = { { ["x"] = 0.605, ["y"] = 0.448, ["mapID"] = 672, ["npcID"] = 99045 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.605, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 99045, ["questTurnInID"] = 99045, ["questType"] = "standard", ["sourceQuests"] = { 40222 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[40052] = { ["id"] = 40052, ["name"] = "Ancient Vrykul Mastered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39945, 39946, 39947, 39951 }, ["description"] = "Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I'll start getting my things ready for when he calls me back to Dalaran. <Nicholo sighs.> Learn from my example, <name>. If I were you, I'd break free from Pallin's \"requests\" as soon as you can.", ["objectivesText"] = "Return the tablets and codex to Professor Pallin .", ["rewardItems"] = { 128980, 129032, 129034 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 97748, ["questType"] = "standard", ["sourceQuests"] = { 39947 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40056] = { ["id"] = 40056, ["name"] = "Our New Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 40057 }, ["description"] = "Student! Your fellow demon hunters in Azsuna have sent for you. I can certainly appreciate your time being spent fending off the Legion, but it doesn't excuse you from your studies. While you're down there, I'd like you to come up with some new glyphs for your abilities. Surely my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", ["objectivesText"] = "Report to Allari the Souleater in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 174066 }, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.372, ["mapID"] = 627, ["npcID"] = 92195 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 92195, ["questType"] = "standard", ["sourceQuests"] = { 39933 }, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
