[40069] = { ["id"] = 40069, ["name"] = "Fledgling Worm Guts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "The drogbar use these caves as a place to train fledgling worms. The rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle. Their guts are also known to be quite useful, and I have need of them. Two worms, one stone.", ["objectivesText"] = "Collect Worm Guts from Fledgling Rockcrawlers within Rockcrawler Chasm. Progress: What are their guts for? Well, you'll see. You might not like it, but you will soon find out.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 137569 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40070] = { ["id"] = 40070, ["name"] = "Eagle Egg Recovery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "Eagles are revered by the Skyhorn tribe, but their numbers are dwindling. The drogbar feed their fledgling worms eagle eggs so they'll grow strong enough to ride into battle. If the drogbar continue to pilfer these eggs, the eagles may become extinct. Head deeper into the cave and recover any eagle eggs you can find.", ["objectivesText"] = "Head into Rockcrawler Chasm and recover eagle eggs . Progress: If the pilfered eggs are not recovered, the eagle may go extinct.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128760 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40071] = { ["id"] = 40071, ["name"] = "Tamer Takedown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "The drogbar will continue to breed vicious worms as long as their tamer lives. Korgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle. Head deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.", ["objectivesText"] = "Kill Tamer Korgrul within Rockcrawler Chasm. Progress: Put an end to Tamer Korgrul , so that we may also put an end to the training of siege worms.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121681, 121682, 121683, 121684, 121721 }, ["rewardChoices"] = { 121681, 121682, 121683, 121684, 121721 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40072] = { ["id"] = 40072, ["name"] = "Halls of Valor: Securing the Aegis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40005 }, ["description"] = "The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked. You, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald's broken bones! The Halls of Valor await!", ["objectivesText"] = "Defeat God-King Skovald in the Halls of Valor and claim the Aegis of Aggramar .", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 141402 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97988, ["x"] = 0.702, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97988, ["x"] = 0.702, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 97988, ["questType"] = "dungeon", ["sourceQuests"] = { 40005 }, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 5, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1477, ["db2PoiUiMapID"] = 705 },
[40077] = { ["id"] = 40077, ["name"] = "The Invasion Begins", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["description"] = "Our advance force of demon hunters is here and has engaged the Legion. Make our presence known. Let's send a shiver down every demon spine. Raise our colors with pride, <name>.", ["objectivesText"] = "Slay 15 demons and change the Legion banner to take control of Despair Ridge.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128953, 133317 }, ["rewardChoices"] = { 128953, 133317 }, ["starts"] = { { ["x"] = 0.221, ["y"] = 0.558, ["mapID"] = 672, ["npcID"] = 93011 } }, ["ends"] = { { ["x"] = 0.221, ["y"] = 0.558, ["mapID"] = 672, ["npcID"] = 93011 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.221, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 93011, ["questTurnInID"] = 93011, ["questType"] = "standard", ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[40078] = { ["id"] = 40078, ["name"] = "A Heavy Burden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 40001, 40002, 40003 }, ["description"] = "With Ashildir's judgment, your final trial is complete. But even Valhallas can wait, for now we must eat! Being dead works up quite an appetite. Come now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.", ["objectivesText"] = "Take the fish from Havi 's Fish Barrel and skewer it on the spear above the fire.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 133813 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39855 }, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
