[40102] = { ["id"] = 40102, ["name"] = "Murlocs: The Next Generation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "The time has come! Murky and his followers need a place to hide out and train--away from the mature murlocs--so that they can prepare to take over in the future. There's a nice cave not too far away... only problem is that it's filled with makrura. This would be a good base for the tadpoles. Murky must go show them what for! Mindmeld with Murky in his egg and show him how it's done!", ["objectivesText"] = "Mindmeld with Murky and slay 10 Cavemoss Clackers . Progress: These young murlocs show such promise. They'll do this shore good.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132183, 132184, 133818 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40045, 40047, 40049 }, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
