[40120] = { ["id"] = 40120, ["name"] = "A Murky Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40120 }, ["description"] = "You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end. The creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites. This is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.", ["objectivesText"] = "Use the Smoldering Torch to burn 8 Decaying Corpses in Morheim. Progress: Have you done this task?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129725 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98587, ["x"] = 0.782, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98587, ["x"] = 0.782, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[40121] = { ["id"] = 40121, ["name"] = "Ley Line Influences", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 15, ["amount"] = 1, ["objectID"] = 0, ["text"] = "Ley Line Influences" }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 100, ["objectID"] = 98585, ["text"] = "1 Point Kill" }, { ["orderIndex"] = 2, ["type"] = 0, ["amount"] = 50, ["objectID"] = 98749, ["text"] = "2 Point Kill" } } },
[40122] = { ["id"] = 40122, ["name"] = "Cenarius, Keeper of the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38384, 40122 }, ["series"] = { 39731, 39861 }, ["description"] = "Ahh, Val'sharah . It has been an age since I have set foot in these sacred woods. Too long... Our work here is simple, <class>. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.", ["objectivesText"] = "Speak to Malfurion Stormrage at Lorlathil in Val'sharah . Progress: Cenarius!", ["rewardGold"] = 5865, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91462, ["x"] = 0.546, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39861 }, ["questLines"] = { { ["id"] = 184, ["name"] = "Nature's Call", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 184, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40123] = { ["id"] = 40123, ["name"] = "The Nightborne Pact", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40008, 40009, 44555 }, ["description"] = "<Thalyssra winces and holds her abdomen.> Ngh... I can ignore this wound no longer. Help me patch this up. I will explain everything.", ["objectivesText"] = "Bandage Thalyssra.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40008 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40125] = { ["id"] = 40125, ["name"] = "Branch of the Arcan'dor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "You have used the spellstone of Kel'danath to soothe countless withered. Yet it contains merely a shade of the arcan'dor's power, drawn from its slumbering seed. <Thalyssra holds aloft a gleaming white branch.> This fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan'dor together. I have enchanted this branch with a new iteration of Kel'danath's charm spell. With it, you can mend the arcane essence of even more withered. Use it well.", ["objectivesText"] = "Speak with Thalyssra.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44156 }, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40129] = { ["id"] = 40129, ["name"] = "Repairing the Source", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40129 }, ["series"] = { 40238, 47508 }, ["description"] = "<A glint catches your eye in the dirt. A brief excavation yields a mostly intact piece of an arcane construct's power core. The breaks appear to be clean, perhaps you could repair it if you find the other fragments.>", ["objectivesText"] = "You have found a damaged power core for an arcane construct. It seems like you could repair the device.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["rewardItems"] = { 130075, 130088 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40130] = { ["id"] = 40130, ["name"] = "Washed Clean", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39920, 39921, 40169 }, ["description"] = "Mighty though the Legion is, theirs is not the strongest power in Azeroth. There is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, <name>. Go to the Nor'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well. I will meet you there.", ["objectivesText"] = "Meet the Fallen Priestess at the Nor'Danil Wellspring. Watch as the priestess attempts the purification ritual. Progress: It... it worked! I am myself again at last!", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98698, ["x"] = 0.399333, ["y"] = 0.362667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39916 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40131] = { ["id"] = 40131, ["name"] = "Stonehide Leather Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40132 }, ["description"] = "The quality of this leather scrap appears representative of the beast hides found in the Broken Isles. Your skinning trainer in Dalaran would be interested in seeing this.", ["objectivesText"] = "Bring the Stonehide Leather Sample , along with 10 additional pieces of Stonehide Leather , to Kondal Huntsworn in Dalaran. Progress: How may I help you?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129860, 129862, 130064, 130102, 139490 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["startItems"] = { 129860 } },
[40132] = { ["id"] = 40132, ["name"] = "In One Piece", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40131 }, ["description"] = "<Your trainer looks over the hide.> This hide is usable, but it is mournably small. You disrespect the beast by chopping it up like this, <name>. You make light of the gift that it gave to you. Go out into the wilds again. Skin the leathery beasts below us, and this time, bring me hides in one piece.", ["objectivesText"] = "Obtain 20 Undivided Hides by skinning the beasts of the Broken Isles. Progress: <Kondal sternly watches you approach.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129888, 130064, 130102 }, ["starts"] = { { ["x"] = 0.359, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 93541 } }, ["ends"] = { { ["x"] = 0.359, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 93541 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.359, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questTurnInID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40131 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40133] = { ["id"] = 40133, ["name"] = "Scrap of Pants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["description"] = "The mouth of this particular beast contained a piece of handsewn cloth. The fabric bears the word \"singwa\". While the term \"singwa\" is unfamiliar, it DOES happen to be the middle of the last name of a fairly notable Azerothian skinner.", ["objectivesText"] = "Bring the Scrap of Pants to Hemet Nesingwary in Highmountain. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129864, 130064, 130102 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40132 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["startItems"] = { 129864 } },
[40134] = { ["id"] = 40134, ["name"] = "Highmountain Hides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["description"] = "So, ye're a skinner too, aye? That's great news, <name>! I don't think I ever knew we shared that in common. Ye've GOT ta see some o'the hides we've got here in Highmountain. Why, I'd give me spare monacle just t'get me hands on some o'those fine, silky hides...", ["objectivesText"] = "Obtain 5 Bear Hides , 5 Elderhorn Hides , and 5 Saber Hides by skinning the creatures of Highmountain. Progress: <Hemet looks lustfully at the horizon.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129900, 129901, 129903, 130064, 130102 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40133 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40135] = { ["id"] = 40135, ["name"] = "The Freedom to Roam", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["description"] = "I remember bein' young, <name>. D'ye remember it? So much less responsibility... I could just run around as I pleased. Now, I'm pretty much stuck with my hunting crew, here in Highmountain. There're so many interestin' creatures in the other regions o'the Broken Isles, though. I'll mark yer map, you get out there and do some skinnin'!", ["objectivesText"] = "Obtain 5 Musken Hides , 5 Lion Seal Hides , 5 Boar Hides, and 5 Wolf Hides . Progress: Once ye're done, I'll show ye a trick or two.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129904, 129905, 129906, 130064, 130102, 140856 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40133 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40136] = { ["id"] = 40136, ["name"] = "Immaculate Stonehide Leather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40137 }, ["description"] = "You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored... Your trainer in Dalaran would be VERY interested in seeing this.", ["objectivesText"] = "Bring the Immaculate Stonehide Leather to Kondal Huntsworn in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129866, 130064, 130102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40135 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["startItems"] = { 129866 } },
[40137] = { ["id"] = 40137, ["name"] = "Leather for Ske'rit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40136 }, ["description"] = "This hide certifies that you have learned everything about leather that I can teach you, <name>. My skills have dulled since I set up shop here in town. I have a former protege who skins the creatures of Suramar. His name is Ske'rit . His skills remain as sharp as his blade, and if there is anyone out there who can teach you, it is him.", ["objectivesText"] = "Report to Ske'rit in Suramar.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102 }, ["starts"] = { { ["npcID"] = 93541, ["x"] = 0.3608, ["y"] = 0.2796, ["mapID"] = 627 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40136 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[40138] = { ["id"] = 40138, ["name"] = "Trial of the Crusader: Hides of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40139, 40140 }, ["description"] = "Ya, I can train you. Ting is, I'm still workin' on my techniques 'ere in Suramar. In fact, you can probably help. I need ta look at a few special skins, for comparison. I need a strong white yeti pelt, a really big demon skin, and da thickest direhorn skin you can find. Do that, and I'll share my results with you and' ol' Kondal up in de city.", ["objectivesText"] = "Obtain the Hide of Icehowl from the Trial of the Crusader. Obtain the Hide of Occu'thar from Baradin Hold. Obtain the Hide of Horridon from the Throne of Thunder. Progress: Any luck findin' dose hides?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 46874, 124113, 124115, 124116, 129912, 129913, 129914, 130064, 130102 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "raid", ["sourceQuests"] = { 40137 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40139] = { ["id"] = 40139, ["name"] = "Halls of Valor: The Hide of Fenryr", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 680, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40138, 40140 }, ["description"] = "While you be here, I got a favor t'ask you. I been hearin' whispers about one big, nasty wolf dat's been causin' all kinds of trouble up in de vrykul lands. His name be Fenryr. I want his hide.", ["objectivesText"] = "Obtain the Hide of Fenryr by skinning Fenryr in Valhallas. Progress: Is it done? Let me see it!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129920, 130064, 130102 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7672 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40137 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40140] = { ["id"] = 40140, ["name"] = "Ske'rit's Leather Handbook", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40131, 40132, 40133, 40134, 40135, 40136, 40137, 40138, 40139, 40140 }, ["series"] = { 40138, 40139 }, ["description"] = "An' wit dat, my research be done. < Ske'rit hands you a scroll casing.> Dis is what I been workin' on here in Suramar. Bring it to Kondal, so dat he can teach it to all you other skinnahs. Since you been helpin' so much, I put your name on it, <name>. Hope you don't mind.", ["objectivesText"] = "Bring Ske'rit 's Leather Handbook to Kondal Huntsworn in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129866, 130064, 130102 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 98720, ["questType"] = "standard", ["sourceQuests"] = { 40138, 40139 }, ["questLines"] = { { ["id"] = 181, ["name"] = "Legion Skinning", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40141] = { ["id"] = 40141, ["name"] = "Stormscale Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["description"] = "This scale shimmers with electrical energy. Your skinning trainer in Dalaran would be interested in seeing this.", ["objectivesText"] = "Bring the Stormscale Sample to Kondal Huntsworn in Dalaran. Provided item:", ["rewardGold"] = 43200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129862, 130064, 130102, 139490 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["startItems"] = { 129862 } },
[40142] = { ["id"] = 40142, ["name"] = "The Core of the Stormscale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["description"] = "Ahh, yes. The elusive stormscale. I have seen similar scales in Northrend, and some in Skywall, but it would appear that such a scale is common here. My colleagues that specialize in mail armor will be happy to learn this. To more efficiently harvest this type of scale, you must first understand its power. Look for broken, unusable scales on your quarry, and remove the sparks within them. Once you have seen the sparks, you will better understand the stormscale.", ["objectivesText"] = "Obtain 20 Stormscale Sparks by skinning scaled creatures in the Broken Isles. Progress: Have you seen the sparks?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129894, 130064, 130102 }, ["starts"] = { { ["x"] = 0.358, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 93541 } }, ["ends"] = { { ["x"] = 0.358, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 93541 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.358, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questTurnInID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40141 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40143] = { ["id"] = 40143, ["name"] = "Unfinished Treatise on the Properties of Stormscale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["description"] = "Tucked between the folds of this animal's hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use. Perhaps your skinning trainer in Dalaran could help you find its owner.", ["objectivesText"] = "Bring the Unfinished Treatise on the Properties of Stormscale to Kondal Huntsworn in Dalaran. Provided item:", ["rewardGold"] = 278548, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129865, 130064, 130102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40142 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["startItems"] = { 129865 } },
[40144] = { ["id"] = 40144, ["name"] = "Glielle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40145 }, ["description"] = "One skinner makes the wilds of Azsuna her home. Her name is Glielle , and she is a night elf - or at least, she was, in life. Perhaps the scroll was hers.", ["objectivesText"] = "Find Glielle in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129865, 130064, 130102 }, ["starts"] = { { ["x"] = 0.359, ["y"] = 0.285, ["mapID"] = 627, ["npcID"] = 93541 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98791, ["x"] = 0.47, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40143 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40145] = { ["id"] = 40145, ["name"] = "Under Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40144 }, ["description"] = "I can train you, though. Everyone knows about the bright stormscales on the hippogryph's hindquarters, but did you know that they also have a few scales beneath their feathers? You just need to know where to look. <The night elf spirit indicates a few places near the hippogryph's wing joints.> Now go see if you can get some on your own.", ["objectivesText"] = "Obtain 20 Hippogryph Scales . Progress: Remember to check the entire beast, not just what's visible on the surface.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129865, 129908, 130064, 130102 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98791, ["x"] = 0.47, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98791, ["x"] = 0.47, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40144 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40146] = { ["id"] = 40146, ["name"] = "Seymour and Agnes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["description"] = "The other skinner - pair of skinners, to be honest - that comes to mind when you show me this scroll is a student of mine, named Seymour , and his mother Agnes. Last I heard, they were in Stormheim, hunting the storm drakes.", ["objectivesText"] = "Find Seymour in Stormheim.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129865, 130064, 130102 }, ["starts"] = { { ["x"] = 0.359, ["y"] = 0.285, ["mapID"] = 627, ["npcID"] = 93541 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40143 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40147] = { ["id"] = 40147, ["name"] = "Mother's Prized Knife", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40148, 40149 }, ["description"] = "The other day, Mother and I were up at the top of the nearby mountain, and she threw her skinning knife at me because the view wasn't good enough. Her knife is still up there, somewhere. I'd feel horrible just leaving it.", ["objectivesText"] = "Obtain Agnes' Skinning Knife . Progress: Mother always wanted to live long enough to see me die. Why did this have to happen!?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129910, 130064, 130102, 141605 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40146 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40148] = { ["id"] = 40148, ["name"] = "Red-Eyed Revenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40147, 40149 }, ["description"] = "It came out of nowhere. I was waiting for mother to finish skinning her half of the drake when the biggest storm dragon I'd ever seen came and... and... < Seymour finds his resolve.> I want you to kill as many of them as you can. Skin them, don't skin them, I don't care. Just get revenge for mother!", ["objectivesText"] = "Slay 15 Adult Squallhunters .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40146 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40149] = { ["id"] = 40149, ["name"] = "Drakol'nir Must Die", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40147, 40148 }, ["description"] = "The dragon that took Mother's life was named Drakol'nir. Mother always wanted to wear his scale as a pendant, but we never got a chance to skin him because I couldn't kill him alone, and she didn't care much for killing. Only skinning. You... you wouldn't mind bringing it for her, would you?", ["objectivesText"] = "Obtain the Scale of Drakol'nir . Progress: Even if I COULD have killed Drakol'nir, I never would have been able to drag him all the way down here.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129911, 130064, 130102 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98721, ["x"] = 0.456, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40147, 40148 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40151] = { ["id"] = 40151, ["name"] = "Immaculate Stormscale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40152 }, ["description"] = "You have been skinning for a long time now, but never have you seen a scale specimen as fine as this. Your trainer in Dalaran would be VERY interested in seeing this.", ["objectivesText"] = "Bring the Immaculate Stormscale to Kondal Huntsworn in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129867, 130064, 130102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40145 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["startItems"] = { 129867 } },
[40152] = { ["id"] = 40152, ["name"] = "Scales for Ske'rit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40151 }, ["description"] = "Your skills surpass mine, <name>. I have never even SEEN a scale such as this... let alone remove one so expertly. If you still wish to learn more, you will need to seek an even greater skinner than I. His name is Ske'rit , and he was once my student. You will find him in the wild areas of Suramar.", ["objectivesText"] = "Find Ske'rit in Suramar.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102 }, ["starts"] = { { ["npcID"] = 93541, ["x"] = 0.3608, ["y"] = 0.2796, ["mapID"] = 627 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40151 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40153] = { ["id"] = 40153, ["name"] = "Return to Karazhan: Scales of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4493, ["mapID"] = 680, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40154, 40155 }, ["description"] = "I know a ting or two about scales, but I'm losin' my edge. I been starin' at stormscales so long, I be forgettin' what de other kinds look like. I need ta look at a few special scales, for comparison. I need a nether dragon scale, a nice hot black dragonscale, and da thickest piece o' insect chitin you can find. Gotta get dese stormscales outta my head, bruddah.", ["objectivesText"] = "Obtain the Scale of Netherspite from Karazhan, the Scale of Sartharion from the Obsidian Sanctum, and the Scales of Garalon from the Heart of Fear. Progress: You been gone a while. You get de scales?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 43345, 52251, 124113, 124115, 124116, 129867, 129915, 129916, 129917, 130064, 130102 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 4493 } }, ["questType"] = "raid", ["sourceQuests"] = { 40152 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40154] = { ["id"] = 40154, ["name"] = "Eye of Azshara: The Scales of Serpentrix", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40153, 40155 }, ["description"] = "I got ta ask you a favor. I haven't been ta Azsuna, and I don't see myself leavin' Suramar anytime soon. Problem is, dere's a big ol' serpent out dere dat's just beggin' ta be skinned. Just BEGGIN' for it.", ["objectivesText"] = "Obtain the Scales of Serpentrix by skinning Serpentrix in the Wrath of Azshara dungeon. Progress: You got dis, skinnah.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129921, 130064, 130102 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40152 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40155] = { ["id"] = 40155, ["name"] = "Ske'rit's Scale-Skinning Suggestions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40141, 40142, 40143, 40144, 40145, 40146, 40147, 40148, 40149, 40151, 40152, 40153, 40154, 40155 }, ["series"] = { 40153, 40154 }, ["description"] = "Now dat I got all dese scales, I tink I know what I need to know. < Ske'rit hands you a few pages of handwritten notes.> Here's my latest findin's on stormscales. Bring 'em to Kondal, an' read through em' togethah.", ["objectivesText"] = "Bring Ske'rit 's Scale-Skinning Suggestions to Kondal Huntsworn in Dalaran.", ["rewardGold"] = 238680, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 124116, 129867, 130064, 130102 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 98720, ["questType"] = "standard", ["sourceQuests"] = { 40153, 40154 }, ["questLines"] = { { ["id"] = 251, ["name"] = "Legion Skinning", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40156] = { ["id"] = 40156, ["name"] = "Felhide Sample", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40156, 40157, 40158, 40159 }, ["description"] = "This demonic hide is completely unlike any standard beast hide you are accustomed to. Your skinning trainer in Dalaran would be interested in seeing this.", ["objectivesText"] = "Bring the Felhide Sample to Kondal Huntsworn in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124115, 124116, 129863, 130064, 130102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 252, ["name"] = "Legion Skinning", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["startItems"] = { 129863 } },
[40157] = { ["id"] = 40157, ["name"] = "An Unseemly Task", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 40156, 40157, 40158, 40159 }, ["series"] = { 40158 }, ["description"] = "I'm quite impressed with what you've been able to skin in these lands, felhide in particular. But as my knowledge is limited in this area of skinning, I know of one who may have increased his skill in skinning such beasts. You can find my old apprentice, Ske'rit in Suramar. Ask him if he knows how to yield better results from skinning demons.", ["objectivesText"] = "Find Ske'rit in Suramar.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102 }, ["starts"] = { { ["npcID"] = 93541, ["x"] = 0.3608, ["y"] = 0.2796, ["mapID"] = 627 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40156 }, ["questLines"] = { { ["id"] = 252, ["name"] = "Legion Skinning", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40158] = { ["id"] = 40158, ["name"] = "Darkheart Thicket: Demons Be Different", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40156, 40157, 40158, 40159 }, ["series"] = { 40157 }, ["description"] = "Oh yes, I've seen me fair share of demons while in dese lands. And skinnin' dem ain't no easy task. Their hides are tougher than normal animals, fibrous, see? But if you be wantin' to make da most of their skins, den ya need to be practicin' more. There be a creature I've heard of in da Darkheart Thicket whose hide's as tough as a demon's. When ya go ta skin him, try cutting with da grain in one even stroke. Bring me his skin to show me you be picking up on what I'm sayin'.", ["objectivesText"] = "Go to Darkheart Thicket and kill Dresaron. Skin him and bring his hide back to Ske'rit in Suramar. Progress: Any luck on gettin' dat skin?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102, 136578 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40157 }, ["questLines"] = { { ["id"] = 252, ["name"] = "Legion Skinning", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40159] = { ["id"] = 40159, ["name"] = "The Emerald Nightmare: The Pestilential Hide of Nythendra", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40156, 40157, 40158, 40159 }, ["description"] = "There is one more demon hide to gather... but it isn't that of a demon. It's a dragon. Nythendra, great green dragon, has nearly been eaten up by the Nightmare. Only a master skinner would be able to remove what bits of bug-eaten hide remain on her body. Go on then, <name>. Show me what you've learned.", ["objectivesText"] = "Obtain the Pestilential Hide of Nythendra . Progress: Any luck with the dragon?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102, 140654 }, ["starts"] = { { ["npcID"] = 93541, ["x"] = 0.3608, ["y"] = 0.2796, ["mapID"] = 627 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93541, ["questType"] = "standard", ["sourceQuests"] = { 40158 }, ["questLines"] = { { ["id"] = 252, ["name"] = "Legion Skinning", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40160] = { ["id"] = 40160, ["name"] = "Magic Clams", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40160 }, ["description"] = "What are murlocs doing with arcane clams? Perhaps your Nightfallen allies could make use of them.", ["objectivesText"] = "Collect Infused Clams from Seerspine murlocs in the Murloc Shoals.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["startItems"] = { 129756 } },
[40161] = { ["id"] = 40161, ["name"] = "Tapping the Underground", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40161 }, ["description"] = "Have you seen them, ? These are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. Somehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes. These disturbances must be stopped if the ley line is to remain intact.", ["objectivesText"] = "Destroy Seerspine Conduits in the Murloc Shoals.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
