[40164] = { ["id"] = 40164, ["name"] = "REUSE", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40164 }, ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2VignetteID"] = 1105, ["db2VignetteName"] = "Treasure Chest" },
[40166] = { ["id"] = 40166, ["name"] = "Leying with Murlocs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40166 }, ["description"] = "I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river. I doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus. Blargrrrl will be deeply entranced if he is trying such a feat. We'll need something powerful to halt his ritual. Infuse yourself with ley energies and return to me.", ["objectivesText"] = "Infuse yourself with ley energies located in the Murloc Shoals.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[40167] = { ["id"] = 40167, ["name"] = "The Story of Huln", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40388, 40515, 40520 }, ["description"] = "You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain. Huln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.", ["objectivesText"] = "Speak with Spiritwalker Ebonhorn to learn about Huln Highmountain . Progress: The history of this place extends beyond our limited memory.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["ends"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["coords"] = { ["mapID"] = 652, ["x"] = 0.748, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98825, ["questTurnInID"] = 98825, ["questType"] = "standard", ["sourceQuests"] = { 40515 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40168] = { ["id"] = 40168, ["name"] = "The Swirling Vial", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Outland Timewalking Dungeon Event", ["expansion"] = 6, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 40168 }, ["description"] = "As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A'dal's light shining behind you. Despite your best efforts however, you can't pinpoint when that might have been - maybe it hasn't been, and is yet to be?", ["objectivesText"] = "Bring the Swirling Timewarped Vial to the central dome in Shattrath.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 98685, ["x"] = 0.545, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard", ["startItems"] = { 129747 } },
[40169] = { ["id"] = 40169, ["name"] = "Crossroads Rendezvous", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39920, 39921, 40130 }, ["description"] = "An old apprentice of mine left during the war, shortly before we were all cursed. I've recently heard that she's been seen near the Felblaze Ingress. I would very much like to speak to her once more. Go and find her. Take her journal to her and let her know that I don't blame her for what she did. And if she's willing, please bring her back to me.", ["objectivesText"] = "Search for signs of the priestess near the Felblaze Ingress. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 129740 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 39891 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40170] = { ["id"] = 40170, ["name"] = "Amateur Hour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 39859, 40216, 40217 }, ["description"] = "The hunters' lodge has attracted a lot of amateurs who call themselves hunters. They're scarin' away all the prize game with their antics. While I'm a known expert with my rifle, I've yet to manage the art of negotiation. How about ya do us all a favor and tell those novice hunters to head for the hills?", ["objectivesText"] = "Confront Amateur Hunters within Pinerock Basin. Progress: Have those amateur hunters scattered? Don't be afraid to use your fists if words don't do the job.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39417, 40217 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40173] = { ["id"] = 40173, ["name"] = "The Unstable Prism", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Northrend Timewalking Dungeon Event", ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 118, ["storyline"] = { 40173 }, ["description"] = "As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.", ["objectivesText"] = "Deliver the Frigid Timewarped Prism to an interested mage in Dalaran .", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44935, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 500 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["startItems"] = { 129928 } },
