[40176] = { ["id"] = 40176, ["name"] = "From Head to Toe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "You've been busy, <name>. And you have some new patterns in your repertoire, I see! How about we add another?", ["objectivesText"] = "Craft a pair of Sturdy Stonehide Boots . You will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers. Progress: I'm very excited to see how this turns out.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129964, 130872, 130873, 130874, 130891, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40179, 40181, 40182 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40177] = { ["id"] = 40177, ["name"] = "Leather Lady", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "I'd like you to start working with my apprentices. The first is Diane Cannings , who has focused her expertise on the softer leather armors. She's just not that into mail armor, like the twins are. Go talk to her about this new type of leather.", ["objectivesText"] = "Meet with Diane Cannings .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40183 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40178] = { ["id"] = 40178, ["name"] = "Vestment Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest. Go to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.", ["objectivesText"] = "Obtain a Hideshaper's Vestment . Progress: How's your search going?", ["rewardGold"] = 182760, ["rewardXP"] = 1415, ["rewardItems"] = { 129971, 138111, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93522, ["questTurnInID"] = 93522, ["questType"] = "standard", ["sourceQuests"] = { 40177 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40179] = { ["id"] = 40179, ["name"] = "Stormheim Savagery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "There's a land below - Stormheim, they call it - that's inhabited by vrykul. I remember the vrykul from my days in Northrend. What I remember most was how well-crafted their armor was. If the vrykul here are as skilled as the ones in Northrend, then I'm certain we can learn something by studying their armaments.", ["objectivesText"] = "Obtain 7 Vrykul Leather Bindings . Progress: Are the vrykul giving you much trouble?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129972, 138111, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93522, ["questTurnInID"] = 93522, ["questType"] = "standard", ["sourceQuests"] = { 40177 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40180] = { ["id"] = 40180, ["name"] = "Mail Men", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "The two dwarves behind me are the Glowergold brothers. They're my resident mail armor experts. While Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade. Introduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.", ["objectivesText"] = "Meet with Thanid Glowergold .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40183 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40181] = { ["id"] = 40181, ["name"] = "Black Rook Bandit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "I've heard rumors of a grand castle in Val'sharah that's known to house an impressive army. Surely, the armor they wear ain't made of sticks and hay. I'm willing to bet they've fashioned some mail armor at some point fer their troops and it's just sitting there, ripe for the taking. How about ye head over there and see what ye can \"borrow\" from their armory.", ["objectivesText"] = "Obtain 5 pieces of Black Rook Armor . Progress: Make sure ye don't get captured now, lad.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129973, 129974, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98931, ["questTurnInID"] = 98931, ["questType"] = "standard", ["sourceQuests"] = { 40180 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40182] = { ["id"] = 40182, ["name"] = "Too Good To Pass Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "All types of Black Rook Hold armor are intriguing, but I'm most interested in their chest pieces. If ye can, try to find someone of importance there and... relieve them of their shirt. If it makes ye feel any better, I've heard they're all cursed, so puttin' them out of their misery is the least ye could do.", ["objectivesText"] = "Obtain a Black Rook Hauberk . Progress: Chest armor is the best armor, I always say!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129973, 129974, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98931, ["questTurnInID"] = 98931, ["questType"] = "standard", ["sourceQuests"] = { 40180 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40183] = { ["id"] = 40183, ["name"] = "Over Your Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 39958 }, ["description"] = "Alright, <name>, I'd like you to assist me with creating a helm. First we'll need to shave the hides, then tan them, and finally cut them into usable pieces. Follow my lead.", ["objectivesText"] = "Craft a Rough Warhide Mask . You will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers. Progress: I'm starting to think we make a pretty good team.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129975, 130868, 130869, 130870, 130872, 130875, 130891, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 39958 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40184] = { ["id"] = 40184, ["name"] = "Tauren Tanning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Have you heard of the Highmountain tauren tribes? They're not unlike the tauren we know on Kalimdor. I've heard they have a leatherworking master there who might be able to help us come up with some new patterns. Travel to Highmountain and see if they're willing to teach you how they craft their armor.", ["objectivesText"] = "Report to Hrul Sharphoof .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93522, ["questTurnInID"] = 93522, ["questType"] = "standard", ["sourceQuests"] = { 40176 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40185] = { ["id"] = 40185, ["name"] = "Shoulder the Burden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar. You would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.", ["objectivesText"] = "Obtain Lohrumn's Shoulderguard . Progress: My brother's armor... have you found it?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129976, 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40184 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40186] = { ["id"] = 40186, ["name"] = "Drogbar Durability", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves. Slay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.", ["objectivesText"] = "Kill 15 drogbar to prove your worth to Hrul.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40184 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40187] = { ["id"] = 40187, ["name"] = "Links in the Chain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Well, <lad/lass>, I'm afraid I'm at me wits' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set. However, I've heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist. Go there and search fer a master. Maybe they can fill in the missing patterns fer us.", ["objectivesText"] = "Find a leatherworking master in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 98931, ["questType"] = "standard", ["sourceQuests"] = { 40176 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40188] = { ["id"] = 40188, ["name"] = "Best Served Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend. That \"friend\" has recently appeared in the ruins to the east. His name is Ranaris . Go to and take revenge for us and I will grant you some of my wisdom.", ["objectivesText"] = "Kill Ranaris in the El'dranil Shallows.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128894, 128899, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40187 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40189] = { ["id"] = 40189, ["name"] = "Naga Know-How", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "The naga of this region wear little armor, but what they do wear is particularly durable. If you wish to make a strong shoulder piece, I would first study the naga's armor and then create a pattern of similar construct. The city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.", ["objectivesText"] = "Obtain 7 Naga Shoulderguards . Progress: They may be vile, but they still know how to craft as well as any master.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129980, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40187 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40190] = { ["id"] = 40190, ["name"] = "Hardening the Hide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Back to Highmountain for you, <name>! I hear they know even more efficient ways to craft our patterns. When you get there, put in a good word for me, will ya? I'd like to start a relationship the tauren, so I don't have to keep sending you back and forth.", ["objectivesText"] = "Return to Highmountain and talk to Hrul Sharphoof .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93522, ["questTurnInID"] = 93522, ["questType"] = "standard", ["sourceQuests"] = { 40185, 40186 }, ["nextQuests"] = { 40191 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40191] = { ["id"] = 40191, ["name"] = "Stamped Stories", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Stamped onto the leather of the tanning racks behind me are the ancient ways of our tribe's leatherworkers. They tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking. Read the stories and learn from them. Perhaps you'll find some insight on how to better your own methods.", ["objectivesText"] = "Learn from the stories of each of the tanning racks.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40190 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40192] = { ["id"] = 40192, ["name"] = "Claw of the Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don't need quite as many of them. For example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.", ["objectivesText"] = "Obtain 100 Stalker Claws . Progress: Their claws are some of the strongest I've ever come across.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 4801, 130070, 130102, 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40191 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40193] = { ["id"] = 40193, ["name"] = "Getting the Kinks Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Now listen, <lad/lass>. Everything ye make can always be done better. I just haven't quite worked out the way to do it with these fancy new scales. Perhaps that ghost-like elf friend of yours can help ye. An' if she DOES know somethin', perhaps ye can relay that information back to us. It would certainly go towards making the shop more lucrative.", ["objectivesText"] = "Go back to Celea in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.346, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 98931 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 98931, ["questType"] = "standard", ["sourceQuests"] = { 40189 }, ["nextQuests"] = { 40194 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40194] = { ["id"] = 40194, ["name"] = "Reclaimed Cargo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves. If you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.", ["objectivesText"] = "Obtain 5 Mail Armor Shipments . Progress: Were you able to recover any of the shipments?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128898, 128899, 130072, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40193 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40195] = { ["id"] = 40195, ["name"] = "A Daring Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40327 }, ["description"] = "My brother, Taldranis , was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive. I believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please. Take this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.", ["objectivesText"] = "Find Taldranis in Oceanus Cove, and deliver the armor to him.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130263, 140517, 140922, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 98964, ["questType"] = "standard", ["sourceQuests"] = { 40194 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40196] = { ["id"] = 40196, ["name"] = "Adventuring Anxieties", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40197, 41889 }, ["description"] = "<name>! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted. I'd like you to go and discuss this idea with her further. Return to me when you're finished. Perhaps we can solve this issue together.", ["objectivesText"] = "Speak with Mei Francis about her barding idea.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40183 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40197] = { ["id"] = 40197, ["name"] = "The Necessary Materials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40196, 41889 }, ["description"] = "In order to make this barding, we'll need a lot of leather. And I mean a LOT of leather. I'll solidify our plans on fitting the pieces together. You go gather the leather. Once that's done, we can begin crafting.", ["objectivesText"] = "Gather 100 Stonehide Leather . Progress: This is probably the biggest project I've ever been a part of. It's quite exciting!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 130875, 130894, 130895, 130896, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40196 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40198] = { ["id"] = 40198, ["name"] = "Rats!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40202 }, ["description"] = "I tell you, <name>, I have the worst luck sometimes. A package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers! Probably building nests with them as we speak. Please, <name>, can you go down there and see if you can retrieve any of them?", ["objectivesText"] = "Go into the Underbelly and recover 3 Highmountain Leatherworking Patterns . Progress: I hope they're not too badly damaged.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 60854, 62996, 62997, 62998, 130077, 130078, 141850, 263358, 263359, 263362, 263364 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93522, ["questTurnInID"] = 93522, ["questType"] = "standard", ["sourceQuests"] = { 40192, 40327 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40199] = { ["id"] = 40199, ["name"] = "Leather Legwork", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40206 }, ["description"] = "Good news, <name>! Langrom's Leather and Links recently delivered a shipment of mail armor to me. It's of the finest quality and I'd love to show it to ye, but it seems I've lost me crowbar and can't open the crate. If ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.", ["objectivesText"] = "Get a crowbar for Thanid. Progress: Fer the life of me, I dunna know where I left the blasted thing!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 69777, 128893, 128897, 130081, 132172, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98931, ["questTurnInID"] = 98931, ["questType"] = "standard", ["sourceQuests"] = { 40198 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40200] = { ["id"] = 40200, ["name"] = "Battle Bonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40327, 40415, 41889 }, ["series"] = { 40201, 40241 }, ["description"] = "Do you like pets, <name>? I love pets. They're so cute! But what I really want is more things with which to play with them. I'm sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", ["objectivesText"] = "Talk to Lio the Lioness at the Magical Menagerie shop. Then return to Namha.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 41889 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40201] = { ["id"] = 40201, ["name"] = "Playthings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40200, 40241 }, ["description"] = "Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?! It sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you're ready. Why don't you work on making the bed, and I'll work out the details for the flaming hoop.", ["objectivesText"] = "Craft a prototype for the pet bed. Progress: Make sure it's nice and cozy!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129960, 130090, 130869, 130870, 130872, 130891, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40200, 40241 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40202] = { ["id"] = 40202, ["name"] = "The Final Lessons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40198 }, ["description"] = "<name>, Hrul has requested your presence. From his message it seems as though he's ready to impart to you all the wisdom he has gained from working with the skins of this land. I envy you, <name>... but I'm also proud to see that you've gained so much respect with him. Go now, and good luck!", ["objectivesText"] = "Go to Hrul Sharphoof in Highmountain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93522 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93522, ["questTurnInID"] = 93522, ["questType"] = "standard", ["sourceQuests"] = { 40199 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40203] = { ["id"] = 40203, ["name"] = "Strength of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40204, 40205, 40207, 40208, 40209, 40210 }, ["description"] = "As you know, the durability of your armor is only as strong as the materials you use to make them. Long ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds. His natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me. This will take all your strength to accomplish.", ["objectivesText"] = "Return a scale of Deathwing to Hrul. Progress: True strength isn't determined by how much you can endure, but by continuing to endure when you lack the strength.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130098, 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40202 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 31, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40204] = { ["id"] = 40204, ["name"] = "Evolution of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40205, 40207, 40208, 40209, 40210 }, ["description"] = "As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again. For centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them. Go, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.", ["objectivesText"] = "Obtain 5 Basilisk Hides . Progress: Do not fear change, for change is the only way to move forward.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130100, 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40202 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 32, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40205] = { ["id"] = 40205, ["name"] = "Respect for the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40207, 40208, 40209, 40210 }, ["description"] = "We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes. Scattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell. Go to these locations, pay your respect, and learn their lessons.", ["objectivesText"] = "Go to the four tanning racks around Highmountain and hear their stories.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 131811, 140336, 141605, 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40202 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 33, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40206] = { ["id"] = 40206, ["name"] = "A Debt Paid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40199 }, ["description"] = "Now, I've never heard of a ghost sending a letter before, but I'll be damned if'n I didn't just receive one now. Celea has sent fer ye, <lad/lass>. I'd best be on me way if I were ye. Might be bad luck to keep a spirit waiting.", ["objectivesText"] = "Go to Celea in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850, 263437, 263438 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 98931 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 98931, ["questType"] = "standard", ["sourceQuests"] = { 40199 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 34, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40207] = { ["id"] = 40207, ["name"] = "Scales of the Arcane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40208, 40209, 40210 }, ["description"] = "In my experience, dragon scale has been the strongest material I've ever had the privilege of working with. It's hard, durable and very little can go a long way. I wish to work with it again, <name>. Being in this form, I'm bound to this area, unable to experience the world any longer. I've heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.", ["objectivesText"] = "Speak with the blue dragonflight and acquire one of their scales. Progress: To work with dragon scale again would be a great honor.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130104, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40206 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 35, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40208] = { ["id"] = 40208, ["name"] = "Eye of Azshara: Scales of the Sea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8040, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40207, 40209, 40210 }, ["description"] = "When we first met, I spoke of the naga, and the armor they're able to craft. No grander armor is worn, however, than by their top warlords. One in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend. Repel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.", ["objectivesText"] = "Go to the Eye of Azshara and obtain Warlord Parjesh's Hauberk . Progress: He will not just hand it over, <name>. You're in for a rough fight.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130106, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 8040 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40206 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 36, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40209] = { ["id"] = 40209, ["name"] = "Scales of the Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40207, 40208, 40210 }, ["description"] = "While leather armor is strong on its own, integrating scales into the design is what truly sets it apart. The type of scales you use will determine how many you'll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales. A fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.", ["objectivesText"] = "Obtain the Axetail Basilisk Matriarch Scales . Progress: You may have to fight past a few of her brood to get to her.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130110, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40206 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 37, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40210] = { ["id"] = 40210, ["name"] = "Time Well Spent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40207, 40208, 40209 }, ["description"] = "Unfortunately, <name>, you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership. Go now and share what you've learned with your allies in Dalaran. I'm sure they'd be eager to share in your training.", ["objectivesText"] = "Tell Namha of your time with the night elves in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 98964, ["questType"] = "standard", ["sourceQuests"] = { 40207, 40208, 40209 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 38, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40211] = { ["id"] = 40211, ["name"] = "Demon Flesh", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Something we haven't really explored yet, <name>, are the creatures of Suramar. Specifically, the demons. Now I certainly don't praise what they are, but you can't ignore the fact that some of their creatures have especially tough hides. We could take a lesson from the demon hunters and use those hides to our advantage against the demons. I'll be damned though if I know the first thing about working with demon hide. Perhaps there's someone in Suramar who can help...", ["objectivesText"] = "Search for a master leatherworker in Suramar.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 109076, 140327, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40210, 40415, 42079 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 40, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40212] = { ["id"] = 40212, ["name"] = "Wrong End of the Knife", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40213, 40214 }, ["description"] = "There he is! The man that isn't there! He's... he's... Wait... no, I'm sorry. My thoughts, they're just all over place lately. Ever since my exile, things have been a bit fuzzier than normal. If you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.", ["objectivesText"] = "Kill the traitor leatherworkers, Feorias , Tallian , and Syana .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140327, 141850 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40211 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 41, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40213] = { ["id"] = 40213, ["name"] = "Hounds Abound", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40212, 40214 }, ["description"] = "I'll invite him to tea. That'll show him! He'll see the leather doll and say, \"When did SHE get here?!\" I mean... sorry, <name>. My mind goes to strange places. You want to know about the demons, the ones with durable hides? Before I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses. We can discuss their hides afterwards.", ["objectivesText"] = "Obtain 5 Fel Hound Corpses . Progress: We met on the lake. It was spring and she wore ley lilies...", ["rewardGold"] = 252720, ["rewardXP"] = 6140, ["rewardItems"] = { 130129, 140327, 141850 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40212 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 42, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40214] = { ["id"] = 40214, ["name"] = "Fel Tanning", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40212, 40213 }, ["description"] = "Listen, you. I'm not sure when the crazy side of me will come out again, so let's make our time together short. You want to learn how to make armor to rival the demons? Follow my instructions and you'll have an excellent grasp on the procedures.", ["objectivesText"] = "Craft a pair of bracers for Stalriss using the tanning rack. Progress: You're really here, right? <Stalriss reaches out and pinches you>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 124438, 128891, 128907, 130130, 140327, 141850 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40213 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 43, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40215] = { ["id"] = 40215, ["name"] = "Mounting Made Easy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "<name>, I'm glad you're here. I confess: I've been working on a secret project behind your back. Behold: the Stonehide Leather Harness! Now, we simply need to find a mount worthy of such a piece of art. The vrykul sing songs of a snow-white elderhorn with endless stamina. Find it, place the harness on it, and tame it.", ["objectivesText"] = "Capture the Great Northern Elderhorn.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 41508, 124113, 124116, 124124, 127839, 128422, 131746, 133577, 133828, 137952, 139710, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40214 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 44, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40216] = { ["id"] = 40216, ["name"] = "A Hunter at Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 39859, 40170, 40217 }, ["description"] = "Addie's one heck of a writer, but I've never seen her hold a rifle. She's keen on learning how to hunt, but who's ever heard of a gnome hunter? You seem to have a knack dealin' with amateurs, so maybe you'd be willin' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill. Ya best start off with some small game. We don't want the lass to get discouraged.", ["objectivesText"] = "Help Addie learn to hunt by killing wildlife in Pinerock Basin. Progress: Keep an eye on the gnome while you're huntin'. She's never held a rifle before.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39859, 40170 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40217] = { ["id"] = 40217, ["name"] = "An Offering of Ammo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 39859, 40170, 40216 }, ["description"] = "The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions. Our leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin. They hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow. While I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.", ["objectivesText"] = "Deliver the Quiver of Arrows to Hemet Nesingwary at Nesingwary's Retreat. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127769 }, ["starts"] = { { ["x"] = 0.424, ["y"] = 0.469, ["mapID"] = 750, ["npcID"] = 99905 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questGiverID"] = 99905, ["questType"] = "standard", ["sourceQuests"] = { 39387, 39456 }, ["nextQuests"] = { 39859, 40170 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40218] = { ["id"] = 40218, ["name"] = "Debt Repaid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 39389, 41759, 41767 }, ["description"] = "I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning. You should warn Ritssyn to keep his distance. I'll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.", ["objectivesText"] = "Speak to Ritssyn Flamescowl .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 6265, 22244 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 105816, ["questType"] = "standard", ["sourceQuests"] = { 39142 }, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[40219] = { ["id"] = 40219, ["name"] = "In Defiance of Deathwing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 657, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing. Today we shall re-live moments of that day through the eyes of our ancestors. For this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.", ["objectivesText"] = "Witness 3 Visions. Progress: You are learning parts of our history few outsiders have ever known.", ["rewardGold"] = 306800, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.428, ["y"] = 0.287, ["mapID"] = 657, ["npcID"] = 99153 } }, ["ends"] = { { ["x"] = 0.428, ["y"] = 0.287, ["mapID"] = 657, ["npcID"] = 99153 } }, ["coords"] = { ["mapID"] = 657, ["x"] = 0.428, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 99153, ["questTurnInID"] = 99153, ["questType"] = "standard", ["sourceQuests"] = { 39575 }, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657 },
[40220] = { ["id"] = 40220, ["name"] = "Thorny Dancing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38862, 40220, 40221 }, ["description"] = "The Thistleleaf sprites have gone completely mad. I suspect they are being manipulated by some very mischievous Thorndancers. Please, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.", ["objectivesText"] = "Defeat 3 Thistleleaf Thorndancers in the Lunarwing Shallows. Progress: Have you dealt with those Thorndancers yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5912, ["name"] = "Lunarwing Shallows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40221] = { ["id"] = 40221, ["name"] = "Spread Your Lunarwings and Fly", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38862, 40220, 40221 }, ["description"] = "These poor faerie dragons are being tortured! What's worse, when the thistleleaf become bored they ensnare their victims to continue their torment later. This behavior is simply unacceptable. Please free any trapped Lunarwings you can find.", ["objectivesText"] = "Save 8 Trapped Lunarwings in the Lunarwing Shallows.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121577, 121578, 121579, 121580, 121589, 121590, 121591, 121592 }, ["rewardChoices"] = { 121577, 121578, 121579, 121580, 121589, 121590, 121591 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5912, ["name"] = "Lunarwing Shallows", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40222] = { ["id"] = 40222, ["name"] = "The Imp Mother's Tome", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38725, 40051 }, ["description"] = "See this giant cave? There's a terrifyingly powerful imp mother inside. But that's not the good part. The good part is what she has. Apparently, she's some kind of keeper of fel secrets. She's in there performing profane Legion rites and scribing them into a book. We need that power! We need her tome!", ["objectivesText"] = "Obtain the Tome of Fel Secrets . Progress: Do you have it?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 128954, 129957, 133314 }, ["rewardChoices"] = { 128954, 133314 }, ["starts"] = { { ["x"] = 0.731, ["y"] = 0.338, ["mapID"] = 672, ["npcID"] = 98711 } }, ["ends"] = { { ["x"] = 0.731, ["y"] = 0.338, ["mapID"] = 672, ["npcID"] = 98711 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.731, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 98711, ["questTurnInID"] = 98711, ["questType"] = "standard", ["sourceQuests"] = { 38725, 39495 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[40224] = { ["id"] = 40224, ["name"] = "The Hammer in the Deep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["description"] = "< Thrall listens intently.> You found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth'xun and retrieve the hammer before any more of this realm is corrupted. Therazane will open a portal directly there. Let's go!", ["objectivesText"] = "Use Therazane's Portal to travel to the Crumbling Depths. Accompany Stormcaller Mylra and Thrall to recover the Doomhammer. Progress: What of the Doomhammer?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["sourceQuests"] = { 42937 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[40225] = { ["id"] = 40225, ["name"] = "A Ring Reforged", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 207, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 41510 }, ["description"] = "Speak with Nobundo, and take your place around the circle, <name>. The Earthen Ring will rise again, with you as its leader! Within these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...", ["objectivesText"] = "Speak with Nobundo and take your place as the head of the Earthen Ring. Progress: The Alliance and Horde are in chaos. If we are to save Azeroth, we <class> must bind together!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.500667, ["y"] = 0.393333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 8046 } }, ["questTurnInID"] = 96539, ["questType"] = "standard", ["sourceQuests"] = { 39771, 40224, 40341 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[40226] = { ["id"] = 40226, ["name"] = "Remnants of the Sashj'tar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40226 }, ["objectivesText"] = "Remnants of the Sashj'tar", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Remnants of the Sashj'tar", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40227] = { ["id"] = 40227, ["name"] = "Bad Intentions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "Suramar is lost. Our leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them. But cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here... I rejected both of these options and found myself here. I will find a third way.", ["objectivesText"] = "Speak with Thaedris Feathersong in Tel'anor. Progress: Why do you seek to dissuade me?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140252, 140326, 141673, 141945 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40266, 40744 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40228] = { ["id"] = 40228, ["name"] = "Scout It Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "You've proven that a gnome can shoot a rifle, and that's no easy feat, but a true test of Addie's skill will be to see if she can track down an elusive beast. Rumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one's seen the beast up close. Take this flare, and shoot it into the sky once you've spotted the roc. When we see the signal, the huntin' party will rush in and help bring down that magnificent bird!", ["objectivesText"] = "Kill Irewing after sending up a flare, signaling his location. Progress: Don't just stand there, head out into the basin and find that bird!", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 53429, 53432, 80768, 80769, 80770, 80771, 80772, 121653, 121654, 121655, 121672, 130074, 130276, 130277, 130278, 130279, 131365, 143488, 169482, 169483, 169485, 188011, 188017, 188025, 188033, 209917, 209918, 210235, 210236, 228439, 228440, 228441, 228442 }, ["rewardChoices"] = { 121653, 121654, 121655, 121672, 130276, 130277, 130278, 130279 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39123, 39124, 39392, 40216 }, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40229] = { ["id"] = 40229, ["name"] = "Step into the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "With the threat to my people quelled, I believe it is time to introduce you to my kin. Meet me at Stonedark Grotto, and you will see where we live.", ["objectivesText"] = "Speak with Navarrogg at Stonedark Grotto.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.494, ["y"] = 0.239, ["mapID"] = 650, ["npcID"] = 96453 } }, ["ends"] = { { ["x"] = 0.494, ["y"] = 0.239, ["mapID"] = 650, ["npcID"] = 96453 } }, ["coords"] = { ["mapID"] = 650, ["x"] = 0.494, ["y"] = 0.239 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 96453, ["questTurnInID"] = 96453, ["questType"] = "standard", ["sourceQuests"] = { 39426 }, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659 },
[40230] = { ["id"] = 40230, ["name"] = "Oh, the Clawdacity!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "The leader of the Cavemoss makrura, Clawdayshus , has been ordering raids into the Cavemoss village to steal the young for snacks. This isn't going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well! This is a job for murlocs. Mindmeld with Murky in his egg and show him how it's done!", ["objectivesText"] = "Mindmeld with Murky and defeat Clawdayshus . Progress: Clawdayshus is ruthless. Murky must stop him.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132110, 132111, 132112, 132113, 132114, 132115, 132116, 132117, 143660, 258221 }, ["rewardChoices"] = { 132110, 132111, 132112, 132113, 132114, 132115, 132117 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40045, 40047, 40049 }, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40235] = { ["id"] = 40235, ["name"] = "Abrogator Arbitrator", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 40235 }, ["description"] = "Da bums in Highmaul refuse to see dey are on da way out. Me, I'm gettin' while da gettin' is good. Da sooner youse bring me a bunch of Apexis Crystals , da sooner I can get off dis stupid island. Da amount required is very precise!", ["objectivesText"] = "Kluk'kluk wants you to bring him 14958 Apexis Crystals . Progress: I can feel da power of da crystals! Give dem to me!", ["rewardXP"] = 1365, ["rewardItems"] = { 115280, 115981 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 99180, ["x"] = 0.583, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 99180, ["x"] = 0.583, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 35998 } },
[40236] = { ["id"] = 40236, ["name"] = "The Dawning Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5736, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 40636 }, ["description"] = "It was a miracle that you were able to survive, <name>. It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors. Now we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this. We all agree that new leader should be you, <name>. You have shown strength, wisdom, courage, and kindness beyond measure. Walk with us to the temple and we will announce our decision.", ["objectivesText"] = "Accompany Fearsome Jang and await the masters' announcement.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948 }, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.544, ["mapID"] = 709, ["npcID"] = 99181 } }, ["ends"] = { { ["x"] = 0.513, ["y"] = 0.544, ["mapID"] = 709, ["npcID"] = 99181 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.513, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 99181, ["questTurnInID"] = 99181, ["questType"] = "standard", ["sourceQuests"] = { 12103 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[40237] = { ["id"] = 40237, ["name"] = "Work Work Stoppage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6723, ["mapID"] = 534, ["storyline"] = { 40237 }, ["description"] = "We've had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat. I've had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals .", ["objectivesText"] = "Bring 20000 Apexis Crystals to the Renegade Ironworker . Progress: It's a good thing you took care of Mar'gok or nobody would be available for hire. Ogre security is still effective, right?", ["rewardXP"] = 1365, ["rewardItems"] = { 115510, 123974 }, ["starts"] = { { ["mapID"] = 534, ["npcID"] = 99183, ["x"] = 0.586, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 534, ["npcID"] = 99183, ["x"] = 0.586, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 534, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 534 }, ["zone"] = { 6723 } }, ["questType"] = "standard", ["sourceQuests"] = { 36013 } },
[40238] = { ["id"] = 40238, ["name"] = "A Grim Equation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 40129, 47508 }, ["description"] = "They were waiting for us when we crashed. It was all we could do to establish our small outpost. Even now they drain the souls of our fallen to fuel their attacks. Destroy their soul coffers . Free our comrades and let them join the Light. When you have finished, find Y'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.", ["objectivesText"] = "Destroy the three Soul Coffers on the Shattered Fields.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121521, ["x"] = 0.4, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["sourceQuests"] = { 47431 }, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["startItems"] = { 130076 } },
[40241] = { ["id"] = 40241, ["name"] = "Battle Bonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40200, 40201 }, ["description"] = "Do you like pets, <name>? I love pets. They're so cute! But what I really want is more things with which to play with them. I'm sure Serr'ah over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", ["objectivesText"] = "Talk to Serr'ah at the Magical Menagerie shop. Then return to Namha.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 41889 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
