[40244] = { ["id"] = 40244, ["name"] = "That Guy in the Costume", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "Aye, when we were out huntin' on the coast, we ran into this ridiculous lad in in a costume. He says he's tryin ta blend in with the murlocs... but I'm pretty sure he's just not right in the head. One of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin' it out? Ye can ask Tamara over there for a ride.", ["objectivesText"] = "Speak to Tamara and fly to Shipwreck Cove.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40228 }, ["nextQuests"] = { 40045, 40047, 40049 }, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40247] = { ["id"] = 40247, ["name"] = "Asking a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "Caria Felsoul was one of our best... before she answered the Legion's foul call. She now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race's greatest champion, who fell only to Sargeras himself. We sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source. Could you ask Khadgar for assistance? Our friends in this world are few.", ["objectivesText"] = "Ask Khadgar for a source to power the Legion communicator.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95240 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95240 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 95240, ["questTurnInID"] = 95240, ["questType"] = "standard", ["sourceQuests"] = { 40814, 44383 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40249] = { ["id"] = 40249, ["name"] = "Vengeance Will Be Ours", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "We aren't going to get our forces anywhere near the Broken Shore without getting knocked out of the sky. I think it best if you handle this matter yourself - there are none among us more capable on the field of battle. Save Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.", ["objectivesText"] = "Take the Aldrachi Warblades from Caria Felsoul.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.49, ["mapID"] = 627, ["npcID"] = 99247 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.49, ["mapID"] = 627, ["npcID"] = 99247 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99247, ["questTurnInID"] = 99247, ["questType"] = "standard", ["sourceQuests"] = { 41807 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
