[40253] = { ["id"] = 40253, ["name"] = "Stop Gul'dan!", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["series"] = { 38723, 39682 }, ["description"] = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens. Gul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse. Even in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", ["objectivesText"] = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 201989 }, ["starts"] = { { ["x"] = 0.494, ["y"] = 0.497, ["mapID"] = 677, ["npcID"] = 92718 } }, ["ends"] = { { ["x"] = 0.494, ["y"] = 0.497, ["mapID"] = 677, ["npcID"] = 92718 } }, ["coords"] = { ["mapID"] = 677, ["x"] = 0.494, ["y"] = 0.497 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 92718, ["questTurnInID"] = 92718, ["questType"] = "standard", ["sourceQuests"] = { 38689, 38690 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677 },
[40254] = { ["id"] = 40254, ["name"] = "Forged in Fire", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. Somehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long. The demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining. I believe that person could be you, <name>.", ["objectivesText"] = "Kill Immolanth and take his power. Progress: Do you have Immolanth's power, <name>?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["starts"] = { { ["x"] = 0.41, ["y"] = 0.471, ["mapID"] = 678, ["npcID"] = 96675 } }, ["ends"] = { { ["x"] = 0.41, ["y"] = 0.471, ["mapID"] = 678, ["npcID"] = 96675 } }, ["coords"] = { ["mapID"] = 678, ["x"] = 0.41, ["y"] = 0.471 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 96675, ["questTurnInID"] = 96675, ["questType"] = "standard", ["sourceQuests"] = { 39682 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678 },
[40255] = { ["id"] = 40255, ["name"] = "Between Us and Freedom", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39694, 40253, 40254, 40255, 40373, 95215 }, ["description"] = "The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.", ["objectivesText"] = "Kill Bastillax and take his power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["starts"] = { { ["x"] = 0.245, ["y"] = 0.562, ["mapID"] = 679, ["npcID"] = 97644 } }, ["ends"] = { { ["x"] = 0.245, ["y"] = 0.562, ["mapID"] = 679, ["npcID"] = 97644 } }, ["coords"] = { ["mapID"] = 679, ["x"] = 0.245, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 97644, ["questTurnInID"] = 97644, ["questType"] = "standard", ["sourceQuests"] = { 40373 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679 },
