[40260] = { ["id"] = 40260, ["name"] = "Suramar - Demon Hunter Daily - Choice Reward Summary - 3", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40260 }, ["rewardGold"] = 462000, ["rewardXP"] = 50, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 800 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40265] = { ["id"] = 40265, ["name"] = "A Touch of Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39903, 39904 }, ["description"] = "I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin. I can sense the power of a potent enchanter in you, <name>. If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I'm sure you can bring them to life again.", ["objectivesText"] = "Sprinkle Arkhana on dormant objects in Tigrid's house. Progress: Just the presence of such a vibrant enchanter gives my home the spark of life!", ["rewardGold"] = 322100, ["rewardXP"] = 1415, ["rewardItems"] = { 71076, 124440, 128535, 128617, 128618, 128619, 128620, 128621, 128622, 129293, 137235 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39903 }, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40266] = { ["id"] = 40266, ["name"] = "The Lost Advisor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "You may as well assist me while you are here. I require a potion to be made, one that will set things right. I must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon. The harpies around here cannot resist cliffthorn . It is what drew them to Tel'anor in the first place. You should find plenty just outside this building.", ["objectivesText"] = "Collect 8 Cliffthorn . Progress: <Thaedris seems lost in thought as he gazes towards the city of Suramar .>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130108, 140252, 140326, 141673, 141945 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99065, ["x"] = 0.455, ["y"] = 0.407 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.407 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40267] = { ["id"] = 40267, ["name"] = "An Unexpected Message", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 25, ["storyline"] = { 11997, 40267, 40270 }, ["series"] = { 40270 }, ["description"] = "Ah, Felo'melorn. I am familiar with this weapon. For ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. As luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her. I suggest you start your search there. The portal over there will bring you back to the city.", ["objectivesText"] = "Discover Archmage Modera 's message by using the Glowing Resonate Crystal .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 130131 }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.381, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 99398, ["x"] = 0.286, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 41085, 43441, 44310 }, ["questLines"] = { { ["id"] = 244, ["name"] = "Felo'melorn", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 244, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 25 },
