[40270] = { ["id"] = 40270, ["name"] = "The Path of Atonement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 11997, 40267, 40270 }, ["series"] = { 40267 }, ["description"] = "Felo'melorn, the runeblade of the kings of Quel'Thalas. It was said to harness the very essence of flame and after being reforged by Kael'thas could even stand against the legendary Frostmourne. We thought that the blade was lost with Kael'thas's death but an associate of mine has a lead on where it may be located. We need every advantage we can get and with Felo'melorn in your hand the Legion surely will tremble! Ah, our company is here.", ["objectivesText"] = "Speak to Archmage Modera 's associate at the Dalaran Crater within Hillsbrad Foothills", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 99398, ["x"] = 0.286, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 99415, ["x"] = 0.286, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard", ["sourceQuests"] = { 40267 }, ["questLines"] = { { ["id"] = 244, ["name"] = "Felo'melorn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 244, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 25 },
