[40300] = { ["id"] = 40300, ["name"] = "Tools of the Trade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "I used to visit here before the barrier was raised. While the ruling council and the Grand Magistrix argued and politicked I watched the caretakers perform their rituals and venerate the dead. I would honor the spirits here one last time. I am headed to the tombs. If some of the sacred oils, burial shrouds, or incense survived the ages then bring them to me.", ["objectivesText"] = "Tools of the Trade is a quest added in Legion. If you are interested in the 8.1.5 profession questlines instead, please visit our Tools of the Trade Crafting Overview . Retrieve burial objects for Thaedris. Progress: Did you find anything?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132253, 132255, 134092, 140252, 140326, 141673, 141945, 142054, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192020, 192021, 192030, 192032, 192037, 193477, 197923, 197924, 197926, 197931, 197932, 197937, 197938, 197944, 197947, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40227 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40306] = { ["id"] = 40306, ["name"] = "The Last Chapter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "The next step of my journey requires a tome, but I find that I am still unable to idly sit by as this place continues to fall into disrepair. I will tidy up the memorials while you go fetch me the tome. It is called the Encyclopedia Botanica and you can find it in the library near the main plaza.", ["objectivesText"] = "Find the Encyclopedia Botanica . Progress: Do you have the tome, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130208, 140252, 140326, 141673, 141945, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40300 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40307] = { ["id"] = 40307, ["name"] = "Glaive Circumstances", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "I came here on a mission to slay the demon eredar, Azoran. During my infiltration, I was shot down from my felbat and captured. I'm not going to mince words, <name>. Azoran plans to use the Burning Legion command ship to destroy Dalaran. To stop him, I will need my warglaives that were lost during my fall from the sky. I would retrieve them myself, but I'm still weakened from my imprisonment. Search for the warglaives on the northern side of the crater, where I was shot down.", ["objectivesText"] = "Retrieve Lyana Darksorrow 's glaives. Progress: Do you have my glaives, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130210, 130211, 140239, 141938, 141939, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40297, 44489 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40308] = { ["id"] = 40308, ["name"] = "Fragments of Memory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40308 }, ["description"] = "<The beautiful elven burial urn is shattered carelessly on the ground. It was clearly handled roughly, but not scratched by the talons of the harpies.> <You find a trail of shards leading towards a cave. Those responsible are certainly within. Thaedris would be interested in the relics and their safe return.>", ["objectivesText"] = "Retrieve 15 Tel'anor Mementos . Progress: What do you have there?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130212, 140252, 140326, 141673, 141945 }, ["starts"] = { { ["x"] = 0.491, ["y"] = 0.343, ["mapID"] = 680, ["objectID"] = 245688 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 }, { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 }, { ["mapID"] = 680, ["npcID"] = 100096, ["x"] = 0.374667, ["y"] = 0.475333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40227 } },
[40310] = { ["id"] = 40310, ["name"] = "Shipwrecked Captive", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40310 }, ["description"] = "I spent my life playing the pet in other peoples battles. Now it's my time to be the pet tamer! Best part of being dead is I can do this forever!", ["objectivesText"] = "Defeat Shipwrecked Captive in a pet battle.", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 116415, 122681, 163036 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98489, ["x"] = 0.4964, ["y"] = 0.4372 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98489, ["x"] = 0.4964, ["y"] = 0.4372 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.4964, ["y"] = 0.4372 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard" },
[40312] = { ["id"] = 40312, ["name"] = "A Timely Opportunity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40312 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40594, 42088, 42512 }, ["description"] = "Now that the whole \"spirit journey\" thing is out of the way we can get down to business.", ["objectivesText"] = "Assist Spiritwalker Ebonhorn in Neltharian's Vault.", ["rewardGold"] = 154000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[40315] = { ["id"] = 40315, ["name"] = "End of the Line", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "I cannot call Suramar my home any more, and I refuse to become a withered abomination. There is no place for me anymore, don't you understand? We only need one last ingredient to complete the elixir. You will help me, won't you?", ["objectivesText"] = "Speak with Thaedris at the upper landing of Tel'anor. Progress: Please let me fulfill my wishes, <name>.", ["rewardGold"] = 151650, ["rewardXP"] = 4605, ["rewardItems"] = { 38129, 38151, 38152, 38153, 38217, 140252, 140326, 141673, 141945 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40306, 40578 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40316] = { ["id"] = 40316, ["name"] = "The Screeching Crag", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40316 }, ["objectivesText"] = "Cleanse Screeching Crag of the harpies' curse Hexxing Fetish destroyed", ["rewardGold"] = 117300, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 200 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cleanse Screeching Crag of the harpies' curse", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Hexxing Fetish destroyed", ["amount"] = 17, ["type"] = 0, ["objectID"] = 104531, ["orderIndex"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
