[40319] = { ["id"] = 40319, ["name"] = "The Final Ingredient", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "The potion is complete, <name>. Soon our journey will be over. There is one last thing I would have you do for me, then you shall have your reward. My wife's bow was kept here, but I have not been able to find it after searching everywhere. There is potent magic in it. I fear one of the restless spirits may have taken it, but it would take a powerful force to pick up an item such as this. Be careful.", ["objectivesText"] = "Find Latara's bow . Progress: What was that? I heard a familiar voice... it couldn't be.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130255, 140252, 140326, 141673, 141945, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40315 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40320] = { ["id"] = 40320, ["name"] = "Band of Blood Brothers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "You are the one that Toryl was bellowing about? Perhaps you can help me. When I set out to search for Throndyr, I was not alone. Three vrykul loyal to Throndyr also accompanied me. As you can plainly see, I now stand alone. Find my kin, <name>. I cannot bear to think that they also share Throndyr's fate.", ["objectivesText"] = "Locate Katarine, Fjolrik, and Stokalfr in Muddledeep Cavern. Progress: I must know what has befallen my kin.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40908 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40321] = { ["id"] = 40321, ["name"] = "Feathersong's Redemption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "I must confess I was not entirely honest with you, <name>. I meant to drink the potion and join my wife. And even she was taken from her rest... I cannot fail her again. I must live and do what I can to stop this coming storm to be worthy of joining her. Come, young one. Let us take care of the harpy matriarch and restore Tel'anor to its former glory. We cannot let this poison go to waste, eh?", ["objectivesText"] = "Slay the Cliffclutch Matriarch . Progress: It will take time, but Tel'anor will flourish again. I swear it on my life.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130260, 140252, 140326, 141673, 141945, 245701, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100779, ["x"] = 0.45, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40319 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
