[40324] = { ["id"] = 40324, ["name"] = "Arcane Communion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 40325, 42224, 42225 }, ["description"] = "All of Kel'danath's experiments to connect with the withered failed, and some even made them more dangerous. Until he found Theryn . His arcane essence - the very soul of the shal'dorei - had been touched by something special. But what? By weaving my arcane essence together with Theryn 's, I can create an empathic bond. This communion will bare his soul to us all - or what's left of it. We need only to feed him mana, and lots of it, in order to begin.", ["objectivesText"] = "Feed Theryn 300 Ancient Mana. Progress: Feed Theryn as much as he will take.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 140255 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41138, 42147 }, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40325] = { ["id"] = 40325, ["name"] = "Scenes from a Memory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 40324, 42224, 42225 }, ["description"] = "Theryn is at the mercy of his own mind. Whatever we find in there, it may be difficult to control. I will need your help to sort through the visions, so be ready for anything. With any luck, we will discover what makes Theryn special. And... whether there is anything left of who he used to be.", ["objectivesText"] = "Help Thalyssra complete the arcane communion with Theryn.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40324 }, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40326] = { ["id"] = 40326, ["name"] = "Scattered Memories", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40012, 41702, 41704, 41760 }, ["description"] = "<As your fingers trace the elegant symbols on the page, a voice dictates the words in your mind. It seems the nightborne have elevated even simple note-taking to a sorcerous art. Arcanist Kel'danath was definitely working in this area. There must be more of his notes scattered around.>", ["objectivesText"] = "Inspect 6 pages of Kel'danath's Notes.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136600, 136970, 140349, 141668, 142054 }, ["starts"] = { { ["x"] = 0.302, ["y"] = 0.396, ["mapID"] = 680, ["objectID"] = 245328 } }, ["ends"] = { { ["x"] = 0.302, ["y"] = 0.396, ["mapID"] = 680, ["objectID"] = 245328 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.302, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40012 }, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40328] = { ["id"] = 40328, ["name"] = "A Fate Worse Than Dying", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "When the Burning Legion takes a prisoner, it is not an act of mercy. While death is the destruction of the mortal body... if you are captured by the Legion, they will seek to destroy your soul. The Burning Legion uses sacrificial souls to power their demonic machinations of war. The soul engine is where the harvested souls are collected and stored. Though countless have already perished in the soul engine, you may yet save those still alive inside. Hurry and release them before it is too late!", ["objectivesText"] = "Open 8 Soul Engine Cages. Progress: Have the soul engine cages been opened?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140239, 141938, 141939 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40901, 44490 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40329] = { ["id"] = 40329, ["name"] = "Battle Pet Tamers: Warlords", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 40329 }, ["description"] = "You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison. By defeating them will show your dominance in Draenor.", ["objectivesText"] = "Defeat 5 pet battle trainers in Draenor. Progress: Have you been able to defeat most of the tamers?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 116429, 120050, 120051, 140590 }, ["rewardChoices"] = { 116429 }, ["starts"] = { { ["x"] = 0.283, ["y"] = 0.388, ["mapID"] = 582, ["npcID"] = 79858 } }, ["ends"] = { { ["x"] = 0.283, ["y"] = 0.388, ["mapID"] = 582, ["npcID"] = 79858 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.283, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 79858, ["questTurnInID"] = 79858, ["questType"] = "standard", ["sourceQuests"] = { 36567, 36592 } },
[40331] = { ["id"] = 40331, ["name"] = "Bite of the Sashj'tar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "If I had been by Throndyr's side when he fought the naga, he might still be alive. These serpents will regret the day that they decided to slither from their watery hole! Killing them is not enough. No! I will honor Throndyr with a necklace of naga fangs!", ["objectivesText"] = "Collect 8 Sashj'tar Fangs from Sashj'tar naga in Azuregale Bay. Progress: We will slay them all!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132244, 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40908 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40332] = { ["id"] = 40332, ["name"] = "Beach Bonfire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "Do not let... my body lie in... the mud. Set my flesh... aflame.", ["objectivesText"] = "Collect 6 Driftwood in Azuregale Bay and build a funeral pyre for Jarl Throndyr . Progress: Throndyr deserved a more honorable death.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132371, 140244, 140245, 140254, 141674, 141675, 141946, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99559, ["x"] = 0.69, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40908 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40333] = { ["id"] = 40333, ["name"] = "Spiritwind Summit Treasure", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[40334] = { ["id"] = 40334, ["name"] = "Fisherman's Tonic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "If you detest these serpents as much as we do, I ask that you continue the fight against them. That will mean fighting them in their watery domain. I don't see any gills on you, so we're going to have to concoct an old tonic used by vrykul fishermen. The ingredients are plentiful around here, taken that you do not mind picking through entrails.", ["objectivesText"] = "Collect 4 Axetail Eyes from Axetail Basilisks, a Sashj'tar Air Bladder from Sashj'tar Naga, and a Sample of Siren Blood from Siren Naz'jul in Azuregale Cove. Progress: I will help you collect what we need.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133960, 133961, 133962, 140244, 140245, 140254, 141674, 141675, 141946, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 102334, ["questType"] = "standard", ["sourceQuests"] = { 40320, 40331, 40332 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40335] = { ["id"] = 40335, ["name"] = "Sashj'tar Accord DISABLED", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40335 }, ["description"] = "As far as you can decipher, the naga are recruiting the sea giants on behalf of Queen Azshara.>", ["objectivesText"] = "Show the stone tablet to Toryl.", ["rewardGold"] = 48500, ["rewardXP"] = 50, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["startItems"] = { 130326 } },
[40336] = { ["id"] = 40336, ["name"] = "Turning the Tidemistress", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "The Tidemistress has fallen back to the elven ruins and is licking her wounds. Her guard is undoubtedly protecting her. To best her, you will have to break her defenses. Construct a ballista using the parts that you salvaged and end her once and for all.", ["objectivesText"] = "Construct a Makeshift Ballista and kill Tidemistress Sashj'tar in the Sashj'tar Ruins. Progress: We finally have the advantage against the Sashj'tar. Now is the time to kill the Tidemistress.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133819, 140244, 140245, 140254, 141674, 141675, 141946, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41425, 41426, 41709 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
