[40339] = { ["id"] = 40339, ["name"] = "Candle of Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39770, 39772, 40345 }, ["description"] = "You no come in yet! Give orders to other kobold on Throne of Ordering Around if you want in, then maybe we talk.", ["objectivesText"] = "Sit upon the Throne of Ordering Around and give orders to kobolds that approach. Progress: What you lookin' at, stink head?", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 128753 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39769 }, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40341] = { ["id"] = 40341, ["name"] = "Throne of the Tides: Azshara's Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 205, ["storyline"] = { 40341, 43644, 43645 }, ["series"] = { 43645 }, ["description"] = "Wavespeaker Adelee tracked Sharas'dal to the Throne of Tides within the Abyssal Maw, then disappeared. <name>, if we go after her, we are almost certainly walking into a trap. But the elements are with us, my friend. The naga will not expect a shaman of your caliber! Swim to the Throne of Tides to the Northwest, within the Abyssal Depths. I will join you once you are inside. Let's find our missing shaman and get that artifact!", ["objectivesText"] = "Travel to the Throne of Tides and acquire Sharas'dal. Progress: What news from the deeps, <class>?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 6948, 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 205, 207 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["sourceQuests"] = { 43645 }, ["questLines"] = { { ["id"] = 267, ["name"] = "Azshara's Power", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 267, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[40342] = { ["id"] = 40342, ["name"] = "Surprise the Sashj'tar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40342 }, ["description"] = "The naga are preoccupied with recruiting the sea giants for Queen Azshara's battles in other lands. Now is the time to strike!", ["objectivesText"] = "Kill 12 Sashj'tar Champions or Sashj'tar Deep Witches in Azuregale Bay.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40345] = { ["id"] = 40345, ["name"] = "Burn the Candle at Both Ends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39770, 39772, 40339 }, ["description"] = "Why you come back already? Have to wait until jobs are done or I no let you through! Go back to Throne of Ordering Around and make sure they finish!", ["objectivesText"] = "Ensure that all of the kobold jobs are done. Progress: You come in when jobs are done.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 129981, 130901 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40339 }, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40346] = { ["id"] = 40346, ["name"] = "Pilfered Provisions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40346 }, ["description"] = "The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.", ["objectivesText"] = "Collect 8 Pilfered Provisions from shipwrecks in Azuregale Bay.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 130889 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["startItems"] = { 130893 } },
