[40348] = { ["id"] = 40348, ["name"] = "Something in the Water", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40348, 40368, 40370 }, ["description"] = "There is something fouling these waters, <class>. We will need to purify the waters in order to restore balance to the elemental forces below this ruin. The magic here has warped the elementals and they are beyond restoration. Release their corrupted forms so that they may be reborn pure.", ["objectivesText"] = "Slay 12 Mana-corrupted Waterspawn . Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140243, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40368 }, ["questLines"] = { { ["id"] = 5766, ["name"] = "Cleansing Tel'anor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
