[40364] = { ["id"] = 40364, ["name"] = "Bubble Trouble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40364, 41606, 41618 }, ["series"] = { 41606 }, ["description"] = "<class>! The sea giants have already eaten half of my kin. We are helpless in these accursed bubbles. I beseech you to get us out of here. Take heed. These bubbles are strong. You will need something that is extremely sharp to pierce them.", ["objectivesText"] = "Collect a piece of Needle Coral and then rescue 5 Captured Vrykul in Azuregale Bay. Progress: Move quickly, <class>! These sea giants have an insatiable appetite!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130944, 140244, 140245, 140254, 141674, 141675, 141946, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41606 }, ["questLines"] = { { ["id"] = 5814, ["name"] = "Brytag", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40368] = { ["id"] = 40368, ["name"] = "Turtle Powered", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40348, 40368, 40370 }, ["description"] = "In order to locate and purify the source of the corruption I am going to need an elemental focus. The turtles around here have developed scales that can focus and amplify their innate magics. Bring back some snapper scales and we will have these waters purified in no time!", ["objectivesText"] = "Collect 7 Shimmering Snapper Scales . Progress: Remember, the scales need to be whole to be of any use as a focus.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 69777, 130942, 132184, 140243, 141944 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5766, ["name"] = "Cleansing Tel'anor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 688 },
[40370] = { ["id"] = 40370, ["name"] = "Purge the Unclean", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40348, 40368, 40370 }, ["description"] = "Do you feel it in the air, <race>? The stage is set for us to make things right. While you were busy I was able to track down the elder elemental that rules these waters. Its name is the Azurefall Guardian and it resides within the channels below Tel'anor. Take the ritual focus, it should help you during the battle.", ["objectivesText"] = "Defeat the corruption in the Azurefall Guardian. Progress: Did you find the source of the corruption?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131760, 140243 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40368 }, ["questLines"] = { { ["id"] = 5766, ["name"] = "Cleansing Tel'anor", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40373] = { ["id"] = 40373, ["name"] = "A New Direction", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "<name>, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command. Kayn or Altruis. You can only choose one. The chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged. If you need a reminder of our past, gaze into the Pool of Judgment. Remember the sacrifices that forged us into demon hunters. Speak to me when you are ready to choose.", ["objectivesText"] = "Choose between Kayn and Altruis. Progress: Have you made a choice?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 138970, 141650 }, ["rewardChoices"] = { 138970, 141650 }, ["starts"] = { { ["x"] = 0.244, ["y"] = 0.558, ["mapID"] = 679, ["npcID"] = 97644 } }, ["ends"] = { { ["x"] = 0.244, ["y"] = 0.558, ["mapID"] = 679, ["npcID"] = 97644 } }, ["coords"] = { ["mapID"] = 679, ["x"] = 0.244, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questGiverID"] = 97644, ["questTurnInID"] = 97644, ["questType"] = "standard", ["sourceQuests"] = { 39686 }, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679 },
[40378] = { ["id"] = 40378, ["name"] = "Enter the Illidari: Ashtongue", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["description"] = "Lord Illidan has placed you in charge. Now, we just need the rest of our Illidari attack force. There are three Burning Legion gateways ahead. Activate them and our Illidari will pour through from the Black Temple. Like most Legion constructs, the gateways are powered by souls. I think we have provided enough to activate this first one, don't you? Let us bring in our Ashtongue forces.", ["objectivesText"] = "Summon in your Ashtongue forces by activating the Legion Gateway. Progress: <name>, I remind you that we need our Ashtongue forces to be brought through the gateway back on Despair Ridge.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["starts"] = { { ["x"] = 0.286, ["y"] = 0.631, ["mapID"] = 672, ["npcID"] = 98229 } }, ["ends"] = { { ["x"] = 0.286, ["y"] = 0.631, ["mapID"] = 672, ["npcID"] = 98229 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.286, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 98229, ["questTurnInID"] = 98229, ["questType"] = "standard", ["sourceQuests"] = { 40077 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[40379] = { ["id"] = 40379, ["name"] = "Enter the Illidari: Coilskar", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38759, 39049, 39050 }, ["description"] = "The next gateway's down on the Molten Shore. Our Coilskar forces are waiting at the Black Temple on the other side. Personally, I wouldn't have chosen to bring our naga allies. But, their leader did swear fealty to Lord Illidan. I suppose we'll see. We'll have to find a way to power the gateway's activator. Like this last gateway, it runs on souls. <Allari the Souleater grins as Sevis says this.>", ["objectivesText"] = "Feed a soul into the Legion Gateway Activator and then use it to summon in your Coilskar forces.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["starts"] = { { ["x"] = 0.339, ["y"] = 0.699, ["mapID"] = 672, ["npcID"] = 100982 } }, ["ends"] = { { ["x"] = 0.339, ["y"] = 0.699, ["mapID"] = 672, ["npcID"] = 100982 } }, ["coords"] = { ["mapID"] = 672, ["x"] = 0.339, ["y"] = 0.699 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questGiverID"] = 100982, ["questTurnInID"] = 100982, ["questType"] = "standard", ["sourceQuests"] = { 40378 }, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672 },
[40384] = { ["id"] = 40384, ["name"] = "Needs of the Hunters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 41415 }, ["description"] = "The eagle appears to have a message for you: To: <name> The time has come to strike back at the Legion. Meet me at Hunter's Reach in Dalaran as soon as you can. - Emmarel Shadewarden", ["objectivesText"] = "Speak with Emmarel Shadewarden in Dalaran.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["npcID"] = 100786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 100786, ["questType"] = "standard", ["questLines"] = { { ["id"] = 271, ["name"] = "Path of the Hunter", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40385] = { ["id"] = 40385, ["name"] = "The Spear in the Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39427, 40385, 41542 }, ["description"] = "Many years ago, a corrupted nightsaber hunted my people. Our chieftain, Dorro Highmountain, took Talonclaw and pursued the beast, but never returned. I have heard tales of a fearsome nightsaber that now stalks the mists of Stormheim. My brother and I believe this to be our ancient foe. The weapon must be there too! If we kill the beast and reclaim the spear, it will be of great use against the Legion.", ["objectivesText"] = "Hunt down Highmountain's Bane.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 140548, 140773 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 110821, ["x"] = 0.599, ["y"] = 0.81 }, { ["mapID"] = 650, ["npcID"] = 110986, ["x"] = 0.608, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 650, 739 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 39427 }, ["questLines"] = { { ["id"] = 220, ["name"] = "Talonclaw", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 220, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40388] = { ["id"] = 40388, ["name"] = "Huln's War - Shadowsong", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40167, 40515, 40520 }, ["description"] = "Someone with whom I believe you are familiar commands in the battlefield below. Jarod Shadowsong speaks highly of you, and has requested that you join him in battle. He has plans to put an end to this fight.", ["objectivesText"] = "Meet with Jarod Shadowsong in the battlefield.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.278, ["y"] = 0.517, ["mapID"] = 697, ["npcID"] = 97892 } }, ["ends"] = { { ["x"] = 0.278, ["y"] = 0.517, ["mapID"] = 697, ["npcID"] = 97892 } }, ["coords"] = { ["mapID"] = 697, ["x"] = 0.278, ["y"] = 0.517 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questGiverID"] = 97892, ["questTurnInID"] = 97892, ["questType"] = "standard", ["sourceQuests"] = { 39990 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697 },
