[40391] = { ["id"] = 40391, ["name"] = "Take Me To Your Leader", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "I am glad you are here, <name>. This... Khadgar, the archmage who found my message, has called a meeting. He wishes to meet us at the entrance to the city as soon as possible. Will you accompany me? I have the strangest feeling that he will not be alone.", ["objectivesText"] = "Meet with Khadgar in Suramar .", ["rewardGold"] = 151650, ["rewardXP"] = 4605, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45263 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40392] = { ["id"] = 40392, ["name"] = "Call of the Marksman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 739, ["storyline"] = { 40392, 40400, 40402, 40403, 40419, 41540 }, ["series"] = { 41540 }, ["description"] = "Time is of the essence! If Alleria and Thas'dorah are in Legion hands, it is only a matter of time until both are forfeit. If you are ready, head to the Broken Shore to meet with Ranger-General Windrunner. She has lent her personal hippogryph to fly you down to the surface.", ["objectivesText"] = "Take the hippogryph from Krasus' Landing down to the Broken Shore and meet with Vereesa Windrunner .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103415, ["x"] = 0.473818, ["y"] = 0.453455 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.473818, ["y"] = 0.453455 }, ["mapCandidates"] = { ["npc"] = { 646, 739 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 41540 }, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
