[40400] = { ["id"] = 40400, ["name"] = "Clandestine Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40400, 40419, 41540 }, ["series"] = { 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "You have long been a trusted hero of the Alliance, <name>. And like the rest of us, you have endured many hardships to reach this point. Now, I must ask even more of you. Will you hear me out?", ["objectivesText"] = "Speak to Vereesa Windrunner . Progress: Now you must decide whether you will stand with me.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 40392 }, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[40401] = { ["id"] = 40401, ["name"] = "A Way Back In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["series"] = { 40424, 40469 }, ["description"] = "I must get back into Suramar . I was exiled unfairly! I cannot live out here like this. I need the Nightwell's energies... I saw a message carved into a wall a few days ago. There is someone in the Water Gardens who can smuggle people into the city. It said \"We shall drink of the Well again.\" I cannot survive a confrontation with the guards again. Will you go in my stead? Once I am back in the city I can repay you.", ["objectivesText"] = "Find the smuggler. Progress: Who are you to seek passage into Suramar ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100185, ["x"] = 0.342, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100192, ["x"] = 0.414, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40402] = { ["id"] = 40402, ["name"] = "Clandestine Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40402, 40403, 40419, 41540 }, ["series"] = { 40400, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "As you well know, I have opposed the Horde at many turns. The orcs have taken... so much from me. From my family. Yet I have witnessed your deeds firsthand, <name>. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point. Now, I must ask your help. Will you hear me out?", ["objectivesText"] = "Listen to Vereesa Windrunner 's tale. Progress: Now you must decide whether you will stand with me.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 40392 }, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[40403] = { ["id"] = 40403, ["name"] = "Clandestine Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["requiredRaces"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40402, 40403, 40419, 41540 }, ["series"] = { 40400, 40402, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "It is no small matter for me to seek the aid of a blood elf. Your leaders have turned their backs on the sacrifices made by my family and so many others. Yet I have witnessed your deeds firsthand, <name>. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point. Now, I must ask your help. Will you hear me out?", ["objectivesText"] = "Listen to Vereesa Windrunner . Progress: Now you must decide whether you will stand with me.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 40392 }, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
