[40408] = { ["id"] = 40408, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 23, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38710 }, ["description"] = "Our gathering has identified several weapons of immense power. In the right hands, these holy artifacts give us a fighting chance against the Legion. We cannot pursue all of them at once. We risk too much if we spread ourselves that thin. We must agree on where our efforts are best focused. That is why I asked you here, <name>. As one of our greatest champions, you must be our voice of reason and decide our next move.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 38710 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40412] = { ["id"] = 40412, ["name"] = "Azoran Must Die", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "You won't have much time before the Legion is aware of your presence on the ship. When the alarm is raised, countless Burning Legion forces will attempt to board the ship through this portal. I will not let them succeed. I will guard this portal from enemy reinforcements until you return. It is up to you to slay Azoran and lay waste to his ship. We don't have much time... you must attack swiftly and without mercy.", ["objectivesText"] = "Defeat Azoran in Felsoul Hold. Progress: Has Azoran been slain?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 140239, 141938, 141939, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100053, ["x"] = 0.31, ["y"] = 0.848 }, { ["mapID"] = 680, ["npcID"] = 100823, ["x"] = 0.31, ["y"] = 0.85 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100878, ["x"] = 0.312667, ["y"] = 0.841333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.848 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41097, 41098 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
