[40415] = { ["id"] = 40415, ["name"] = "Well Spent Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Your respect for our ways has earned you all the knowledge we have to teach. Go now, <name>, and spread our ways to those who fight against the legion. Perhaps it will help to turn the tide in this war for our world.", ["objectivesText"] = "Tell Namha of your time with the tauren in Highmountain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["ends"] = { { ["x"] = 0.368, ["y"] = 0.782, ["mapID"] = 750, ["npcID"] = 98948 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.368, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 98948, ["questTurnInID"] = 98948, ["questType"] = "standard", ["sourceQuests"] = { 40203, 40204, 40205 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 39, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40418] = { ["id"] = 40418, ["name"] = "To Tanaan!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 40418 }, ["series"] = { 38253, 38254, 38255, 38256, 38257, 38258, 38259 }, ["description"] = "It is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters. The King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", ["objectivesText"] = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 94219 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 92219, ["x"] = 0.276, ["y"] = 0.102 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.102 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard", ["sourceQuests"] = { 36615 } },
[40419] = { ["id"] = 40419, ["name"] = "Rescue Mission", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7737, ["mapID"] = 646, ["storyline"] = { 40392, 40400, 40402, 40403, 40419, 41540 }, ["series"] = { 40400, 40402, 40403, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "The demon has told us how to open a portal to the world where he says Alleria is being held. You and I can go through and see if there is any truth to his claims. In case it's a trap, Magus Solgaze has given me a portal stone to get us back to Dalaran. This demonic magic is anathema to the mage, so we must move quickly. I'm ready when you are, <name>.", ["objectivesText"] = "Travel through the portal and rescue Alleria Windrunner.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 141446 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 100190, ["questType"] = "standard", ["sourceQuests"] = { 40400, 40402, 40403 }, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40423] = { ["id"] = 40423, ["name"] = "Unethical Adventurers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40423 }, ["rewardItems"] = { 131767, 138839, 140680, 140681, 140682, 140683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2VignetteID"] = 1158, ["db2VignetteName"] = "Unethical Adventurers" },
[40424] = { ["id"] = 40424, ["name"] = "A Desperate Journey", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["series"] = { 40401, 40469 }, ["description"] = "The city's entrances are under heavy guard. He must have another way. Thanks to this wine I am strong enough to make the journey to him. I fear that I will not be able to defend or run if I come under attack. You will accompany me, <race>. You and this Astoril are my only chance at surviving now. I remember when I was leaving the city that there were lamps guiding me here. We should be able to retrace our steps by following them.", ["objectivesText"] = "Follow the lamp posts to take Iadreth to Astoril . Progress: I was worried something had happened to you in the forest. I am glad that I was wrong.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140237 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100185, ["x"] = 0.342, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100301, ["x"] = 0.38, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40469 }, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
