[40469] = { ["id"] = 40469, ["name"] = "Final Preparations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["series"] = { 40401, 40424 }, ["description"] = "We will need supplies for our trip into Suramar . We cannot exactly stop for refreshments at the gate with you two in tow, can we? The water gardens were a place to socialize and relax. Before the patrols arrived it was rather trivial to hide some mana wine for later retrieval. That's where you come in. Fetch some supplies and bring them to your friend, then meet me at the ruins north of the city. We will be ready to depart soon.", ["objectivesText"] = "Recover 6 stashed supplies . Progress: Did you find the smuggler? What did they say?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132177, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100192, ["x"] = 0.414, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100185, ["x"] = 0.342, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40401 }, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40470] = { ["id"] = 40470, ["name"] = "Quality of Life", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["description"] = "I am afraid, <name>. We're so close to home, so close to salvation... Astoril says he knows the rest of the way through and can get us there safely. I believe him, but you've come this far to see us safe. Will you see this through to the end?", ["objectivesText"] = "Follow Iadreth .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133760, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100331, ["x"] = 0.379333, ["y"] = 0.662667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.379333, ["y"] = 0.662667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40424 }, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
