[40495] = { ["id"] = 40495, ["name"] = "Ulthalesh, the Deadwind Harvester", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 47, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "The book says the Dark Riders were last seen in a place called Manor Mistmantle. If friend can find these riders, then <he/she> can get Ulthalesh! Calydus will wait here and await your return. Find Ulthalesh, friend!", ["objectivesText"] = "Start your search for the Deadwind Harvester at Manor Mistmantle in Duskwood. Progress: And just why should I help you, <class>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 173527 }, ["starts"] = { { ["x"] = 0.561, ["y"] = 0.657, ["mapID"] = 628, ["npcID"] = 101097 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7875 } }, ["questGiverID"] = 101097, ["questType"] = "standard", ["sourceQuests"] = { 40684, 43984, 44089 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 47 },
