[40515] = { ["id"] = 40515, ["name"] = "A Walk With the Spirits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40167, 40388, 40520 }, ["description"] = "The spiritwalker you saved from Riverbend has been insufferable since his arrival. He is insisting on showing you the ways of our people so that you better understand what is to come. He is a strange one, even by spiritwalker standards. Even so, only a fool would discard his insight. Please, go to speak with him when you get a moment.", ["objectivesText"] = "Speak with Spiritwalker Ebonhorn .", ["rewardGold"] = 29200, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.63, ["mapID"] = 652, ["npcID"] = 93826 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.63, ["mapID"] = 652, ["npcID"] = 93826 } }, ["coords"] = { ["mapID"] = 652, ["x"] = 0.55, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 93826, ["questTurnInID"] = 93826, ["questType"] = "standard", ["sourceQuests"] = { 38909 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40517] = { ["id"] = 40517, ["name"] = "The Fallen Lion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40519, 42740, 42782, 43806 }, ["description"] = "I haven't left the deck of this ship since we got back. The fleet must be made ready for war. Don't know where we will be needed, but when the call comes, we'll be ready. Truth be told... I welcome the distraction. The others are paying their respects to Varian, but I... I cannot bring myself to face that casket. To face his son. Varian gave me a letter he wrote to Anduin. Please, take it to him on my behalf.", ["objectivesText"] = "Deliver King Varian's letter to King Anduin. Progress: Welcome, <name>. I am pleased you survived the battle. You have something for me?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 132251 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100395, ["x"] = 0.202, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100429, ["x"] = 0.856, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 42740 }, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[40518] = { ["id"] = 40518, ["name"] = "The Battle for Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Your warship awaits at the end of the dock, <name>. May your weapon bring you many kills today. The Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", ["objectivesText"] = "Take Captain Russo 's ship to the Broken Shore.", ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292 }, ["rewardChoices"] = { 136582, 136583, 136584, 136587, 136588, 136589, 136591, 136595, 139292 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 113547, ["x"] = 0.555, ["y"] = 0.11 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100453, ["x"] = 0.572, ["y"] = 0.105 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 44281 }, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[40519] = { ["id"] = 40519, ["name"] = "Legion: The Legion Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40517, 42740, 42782, 43806 }, ["description"] = "Heroes of the Alliance, I write to you in Azeroth's darkest hour. From the maw of hell, the burning armies of the Legion have returned. Our fleets depart for the Broken Isles at once. As a grand lance, we will pierce the Legion's lines and drive them back to the nether that spawned them. Your ship awaits in the Stormwind Harbor, make haste.", ["objectivesText"] = "Check in with Recruiter Lee at Stormwind Harbor. Provided item:", ["rewardItems"] = { 132120, 139389, 139391, 140192, 143785 }, ["starts"] = { { ["x"] = 0.261, ["y"] = 0.383, ["mapID"] = 84, ["npcID"] = 167032, ["objectID"] = 206111 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107934, ["x"] = 0.368, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 167032, ["questType"] = "standard", ["nextQuests"] = { 42782 }, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2DetailThemeID"] = 1, ["db2PoiUiMapID"] = 84 },
[40520] = { ["id"] = 40520, ["name"] = "To See the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40167, 40388, 40515 }, ["description"] = "I would like for you to experience firsthand what Huln Highmountain was able to accomplish in a single battle during the War of the Ancients. To do so, I will need very specific ingredients. They are not too difficult to obtain--you can find all of them near Thunder Totem.", ["objectivesText"] = "Collect a Bottle of Airspark , Mu'sha's Tears , and Darkshard Crystal . Progress: Earth, air, and water are all magics we have come to know well in our mountain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132246, 132247, 132248 }, ["starts"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["ends"] = { { ["x"] = 0.748, ["y"] = 0.75, ["mapID"] = 652, ["npcID"] = 98825 } }, ["coords"] = { ["mapID"] = 652, ["x"] = 0.748, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questGiverID"] = 98825, ["questTurnInID"] = 98825, ["questType"] = "standard", ["sourceQuests"] = { 40167 }, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40522] = { ["id"] = 40522, ["name"] = "Fate of the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It is a wonder any of our troops survived that bloodbath on the Broken Shore. If not for Lady Sylvanas... High Overlord Saurfang has been asking for you at Grommash Hold. He will not say why... but he was insistent that I send you to him.", ["objectivesText"] = "Go to Grommash Hold and learn the fate of the Horde. Progress: Dark days are upon us.", ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100453, ["x"] = 0.572, ["y"] = 0.105 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100866, ["x"] = 0.456, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.105 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 40518 }, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[40523] = { ["id"] = 40523, ["name"] = "Facet-nating Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40529, 40530, 40531 }, ["description"] = "Excuse me, <sir/madam>. Are you sure you're in the correct shop? We only deal in the finest of jewels here. Ahh, I see... you're a fellow lapidary. Then perhaps we can work together. Introduce yourself to my associates, so they're aware of who you are and what you may have to offer.", ["objectivesText"] = "Introduce yourself to Timothy Jones and Sminx Glasseye. Progress: Get yourself acquainted and we'll discuss business.", ["rewardItems"] = { 132467, 139497 }, ["starts"] = { { ["x"] = 0.403, ["y"] = 0.347, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.403, ["y"] = 0.347, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.403, ["y"] = 0.347 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40524] = { ["id"] = 40524, ["name"] = "A Familiar Ring to It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "<name>! Let's talk bling. I'm looking for a ring. See, the elves down in Azsuna were some fine master jewelcrafters back in the day... or so they say. The books all talk about a ring called the \"Band of Farondis\". Can't hurt to ask around for it. Let's head to Azsuna. Bet I'll get there sooner!", ["objectivesText"] = "Find the Shrine of Aldiir near the Crumbling Palace in Azsuna and read about its legend. Progress: Have you tracked down the ring?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93527 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93527, ["questType"] = "standard", ["sourceQuests"] = { 40523 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40525] = { ["id"] = 40525, ["name"] = "Getting the Band Back Together", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "I like our dynamic, <name>. You're the muscle with all the hustle! And I'm the brains who entertains! I think this next task is all on you. Try to find that ring, or whatever the murlocs left of it.", ["objectivesText"] = "Find the three pieces of the Band of Farondis and bring them back to Timothy Jones . Progress: How goes the hunt for the ring?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132368, 132467, 132875, 132876 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40524 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40526] = { ["id"] = 40526, ["name"] = "Finishing Touches", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Well, I've managed to repair the ring, but the gem still needs work. Say... you're a gemcutter, <name>. You've got the tools, so cut those jewels!", ["objectivesText"] = "Use Timothy's Gem Vise to obtain a Cut Skystone . Progress: How'd you do?", ["rewardItems"] = { 132331, 132332, 132333, 132467, 137212 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.414, ["mapID"] = 630, ["npcID"] = 100538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questGiverID"] = 100538, ["questType"] = "standard", ["sourceQuests"] = { 40525, 42214 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40527] = { ["id"] = 40527, ["name"] = "Finishing Touches", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Well, I've managed to repair the ring, but the gem still needs work. Say... you're a gemcutter, <name>. You've got the tools, so cut those jewels!", ["objectivesText"] = "Use Timothy's Gem Vise to obtain a Cut Deep Amber . Progress: How'd you do?", ["rewardItems"] = { 132331, 132332, 132333, 132467, 137214 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.414, ["mapID"] = 630, ["npcID"] = 100538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questGiverID"] = 100538, ["questType"] = "standard", ["sourceQuests"] = { 40525, 42214 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40528] = { ["id"] = 40528, ["name"] = "Finishing Touches", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Well, I've managed to repair the ring, but the gem still needs work. Say... you're a gemcutter, <name>. You've got the tools, so cut those jewels!", ["objectivesText"] = "Use Timothy's Gem Vise to obtain a Cut Azsunite . Progress: How'd you do?", ["rewardItems"] = { 130223, 130224, 130225, 132331, 132332, 132333, 132467, 137215 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.414, ["mapID"] = 630, ["npcID"] = 100538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questGiverID"] = 100538, ["questType"] = "standard", ["sourceQuests"] = { 40525, 42214 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40529] = { ["id"] = 40529, ["name"] = "Truly Outrageous", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40523, 40530, 40531 }, ["description"] = "Ore prospecting is our primary method of gem acquisition. And while prospecting... you're bound to find small, unusable gem chips . Many gem shops simply discard the small gem chips they find, but we here at Cartier & Co. let nothing go to waste.", ["objectivesText"] = "Gather 5 Gem Chips for Tiffany Cartier . Gem Chips can be acquired through Prospecting raw ore or purchased off the auction house. Progress: Try not to get any blood on them while you're out \"adventuring\".", ["rewardItems"] = { 123918, 123919, 129100, 132467, 139497 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40523 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40530] = { ["id"] = 40530, ["name"] = "An Eye for Detail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40523, 40529, 40531 }, ["description"] = "<name>, if there's one thing I despise, it's slander. A rumor is spreading that one of my recent commissions is a fake. We need to quell these rumors as quickly as possible. I need you to visit the customers I recently worked for and examine their gems. If your claim of being a jewelcrafter is true, then you will be able to spot a fake gem from a mile away. Here's the list of my patrons. Return immediately if you find any truth to these rumors.", ["objectivesText"] = "Visit the patrons of the jewelcrafting shop in Dalaran and report back to Tiffany. Progress: I will not let these falsehoods ruin the good name of Tiffany & Co.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40529 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40531] = { ["id"] = 40531, ["name"] = "Swift Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40523, 40529, 40530 }, ["description"] = "I swear, when I find him... <Tiffany catches your eye and regains her composure.> <name>, I need you to track down my FORMER associate, Harold Winston. I doubt he's gotten far, given our location. When you find him, I would like you to recover the stolen property and return it to me. Use any means necessary. And don't worry about Ms. Moore's jewels, I'll redeliver a fresh supply to her personally.", ["objectivesText"] = "Find Harold Winston in Dalaran's Underbelly. Progress: Did you find him? Were you able to recover the jewels?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132259, 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40530 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40532] = { ["id"] = 40532, ["name"] = "Making the Cut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Deadly Deep Amber. We'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", ["objectivesText"] = "Craft a Deadly Deep Amber using the Tiffany's cutting tool. Progress: Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", ["rewardItems"] = { 132262, 132265, 132268, 132269, 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40531 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40533] = { ["id"] = 40533, ["name"] = "Making the Cut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Quick Azsunite. We'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", ["objectivesText"] = "Craft a Quick Azsunite using the Tiffany's cutting tool. Progress: Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", ["rewardItems"] = { 132262, 132266, 132268, 132269, 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40531 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40534] = { ["id"] = 40534, ["name"] = "Making the Cut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Masterful Queen's Opal. We'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", ["objectivesText"] = "Craft a Masterful Queen's Opal using the Tiffany's cutting tool. Progress: Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", ["rewardItems"] = { 130215, 130216, 130218, 132262, 132267, 132268, 132269, 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40531 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40535] = { ["id"] = 40535, ["name"] = "Raising the Drogbar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40536 }, ["description"] = "Word travels fast around Dalaran, <name>. And the latest word is that there's a master jewelcrafter somewhere in Val'sharah. I want you to go down there and find this master. Perhaps they have designs that can help bolster business here at the shop. I've heard the name \"Lasune Starblade\" tied to these rumors. She might be a good place to start looking.", ["objectivesText"] = "Talk to Lasune Starblade in Val'sharah as to the whereabouts of the jewelcrafting master. Progress: Those damned harpies ambushed Jabrul !", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132446, 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100776, ["x"] = 0.454, ["y"] = 0.693333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.693333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40526, 40527, 40528, 40532, 40533, 40534 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40536] = { ["id"] = 40536, ["name"] = "Bruls Before Jewels", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40535 }, ["description"] = "So, you wish to learn what Jabrul knows about jewels? Well, Jabrul needs your help. Before we leave this place, Jabrul still needs harpy necklaces. Keep those harpies off of Jabrul while he takes their necklaces and Jabrul will reward you with his knowledge.", ["objectivesText"] = "Protect Jabrul while he finds harpy necklaces and escort him back to the nearby night elf camp.", ["rewardItems"] = { 132467, 132468, 132469 }, ["rewardChoices"] = { 132467, 132468, 132469 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 100776, ["x"] = 0.454, ["y"] = 0.693333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100776, ["x"] = 0.454, ["y"] = 0.693333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.693333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 40535 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40537] = { ["id"] = 40537, ["name"] = "Drawing Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 40537, 49694, 49876 }, ["series"] = { 49694 }, ["description"] = "Hey, <name>! I have something exciting to tell you about, but you must keep a secret. Just between us scribes. <Zooey gives you a wink and pulls out a large tome.> This is the Bloodbound Ledger. Inscribing your name in it allows you to learn how to craft \"blood contracts\" which can hurt a little bit, but are absolutely worth it! I currently know one of them and I get so excited when I use it 'cause it... well, you'll see. So whaddya say? Interested?", ["objectivesText"] = "Sign the Bloodbound Ledger.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["x"] = 0.734, ["y"] = 0.063, ["mapID"] = 1161, ["npcID"] = 130399 } }, ["ends"] = { { ["x"] = 0.734, ["y"] = 0.063, ["mapID"] = 1161, ["npcID"] = 130399 } }, ["coords"] = { ["mapID"] = 1161, ["x"] = 0.734, ["y"] = 0.063 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questGiverID"] = 130399, ["questTurnInID"] = 130399, ["questType"] = "standard", ["questLines"] = { { ["id"] = 901, ["name"] = "8.1.5 Inscription - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161 },
[40538] = { ["id"] = 40538, ["name"] = "Lapidary Lessons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "It's good to see you again, <name>. It seems we've both been busy since last we spoke. I have something that you may be interested in. A recent shipment of rare jewels called maelstrom sapphires have finally arrived here at the shop. I came up with a beautiful design for them and would like to show you how to cut them into something useful.", ["objectivesText"] = "Craft a Well-Cut Maelstrom Sapphire using Tiffany's cutting tool. Progress: I'd recommend keeping a steadier hand than usual with these jewels.", ["rewardItems"] = { 132467, 132484 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.402, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questTurnInID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40536 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40539] = { ["id"] = 40539, ["name"] = "Hidden Intentions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Word on the street is, yer a reliable resource for getting things done, let's say, discreetly. So here's the job. I need a new set of lock picking tools. But not just any old lock picks will do. I need something special, something that won't break if ye apply too much pressure. I'm thinking a set of diamond lock picks might do the trick. That would be lock picks made out of diamond, not the ones shaped like a diamond. Look, ye in or what?", ["objectivesText"] = "Collect a set of Diamond Lockpicks for Clive Cozen . Progress: Try not to attract too much attention, okay?", ["rewardItems"] = { 132467, 132882, 137624, 137625 }, ["starts"] = { { ["x"] = 0.383, ["y"] = 0.362, ["mapID"] = 627, ["npcID"] = 100939 } }, ["ends"] = { { ["x"] = 0.383, ["y"] = 0.362, ["mapID"] = 627, ["npcID"] = 100939 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.383, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 100939, ["questTurnInID"] = 100939, ["questType"] = "standard", ["sourceQuests"] = { 40536 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40540] = { ["id"] = 40540, ["name"] = "Come at Me, Brul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40541 }, ["description"] = "<name>, I received a... well, what can only be constituted as a \"letter\", carved into a piece of flat rock. That jewelcrafting master you found in Val'sharah has sent for you. He said he's in Stormheim currently. When you see him, would you be so kind as to inform him that we don't wish to receive any more of his requests for your presence. They just make a mess.", ["objectivesText"] = "Find Jabrul in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 132467 }, ["starts"] = { { ["x"] = 0.402, ["y"] = 0.346, ["mapID"] = 627, ["npcID"] = 93526 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93526, ["questType"] = "standard", ["sourceQuests"] = { 40538 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40541] = { ["id"] = 40541, ["name"] = "The Charge Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40540 }, ["description"] = "Before Jabrul shares his designs with you, he needs you to help him with a special project. Jabrul has a jewel that can trap storm energy. The more lightning it traps, the brighter it shines. Jabrul thinks the storm drakes' power would be better spent in his jewel than terrorizing the skies of Stormheim. Don't you?", ["objectivesText"] = "Use the Conducting Jewel on the corpses of 10 Squallhunter storm drakes.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132467, 132760, 137663 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40540 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40542] = { ["id"] = 40542, ["name"] = "Eyes of Nashal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40543, 40544, 40546 }, ["description"] = "Deadly eye of prophecy ... a good choice. Before we can cut, though, we need gems. Here stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need. Ascend the statue, take its jeweled eyes, and return them to Jabrul .", ["objectivesText"] = "Obtain 2 Eyes of Nashal . Progress: Jabrul is anxious to see these jewels up close.", ["rewardItems"] = { 130219, 130220, 130222, 132467, 132767, 132769 }, ["starts"] = { { ["x"] = 0.422, ["y"] = 0.35, ["mapID"] = 634, ["npcID"] = 100499 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questGiverID"] = 100499, ["questType"] = "standard", ["sourceQuests"] = { 40546 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40543] = { ["id"] = 40543, ["name"] = "Eyes of Nashal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40542, 40544, 40546 }, ["description"] = "Quick dawnlight ... a good choice. Before we can cut, though, we need gems. Here stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need. Ascend the statue, take its jeweled eyes, and return them to Jabrul .", ["objectivesText"] = "Obtain 2 Eyes of Nashal . Progress: Jabrul is anxious to see these jewels up close.", ["rewardItems"] = { 130219, 130220, 130222, 132467, 132768, 132769 }, ["starts"] = { { ["x"] = 0.422, ["y"] = 0.35, ["mapID"] = 634, ["npcID"] = 100499 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questGiverID"] = 100499, ["questType"] = "standard", ["sourceQuests"] = { 40546 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40544] = { ["id"] = 40544, ["name"] = "Eyes of Nashal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40542, 40543, 40546 }, ["description"] = "Masterful shadowruby ... a good choice. Before we can cut, though, we need gems. Here stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need. Ascend the statue, take its jeweled eyes, and return them to Jabrul .", ["objectivesText"] = "Obtain 2 Eyes of Nashal . Progress: Jabrul is anxious to see these jewels up close.", ["rewardItems"] = { 130219, 130220, 130222, 132467, 132769 }, ["starts"] = { { ["x"] = 0.422, ["y"] = 0.35, ["mapID"] = 634, ["npcID"] = 100499 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questGiverID"] = 100499, ["questType"] = "standard", ["sourceQuests"] = { 40546 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40545] = { ["id"] = 40545, ["name"] = "Aww Scrap!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40854 }, ["description"] = "It's a catastrophe! No, even worse, a conspiracy! I heard the Legion was back again, and I thought to myself, \"Hobart, now's your time to shine.\" I made us enough guns to blow those demons back to the beginning of time! But then we get here, and what happens? Everyone just happens to \"find\" all these ancient artifacts to fight the demons with! Long story short, I have too many guns and need to get rid of 'em.", ["objectivesText"] = "Take the Crate of Guns down to Filgo Scrapbottom in the Underbelly. Provided item:", ["rewardItems"] = { 133578, 133671, 133672, 133673, 133674, 133750, 137691, 137692, 137725, 139495, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questTurnInID"] = 93539, ["questType"] = "standard", ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40546] = { ["id"] = 40546, ["name"] = "Mysteries of Nature", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40542, 40543, 40544 }, ["description"] = "Jabrul wants to show you his special crystals. Nobody knows what they do. Very mysterious. If you want to learn how to make one, Jabrul would be happy to show you. High in the mountains live storm drakes. They blast the cliffs with their lightning breath and sometimes blast so hard, they turn the rock to crystal. Get a piece of that crystal and bring it back to Jabrul .", ["objectivesText"] = "Recover a piece of Dragon Glass . Progress: Got the stone?", ["rewardItems"] = { 124124, 130172, 130175, 130254, 132467, 132820, 140500 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40541 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40547] = { ["id"] = 40547, ["name"] = "To Dalaran, With Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40556 }, ["description"] = "Jabrul was thinking that he'd like to come up to Dalaran and discuss jewel designs with the masters. But Jabrul doesn't know how to get up to it. Jabrul did have an interesting idea that might work. If you mailed Jabrul to Dalaran, then surely he'd arrive safe and sound.", ["objectivesText"] = "Crate up Jabrul and mail him to the Cartier & Co Fine Jewelry shop. Progress: Jabrul is SO anxious!", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 132467, 132823 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100521, ["x"] = 0.564, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100521, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 100521, ["questType"] = "standard", ["sourceQuests"] = { 40556 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40556] = { ["id"] = 40556, ["name"] = "Jabrul Needs You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40547 }, ["description"] = "Hello <name>, Jabrul needs your help with something. Could you please come to Azsuna and find Jabrul ? Thank you, Jabrul", ["objectivesText"] = "Find Jabrul in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 132467 }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.353, ["mapID"] = 627, ["objectID"] = 246250 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100521, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40542, 40543, 40544 }, ["nextQuests"] = { 40547 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40558] = { ["id"] = 40558, ["name"] = "Socket to Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40558 }, ["description"] = "You admire the contraption sitting on the counter. There's a button on it, but pressing it seems to warrant no response. Tiffany tells you that it's an old toy box, but the crystal components are all broken. If you were to find new ones, she could repair it and teach you how to make one for yourself.", ["objectivesText"] = "Obtain all 6 components from around the world. Refer to Tiffany's notebook for reference on where to acquire each piece. Progress: You're going to have to travel all over the world for these, I hope you're up to the challenge.", ["rewardItems"] = { 21756, 21760, 82774, 124444, 130178, 130179, 130180, 130181, 130182, 130183, 130251, 132467, 132838, 132839, 132840, 132841, 132842, 132843, 132925, 132976 }, ["starts"] = { { ["x"] = 0.4, ["y"] = 0.353, ["mapID"] = 627, ["objectID"] = 246154 } }, ["ends"] = { { ["x"] = 0.4, ["y"] = 0.353, ["mapID"] = 627, ["objectID"] = 246154 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.4, ["y"] = 0.353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 40547 } },
[40559] = { ["id"] = 40559, ["name"] = "Black Rook Hold: The Raven's Wisdom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40559 }, ["description"] = "<name>, I've been hearing a lot of talk about Black Rook Hold from our friend here, about a room which contains volumes of texts on just about every type of craft there is. I'm willing to bet there's a book in there on jewelcrafting that could come in handy for us. Go there and bring me back anything you find. I'll share a sweet new design I came up with you when you return.", ["objectivesText"] = "Go to Black Rook Hold and locate a book on jewelcrafting and bring it to Timothy Jones in Dalaran. Progress: A book, you'll find, is a design for the mind!", ["rewardItems"] = { 132467, 132859 }, ["starts"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93527 } }, ["ends"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93527 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.398, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93527, ["questTurnInID"] = 93527, ["questType"] = "dungeon", ["sourceQuests"] = { 40558 } },
[40560] = { ["id"] = 40560, ["name"] = "Maw of Souls: Spiriting Away", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40560 }, ["description"] = "What I'm about to ask you to do is no easy task, <name>. I need you to die. But, you'll be able to come back of course! There's a ship, the Naglfar, that ferries souls from this world to the next. It's said that an ancient treasure called the Ring of the Fallen rests in the bowels of that ship. You know me, <name>, and nothing catches my interest more than a sweet looking ring. Find a way onto that boat and bring me back that ancient treasure.", ["objectivesText"] = "Go to the Maw of Souls and bring back the Ring of the Fallen to Timothy Jones in Dalaran. Progress: The goddess that rules that world won't let you leave without a fight. Be careful in there, <name>.", ["rewardItems"] = { 132467, 132862 }, ["starts"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93527 } }, ["ends"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93527 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.398, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93527, ["questTurnInID"] = 93527, ["questType"] = "dungeon", ["sourceQuests"] = { 40558 } },
[40561] = { ["id"] = 40561, ["name"] = "Halls of Valor: Jewel of the Heavens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40561 }, ["description"] = "Queens and kings wear the best rings! And I've heard that a certain king of gods has made his presence available. In the Halls of Valor, the ruler Odyn has treasures unlike anyone in existence. If you happen to go there, try and... obtain, let's say, one of his rings for me. I doubt he'll just hand it over, so you may have the fight of a lifetime in store.", ["objectivesText"] = "Kill Odyn in the Halls of Valor and bring back his ring to Timothy Jones in Dalaran. Progress: This will easily be the finest piece in my collection.", ["rewardItems"] = { 132467, 132866 }, ["starts"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93527 } }, ["ends"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93527 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.398, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93527, ["questTurnInID"] = 93527, ["questType"] = "dungeon", ["sourceQuests"] = { 40558 } },
[40562] = { ["id"] = 40562, ["name"] = "A Personal Touch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40562 }, ["description"] = "<name>, great to see you again. It feels like forever since last we spoke. We've received some information about a group of jewelcrafting nightborne in Suramar that are doing fantastic things with necklaces. I'd like to take a look at some of their gems. And their designs. And... a new loupe might be nice, too. I hear the city inspectors carry them.", ["objectivesText"] = "Obtain a Nightborne Loupe , a Custom Jewelry Order , and 5 Nightborne Jewelry Cases . Progress: Oh, how did I know about the nightborne gems? Well, that's a trade secret. <Sminx gives you a quick wink.>", ["rewardItems"] = { 132867, 139886, 139887 }, ["starts"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93543 } }, ["ends"] = { { ["x"] = 0.398, ["y"] = 0.35, ["mapID"] = 627, ["npcID"] = 93543 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.398, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93543, ["questTurnInID"] = 93543, ["questType"] = "standard", ["sourceQuests"] = { 40559, 40560, 40561 } },
