[40567] = { ["id"] = 40567, ["name"] = "Darkheart Thicket: Enter the Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "We could not save Ysera, but we did prevent her from destroying the temple. Now I can finally turn my attention to my husband. I do not know what fate he suffers now. I only know that if we stand any chance of saving him, you must go now. Follow Xavius into the Nightmare and find Malfurion. Please, save my husband if you can.", ["objectivesText"] = "Enter Darkheart Thicket and Slay the Shade of Xavius . Progress: Is he alive? Will my husband return to me?", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 141548, 141549, 141550, 141551 }, ["rewardChoices"] = { 141548, 141549, 141550, 141551 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104921, ["x"] = 0.536, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104921, ["x"] = 0.536, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 38743 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 10, ["flags"] = 1 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 10, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40568] = { ["id"] = 40568, ["name"] = "Fury of the Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 44922, 44940 }, ["description"] = "The Felskorn who ravage my brood were once Drekirjar - a tribe with whom we shared an ancient pact. Now, under the influence of the God-King, they forsake their oaths and strike at the forebears of their coveted drakes. They should answer for this slight. Awaken your fury, <class>, and take the battle to them!", ["objectivesText"] = "Kill 10 Felskorn vrykul in Thorim's Peak. Progress: Are we rid of the Felskorn threat?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 197921 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91249, ["x"] = 0.446, ["y"] = 0.775 }, { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 38412, 38618 }, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 }, { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 638 },
[40569] = { ["id"] = 40569, ["name"] = "The Legend of the Sands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "Nothing! There is next to nothing in our records about this weapon! I've checked and re-checked, and can find barely a shred of a tale. This can only mean that the story comes from a land outside Pandaria. Li Li Stormstout is young, but she is the most traveled on the entire isle except for you. If anyone might know of this weapon, it is she.", ["objectivesText"] = "Speak with Li Li Stormstout . Progress: What's up?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 40636, 43973, 44424 }, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[40570] = { ["id"] = 40570, ["name"] = "Into The Heavens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "This stone is saturated with elemental power, possibly the remnant of the magic used against Irmaat! If you went outside and held the stone aloft, it should unleash the stone's essence as a mighty whirlwind. So potent a windstorm could carry you and your companion all the way to Skywall! If the hand blades of Irmaat, the Fists of the Heavens, are as powerful as the old tales say, they would certainly be found there.", ["objectivesText"] = "Obtain the Fists of the Heavens.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128937, 128938, 132745, 133948 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questTurnInID"] = 47684, ["questType"] = "standard", ["sourceQuests"] = { 40634 }, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[40573] = { ["id"] = 40573, ["name"] = "The Nightmare Lord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 38148, 38322, 38323, 38377 }, ["description"] = "You arrived just in time, friend. Kagraxxis was moments away from sacrificing me to his master... I was certain I would perish. I am grateful, but we are not out of danger yet... Xavius has returned. The Nightmare Lord is here in Val'sharah , personally orchestrating the corruption of this land. My captor revealed as much to me before I was to be sacrificed. We must find Thaon Moonclaw and inform him before it is too late!", ["objectivesText"] = "Inform Thaon Moonclaw of the return of Xavius.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121643, 129992, 130000, 130008, 130019, 245698, 246937 }, ["rewardChoices"] = { 121643, 129992, 130000, 130008, 130019 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91650, ["x"] = 0.65, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100573, ["x"] = 0.622, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39384 }, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40578] = { ["id"] = 40578, ["name"] = "Paying Respects", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "All I see is despair. Look, <race>. The grounds are overwhelmed with these wraiths, spirits of those interred here. Something has made them angry and they are lashing out. I can feel their pain. I will go look for remaining relics, and there is a tomb I must see. It is too late for these unfortunate souls. Please defeat any you find and return them to the rest they deserve.", ["objectivesText"] = "Slay 8 Disturbed Apparitions or Disturbed Spectres .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140252, 140326, 141673, 141945 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40300 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40579] = { ["id"] = 40579, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 40579 }, ["description"] = "As the greatest warrior in these halls, you require a great weapon to do both your will and mine. I have looked down on Azeroth and found artifacts worthy of your hands. I leave it to you to choose which artifact you wish to seek out and wield against the Legion. We will recover the others in time.", ["objectivesText"] = "Select an artifact weapon to pursue. Progress: Choose wisely, <name>.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.849, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.849, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 39654 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
