[40585] = { ["id"] = 40585, ["name"] = "Thus Begins the War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "The Legion thinks you are dead. It will be quite the surprise when you punish them for that assumption! This allows us to see all across the Broken Isles and assign warriors to various tasks. Once you've taken a look, you should choose your first area of operation. I've already picked out the best spots!", ["objectivesText"] = "Select your order's first assault point.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.597, ["y"] = 0.133, ["mapID"] = 695, ["npcID"] = 100635 } }, ["ends"] = { { ["x"] = 0.597, ["y"] = 0.133, ["mapID"] = 695, ["npcID"] = 100635 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.597, ["y"] = 0.133 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 100635, ["questTurnInID"] = 100635, ["questType"] = "standard", ["sourceQuests"] = { 39214 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
