[40588] = { ["id"] = 40588, ["name"] = "Following the Curse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Very well. I suppose an introduction is in order. I am Revil Kost , priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them. The Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before. Come with me to Ariden's camp. I will explain on the way.", ["objectivesText"] = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 42, 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 40495 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42 },
[40593] = { ["id"] = 40593, ["name"] = "Demons Among Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 39691, 40518, 40522, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "The king is wise to focus on the Legion's threat, <name>. Even now, the demons move against us. The Illidari will aid the cause of the Alliance. We believe they have set their sights on key locations around Azeroth. In fact, they could already be in your midst! I sense they are close...", ["objectivesText"] = "Protect Stormwind Keep from the Legion. Progress: I never suspected they had infiltrated my own throne room! Praise the Light you were here!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104, 138773, 138774, 138775, 138776 }, ["rewardChoices"] = { 128959, 138773, 138774 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100675, ["x"] = 0.854667, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.854667, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 40517 }, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[40594] = { ["id"] = 40594, ["name"] = "Justice Rains from Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 42088, 42512 }, ["description"] = "Kill now, grieve later! Here, champion, take flight with one of my war eagles . Use the powers bestowed upon you by our united tribes and help us rain destruction down on these drogbar. Let us clog that new doorway to their lair with the bodies of their own!", ["objectivesText"] = "Bomb the forces of the Understone Breach Progress: The drogbar sure do love those rocks.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 42512 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
