[40603] = { ["id"] = 40603, ["name"] = "Seeking the Valkyra", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We simply cannot risk another catastrophe like that; we have to protect the Heart against fel energy before we continue our work. The mighty Ashildir has proven willing to aid those who she deems worthy, and her master just may be able to help us protect the Heart. You should seek her out at the Vault of Eyir in Stormheim. I'll meet you there.", ["objectivesText"] = "Seek out Ashildir at the Vault of Eyir in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 634, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43526 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40604] = { ["id"] = 40604, ["name"] = "Disturbing the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["description"] = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner. Help me search the camp. Let's see if we can find something to lead us to the Dark Riders.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 100729, ["x"] = 0.524, ["y"] = 0.344, ["mapID"] = 42 } }, ["ends"] = { { ["npcID"] = 245793, ["x"] = 0.523, ["y"] = 0.34, ["mapID"] = 42 } }, ["coords"] = { ["x"] = 0.524, ["y"] = 0.344, ["source"] = "quest_giver", ["mapID"] = 42 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40588 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } } },
[40605] = { ["id"] = 40605, ["name"] = "Keep Your Friends Close", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "The Legion is bold indeed to strike at the Horde's stronghold! You aided our defense, but now I have a more important task for you. It seems the demon hunters will play a crucial part in this war... but I still don't trust them. You will be my envoy to the Illidari. Learn what they know. Study their techniques. If they betray us, we'll use their own knowledge against them. Their camp lies atop the plateau in the city. Go. Nathanos and I will clean up this mess.", ["objectivesText"] = "Speak to Elthyn Da'rai at the Illidari camp atop the plateau in Orgrimmar .", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 40607, 40983 }, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[40606] = { ["id"] = 40606, ["name"] = "To Point the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Though the journal devolves into dark ramblings written in hurried scribbles, one entry stands out: \"Ulthalesh. The name rings in my head. I can hear it calling, but where? \"The spirits... the very land here is tied to it. It is no wonder we would so often get lost in this place. The forces pull my compass point in every direction... \"Perhaps if it had a stronger pull, the compass could show the way...\"", ["objectivesText"] = "Find the compass mentioned in the journal in Ariden's Camp. Progress: Is that the one?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 132377 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.339, ["mapID"] = 42, ["objectID"] = 245793 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40604 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40607] = { ["id"] = 40607, ["name"] = "Demons Among Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Look around. What do you see? <Allari glares at something over your shoulder.> The Legion has already infiltrated the Horde... even now, they are among you. We must protect your Warchief. When you are ready to see what lies beneath the veil, say the word.", ["objectivesText"] = "Learn what Allari the Souleater sees. Progress: The Illidari were right! Destroy the demons, <name>!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104, 138773, 138774, 138775, 138776 }, ["rewardChoices"] = { 129104, 138775, 138776 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 40760 }, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[40608] = { ["id"] = 40608, ["name"] = "The Mark", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Your blade is powerful, but it has not yet met its full potential. The all-powerful Odyn in the Halls of Valor can bestow upon you his strength. In order to seek this blessing, you must bring him a worthy tribute. I know where you may obtain such a gift, but in order to retrieve it you must first receive the mark of the Valkyra. Prove yourself worthy of our mark, champion, then you may enter the Vault of Eyir- the goddess will guide you from there.", ["objectivesText"] = "Prove your worth to the Valarjar , then receive the Mark of the Valkyra from Eyir. Progress: Greetings, champion. How go your trials?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 9630, 9631, 9632, 9633, 25502, 25503, 25504, 30226, 30252, 65466, 128826, 131425, 131426, 131427, 131428, 132471, 139020, 139631, 139706, 139780, 140198, 140199, 140410, 142054, 146127, 158968, 158969, 158970, 158971, 159075, 160009, 160010, 160011, 160012, 160021, 160022, 160023, 160024, 198608, 205251, 235913, 239484, 260427 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40603 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40611] = { ["id"] = 40611, ["name"] = "The Fate of Deadwind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "The journal mentions a \"stronger pull\" for the compass. If the spirits of this place are indeed tied to it, they may serve as the pull we need. I've come upon several locations in the pass where restless spirits tend to appear. Perhaps if you show the spirits there the compass, they may be able to help point it in the right direction. You seek these locations out. I'll continue on to Karazhan and see if I can find anything leading to the Dark Riders.", ["objectivesText"] = "Attune Ariden's Compass at the sites of restless spirits around Deadwind Pass.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40606 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40613] = { ["id"] = 40613, ["name"] = "Maw of Souls: Retrieving the Svalnguard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Svalnguard was once Odyn's shield; it is said that it hid the Halls of Valor from the endless darkness below his realm. Helya, who was cast from the shining halls long ago, stole The Svalnguard and keeps it on her accursed ship, the Naglfar. You must board the Naglfar, defeat Helya, and retrieve The Svalnguard - it will make a worthy tribute for Odyn.", ["objectivesText"] = "Retrieve the Svalnguard and defeat Helya in the Maw of Souls on Mythic difficulty. Progress: Have you wrested the Svalnguard from Helya's clutches?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132440, 132471, 139631 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40608 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40614] = { ["id"] = 40614, ["name"] = "A Feast Fit for Odyn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "It is customary in the Halls of Valor to feast after battle is finished. Presenting a truly glorious feast to Odyn from beasts worthy of his throne will show him your determination to earn his blessing. Acquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and the finest cut of steak from Leytusk in Azsuna. They will make a feast worthy of the great battle to come.", ["objectivesText"] = "Acquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and a steak from Leytusk in Azsuna. Progress: The beasts you hunt have taken the lives of many.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132462, 132463, 132464, 132471, 139631 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40613 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40615] = { ["id"] = 40615, ["name"] = "Halls of Valor: Odyn's Blessing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "You are ready, <class>. Travel to Odyn's shining halls and offer the feast on the altar just inside. Mighty Odyn will then set his gaze upon you - you must pass the ancient trials of the Valarjar under his watch. Only then will you receive Odyn's blessing.", ["objectivesText"] = "Obtain Odyn's blessing in the Halls of Valor on Mythic difficulty. Progress: Few have sought Odyn's blessing and returned triumphant.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 140306 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40614, 40672 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40617] = { ["id"] = 40617, ["name"] = "Turn Around, Nighteyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 41230 }, ["description"] = "Stranger, you must help me! Nighteyes, my old friend... he was scouting ahead and I heard him cry out a warning. I tried to run after him, but in my carelessness I stepped in this trap. He's so close, just on the other side of this ridge. Please find him!", ["objectivesText"] = "Help Lilryia Dawnwind find Nighteyes. Progress: You must find Nighteyes!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134120, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42230 }, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40618] = { ["id"] = 40618, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 41415 }, ["description"] = "Three weapons... three worthy paths. Acquiring one such artifact will be the first step in battling the Legion. The weapon will grow in power as you wield it, so you must choose the one which will be the focus of your efforts, <name>. After a time, you will be able to pursue the other weapons. But you must decide which to seek first.", ["objectivesText"] = "Select your first artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["x"] = 0.598, ["y"] = 0.53, ["mapID"] = 627, ["npcID"] = 102478 } }, ["ends"] = { { ["x"] = 0.598, ["y"] = 0.53, ["mapID"] = 627, ["npcID"] = 102478 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.598, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102478, ["questTurnInID"] = 102478, ["questType"] = "standard", ["sourceQuests"] = { 41415 }, ["questLines"] = { { ["id"] = 271, ["name"] = "Path of the Hunter", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40623] = { ["id"] = 40623, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh. Progress: Did you find what you seek, <class>?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100812, ["questType"] = "standard", ["sourceQuests"] = { 40611 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40625] = { ["id"] = 40625, ["name"] = "A Different Source", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I need you to fetch me something. I think I might be on the verge of a breakthrough of a new source of magic, but I require tools. I can no longer access my workshop, but I have seen the smaller demons below using tools. Bring me one of their tools and I can save our people.", ["objectivesText"] = "Find a Fel Deconstructor for Kyrtos . Progress: Did you find anything? I did not exactly get a chance to pack my things before I was exiled.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132472, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40631] = { ["id"] = 40631, ["name"] = "Basking in Glory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40631 }, ["description"] = "You... you glow with the radiance of Odyn himself... You must return to your people at once. Odyn's light is a gift that must be shared with all.", ["objectivesText"] = "Return to Sister Elda in the Sanctum of Light.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40632] = { ["id"] = 40632, ["name"] = "Take Me To Your Leader", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["description"] = "I am glad you are here, <name>. This... Khadgar, the archmage who found my message, has called a meeting. He wishes to meet us by the entrance to the city as soon as possible. Will you accompany me? I have the strangest feeling that he will not be alone.", ["objectivesText"] = "Meet with Khadgar in Suramar .", ["rewardGold"] = 151650, ["rewardXP"] = 4605, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45263 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40633] = { ["id"] = 40633, ["name"] = "Off To Adventure!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 249, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "Oh I'd love to go see if that story is true! But Pops is too busy stuffing his gut and being a grouch to let me go do any real exploring. He even told me that I can't leave the village unless I have a guardian! Is Pops for real? I can protect myself just fine! Say, would you be my guardian? Please, get me away from this boredom and you will totally be my hero!", ["objectivesText"] = "Meet with Li Li in Ramkahen. Progress: Do you see this place? This is so neat!", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948 }, ["starts"] = { { ["x"] = 0.492, ["y"] = 0.586, ["mapID"] = 709, ["npcID"] = 100475 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 100571, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 7902 } }, ["questGiverID"] = 100475, ["questType"] = "standard", ["sourceQuests"] = { 40569 }, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[40634] = { ["id"] = 40634, ["name"] = "Thunder on the Sands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "I know the tale of Irmaat well. It is said that his home was the ancient city of Ahmtul, long buried under the desert sands. Recently a strange storm has appeared over the ruins. What's more, I am told that an elemental called Nader has attacked my people in nearby lands. These events must be related. Find this Nader and put an end to him. Make sure to search his body for clues as to what is behind this.", ["objectivesText"] = "Defeat Nader and search his body for clues. Progress: Have you found anything, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 132560, 133948 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["sourceQuests"] = { 40633 }, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249 },
[40635] = { ["id"] = 40635, ["name"] = "Sashj'tar Slayer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40635 }, ["description"] = "I cannot believe that Throndyr is gone. By the horns on my head, we shall have revenge for all of the pain that the Sashj'tar have inflicted on us! Press forward, . Kill them! Kill them all!", ["objectivesText"] = "Slay 12 Sashj'tar naga in Azuregale Cove.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40636] = { ["id"] = 40636, ["name"] = "Prepare To Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 40236 }, ["description"] = "The Burning Legion took us by surprise at the Peak of Serenity. We will not allow them to do so again! We have trained hard, but we need weapons capable of destroying this great evil if we are to have any chance of success. Our scrolls speak of several weapons that should prove suitable, but we are unable to decide which one to pursue first. The choice, Grand Master, is yours.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 128940, 133948 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 40236 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[40637] = { ["id"] = 40637, ["name"] = "Proof of Honor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40637 }, ["description"] = "This cave will be my final resting place, . Find Toryl. Tell her of what happened here today. Tell all of Jandvik that I died defending our village...", ["objectivesText"] = "Return to Toryl in Jandvik.", ["rewardGold"] = 119340, ["rewardXP"] = 3070, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40642] = { ["id"] = 40642, ["name"] = "Power! Get The Power!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I need more power. I need more! I can control the energies, and they are enough to sustain me. For now. I will not end up withered, like those weaklings. Go out into Felsoul Hold and slay the demons. Bring me their essence and make it quick!", ["objectivesText"] = "Collect 8 Fel Essence for Kyrtos . Progress: Do you have the essence? I must have it!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136592, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40694 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40643] = { ["id"] = 40643, ["name"] = "A Summons From Moonglade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40644, 40645, 40646, 41106 }, ["description"] = "<name>, Your presence is requested at Moonglade at once. We are preparing for a ritual of great importance and will require your assistance. I will meet you there, so please come with haste.", ["objectivesText"] = "Meet Hamuul Runetotem at the Moonglade. Provided item:", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140192, 173716 }, ["starts"] = { { ["x"] = 0.578, ["y"] = 0.458, ["mapID"] = 627, ["npcID"] = 101061 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questGiverID"] = 101061, ["questType"] = "standard", ["sourceQuests"] = { 44663 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80 },
[40644] = { ["id"] = 40644, ["name"] = "The Dreamway", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40645, 40646, 41106 }, ["description"] = "The preparations for the ritual are now complete. Come with me, <name>, I will guide you to the ceremony.", ["objectivesText"] = "Assist with the ritual. Progress: Are you ready to begin the ritual?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 103875, ["x"] = 0.668, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 41106 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80 },
[40645] = { ["id"] = 40645, ["name"] = "To The Dreamgrove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40644, 40646, 41106 }, ["description"] = "The portal to the Dreamway is open and it is here where our paths must part. The Moonglade remains vulnerable to the attacks of the Burning Legion and I must ensure it is well defended. I'm entrusting you with the mission to Val'sharah, <name>. Archdruid Greathoof is the leader of the druids there. He is wise in the old ways and will provide us invaluable assistance. The Dream can be dangerous so I will send Keeper Remulos to guide you. Meet with him upon the other side.", ["objectivesText"] = "Go through the portal to the Dreamgrove.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 103875, ["x"] = 0.668, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 103875, ["x"] = 0.668, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questTurnInID"] = 103875, ["questType"] = "standard", ["sourceQuests"] = { 40644 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[40646] = { ["id"] = 40646, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40644, 40645, 41106 }, ["description"] = "I agree with Keeper Remulos. To confront and defeat the Legion, we will need weapons of legendary power. Among the history of our kind, there have been four weapons of renown. Tell me, which weapon would you pursue first?", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128306, 128821, 128822, 128858, 128859, 128860 }, ["starts"] = { { ["x"] = 0.445, ["y"] = 0.511, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.445, ["y"] = 0.511, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.445, ["y"] = 0.511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 40644 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[40647] = { ["id"] = 40647, ["name"] = "When Dreams Become Nightmares", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "Now that we have Ursol's blessing, we can safely pass the magical wards and reach the claws' resting place! Now, we must pass into the Dream. Lay down before the Shrine of Ursol and drink of the moonwater you brought earlier and your spirit will drift off into the dream. Be careful, the Dream can be a dangerous place.", ["objectivesText"] = "Enter the Emerald Dream and obtain the Claws of Ursoc. Progress: Have you retrieved the Claws of Ursoc?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 136414 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["sourceQuests"] = { 41792 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["db2QuestSortName"] = "Battle Pets" },
[40649] = { ["id"] = 40649, ["name"] = "Meet with Mylune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "It would seem we are fortuitous that you seek G'Hanir this day, <name> - the dryad Mylune arrived not long ago from the sacred shrine where the staff has been guarded for many centuries. Few are privy to its hidden location within the roots of Shaladrassil, but you have certainly earned that right. Speak to Mylune when you are ready to depart - I saw her last just east of here up the hill.", ["objectivesText"] = "Find Mylune .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["x"] = 0.448, ["y"] = 0.506, ["mapID"] = 747, ["npcID"] = 103832 } }, ["ends"] = { { ["x"] = 0.448, ["y"] = 0.506, ["mapID"] = 747, ["npcID"] = 103832 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.448, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 103832, ["questTurnInID"] = 103832, ["questType"] = "standard", ["sourceQuests"] = { 40646, 43980, 44431, 44443 }, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[40650] = { ["id"] = 40650, ["name"] = "Champion: Zen'tabra", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["starts"] = { { ["npcID"] = 98013, ["x"] = 0.472, ["y"] = 0.076, ["mapID"] = 747 } }, ["ends"] = { { ["npcID"] = 98013, ["x"] = 0.472, ["y"] = 0.076, ["mapID"] = 747 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.076, ["source"] = "quest_giver", ["mapID"] = 747 }, ["mapCandidates"] = { ["npc"] = { 747 }, ["zone"] = { 7846 } }, ["questGiverID"] = 98013, ["questTurnInID"] = 98013, ["questType"] = "standard", ["sourceQuests"] = { 42583 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[40652] = { ["id"] = 40652, ["name"] = "Word on the Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40653, 41332 }, ["description"] = "It is time that we turn our attention to matters in the Broken Isles. Skylord Omnuron has gathered information on events from all over the Isles. If we are presented with any opportunity to strike against the Legion he will know of it. Go and see if he has anything available.", ["objectivesText"] = "Speak to Skylord Omnuron .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.46, ["y"] = 0.511, ["mapID"] = 747, ["npcID"] = 104241 } }, ["ends"] = { { ["x"] = 0.46, ["y"] = 0.511, ["mapID"] = 747, ["npcID"] = 104241 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.46, ["y"] = 0.511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 104241, ["questTurnInID"] = 104241, ["questType"] = "standard", ["sourceQuests"] = { 41332 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[40653] = { ["id"] = 40653, ["name"] = "Making Trails", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40652, 41332 }, ["description"] = "The Burning Legion threatens the life of Azeroth, but the nightmare threatens its very soul. We must remove both threats if our world is to survive. This map will allow us to track the developments all across the Broken Isles and respond to threats as they arise. Our forces are limited for now, so we should focus our efforts where they will be the most effective. Once you've taken a look, you should choose where we shall begin.", ["objectivesText"] = "Select your order's first operational area.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 40652 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40654] = { ["id"] = 40654, ["name"] = "Druids of the Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["description"] = "A new ally has joined our ranks. His name is Yaris Darkclaw , a skilled trainer among the Druids of the Claw. Go speak to him now.", ["objectivesText"] = "Speak to Yaris Darkclaw .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.446, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 42036 }, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[40657] = { ["id"] = 40657, ["name"] = "The Road to Fel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "An early step to understanding how magic works is to understand and study materials made using that magic. That was how I made my breakthrough on warlock soul crystals, after all. The wyrmtongue minions in this pit hammer plates into their structures for support and maintenance. Those will be a good starting point. Fetch me some, my faithful assistant!", ["objectivesText"] = "Gather 10 Fel-Infused Plates for Kyrtos . Progress: I can practically feel the buildings hum with power.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132761, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40625 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40659] = { ["id"] = 40659, ["name"] = "Seeing Stars", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40659 }, ["description"] = "You think those naga are good sport, little rabbit? I would savor the chance to do battle with one of those barnacle-crusted behemoths. If you want to impress me, bring me the stars from their heads. I might consider you a true then.", ["objectivesText"] = "Collect 4 Sea Stars from Elder Trenchwalkers in Azuregale Bay.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132559 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40661] = { ["id"] = 40661, ["name"] = "Protect the Home Front", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["description"] = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world. We must seek them out and stop them, everywhere their darkness touches. We've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map. Make them suffer, <name>!", ["objectivesText"] = "Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons! Progress: Find them! Stop them! Suffer well!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.779 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[40668] = { ["id"] = 40668, ["name"] = "Eye of Azshara: The Heart of Zin-Azshari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The naga in the Eye of Azshara summon terrible storms that ravage the coastline of Azsuna - storms far beyond the abilities of even their best sirens. It can only be the Heart of Zin-Azshari . Prior to the Sundering, Azshara's chosen used the Heart to greatly magnify their power - it is said to have been key in their dominance of the Well of Eternity. If you can journey to their domain and retrieve it, <name>, we will put its power to far better use than those foul creatures.", ["objectivesText"] = "Retrieve the Heart of Zin-Azshari and defeat the Wrath of Azshara in the Eye of Azshara on Mythic difficulty. Progress: Have you retrieved the Heart?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 132738, 139631 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 43496, 43501, 43503, 43505 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40672] = { ["id"] = 40672, ["name"] = "Neltharion's Lair: Presentation is Key", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Odyn will demand a feast worthy of the ancient trials you must complete; a feast's merit begins not at the great beasts piled upon it, but at the dish used to serve it. Deep beneath Highmountain lies the former lair of Neltharion - you may know the infernal drake better as Deathwing. You will find remnants of the adamantium plating used to hold his molten skin together in the deepest recesses of his lair. They will form a fine dish for the feast.", ["objectivesText"] = "Retrieve 4 Adamantium Casing Scraps and defeat Dargrul the Underking in Neltharion's Lair on Mythic difficulty. Progress: Dare not serve Odyn a feast upon an improper dish. Such action will only earn his ire.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 132744, 139631, 139773 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40613 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40673] = { ["id"] = 40673, ["name"] = "Lost Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We are indeed familiar with the Nightborne's magic, but we were never allowed access to the Heart. It was a right reserved only for the Queen's favored. However, we can still learn how to properly tap its magic. Thousands of years ago, a Nightborne scholar studied the Heart and documented his findings in great detail. He was executed and the scroll of his writings banned, but the Nightfallen secreted it away in their escape. If you obtain the scroll, we can help you.", ["objectivesText"] = "Obtain the Scroll of Elun'dris from First Arcanist Thalyssra. Progress: The Nightfallen have become... distrustful... since the Nightborne's betrayal. You will have to earn their respect before they will let you near the scroll.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43527 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40674] = { ["id"] = 40674, ["name"] = "Jars for Jandvik", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40674 }, ["description"] = "Last time we met, , I was in a cage. You risked your life once before for my kin. Are you willing to aid me once again? The serpents' attack has left many of us wounded. I require mending waters to perform my healing rituals. I have seen the serpents use this water. Return any that you find to me.", ["objectivesText"] = "Retrieve 6 Mending Water from the Sashj'tar Ruins.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132747 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40675] = { ["id"] = 40675, ["name"] = "The Arcway: Rite of the Captain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Only a captain of the Guard may receive the power of our order - our ancient laws forbid otherwise. You must complete the rite of the captain. Traditionally, aspirants patrol the Arcway for three weeks without rest, the vast labyrinth putting their skills as a Guard to the test. Our laws must still be honored, but I believe there another way you may prove yourself. Elisandre's advisor, Vandros, has recently descended into the Arcway's depths. Kill him, and take his Eon Winder .", ["objectivesText"] = "Take Advisor Vandros' Eon Winder from The Arcway on Mythic difficulty. Progress: Have you completed the rites as asked?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139787 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40673 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40676] = { ["id"] = 40676, ["name"] = "You Must Make Haste", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40676 }, ["description"] = "I suggest that you set off immediately, . You have been here for far too long - the Legion's assassins could close in at any moment to make an attempt on your life. Do take caution when using the heart - even with the bindings to aid you the power within is dangerous.", ["objectivesText"] = "Return to King Magni Bronzebeard in the hills below Ironforge.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40678] = { ["id"] = 40678, ["name"] = "Twisted Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "It is time we put our work to the test by infusing the most potent source of power I know of - fel magic. Rarely, the Legion's minions will carry fragments of the greater portal stones used to usher in their eredar masters. If you gather enough to form a complete stone, you can use it in Faronaar to call forth the eredar lord Vizuul the Twisted at the Altar of End Times. The bindings Vizuul wears to augment his power should push the Heart to its very limit.", ["objectivesText"] = "Use a Greater Portal Stone to summon Vizuul the Twisted at the Altar of End Times in Faronaar and collect his runebindings. Progress: Do you have the bindings?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 132749, 132750, 132751, 137604, 137623, 139631 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40675, 43524, 43525 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
