[40683] = { ["id"] = 40683, ["name"] = "Discovery Requires Experimentation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I can sense residues of magic all over you. You will be useful. I must study how the demon bodies can handle the fel energies in such large quantities. I have plenty of flesh to sample, but there must be something... Go retrieve some spines from the nearby basilisks so that I may analyze their magical residues. No sense in both of us getting our hands dirty, is there?", ["objectivesText"] = "Collect 8 Felfire Spines from Felfire Basilisks. Progress: I hope you brought enough. I will require more energy before my studies are complete.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133793 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40625 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40684] = { ["id"] = 40684, ["name"] = "The Tome of Blighted Implements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 628, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 40685, 40716, 40729 }, ["description"] = "The book you carry is the key to your friends' salvation, and to your absolute power! It holds within information about many relics too dangerous to the Legion to leave unchecked. Read, friend. And decide which of these artifacts you will use to strike Jagganoth down!", ["objectivesText"] = "Speak with Calydus to choose which artifact you will pursue. Progress: Have you made your choice?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128941, 128942, 128943 }, ["starts"] = { { ["x"] = 0.563, ["y"] = 0.65, ["mapID"] = 628, ["npcID"] = 101097 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.65, ["mapID"] = 628, ["npcID"] = 101097 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.563, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 101097, ["questTurnInID"] = 101097, ["questType"] = "standard", ["sourceQuests"] = { 40729 }, ["questLines"] = { { ["id"] = 274, ["name"] = "The Tome of Blighted Implements", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[40685] = { ["id"] = 40685, ["name"] = "Into the Mouth of the Nether", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40685 }, ["series"] = { 40684, 40716, 40729 }, ["description"] = "With the ritual failed and the council scattered, you find yourself trapped in the prison of the pit lord, Jagganoth. The situation is grim, but with the help of the remaining council members, you may be able to escape.", ["objectivesText"] = "Escape from Dreadscar Rift.", ["rewardGold"] = 154000, ["rewardXP"] = 200, ["rewardItems"] = { 132512 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
