[40694] = { ["id"] = 40694, ["name"] = "One Small Step for Magic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "It is time to embrace the future. I have mastered every magic known to our kind. I will master this one. By applying the principles of arcane magic it is fairly trivial to control the primitive fel energies within the material you have given me. I need to move to live prey next. Let us start with a small summoning. Defeat the creature for me and watch how a true scholar works!", ["objectivesText"] = "Speak to Kyrtos and assist him with his ritual. Progress: Ahh, this is a most interesting observation.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140238, 217930 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40657, 40683 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
