[40705] = { ["id"] = 40705, ["name"] = "Priestly Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 40706 }, ["description"] = "<Master/Mistress> <name>, I come at the behest of one who seeks to organize a stronger resistance to the Legion threat. If you would meet him at Faol's Rest in Tirisfal Glades, he will guarantee both your safety and an opportunity to play a pivotal role in the conflict.", ["objectivesText"] = "Attend the secret meeting at Faol's Rest in Tirisfal Glades.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 173373 }, ["starts"] = { { ["npcID"] = 101344 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questGiverID"] = 101344, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 18 },
[40706] = { ["id"] = 40706, ["name"] = "A Legend You Can Hold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 40705 }, ["description"] = "To face the trials ahead, you require a weapon that can enhance your considerable abilities. I have learned of a few possibilities that you might consider. You must decide which weapon to pursue first. I have the utmost confidence in your decision.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128825, 128827, 128868 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["sourceQuests"] = { 40705 }, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 18 },
[40710] = { ["id"] = 40710, ["name"] = "Blade in Twilight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 18, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "I have been working with Moira Thaurissan to infiltrate the Twilight's Hammer cult. We've learned of an ancient and powerful Old God relic, a blade used at various points in history to wreak havoc. Moira's double agent informs us a new leader is rising, and plans to cement his ascension using this weapon in an unholy ritual. You must find him, stop the ritual, and seize the artifact. We will meet in Dalaran afterwards.", ["objectivesText"] = "Stop the ritual and acquire Xal'atath, Blade of the Black Empire. Progress: Not too difficult a task, I hope!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 173523 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 }, { ["mapID"] = 18, ["npcID"] = 231472, ["x"] = 0.128, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18, 84 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["sourceQuests"] = { 40706 }, ["questLines"] = { { ["id"] = 219, ["name"] = "Blade in Twilight", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 219, ["questLineOrder"] = 8 }, { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[40712] = { ["id"] = 40712, ["name"] = "The Power Possessed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 627, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "I was wrong about you, warlock. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge. Nevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Ulthalesh, I can think of no safer place than in your care. May it serve you well against the Legion, warlock.", ["objectivesText"] = "Return to Calydus in The Underbelly in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 140192 }, ["starts"] = { { ["x"] = 0.685, ["y"] = 0.287, ["mapID"] = 46, ["npcID"] = 101282 } }, ["ends"] = { { ["x"] = 0.685, ["y"] = 0.287, ["mapID"] = 46, ["npcID"] = 101282 } }, ["coords"] = { ["mapID"] = 46, ["x"] = 0.685, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questGiverID"] = 101282, ["questTurnInID"] = 101282, ["questType"] = "standard", ["sourceQuests"] = { 40623 }, ["nextQuests"] = { 40731 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40713] = { ["id"] = 40713, ["name"] = "The Black Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["description"] = "I have made a great discovery, . There is a powerful warlock in the Soul Engine, in possession of a powerful tome. It contains forbidden secrets to summoning the most powerful of demons. Even the Legion is afraid to call on these fel lords, but now I possess knowledge beyond theirs. Fetch me the tome and I will never want for magic again.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142054 }, ["starts"] = { { ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708, ["mapID"] = 680 } }, ["ends"] = { { ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708, ["mapID"] = 680 } }, ["coords"] = { ["x"] = 0.268, ["y"] = 0.708, ["source"] = "quest_giver", ["mapID"] = 680 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40694 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40714] = { ["id"] = 40714, ["name"] = "The Call To War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39799, 39832, 40714 }, ["series"] = { 40715 }, ["description"] = "Hear me, . The Legion has returned. They hope to control us, to bend us to their will. Fools - they only walk back within reach of our blades. Your brethren within Dalaran have begun to gather at Krasus' Landing. Go, meet with Duke Lankral and all will be explained.", ["objectivesText"] = "Meet with Duke Lankral at Krasus' Landing.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 170, ["name"] = "The Ebon Blade", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40715] = { ["id"] = 40715, ["name"] = "A Pact of Necessity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 40714 }, ["description"] = "We have an unexpected ally in this war, <name>, and we're going to need every advantage we can get to defeat the Burning Legion. The Ebon Blade will serve as the Lich King's arm as long as the Scourge is confined to Northrend. In return for our assistance, our ally has offered to assist in obtaining powerful weapons for the strongest of our knights. Weapons powerful enough to end the Legion once and for all! You are one of our best, <name>. I want you to decide which weapon you would like to seek out.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128292, 128293, 128402, 128403 }, ["starts"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["ends"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.728, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101441, ["questTurnInID"] = 101441, ["questType"] = "standard", ["sourceQuests"] = { 40714 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40716] = { ["id"] = 40716, ["name"] = "The Sixth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 40684, 40685, 40729 }, ["description"] = "Greetings, warlock. I speak on behalf of the Council of the Black Harvest. With the Legion invasion upon us, it is painfully clear that our only hope is to grow stronger. The council plans to tap into the Twisting Nether and call forth more powerful demon allies. The ritual is ready, but we are short one number. No doubt you have heard of the fate that befell Kanrethad Ebonlocke. You will be his replacement. Do you accept?", ["objectivesText"] = "Meet with Ritssyn Flamescowl in the Circle of Wills beneath Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140192, 140517, 140922, 142057, 142058, 142059, 142063 }, ["starts"] = { { ["npcID"] = 103506 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 103506, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[40717] = { ["id"] = 40717, ["name"] = "Calling of the Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7886, ["mapID"] = 42, ["storyline"] = { 40717, 40755, 42970 }, ["description"] = "<The arcane anomaly turns to address you, speaking in what is clearly Khadgar's voice.> Though I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we must be at our full strength to overcome it. Some will not agree with this position. Please join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms. You'll find it over Deadwind Pass, above Karazhan.", ["objectivesText"] = "Meet Khadgar in Dalaran at its new location above Deadwind Pass.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 139389, 139391 }, ["starts"] = { { ["npcID"] = 114550 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113637, ["x"] = 0.412, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 12 } }, ["questGiverID"] = 114550, ["questType"] = "standard", ["sourceQuests"] = { 46734 }, ["questLines"] = { { ["id"] = 241, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 41 },
[40718] = { ["id"] = 40718, ["name"] = "Calling of the Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7886, ["mapID"] = 42, ["storyline"] = { 40718, 40755, 42970 }, ["description"] = "<The arcane anomaly addresses you in Khadgar's voice.> Though I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we require the full might of Azeroth's people to overcome it. The Horde must become part of the Kirin Tor once again. Some will not agree with this position. Please join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms, above Karazhan.", ["objectivesText"] = "Meet Khadgar in Dalaran at its new location above Deadwind Pass.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 13379 }, ["starts"] = { { ["npcID"] = 114550 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113637, ["x"] = 0.412, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 12 } }, ["questGiverID"] = 114550, ["questType"] = "standard", ["sourceQuests"] = { 46734 }, ["questLines"] = { { ["id"] = 258, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 42 },
[40725] = { ["id"] = 40725, ["name"] = "Arganax", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40725 }, ["description"] = "A satyr known as Arganax has infiltrated the village of Lorlathil in Val'sharah. I believe that Arganax has disguised himself as one of the local residents. Use the demon Eye of Azzorok on the villagers in Lorlathil. If there is a demon disguised as a local, the Eye of Azzorok will reveal their true identity. Uncover the demon infiltrator Arganax , and slay him without mercy.", ["objectivesText"] = "Find and slay Arganax in Lorlathil.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["rewardItems"] = { 132877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40727] = { ["id"] = 40727, ["name"] = "All Along the Waterways", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I've noticed some wandering eyes, lately. I am more than happy to continue delivering the goods to Vanthir , but it is getting increasingly dangerous to do so. The Duskwatch that walk the bazaar are by far the most observant. Find and slay the Orbitists so that I may deliver the goods safely. I will follow behind with the shipment.", ["objectivesText"] = "Slay 3 Duskwatch Orbitists . Progress: What of Deline ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41878 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40729] = { ["id"] = 40729, ["name"] = "The New Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["series"] = { 40684, 40685, 40716 }, ["description"] = "It is time to begin the ritual, warlock. Be prepared, for the summoning we perform today will be more challenging than any you have known or seen before. Are you ready?", ["objectivesText"] = "Complete the summoning ritual with the Council of the Black Harvest in the Circle of Wills in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 132512, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.573, ["y"] = 0.608, ["mapID"] = 628, ["npcID"] = 101456 } }, ["ends"] = { { ["x"] = 0.573, ["y"] = 0.608, ["mapID"] = 628, ["npcID"] = 101456 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.573, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101456, ["questTurnInID"] = 101456, ["questType"] = "standard", ["sourceQuests"] = { 40716 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[40730] = { ["id"] = 40730, ["name"] = "Redistribution", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I would imagine you thought I would simply have wine to deliver. < Deline chuckles.> If it were that easy, his people would not be starving. <Her expression becomes serious.> These... loyalists, shall we say, enjoy abundance. They dance to the Magistrix's whims and so they have all that they need. There is no Arcwine shortage. The Magistrix created one to keep us in line. They will not miss a few bottles. They have plenty. Search the square and bring as much as you can carry back.", ["objectivesText"] = "Acquire 20 Bottles of Arcwine . Progress: Did you find enough?", ["rewardGold"] = 278548, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 137295, 140255, 141677, 141951, 141952, 142054, 166970 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41878 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40731] = { ["id"] = 40731, ["name"] = "The Heart of the Dreadscar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Friend has the artifact! Now Jagganoth does not stand a chance! Quickly, you must go back to Dreadscar Rift! You may still be able to save your friends from Jagganoth's vengeance. If you take the heart of the overlord , his army will be yours to command!", ["objectivesText"] = "Defeat Jagganoth and take his heart to the Seat of the Overlord in Dreadscar Rift.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 132880, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.564, ["y"] = 0.65, ["mapID"] = 628, ["npcID"] = 101097 } }, ["ends"] = { { ["x"] = 0.564, ["y"] = 0.65, ["mapID"] = 628, ["npcID"] = 101097 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.564, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 101097, ["questTurnInID"] = 101097, ["questType"] = "standard", ["sourceQuests"] = { 40623, 40712, 41155, 41156, 42125, 43254 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[40740] = { ["id"] = 40740, ["name"] = "The Dead and the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 40740 }, ["description"] = "<A powerful mind again touches your thoughts.> Gorelix the Fleshripper is a monstrous demon. The butcher of a thousand worlds, he has exterminated countless races with his axe, the Maw of the Damned . A group of Ebon Blade was dispatched to slay him but they have gone missing. You will succeed where they failed. You will not be alone in this, I've sent Baron Sliver ahead to assist you. Go, obtain the Maw of the Damned and ensure that Gorelix is no more.", ["objectivesText"] = "Travel to Dalaran and fly upon Zeomus to Darkstone Isle. While there, travel through the Demon Portal, find Baron Sliver, and obtain the Maw of the Damned . Progress: It is time to begin, <name>.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 124124, 128292, 128293, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["ends"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.728, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 101441, ["questTurnInID"] = 101441, ["questType"] = "standard", ["sourceQuests"] = { 40715, 43962, 44401 }, ["questLines"] = { { ["id"] = 169, ["name"] = "The Maw of the Damned", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 169, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[40744] = { ["id"] = 40744, ["name"] = "An Ancient Recipe", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "Suramar is... was... an intellectual's dream. We studied everything in there, from alchemy and the arts to the very nature of magic itself. How could we be so foolish as to accept them in? Look at me, lost in the clouds again when there is much to be done. My work requires some fairly difficult ingredients, <race>. Perhaps you would help me procure them? I am going to need some harpy talons . Crushed into a powder, they will be a potent reagent.", ["objectivesText"] = "Collect 6 Harpy Talons . Progress: Do you have what I require, <race>? We don't have much time to spare.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132881, 140252, 140326, 141673, 141945 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99065, ["x"] = 0.455, ["y"] = 0.407 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.407 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42230 }, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40745] = { ["id"] = 40745, ["name"] = "Shift Change", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "This is as good a chance as we are going to get to rescue Verene's daughter. Here is how this is going to work. You are going to wait here for the guard to pass by on their way to their guard shift. Look for something to hide in. < Silgryn marks a spot on your map.> You will know the guard by their bright red armor. Follow closely, but not so closely that you are seen. It may be necessary to kill the guard when you reach your destination. The child's name is Korine . Good luck.", ["objectivesText"] = "Hide in the basket and wait for the guard to appear. Follow the guard to their destination. Progress: W-who are you?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138147, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107997, ["x"] = 0.482, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40947 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40746] = { ["id"] = 40746, ["name"] = "One of the People", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "It is time for you to enter the city proper, <name>. I am sending you to my loyal friend Vanthir . I do hope you remember him- I can guarantee that he remembers you. I will not be able to accompany you, but I must stress that the disguise I have granted you is not impervious. Tread carefully, and avoid those who stare too long. Farewell for now.", ["objectivesText"] = "Meet with Vanthir in Suramar City.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41877 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40747] = { ["id"] = 40747, ["name"] = "The Delicate Art of Telemancy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "I hadn't the time to gather my instruments before fleeing the palace. I came here to salvage some equipment. This old workshop is actually several rooms connected by teleporter pads. Elisande's goons are already scouring the place looking for me, but from here I can alter the teleporter network and keep them moving in circles. You go in. I'll monitor your position and ensure the teleporters work normally for you. Find these two parts and bring them back!", ["objectivesText"] = "Collect the Weathered Telemancy Beacon and Cracked Warpsleeve from Oculeth's Workshop. Progress: Salvaging the equipment here is necessary if I am to develop a teleporter network for Thalyssra.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 132893, 132894, 139786, 139890, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.477333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40011 }, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40748] = { ["id"] = 40748, ["name"] = "Network Security", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "We must lock down the facility. Otherwise my esteemed colleagues from the palace could uncover my secrets, which puts any teleporters I build for you and Thalyssra at risk. <The inactive attunement device near Oculeth hums to life.> This will take us to my secret test chamber beneath the mountain. From there we can begin the lockdown sequence and make our escape!", ["objectivesText"] = "Complete the lockdown sequence in Oculeth's Test Chamber.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 138783, 139786, 139890, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102142, ["x"] = 0.344, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.477333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40747 }, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40749] = { ["id"] = 40749, ["name"] = "A Token of Remembrance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40749 }, ["description"] = "The flower rests peacefully in your hand, glowing softly. While it doesn't appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here. Perhaps laying down some flowers on the remaining graves will ease the gloom.", ["objectivesText"] = "Place 4 Bouquets of Moon Lilies.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132886, 132887 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["startItems"] = { 132885 } },
