[40755] = { ["id"] = 40755, ["name"] = "Hiding in the Stacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7969, ["mapID"] = 42, ["storyline"] = { 40717, 40755, 42970 }, ["series"] = { 42970 }, ["description"] = "Magni's information was enlightening. It should prove handy to have a friend who has the ear of a titan. It's time to head into Karazhan . Not that I need to remind you, but it can be a dangerous place. There are countless strata of spells woven throughout the tower, and the interactions of the forces within can be... unpredictable. Be on your guard. I'll join you inside. I need a moment to... gather my thoughts. This place holds a lot of memories for me.", ["objectivesText"] = "Enter Karazhan and search for knowledge of the Pillars of Creation with Khadgar. Progress: Do you have something for me?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139905, 139934, 139965, 140635 }, ["rewardChoices"] = { 139905, 139934, 139965 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 101547, ["x"] = 0.47, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113836, ["x"] = 0.412, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 42970 }, ["questLines"] = { { ["id"] = 241, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 258, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead" },
[40760] = { ["id"] = 40760, ["name"] = "Emissary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "As if things weren't unsettled enough, guests have arrived... the Illidari. These demon hunters have been imprisoned since their master's fall at the Black Temple. For the Wardens to release them can only mean the peril is dire indeed. Their delegation's leader, Allari \"the Souleater,\" claims Orgimmar faces a hidden threat. I gave them leave to establish a camp within the city... for now. You will speak with her at once. Find out whether this threat is credible.", ["objectivesText"] = "Speak with Allari the Souleater .", ["rewardGold"] = 70225, ["rewardXP"] = 2125, ["rewardItems"] = { 37213, 37396, 37423, 37487, 197639, 197640, 197641, 226194, 234731, 247820, 250117 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100866, ["x"] = 0.456, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 40522 }, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[40761] = { ["id"] = 40761, ["name"] = "Whispers from Oronaar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "Ethereals, the Void, a Dark Naaru... I feel they are all connected. I explored the ruins below while you and Velen were seeking the Crown. There are survivors, <name>. Broken wander the cluster of buildings to our west- I cannot understand much of what they say but I suspect that their minds are not their own. If the Void is to blame, we will need to start our investigation there. I will conduct my own search in the meantime.", ["objectivesText"] = "Investigate the Ruins of Oronaar .", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["sourceQuests"] = { 47238 }, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882 },
[40762] = { ["id"] = 40762, ["name"] = "Zealot's Dues", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40762 }, ["description"] = "Commander Domitille represents the very essence of the Nightborne's corruption. Abhorrent of power not their own, enamoured with their Grand Magistrix to the point of zealotry, and focused utterly on the destruction of the Moon Guard. Take her helm to Lothrius as proof of her demise.", ["objectivesText"] = "Take Commander Domitille's Helm to Lothrius Mooncaller . Provided item:", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 109076, 131811, 136851, 141672 }, ["starts"] = { { ["x"] = 0.353, ["y"] = 0.131, ["mapID"] = 680 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101082, ["x"] = 0.395, ["y"] = 0.328 }, { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["startItems"] = { 136851 } },
[40763] = { ["id"] = 40763, ["name"] = "Casual Redistribution", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40763 }, ["description"] = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. I imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine. With the presence of the demons came rationing. There are many who do not have enough to sustain themselves. Bring me as much Arcwine as you can carry. I will see that it gets to the right people. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(40763)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(40763))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Collect 20 Bottles of Arcwine .", ["rewardItems"] = { 137295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
