[40776] = { ["id"] = 40776, ["name"] = "Kazok'thul", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40776 }, ["description"] = "A rogue felhunter known as Kazok'thul has been terrorizing Azurewing Repose in Azsuna. Felhunters feed on arcane energy and it seems that Kazok'thul has been gorging itself on the mana from nearby Azurewing whelps. Travel to Azurewing Repose and speak with Ardonu to find the last known location of Kazok'thul . Slay the demon and return here when your mission is complete.", ["objectivesText"] = "Find and slay Kazok'thul in Azurewing Repose.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40779] = { ["id"] = 40779, ["name"] = "We Need Even More Power!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40779 }, ["description"] = "Good new, ! I have located another power orb. I last saw it down by the Nightborne encampment to the southwest. I had to get out of there before their patrols saw me, but it should be no trouble for you, now should it?", ["objectivesText"] = "Find the Charged Power Orb.", ["rewardGold"] = 179010, ["rewardXP"] = 4605, ["rewardItems"] = { 129759, 130079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40783] = { ["id"] = 40783, ["name"] = "The Scythe of Elune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40784, 40785, 40834, 40835 }, ["description"] = "I have received word that Tyrande herself has authorized the release of a great artifact, the Scythe of Elune, to aid our cause. Valorn Stillbough has agreed to give up the weapon, which he has kept as part of an investigation into the cursed worgen of Duskwood. I believe that you, champion, will be our best hope at wielding its power without succumbing to the animal rage that ebbs within. You must go to Duskwood, and take up the scythe against our foes!", ["objectivesText"] = "Meet with Valorn Stillbough in the Twilight Grove in Duskwood. Progress: The champion arrives. I hope you are prepared for this burden.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 103778 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 101656, ["x"] = 0.488, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7846 } }, ["questGiverID"] = 103778, ["questType"] = "standard", ["sourceQuests"] = { 40646, 43980, 44431, 44443 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 47 },
[40784] = { ["id"] = 40784, ["name"] = "Its Rightful Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40785, 40834, 40835 }, ["description"] = "Though it goes against my better judgment, it is Tyrande's wish that the Scythe of Elune be brandished once more against the new Legion threat. It is a small comfort to see it wielded by a keeper of the balance, such as yourself. Know that the last time the scythe was wielded, it resulted in great calamity. You must be vigilant to contain the bestial wrath that ebbs within. With those words in your heart, take the scythe and bring its fury against our foes. May the light of Elune protect you.", ["objectivesText"] = "Take the Scythe of Elune from Valorn. Progress: The scythe is yours, <class>.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128306, 128822, 128858, 128859, 175451, 175452, 175453, 175454 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 101656, ["x"] = 0.488, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 101651, ["x"] = 0.488, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 40783 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80 },
[40785] = { ["id"] = 40785, ["name"] = "A Foe of the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40784, 40834, 40835 }, ["description"] = "I cannot believe the Dark Riders found us here. Long have they hunted the scythe to sate their lust for the artifacts of Azeroth. We thought we would be protected within the grove... And now, Valorn is gone... You must become the hunter, <name>. Seek the Dark Riders and recover the scythe. We last encountered them near Manor Mistmantle in Duskwood. Start your search there. And <name>... bring justice to Valorn. The rider must pay.", ["objectivesText"] = "Start your search for the Scythe of Elune at Manor Mistmantle in Duskwood.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 101651, ["x"] = 0.488, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 40784 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 47 },
[40786] = { ["id"] = 40786, ["name"] = "The Smoldering Ember", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Cataclysm Timewalking Dungeon Event", ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 40786 }, ["description"] = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear conversation taking place in Orgrimmar and the familiar sight of circle portals bubbles to the top.", ["objectivesText"] = "Bring the Smoldering Timewarped Ember to Kiatke in Orgrimmar .", ["rewardGold"] = 303800, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 133377 } },
[40787] = { ["id"] = 40787, ["name"] = "The Smoldering Ember", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = false, ["event"] = "Cataclysm Timewalking Dungeon Event", ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40787 }, ["description"] = "Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear the hustle and bustle of Stormwind and the familiar sight of circle portals bubbles to the top.", ["objectivesText"] = "Bring the Smoldering Timewarped Ember to Kiatke in Stormwind.", ["rewardGold"] = 303800, ["rewardXP"] = 200, ["rewardItems"] = { 19971, 33816, 33818, 33820, 33844, 33857, 33869, 33870, 33871, 33873, 33875, 33925, 34109, 34834, 34836, 35348, 35349, 35350, 43007, 44113, 44228, 44983, 45984, 45991, 45992, 46007, 49602, 50362, 67414, 122338, 122339, 122340, 122341, 127669, 129747, 129857, 129922, 129923, 129926, 129928, 129929, 129938, 129940, 129941, 129942, 129943, 129944, 129945, 129946, 129947, 129948, 129949, 129950, 129951, 129952, 129954, 129955, 129965, 133150, 133151, 133152, 133154, 133159, 133160, 133377, 133378, 133511, 133542, 133543, 133545, 143776, 167921, 167922, 187611, 225348 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101759, ["x"] = 0.762, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 133378 } },
[40792] = { ["id"] = 40792, ["name"] = "A Shattered Path Through Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 40792 }, ["description"] = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Follow the Destroyer's star, and walk the paths it reveals.", ["rewardItems"] = { 127853, 129946, 129965, 133543, 226193, 226194, 247821, 250116 }, ["rewardCurrencies"] = { { ["id"] = 1129, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["ends"] = { { ["x"] = 0.336, ["y"] = 0.376, ["mapID"] = 582, ["npcID"] = 94870 } }, ["coords"] = { ["mapID"] = 582, ["x"] = 0.336, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questGiverID"] = 94870, ["questTurnInID"] = 94870, ["questType"] = "standard" },
[40793] = { ["id"] = 40793, ["name"] = "A Matter of Planning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Your weapon is stronger than ever, now is the perfect time to put it to use and take our fight to the Legion. Master Hsu has set up a command table by the training grounds, and has collected reports from our friends and allies around all of Azeroth. When you are ready, Grandmaster, he should have an update prepared for you.", ["objectivesText"] = "Speak to Master Hsu .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 40570, 41003, 42765 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[40794] = { ["id"] = 40794, ["name"] = "Fate of the Queen's Reprisal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 627, ["storyline"] = { 37654, 37657, 37659, 40794, 42220 }, ["description"] = "<This is the kind of intelligence that should be shared. Perhaps someone at the Greyfang Enclave on Dalaran will know what to do with it.>", ["objectivesText"] = "Take the Captain's Log to Lieutenant Surtees at the Greyfang Enclave on Dalaran. Provided item:", ["rewardGold"] = 45200, ["rewardXP"] = 1770, ["rewardItems"] = { 121482, 121488, 122570, 138855, 138856, 138857, 138858, 138859, 138860, 138861, 138862, 141403 }, ["rewardChoices"] = { 121482, 138855, 138856, 138857, 138858 }, ["starts"] = { { ["x"] = 0.656, ["y"] = 0.568, ["mapID"] = 630, ["objectID"] = 239328 } }, ["ends"] = { { ["x"] = 0.656, ["y"] = 0.568, ["mapID"] = 630, ["objectID"] = 239328 } }, ["coords"] = { ["mapID"] = 630, ["x"] = 0.656, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 37659 }, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["startItems"] = { 133328 } },
[40795] = { ["id"] = 40795, ["name"] = "The Fight Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "The Burning Legion has left a trail of ruin all across the face of Azeroth. We must strike at their bases within the Broken Isles if we are to have any hope of ending this war. I've put together a map of the isles and a list of tasks that we will need to have done there. Once you've had a chance to peruse the map, you should choose where we will begin our assault.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.597, ["mapID"] = 709, ["npcID"] = 99179 } }, ["ends"] = { { ["x"] = 0.528, ["y"] = 0.597, ["mapID"] = 709, ["npcID"] = 99179 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.528, ["y"] = 0.597 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 99179, ["questTurnInID"] = 99179, ["questType"] = "standard", ["sourceQuests"] = { 40793 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[40796] = { ["id"] = 40796, ["name"] = "Lingering on the Edge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40796, 40798 }, ["description"] = "I h-have made... mistakes... < Absolon draws in a rasping breath.> I want to make it right... I want to live! But the madness... the WITHERING.. I am... fading. < Absolon stares at you helplessly.>", ["objectivesText"] = "Give Absolon 100 Ancient Mana . Progress: Can you help me? Is there nothing you can do?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101848, ["x"] = 0.3675, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101848, ["x"] = 0.3675, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42229 }, ["questLines"] = { { ["id"] = 5816, ["name"] = "Absolon", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40798] = { ["id"] = 40798, ["name"] = "Cling to Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40796, 40798 }, ["description"] = "Your kindness has inspired me, friend. I thought I would wander forever among the empty husks of the Withered, but Thalyssra invited me in. I have chosen to remain here with my people and together we will take back Suramar . For now I have but one request. Take this letter to my wife. She should know that I still live, among other things. Give her the hope that you gave me.", ["objectivesText"] = "Deliver a letter to Absolon 's Wife, Noressa . Progress: < Noressa eyes you suspiciously.>", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139779, 140235 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101848, ["x"] = 0.3675, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111318, ["x"] = 0.415, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40796 }, ["questLines"] = { { ["id"] = 5816, ["name"] = "Absolon", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40801] = { ["id"] = 40801, ["name"] = "Journey to Azsuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40801 }, ["description"] = "t, I've obtained word that Archmage Khadgar has been able to form a portal that will enable access to the isle of Azsuna. He requests an audience with you at the earliest opportunity. The Kirin Tor have also constructed a permanent waygate to enable speedy movement between here and Dalaran - you can find it near the path down in the village should you wish to use it.", ["objectivesText"] = "Speak with Archmage Khadgar in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40814] = { ["id"] = 40814, ["name"] = "The Power to Survive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "We have long relied on Lord Illidan to vanquish the Legion's strongest warriors - many have expressed concern over our efforts without him. Thankfully, their concerns may not matter much longer. We know of two pairs of blades rumored to be more powerful than even Lord Illidan's that are not yet out of reach. If we act quickly we should be able to hunt down one without forsaking our watch over the Legion's movements. I must defer judgment on which is most worthy of our time to you, <name>.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 99247 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 99247 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99247, ["questTurnInID"] = 99247, ["questType"] = "standard", ["sourceQuests"] = { 39261 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40815] = { ["id"] = 40815, ["name"] = "From Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within. I haven't heard from them in a while. It would be best if you could find and lead them to success. Agreed?", ["objectivesText"] = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 101927, ["x"] = 0.435, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90255, ["x"] = 0.412, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 37660 }, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40816] = { ["id"] = 40816, ["name"] = "The Power to Survive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "Illidan and I may have disagreed, but he was unarguably powerful. He was pivotal in vanquishing some of the Legion's most powerful soldiers. However, that may not matter much longer. There are two pairs of blades rumored to be more powerful than even Illidan's that may still be within reach. Regrettably, our numbers are too few to hunt both while maintaining our vigil over the Legion. I fear our window of opportunity is waning quickly. As the ranking Illidari, that decision falls to you.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127829, 127830, 128831, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 99254 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 99254 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99254, ["questTurnInID"] = 99254, ["questType"] = "standard", ["sourceQuests"] = { 39047 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40819] = { ["id"] = 40819, ["name"] = "Making Arrangements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "Do you recall Varedis, <name>? He was once our lead trainer, but fell with the Black Temple years ago. ...or so we thought. Kor'vas spotted the traitor alongside the Legion... wielding glaives imbued with power unlike anything she'd ever seen. The Kirin Tor have an eredar lord locked away in the Violet Hold that will know where Varedis' stronghold lies. The prison warden has agreed to consider granting us access to the fiend. Time to do some convincing.", ["objectivesText"] = "Meet Kayn Sunfury outside the Violet Hold.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95240 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95240 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 95240, ["questTurnInID"] = 95240, ["questType"] = "standard", ["sourceQuests"] = { 40814, 44383 }, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40823] = { ["id"] = 40823, ["name"] = "Rebuilding the Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "It seems that friend has caught the attention of Mephistroth. This is very bad news, as the dreadlord will surely wish to seek revenge for losing his general. Friend will need more than the Dreadscar to stand against him, you will need powerful warlocks such as those who were captured. Calydus thinks the orc still lies in the pit where you were chained. Friend must revive him, and rebuild the council!", ["objectivesText"] = "Resurrect Ritssyn Flamescowl in Dreadscar Rift. Progress: I will not rest until the council has been rebuilt.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.377, ["y"] = 0.318, ["mapID"] = 717, ["npcID"] = 101097 } }, ["ends"] = { { ["x"] = 0.377, ["y"] = 0.318, ["mapID"] = 717, ["npcID"] = 101097 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.377, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 101097, ["questTurnInID"] = 101097, ["questType"] = "standard", ["sourceQuests"] = { 40731 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[40824] = { ["id"] = 40824, ["name"] = "The Path of the Dreadscar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["description"] = "It would seem that where the council has failed, you have found untold success. These Dreadscar should prove powerful allies, but they may not be enough. For now, we must look to rebuild. I will send agents out to locate the whereabouts of the captured council members, as well as any other warlocks who may be able to aid the cause. Meet me at the scrying pool, and we will plan our action from there.", ["objectivesText"] = "Use the Dreadscar Battle Plans to choose your first zone.", ["rewardGold"] = 28300, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.312, ["y"] = 0.588, ["mapID"] = 717, ["npcID"] = 101921 } }, ["ends"] = { { ["x"] = 0.312, ["y"] = 0.588, ["mapID"] = 717, ["npcID"] = 101921 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.312, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 101921, ["questTurnInID"] = 101921, ["questType"] = "standard", ["sourceQuests"] = { 40823 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
