[40830] = { ["id"] = 40830, ["name"] = "Close Enough", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "<Oculeth's eyes have dulled. His voice trembles.> Are we... are we close? So hungry...", ["objectivesText"] = "Carry Chief Telemancer Oculeth to Thalyssra in Shal'Aran. Progress: Where is Oculeth?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102142, ["x"] = 0.344, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40748 }, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40832] = { ["id"] = 40832, ["name"] = "Call of The Uncrowned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40839 }, ["description"] = "My masters gave me strict instructions to deliver this letter to you as quickly as possible. Its contents are for you and you alone. Good luck.", ["objectivesText"] = "Read the Sealed Letter and follow the instructions within.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128479, 128870, 128872, 133558 }, ["starts"] = { { ["npcID"] = 102018 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102018, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[40834] = { ["id"] = 40834, ["name"] = "Following the Curse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40784, 40785, 40835 }, ["description"] = "In my previous confrontation with your foe, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they once were. Come, we must go to Ariden's Camp in Deadwind Pass. I can explain its significance along the way.", ["objectivesText"] = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 42, 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 40785 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42 },
[40835] = { ["id"] = 40835, ["name"] = "Disturbing the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40784, 40785, 40834 }, ["description"] = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner. Help me search the camp. Let's see if we can find something to lead us to the Dark Riders.", ["objectivesText"] = "Search around Ariden's Camp for clues leading to the Dark Riders.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100729, ["questType"] = "standard", ["sourceQuests"] = { 40834 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40837] = { ["id"] = 40837, ["name"] = "The Deadwind Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40838, 40900 }, ["description"] = "The Nightbane! If they are in Deadwind Pass, then they may be seeking the scythe as well. Let's split up and try to track them down. We'll see where their trail leads...", ["objectivesText"] = "Follow the tracks of the Nightbane worgen.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40835 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40838] = { ["id"] = 40838, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40837, 40900 }, ["description"] = "This sewer grate leads to the catacombs underneath Karazhan. I've never paid it much attention, but it seems to be where the Nightbane are being drawn to. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders and claim the Scythe of Elune. Progress: It is done.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40837 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40839] = { ["id"] = 40839, ["name"] = "The Final Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40832 }, ["description"] = "You walk in the halls of the Uncrowned. We are the slayers of kings, the downfall of empires, the unseen blades that write the true history of this world. Seated before you are the Shadows, the council which aims the blades of the Uncrowned wherever our will demands. We have brought you here today with an offer. Take your seat as the final Shadow and help us lead the Uncrowned. What do you say?", ["objectivesText"] = "Take your seat in the Council of Shadows. Progress: It's up to you, <name>.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128479, 128870, 128872, 136786 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.413, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 40832 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[40840] = { ["id"] = 40840, ["name"] = "A Worthy Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["description"] = "For quite some time, we've been looking for someone who can operate outside these halls. <name>, you are the answer to that search. You will be the blade in the dark that vanquishes our foes. In order to do so, you require weapons capable of striking down the Legion's best. Greymane, Tethys, and Valeera each have devised plans to obtain weapons worthy of the tasks to come. I suggest you hear each out before proceeding.", ["objectivesText"] = "Select a weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128476, 128479, 128870, 128872 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.413, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 40839 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[40847] = { ["id"] = 40847, ["name"] = "A Friendly Accord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 210, ["storyline"] = { 40847 }, ["description"] = "I'd like to offer ya an accord. The Dread Admiral Eliza wields a pair of cursed blades that have made her the scourge of the south seas. She also stole one of me best ships - the Horizon's Edge - and has it anchored off the shore of Azsuna as we speak. If you help me take back me ship, then her cursed blades are yours. Now, assuming that sounds agreeable, meet me aboard the Crimson Veil. We have her docked right in Booty Bay - not a cheap arrangement.", ["objectivesText"] = "Meet Fleet Admiral Tethys aboard the Crimson Veil in Booty Bay.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 173528 }, ["starts"] = { { ["x"] = 0.412, ["y"] = 0.743, ["mapID"] = 626, ["npcID"] = 94159 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 102120, ["x"] = 0.406, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 7502 } }, ["questGiverID"] = 94159, ["questType"] = "standard", ["sourceQuests"] = { 40840, 44034, 44375 }, ["questLines"] = { { ["id"] = 162, ["name"] = "The Dreadblades", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 162, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 210 },
[40849] = { ["id"] = 40849, ["name"] = "The Dreadblades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 40849 }, ["description"] = "I can promise ya a safe journey to Eliza's position, but once we're there... well, we both know there be no guarantees. The plan is simple. We'll take the Crimson Veil as close as we can get her without being seen and disembark from there. Once we're ashore, we'll board the Horizon's Edge, bribe her mutinous crew to hand it over, and hunt down Eliza and her legendary blades wherever she may be. Just say the word when yer ready.", ["objectivesText"] = "Capture the Horizon's Edge and obtain the Dreadblades .", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 102120, ["x"] = 0.406, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 102120, ["x"] = 0.406, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questTurnInID"] = 102120, ["questType"] = "standard", ["sourceQuests"] = { 40847 }, ["questLines"] = { { ["id"] = 162, ["name"] = "The Dreadblades", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 162, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40850] = { ["id"] = 40850, ["name"] = "Prisoners of Greystone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40850 }, ["objectivesText"] = "Captives rescued from the Grey Bazaar Captive leader rescued from Basilisk Pit", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Captives rescued from the Grey Bazaar", ["amount"] = 5, ["type"] = 0, ["objectID"] = 102100, ["orderIndex"] = 0 }, { ["text"] = "Captive leader rescued from Basilisk Pit", ["amount"] = 1, ["type"] = 0, ["objectID"] = 102107, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[40854] = { ["id"] = 40854, ["name"] = "Endless Possibilities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40545 }, ["description"] = "Say, since you're down here, I have something that you might be interested in. <Filgo points over to a husk lying in the junk behind him.> I found that thingy down in Azsuna, just lying on the beach. I'm sure with a little tinkering, an engineer like you could probably get it up and running in no time. Might even be useful against the Legion. Kind of like fighting fel with fel, heh!", ["objectivesText"] = "Bring the Fel Reaver Husk back to Didi the Wrench in Dalaran. Progress: Is there something you need fixed?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133752, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.664, ["y"] = 0.534, ["mapID"] = 628, ["npcID"] = 102193 } }, ["ends"] = { { ["x"] = 0.664, ["y"] = 0.534, ["mapID"] = 628, ["npcID"] = 102193 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.664, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102193, ["questTurnInID"] = 102193, ["questType"] = "standard", ["sourceQuests"] = { 40545 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40855] = { ["id"] = 40855, ["name"] = "Our Man in Azsuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "Yikes! OK. This thing is missing a LOT of parts. Why don't you go hunt down some new gears or whatever while I do what I can to its existing frame? A colleague of ours, down in Azsuna, may be able to help out here. His name's Flintlocke. Fetching parts should keep him out of trouble. Just don't let him BUILD anything.", ["objectivesText"] = "Find Fargo Flintlocke in Azsuna near the Felblaze Ingress.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questType"] = "standard", ["sourceQuests"] = { 40854 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40856] = { ["id"] = 40856, ["name"] = "It'll Cost You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40858, 40863, 40864 }, ["description"] = "If yeh need demon parts, oh aye, this place is right teeming with them fel buggers. Yer bound ta find what'yer lookin' fer probably near them portals they've got jus' sou'east of 'ere.", ["objectivesText"] = "Collect a Fel Reaver Arm and a Fel Reaver Leg from within the Felblaze Ingress. Progress: Found what'cha need yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133753, 133754, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40855 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40857] = { ["id"] = 40857, ["name"] = "Bits and Pieces", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40857, 41157 }, ["series"] = { 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "So many artifacts to catalogue, and never enough time. Good to see you again, <name>. Brann Bronzebeard and the Explorers' League are in Stormheim right now and could use your help tracking down an ancient titan relic. Brann can fill you in on the details when you arrive.", ["objectivesText"] = "Meet with Brann Bronzebeard in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136360, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 321, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40858] = { ["id"] = 40858, ["name"] = "The Missing Pieces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40856, 40863, 40864 }, ["description"] = "Yeh seem ta 'ave everything yeh need. Head back to Didi now wit' yer supplies and giv'er a slap on tha back from me!", ["objectivesText"] = "Head back to Didi the Wrench in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 49040, 123918, 132514, 133671, 133672, 133673, 133674, 136633, 136637, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 102195, ["questType"] = "standard", ["sourceQuests"] = { 40856, 40859 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40859] = { ["id"] = 40859, ["name"] = "The Latest Fashion: Headguns!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "So Grapplehammer's got hisself a whole lotta extra guns, right? Glorious! An'it got me ta thinkin', \"What if we put 'em on our heads?\" Hear me out! See, yer hands are already busy with yer current weapons, but what's yer head doin'? It's just sittin' there LOOKIN' at stuff. That's me plan. Weaponize yer head! You, me lucky <lad/lass>, can test it out. Strap this on. Now, go blast some fel-tainted critters down below. Blammo!", ["objectivesText"] = "Kill 10 Fel Critters using Flintlocke's Headgun Prototype .", ["rewardItems"] = { 133671, 133672, 133673, 133674, 133761, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40855 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40860] = { ["id"] = 40860, ["name"] = "Resupplying the Line", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, I need you to make a delivery for me. Flintlocke's sent word from Val'sharah stating that they're out of bullets. I sent him down there with enough ammo to cut the planet in half, but Flintlocke goes through ammunition the way you or I go through... air. Go help him out!", ["objectivesText"] = "Deliver the Crate of Ammunition to Fargo Flintlocke in Val'sharah. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133772, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questType"] = "standard", ["sourceQuests"] = { 40858 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40861] = { ["id"] = 40861, ["name"] = "In My Sights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "I used up all me bullets on a wee invention of mine. I call it: Tha Deployable Bullet Dispenser! Oh aye. It shoots in-der-scriminantly wit'out all that messy and time-consumin' \"aiming\" or \"thinkin'\" that us people-folk are wont ta do. We had deployed quite a few of 'em east o' here when this swarm of plants came a'thrashin from tha trees. I didn't 'ave time ta go back an' get me turrets. Would ye mind gettin' them back fer me? Or at least, what's left of 'em?", ["objectivesText"] = "Recover 10 Deployable Bullet Dispenser Parts around Moonrest. Progress: Those mean greenies better not've touched me dispensers!", ["rewardGold"] = 683200, ["rewardXP"] = 1415, ["rewardItems"] = { 132509, 133671, 133672, 133673, 133674, 133978, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 40860 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40862] = { ["id"] = 40862, ["name"] = "All Charged Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "If yer gonna wander inta these woods, ye'll be wantin' somethin' with some punch. These plants are a might grabby. I've got me special explosive charges here that should send those fertilizer mutations back to the dirt. Take 'em with yeh and give them viney beasties a what-fer!", ["objectivesText"] = "Use Flintlocke's Gunpowder Charges to kill 15 Shimmering Oleanders.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 97919, 132510, 133671, 133672, 133673, 133674, 133775, 137691, 137692, 137725, 141849, 239607 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 40860 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[40863] = { ["id"] = 40863, ["name"] = "Always the Last Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40856, 40858, 40864 }, ["description"] = "Well, I've worked out all the kinks. Added a few nuts and bolts, and fitted a new housing for the power core. Problem is, none of the batteries I have here seem to work. I think we're gonna have to fashion somethin' new together. I'm gonna need your help, <name>. Let's start by trying a charged gem from the jewelcrafting shop down the way.", ["objectivesText"] = "Find a suitable power source for Didi's design and deliver it to her. Then, see if her new battery actually works. Progress: Hopefully it's not too much trouble finding a suitable power source.", ["rewardItems"] = { 112059, 123919, 132515, 132523, 132524, 132525, 132526, 132528, 132529, 132530, 132531, 133671, 133672, 133673, 133674, 133879, 133880, 133881, 133895, 137691, 137692, 137725, 139495, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questTurnInID"] = 93520, ["questType"] = "standard", ["sourceQuests"] = { 40858 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40864] = { ["id"] = 40864, ["name"] = "Modular Modifications", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40856, 40858, 40863 }, ["description"] = "Now that we got this baby running, let's give it some cool abilities. When I was fixing Reaves up, I installed a module port onto his motherboard. This will allow us to upload anything we want. I'll teach you one of my module designs and you install it on Reaves.", ["objectivesText"] = "Create a Reaves Module: Snack Distribution Mode. Then summon Reaves and install it into him. Progress: I have a lot of other ideas for things we can do, but I only wrote down a couple to start.", ["rewardItems"] = { 112059, 123919, 124109, 124112, 124119, 124121, 132500, 132501, 132502, 132503, 132504, 132505, 132506, 132507, 132509, 132510, 132511, 132513, 132514, 132515, 132516, 132517, 132518, 132519, 132523, 132524, 132525, 132526, 132528, 132529, 132530, 132531, 132982, 133578, 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questTurnInID"] = 93520, ["questType"] = "standard", ["sourceQuests"] = { 40863 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40865] = { ["id"] = 40865, ["name"] = "It's Not Rocket Science", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, I need you to help me track down Flintlocke again. I sent him to Stormheim to gather some materials for an invention of mine and he hasn't been back for days. I'm not worried about Flintlocke, but I DO fear for Stormheim. See if you can find him!", ["objectivesText"] = "Find Fargo Flintlocke in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questType"] = "standard", ["sourceQuests"] = { 40861, 40862 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40866] = { ["id"] = 40866, ["name"] = "The Shell, You Say?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40867, 40868 }, ["description"] = "I know ol' Hobart sent me down 'ere to acquire 'is precious murloc glass thingies, but I have designs of me own! I've seen those murlocs carrying interesting lookin' shells that would go perfectly into me music box I've been workin on. Ya lead the charge an'a I'll be right behind ya.", ["objectivesText"] = "Slay murlocs to collect 10 of their shells for Fargo Flintlocke . Progress: Jes let me finish up 'ere and I'll be right with yeh.", ["rewardItems"] = { 132982, 133671, 133672, 133673, 133674, 133782, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40865 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40867] = { ["id"] = 40867, ["name"] = "Bubble Baubles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40866, 40868 }, ["description"] = "Ol' Hobart wanted me ta gather up these shiny, glass trinkets the murlocs carry around, but those bloody buggers ain't willin' to jes' hand 'em over! I tried the dip-ler-matic approach, but I don't speak murloc, so I just end up shootin' 'em. Maybe you might have better luck gettin' them baubles.", ["objectivesText"] = "Gather 12 Murloc Trinkets from around their camps. Progress: Any luck? Did yeh try shootin' 'em?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133791, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40865 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40868] = { ["id"] = 40868, ["name"] = "Wibbly-Wobbly, Timey-Wimey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40866, 40867 }, ["description"] = "I gotta finish up 'ere, so why don'tcha take those trinkets back to Hobart fer me. 'Sides, I'ma thinkin' he likes ya more than me.", ["objectivesText"] = "Deliver the Murloc Trinkets to Hobart Grapplehammer in Dalaran.", ["rewardItems"] = { 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 102198, ["questType"] = "standard", ["sourceQuests"] = { 40866, 40867 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40869] = { ["id"] = 40869, ["name"] = "Fire and Forget", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "They say, \"When life gives you lemons, make lemonade.\" Well, life gave me a butt-load of guns. So I've been figuring out ways to turn these guns into useful tools. My latest modification is a gun that shoots bandages! Imagine it, you're on the battlefield, you see your ally go down, you pull out your bandage gun, shoot him with it and bam, he's back in the fight! I just need you to test it first and make sure it's safe.", ["objectivesText"] = "Test out the Prototype Pump-Action Bandage Gun on Wounded Kirin Tor Guardians in Dalaran. Use the gun to calibrate it when needed.", ["rewardItems"] = { 132511, 133671, 133672, 133673, 133674, 133928, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questTurnInID"] = 93539, ["questType"] = "standard", ["sourceQuests"] = { 40861, 40862 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40870] = { ["id"] = 40870, ["name"] = "Here Comes the BOOM!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, they stole all my fireworks, the little scamps. You didn't see them? I was just on the verge of creating a new module for Reaves when these kids came in here and ran off with my fireworks. I need them back if I'm going to finish what I'm working on. Can you go get them back for me?", ["objectivesText"] = "Get Didi's fireworks back from the children in Dalaran. Progress: If I ever get my hands on those kids...", ["rewardItems"] = { 132528, 133671, 133672, 133673, 133674, 133794, 133934, 133935, 133936, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questTurnInID"] = 93520, ["questType"] = "standard", ["sourceQuests"] = { 40861, 40862 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40871] = { ["id"] = 40871, ["name"] = "Locke and Load", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40872 }, ["description"] = "Flintlocke's been looking for you, <name>. I think he needs your help again. I sent him out to test out a couple of new inventions of mine back down in Azsuna. Look for him on the shoreline west of Oceanus Cove!", ["objectivesText"] = "Find Fargo Flintlocke in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 64559, 64560, 64561, 64562, 64563, 64564, 64565, 64566, 64567, 64568, 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questType"] = "standard", ["sourceQuests"] = { 40868 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40872] = { ["id"] = 40872, ["name"] = "Going Out With a Bang", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40871 }, ["description"] = "While I was, eh, testin' out this new flight pack fer Hobart, it sorta exploded an' sent me flyin' back over 'ere. You can see all the pieces out there in tha water. Now, I've got these boots 'ere that Hobart gave me to test out too, but they're not quite me size. I figure we could kill two birds with one stone and 'ave ye test 'em out while pickin' up the broken bits of the pack. Mind tha sharks while yer out there.", ["objectivesText"] = "Use the Gunshoes to skim across the water while picking up 15 pieces of Gunpack Debris .", ["rewardItems"] = { 132516, 133941 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40871 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40873] = { ["id"] = 40873, ["name"] = "Keep Yer Powder Dry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40874, 40875, 40876 }, ["description"] = "So while we've got all tha parts for tha pack again, I'm afraid I'm all outta gunpowder. This is the worst thing ta ever happen ta me. But there's hope. Just o'er to tha north are caves filled with crashed ships. Chances are them sea giants crashed one or two ships with cannons. And cannons mean gunpowder, sweet gunpowder. Search their caves fer sum powder an' bring it on back.", ["objectivesText"] = "Gather 8 Barrels of Gunpowder and return them to Fargo in Azsuna. Progress: Try not ta get it wet, I dunna feel like waitin' fer it ta dry out.", ["rewardItems"] = { 132513, 133798 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40872 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40874] = { ["id"] = 40874, ["name"] = "I'd Do It Myself, But...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40873, 40875, 40876 }, ["description"] = "If yer headed over ta tha sea giant caves, do me a favor give those slimy naga a right bludgerin'. They done run oft with me rogue friend an' I figure some revenge is in order. I'd do it meself but ol' Hobart would give me wut-fer if I abandoned his stuff.", ["objectivesText"] = "Kill 10 Hatecoil Slavemasters in the Oceanus Cove.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40872 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40875] = { ["id"] = 40875, ["name"] = "Going to Waste", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40873, 40874, 40876 }, ["description"] = "Me wee rogue friend Lowping were gnome-napped by them dirty naga when we got 'ere. He's gone! They drug him right oft toward tha cove! But 'ere's tha real issue. He 'ad a schematic on 'im fer one of me greatest inventions. And by \"on 'im,\" I mean I tattooed it to tha top o' his head. FOR SAFETY! When ye find 'im, jes shave 'is head and make a quick copy o' tha design.", ["objectivesText"] = "Find Lowping in the sea giant caves, shave his head, and make a copy of the schematic that's tattooed there. Progress: Poor lad's probably bein' tortured as we speak. Curse them scaley beasts!", ["rewardItems"] = { 132515, 133799 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40872 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[40876] = { ["id"] = 40876, ["name"] = "Locke, Stock and Barrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40873, 40874, 40875 }, ["description"] = "Well that jes' about wraps up me work 'ere. I'll start packin up an'ead back ta Dalaran. If yeh wouldn't mind, could yeh tell Hobart 'ow things went down 'ere? Maybe leave out tha bits with tha explodin', tha drownin', an' tha gettin captured an' what not. Yer a proper friend, <name>!", ["objectivesText"] = "Return to Hobart in Dalaran and inform him of Flintlocke's work.", ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 102196, ["questType"] = "standard", ["sourceQuests"] = { 40873, 40874, 40875 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40877] = { ["id"] = 40877, ["name"] = "Halls of Valor: Trigger Happy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "In order to complete my latest invention, I need a special relic known as the Runestone of Vitality . Odyn, king of the Halls of Valor is known to use it to breathe life into his constructs. What I'm asking is no easy task, but I need to take the runestone from Odyn and bring it back to me.", ["objectivesText"] = "Obtain the Runestone of Vitality from Odyn in the Halls of Valor. Progress: I'm glad you're the one going up against a god and not me.", ["rewardItems"] = { 132519, 133802 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questTurnInID"] = 93539, ["questType"] = "dungeon", ["sourceQuests"] = { 40876 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40878] = { ["id"] = 40878, ["name"] = "Assault on Violet Hold: Cheating Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "Hobart was showing me a copy of a design you found, and it got me to thinking of a new module for Reaves. Unfortunately I didn't have the materials required to test it. Could you make me a couple Failure Detection Pylons ? I'll also need a plasmatic laser bolt . You should be able to find one in the Violet Hold.", ["objectivesText"] = "Craft 2 Failure Detection Pylons . Go to the Violet Hold and recover a Plasmatic Laser Bolt and return everything to Didi the Wrench in Dalaran. Progress: Just rip the bolt off of one of the prison cells. I'm sure whatever's inside has long since died.", ["rewardItems"] = { 123919, 132515, 132526, 133946, 136632 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questTurnInID"] = 93520, ["questType"] = "dungeon", ["sourceQuests"] = { 40876 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40879] = { ["id"] = 40879, ["name"] = "It's On With Automatons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questTurnInID"] = 93520, ["questType"] = "standard", ["sourceQuests"] = { 40881 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40880] = { ["id"] = 40880, ["name"] = "Short Circuit", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 71, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40881 }, ["description"] = "While I've got you here, I was wondering if you could track something down for me. I'm sure you're familiar with a Blingtron, yes? Well, I started askin' around, and it seems no one really knows where the design for it came from. One rumor does pop up more than others, though: Area 52. Interested in a field trip?", ["objectivesText"] = "Find the inventor of Blingtron.", ["rewardItems"] = { 30542, 48933, 127840, 132518, 133975 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93520 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93520, ["questTurnInID"] = 93520, ["questType"] = "standard", ["sourceQuests"] = { 40877, 40878 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 26, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71 },
[40881] = { ["id"] = 40881, ["name"] = "Oil Rags to Riches", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 440, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40880 }, ["description"] = "Didi will be very interested in reading the journal you found as well as examining the circuit design. You should return to her as soon as you can.", ["objectivesText"] = "Return to Didi the Wrench in Dalaran and show her the items you've found.", ["rewardItems"] = { 141849 }, ["starts"] = { { ["x"] = 0.695, ["y"] = 0.684, ["mapID"] = 71, ["objectID"] = 246438 } }, ["ends"] = { { ["x"] = 0.695, ["y"] = 0.684, ["mapID"] = 71, ["objectID"] = 246438 } }, ["coords"] = { ["mapID"] = 71, ["x"] = 0.695, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 40880 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 27, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["db2QuestSortName"] = "Nightborne" },
[40882] = { ["id"] = 40882, ["name"] = "Court of Stars: Revamping the Recoil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, you'll be very excited to hear that I've been working on a newer, better version of those goggles that Flintlocke rigged up. The ones I've designed have double the power, but unfortunately they also have double the recoil. I'm afraid if you use them, they'll break your neck. But I found a solution. Deep inside Suramar City lies a magical mechanism that will reduce the recoil to practically nothing. Recover that mechanism for me and we're in business!", ["objectivesText"] = "Go into the Court of Stars and recover the Arcanic Compressor for Hobart. Progress: Those elves probably had no idea the quantum mechanical applications that mechanism has!", ["rewardItems"] = { 133671, 133672, 133673, 133674, 133806, 137975 }, ["rewardChoices"] = { 133671, 133672, 133673, 133674 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.25, ["mapID"] = 627, ["npcID"] = 93539 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93539, ["questTurnInID"] = 93539, ["questType"] = "dungeon", ["sourceQuests"] = { 40877 }, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 28, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40883] = { ["id"] = 40883, ["name"] = "Fate of the Guard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "<Thalrenus looks you over.> You are not one of them. The Nightborne came to our gates hours after the shield over Suramar fell. We thought them friends, despite our long separation. We were wrong. They poured into our stronghold and began the slaughter. We were unprepared. Though we fought, we were beaten. The keep is lost. Our leaders have perished and their corpses lay in the streets. Find them, give them their final rites. While you search, look for survivors. Help them if you can.", ["objectivesText"] = "Find the corpses of Nyellus Starweaver , Galar'thus Rivertree , and Kailea Windfeather and perform funereal rites for them. Progress: Are you here to fight the Nightborne?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101766, ["x"] = 0.289, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101767, ["x"] = 0.336, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42228 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40890] = { ["id"] = 40890, ["name"] = "The Tears of Elune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 629, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.", ["objectivesText"] = "Use the central teleporter in Dalaran and then place the Tears of Elune in the Portrait Room.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129985, 129993, 130001, 130012, 139043, 245739 }, ["rewardChoices"] = { 129985, 129993, 130001, 130012 }, ["starts"] = { { ["x"] = 0.537, ["y"] = 0.558, ["mapID"] = 641, ["objectID"] = 248534 } }, ["ends"] = { { ["x"] = 0.537, ["y"] = 0.558, ["mapID"] = 641, ["objectID"] = 248534 } }, ["coords"] = { ["mapID"] = 641, ["x"] = 0.537, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38743 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
