[40898] = { ["id"] = 40898, ["name"] = "Fresh Meat", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "This crater is infested with felfire basilisks. They may not be the most cunning of creatures, but they are as vile and dangerous as any demon. However, they may yet prove useful to us. Slay the basilisks, but return to me with chunks of their fel-infused flesh. I have plans to make use of their freshly carved flesh...", ["objectivesText"] = "Collect 6 Fresh Fel-Flesh . Progress: Do you have the Fresh Fel-Flesh I require?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 53563, 53564, 53565, 133743, 140239, 141938, 141939, 156996 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40297, 44489 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40900] = { ["id"] = 40900, ["name"] = "The Burden Borne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40837, 40838 }, ["description"] = "Your assistance against the Dark Riders has proven a great service to the Light. Though our beliefs may separate us, I know that we share one goal. You have allowed me to fill my purpose in returning these artifacts to their rightful owners, and for this I am thankful. As for the Scythe of Elune, I can think of no safer place than in your care. May it serve you well against the Legion, <name>.", ["objectivesText"] = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100812, ["questType"] = "standard", ["sourceQuests"] = { 40838 }, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["db2QuestSortName"] = "Day of the Dead" },
[40901] = { ["id"] = 40901, ["name"] = "Grimwing the Devourer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "You have my thanks for rescuing me from captivity, <class>. However, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion. If you wish to continue with me, I need proof of your strength. Grimwing the Devourer is the strongest of the felbats and a suitable test of skill. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears. Return to me with her head and I will not doubt your ability.", ["objectivesText"] = "Slay Grimwing the Devourer. Progress: What news do you bring of Grimwing the Devourer?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 133756, 134065, 141936 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40307, 40898 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40902] = { ["id"] = 40902, ["name"] = "7.0 Suramar - Treasure 002 - Fel Breach - AJB", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40904] = { ["id"] = 40904, ["name"] = "Shadow of the Defiler", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["mapID"] = 80, ["storyline"] = { 40904 }, ["description"] = "Crimson energy swirls within this disturbing object, which seems to have slightly different contours each time your gaze returns to it. Its power is utterly foreign, unlike anything you have seen in Draenor or during your battles with the Legion. Perhaps the keepers of Moonglade, back on Azeroth, might have some insight into its nature.", ["objectivesText"] = "Consult the keepers of Moonglade to see if they can shed any light on the nature of the Remnant of Chaos . Progress: I have heard of your deeds beyond the red portal, <name>. Two worlds owe you and your companions a great debt. What brings you to the Moonglade?", ["rewardXP"] = 1365, ["rewardItems"] = { 20644, 123890, 128422, 133762 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 102432, ["x"] = 0.364667, ["y"] = 0.415333 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["startItems"] = { 133762 } },
[40905] = { ["id"] = 40905, ["name"] = "Lieutenant Strathmar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40905 }, ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121735, 138839, 139390 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2VignetteID"] = 1239, ["db2VignetteName"] = "Lieutenant Strathmar" },
[40906] = { ["id"] = 40906, ["name"] = "Serpents from the Deep", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40906 }, ["description"] = "Hail, . My village of Jandvik has fallen under siege by a group of naga called the Sashj'tar. Normally I would not seek out the help of an outsider, but we are facing an enemy that we are incapable of defeating. Many powerful elven relics can be found in the ruins around Jandvik. In exchange for your help, you will have your just rewards. Do we have an accord?", ["objectivesText"] = "Speak with Toryl outside of Jandvik.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40907] = { ["id"] = 40907, ["name"] = "Removing Obstacles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "<class>! Interested in earning some coin? The jarl of Jandvik is missing and two headstrong whelps are vying to take over leadership. I should be the next jarl, not them! I want you to enter Jandvik and defeat Calder and Eynar in mortal combat. I would not normally put my trust in an outsider, but this situation requires the aid of someone like you. Jandvik would condemn me if I were caught with their blood on my hands. Meet me in the center of Jandvik when the deed is done.", ["objectivesText"] = "Kill Calder and Eynar in Jandvik. Progress: Do not underestimate Calder and Eynar .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102309, ["x"] = 0.654, ["y"] = 0.511 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99948, ["x"] = 0.705, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.511 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42230 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40908] = { ["id"] = 40908, ["name"] = "Jarl Come Back Now", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "You seem to follow my commands well, <name>. Perhaps I can use you again. Jarl Throndyr , the leader of Jandvik, has been missing for some time now. I assume that he has fallen in battle to the invading Sashj'tar naga, but I must know for certain. Find out what has become of him. Do this task for me and I can assure you that my vrykul will not harm you.", ["objectivesText"] = "Locate Jarl Throndyr in Azuregale Bay.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99948, ["x"] = 0.705, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99559, ["x"] = 0.69, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40907 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40919] = { ["id"] = 40919, ["name"] = "Fel Bent for Leather", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "Ah, my faithful assistant. I have just the task for you. As you have seen, fel power permeates living tissue and can easily be coaxed out. Also, these damned bats are driving me to my wits' end. There is an opportunity to kill two bats with one blade, it seems. Your blade. Take this crystal. It should rip those hellions from the sky and into your waiting arms. You may as well bring back their hides, if only to shut up that fellow in the corner for a few moments.", ["objectivesText"] = "Collect 50 Felbat Hide Scraps for Kyrtos . Progress: Have you obtained the hides?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133780, 133925 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40694 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40920] = { ["id"] = 40920, ["name"] = "Stonebinder Bounty", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40920 }, ["objectivesText"] = "Bitestone drogbar slain", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bitestone drogbar slain", ["amount"] = 8, ["type"] = 0, ["objectID"] = 94261, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[40925] = { ["id"] = 40925, ["name"] = "Bitestone Burglary", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40925 }, ["objectivesText"] = "Obtain a Disguise Drog Bitestone burgled Contaminate Stolen Drog Prized Racing Snail recovered Private Stalk collected", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127271, 133808, 133874, 133987, 134015, 134016 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Obtain a Disguise Drog", ["amount"] = 1, ["type"] = 0, ["objectID"] = 102366, ["orderIndex"] = 0 }, { ["text"] = "Bitestone burgled", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Contaminate Stolen Drog", ["amount"] = 50, ["type"] = 0, ["objectID"] = 102406, ["orderIndex"] = 2 }, { ["text"] = "Prized Racing Snail recovered", ["amount"] = 7, ["type"] = 0, ["objectID"] = 102407, ["orderIndex"] = 4 }, { ["text"] = "Private Stalk collected", ["amount"] = 10, ["type"] = 1, ["objectID"] = 133874, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[40927] = { ["id"] = 40927, ["name"] = "Jandvik's Last Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["series"] = { 41426 }, ["description"] = "Commander Malt'his was conferring with a sea giant? Without your help, this village will surely fall to the combined forces of the Sashj'tar and the sea giants. < Toryl stands there quietly for a moment.> Meet me in an underground cave out in Azuregale Bay. I want to show you something that may turn the tide in this battle.", ["objectivesText"] = "Meet with Toryl in the Sashj'tar Grotto.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99948, ["x"] = 0.705, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102390, ["x"] = 0.76, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41034 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40929] = { ["id"] = 40929, ["name"] = "Symbols of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "This demon has information that could lead us to those in charge. Unfortunately, he is more fearful of his master than he is of us. We need to change his mind about that. The most powerful Burning Legion soldiers often carry an emblem of their rank and status within the demon army. Seek out the stronger demons in Felsoul Hold, slay them, and return to me with their emblems. We will show this wyrmtongue servant who it is he should fear...", ["objectivesText"] = "Collect 8 Legion Emblems . Progress: Do you have the Legion Emblems ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133807, 140239, 141938, 141939, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40901, 44490 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40930] = { ["id"] = 40930, ["name"] = "Apocalypse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40931, 40932 }, ["description"] = "<The Lich King's chill voice fills your mind once again> There is an ancient blade, lost in the echoes of time, that has the power to bring my vengeance upon the Legion. It is known as Apocalypse. I've sensed the blade in the possession of the Dark Riders of Deadwind Pass. Their magic conceals them from my sight but they cannot hide from the scourge! They were last seen by my agents near a place called Manor Mistmantle. Go there, <name>. Defeat the Dark Riders, and claim the blade!", ["objectivesText"] = "Start your search for Apocalypse at Manor Mistmantle in Duskwood. Progress: And just why should I help you, <class>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 24107, 24108, 24109, 65685, 65705, 65723, 124124, 128292, 128293, 128402, 128403, 131257, 131702, 136922, 139506, 139673, 139676, 139680, 140517, 140923, 153048, 173527 }, ["starts"] = { { ["x"] = 0.728, ["y"] = 0.468, ["mapID"] = 627, ["npcID"] = 101441 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questGiverID"] = 101441, ["questType"] = "standard", ["sourceQuests"] = { 40715, 43962, 44401 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 47 },
[40931] = { ["id"] = 40931, ["name"] = "Following the Curse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40930, 40932 }, ["description"] = "Very well. I suppose an introduction is in order. I am Revil Kost , priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them. The Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before. Come with me to Ariden's camp. I will explain on the way.", ["objectivesText"] = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128293, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 42, 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 40930 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42 },
[40932] = { ["id"] = 40932, ["name"] = "Disturbing the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40930, 40931 }, ["description"] = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner. Help me search the camp. Let's see if we can find something to lead us to the Dark Riders.", ["objectivesText"] = "Search around Ariden's Camp for clues leading to the Dark Riders.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128293, 128402, 128403 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100729, ["questType"] = "standard", ["sourceQuests"] = { 40931 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40933] = { ["id"] = 40933, ["name"] = "A Grisly Task", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40934, 40935 }, ["description"] = "Wet soil? Shallow graves? I think the journal is referring to the gravesites off of the lake near Karazhan. Nobody knows who is buried there, but they may be the key to finding the Dark Riders. You can... speak to the dead, yes?", ["objectivesText"] = "Raise the dead buried in the Sodden Graves in Deadwind Pass until you find one who can point you to the Dark Riders location.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128293, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40932 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40934] = { ["id"] = 40934, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40933, 40935 }, ["description"] = "The catacombs? I've never heard of such a place. Unless, he means... There's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse. Progress: Didyou find what you seek, <class>?", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["rewardItems"] = { 128293, 128402, 128403 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100812, ["questType"] = "standard", ["sourceQuests"] = { 40933 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40935] = { ["id"] = 40935, ["name"] = "The Call of Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 648, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40933, 40934 }, ["description"] = "I was wrong about you, death knight. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge. Nevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Apocalypse, I can think of no safer place than in your care. May it serve you well against the Legion, death knight.", ["objectivesText"] = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403 }, ["starts"] = { { ["x"] = 0.684, ["y"] = 0.27, ["mapID"] = 46, ["npcID"] = 101282 } }, ["ends"] = { { ["x"] = 0.684, ["y"] = 0.27, ["mapID"] = 46, ["npcID"] = 101282 } }, ["coords"] = { ["mapID"] = 46, ["x"] = 0.684, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questGiverID"] = 101282, ["questTurnInID"] = 101282, ["questType"] = "standard", ["sourceQuests"] = { 40934 }, ["nextQuests"] = { 39757, 39832 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[40938] = { ["id"] = 40938, ["name"] = "The Light and the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["description"] = "Alonsus Faol has been a valuable ally, and his instincts about you have proven true. I believe you are uniquely suited to assist in a matter that will bring a great force of good into this world. I must take you somewhere far from Azeroth to finish a task my people began long ago. Will you aid us?", ["objectivesText"] = "Aid Velen with his mysterious task. Progress: We have important work to do, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.209, ["mapID"] = 627, ["npcID"] = 101313 } }, ["ends"] = { { ["x"] = 0.466, ["y"] = 0.209, ["mapID"] = 627, ["npcID"] = 101313 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.466, ["y"] = 0.209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101313, ["questTurnInID"] = 101313, ["questType"] = "standard", ["sourceQuests"] = { 40710, 41632, 42074 }, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[40941] = { ["id"] = 40941, ["name"] = "Missive: Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 40941 }, ["description"] = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.", ["objectivesText"] = "Assault the Blackrock forces at the Pit in Gorgrond.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["ends"] = { { ["npcID"] = 78495, ["x"] = 0.408, ["y"] = 0.518, ["mapID"] = 525 } }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "group", ["startItems"] = { 133876 } },
[40942] = { ["id"] = 40942, ["name"] = "Missive: Assault on the Pit", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 40942 }, ["description"] = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.", ["objectivesText"] = "Assault the Blackrock orcs at the Pit in Gorgrond.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 81152, ["x"] = 0.406, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "group", ["startItems"] = { 133878 } },
[40943] = { ["id"] = 40943, ["name"] = "Missive: Assault on the Heart of Shattrath", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 40943 }, ["description"] = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.", ["objectivesText"] = "Assault the Sargerei force in Shattrath City in Talador.", ["rewardGold"] = 679200, ["rewardXP"] = 1365, ["rewardItems"] = { 251547 }, ["rewardCurrencies"] = { { ["id"] = 823, ["amount"] = 1000 } }, ["ends"] = { { ["npcID"] = 78495, ["x"] = 0.408, ["y"] = 0.518, ["mapID"] = 525 } }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "group", ["startItems"] = { 133884 } },
