[40947] = { ["id"] = 40947, ["name"] = "Special Delivery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "Verene's child has gone missing. I can guess what happened, but I need to be sure. Most guardsmen use couriers to relay delicate information. In this, magic is strictly the province of high ranking officials. Take this blade. Do not touch the cutting edge. Use it to silently waylay the couriers and collect any correspondence they carry. With any luck, the missives will tell us exactly where to find the girl. We guards know everything, after all. < Silgryn offers you a winning smile.>", ["objectivesText"] = "Acquire 3 Stacks of Letters from Nightborne Couriers using the Nightborne Spellblade . Progress: Were you successful?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 30256, 30257, 30258, 130209, 137299, 137601, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108411, ["x"] = 0.482, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107997, ["x"] = 0.482, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41148 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40949] = { ["id"] = 40949, ["name"] = "Not Their Last Stand", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I've been watching you- you are not with them. <Ivanel coughs quietly.> I am not long for this world, but there is one thing I would have you do while you are here. The hippogryphs here still fight bitterly to defend their home and their companions in the Moon Guard. They have not accepted that the Guard is no more. Please... send them away. Let them know there is nothing left for them to fight for here.", ["objectivesText"] = "Dissuade 5 Lingering Moonfall Hippogryphs Progress: What is it?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106095, ["x"] = 0.296, ["y"] = 0.185 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106182, ["x"] = 0.333, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.296, ["y"] = 0.185 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40883 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40950] = { ["id"] = 40950, ["name"] = "Honoring Success", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40996 }, ["description"] = "All has gone as planned. Your new blades are a testament to that. We will demand a great deal of you in the weeks and months to come, as we must. But we would be remiss if we failed to take a moment to celebrate a job well done. What do you say?", ["objectivesText"] = "Celebrate the successful acquistion of your artifact with your fellow Shadows. Progress: It's kill or be killed.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128479, 128870, 128872 }, ["starts"] = { { ["x"] = 0.414, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.414, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.414, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 40849, 41924, 42504, 42627 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
