[40952] = { ["id"] = 40952, ["name"] = "Hunter to Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 40400, 40402, 40403, 40419, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "Now that you wield Thas'dorah, it's time to learn more about the night elf who set you on this journey I suggest returning to the Hunter's Reach shop where you met my courier. Whoever this Emmarel Shadewarden is, it seems she has some part to play in the war against the Legion.", ["objectivesText"] = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden .", ["rewardGold"] = 315000, ["rewardXP"] = 175, ["rewardItems"] = { 17687, 38741, 39040, 39066, 39108, 39330, 39373, 39428, 39448, 61124, 61125, 61126, 61127, 116394, 121802, 131202, 139902, 139932, 139962, 140002, 155383, 159038, 159039, 159040, 159041, 184373, 184374, 246492, 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["starts"] = { { ["x"] = 0.661, ["y"] = 0.454, ["mapID"] = 627, ["npcID"] = 102570 } }, ["ends"] = { { ["x"] = 0.661, ["y"] = 0.454, ["mapID"] = 627, ["npcID"] = 102570 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.661, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102570, ["questTurnInID"] = 102570, ["questType"] = "standard", ["sourceQuests"] = { 40419 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[40953] = { ["id"] = 40953, ["name"] = "On Eagle's Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "Since ancient times, my order has stood vigil on these Broken Isles, watching for the Legion's return. Only a handful of us remain... but that changes today. The artifact you hold is more than a weapon. It is a symbol that will unite hunters of all kingdoms and creeds. I'm sure you have questions. Meet me at the Trueshot Lodge in Highmountain and see with your own eyes what awaits us. Snowfeather and I will make our own way there.", ["objectivesText"] = "Meet Emmarel Shadewarden at Trueshot Lodge in Highmountain.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["starts"] = { { ["x"] = 0.434, ["y"] = 0.264, ["mapID"] = 739, ["npcID"] = 102478 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102578, ["x"] = 0.3976, ["y"] = 0.257 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.3976, ["y"] = 0.257 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7502 } }, ["questGiverID"] = 102478, ["questType"] = "standard", ["sourceQuests"] = { 40385, 40952, 41009 }, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40954] = { ["id"] = 40954, ["name"] = "The Unseen Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "For a thousand years, the Unseen Path has watched and waited. We remained few in number, quietly acting behind the scenes when Azeroth needed us. Only a select few even knew our group existed. But the time for lingering in the shadows is over. Before we begin our work, you should hear more about the Unseen Path.", ["objectivesText"] = "Hear Emmarel's tale.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 21401, 21402, 21403 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102578, ["x"] = 0.3976, ["y"] = 0.257 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.3976, ["y"] = 0.257 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 40953 }, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40955] = { ["id"] = 40955, ["name"] = "Oath of Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40958, 40959, 41008, 41009 }, ["description"] = "Assembled before you are many of our world's greatest archers, rangers, beast masters, and trappers, ready to fight the Legion as one. It is time to take your first step in becoming a true leader of hunters. We gather at the fire pit and take our oaths of service before the statue of Ohn'ahra. Touch the statue and kneel before it while I recite the oath, and the Unseen Path will be reborn!", ["objectivesText"] = "Kneel before the eagle statue and pledge your service to the Unseen Path. Progress: Ohn'ahra has blessed our order!", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.43725, ["y"] = 0.25275 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 40954 }, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40956] = { ["id"] = 40956, ["name"] = "Survey Says...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "It is time to establish the first secure connection in our teleportation network. Take this beacon to the Ruins of Elune'eth above us and survey the area to find a suitable location. Once your survey is complete, place the beacon and I will anchor a connection to it from here.", ["objectivesText"] = "Use the Telemancy Beacon to survey the Ruins of Elune'eth.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 133897, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3664, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 98548, ["questType"] = "standard", ["sourceQuests"] = { 44691 }, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
