[40958] = { ["id"] = 40958, ["name"] = "Tactical Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40959, 41008, 41009 }, ["description"] = "Now that your artifact is ready, it's time to plan your first strike against the Legion. Speak to Tactician Tinderfell , our expert on such matters.", ["objectivesText"] = "Speak to Tactician Tinderfell in the Trueshot Lodge .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 }, { ["mapID"] = 739, ["npcID"] = 102940, ["x"] = 0.476333, ["y"] = 0.530333 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.43725, ["y"] = 0.25275 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 40955 }, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40959] = { ["id"] = 40959, ["name"] = "The Campaign Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 41008, 41009 }, ["description"] = "The Legion believes we are still reeling from our loss on the Broken Shore. Let's prove them wrong. Our scouts have mapped out the Broken Isles, learning everything we can about each region for our imminent assault. Choose where to strike first, and you will lead the Unseen Path's efforts personally.", ["objectivesText"] = "Choose an initial assault point on the Command Map", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 40958 }, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[40960] = { ["id"] = 40960, ["name"] = "Luminous Pearl", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40960 }, ["series"] = { 40961 }, ["description"] = "Balanced upon your fishing hook, you find a pearl unlike any other you've seen before. It shines with a cold, steady light, and its size and weight fluctuate in your hand. This is clearly a magical item, and should be brought to a magical person.", ["objectivesText"] = "Bring the Luminous Pearl to Archmage Khadgar in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124111, 124112, 133755, 133887 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 133887 } },
[40961] = { ["id"] = 40961, ["name"] = "The Dalaran Fountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40961 }, ["series"] = { 40960 }, ["description"] = "You fished this up, did you? I'm... not quite sure what you want ME to do about that. Here. <Khadgar pats you on the head.> \"Good job.\" With regard to the pearl... it does seem to be magical, but I couldn't tell you much more than that. Perhaps it might look nice in the Dalaran fountain?", ["objectivesText"] = "Bring the Luminous Pearl to the fountain in Dalaran. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 7909, 21228, 43512, 133939 }, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.486, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.288, ["y"] = 0.486, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.288, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 40960 } },
[40962] = { ["id"] = 40962, ["name"] = "Dark Waters", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7545, ["mapID"] = 80, ["storyline"] = { 40962 }, ["description"] = "Come with me to the edge of Elune'ara. Its crystal waters can wash away even the darkest shroud to reveal the truth within.", ["objectivesText"] = "Accompany Malfurion to Elune'ara to reveal the nature of the Remnant of Chaos. Progress: Yes, <race>?", ["rewardXP"] = 1365, ["rewardItems"] = { 123890, 128422, 133762 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 102432, ["x"] = 0.364667, ["y"] = 0.415333 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 11832, ["x"] = 0.362, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.415333 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 40904 } },
[40963] = { ["id"] = 40963, ["name"] = "Take Them in Claw", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "We should have seen this coming. My sister is dead, my friends are wounded and we will likely die here. I want revenge. <Lyrea hands you a vial full of growing green liquid.> We cannot beat them, but we can turn the Stronghold against them. Wild hippogryphs are attracted to the scent in this bottle. Wild hippogryphs are also notoriously violent when the object of their attraction is not a hippogryph. Use it to clear a path deeper into the stronghold.", ["objectivesText"] = "Attract 3 Wild Moonfall Hippogryphs to deal with the Nightborne at Moonfall Roost. Progress: I thought I was alone here. Are you here to continue the fight?", ["rewardGold"] = 273848, ["rewardXP"] = 6140, ["rewardItems"] = { 139882, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101767, ["x"] = 0.336, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40883, 40949, 41030 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40964] = { ["id"] = 40964, ["name"] = "The Rift Between", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I was with Lothrius when the Nightborne poured into the stronghold. He and his constructs managed to get the majority of us out of the Athenaeum, but he was cornered before he could make good on his own escape. I know he still lives- I feel it in my gut!- but I cannot go back for him myself. My injuries are too severe. Beakbuck will take you to where we last saw Lothrius. Simply let him know when you are ready to leave. Go quickly, and good luck!", ["objectivesText"] = "Locate Lothrius Mooncaller in the Athenaeum.", ["rewardGold"] = 27385, ["rewardXP"] = 770, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40963 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 689 },
[40965] = { ["id"] = 40965, ["name"] = "Lay Waste, Lay Mines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "They ransacked my library, <name>. If they want our knowledge, we will give it to them. This piece of rune work will allow you to cast an ensnaring spell on the ground. When the Nightborne cross the threshold they will see the true might of the Moon Guard. Teach them well!", ["objectivesText"] = "Slay 50 Nightborne With the Trap Rune . Progress: How fares the education?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133882, 138781, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40964 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40966] = { ["id"] = 40966, ["name"] = "Ritualists in Our Midsts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40966 }, ["objectivesText"] = "Crystal Conduit smashed", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Crystal Conduit smashed", ["amount"] = 7, ["type"] = 0, ["objectID"] = 102795, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[40967] = { ["id"] = 40967, ["name"] = "Precious Little Left", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I have not been able to leave the safety of my guardians to search, but there are three tomes of great importance to me and mine. They contain secrets and cantrips that the Nightborne must NOT obtain. <Lothrius raises his hand to your forehead, cementing the names of three tomes into your mind> If we cannot best them, we must preserve all we can. Hurry, <name>.", ["objectivesText"] = "Locate and recover \" Anthology of the Guard \", \" Magical Manifest of the Moon \", and \" Aftermath of the Well \". Progress: Did you locate them?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133882, 133898, 133899, 133900, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40964 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40968] = { ["id"] = 40968, ["name"] = "Recovering Stolen Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40968 }, ["series"] = { 41108, 41109, 41110 }, ["description"] = "My injuries will not kill me, but I cannot fight. I have my own idea of how to deal with the remaining Nightborne. They destroyed our defense matrix as soon as they arrived. Surely one of them carries the spell focus necessary to reactivate it. Find it, then go to a hippogryph. They linger throughout the Stronghold. These loyal beasts will take you to the skies and take care of the rest.", ["objectivesText"] = "Acquire a Volatile Spell Focus .", ["rewardItems"] = { 133882, 133956, 133957, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 102425, ["questType"] = "standard", ["sourceQuests"] = { 40963 } },
[40969] = { ["id"] = 40969, ["name"] = "Starweaver's Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I will take these tomes to Thalrenus. There is one thing that weighs heavily on my mind, and I would like for you to attend to it in my stead. My wife and life partner, Syrana Starweaver , resides in the Starweaver's Sanctum across the bridge. It fell shortly after the Nightborne entered the Stronghold. If she still lives she will need to know of our efforts. Her power is sorely needed. Give her my best- I will be along shortly.", ["objectivesText"] = "Locate Syrana Starweaver", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101765, ["x"] = 0.33, ["y"] = 0.309 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40965, 40967, 41032 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40970] = { ["id"] = 40970, ["name"] = "The Orchestrator of Our Demise", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "Conjurer Thalerian must be stopped. He immediately sought out my father's private study when he arrived and he has not yet emerged. I worry that he may have found a very dangerous item. It is called the Astromancer's Keystone . It is used to manipulate the stronghold's defenses. Such magic was meant to protect the Moon Guard- used for any other purpose and it becomes unspeakably destructive. Retrieve the Keystone. Slay Conjurer Thalerian to get it, if you must.", ["objectivesText"] = "Slay Conjurer Thalerian and acquire the Astromancer's Keystone . Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133924, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101765, ["x"] = 0.33, ["y"] = 0.309 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103129, ["x"] = 0.3, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.309 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40969 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40971] = { ["id"] = 40971, ["name"] = "Overwhelming Distraction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "Do you see the Nightborne outside this room? They hold us here, like mice in a cage. It is more convenient for them that we are pinned down while they search the Sanctum for my father's relics. My companions and I can escape to higher ground with some help. Take this crystal. While standing on a mana focusing rune, use it to overcharge a Conjurer. Their summons will turn on them and create an opening. Use it well, and we will meet you atop the stronghold when the way is clear.", ["objectivesText"] = "Overcharge 3 Imperial Conjurers using the Inert Crystal . You must be standing on a Mana Focuser to use the crystal.", ["rewardGold"] = 273848, ["rewardXP"] = 6140, ["rewardItems"] = { 133999, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101765, ["x"] = 0.33, ["y"] = 0.309 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103129, ["x"] = 0.3, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.309 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40969 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40972] = { ["id"] = 40972, ["name"] = "Last Stand of the Moon Guard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "This is all that remains of the Moon Guard. Take a good look. We are but a shadow of our former selves, and we have the Nightborne to thank for our demise. For now there is nothing more we can do. If we want to live, we must leave immediately. Retribution can wait.", ["objectivesText"] = "Leave Moon Guard Stronghold with Thalrenus, Lothrius, and Syrana.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101766, ["x"] = 0.289, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40970, 40971 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[40973] = { ["id"] = 40973, ["name"] = "Creating Time", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40973 }, ["description"] = "Thanks in large part to your substantial efforts, we have discovered the whereabouts of a powerful piece of our history. It should enable us to survive whatever else the Nightborne have to throw at us, and hopefully more. However, recovering it will require a great deal of our energy and focus. We will bolster the Starweaver's scrying efforts, but the slightest disruption will ruin this delicate spellwork. See that we are not disturbed. Speak to Syrana Starweaver when you are ready to begin. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(40973)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(40973))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Defend Syrana Starweaver .", ["rewardItems"] = { 133994 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40974] = { ["id"] = 40974, ["name"] = "Latosius' Trial", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40974 }, ["description"] = "I bow to Latosius' wisdom. If we are to endure, it must be you who claims the Amulet. Survive this challenge, , and the might of the Moon Guard will be yours forevermore.", ["objectivesText"] = "Survive the Trial of Latosius.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40975] = { ["id"] = 40975, ["name"] = "Arluin Bribe Tracking", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40976] = { ["id"] = 40976, ["name"] = "Audience with the Warchief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Tensions are running high, demon hunter. Warchief Vol'jin was gravely wounded in a disastrous assault on the Broken Shore. I suggest you offer your skills in service of the Horde before your presence is... misinterpreted. High Overlord Saurfang commands the city's defenses. Though wary of the Illidari, I believe he will give you a chance to prove your worth. Speak to him and request passage into Grommash Hold.", ["objectivesText"] = "Speak to High Overlord Saurfang.", ["rewardGold"] = 278548, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 97296, ["x"] = 0.725, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1, 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
