[40982] = { ["id"] = 40982, ["name"] = "Second Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Sylvanas becoming Warchief may be problematic. In life she was a proud ranger, known to many in our ranks. But since the Scourge took her, some of her own allies do not trust the Banshee Queen. The Legion will strike at the first hint of dissension. Even now, I sense something amiss, <name>. I fear that not all is as it seems. Quickly, use your Spectral Sight. We must know if there are foes among us!", ["objectivesText"] = "Use your Spectral Sight. Progress: Time is precious.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[40983] = { ["id"] = 40983, ["name"] = "Demons Among Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It is just as we suspected, <name>! The demons thought they could take us by surprise. Quickly, to arms! Protect the Banshee Queen!", ["objectivesText"] = "Protect the Warchief. Progress: This is what we were born for.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104 }, ["rewardChoices"] = { 129104 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 40982 }, ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
