[40986] = { ["id"] = 40986, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40987 }, ["description"] = "The catacombs? I've never heard of such a place. Unless, he means... There's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse. Progress: Did you find what you seek, <class>?", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100812, ["questType"] = "standard", ["sourceQuests"] = { 40933 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[40987] = { ["id"] = 40987, ["name"] = "The Call of Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 648, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40986 }, ["description"] = "Our goals have been met, death knight, and it is time we part ways. I think I will be glad to see the last of you. Go on, return to your dark masters. We are done here.", ["objectivesText"] = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.684, ["y"] = 0.27, ["mapID"] = 46, ["npcID"] = 101282 } }, ["ends"] = { { ["x"] = 0.684, ["y"] = 0.27, ["mapID"] = 46, ["npcID"] = 101282 } }, ["coords"] = { ["mapID"] = 46, ["x"] = 0.684, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questGiverID"] = 101282, ["questTurnInID"] = 101282, ["questType"] = "standard", ["sourceQuests"] = { 40986 }, ["nextQuests"] = { 39757, 39832 }, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[40988] = { ["id"] = 40988, ["name"] = "Too Many Cooks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40988 }, ["series"] = { 40989, 40990, 40991 }, ["description"] = "Greetings. I am called Nomi . I couldn't help but notice that recipe that you just picked up and... well, you'd never guess it, but I'm a bit of a chef myself. Unfortunately, I'm not much of a fighter, and this place is dangerous. You, on the other hand, are clearly an accomplished <class>. Come find me in Dalaran. Maybe we can work together!", ["objectivesText"] = "Meet Nomi in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124108, 124110, 124117, 124121, 133564, 133575, 133578, 133680, 133814, 133816, 133826, 133827, 198609 }, ["starts"] = { { ["npcID"] = 102546 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102546, ["questType"] = "standard" },
[40989] = { ["id"] = 40989, ["name"] = "The Prodigal Sous Chef", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40989 }, ["series"] = { 40988, 40990, 40991 }, ["description"] = "<name>? Master, is that you? Don't you recognize me? It's me, Nomi ! Remember, we cooked together in Pandaria? More accurately, you cooked and I learned. I was not much more than a cub back then. Boy, am I glad to see you! I'm headed back to the Dalaran kitchens. Come find me! Maybe we can work together!", ["objectivesText"] = "Meet Nomi in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124108, 124110, 124117, 124121, 133564, 133575, 133578, 133680, 133816, 133826, 133827 }, ["starts"] = { { ["npcID"] = 102546 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102546, ["questType"] = "standard" },
[40990] = { ["id"] = 40990, ["name"] = "A Good Recipe List", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40990 }, ["series"] = { 40988, 40989, 40991 }, ["description"] = "I've tried adventuring, and it isn't for me. Cooking is my one true passion: the heat of the stove, the sizzle of bacon... nothing beats it. Let me help you, Master <name>. If you can bring me some recipes, I can work on improving them, here in Dalaran. We'll make a great team. What do you say?", ["objectivesText"] = "Learn 6 Legion cooking recipes. Progress: We need more recipes before we can do any meaningful work in this kitchen.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124108, 124110, 124117, 124121, 133564, 133578, 133680, 133810, 133812, 133813, 133814, 133816, 133817, 133818, 133820, 133826, 133827, 133828, 141011, 141012, 142331, 152565, 194034, 194521, 194549, 194705 }, ["starts"] = { { ["x"] = 0.698, ["y"] = 0.388, ["mapID"] = 627, ["npcID"] = 101846 } }, ["ends"] = { { ["x"] = 0.698, ["y"] = 0.388, ["mapID"] = 627, ["npcID"] = 101846 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.698, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101846, ["questTurnInID"] = 101846, ["questType"] = "standard", ["sourceQuests"] = { 40988, 40989 } },
[40991] = { ["id"] = 40991, ["name"] = "Opening the Test Kitchen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40991 }, ["series"] = { 40988, 40989, 40990 }, ["description"] = "I can cook, but I can't really hunt... or even fish, for that matter. If you bring me ingredients, however, I will use them to research new recipes for you. We can start with the few fish I managed to scrounge up. You'll find them in the barrel in the back of the kitchen.", ["objectivesText"] = "Obtain 5 of Nomi's Silver Mackerel , then bring them to Nomi to research. Progress: Mackerel may not be extravagant, but it will fill your belly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 86425, 124108, 124110, 124117, 124121, 133564, 133578, 133680, 133816, 133827, 133846, 133912 }, ["starts"] = { { ["npcID"] = 101846 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101846, ["questType"] = "standard", ["sourceQuests"] = { 40990 } },
[40996] = { ["id"] = 40996, ["name"] = "Delegation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40950 }, ["description"] = "If I might impart some advice to aid you on the trials and tribulations ahead: do not hesitate to use the many resources of the Uncrowned to aid your efforts. There is a communal board in the tavern beyond this chamber where we organize the efforts of our underlings. Seek out Nikki by the board - she can show you the ropes.", ["objectivesText"] = "Speak to Nikki the Gossip .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.316, ["y"] = 0.664, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.316, ["y"] = 0.664, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.316, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 40950 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[40997] = { ["id"] = 40997, ["name"] = "Lethal Efficiency", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["description"] = "Word is you're headin' down to the Broken Isles. That true? Soon as news got out about the place, we combed through every book, tome, and paper we could get our hands on. We put together quite the report! You should take a look. While you're here, this board is where the magic of the Uncrowned happens. You can put a bounty on a king's head, offer a reward for felsilk cloth... just jot down your latest whim and your agents will take care of it.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.377, ["y"] = 0.448, ["mapID"] = 626, ["npcID"] = 98092 } }, ["ends"] = { { ["x"] = 0.377, ["y"] = 0.448, ["mapID"] = 626, ["npcID"] = 98092 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.377, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98092, ["questTurnInID"] = 98092, ["questType"] = "standard", ["sourceQuests"] = { 40996 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[41000] = { ["id"] = 41000, ["name"] = "King Forgalash's Burden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41000 }, ["description"] = "That sea witch spoke the truth. I witnessed the Tidemistress confer with King Forgalash on several occasions. Kill Forgalash and bring the prow from his shoulder to Fjolrik as proof of his demise. I will meet afterwards in the center of Jandvik. I need to warm myself by its fires.", ["objectivesText"] = "Retrieve Forgalash's Prow from King Forgalash in Forgalash's Den.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 133910 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41001] = { ["id"] = 41001, ["name"] = "Shatter the Sashj'tar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41001, 41499 }, ["description"] = "The Sashj'tar forces may have dwindled, but the Tidemistress has surrounded herself with her fiercest naga. This is the time to strike a final crushing blow against the Sashj'tar. If we can defeat them now, we may finally break the back of this menace and save Jandvik.", ["objectivesText"] = "Kill 12 Sashj'tar naga in the Sashj'tar Ruins. Progress: We must defeat the Sashj'tar once and for all.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41425, 41426, 41709 }, ["questLines"] = { { ["id"] = 5813, ["name"] = "Brandolf", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41002] = { ["id"] = 41002, ["name"] = "A Weapon of the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It would seem I underestimated your initial value. We will have need of your kind in the coming war. I plan to hunt these demons to the ends of Azeroth, and your kind will be the arrow I shall loose upon them. Tell your Illidari within Orgrimmar to make ready to serve the Horde. But make no mistake, your kind once served the Betrayer. Betray me, and there is no world you can run to that will save you from my vengeance.", ["objectivesText"] = "Report to Elthyn Da'rai at the Illidari camp in Orgrimmar .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 40983 }, ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[41003] = { ["id"] = 41003, ["name"] = "The Emperor's Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41003 }, ["description"] = "Ah, Sheilun , the legendary staff wielded by our last emperor. If the Legion were to acquire this weapon, they could unleash untold horrors across the whole of the continent. They must be stopped! If you want to get to the Terrace as fast as possible, you should hitch a ride directly to the mainland. Tak-Tak , a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", ["objectivesText"] = "Retrieve Sheilun , Staff of the Mists, from the Terrace of Eternal Spring. See Tak-Tak to fly directly to the Terrace. Progress: The Terrace of Eternal Spring is a very sacred place for mainland Pandaren. I hope you were able to preserve it from corruption. Enough of Pandaria was destroyed when Garrosh Hellscream turned it into a battlefield.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128937, 128938, 129079, 133948, 140551 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 40636, 43973, 44424 }, ["questLines"] = { { ["id"] = 246, ["name"] = "Staff of the Mists", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 246, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
