[41008] = { ["id"] = 41008, ["name"] = "Hunter to Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41009 }, ["description"] = "I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey. I can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness. Fight well, . May Talonclaw serve you well.", ["objectivesText"] = "Return to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", ["rewardGold"] = 315000, ["rewardXP"] = 175, ["rewardItems"] = { 17687, 38741, 39040, 39066, 39108, 39330, 39373, 39428, 39448, 61124, 61125, 61126, 61127, 116394, 121802, 131202, 139902, 139932, 139962, 140002, 155383, 159038, 159039, 159040, 159041, 184373, 184374, 246492, 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41009] = { ["id"] = 41009, ["name"] = "Hunter to Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008 }, ["description"] = "Now that Titanstrike is yours, ye should learn more about the night elf who set us on this journey. She might well be back at the Hunter's Reach shop where you met her. Whoever this Emmarel Shadewarden is, I'd bet me beard she has some part to play in the war against the Legion! Thanks again fer the fun, <name>. If ye ever have need of me, just call!", ["objectivesText"] = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden .", ["rewardGold"] = 315000, ["rewardXP"] = 175, ["rewardItems"] = { 17687, 38741, 39040, 39066, 39108, 39330, 39373, 39428, 39448, 61124, 61125, 61126, 61127, 116394, 121802, 131202, 139902, 139932, 139962, 140002, 155383, 159038, 159039, 159040, 159041, 184373, 184374, 246492, 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["starts"] = { { ["x"] = 0.699, ["y"] = 0.432, ["mapID"] = 627, ["npcID"] = 106879 } }, ["ends"] = { { ["x"] = 0.699, ["y"] = 0.432, ["mapID"] = 627, ["npcID"] = 106879 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.699, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 106879, ["questTurnInID"] = 106879, ["questType"] = "standard", ["sourceQuests"] = { 42185 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 