[41010] = { ["id"] = 41010, ["name"] = "Fish Frenzy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 41010 }, ["description"] = "<name>! <pant, pant> You've got to see it! The fish, they're... they're everywhere! Off the coast of Val'sharah, something's whipping them up into a frenzy. I've never seen better fishing in my life! I've got a boat down below. Grab your pole and I'll take you there!", ["objectivesText"] = "Follow Nat Pagle to the Gloaming Reef, then dispatch all of the fish in the area.", ["rewardXP"] = 1415, ["rewardItems"] = { 133723, 133755, 133887, 138777, 227669 }, ["starts"] = { { ["npcID"] = 102639 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102639, ["questType"] = "standard", ["sourceQuests"] = { 40961 } },
