[41019] = { ["id"] = 41019, ["name"] = "Actions on Azeroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["description"] = "Let me show you the Command Map. Thanks to some draenei construction and naaru magic we now have a window into the Broken Isles! You can devise strategy, send your agents on missions, and choose our first area to operate in. Take a look and let me know where we are going!", ["objectivesText"] = "Use the Command Map to select your order's first operational area.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.491, ["mapID"] = 702, ["npcID"] = 102655 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.491, ["mapID"] = 702, ["npcID"] = 102655 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.489, ["y"] = 0.491 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 102655, ["questTurnInID"] = 102655, ["questType"] = "standard", ["sourceQuests"] = { 40938 }, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
