[41027] = { ["id"] = 41027, ["name"] = "One Last Breath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41027 }, ["description"] = "To whomever finds this note first, Before I was cast from Suramar , I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne. All of this was forgotten when the Legion came. Before I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea. Drink it and explore the vast deep in my honor.", ["objectivesText"] = "Drink the Nightfallen Alchemist's Strange Draught in Azuregale Bay.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41028] = { ["id"] = 41028, ["name"] = "Power Grid", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40010, 41028, 41138 }, ["series"] = { 40010 }, ["description"] = "This station has fallen into disrepair. The circuit is broken, and to mend it we must recharge the seals in the central chamber. Both a high potency current and low potency current are needed for each seal. Direct the currents to point at the same seal, then engage the seal. Me? I shall supervise. You are the help, after all.", ["objectivesText"] = "Charge the Moon Seal, Star Seal, Beast Seal and Elven Seal in Ley Station: Tel'Anor.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141934 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.4348 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40010 }, ["questLines"] = { { ["id"] = 155, ["name"] = "Feeding Shal'Aran", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 155, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41030] = { ["id"] = 41030, ["name"] = "Sigil Reclamation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "The smooth square sigil weighs a fair amount more than its appearance would suggest. Handling it results in an intense tingling sensation in your palm- this is an object of focused, pure power. Such an advantage should not be so easily surrendered to the Nightborne.", ["objectivesText"] = "Collect 7 Moon Guard Sigils . Progress: What is this?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133675, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["x"] = 0.274, ["y"] = 0.173, ["mapID"] = 680 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101767, ["x"] = 0.336, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40883 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 1, ["flags"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41031] = { ["id"] = 41031, ["name"] = "For the People", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41031 }, ["description"] = "We have a problem, friend. Across the canal is a district not well known for affluence. Since the demons' arrival, it has been locked down. I have heard the cries of those who have been deprived of sustenance. Take this wineskin. Find an Arcwine fountain and take your fill. Find those who are suffering and offer them a drink. It is the best we can do in the present circumstances. You must not be seen doing this, . It will end badly. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(41031)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(41031))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Locate an Arcwine Fountain to fill your Empty Arcwine Skin, then offer Arcwine to Mana-Starved Nightborne.", ["rewardGold"] = 105000, ["rewardXP"] = 150, ["rewardItems"] = { 137343, 137345, 232354, 232401, 232403, 232405, 256228, 256229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41032] = { ["id"] = 41032, ["name"] = "Stop the Spell Seekers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "The Nightborne are here in force. As if that were not worrying enough, they now bring reinforcements. I have seen them opening large portals to Suramar . Through these portals they have called in their constructs. They are immune to much of my magic and so represent something of a stumbling block to rejoining the others. Find the portals and close as many as you can. That should buy us some time.", ["objectivesText"] = "Close 3 Spell Seeker Portals . Progress: I can still sense them, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133882 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40964 }, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41033] = { ["id"] = 41033, ["name"] = "Return to Mardum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The gateway is fully functional, <name>. Ooh, I am positively tingling with excitement! Do let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time. You will be joining us aboard, won't you?", ["objectivesText"] = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.949, ["y"] = 0.665, ["mapID"] = 627, ["npcID"] = 109295 } }, ["ends"] = { { ["x"] = 0.949, ["y"] = 0.665, ["mapID"] = 627, ["npcID"] = 109295 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.949, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 109295, ["questTurnInID"] = 109295, ["questType"] = "standard", ["sourceQuests"] = { 42872 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41035] = { ["id"] = 41035, ["name"] = "Felstorm's Plea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41036, 41085 }, ["description"] = "You may not know me, but I need your help, <name>. Meet me in the Violet Gate and I'll explain everything. Make haste. I fear we have little time.", ["objectivesText"] = "Meet Meryl Felstorm in the Violet Gate in Dalaran.", ["rewardGold"] = 23870, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["npcID"] = 102700 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102700, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41036] = { ["id"] = 41036, ["name"] = "The Dreadlord's Prize", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41035, 41085 }, ["description"] = "Kathra'natir escaped my grasp, but I know what his next step will be. He seeks an ancient relic called the Forge of the Guardian, used for centuries by the Council of Tirisfal to infuse their power into the Guardian. The forge was hidden away, its location known only to the Council themselves. Now the dreadlord has this knowledge. We must go to the Violet Hold. I only hope we are not too late.", ["objectivesText"] = "Defeat Kathra'natir in Violet Hold. Progress: We must hurry!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["npcID"] = 102700 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 41035 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[41037] = { ["id"] = 41037, ["name"] = "Unbridled Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord. Thankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", ["objectivesText"] = "Activate the Fel Hammer and rally your Illidari forces. Progress: Yes?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.577, ["y"] = 0.684, ["mapID"] = 720, ["npcID"] = 95240 } }, ["ends"] = { { ["x"] = 0.577, ["y"] = 0.684, ["mapID"] = 720, ["npcID"] = 95240 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.577, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95240, ["questTurnInID"] = 95240, ["questType"] = "standard", ["sourceQuests"] = { 41221 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41038] = { ["id"] = 41038, ["name"] = "The Mead Master", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 634, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 41039 }, ["description"] = "The Storm Brew is created by a legendary vrykul brewmaster named Melba. Here is the location of her meadery along the northern Stormheim coast. If we can convince her to share her secret recipe with us, we will gain a significant advantage over the enemy. Grandmaster, how are your skills of persuasion?", ["objectivesText"] = "Speak to Aegira in Stormheim. Progress: What do you seek?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102843, ["x"] = 0.626, ["y"] = 0.2095 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.2095 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 41736, 41737, 41738 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41039] = { ["id"] = 41039, ["name"] = "Stolen Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 41038 }, ["description"] = "Morjirn, the head brewer of the Tideskorn clan, has the Storm Brew recipe . I have never been strong enough to assault his fortress alone, but together with you, I think we can claim retribution for my fallen master. I would like nothing better than to pry the recipe from Morjirn's cold, dead fingers. While we are there, we will sample his Storm Brew. I'd like to see if his brewing skills are even near my master's.", ["objectivesText"] = "Taste the Sour Storm Brew, Weak Storm Brew, Blazing Storm Brew, and kill Morjirn for the Storm Brew Recipe . Progress: Do you have the recipe?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133995 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102843, ["x"] = 0.626, ["y"] = 0.2095 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102843, ["x"] = 0.626, ["y"] = 0.2095 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.2095 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 102843, ["questType"] = "standard", ["sourceQuests"] = { 41038 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41040] = { ["id"] = 41040, ["name"] = "Halls of Valor: The Brewmaster", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 704, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 32442, 41059, 41087 }, ["description"] = "I've made a new breakthrough with Melba 's Storm Brew recipe. We need the use of a special cauldron, one owned by Odyn himself. This cauldron is located in none other than the Halls of Valor. There is only one way to enter this exalted place, and that is through the storm god's favor. You must find a way to enter the hall of warriors. You may require allies for this endeavor, <name>.", ["objectivesText"] = "Speak to Melba in the Halls of Valor.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 102843 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7672 } }, ["questGiverID"] = 102843, ["questType"] = "dungeon", ["sourceQuests"] = { 41039 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1477, ["db2PoiUiMapID"] = 704 },
[41041] = { ["id"] = 41041, ["name"] = "Sashj'tar Allies DISBALED", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41041 }, ["description"] = "Commander Malt'his was conferring with a sea giant? We are prepared to battle the naga, but if they have yoked the strength of the sea giants, we will have to double our efforts to save Jandvik. You must tell Toryl about this grave news right away.", ["objectivesText"] = "Speak with Toryl in Jandvik.", ["rewardGold"] = 97000, ["rewardXP"] = 100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
