[41052] = { ["id"] = 41052, ["name"] = "A Desperate Plea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611 }, ["series"] = { 38904, 39654, 42814, 42815 }, ["description"] = "<name>, Saurfang has not been the same since our loss at the Broken Shore. Though he led well and slew many, he has taken our defeat hard. I fear he is determined to return to the Broken Shore. Will you speak to him?", ["objectivesText"] = "Meet with High Overlord Saurfang at Krasus' Landing. Progress: Will you help?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["npcID"] = 93775 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93775, ["questType"] = "standard", ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41054] = { ["id"] = 41054, ["name"] = "Love Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "Malfurion, my love... In vision I saw him, enraged and then distressed, and now lost beyond my mind's reach. <race>, I know we have little reason to trust one another, but I will not turn away your help. If you value the sanctity of this world, you will come with me.", ["objectivesText"] = "Speak with Tyrande Whisperwind at Starsong Refuge.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102938, ["x"] = 0.674, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38753 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
