[41056] = { ["id"] = 41056, ["name"] = "Love Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "Malfurion, my love... In vision I saw him, enraged and then distressed, and now lost beyond my mind's reach. He is strong, but the horrors that have befallen this land are all-consuming. I must find him, and you must help me! Gather your wits, <race>, and follow me.", ["objectivesText"] = "Speak to Tyrande Whisperwind at Starsong Refuge.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102938, ["x"] = 0.674, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38753 }, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
