[41059] = { ["id"] = 41059, ["name"] = "Halls of Valor: Odyn's Cauldron", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 32442, 41040, 41087 }, ["description"] = "Your actions in Stormheim were courageous. I thank you for avenging me, and for helping my apprentice, Aegira. I can think of none better to inherit my knowledge. With you, I will share the secret to my Storm Brew. The true strength of the brew comes from Odyn's Cauldron , which can be found in the great hall just ahead. You have my blessing to borrow it. Good luck in your journey ahead, <name>.", ["objectivesText"] = "Collect Odyn's Cauldron from the Halls of Valor, then pass Odyn 's trial. Progress: Did you pass the trials?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134005 }, ["starts"] = { { ["npcID"] = 103049 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7672 } }, ["questGiverID"] = 103049, ["questType"] = "standard", ["sourceQuests"] = { 41040 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41060] = { ["id"] = 41060, ["name"] = "Unbridled Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord. Thankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", ["objectivesText"] = "Activate the Fel Hammer and rally your Illidari forces. Progress: Yes?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.577, ["y"] = 0.684, ["mapID"] = 720, ["npcID"] = 95237 } }, ["ends"] = { { ["x"] = 0.577, ["y"] = 0.684, ["mapID"] = 720, ["npcID"] = 95237 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.577, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95237, ["questTurnInID"] = 95237, ["questType"] = "standard", ["sourceQuests"] = { 41033 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41062] = { ["id"] = 41062, ["name"] = "Spoils of Victory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The Fel Hammer will be a fine home for our kind, but it is what we found within its depths that is the true prize of our conquest. Battlelord Gaardoun and his Ashtongue have it closely guarded - you should have him show you.", ["objectivesText"] = "Have Battlelord Gaardoun show you what your forces obtained.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.586, ["y"] = 0.589, ["mapID"] = 720, ["npcID"] = 95240 } }, ["ends"] = { { ["x"] = 0.586, ["y"] = 0.589, ["mapID"] = 720, ["npcID"] = 95240 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.586, ["y"] = 0.589 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95240, ["questTurnInID"] = 95240, ["questType"] = "standard", ["sourceQuests"] = { 41037 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[41065] = { ["id"] = 41065, ["name"] = "Troubling News", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 41065 }, ["description"] = "Master, there is one more thing I wish to speak to you about. Below us lies an open chamber cut off from the rest of the citadel. We thought you might desire it as your personal sanctum - a place where you might gather your thoughts or scry upon your enemies. The sanctum crystal before you will transport you there - Lady S'theno has already descended to help you get acquainted.", ["objectivesText"] = "Use the Sanctum Crystal to enter the Master's Sanctum.", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[41066] = { ["id"] = 41066, ["name"] = "The Hunter's Gaze", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<name>, before you lies your nether crucible - more powerful than any we've crafted before. The souls of the hundreds of slain demons in Mardum have provided us with enough power to directly observe the Legion on Azeroth. What we have uncovered so far has been... unsettling. Gaze into the pool and see for yourself.", ["objectivesText"] = "Use the Empowered Nether Crucible to gaze upon the Burning Legion's forces in Azeroth. Progress: The Legion threat is more dire than we thought.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.594, ["y"] = 0.504, ["mapID"] = 721, ["npcID"] = 95238 } }, ["ends"] = { { ["x"] = 0.594, ["y"] = 0.504, ["mapID"] = 721, ["npcID"] = 95238 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.594, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95238, ["questTurnInID"] = 95238, ["questType"] = "standard", ["sourceQuests"] = { 41062, 41070 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[41067] = { ["id"] = 41067, ["name"] = "Time is of the Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "As you can see, there is little time to spare - the Legion's armies already encroach on our world. Kayn has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", ["objectivesText"] = "Speak to Kayn Sunfury .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.588, ["y"] = 0.512, ["mapID"] = 721, ["npcID"] = 95238 } }, ["ends"] = { { ["x"] = 0.588, ["y"] = 0.512, ["mapID"] = 721, ["npcID"] = 95238 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.588, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95238, ["questTurnInID"] = 95238, ["questType"] = "standard", ["sourceQuests"] = { 41066 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41069] = { ["id"] = 41069, ["name"] = "Direct Our Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "We must seal the Tomb of Sargeras at all costs or the flow of demons will never cease. Until then, we must do what we can on the ground to alleviate their foothold before it grows further. This citadel was created to spearhead Legion invasions on other worlds - we can use its navigation systems to plan our assault. I think you would agree that none would be better suited to lead our charge than you.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.595, ["y"] = 0.58, ["mapID"] = 720, ["npcID"] = 95240 } }, ["ends"] = { { ["x"] = 0.595, ["y"] = 0.58, ["mapID"] = 720, ["npcID"] = 95240 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.595, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95240, ["questTurnInID"] = 95240, ["questType"] = "standard", ["sourceQuests"] = { 41067 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41070] = { ["id"] = 41070, ["name"] = "Spoils of Victory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "In conquering this citadel we obtained something that I think would be of great use to you. Gaardoun's men have it well-guarded just below - I suggest you have him show you.", ["objectivesText"] = "Have Battlelord Gaardoun show you what your forces obtained.", ["rewardGold"] = 23870, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.586, ["y"] = 0.589, ["mapID"] = 720, ["npcID"] = 95237 } }, ["ends"] = { { ["x"] = 0.586, ["y"] = 0.589, ["mapID"] = 720, ["npcID"] = 95237 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.586, ["y"] = 0.589 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95237, ["questTurnInID"] = 95237, ["questType"] = "standard", ["sourceQuests"] = { 41060 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[41085] = { ["id"] = 41085, ["name"] = "A Mage's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41035, 41036 }, ["description"] = "It is decided, then. The foundation of the Tirisgarde's strength lies in the ancient artifacts wielded by its champions. Your first task will be to retrieve one such artifact. The master appendix of this library lists every artifact known to the Council of Tirisfal. There should be a few choices in there worth looking into. I will leave it to you to choose which to pursue.", ["objectivesText"] = "Use the Appendix of Azerothian Artifacts to choose an artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862 }, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.59, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 41036 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[41086] = { ["id"] = 41086, ["name"] = "A Peaceful World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "Word has reached us that the Legion is advancing on the Broken Isles. They beset us from all sides, and if we do not stand strong, they will spill over into the rest of Azeroth. <name>, we need your help more than ever. Lend your strength to those defending at the front. We cannot fail here.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["starts"] = { { ["x"] = 0.552, ["y"] = 0.57, ["mapID"] = 709, ["npcID"] = 102820 } }, ["ends"] = { { ["x"] = 0.552, ["y"] = 0.57, ["mapID"] = 709, ["npcID"] = 102820 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.552, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 102820, ["questTurnInID"] = 102820, ["questType"] = "standard", ["sourceQuests"] = { 41911 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41087] = { ["id"] = 41087, ["name"] = "Storm Brew", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 32442, 41040, 41059 }, ["description"] = "Grandmaster, the Legion is attacking the Wandering Isle! We sent defenders up to the Ridge of Laughing Winds, but they can't hold for long. Our only chance is to finish making the Storm Brew. Chen and Aegira have already gone up to the Chamber of Whispers, but they are under heavy attack as well. Speak to Tak Tak and take a kite up to join them at once!", ["objectivesText"] = "Take Tak-Tak's kite to the Ridge of Laughing Winds, help Chen Stormstout & Aegira make the Storm Brew, and defeat the Burning Legion's forces.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139731, 142060, 142061, 142062, 142064 }, ["rewardChoices"] = { 142060, 142061, 142062, 142064 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 32442 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
