[41094] = { ["id"] = 41094, ["name"] = "Hatchlings of the Talon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41094 }, ["description"] = "Greetings, hatchling. Do you wish to soar amongst the clouds as my children do? < Aviana chuckles - a clicking, crow-like noise.> Very well, receive my blessing and we shall see how developed your wings are.", ["objectivesText"] = "Talk to Aviana to receive her blessing, then complete her challenge by collecting Emerald Globes.", ["rewardXP"] = 1415, ["rewardItems"] = { 139773 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97925, ["x"] = 0.322, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97925, ["x"] = 0.322, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 97925, ["questType"] = "standard" },
