[41096] = { ["id"] = 41096, ["name"] = "Time is of the Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "As you can see, there is little time to spare - the Legion's armies already encroach on our world. Altruis has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", ["objectivesText"] = "Speak to Altruis the Sufferer .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.588, ["y"] = 0.512, ["mapID"] = 721, ["npcID"] = 95238 } }, ["ends"] = { { ["x"] = 0.588, ["y"] = 0.512, ["mapID"] = 721, ["npcID"] = 95238 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.588, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95238, ["questTurnInID"] = 95238, ["questType"] = "standard", ["sourceQuests"] = { 41066 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41097] = { ["id"] = 41097, ["name"] = "Shard of Vorgos", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "According to the wyrmtongue servant, there is a portal that will take you into the Burning Legion command ship. However, the portal is locked to those without the keys. The first key shard is held by an Ered'ruin known as Vorgos. He resides within the Fel Breach, which is at the end of the Arcway. Slay Vorgos and place the key shard into its position next to the portal.", ["objectivesText"] = "Collect the Shard of Vorgos . Progress: <The Shard of Vargos pulses in your hand.>", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 134027, 140239, 141605, 141937, 141938, 141939 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 99890, ["questType"] = "standard", ["sourceQuests"] = { 40328, 40929 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41098] = { ["id"] = 41098, ["name"] = "Shard of Kozak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "The demon leading the operation in Felsoul Hold is an eredar named Azoran. In order to get to him, we will need to open a portal to the Burning Legion command ship. Azoran has a demon jailer in his service known as Kozak the Afflictor. Kozak the Afflictor holds one of the key shards necessary to open a portal to the ship. He can be found in the prison quarters known as the Halls of the Eclipse in the lower portion of Felsoul Hold. Slay Kozak and place his key shard next to the portal.", ["objectivesText"] = "Collect the Shard of Kozak . Progress: <The Shard of Kozak tugs as if it wants to fly into place.>", ["rewardGold"] = 528896, ["rewardXP"] = 7675, ["rewardItems"] = { 134028, 140239, 141937, 141938, 141939 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 99890, ["questType"] = "standard", ["sourceQuests"] = { 40328, 40929 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41099] = { ["id"] = 41099, ["name"] = "Direct Our Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The Tomb of Sargeras is the Legion's primary entrance into our world - it must be destroyed. No easy task, but until we have the means to do so we must do what we can to stop their invasion. The Legion used this citadel to spearhead invasions on other worlds - we can use its navigation systems to plan our own assault against them. You, of course, must take the honor of first breaking ground on their territory, but we will soon follow.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.595, ["y"] = 0.58, ["mapID"] = 720, ["npcID"] = 95237 } }, ["ends"] = { { ["x"] = 0.595, ["y"] = 0.58, ["mapID"] = 720, ["npcID"] = 95237 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.595, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 95237, ["questTurnInID"] = 95237, ["questType"] = "standard", ["sourceQuests"] = { 41067 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41105] = { ["id"] = 41105, ["name"] = "The Sword of Kings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 41105 }, ["description"] = "The first king of the humans, Thoradin, performed many acts of heroism and valor. While on a personal quest near the end of his reign, he stumbled upon the tomb of my brother Tyr... and the grave-prison of the monstrosity he died fighting. Thoradin unintentionally awoke the beast and gave his life to keep it from escaping. It is Thoradin's sword, Strom'kar, that has kept the monster at bay. Retrieve it and finish what Tyr and Thoradin started. Kill Zakajz the Corrupted.", ["objectivesText"] = "Find Strom'kar, the Warbreaker and deal with Zakajz. Progress: Ah, you have returned...", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 40579, 43949, 44417 }, ["questLines"] = { { ["id"] = 216, ["name"] = "The Sword of Kings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 216, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[41106] = { ["id"] = 41106, ["name"] = "Call of the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40644, 40645, 40646 }, ["description"] = "Beating the Legion requires us to strike quickly and unexpectedly. We have discovered a Dreamway by which we can travel through the Emerald Dream itself. Though only a short walk through the Dream, it will allow us to cross vast distances on Azeroth and even access the ancient home of all druids, Val'sharah. Malfurion is preparing the ritual to open the Dreamway. I need you to summon Zen'tabra and Naralex to his side. Only by combining our efforts can we hope to succeed.", ["objectivesText"] = "Locate Zen'tabra and Naralex , and direct them to the ritual site. Progress: This ritual must succeed, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["sourceQuests"] = { 40643 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80 },
[41107] = { ["id"] = 41107, ["name"] = "Bad Apples", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41107, 41256, 41258 }, ["description"] = "That fruit over there? That's a pale imitation to what I can grow. But that accursed Daglir somehow manages to gain the favor of the courts, so we must dine on mediocrity! We must teach Daglir a lesson for stealing my crop, but we must be discreet. Outside the shield grows a purple flower called Shadowbloom . Fetch some for me and we'll make sure that he pays dearly for his insolence!", ["objectivesText"] = "Gather 8 Shadowbloom . Progress: I would avoid eating any food until you've washed your hands.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134014, 141948 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5823, ["name"] = "Fruit of the Doom", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41108] = { ["id"] = 41108, ["name"] = "Rain Death Upon Them", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41108 }, ["series"] = { 40968, 41109, 41110 }, ["description"] = "Aboard the hippogryph you now possess a unique opportunity. It is time for the Nightborne to regret letting you live.", ["objectivesText"] = "Slay 50 Nightborne.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103129, ["x"] = 0.3, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41109, 41110 } },
[41109] = { ["id"] = 41109, ["name"] = "Waiting for Revenge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41109 }, ["series"] = { 40968, 41108, 41110 }, ["description"] = "The Volatile Spell Focus hums with energy as you hold it. Handle with care! Only with this item in your possession will the Hippogryphs allow themselves to be mounted. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(41109)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(41109))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Mount a Hippogryph.", ["rewardItems"] = { 133956, 140241, 140242, 140329, 141671, 141943, 142054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40968 } },
[41110] = { ["id"] = 41110, ["name"] = "Waiting for Revenge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41110 }, ["series"] = { 40968, 41108, 41109 }, ["description"] = "The Hippogryph eyes you curiously, searching your hands.", ["objectivesText"] = "Mount the Hippogryph.", ["rewardItems"] = { 133956 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102740, ["x"] = 0.312, ["y"] = 0.235 }, { ["mapID"] = 680, ["npcID"] = 111604, ["x"] = 0.352, ["y"] = 0.166 }, { ["mapID"] = 680, ["npcID"] = 111605, ["x"] = 0.32, ["y"] = 0.132 }, { ["mapID"] = 680, ["npcID"] = 111606, ["x"] = 0.312, ["y"] = 0.112 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102740, ["x"] = 0.312, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 102740, ["questType"] = "standard", ["sourceQuests"] = { 40968 } },
