[41112] = { ["id"] = 41112, ["name"] = "The Great Akazamzarak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 627, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41113 }, ["description"] = "There is a goblin who is a master of portals and teleportation by the name of Akazamzarak. His talents have gone mostly unnoticed, however, since he mostly uses them for chicanery. He is, what you would call, a street performer. Fortunately for us, he is performing in the streets of Dalaran, grifting coins from the unenlightened masses. Take this bag of gold. See if you can convince him to change vocations.", ["objectivesText"] = "Place the Sizeable Pouch of Gold in Akazamzarak's tip bucket .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 127857, 128820, 128862, 134060, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.565, ["y"] = 0.338, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.565, ["y"] = 0.338, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.565, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 41114 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41113] = { ["id"] = 41113, ["name"] = "The Only Way to Travel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41112 }, ["description"] = "Portals? Teleportation? You bet I can help you out with that! I mean, how do you think I pull the rabbit out of... ...um, you didn't hear that. Anyway, I can help you move your mages around, if the price is right. Heck I can even teach those combat mages a thing or two. Ever been on the receiving end of an exploding bunny? It ain't pretty! For starters, let me whip up a portal to take us to this hall you're talking about.", ["objectivesText"] = "Return to Meryl Felstorm in the Hall of the Guardian .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 116395 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.634, ["mapID"] = 627, ["npcID"] = 103092 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.634, ["mapID"] = 627, ["npcID"] = 103092 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.485, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 103092, ["questTurnInID"] = 103092, ["questType"] = "standard", ["sourceQuests"] = { 41112 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[41114] = { ["id"] = 41114, ["name"] = "The Champion's Return", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["description"] = "I can sense the power of the artifact you hold. It will do well against the Legion as it is, but we have the ability to unlock its power even further. You must return to the Hall of the Guardian. You can use the incantation I taught you before to pass through the runes.", ["objectivesText"] = "Teleport to the Hall of the Guardian and return to Meryl Felstorm .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128862, 134058 }, ["starts"] = { { ["x"] = 0.286, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["ends"] = { { ["x"] = 0.286, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.286, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105081, ["questTurnInID"] = 105081, ["questType"] = "standard", ["sourceQuests"] = { 11997, 42011, 42479 }, ["nextQuests"] = { 41112, 41125 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
