[41119] = { ["id"] = 41119, ["name"] = "The Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "You must lead this hunt, <name> - a small force will join you to ensure Varedis meets his end. You must try to make it into Varedis' hold undetected; the less time you spend in Legion territory the better. Meet at Krasus' Landing when you are prepared to leave.", ["objectivesText"] = "Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.504, ["y"] = 0.7, ["mapID"] = 723, ["npcID"] = 103156 } }, ["ends"] = { { ["x"] = 0.504, ["y"] = 0.7, ["mapID"] = 723, ["npcID"] = 103156 } }, ["coords"] = { ["mapID"] = 723, ["x"] = 0.504, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 103156, ["questTurnInID"] = 103156, ["questType"] = "standard", ["sourceQuests"] = { 41121 }, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41120] = { ["id"] = 41120, ["name"] = "Making Arrangements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "Do you remember Varedis? He was once our lead trainer at the Black Temple, but fell early in the siege. ...or so we thought. Kor'vas spotted the traitor amongst the Legion wielding glaives imbued with power unlike anything she'd ever seen. The Kirin Tor have an eredar lord interred in the Violet Hold that will know where Varedis' base of operations is. The hold's warden has agreed to consider granting us access to him. <Altruis smirks.> Time to play the friendly diplomat.", ["objectivesText"] = "Meet Altruis the Sufferer outside the Violet Hold.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95237 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95237 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 95237, ["questTurnInID"] = 95237, ["questType"] = "standard", ["sourceQuests"] = { 40816, 44379 }, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41121] = { ["id"] = 41121, ["name"] = "By Any Means", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7777, ["mapID"] = 723, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "We need to find out Varedis' location from the eredar inside this prison - the kind warden and his men here are all that stand in our way. We'll take them on together if need be - whatever it takes.", ["objectivesText"] = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis. Progress: Well done.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 53265, 53267, 53292, 62178, 62179, 62180, 127830, 128832, 131398 }, ["starts"] = { { ["x"] = 0.656, ["y"] = 0.672, ["mapID"] = 627, ["npcID"] = 103156 } }, ["ends"] = { { ["x"] = 0.656, ["y"] = 0.672, ["mapID"] = 627, ["npcID"] = 103156 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.656, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7777 } }, ["questGiverID"] = 103156, ["questTurnInID"] = 103156, ["questType"] = "standard", ["sourceQuests"] = { 41120 }, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1494, ["db2PoiUiMapID"] = 723 },
