[41137] = { ["id"] = 41137, ["name"] = "Fall of the King", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41137 }, ["description"] = "All that remains is the Sea Giant King. Place our banner upon his beach and draw him out of the sea. Once he has revealed himself, use the trident to wound him. There is a derelict boat that washed up on the shore. Use that to quickly get to the king's island. Gird your loins, . This fight will not be easy.", ["objectivesText"] = "Place the Jandvik Banner on the Sea Giant King's island to draw him out and defeat him.", ["rewardGold"] = 567400, ["rewardXP"] = 7675, ["rewardItems"] = { 134836, 140384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41138] = { ["id"] = 41138, ["name"] = "Feeding Shal'Aran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40010, 41028, 41138 }, ["description"] = "With leyline energy feeding in from Anora, this chamber can begin to awaken. It will be a slow process, and we must take care to mask this activity from our enemies, a process which itself requires enormous effort and focus. Furthermore, there is the conundrum of actually consuming the mana in this form. A stream too weak is not enough to provide sustenance - too powerful and it would vaporize us. There is much work to be done yet. For now, let us examine the feed.", ["objectivesText"] = "Examine the Leyline Feed in Shal'Aran with Arcanist Valtrois .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.4348 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41028 }, ["questLines"] = { { ["id"] = 155, ["name"] = "Feeding Shal'Aran", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 155, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41139] = { ["id"] = 41139, ["name"] = "The Key Is Around Here Somewhere...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["description"] = "Well aren't ye a sight fer sore eyes! It's no use tryin' to bust open this cage, this one needs a key! Now, I know what yer thinkin', \"How is it possible that the Burnin' Legion could capture a dwarf as mighty as ol' Angus here.\" Ye can rest easy knowin' I let myself be captured. I'm here to rescue a dear friend o' mine, an' gettin' captured was the only way! I had the key in me pocket... but it musta' fell out. It's errm... around here somewhere. A felhunter ate it a wee while back...", ["objectivesText"] = "Find the Reinforced Cage Key . Progress: Did ye find the key?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134051, 134055, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103204, ["x"] = 0.284, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103204, ["x"] = 0.284, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41140] = { ["id"] = 41140, ["name"] = "Search and Rescue!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["description"] = "We've got to find Brambley before it's too late! Ol' Brambley an' I have been fightin' side by side since the Third War. When the Burnin' Legion invaded, we didn't think twice about coming to the Broken Isles. Fightin' is what we do best! During the battle ol' Brambley got caught too deep an' got himself captured. Now we've got to rescue him! Last I saw, the demons were keeping him in a prison cell not far from here... let's go!", ["objectivesText"] = "Find Brambley Morrison. Progress: Have you found the key yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 39648, 39649, 39650, 134080, 141940 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103204, ["x"] = 0.284, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102365, ["x"] = 0.27, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41139 }, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41141] = { ["id"] = 41141, ["name"] = "A Conjuror's Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41124 }, ["description"] = "I don't know about you but I'm ready to get this show on the road. This place is nice and all, but it's a bit stuffy. I'll see what I can do to get some more mages in this group of yours. You go ahead and check the map over there. It'll help you plan your first moves.", ["objectivesText"] = "Use the Scouting Map to choose your first zone.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.816, ["y"] = 0.602, ["mapID"] = 734, ["npcID"] = 103092 } }, ["ends"] = { { ["x"] = 0.816, ["y"] = 0.602, ["mapID"] = 734, ["npcID"] = 103092 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.816, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 103092, ["questTurnInID"] = 103092, ["questType"] = "standard", ["sourceQuests"] = { 41124 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
