[41145] = { ["id"] = 41145, ["name"] = "Water of Life", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41145 }, ["objectivesText"] = "Drogbar Manathirster slain Drogbar Idol destroyed", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 63715, 63716, 63717, 63718, 63719, 63720 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Drogbar Manathirster slain", ["amount"] = 3, ["type"] = 0, ["objectID"] = 114295, ["orderIndex"] = 0 }, { ["text"] = "Drogbar Idol destroyed", ["amount"] = 6, ["type"] = 2, ["objectID"] = 247106, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[41146] = { ["id"] = 41146, ["name"] = "Elegant Design", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["description"] = "Amateur merchants complain about supply and demand. Masters create their own. You have done well retrieving the last two pieces I requested, but they are baubles compared to this. Your target is the Lady Anastae , and she has something very valuable of mine: A design for a masterwork gem cut. Go and get it from her by any means necessary, but take care. She is a master manipulator and will tell you all manner of lies.", ["objectivesText"] = "Convince Lady Anastae to give you the Gemcutter's Tome. Progress: What do you want?", ["rewardGold"] = 151650, ["rewardXP"] = 4605, ["rewardItems"] = { 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104394, ["x"] = 0.416, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41465, 41466 }, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41148] = { ["id"] = 41148, ["name"] = "Dispensing Compassion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "There is much you need to learn about our city. First and foremost, Arcwine. It is the vehicle by which we imbibe the Nightwell's energies. Without it, we wither and die. Palace lackeys have seen fit to ration it, thinking this will control us. Keep us quiet, complacent. I would like you to look for those in need near the tavern. You will find many, but those most desperately afflicted by this rationing will be obvious. Take this flask. Revive them. Tend to their suffering.", ["objectivesText"] = "Offer Arcwine to suffering citizens. Progress: Have you served those who suffer?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138308, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40746 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41149] = { ["id"] = 41149, ["name"] = "A Re-Warding Effort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["description"] = "<This small device of elegant nightborne design crackles gently with arcane power. Kel'danath's notes mention wards that keep the withered at bay. It seems he found some form of spellcasting that does not tempt their ravenous appetite for magic. These may prove useful in your search for the missing arcanist.>", ["objectivesText"] = "Activate 4 Arcane Wards in Ambervale.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136269, 140349, 141668, 142054 }, ["starts"] = { { ["x"] = 0.306, ["y"] = 0.4, ["mapID"] = 680, ["npcID"] = 109022 } }, ["ends"] = { { ["x"] = 0.306, ["y"] = 0.4, ["mapID"] = 680, ["npcID"] = 109022 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.306, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questGiverID"] = 109022, ["questTurnInID"] = 109022, ["questType"] = "standard", ["sourceQuests"] = { 40012 }, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41155] = { ["id"] = 41155, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh. Progress: Did you find what you seek, <class>?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questTurnInID"] = 100812, ["questType"] = "standard", ["sourceQuests"] = { 40611 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[41156] = { ["id"] = 41156, ["name"] = "The Power Possessed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 627, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Our goals have been met, warlock, and it is time we part ways. I think I will be glad to see the last of you. Go on, return to your dark masters. We are done here.", ["objectivesText"] = "Return to Calydus in The Underbelly in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.685, ["y"] = 0.287, ["mapID"] = 46, ["npcID"] = 101282 } }, ["ends"] = { { ["x"] = 0.685, ["y"] = 0.287, ["mapID"] = 46, ["npcID"] = 101282 } }, ["coords"] = { ["mapID"] = 46, ["x"] = 0.685, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questGiverID"] = 101282, ["questTurnInID"] = 101282, ["questType"] = "standard", ["sourceQuests"] = { 41155 }, ["nextQuests"] = { 40731 }, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41157] = { ["id"] = 41157, ["name"] = "Corrupted Studies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 40857, 41157 }, ["series"] = { 40857, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "Stormheim is steeped with artifacts from tha War of the Ancients. Demon artifacts ta be exact. I think these artifacts can clue us into some knowledge about their leader, Sargeras. I've already found some fragments to a titan disc, but need ta find the rest of 'em. I need ya ta dig around Stormheim and see if ye can find any more fragments so we can reassemble the disc.", ["objectivesText"] = "Survey digsites in Stormheim and bring Brann back 200 War of the Ancients Fragments . Progress: With so many demon artifacts buried here, it's a wonder this place is as vibrant as it is.", ["rewardItems"] = { 134082, 136360, 136362 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40857 }, ["questLines"] = { { ["id"] = 321, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41158] = { ["id"] = 41158, ["name"] = "Fragments of the Fjords", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41158, 41159, 41802 }, ["series"] = { 40857, 41157, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "<name>, have you seen my ledger around here? I seemed to have misplaced it when I was stowing some canopic jars. Oh, nevermind. Brann Bronzebeard has sent for you though. He's in Stormheim continuing his research. Make your way out to him and let him know I'm still waiting on those flayed-skin chronicles he found.", ["objectivesText"] = "Meet with Brann Bronzebeard in Stormheim.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 325, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41159] = { ["id"] = 41159, ["name"] = "Process of Elimination", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41158, 41159, 41802 }, ["series"] = { 40857, 41157, 41158, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "With so many places ta dig up fragments, it's become quite a pain figuring out where ta look for more of the titan disc. I have a plan though. I need ye ta eliminate potential areas where the disc could exist so we can narrow down where in Stormheim it might exist. You take part of the area an' I'll take the other part. Meet back here if ye find anythin'.", ["objectivesText"] = "Dig around Stormheim until you find a piece of the Titan Disc.", ["rewardGold"] = 208560, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41158 }, ["questLines"] = { { ["id"] = 325, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41160] = { ["id"] = 41160, ["name"] = "Earth to Earth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 41160 }, ["description"] = "From the earth comes strength, and such strength can be imbued into weapons of power. You have the look of one who seeks to know how to create such weapons. There are creatures that still inhabit this dying planet who bear such strength. Bring me their cores and I shall trade you the knowledge you seek.", ["objectivesText"] = "Recover a Cardinal Stone Core , a Cardinal Earth Core , and a Cardinal Lava Core for Lunelli . Bring them back to her in Shattrath when you have all three. Progress: There are also those who use such cores for more than mere forging. Be weary of such beings.", ["rewardGold"] = 154900, ["rewardXP"] = 345, ["rewardItems"] = { 16659, 16660, 16661, 25574, 25575, 25576, 25929, 25930, 25931, 25932, 39772, 39783, 39786, 39835, 42847, 42871, 42882, 42893, 52352, 52620, 52634, 57207, 57223, 57233, 57281, 57282, 57283, 61466, 61467, 61468, 61490, 61491, 61492, 61502, 61503, 61504, 62048, 65654, 65655, 65656, 118151, 118152, 118153, 119066, 119074, 131216, 139506, 139705, 142267, 142268, 142269, 142270, 142271, 142272, 142284, 142286, 142287, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 191837, 219360, 219370, 219372, 219377, 219783, 219784, 219785, 219786, 219787, 219788, 219789, 219790, 219792, 223951, 232371 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 115546, ["x"] = 0.64, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 115546, ["x"] = 0.64, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[41161] = { ["id"] = 41161, ["name"] = "Out of the Frying Pan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41161, 41162, 41163 }, ["series"] = { 40857, 41157, 41158, 41159, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "Oh hello, <name>. I tell you, ever since I was given this shop, it's been nothing but a headache. I can't seem to ever find what I'm looking for. Which reminds me, Brann Bronzebeard has sent for you. He's in Azsuna tracking down more pieces of whatever it is he's searching for. Now where'd those pewter drinking cups go...", ["objectivesText"] = "Meet with Brann in Azsuna.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 327, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41162] = { ["id"] = 41162, ["name"] = "And Into the Fel Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41161, 41162, 41163 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "I found something, <name>. Well, a couple of things actually. First I found an ancient text talking about a demon who harnessed the power of the titan disc I've been searching for. Then I found a device which supposedly is used to summon 'im! Only, it's missin' some pieces from what I can make out. I'm sure if we survey around Azsuna some more, those missin' pieces are sure ta turn up.", ["objectivesText"] = "Survey digsites in Azsuna and find 10 missing Parts of the Infernal Device and bring them back to Brann. Progress: From what I can make out, I think there's only seven or eight parts we need...", ["rewardItems"] = { 134084, 146328 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41161 }, ["questLines"] = { { ["id"] = 327, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41163] = { ["id"] = 41163, ["name"] = "The Apocalypse Bringer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41161, 41162, 41163 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "Right, well, I managed to piece the device back together. I guess I'll jes' turn it on when you're ready and we'll see what happens, yea?", ["objectivesText"] = "Talk to Brann when you're ready to activate the device. Progress: Be ready for anything, lad.", ["rewardItems"] = { 136922 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41162 }, ["questLines"] = { { ["id"] = 327, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41164] = { ["id"] = 41164, ["name"] = "One Step Closer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41164, 41165, 41166 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "<name>! I just heard that Brann Bronzebeard - that crazy, titan-obsessed dwarf - has decided to go hunting for his precious disc in Suramar. Talk about the last place you'd want to go digging around, given the current events. I'm sure he could use your help.", ["objectivesText"] = "Meet with Brann in Suramar.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 124125, 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 330, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41165] = { ["id"] = 41165, ["name"] = "Deciphering Demonology", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41164, 41165, 41166 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "I found a piece of what appears to be a key to something. I'm certain I can restore it if we can find the other bits. After that, we need to figure out what it's a key to. An' I think I know how to do that. I've been studying some of the artifacts I've found, and they seem to be pointing to a hidden chamber. I jes' need some more artifacts to study.", ["objectivesText"] = "Crate artifacts into 5 Restored Artifacts and find 5 Chamber Key Fragments and bring them to Brann. Progress: How goes the search?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 87399, 109076, 131743, 134085 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41164 }, ["questLines"] = { { ["id"] = 330, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41166] = { ["id"] = 41166, ["name"] = "Dark Secrets", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41164, 41165, 41166 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "I fixed the key and am ready to open the chamber. Meet me there when you have a chance and we'll discover what waits inside together!", ["objectivesText"] = "Meet Brann at the entrance to the secret chamber. Once inside, stay close to Brann in case anything happens. Progress: I always love a good adventure!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 131743, 136397, 136398 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41165 }, ["questLines"] = { { ["id"] = 330, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41167] = { ["id"] = 41167, ["name"] = "Fel Fragments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41167, 41168, 41169 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41168, 41169, 41170, 41802 }, ["description"] = "Brann Bronzebeard has requested that I send him more surveying equipment , but I just don't have the time. Would you be a dear and take this crate to him, <name>? I'd truly appreciate it.", ["objectivesText"] = "Deliver the crate of surveying equipment to Brann in Val'sharah. Provided item:", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 134086, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 332, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41168] = { ["id"] = 41168, ["name"] = "The Purple Hills of Eredath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41167, 41168, 41169 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41169, 41170, 41802 }, ["description"] = "Now that we're re-supplied, we can get back ta work. I found something here that I think ye'll be interested in. It's a page of a book talking about the world of Argus. But before the demons destroyed it. Anyway, it's been me experience that if ye find one of something, there's sure ta be more of it around. Keep lookin' around Val'sharah for more of these pages and bring what ye find back ta me. And take the page I found with ya so ye know what yer lookin' fer.", ["objectivesText"] = "Find the remaining pages of The Purple Hills of Eredath and assemble them into the final book. Return the book to Brann when you have finished. Progress: I can't wait to read the rest of that story.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134087, 134088, 134089, 146328 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41167 }, ["questLines"] = { { ["id"] = 332, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41169] = { ["id"] = 41169, ["name"] = "Darkheart Thicket: Through the Fog", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41167, 41168, 41169 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41170, 41802 }, ["description"] = "I can't believe that after all that searchin' ye did, it's still missing a chapter! I'm willin' ta bet that those satyrs got a hand on it and took it somewhere. Probably somewhere dark where no one could find it. I've heard rumors of a place, the Darkheart Thicket they call it, where the strongest of the satyrs are. If I had ta guess, I'd say ye need to go there and look around fer it.", ["objectivesText"] = "Obtain the Final Chapter of The Purple Hills of Eredath . Progress: A world of nightmares is nowhere where anyone should have ta go to.", ["rewardItems"] = { 131732, 134090, 134091 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 41168 }, ["questLines"] = { { ["id"] = 332, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41170] = { ["id"] = 41170, ["name"] = "The Relic Renewed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41170 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41802 }, ["description"] = "Very good, very good! Now that we have all the pieces, it's time to put this disc back together!", ["objectivesText"] = "Observe Brann as he puts the Titan Disc back together. Progress: Jes a moment, lad...", ["rewardItems"] = { 87399, 87539, 130903, 130904, 130905 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41867, 41868, 41869, 41870, 41871 }, ["questLines"] = { { ["id"] = 182, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41171] = { ["id"] = 41171, ["name"] = "The Reliquary Calls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41171, 41172, 41173 }, ["description"] = "Tae'thelan of the Reliquary has asked me to send anyone who may be able to help them in Azsuna. Seeing as how you happened into my shop purely by coincidence, I thought you'd be willing to go, <name>. Back to work for me though. So much to do and so little help. <Dariness lets out a sigh.>", ["objectivesText"] = "Meet with Tae'thelan Bloodwatcher in Azsuna.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 130903, 130906, 130907, 130908, 130909, 130910, 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922, 164626 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.404, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questTurnInID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 322, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41172] = { ["id"] = 41172, ["name"] = "Echoes of My Ancestors", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41171, 41172, 41173 }, ["description"] = "This land holds many secrets and many artifacts of ancient times. From what I've been able to discern there's an artifact of great power close to here. I just need to narrow down its location. I'd like you to dig up more artifacts and learn what you can. When you feel you've done enough research, come back to me and share your knowledge.", ["objectivesText"] = "Complete 25 Highborne Archaeology Projects.", ["rewardGold"] = 257400, ["rewardXP"] = 6140, ["rewardItems"] = { 87399, 130903, 130906, 130907, 130908, 130909, 130910, 130923, 131717, 164626 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41171 }, ["questLines"] = { { ["id"] = 322, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41173] = { ["id"] = 41173, ["name"] = "A Beacon of Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41171, 41172, 41173 }, ["description"] = "I've marked the location of the artifact on your map. It's in a rather hostile location, so I'd like you to go there and find it. When you've recovered it, bring it back to me so I can discern its power.", ["objectivesText"] = "Go to the location Tae'thelan marked on your map and survey the area until you find the artifact. Progress: Perhaps we can use this artifact to turn the tide of this war in our favor.", ["rewardItems"] = { 131717, 134108 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41172 }, ["questLines"] = { { ["id"] = 322, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41174] = { ["id"] = 41174, ["name"] = "Worth Its Weight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41174, 41175, 41176 }, ["description"] = "<name>, if you were a crate of black trilobites, where do you think I would have put you? <Dariness begins looking around the shop.> Oh, that reminds me. Tae'thelan has requested your presence. He's onto something in Suramar and needs your help.", ["objectivesText"] = "Meet with Tae'thelan in Suramar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922, 142346 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 324, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41175] = { ["id"] = 41175, ["name"] = "Fit for an Elven Queen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41174, 41175, 41176 }, ["description"] = "The nightborne have dropped their shield allowing us to penetrate their city and learn their secrets. One such secret I've discovered is a crown of immeasurable power. I'd like you to find this crown and report back to me on what it does.", ["objectivesText"] = "Fight your way through Suramar into the chamber that holds the crown. Inspect the crown and report your findings back to Tae'thelan.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 109076, 131811 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41174 }, ["questLines"] = { { ["id"] = 324, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41176] = { ["id"] = 41176, ["name"] = "Sifting Through the Rubble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41174, 41175, 41176 }, ["description"] = "Then I believe it's clear what we must do next. Find the jewels. They're bound to be here somewhere in Suramar, so we better start looking. I'll coordinate the search from here, while you and my assistants look for the jewels.", ["objectivesText"] = "Survey different areas around Suramar until you find the 6 missing Jewels of the Crown. Progress: What's the status on the search for the jewels?", ["rewardItems"] = { 60847, 87399, 109076, 128561, 131740, 134114 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41175 }, ["questLines"] = { { ["id"] = 324, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41177] = { ["id"] = 41177, ["name"] = "Goblin Archaeology", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41177, 41178, 41179 }, ["description"] = "I'm not sure if you're in on this, but the Reliquary has commissioned the goblins to help them with uncovering artifacts in this land. I'd like you to go and see if there's any validity to this rumor... and I'd also be interested to know the results.", ["objectivesText"] = "Meet with Tae'thelan in Val'sharah.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136381, 136382, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 326, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41178] = { ["id"] = 41178, ["name"] = "Explosive Results", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 630, ["storyline"] = { 41177, 41178, 41179 }, ["description"] = "As you may or may not have heard, I've been working with the goblins on using a new way of uncovering our artifacts. And if you know anything about goblins, you know that I'm talking about explosives. We've only run a few tests here at my camp, but I would appreciate your help in testing this method out in the field. I've marked a location on your map that has some particularly difficult digs.", ["objectivesText"] = "Use the goblin explosives to free 500 Artifact Fragments from their geological prisons. Progress: The working theory is that due to the amount of gunpowder that's being used, it should only produce a small shock to whatever the artifact has been encased in.", ["rewardGold"] = 286500, ["rewardXP"] = 6140, ["rewardItems"] = { 134115, 135488 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41177 }, ["questLines"] = { { ["id"] = 326, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41179] = { ["id"] = 41179, ["name"] = "What Once Was Lost", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 630, ["storyline"] = { 41177, 41178, 41179 }, ["description"] = "That reminds me, I found a map to a chamber that may or may not hold something of value. It doesn't seem to have any power associated with it, which is why I'm handing it over to you. Here, take some more explosives. They may help speed up the process of finding it.", ["objectivesText"] = "Go to the location marked on the map and recover the artifact in question. Use the dynamite to uncover the artifact.", ["rewardItems"] = { 131745, 135488, 136381, 136382, 136383 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 103482, ["questType"] = "standard", ["sourceQuests"] = { 41178 }, ["questLines"] = { { ["id"] = 326, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41180] = { ["id"] = 41180, ["name"] = "Unspeakable Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41180, 41181, 41182 }, ["description"] = "<name>, I received an urgent message from the High Examiner requesting your presence. He's finally found something powerful-- VERY powerful--and he wants your help in recovering it. Be careful down there, <name>. Tae'thelan can be a tad fanatical when it comes to artifacts that hold any sort of energy.", ["objectivesText"] = "Meet with Tae'thelan Bloodwatcher in Suramar.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 131811, 134076, 134077, 134078, 134079, 134081, 134116, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 328, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41181] = { ["id"] = 41181, ["name"] = "Narrowing Down", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41180, 41181, 41182 }, ["description"] = "I was right about the nightborne here having objects of great power. I found an ancient text referring to such an object called the Orb of Sciallax. From what I recall in studying the War of the Ancients, Sciallax was a demon lord who came to Suramar and offered the elves at the time a powerful artifact in return for their servitude to the Legion. I haven't discovered the exact location yet as to the whereabouts, but perhaps some digging can yield us an answer.", ["objectivesText"] = "Survey Suramar and uncover 10 Tattered Highborne Scrolls . Progress: We must discover this artifact at all costs!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134116 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41180 }, ["questLines"] = { { ["id"] = 328, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41182] = { ["id"] = 41182, ["name"] = "Uncovering the Orb of Sciallax", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41180, 41181, 41182 }, ["description"] = "We'll need to hurry before the nightborne realize what we're after. I'm bringing the goblins along in case we run into any obstacles along the way. I've marked the location of the entrance to the chamber the Orb resides in on your map. Meet me there as soon as you're ready and we'll claim this artifact for our own.", ["objectivesText"] = "Meet Tae'thelan Bloodwatcher at the entrance to the chamber where the Orb of Sciallax is held. Once inside, set the charges on the casing and recover the artifact. Progress: Well?", ["rewardItems"] = { 131731, 134076, 134077, 134078, 134079, 134081 }, ["rewardChoices"] = { 131731, 134076, 134077, 134078, 134079, 134081 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41181 }, ["questLines"] = { { ["id"] = 328, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41183] = { ["id"] = 41183, ["name"] = "Academic Exploration", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 41183, 41184, 41185 }, ["description"] = "<name>, good to see you. What do you think of my shop so far? Not too bad for just one person, huh? By the way, High Examiner Tae'thalan has been digging around Azsuna, and asked that I send you to see him. Knowing him, he probably thinks he's found yet another world-shatteringly powerful artifact.", ["objectivesText"] = "Meet with Tae'thelan in Azsuna.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 331, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41184] = { ["id"] = 41184, ["name"] = "Tried and True", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41183, 41184, 41185 }, ["description"] = "I have realized through experience that the old methods are usually the best and for good reason. I'm done with alternate means of digging for now, and wish to focus on the right way to do things. That being said, I believe I've found a new powerful artifact and I'll do literally anything to have it. I've uncovered a fragment that appears to be a mold for a key. I now simply need the other pieces.", ["objectivesText"] = "Find the remaining 15 Azsunian Key Mold Pieces and return them to Tae'thelan. Progress: Have you recovered any of the other pieces yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131744, 134117 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41183 }, ["questLines"] = { { ["id"] = 331, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41185] = { ["id"] = 41185, ["name"] = "The Keys to Success", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41183, 41184, 41185 }, ["description"] = "I'd like you to take the mold to the blacksmith in Dalaran. Alard, I believe his name is. Have him help you forge a new set of keys. I found some writing on the back of the mold that may hold the answer to what these keys unlock. I'll stay here and try to translate the text.", ["objectivesText"] = "Bring the mold to Alard Schmied in Dalaran and have him help you forge a new set of keys. Return to Tae'thelan when you have the finished set. Progress: The key is clearly tied to something here in Azsuna.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 131744, 134832, 134833, 134834, 134835 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41184 }, ["questLines"] = { { ["id"] = 331, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41186] = { ["id"] = 41186, ["name"] = "History of Highmountain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 41186, 41187, 41188 }, ["description"] = "Let's see, one... two... three... oh, hello <name>. Sorry I didn't see you come in. Things have been hectic around here. I could really use an assistant. I do have something for you though, a fellow archaeologist named Lessah has been asking for someone to help her in Highmountain. I thought you'd be the perfect person for the job.", ["objectivesText"] = "Meet with Lessah in Highmountain.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136372, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.404, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questTurnInID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 323, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41187] = { ["id"] = 41187, ["name"] = "Surveying Student", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41186, 41187, 41188 }, ["description"] = "The reason I sent for someone was that I've been having trouble keeping up with my research and training my assistant. I was hoping you might be able to show him the ropes again. Get him reacquainted with surveying. Just speak with him when you're ready to go.", ["objectivesText"] = "Complete 20 successful surveys with Luron present.", ["rewardItems"] = { 136372, 146327 }, ["starts"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["ends"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["coords"] = { ["mapID"] = 650, ["x"] = 0.458, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 103485, ["questTurnInID"] = 103485, ["questType"] = "standard", ["sourceQuests"] = { 41186 }, ["questLines"] = { { ["id"] = 323, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41188] = { ["id"] = 41188, ["name"] = "Neltharion's Lair: Misdirected", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41186, 41187, 41188 }, ["description"] = "I've been looking into the history of Huln Highmountain, a legendary warrior from the War of the Ancients whom this very land is named after. Allegedly some of his personal effects were carried here after his death and have been lost in time. After some digging around I believe I have discovered the location of one of his artifacts to be in a place called Neltharion's Lair. I'm no fighter, <name>, but you are. Will you go and recover this artifact for me?", ["objectivesText"] = "Go to Neltharion's Lair and recover the Ancient Highmountain Artifact . Progress: If I've followed the clues correctly, then this could lead to one of Huln's weapons.", ["rewardItems"] = { 131733, 134093 }, ["starts"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["ends"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["coords"] = { ["mapID"] = 650, ["x"] = 0.458, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 103485, ["questTurnInID"] = 103485, ["questType"] = "dungeon", ["sourceQuests"] = { 41187 }, ["questLines"] = { { ["id"] = 323, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41189] = { ["id"] = 41189, ["name"] = "A New Lead", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 41189, 41190, 41191 }, ["description"] = "<name>, Lessah in Highmountain has been asking for you. Apparently she's caught a lead on some ancient piece of armor that Huln Highmountain used to wear. When you can, make your way out to her.", ["objectivesText"] = "Meet with Lessah in Highmountain.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 136922, 164627 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.404, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questTurnInID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 329, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41190] = { ["id"] = 41190, ["name"] = "Crystal Eyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41189, 41190, 41191 }, ["description"] = "I've delved into the caves here and have discovered many ancient writings. The most interesting I've found are resonating crystals, where the drogbar have resided. Unfortunately, they aren't on very good terms with the tauren here and this has hindered my research. I thought, should there be any trouble with the drogbar, that you'd be able to handle them. I'd like you to continue my research and discover what you can about Huln.", ["objectivesText"] = "Interact with the two different resonating stones in Highmountain. Each stone requires 3 Highmountain Ritual-Stones to activate.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130904, 146329 }, ["starts"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["ends"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["coords"] = { ["mapID"] = 650, ["x"] = 0.458, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 103485, ["questTurnInID"] = 103485, ["questType"] = "standard", ["sourceQuests"] = { 41189 }, ["questLines"] = { { ["id"] = 329, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41191] = { ["id"] = 41191, ["name"] = "Drogbar Deception", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41189, 41190, 41191 }, ["description"] = "According to my research and the information you gave me, I've isolated the location of the necklace. It's deep in a drogbar cave, and I'm willing to bet they're not just going to hand it over to you, <name>. I need you to recover that necklace at any cost.", ["objectivesText"] = "Recover the ancient necklace and bring it back to Lessah. Progress: If only the drogbar were more reasonable.", ["rewardItems"] = { 131736, 134094 }, ["starts"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["ends"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 650, ["npcID"] = 103485 } }, ["coords"] = { ["mapID"] = 650, ["x"] = 0.458, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 103485, ["questTurnInID"] = 103485, ["questType"] = "standard", ["sourceQuests"] = { 41190 }, ["questLines"] = { { ["id"] = 329, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41192] = { ["id"] = 41192, ["name"] = "The Right Path", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 41192, 41193 }, ["description"] = "This new shop is shaping up quite nicely, I think. Still, there's so much left to organize. <name>, Lessah has requested your presence in Highmountain. Something about a moose? I'm not sure to what she's speaking of, but as soon as you have a chance, please go see her.", ["objectivesText"] = "Meet with Lessah in Highmountain.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 38667, 131717, 131724, 131731, 131732, 131733, 131734, 131735, 131736, 131740, 131743, 131744, 131745, 134076, 134077, 134078, 134079, 134081, 134095, 136922 }, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["x"] = 0.404, ["y"] = 0.24, ["mapID"] = 627, ["npcID"] = 93538 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.404, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questTurnInID"] = 93538, ["questType"] = "standard", ["questLines"] = { { ["id"] = 333, ["name"] = "Legion Archaeology", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41193] = { ["id"] = 41193, ["name"] = "Laying to Rest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41192, 41193 }, ["description"] = "If I was able to find a bone fragment in what appeared to be a random location, then that means Eche'ro's bones must be scattered around Highmountain. We must find his remains and give him the proper burial he deserved. Oh, I'm sorry, in case you weren't aware, Eche'ro was Huln Highmountain's mount and companion. He deserves to be honored as Huln once was.", ["objectivesText"] = "Find 600 Bone Fragments of Eche'ro and return them to Lessah in Highmountain. Then observe the burial ceremony Lessah performs. Progress: We must see to it that his remains are given the respect they deserve.", ["rewardGold"] = 929400, ["rewardXP"] = 2615, ["rewardItems"] = { 87399, 124671, 128561, 130904, 131734, 131811, 131900, 134095, 139773, 146326 }, ["starts"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 750, ["npcID"] = 103485 } }, ["ends"] = { { ["x"] = 0.458, ["y"] = 0.446, ["mapID"] = 750, ["npcID"] = 103485 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.458, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 103485, ["questTurnInID"] = 103485, ["questType"] = "standard", ["sourceQuests"] = { 41192 }, ["questLines"] = { { ["id"] = 333, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
