[41197] = { ["id"] = 41197, ["name"] = "You've Got to Be Kitten Me Right Meow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "While you were dealing with the stray Owlkitten, I took a look around. It seems these curious creatures have a habit of escaping their parents' watchful eyes - some are trapped across the road by a wandering Ettin. He appears to have been... ahem... eating them. We can earn Yowlon's blessing by bringing his children home.", ["objectivesText"] = "\"Herd\" 7 Lost Feathermane Kittens back home. Progress: Have you managed to rescue any?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137179, 139791, 140240, 140251, 141941, 142054 }, ["rewardChoices"] = { 139791 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41453 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
