[41220] = { ["id"] = 41220, ["name"] = "Down to Azsuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 39718 }, ["description"] = "<name>, we must find a way to reseal the Tomb of Sargeras. I have uncovered information concerning an ancient relic, which might be the key to stopping the Legion. Our search begins on the ancient elven island of Azsuna . Long ago, it was where the Highborne elves of Suramar perfected their mightiest of magics. Now it is a cursed ruin. The Illidari demon hunters have established a camp on the island. As they are the only people we know in the area, that is where we will begin. Ready to take wing?", ["objectivesText"] = "Speak with Archmage Khadgar to fly down to Azsuna . Progress: It would seem that we have arrived at the crucial moment.", ["rewardXP"] = 1415, ["rewardItems"] = { 22589, 109076 }, ["starts"] = { { ["x"] = 0.72, ["y"] = 0.454, ["mapID"] = 627, ["npcID"] = 86563 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93326, ["x"] = 0.435, ["y"] = 0.434 }, { ["mapID"] = 630, ["npcID"] = 93337, ["x"] = 0.45, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 86563, ["questType"] = "standard", ["sourceQuests"] = { 39718 }, ["nextQuests"] = { 38834, 44137 }, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[41221] = { ["id"] = 41221, ["name"] = "Return to Mardum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The gateway is fully functional, <name>. Ooh, I am positively tingling with excitement! Do let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time. You will be joining us aboard, won't you?", ["objectivesText"] = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.949, ["y"] = 0.665, ["mapID"] = 627, ["npcID"] = 109295 } }, ["ends"] = { { ["x"] = 0.949, ["y"] = 0.665, ["mapID"] = 627, ["npcID"] = 109295 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.949, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 109295, ["questTurnInID"] = 109295, ["questType"] = "standard", ["sourceQuests"] = { 42872 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[41222] = { ["id"] = 41222, ["name"] = "Into The Pit!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["series"] = { 41214, 41309 }, ["description"] = "The felstalker pits?! There's no time to waste, <name>! I canna' tell ye what the Burnin' Legion has planned for ol' Brambley, but it canna' be good! Hurry! We've got to find him before the Burnin' Legion has their way with him!", ["objectivesText"] = "Escort Angus to Felmaw Cavern in Felsoul Hold. Progress: We've got to get to the felstalker pits an' save Brambley!", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 142054 }, ["starts"] = { { ["x"] = 0.271, ["y"] = 0.86, ["mapID"] = 680, ["npcID"] = 103437 } }, ["ends"] = { { ["x"] = 0.271, ["y"] = 0.86, ["mapID"] = 680, ["npcID"] = 103437 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.271, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 103437, ["questTurnInID"] = 103437, ["questType"] = "standard", ["sourceQuests"] = { 41140 }, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
