[41226] = { ["id"] = 41226, ["name"] = "Breaking Out", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 41226 }, ["description"] = "We cannot fight our way out of the Vault alone. Two of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. Free them with haste. Their strength will be of great use to us.", ["objectivesText"] = "Free both Altruis the Sufferer and Kayn Sunfury.", ["rewardGold"] = 154000, ["rewardXP"] = 200, ["rewardItems"] = { 31312, 31313, 31314, 31315, 37959, 38001, 38044, 38105, 38230, 38231, 38232, 65683, 65703, 65721, 112591, 112592, 112593, 112594, 131699, 142054, 175733, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 177657, 251221, 251222, 251228, 251234, 251235, 252258 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
