[41230] = { ["id"] = 41230, ["name"] = "Trapping Evolved", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 40617 }, ["description"] = "The Nightborne are using magic for everything, even trapping. Nighteyes saw them at work, laying down magical snares to capture prey rather than the kind our people use. Bring me their traps so that I may study their make.", ["objectivesText"] = "Collect 4 Arcane Traps for Lilryia. Progress: Do you have the snares, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134128, 139791, 140240, 140251, 141670, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40617 }, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41231] = { ["id"] = 41231, ["name"] = "Apex Predator", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 43582 }, ["description"] = "I have good news and bad news, <race>. The bad news is that they somehow managed to capture and train a Devilsaur. The good news is that it doesn't seem to have a collar and is tame. I imagine it must think that one of the Nightborne in there is its master. Find the pack leader and take him out, and we will set quite a beast upon them.", ["objectivesText"] = "Find and slay the Nightborne keeping Su'esh obedient. Progress: Did you find the alpha?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41216 }, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
