[41255] = { ["id"] = 41255, ["name"] = "Sowing The Seed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "Your weapon is ancient and powerful but it holds the potential to be so much more. Take this seed, it is all that remains of a forest that grew tall when the world was young. Plant it within the grove to the west and allow it to take root. With its power both it and your weapon will be far more than they are alone.", ["objectivesText"] = "Plant the Seed of Ages in the Soft Soil within The Dreamgrove.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 134550 }, ["starts"] = { { ["x"] = 0.445, ["y"] = 0.511, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.445, ["y"] = 0.511, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.445, ["y"] = 0.511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 40900, 41689, 41918, 42430 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[41256] = { ["id"] = 41256, ["name"] = "Blast of Spice Fish", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41107, 41256, 41258 }, ["description"] = "I have an ingredient that will make my fruit irresistible. Not many remember the delicacy of manatrout liquor. Its pungent aroma, the unctuous mouthfeel... The toads near the northern river concentrate this additive in their gizzards. Fetch some stomachs for me, and we will have plenty.", ["objectivesText"] = "Collect Toad Gizzards for Keelay. Progress: Daglir is young and foolish!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134549 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5823, ["name"] = "Fruit of the Doom", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
