[41309] = { ["id"] = 41309, ["name"] = "Mangelrath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["series"] = { 41214, 41222 }, ["description"] = "The demonic beast that stands before ye, must be the one that devoured ol' Brambley... Just look at it, lying there with a full belly! I canna abide it any longer, <name>! We must slay the foul creature and avenge Brambley! We've come this far already, <class>. Are ye with me?!", ["objectivesText"] = "Defeat Mangelrath .", ["rewardGold"] = 259748, ["rewardXP"] = 6140, ["rewardItems"] = { 140250 }, ["starts"] = { { ["x"] = 0.358, ["y"] = 0.708, ["mapID"] = 680, ["npcID"] = 103437 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104161, ["x"] = 0.358, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questGiverID"] = 103437, ["questType"] = "standard", ["sourceQuests"] = { 41214 }, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
