[41320] = { ["id"] = 41320, ["name"] = "Pry It From Their Cold, Feral Claws", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["series"] = { 41465 }, ["description"] = "The shield being lowered presents a unique opportunity for new styles. Feathers, bone and other primitive materials are suddenly fashionable again. Who would have thought they could grow tired of my masterpieces? Venture out of the city and collect necklaces from the harpies on the southern cliffs. Etching my mark into them should net me a tidy profit.", ["objectivesText"] = "Retrieve 8 Harpy Necklaces for Lespin. Progress: Do you have my necklaces? They are of no use to me on the necks of those... creatures.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134821 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41123 }, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
