[41367] = { ["id"] = 41367, ["name"] = "Priority Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7695, ["mapID"] = 648, ["description"] = "An adventurer of another time has forgotten to loot something big... something that might cause them great emotional strain if not received quickly. Your destination is Icecrown Citadel, your target the Lich King's corpse. Retrieve the missing item post-haste and deliver it to the stalwart adventurer - he should be somewhere at the Steam Pools in Feralas. My assistant will open a portal to deliver you there. Just a moment!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 103976 } }, ["ends"] = { { ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73, ["mapID"] = 69 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 7695 } }, ["questGiverID"] = 103976, ["questType"] = "standard", ["sourceQuests"] = { 41397 } },
