[41394] = { ["id"] = 41394, ["name"] = "Service with a Smile", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 41394 }, ["description"] = "Oh, simple <race>. Simple, simple <race>. I did not 'forget' to sweep up those reins from that foolish cakewalk of a knight they call the Lich King. I simply did not bother, as I already received the mighty steed during my raid last week. <Johnny motions to the horse on his left.> Since you're here and clearly intrigued by my sweltering greatness, won't you take that superfluous stallion to the assistant resort director in town? My coffers could use a bit of extra lining.", ["objectivesText"] = "Sell Invincible's Reins to Gott Weedlespan for Johnny Awesome . Progress: Do not tarry, <class>. The longer you take, the longer until you may dote on me as one of my many admirers.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 3466, 4338, 7912, 45693, 134859, 135463, 135464, 156721, 156833 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "standard", ["sourceQuests"] = { 41367 } },
[41395] = { ["id"] = 41395, ["name"] = "Due Reward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 41395 }, ["description"] = "You have served me well these past few minutes we've spent together - minutes I shall not soon forget. I believe a reward befitting your unwavering loyalty is in order. You will have the distinct honor of placing Twinkles' favorite toy by his grave in honor of his memory. Please, please - save your thanks for Twinkles; it is not every day that we may honor a horse made of STARS.", ["objectivesText"] = "Place Twinkles' favorite toy by his grave at the Sludge Fields in Hillsbrad Foothills.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 7912, 45693, 122340, 134859, 135463, 156721, 156833 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questTurnInID"] = 52562, ["questType"] = "standard", ["sourceQuests"] = { 41394 } },
[41397] = { ["id"] = 41397, ["name"] = "A Huge Package", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 41397 }, ["description"] = "Due to the incredible volume of complaints in recent months we have been barred from delivering s... s... < The Postmaster holds back tears, pain visible in his eyes.> Solid stone. We're positively swimming in it - if we can't deliver it then pretty soon we will be overwh- < The Postmaster 's eyes light up suddenly.> That's it! There is an old Consortium portal not far from here that we could deposit it in with none the wiser! Can you help, <name>? The stone is extraordinarily heavy.", ["objectivesText"] = "Deliver 1,362 pieces of solid stone to the Ethereal Portal in Dalaran .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 7912, 45693, 109076, 134859, 135463, 139773, 140336, 147869, 156721, 156833 }, ["starts"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 103976 } }, ["ends"] = { { ["x"] = 0.386, ["y"] = 0.408, ["mapID"] = 627, ["npcID"] = 103976 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.386, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 103976, ["questTurnInID"] = 103976, ["questType"] = "standard", ["sourceQuests"] = { 46278 } },
