[41409] = { ["id"] = 41409, ["name"] = "Timing Is Everything", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41409, 41410 }, ["description"] = "Can you feel it, <name>? The waters churn with approaching Sashj'tar. You must strike now... Leave me... Find a way to bombard the naga... with the kegs... Protect... Jandvik...", ["objectivesText"] = "Ride an Azuregale Paddlefoot and kill 50 Sashj'tar naga using the Sealed Powder Kegs in Azuregale Bay.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 69777, 140244, 140245, 140254, 141674, 141675, 141946, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104586, ["x"] = 0.775, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41410 }, ["questLines"] = { { ["id"] = 5821, ["name"] = "Protecting Jandvik", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41410] = { ["id"] = 41410, ["name"] = "Dry Powder", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41409, 41410 }, ["description"] = "<name>... I did not expect to see you down here. The Sashj'tar are... rallying against Jandvik. I had a plan to... decimate them using these old powder kegs. The naga proved more formidable to these old bones than I thought. < Fjolrik coughs out some blood.> We haven't much time... to prepare.", ["objectivesText"] = "Collect 5 Sealed Powder Kegs from the shipwrecks in Azuregale Bay. Progress: Move quickly, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135478, 140244, 140245, 140254, 141674, 141675, 141946, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104586, ["x"] = 0.775, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104586, ["x"] = 0.775, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40927 }, ["questLines"] = { { ["id"] = 5821, ["name"] = "Protecting Jandvik", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
