[41415] = { ["id"] = 41415, ["name"] = "The Hunter's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 41415 }, ["description"] = "I realize we have never met, but you will learn of my order soon enough. For now, pleasantries must wait. The Legion has returned to Azeroth stronger than ever, and we need new weapons to fight them. I have met three individuals here in Dalaran who have leads on ancient artifacts which could prove vital in the battle to come. Acquiring these weapons demands the skills of a master hunter. Speak to each of them and decide whom you will aid first.", ["objectivesText"] = "Investigate leads on three artifact weapons. Progress: Have you chosen a lead to pursue first?", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["x"] = 0.598, ["y"] = 0.53, ["mapID"] = 627, ["npcID"] = 102478 } }, ["ends"] = { { ["x"] = 0.598, ["y"] = 0.53, ["mapID"] = 627, ["npcID"] = 102478 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.598, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102478, ["questTurnInID"] = 102478, ["questType"] = "standard", ["sourceQuests"] = { 40384 }, ["questLines"] = { { ["id"] = 271, ["name"] = "Path of the Hunter", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
