[41422] = { ["id"] = 41422, ["name"] = "Necessary Preparations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "G'Hanir is... is... < Mylune wipes her eyes, sniffling.> Corrupted! The Nightmare has risen from the depths of the dream. It all happened so fast... I was able to secret the staff here through the dream before it fell fully. It rests for now... but I fear we don't have much time. You must prepare to retrieve G'Hanir from the Dream. Draw water from the sacred moonwell on the northern edge of the grove and obtain an ancient's blessing. Quickly - every moment is precious!", ["objectivesText"] = "Fill a cup with moonwell water and obtain Leafbeard the Storied's blessing. Progress: Are you ready?", ["rewardGold"] = 283700, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 135501 }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.528, ["mapID"] = 747, ["npcID"] = 113525 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.528, ["mapID"] = 747, ["npcID"] = 113525 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 113525, ["questTurnInID"] = 113525, ["questType"] = "standard", ["sourceQuests"] = { 40649 }, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
