[41449] = { ["id"] = 41449, ["name"] = "Join the Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "I'm afraid I can't really help you actually enter the Emerald Dream - we dryads merely shift our bodies between the planes. That's ok, though - Naralex has offered to help! Go to the very bottom of the Tel'Andu Barrow Den. Naralex is already there setting things up for you.", ["objectivesText"] = "Find Naralex deep within the Tel'Andu Barrow Den.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.528, ["mapID"] = 747, ["npcID"] = 113525 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.183 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questGiverID"] = 113525, ["questType"] = "standard", ["sourceQuests"] = { 41422 }, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
