[41452] = { ["id"] = 41452, ["name"] = "Feline Frantic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "Greetings, stranger. <Mayruna bows to you.> We arrived from Val'Sharah a short time ago with hopes of settling here. Our journey was not easy and we are weary. These owlcats have made a mess of our camp, as you can surely see. Would you be so kind as to assist us with cleaning up? Then perhaps you can help us establish a new moonwell!", ["objectivesText"] = "Organize the camp. Progress: Is everything in its proper place?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41453] = { ["id"] = 41453, ["name"] = "Homeward Bounding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "The first step to establishing a moonwell is to gain the blessings of the local wildlife. It is their good will that enables us to peacefully coexist, and a moonwell thrives on such energies. Combined with Elune's light, a moonwell can purify its surroundings for years. To begin, we must find creatures willing to give their blessing. We can start with these owl-cat creatures. They ran while you cleaned, but I saw one lingering just before the bridge. See if you can find where it lives!", ["objectivesText"] = "Chase the Lost Feathermane Kitten across the bridge and return it to its family. Progress: Did you bring the little one back with you?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41452 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
