[41462] = { ["id"] = 41462, ["name"] = "Trouble Has Huge Feet", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "The Ettin's hide bears many shallow scratch marks and bite scars. It seems he had been terrorizing the local Owlcats for quite some time. Mardranel Forestheart would be interested in this.", ["objectivesText"] = "Take the Grotesque Ettin Leather to Mardranel Forestheart .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137179, 139791, 140240, 140251, 141941, 142054 }, ["starts"] = { { ["x"] = 0.217, ["y"] = 0.287, ["mapID"] = 680 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 3, ["flags"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41463] = { ["id"] = 41463, ["name"] = "Missing Along the Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41463 }, ["description"] = "As we retreated from Val'Sharah, our company was briefly separated by a conflict with some satyrs at the border. One of our own did not make it here- Mythandros' brother, Kalendros. I would like you to try and find him if you could. Search the woods just before the bridge back into Val'Sharah.", ["objectivesText"] = "Locate Kalendros Irongrove .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41452 } },
[41464] = { ["id"] = 41464, ["name"] = "Not Here, Not Now, Not Ever", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41464 }, ["description"] = "I cannot, will not, accept what is happening here. My body resists me, but I will stop this. <He looks at you.> You will stop this. Here is a root of the corrupted World Tree Shaladrassil. It has somehow found its way out of the ground to this untouched place and already the Darkfiend satyrs are hard at work corrupting Suramar . Stop them. Kill the satyrs, take their horns, drive their points through the totems. Only then can we have any hope of reversing this.", ["objectivesText"] = "Use Satyr Horns to destroy 3 Darkfiend Totems. Progress: Have you stalled their efforts, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137189, 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41463 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41465] = { ["id"] = 41465, ["name"] = "Estate Jewelry: A Braggart's Brooch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["series"] = { 41320 }, ["description"] = "Amateur merchants worry about losing face from bad products. Masters worry about losing face from bad customers. Naltethis Springblade has grown too bold for his station, and as such has lost much standing in the eyes of the city's elite. I sold this man a brooch, a clasp he wears on his cape. I am careful to only sell to those above my station. My pieces never tarnish, but my name and reputation are much more fragile. Relieve him of my property before he lowers me further.", ["objectivesText"] = "Retrieve Lespin's Brooch from Naltethis Springblade. Progress: That oaf will undo years of hard work. It is so much easier to fall than it is to climb...", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135508 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41307, 41320 }, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41466] = { ["id"] = 41466, ["name"] = "Estate Jewelry: Haute Claw-ture", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["series"] = { 41123, 41307 }, ["description"] = "An amateur merchant looks back on their previous work as a learning experience. A master knows that some things are better left forgotten. I was... vain, centuries ago. Desperate to prove myself, I took on a bold commission. Find him and bring... it... back. You will know what I am talking about when you see it. He resides near the villa south of this courtyard.", ["objectivesText"] = "Find and retrieve Lespin's 'art' from Mornath. Progress: He was so passionate, so driven. I saw his vision, created it to his exact specifications. Beautiful filigree and enamel put to a fearsome weapon...", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135509, 136577, 140247 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41307, 41320 }, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41467] = { ["id"] = 41467, ["name"] = "The Only Choice We Can Make", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41467 }, ["description"] = "Take this torch, <name>. We cannot reverse the Nightmare corruption once it has taken hold. All we can hope to do is destroy its manifestations. Incinerate the root. Only then can we rest easy in Suramar .", ["objectivesText"] = "Incinerate the Shaladrassil Root.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135534, 139791, 140240, 140251, 141941, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41464 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41468] = { ["id"] = 41468, ["name"] = "Mistress of the Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["series"] = { 41782 }, ["description"] = "The great forest guardian, Ursoc, gave his life for this world ten thousand years ago. After the guardian's death his claws were hidden away, safe from any who would use their power for evil. Lea Stonepaw and her Druids of the Claw consider Ursoc their paragon and dedicate their lives to following in his example. If anyone would know where the claws reside, it would be Lea. She and her Druids of the Claw reside in the Tel'Andu Barrow Den just to the north.", ["objectivesText"] = "Find Lea Stonepaw .", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 101259, ["x"] = 0.392, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 40646, 43980, 44431, 44443 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[41469] = { ["id"] = 41469, ["name"] = "Return to Irongrove Retreat", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "We have three blessings from the creatures we share this land with. Combined with a blessing from Elune, the moonwell will watch over this land for years to come. Meet Mythandros at the retreat. I am sure he would like to include you in the ritual.", ["objectivesText"] = "Seek Mythandros at Irongrove Retreat.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41479, 41480, 41485 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41473] = { ["id"] = 41473, ["name"] = "Redhoof the Ancient", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "While you were busy assisting the Owlcats across the river, Mythandros and Solendra ventured further to the east. I believe Mythandros may have found the next creature that may offer us its blessing. There is a secluded glade along the river's bend to the Northeast. There you may find our new ally, an elderly stag named Redhoof.", ["objectivesText"] = "Locate Mythandros and Redhoof the Ancient.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41197 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41474] = { ["id"] = 41474, ["name"] = "Fertilizing the Future", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "Like most herbivores, our antlered friends will eat anything green enough to chew. However I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food. I will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.", ["objectivesText"] = "Plant 5 Lush Grass Seeds in piles of Rich Soil . Progress: How goes the planting?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124640, 135558, 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41473 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41475] = { ["id"] = 41475, ["name"] = "Prongs and Fangs", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "Now, <name>, do not mistake me- I am a druid. I understand that nature has a balance. Predators must feed, and others will be hunted. I also understand that tampering with such balance has consequences. That is why I have taken upon myself to walk this land and perform some... ah... calculations. Slay only a small number of the wolves you find, and one alpha. That should reduce their number enough to allow the Sablehorn to thrive without disrupting the flow of things here.", ["objectivesText"] = "Slay 8 Suramar Snarlers and Gloomfang . Progress: Are you being gentle with your pruning?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41473 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41478] = { ["id"] = 41478, ["name"] = "The Final Blessing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "My friend Solendra Featherdown went to explore the habitat of the native Nightsabers. Now that we have the blessings of the Feathermane and the Sablehorn it is time to seek the blessing of the Nightsabers. She is just on the other side of this glade, to the North.", ["objectivesText"] = "Speak to Solendra Featherdown .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41474, 41475 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41479] = { ["id"] = 41479, ["name"] = "Natural Adversaries", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "I have walked this land in the time since our arrival. Here, basilisks have emerged from the ravines to the east. They encroach upon the home of the Nightsabers. To earn their blessing, I believe we should clear the way for their return. Slay the basilisks that have taken more than their fair share of the land, <race>.", ["objectivesText"] = "Slay 8 Manascale Basilisks .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41478 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41480] = { ["id"] = 41480, ["name"] = "Managazer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "There is one basilisk here who has gorged himself so thoroughly on Nightsaber flesh that he seldom leaves his cave. We will use this to our advantage. Seek out the basilisk Managazer and use his death as an example to the others who have strayed from their home.", ["objectivesText"] = "Slay Managazer , the Basilisk Lord. Progress: Managazer must perish, <race>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941, 141942 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41478 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
