[41485] = { ["id"] = 41485, ["name"] = "Moonwhisper Rescue", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "As a druid I understand that predation happens. Creatures that eat meat must acquire meat. But this... <Solendra gestures angrily toward a nearby petrified nightsaber .> This is just sad. Free them, <race>. Take my blessing and free them from this needless torment.", ["objectivesText"] = "Free 5 Petrified Nightsabers using Solendra's Gift. Progress: Have you freed them, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136605, 139791, 140240, 140251, 141941, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41478 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
