[41494] = { ["id"] = 41494, ["name"] = "Eminent Grow-main", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "You have done very well, <race>. All that is left is to combine their blessings into the ritual bundle and imbue the Moonwell. Once that is done, Mayruna will add a little water from a purified Moonwell and this land will be protected so long as we inhabit it. This is a momentous occasion, my friend. You bear witness to a sacred rite not often performed in the company of strangers. I will let you do the honors- simply place the ritual bundle into the sacred waters and we will do the rest.", ["objectivesText"] = "Imbue the inert waters with the ritual bundle , then witness the well's creation. Progress: You witness history, <race>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 136680, 139791, 140240, 140251, 141941, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41469 }, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
