[41499] = { ["id"] = 41499, ["name"] = "Squid Out of Water", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41001, 41499 }, ["description"] = "Toryl told me about those squid creatures that are controlling my brothers. I have never seen anything like them before around Jandvik. The naga must have brought them from wherever they came. I do not want any more of my kin to suffer the fate of being controlled by the naga. Find out where those squids come from and stop them.", ["objectivesText"] = "Destroy 5 Willbreaker Incubators in the Sashj'tar Ruins.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41425, 41426, 41709 }, ["questLines"] = { { ["id"] = 5813, ["name"] = "Brandolf", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
