[41540] = { ["id"] = 41540, ["name"] = "Rendezvous with the Courier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40392, 40400, 40402, 40403, 40419, 41540 }, ["series"] = { 40392 }, ["description"] = "Thas'dorah is a mighty bow indeed! The weapon was carved from a limb of Thas'alah, the mother tree of Eversong, and infused with the magic of the Sunwell. I fought alongside its first wielder, Talanas Windrunner, during an Amani troll incursion. Ah, but such tales can wait for another time. Courier Larkspear was making preparations to depart. You can meet him at Krasus' Landing.", ["objectivesText"] = "Speak to Courier Larkspur at Krasus' Landing.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questTurnInID"] = 107317, ["questType"] = "standard", ["sourceQuests"] = { 40618, 44043, 44366 }, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41541] = { ["id"] = 41541, ["name"] = "A Beastly Expedition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["series"] = { 41574 }, ["description"] = "I know the power of Titanstrike well. The Unseen Path battled the vrykul warlord Volund as he campaigned to conquer the Broken Isles. We sought to wrest the rifle from him, but he took it to his grave. If Volund's tomb can at last be opened, the artifact would be a great boon to our cause. I believe Grif Wildheart is making preparations to depart. You can meet him at Krasus' Landing.", ["objectivesText"] = "Speak to Grif Wildheart at Krasus' Landing in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questTurnInID"] = 107317, ["questType"] = "standard", ["sourceQuests"] = { 40618, 44043, 44366 }, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41542] = { ["id"] = 41542, ["name"] = "Preparation for the Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 39427, 40385, 41542 }, ["description"] = "Talonclaw is a mighty spear indeed! I first set eyes upon it when the Highmountain tauren led the members of my order up to Talon Peak to found the Trueshot Lodge. But such tales must wait for another time. Apata has been in Dalaran gathering supplies for her expedition. I imagine she's ready to depart by now. Seek her out at Krasus' Landing. I know she will be eager to begin.", ["objectivesText"] = "Speak to Apata Highmountain at Krasus' Landing in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questTurnInID"] = 107317, ["questType"] = "standard", ["sourceQuests"] = { 40618, 44043, 44366 }, ["questLines"] = { { ["id"] = 220, ["name"] = "Talonclaw", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 220, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
