[41574] = { ["id"] = 41574, ["name"] = "Stolen Thunder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 745, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["series"] = { 41541 }, ["description"] = "Titanstrike is in the tomb of Warlord Volund somewhere on the isle of Shield's Rest. It's a dank, sloppy mess adrift in a sea of gloom. Sounds lovely, eh? I've been workin' with a vrykul guide named Prustaga. She'll help us break the wards keepin' the tomb sealed. I know what you're thinkin'... vrykul are trouble. But she hasn't taken a swing at me just yet. Huey'll take us down to the shore. Prustaga's probably found the tomb by now!", ["objectivesText"] = "Accompany Grif Wildheart to Shield's Rest Island and track down Titanstrike. Progress: It's a good thing you found my observation relay! It's been missing for at least a thousand years.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["x"] = 0.712, ["y"] = 0.502, ["mapID"] = 627, ["npcID"] = 104381 } }, ["ends"] = { { ["x"] = 0.712, ["y"] = 0.502, ["mapID"] = 627, ["npcID"] = 104381 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.712, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 104381, ["questTurnInID"] = 104381, ["questType"] = "standard", ["sourceQuests"] = { 41541 }, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1579, ["db2PoiUiMapID"] = 745 },
