[41607] = { ["id"] = 41607, ["name"] = "Taking a Promenade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["description"] = "We must learn much about our long-lost kin if we are to fight them. We dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in. They have not returned in some time, and we must suspect the worst. Find them and we shall see what we are up against.", ["objectivesText"] = "Locate the scouts in the Promenade.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114883, ["x"] = 0.405, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114883, ["x"] = 0.405, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40632 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
