[41618] = { ["id"] = 41618, ["name"] = "The Seawarden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40364, 41606, 41618 }, ["description"] = "The Seawarden made a deal with the Tidemistress. She handed us over to him like cattle. I despise that sea giant! If I were not trapped in this bubble, I would choke the life out of him with my own two hands. If you cross his path before I get out of here, make him regret ever making a deal with the naga!", ["objectivesText"] = "Kill Seawarden Largush in Azuregale Bay. Progress: Have you slain the Seawarden?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41606 }, ["questLines"] = { { ["id"] = 5814, ["name"] = "Brytag", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
