[41625] = { ["id"] = 41625, ["name"] = "The Light's Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 18, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "Light's Wrath... a bold choice. Though if you believe you can control its energies, it could prove vital to our cause. Retrieving it won't be easy. It was last held by the Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it. The dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.", ["objectivesText"] = "Meet Kalec at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 7834 } }, ["questTurnInID"] = 101314, ["questType"] = "standard", ["sourceQuests"] = { 40706 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41626] = { ["id"] = 41626, ["name"] = "A New Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 115, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "If you seek the Nexus, I would warn not to rush headlong. There are strange happenings in Coldarra, and it would be best to gather some information before proceeding. During my last visit to the Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was very closely tied to Malygos' plans during the Nexus Wars, whatever is present there may explain the current state of the Nexus. I cannot accompany you, but this crystal can be used to communicate with me. Good luck.", ["objectivesText"] = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.287, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["ends"] = { { ["x"] = 0.287, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.287, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105081, ["questTurnInID"] = 105081, ["questType"] = "standard", ["sourceQuests"] = { 41625 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[41627] = { ["id"] = 41627, ["name"] = "A Forgotten Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "The device still hums with power. It must have been abandoned not long ago. The nearby switch appears to activate it.", ["objectivesText"] = "Activate the Ethereal Communication Device at the Azure Dragonshrine.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.567, ["y"] = 0.691, ["mapID"] = 115, ["objectID"] = 248398 } }, ["ends"] = { { ["x"] = 0.567, ["y"] = 0.691, ["mapID"] = 115, ["objectID"] = 248398 } }, ["coords"] = { ["mapID"] = 115, ["x"] = 0.567, ["y"] = 0.691 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard", ["sourceQuests"] = { 41626 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[41628] = { ["id"] = 41628, ["name"] = "Eyes of the Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 114, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41631, 41632 }, ["description"] = "You should travel at once to Coldarra in Borean Tundra, <name>. There, I would recommend you scout out a few key locations and report back to me. I know the area well, and should be able to tell you how to proceed. Make haste!", ["objectivesText"] = "Scout out the key locations in Coldarra.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930, 173430, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["npcID"] = 105917 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 41626 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114 },
[41629] = { ["id"] = 41629, ["name"] = "Harnessing the Holy Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 114, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41631, 41632 }, ["description"] = "The energy from Light's Wrath lashes out from within the weakened Nexus Vault. We may be able to use this raw, chaotic energy to our advantage. If we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", ["objectivesText"] = "Empower yourself with Unstable Holy Energy by defeating Wraths of the Light or siphoning from Breaches of Holy Energy around the foundation of the Nexus.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["npcID"] = 105917 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 41627 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114 },
[41630] = { ["id"] = 41630, ["name"] = "Unleashing Judgment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 114, ["storyline"] = { 41625, 41626, 41627, 41629, 41630, 41631, 41632 }, ["description"] = "You have the power you need to destroy the Surge Needles. At the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Light's Wrath into these points of focused void, and the reaction should cause an overload, destroying the Surge Needle above. You must act quickly. The Ethereum likely won't sit idly by as you lay waste to their machinations.", ["objectivesText"] = "Use your built up Unstable Holy Energy to destroy the Surge Needles in Coldarra.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["npcID"] = 105917 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 41628 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114 },
[41631] = { ["id"] = 41631, ["name"] = "The Nexus Vault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3, 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8094, ["mapID"] = 627, ["storyline"] = { 41628, 41629, 41630, 41631 }, ["description"] = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. We have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Light's Wrath, I would ask that you also free my brother from their grip. With the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, <name>.", ["objectivesText"] = "Defeat Nexus-Prince Bilaal and claim Light's Wrath.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["npcID"] = 105917 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8094 } }, ["questGiverID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 41630 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41632] = { ["id"] = 41632, ["name"] = "A Gift of Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 702, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "You have done a great thing for the blue dragons today, <name>, as well as for my own peace of mind. Now, armed with Light's Wrath, I only ask that you fulfill your original goal, and take the fight to the Legion. I believe Alonsus Faol awaits your return. Safe travels, friend.", ["objectivesText"] = "Speak with Alonsus Faol .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410 }, ["starts"] = { { ["x"] = 0.286, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["ends"] = { { ["x"] = 0.286, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.286, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105081, ["questTurnInID"] = 105081, ["questType"] = "standard", ["sourceQuests"] = { 41630 }, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
