[41689] = { ["id"] = 41689, ["name"] = "Cleansing the Mother Tree", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "We must save the Mother Tree at all costs. I believe I know a way. The world tree Nordrassil, atop Mount Hyjal, was born from an acorn of G'Hanir. We can use the sacred waters surrounding its roots to purify the corruption. If we take the Dreamway to Mount Hyjal's summit we should have enough time to complete the cleansing ritual before G'Hanir falls completely to the darkness.", ["objectivesText"] = "Use the Dreamway to travel to Mount Hyjal, then cleanse G'Hanir in the sacred waters beneath Nordrassil.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["x"] = 0.452, ["y"] = 0.519, ["mapID"] = 747, ["npcID"] = 104577 } }, ["ends"] = { { ["x"] = 0.452, ["y"] = 0.519, ["mapID"] = 747, ["npcID"] = 104577 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.452, ["y"] = 0.519 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 104577, ["questTurnInID"] = 104577, ["questType"] = "standard", ["sourceQuests"] = { 41690 }, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[41690] = { ["id"] = 41690, ["name"] = "Reconvene", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "You found Lyessa in the Dream, didn't you, Shan'do <name>? I heard you mutter her name in your slumber. Thank Elune she is well. You must seek her out - I can sense her presence even now at the Circle of Spirits above. If ever there were one who could help us cleanse G'Hanir, it is Lyessa.", ["objectivesText"] = "Meet with Lyessa Bloomwatcher at the Circle of Spirits.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.183 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 104349, ["questType"] = "standard", ["sourceQuests"] = { 41436 }, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
