[41702] = { ["id"] = 41702, ["name"] = "Written in Stone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40012, 40326, 41704, 41760 }, ["description"] = "<You bundle the notes and store them away in your pack. According to his final journal entry, Kel'danath used something called a \"spellstone\" in his experiments. The spellstone, if not the arcanist himself, must be nearby.>", ["objectivesText"] = "Retrieve the Spellstone of Kel'danath . Progress: <This withered seems entranced by the spellstone. He is completely pacified.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136271, 136600, 136970, 140349, 141668, 142054 }, ["starts"] = { { ["x"] = 0.209, ["y"] = 0.522, ["mapID"] = 680, ["objectID"] = 247694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104618, ["x"] = 0.26, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40326 }, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
