[41707] = { ["id"] = 41707, ["name"] = "Wormtalon Wreckage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38671, 41707 }, ["description"] = "As if Shaladrassil's encroaching roots were not enough to deal with, now the Wormtalon harpies have come to take advantage of our plight. Kill them, <race>. They deserve nothing less for feeding on our misery.", ["objectivesText"] = "Slay 15 Wormtalon Harpies in Shadowfen.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95117, ["x"] = 0.694, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95117, ["x"] = 0.694, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41054 }, ["questLines"] = { { ["id"] = 5764, ["name"] = "Shadowfen Sorrows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41708] = { ["id"] = 41708, ["name"] = "Dark Side of the Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "Xavius led Ysera past here, but their destination is unclear. This twisted wickedness smothers my mind! These refugees tell of an ancient Moonwell hidden in the ruins of their home. If it somehow resisted this corruption... I will beg of Elune a vision to give me direction. With her light, I may find my husband yet.", ["objectivesText"] = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 106175, 107307, 107312, 107317 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104885, ["x"] = 0.668, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6805, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41056 }, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41709] = { ["id"] = 41709, ["name"] = "Breaking Down the Big Guns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "You did well against that sea witch, but not well enough. Her power far surpasses any creature that I have ever fought. To defeat her, we will need something formidable. Something that she will not expect... < Toryl grins wryly.> Something of their own design... Salvage as many parts from their harpoon launchers as you can carry and meet me back in Jandvik.", ["objectivesText"] = "Collect 50 Harpoon Parts from Sashj'tar Harpooners in Azuregale Bay. Progress: The Tidemistress is a dangerous foe. We must be just as cunning to defeat her.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133926, 140244, 140245, 140254, 141674, 141675, 141946, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102390, ["x"] = 0.76, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40927 }, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
