[41728] = { ["id"] = 41728, ["name"] = "The Defense of Tian Monastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41729, 41730, 41731, 41732, 41733 }, ["description"] = "Chen's recent report indicates that Tian Monastery is under attack! <name>, they need your help. Go speak to Tak-Tak west of the main temple. He can get you there quickly.", ["objectivesText"] = "Travel to the Jade Forest on Pandaria, then speak to Taran Zhu at Tian Monastery. Speak to Tak-Tak west of the Temple of Five Dawns to fly there.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104784, ["x"] = 0.410667, ["y"] = 0.247333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.247333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 41905 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[41729] = { ["id"] = 41729, ["name"] = "Slowing the Spread", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41730, 41731, 41732, 41733 }, ["description"] = "Reinforcements. Just what we needed! Grandmaster, the monastery is under attack. The Legion is using a foul device known as a Fel Spreader to scorch the very earth we walk on with disgusting fel energy. Destroy those machines, and we can slow their efforts.", ["objectivesText"] = "Destroy 3 Fel Spreaders .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104745, ["x"] = 0.382, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 41905 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[41730] = { ["id"] = 41730, ["name"] = "Desperate Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41731, 41732, 41733 }, ["description"] = "Good, your timing couldn't have been better, <name>. These foul Legion creatures have invaded our sanctuary. They have no place here on our world. Kill every demon you see, <brother/sister>.", ["objectivesText"] = "Kill 20 demon attackers. Progress: This is an invasion like none I have ever seen before.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104784, ["x"] = 0.410667, ["y"] = 0.247333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.247333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 41728 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[41731] = { ["id"] = 41731, ["name"] = "Storm, Earth, and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41730, 41732, 41733 }, ["description"] = "Tian Monastery is in bad shape. Felspreader imps are torching the grounds. Fel spikes radiate foul energy, corrupting the nearby earth. And fel magic has seeped into the monastery's ale barrels, tainting the brew. Use your abilities to snuff the flames, shatter the spikes, and destroy the tainted barrels. Sigh... hundreds of years of the finest ale... ruined. I don't wish to hear any more of it. Just get it done.", ["objectivesText"] = "Destroy 5 Fel Spikes, put out 5 Fel Fires , and destroy 5 Tainted Ale barrels. Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104784, ["x"] = 0.410667, ["y"] = 0.247333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.247333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 41728 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[41732] = { ["id"] = 41732, ["name"] = "The Hand of Keletress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41730, 41731, 41733 }, ["description"] = "The demons' leader is up ahead, taking prisoners it is said! This dire storm, we will weather... if we fight her together!", ["objectivesText"] = "Kill Skola Greatsword .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.431333, ["y"] = 0.253333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 41729, 41730, 41731 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
