[41740] = { ["id"] = 41740, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "There are many ways to commune with the elements. In their ingenuity, the goblins have found ways to imbue their mechanical devices with the energy of elemental spirits. I do not pretend to understand. But in our hour of need, we should not hesitate to embrace a diversity of options. We are fortunate to have at our disposal the services of the one they call \"Goldmine,\" whose unorthodox research may significantly augment our power. He waits nearby.", ["objectivesText"] = "Speak to Journeyman Goldmine at the Heart of Azeroth in the Maelstrom. Progress: What's it gonna be, boss?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41741 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 13, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[41741] = { ["id"] = 41741, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "It is time for us to test the strength of your newly summoned Lesser Elementals. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Troops in the Field.\" Progress: How did it go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42142 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
