[41760] = { ["id"] = 41760, ["name"] = "Kel'danath's Legacy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40012, 40326, 41702, 41704 }, ["description"] = "Kel'danath discovered something incredible - the power to subdue and even control the withered. I will pick up where my old friend left off. We shall see to it that he did not die in vain. Perhaps in the end we can even find peace for the wretches who have been left to a fate worse than death. I will need more subjects. Take Kel'danath's spellstone and use it to subdue more withered.", ["objectivesText"] = "Use the Spellstone of Kel'danath to charm 5 withered and send them to Shal'Aran. Progress: We will need more subjects if we are to continue Kel'danath's research.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136600, 136970, 140349, 141668, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41704 }, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41761] = { ["id"] = 41761, ["name"] = "Winter Moose Roundup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41761 }, ["description"] = "My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped! The little terrors could have slaughtered them in the cage, but they like to hunt their prey. I'm afraid that if I stay out here much longer, I'll be their next meal! Will you round up the talbuk and bring them here? I can't get them myself, and I can't let my dad find out about this! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(41761)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(41761))\");", ["objectivesText"] = "Rescue 4 Talbuk at Kuuros Farm.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard" },
[41762] = { ["id"] = 41762, ["name"] = "Sympathizers Among the Shal'dorei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41762, 41834, 41989, 42079, 42147 }, ["series"] = { 41834, 41989 }, ["description"] = "Elisande's decision to welcome the Legion into Suramar earned her plenty of enemies, though only some of us were bold enough to openly defy her. We have allies in the city - we just don't know how many. I need you to make contact with a spell-fencer by the name of Silgryn . He is loyal to our cause, and has been lying in wait since our failed coup. He patrols the western edge of the city. Address him by name and tell him our cause is not lost!", ["objectivesText"] = "Speak with Silgryn in the Suramar Outskirts.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136600, 136970, 137010, 141947 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 105071, ["x"] = 0.41, ["y"] = 0.7355 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41760 }, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41763] = { ["id"] = 41763, ["name"] = "Close Enough to Touch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "He is near, <race>, I can feel it. We must search Shala'nir for Malfurion. If we do not find him soon, I fear he will be lost to me forever. I was unsure of your worth when first we met. I know now that you will not fail me. I am... grateful.", ["objectivesText"] = "Search for Malfurion within Shala'nir.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325 }, ["rewardChoices"] = { 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104799, ["x"] = 0.578, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.427333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 43702 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41764] = { ["id"] = 41764, ["name"] = "Walking in Their Footsteps", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41799, 41800, 41884, 48185, 48190, 48434, 48435 }, ["description"] = "Spiritwalkers maintain balance between the world of the living and the spirit realm. We can travel into the memories of the dead to glean clues about the past. The wards Ebonhorn maintained were placed long ago by heroes who fought the darkness. By walking in their footsteps, we may locate the wards and restore them. Igrul, the drogbar known as the Scalebane, was a true friend to Huln Highmountain. Use the Water of Vision to enter his memories and find where he placed the first ward.", ["objectivesText"] = "Use the Water of Vision to walk in the memories of Igrul the Scalebane. Progress: As a spiritwalker, I am able to see the memories of the dead.", ["rewardGold"] = 312800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 41884 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41766] = { ["id"] = 41766, ["name"] = "Wildlife Protection Force", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41766 }, ["objectivesText"] = "Defeat Rocko in a pet battle.", ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defeat the Hungry Icefang", ["amount"] = 1, ["type"] = 12, ["objectID"] = 1843, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest" },
[41767] = { ["id"] = 41767, ["name"] = "A Daring Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 748, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 39389, 40218, 41759 }, ["description"] = "The plan is a simple one, but it will require great effort on your part. Kira and I will summon the demonic gateway, but you will have to enter alone and recover the missing council members.", ["objectivesText"] = "Enter the demon world and rescue the missing council members. Progress: Kira and I can sustain the gateway, but you will need to enter the demon world alone.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.552, ["y"] = 0.37, ["mapID"] = 717, ["npcID"] = 105018 } }, ["ends"] = { { ["x"] = 0.552, ["y"] = 0.37, ["mapID"] = 717, ["npcID"] = 105018 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.552, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 105018, ["questTurnInID"] = 105018, ["questType"] = "standard", ["sourceQuests"] = { 40218 }, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1604, ["db2PoiUiMapID"] = 748 },
[41768] = { ["id"] = 41768, ["name"] = "Soul Beacon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41769, 41780, 41781, 41784 }, ["description"] = "I have bound Shinfel's soul to her staff, allowing it to serve as an anchor in this world. When we perform the ritual of summoning, it will act as a beacon, guiding Shinfel through the Twisting Nether and back to our world.", ["objectivesText"] = "Perform a ritual of summoning to retrieve the missing council member. Progress: The council cannot be rebuilt without Shinfel.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.371, ["mapID"] = 717, ["npcID"] = 105018 } }, ["ends"] = { { ["x"] = 0.553, ["y"] = 0.371, ["mapID"] = 717, ["npcID"] = 105018 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.553, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 105018, ["questTurnInID"] = 105018, ["questType"] = "standard", ["sourceQuests"] = { 42098, 42100 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41769] = { ["id"] = 41769, ["name"] = "Mad Ernie the Alchemist", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41780, 41781, 41784 }, ["description"] = "If we have any hope of curing this curse, we need to know what kind of magic we're dealing with. I know of an alchemist who earned himself quite the reputation for his unconventional methods. Shunned from Gilneas long ago, I believe Mad Ernie has taken up residence in these lands. His knowledge may be the first step to breaking this curse.", ["objectivesText"] = "Find Mad Ernie the Alchemist in Val'sharah. Progress: Have you come to lend a hand? We all must do our part.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.54, ["y"] = 0.362, ["mapID"] = 717, ["npcID"] = 105102 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7875 } }, ["questGiverID"] = 105102, ["questType"] = "standard", ["sourceQuests"] = { 41768 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41770] = { ["id"] = 41770, ["name"] = "The Skies Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 737, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41771, 42184 }, ["description"] = "There has been no Windlord to lead the air elementals since the death of Al'Akir. The realm of Skywall has been thrown into turmoil. The throne of Al'Akir is Thunderaan's by right, but what remains of the prince's essence within Thunderfury is diminishing. If we do not move quickly, Thunderaan may be lost forever. Take the damaged Thunderfury to Vortex Pinnacle and speak with Celestos. Celestos was a loyal servant of Al'Akir and he will share our desire to see Thunderaan reborn.", ["objectivesText"] = "Speak with Celestos in The Vortex Pinnacle.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139000, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 43002 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1602, ["db2PoiUiMapID"] = 737 },
[41771] = { ["id"] = 41771, ["name"] = "Recharging the Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["mapID"] = 737, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41770, 42184 }, ["description"] = "You have recovered the Blessed Blade of the Windseeker, and with it you hold all that is left of the soul of Prince Thunderaan. Thunderfury can be restored, but it will require a rare essence known as the Heart of Skywall . Vortos, the Duke of the East Winds, possesses the heart... but he will not give it willingly. Vortos must be defeated, and the Heart of Skywall must be combined with the blade. Only then can Thunderaan return and claim the Throne of Four Winds.", ["objectivesText"] = "Obtain the Heart of Skywall . Progress: Have you retrieved the Heart of Skywall ?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 135589, 137209, 137374, 139000, 139037, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.552, ["y"] = 0.184, ["mapID"] = 737, ["npcID"] = 104797 } }, ["ends"] = { { ["x"] = 0.552, ["y"] = 0.184, ["mapID"] = 737, ["npcID"] = 104797 } }, ["coords"] = { ["mapID"] = 737, ["x"] = 0.552, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8093 } }, ["questGiverID"] = 104797, ["questTurnInID"] = 104797, ["questType"] = "standard", ["sourceQuests"] = { 41770 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1602, ["db2PoiUiMapID"] = 737 },
[41772] = { ["id"] = 41772, ["name"] = "Ascendant of Flames", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 738, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41900, 42208 }, ["description"] = "As we speak, an endless war rages for control of the Firelands. Of the two aspiring Firelords, Lord Smolderon hates mortals less. If we help him defeat his rival and ascend to Firelord, he may unite with us in return. The champions of the Earthen Ring have already made their way to the Firelands. Go and meet with Rehgar Earthfury and find a way to turn an old enemy into a new ally. If anyone can succeed at this impossible task, I have faith that it is you, Farseer. May the elements be with you.", ["objectivesText"] = "Speak with Rehgar Earthfury in the Firelands.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 143489 }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.6, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.6, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42208, 42988, 42990 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1605, ["db2PoiUiMapID"] = 738 },
[41773] = { ["id"] = 41773, ["name"] = "The Firelord's Command", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8125, ["mapID"] = 738, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41774, 41888, 41934 }, ["description"] = "Greetings, mortal. I am Scaldius, emissary of Lord Smolderon . I have just met with others from your order. They tell me that you will bring an end to those who oppose my master. This pleases Lord Smolderon . Pyroth and his minions defy my master's rule and so an example must be made of them. You will slay Pyroth and his champions! Nothing is more humiliating than death at the hands of a mortal. Do this and Lord Smolderon will grant you audience.", ["objectivesText"] = "Defeat the forces of Pyroth. Progress: I will devour the heart of Pyroth with great pleasure!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 136535, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.27, ["y"] = 0.822, ["mapID"] = 738, ["npcID"] = 105055 } }, ["ends"] = { { ["x"] = 0.27, ["y"] = 0.822, ["mapID"] = 738, ["npcID"] = 105055 } }, ["coords"] = { ["mapID"] = 738, ["x"] = 0.27, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questGiverID"] = 105055, ["questTurnInID"] = 105055, ["questType"] = "standard", ["sourceQuests"] = { 41772 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1605, ["db2PoiUiMapID"] = 738 },
[41774] = { ["id"] = 41774, ["name"] = "The Rival Lords of Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8125, ["mapID"] = 738, ["storyline"] = { 41774 }, ["series"] = { 41773, 41888, 41934 }, ["description"] = "You stand before the true Lord of the Firelands, mortal. This land is mine by right, claimed from the ashes of Ragnaros himself. However, there are still some who foolishly oppose my reign. I would take great pleasure in destroying their worthless souls, but I will not honor them with death by my hands. They must be humiliated for their insolence, and there is nothing more humiliating than being slain by a mere mortal. Amuse me shaman. Prove your worth and destroy my rivals!", ["objectivesText"] = "Return to Lord Smolderon with Garixxia's Smoldering Heart and the Core of Molten Rage.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 136535, 136536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questType"] = "standard" },
[41775] = { ["id"] = 41775, ["name"] = "The Great Stonemother", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41901, 42068, 42200 }, ["description"] = "In order to unite the four Elemental Lords of Azeroth, you will need to seek out Therazane and convince her to join the cause of Azeroth. However, the Stonemother currently has her hands full battling a Twilight's Hammer resurgence in Deepholm. If we lend Therazane our aid she may agree to unite with the Earthen Ring against the Burning Legion. Journey to Therazane 's Throne in the heart of Deepholm. Aid her in defeating the Twilight's Hammer and convince her to join the defense of Azeroth!", ["objectivesText"] = "Speak with Therazane in Deepholm. Progress: What would you have with the Stonemother, <class>?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42200 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[41776] = { ["id"] = 41776, ["name"] = "Return of the Windlord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["mapID"] = 737, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "With Thunderfury recharged, Prince Thunderaan can now return to the physical realm. In a moment, I will release my master's spirit from the blessed blade. When the ritual is complete, Skywall will once again have its Windlord.", ["objectivesText"] = "Summon Prince Thunderaan .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["starts"] = { { ["x"] = 0.521, ["y"] = 0.819, ["mapID"] = 737, ["npcID"] = 113340 } }, ["ends"] = { { ["x"] = 0.521, ["y"] = 0.819, ["mapID"] = 737, ["npcID"] = 113340 } }, ["coords"] = { ["mapID"] = 737, ["x"] = 0.521, ["y"] = 0.819 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8093 } }, ["questGiverID"] = 113340, ["questTurnInID"] = 113340, ["questType"] = "standard", ["sourceQuests"] = { 41771 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1602, ["db2PoiUiMapID"] = 737 },
[41777] = { ["id"] = 41777, ["name"] = "Destroying the Cult", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41897, 41898, 41899, 42065 }, ["description"] = "We are all that stands between the Twilight's Hammer and their conquest of Deepholm. Azeroth cannot hope to fight the full strength of the Twilight's Hammer and the Burning Legion at the same time. It is up to us to put an end to their cult before they are able to fully rebuild. Accompany me into their stronghold and we shall cut through their ranks together!", ["objectivesText"] = "Slay 15 Twilight's Hammer cultists at The Twilight Throne. Progress: How many have you slain? I've lost count.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.64, ["y"] = 0.705, ["mapID"] = 207, ["npcID"] = 106001 } }, ["ends"] = { { ["x"] = 0.64, ["y"] = 0.705, ["mapID"] = 207, ["npcID"] = 106001 } }, ["coords"] = { ["mapID"] = 207, ["x"] = 0.64, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5042 } }, ["questGiverID"] = 106001, ["questTurnInID"] = 106001, ["questType"] = "standard", ["sourceQuests"] = { 42068 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[41780] = { ["id"] = 41780, ["name"] = "Doom and Gloom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41769, 41781, 41784 }, ["description"] = "Doom curses are serious business, so much so that many warlocks didn't deal in them for some time. The magic grows stronger as time goes on, eventually leading to death. Only the caster of the curse can remove it. I can craft an elixir that will slow its progression, but you'll need to collect an assortment of ingredients first.", ["objectivesText"] = "Recover the ingredients Ernest needs to create an Elixir of Suspension. Progress: Have you found those ingredients yet? Time really isn't on your side, you know.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 128330, 128758, 128759, 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41781 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41781] = { ["id"] = 41781, ["name"] = "Herding Goats", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41769, 41780, 41784 }, ["description"] = "In case you haven't noticed, things are a bit hectic around here. Marl's doing a good job protecting the corn fields, but the commotion gave our goats quite the scare. They dashed out of their pen as soon as the fighting started, and are now running amuck! Round them up for me and I'll do my best to figure out how to handle the curse you're dealing with.", ["objectivesText"] = "Catch Greyhorn Goats, then return them to their pen. Progress: Have you found my goats yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41769 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41782] = { ["id"] = 41782, ["name"] = "To The Hills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["series"] = { 41468 }, ["description"] = "It is said that a fragment of Ursoc's spirit, his fury and rage, remained within the claws after his death. Only those who have attained mastery of discipline have any hope of wielding them without being overwhelmed by the bear lord's fury. <Lea looks intently at you for a moment.> But you are no novice, I can see that clearly. Very well, draw water from the moonwell on the northern edge of the grove then come find me. I'll await your arrival within the broken stump of Vordrassil in Northrend.", ["objectivesText"] = "Fill a Vial of Moonwell Water and locate Lea Stonepaw within Grizzly Hills. Progress: Did you get the moonwell water? It is essential for our task!", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 49927, 128306, 128822, 128858, 128859, 135563, 197388, 197998, 198015, 198023, 198030 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 101259, ["x"] = 0.392, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 116, 641 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["sourceQuests"] = { 41468 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116 },
[41784] = { ["id"] = 41784, ["name"] = "Borrowed Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41769, 41780, 41781 }, ["description"] = "Don't let the aroma deceive you, this concoction is mostly safe for consumption. Whoever is afflicted should drink the entire contents of the vial, every last drop! If the elixir works, the effects should be immediate. If not, well... just tell them they drink at their own risk, alright? Keep in mind, this will only weaken the curse, not cure it.", ["objectivesText"] = "Give the Elixir of Suspension to Shinfel Blightsworn. Progress: Shinfel's curse will kill her soon if we don't find a way to slow its progression.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 136357, 139506, 139765, 139767, 139770, 140517, 140922, 224272, 224273, 224274 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 104824, ["questType"] = "standard", ["sourceQuests"] = { 41780 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41785] = { ["id"] = 41785, ["name"] = "Finding Fizzlebang", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41787, 41788, 41793, 41795, 41796, 42102 }, ["description"] = "I have reason to believe that Wilfred Fizzlebang's sister has made her way to Stormheim. If she has half his power, but at least twice his intelligence, then we just might succeed in summoning the eredar twins.", ["objectivesText"] = "Find Lulubelle Fizzlebang in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.539, ["y"] = 0.362, ["mapID"] = 717, ["npcID"] = 105102 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7875 } }, ["questGiverID"] = 105102, ["questType"] = "standard", ["sourceQuests"] = { 42102, 42103, 42660, 44682 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41787] = { ["id"] = 41787, ["name"] = "Someone Else's Mess", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41788, 41793, 41795, 41796, 42102 }, ["description"] = "A confession alone won't be enough to clear my name. As long as those demons run amuck, people will blame their presence on me. Someone needs to clean up the mess that warlock made. I'd do it myself, but I can't be placed at the scene of the crime. You could banish them though. That would do the trick. Use this orb on newly summoned demons to send them right back where they came from - permanently!", ["objectivesText"] = "Banish demons that have been irresponsibly summoned in Stormheim.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 141865 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 41785 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41788] = { ["id"] = 41788, ["name"] = "Coercing a Confession", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41793, 41795, 41796, 42102 }, ["description"] = "My location has to be kept secret, at least until I have proof of my innocence. Thanks to the legacy of my family name, any time some miserable warlock summons demons they can't control, I get the blame. The scene of my latest \"crime\" is a nearby cave, where unruly imps and other nasty demons are roaming free. Find the lousy warlock who's responsible, and get him to write a confession.", ["objectivesText"] = "Find the warlock that has been irresponsibly summoning demons and obtain a written confession of his wrongdoings.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 136363, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 41785 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41789] = { ["id"] = 41789, ["name"] = "Return to the Crag", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41789 }, ["objectivesText"] = "Vilewing harpy slain Hexxing Fetish destroyed Cursed wildlife slain", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Vilewing harpy slain", ["amount"] = 3, ["type"] = 0, ["objectID"] = 113656, ["orderIndex"] = 0 }, { ["text"] = "Hexxing Fetish destroyed", ["amount"] = 4, ["type"] = 0, ["objectID"] = 104531, ["orderIndex"] = 1 }, { ["text"] = "Cursed wildlife slain", ["amount"] = 6, ["type"] = 0, ["objectID"] = 113657, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[41790] = { ["id"] = 41790, ["name"] = "The First Trial of Ursol", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "The Legion... <the glow of Ursol 's eyes begin to shine intensely> Yes... I remember clearly that day long ago when my brother fell. Countless demons fell beneath his claws until, through the overwhelming numbers of the enemy, he was overtaken. My brother was the true spirit of the bear! You must prove to me that the spirit of the bear resides within you as well.", ["objectivesText"] = "Complete the first of Ursol 's trials. Progress: <The ancient stares at you expectantly.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["sourceQuests"] = { 41782 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets" },
[41791] = { ["id"] = 41791, ["name"] = "The Second Trial of Ursol", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "Ursoc never backed down from a battle, even when faced with overwhelming odds. If you would take up his claws you will show me that you possess the same courage. Your next trial will place you against an onslaught of my followers. Defeat all of the spirits and prove that you possess the courage of the bear!", ["objectivesText"] = "Complete the second of Ursol 's trials. Progress: <The ancient stares at you expectantly.>", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["sourceQuests"] = { 41790 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets" },
[41792] = { ["id"] = 41792, ["name"] = "The Third Trial of Ursol", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "You've proven to me your strength and your courage, but do you possess the ability to apply yourself when it matters most? This final trial will reveal all.", ["objectivesText"] = "Complete the third of Ursol 's trials. Progress: <The ancient stares at you expectantly.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["sourceQuests"] = { 41791 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets" },
[41793] = { ["id"] = 41793, ["name"] = "Lulubelle on Loan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41795, 41796, 42102 }, ["description"] = "What you plan to do is pretty risky, you know? Summoning one sister would be difficult enough, but both of them at once? That's just asking for trouble. Luckily, I'm up for the challenge. I'll help you and the rest of the council summon those demons, and hopefully restore pride to the Fizzlebang name.", ["objectivesText"] = "Speak to Ritssyn Flamescowl .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 104855, ["questType"] = "standard", ["sourceQuests"] = { 41787, 41788 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41794] = { ["id"] = 41794, ["name"] = "Drakestalker", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41794 }, ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136369 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 30, ["objectID"] = 136369 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[41795] = { ["id"] = 41795, ["name"] = "Summoning the Sisters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41793, 41796, 42102 }, ["description"] = "It would be best to conduct the summoning on the outskirts of Dreadscar Rift. If things do not go as planned, at least the aftermath will be contained to a small island of land that floats above our order. Once the sisters have been summoned, use the Bloodstone to enslave them. I'll let the others know it's time to begin.", ["objectivesText"] = "Travel through the Demonic Gateway to reach the summoning platform and use the Bloodstone to subdue the eredar sisters once the summoning is complete.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.374, ["mapID"] = 717, ["npcID"] = 105815 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.374, ["mapID"] = 717, ["npcID"] = 105815 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.55, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 105815, ["questTurnInID"] = 105815, ["questType"] = "standard", ["sourceQuests"] = { 41755 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41796] = { ["id"] = 41796, ["name"] = "Selecting a Sixth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41793, 41795, 42102 }, ["description"] = "With the demon sisters under your control, you have managed to weaken Mephistroth's army and gain powerful allies for the council. Our work is not done, however. Dreadscar Rift will remain a target as long as the Burning Legion remains. If we wish to protect our new home, we must rebuild the council. Both Lulubelle and Kira have proven themselves worthy to join our ranks, though only one spot remains. As First of the Black Harvest, the choice is yours.", ["objectivesText"] = "Choose who will become the final member of the council. Progress: The choice may not be easy, but it is yours to make.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 142057, 142058, 142059, 142063 }, ["rewardChoices"] = { 142057, 142058, 142059, 142063 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.374, ["mapID"] = 717, ["npcID"] = 105951 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.374, ["mapID"] = 717, ["npcID"] = 105951 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.55, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 105951, ["questTurnInID"] = 105951, ["questType"] = "standard", ["sourceQuests"] = { 41795 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41797] = { ["id"] = 41797, ["name"] = "Recruiting The Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 42601, 42602, 42603, 42608 }, ["description"] = "As her name suggests, Imp Mother Dyala is adept at summoning imps. While the council controls Dreadscar Rift, her services will be ours to use as we see fit. Speak to her if you wish to train a pack of imps.", ["objectivesText"] = "Speak to Imp Mother Dyala and train a Pack of Imps. Progress: How did the training go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["ends"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.663, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 106199, ["questTurnInID"] = 106199, ["questType"] = "standard", ["sourceQuests"] = { 42603 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41798] = { ["id"] = 41798, ["name"] = "Recruiting More Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["description"] = "As First of the council, you have acolytes devoted to helping any way they can. Recruiter Jared is in charge of screening candidates, only selecting those that possess the skills we desire. Speak to him now.", ["objectivesText"] = "Speak to Recruiter Jared .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["ends"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.663, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 106199, ["questTurnInID"] = 106199, ["questType"] = "standard", ["sourceQuests"] = { 41752, 41753 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[41799] = { ["id"] = 41799, ["name"] = "Minions of the Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41800, 41884, 48185, 48190, 48434, 48435 }, ["description"] = "Oenia Skyhorn was a legendary chieftain of her tribe. Though she crossed over to the spirit realm long ago, her presence is still felt all around us. Ebonhorn told me that Oenia placed a ward here to protect the people she cared for so deeply... perhaps from the specter of the Darkness. Use the Water of Vision to journey into her echoes. Worry not that this ritual might disturb her rest. A hero like Oenia would relish a chance to aid us in the present.", ["objectivesText"] = "Use the Water of Vision to walk in the memories of Oenia Skyhorn. Progress: The spirits speak of the Darkness. A great danger rises, <name>.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125459, ["x"] = 0.57, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125459, ["x"] = 0.57, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 48185 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41800] = { ["id"] = 41800, ["name"] = "Servants of the Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41884, 48185, 48190, 48434, 48435 }, ["description"] = "The heroes of Highmountain's past placed wards to protect our land from the insidious Old Gods. The deeds of these noble champions kept us safe for thousands of years. We must not fail their memory. Huln Highmountain himself placed the ward here at Snowblind Mesa. It must be reactivated for us to have any hope of saving Ebonhorn. Enter the echo of Huln's spirit, and let his courage lead you to the location of this ward.", ["objectivesText"] = "Use the Water of Vision to walk in the memories of Huln Highmountain.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125466, ["x"] = 0.532, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125466, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 48190 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41802] = { ["id"] = 41802, ["name"] = "The Gates of Valor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41158, 41159, 41802 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170 }, ["description"] = "Ye'd not normally know it, but the terraced entrance to the vrykul's Halls o' Valor is a fine place for findin' ancient artifacts. Problem is, the place is just a big mess with demons at the time. Well, ye've not got much choice. If the disc isn't elsewhere in Stormheim, it most likely lies at the Gates of Valor. Good luck, <name>.", ["objectivesText"] = "Obtain 6 Chipped Titan Disc Fragments by surveying near the Gates of Valor in Stormheim. Progress: Ye're back in one piece. What's the news?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131735, 134083 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41159 }, ["questLines"] = { { ["id"] = 325, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41803] = { ["id"] = 41803, ["name"] = "Asking a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "Caria Felsoul was a bright student... and a Legion traitor. In her treason she was bestowed the Aldrachi Warblades, the soul-rending blades of the Aldrachi's greatest champion - they say he only finally fell to Sargeras himself. We sent a small force to find Caria, but we have not heard word since. Jace has a Legion communicator he believes we can use to reach them- we just need a power source. Perhaps you could see if Khadgar has anything we could use? I'm afraid our allies are few.", ["objectivesText"] = "Ask Khadgar for a source to power the Legion communicator.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95237 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 95237 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 95237, ["questTurnInID"] = 95237, ["questType"] = "standard", ["sourceQuests"] = { 40816, 44379 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41804] = { ["id"] = 41804, ["name"] = "Ask and You Shall Receive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "A Legion communicator? Hmmmm. <Khadgar pauses to think for a moment.> You know what, I think I have something in my lockbox upstairs that is just the ticket.", ["objectivesText"] = "Obtain the Crystallized Soul from Archmage Khadgar . Progress: I'm always happy to help a friend.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 127830, 128832, 136385 }, ["starts"] = { { ["x"] = 0.285, ["y"] = 0.483, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.483, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 40247, 41803 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41806] = { ["id"] = 41806, ["name"] = "Return to Jace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "That crystallized soul should power your communicator long enough to reach your allies. I must urge you to be cautious, <name>. If that device is of Legion origin, then you never know who among its creators might overhear your message. I'm sure your allies eagerly await your return.", ["objectivesText"] = "Return to Jace Darkweaver .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.486, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.288, ["y"] = 0.486, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.288, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 41804 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41807] = { ["id"] = 41807, ["name"] = "Establishing a Connection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "<Jace glances at the crystallized soul.> Yes, that will do nicely. Release its energy to activate the communicator - it should already be configured to contact Allari and her forces. If Caria is out there, we will find her, and we will make her suffer for her transgressions.", ["objectivesText"] = "Activate the Legion Communicator and receive Allari the Souleater's report. Progress: This may be our only chance at revenge against Caria. Every moment is precious.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.744, ["y"] = 0.512, ["mapID"] = 627, ["npcID"] = 99262 } }, ["ends"] = { { ["x"] = 0.744, ["y"] = 0.512, ["mapID"] = 627, ["npcID"] = 99262 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.744, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99262, ["questTurnInID"] = 99262, ["questType"] = "standard", ["sourceQuests"] = { 41806 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41815] = { ["id"] = 41815, ["name"] = "Curse of the Necrodark", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41839, 41840, 41841, 41882, 48403 }, ["description"] = "It is clear that the Old Gods have long sought to control Highmountain. Their covetous desire speaks to the power of this land, and the strength of the spirits that echo through its peaks and valleys. They will not take our sacred mountain, <name>. Not while I draw breath. With the Highmountain tribes united, and with Baine Bloodhoof at our side, we will defeat the Darkness... once and for all. Come. Let us take back the summit from the forces that would corrupt it.", ["objectivesText"] = "Journey to Highmountain Summit.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["starts"] = { { ["x"] = 0.69, ["y"] = 0.704, ["mapID"] = 650, ["npcID"] = 108434 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 130423, ["x"] = 0.564, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 108434, ["questType"] = "standard", ["sourceQuests"] = { 48434 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
