[41834] = { ["id"] = 41834, ["name"] = "The Masks We Wear", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41762, 41834, 41989, 42079, 42147 }, ["series"] = { 41762, 41989 }, ["description"] = "Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent. We must spread the word, discreetly, among the populace. Ly'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion. Ly'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers. Let us invite ourselves in.", ["objectivesText"] = "Speak with 8 Masqued Revelers while in costume, then speak with Ly'leth Lunastre . Progress: Pleased to make your acquaintance.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136600, 136970, 137010, 141947 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 105071, ["x"] = 0.41, ["y"] = 0.7355 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.7355 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41762 }, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
