[41839] = { ["id"] = 41839, ["name"] = "The Taken", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41839 }, ["series"] = { 41815, 41840, 41841, 41882, 48403 }, ["description"] = "When Mayla's father was taken, so were the corpses of several of our greatest chieftains. The Grey One, even now, is priming Mayla's father to be a vessel for his evil agenda. But the others have already been taken by the necrodark, their corpses now vessels for malevolent drogbar spirits. I will be honest, I do not think my skills could defeat these monstrosities. We need your help! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(41839)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(41839))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Defeat the Taken Chieftains.", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 37206, 37403, 37417, 37482, 197642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[41840] = { ["id"] = 41840, ["name"] = "Ice and Shadow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41841, 41882, 48403 }, ["description"] = "We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence. Perhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets. I know little of such magics, but it seemed that Ebonhorn had a use for them in mind.", ["objectivesText"] = "Collect 20 Shadowice Shards . Progress: Did you find more of the shards?", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 136400 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 130423, ["x"] = 0.564, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 41815 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[41841] = { ["id"] = 41841, ["name"] = "The Final Ward", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41840, 41882, 48403 }, ["description"] = "The Necrodark are readying their ritual to give physical form to the Darkness. They've sealed themselves inside and barred our way. The shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest. Do not hesitate. The fate of Highmountain itself hangs in the balance.", ["objectivesText"] = "Restore the Summit Ward. Progress: This is the hardest challenge I have ever had to face.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.922667 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 41840, 41882 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
