[41849] = { ["id"] = 41849, ["name"] = "The Iron Fist", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["series"] = { 41850, 41852 }, ["description"] = "It's time to send a rescue operation to the Gates of Valor, <name>. I will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim. Grandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.", ["objectivesText"] = "Speak to Angus Ironfist at Tideskorn Warcamp in Stormheim.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 105045, ["x"] = 0.629, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 41909, 43054, 43062 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41850] = { ["id"] = 41850, ["name"] = "The Master of Swords", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["series"] = { 41849, 41852 }, ["description"] = "I got bad news fer ya - we don't have time to wait for reinforcements. They're sacrificin' prisoners now! Every minute we wait here jabberin' is another life on the line! First things first, my friend Sylara is being held captive in the camp just across the road. We need ta free her - she'll be a valuable ally. We've got ta move move move!", ["objectivesText"] = "Collect Dravax's Key from Dravax, then free Sylara Steelsong . Progress: Something need punching?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136406 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 105045, ["x"] = 0.629, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 105045, ["x"] = 0.629, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 105045, ["questType"] = "standard", ["sourceQuests"] = { 41849 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41851] = { ["id"] = 41851, ["name"] = "Quelling the Tide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "<Sylara looks at you with determined eyes.> Our friends are in danger. We will save them. Kill any Legion in the way.", ["objectivesText"] = "Kill 16 Legion defenders at the Gate of Valor. Progress: <Sylara nods at you.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.642, ["y"] = 0.57, ["mapID"] = 634, ["npcID"] = 105088 } }, ["ends"] = { { ["x"] = 0.642, ["y"] = 0.57, ["mapID"] = 634, ["npcID"] = 105088 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.642, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 105088, ["questTurnInID"] = 105088, ["questType"] = "standard", ["sourceQuests"] = { 41850 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41852] = { ["id"] = 41852, ["name"] = "No Monk Left Behind", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["series"] = { 41849, 41850 }, ["description"] = "Most of the prisoners are being held in the main camp at the Gates of Valor. Our people have been beaten and tortured, and worse still awaits for them if we don't save them. Find the cages within the main camp and free as many monks as you can find. I'll be right beside you, knocking heads and taking names!", ["objectivesText"] = "Free 6 Tortured Prisoners. Progress: Did we free them all?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139506, 139738 }, ["starts"] = { { ["x"] = 0.642, ["y"] = 0.57, ["mapID"] = 634, ["npcID"] = 105072 } }, ["ends"] = { { ["x"] = 0.642, ["y"] = 0.57, ["mapID"] = 634, ["npcID"] = 105072 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.642, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 105072, ["questTurnInID"] = 105072, ["questType"] = "standard", ["sourceQuests"] = { 41850 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[41853] = { ["id"] = 41853, ["name"] = "Zero to Hiro", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "I have a favor to ask of you, <name>. My good friend Hiro is still somewhere inside the main camp. Only problem is, the Gates of Valor are swarming with the biggest, baddest, nastiest Legion creatures I've ever seen. If we walk in there, we'll just get slaughtered. But I've seen these vrykul chugging some kind of special brew called Storm Brew . It's some kind of combat tonic that makes them bigger and stronger. Let's steal some of that drink, then storm in to save Hiro !", ["objectivesText"] = "Steal a Storm Brew , then save Hiro .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.642, ["y"] = 0.57, ["mapID"] = 634, ["npcID"] = 105072 } }, ["ends"] = { { ["x"] = 0.642, ["y"] = 0.57, ["mapID"] = 634, ["npcID"] = 105072 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.642, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 105072, ["questTurnInID"] = 105072, ["questType"] = "standard", ["sourceQuests"] = { 41850 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
