[41863] = { ["id"] = 41863, ["name"] = "Vengeance Will Be Ours", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "Caria lies in the very heart of Legion territory - they'll see our forces immediately if we try to launch an all-out attack. Failure is not an option. However, if you go alone you might be able to slip by unnoticed long enough to avoid the brunt of the Legion army. Remember, <name> - this is not a rescue mission. The power of the Aldrachi Warblades could tip the scales of this war in our favor; Allari and her men are expendable if need be.", ["objectivesText"] = "Take the Aldrachi Warblades from Caria Felsoul.", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.749, ["y"] = 0.49, ["mapID"] = 627, ["npcID"] = 99254 } }, ["ends"] = { { ["x"] = 0.749, ["y"] = 0.49, ["mapID"] = 627, ["npcID"] = 99254 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.749, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 99254, ["questTurnInID"] = 99254, ["questType"] = "standard", ["sourceQuests"] = { 41807 }, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
