[41877] = { ["id"] = 41877, ["name"] = "Lady Lunastre", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "Our friend Ly'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city. Have your disguise ready just in case, <name>.", ["objectivesText"] = "Seek out Ly'leth at the Grand Promenade. Progress: Hm?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42230 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41878] = { ["id"] = 41878, ["name"] = "The Gondolier", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I need your help. The wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered. I am dedicated to preventing this for as long as possible. There is a woman by the name of Deline who owns and operates a small delivery service out of her gondola. Find her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.", ["objectivesText"] = "Make contact with the Gondolier. Progress: Unless you want a ride, you should keep moving.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41148 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
