[41882] = { ["id"] = 41882, ["name"] = "Whispers of the Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41840, 41841, 48403 }, ["description"] = "Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into. Our people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own. Wake them from their stupor. Free them from the whispers any way you can.", ["objectivesText"] = "Free 6 Highmountain Protectors .", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 119036 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97662, ["x"] = 0.484, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 41815 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41884] = { ["id"] = 41884, ["name"] = "Dark Tales", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41800, 48185, 48190, 48434, 48435 }, ["description"] = "Spiritwalker Ebonhorn is stable... for now. He once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own. Incapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack. To find the wards, we must enter the echoes of Ebonhorn's past and commune with the spirits we find there. Meet me in Riverbend, <name>. It is there our search begins.", ["objectivesText"] = "Meet Spiritwalker Graysky in Riverbend.", ["rewardGold"] = 312800, ["rewardXP"] = 5465, ["starts"] = { { ["x"] = 0.702, ["y"] = 0.72, ["mapID"] = 650, ["npcID"] = 105085 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 105085, ["questType"] = "standard", ["sourceQuests"] = { 48079 }, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
