[41888] = { ["id"] = 41888, ["name"] = "Allegiance of Flame", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8125, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41773, 41774, 41934 }, ["description"] = "My rivals lay dead and there are none within the Firelands who dare oppose my rule! As promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies! Go now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!", ["objectivesText"] = "Speak with Farseer Nobundo in The Heart of Azeroth. Progress: What news do you bring from the Firelands?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139698, 142059, 142060, 142061, 142062, 142064 }, ["rewardChoices"] = { 142059, 142060, 142061, 142062, 142064 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.492, ["y"] = 0.297, ["mapID"] = 738, ["npcID"] = 105120 } }, ["ends"] = { { ["x"] = 0.492, ["y"] = 0.297, ["mapID"] = 738, ["npcID"] = 105120 } }, ["coords"] = { ["mapID"] = 738, ["x"] = 0.492, ["y"] = 0.297 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questGiverID"] = 105120, ["questTurnInID"] = 105120, ["questType"] = "standard", ["sourceQuests"] = { 41934 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[41889] = { ["id"] = 41889, ["name"] = "Dazed of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40196, 40197 }, ["description"] = "Let's begin crafting this mount armor, shall we?", ["objectivesText"] = "Construct a Stonehide Leather Barding . Progress: I'm quite anxious to see how it turns out.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130887, 130891, 130894, 130895, 130896, 141850 }, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["ends"] = { { ["x"] = 0.354, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 93523 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.354, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93523, ["questTurnInID"] = 93523, ["questType"] = "standard", ["sourceQuests"] = { 40197 }, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41890] = { ["id"] = 41890, ["name"] = "Dark Side of the Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind! These refugees tell of an ancient Moonwell hidden in the ruins ahead. If it is uncorrupted, it will give me the focus I need. By Elune's light, we will find my husband yet. Meet me at the Moonwell at once, <class>.", ["objectivesText"] = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 106175, 107307, 107312, 107317 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104885, ["x"] = 0.668, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6805, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41054 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[41893] = { ["id"] = 41893, ["name"] = "Given to Corruption", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "A final favor for an old friend, perhaps? My age-old companion, Varethos , has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour. As with all who suffer this fate, there is no restoring him. Please, <name>, bring him peace.", ["objectivesText"] = "Slay Keeper Varethos . Progress: Is it done, then?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92783, ["x"] = 0.662, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92783, ["x"] = 0.662, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41724 }, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
