[41897] = { ["id"] = 41897, ["name"] = "The Master's Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41898, 41899, 42065 }, ["description"] = "The purpose of the Twilight's Hammer has always been the same. They seek to bring about the end of the world. Their schemes may change, but their wicked purpose remains constant. Defeating the Twilight's Hammer is not simply a matter of defeating them in battle. If we are to be successful, we will need to uncover their scheme and put an end to whatever terrible plans they have created. Let us start by searching the encampment for clues as to their true purpose here.", ["objectivesText"] = "Collect the excerpts from The Master's Journal. Progress: What vile scheme have the Twilight's Hammer plotted against the world this time?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 136791, 136792, 136793, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.64, ["y"] = 0.705, ["mapID"] = 207, ["npcID"] = 106001 } }, ["ends"] = { { ["x"] = 0.64, ["y"] = 0.705, ["mapID"] = 207, ["npcID"] = 106001 } }, ["coords"] = { ["mapID"] = 207, ["x"] = 0.64, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 106001, ["questTurnInID"] = 106001, ["questType"] = "standard", ["sourceQuests"] = { 42068 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[41898] = { ["id"] = 41898, ["name"] = "Unleashing the Elements", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41897, 41899, 42065 }, ["description"] = "According to The Master's journal, the Twilight's Hammer has discovered a method of harnessing the void to subjugate even the most powerful of elementals. The journal specifically mentioned the children of Therazane as test subjects. Whether The Master was speaking literally or figuratively in this regard, I do not know. Regardless, we need to free these elementals and stop these dark rituals from continuing. It appears that our journey here is going to take us deeper into the depths of darkness...", ["objectivesText"] = "Release the Servants of Therazane from Twilight Depths. Progress: Dark rituals such as these must not be allowed to continue.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["npcID"] = 106001 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 106001, ["questType"] = "standard", ["sourceQuests"] = { 41777, 41897 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[41899] = { ["id"] = 41899, ["name"] = "Held Captive!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41897, 41898, 42065 }, ["description"] = "There are prisoners here, Farseer <name>, that are enslaved by the Twilight's Hammer. The cultists work them to death in the depths of the mine. I cannot abide such cruel mistreatment! Let us clear a path through the mine and rescue any Twilight's Hammer prisoners we find, so that they may return to their homes and families. The Twilight's Hammer will pay for their crimes!", ["objectivesText"] = "Rescue 10 Twilight Slaves from the Twilight Depths. Progress: Have the slaves been rescued?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["npcID"] = 106001 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 106001, ["questType"] = "standard", ["sourceQuests"] = { 41777, 41897 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[41900] = { ["id"] = 41900, ["name"] = "A Promise of Earth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41772, 42208 }, ["description"] = "Deepholm thanks you, shaman. The Twilight's Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts. For your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth. I have no love for the mortal races, but this world is not the Burning Legion's to destroy. Tell your Earthen Ring that Therazane the Stonemother stands with them!", ["objectivesText"] = "Speak with Advisor Sevel in the Heart of Azeroth.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139506, 139705 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questTurnInID"] = 42465, ["questType"] = "standard", ["sourceQuests"] = { 42065 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[41901] = { ["id"] = 41901, ["name"] = "Oath of the Windlord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["mapID"] = 726, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41775, 42068, 42200 }, ["description"] = "You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable. I know that the Earthen Ring seeks to save Azeroth from the Burning Legion. I will pledge my sword, and the armies of Skywall to the aid of Azeroth. When the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.", ["objectivesText"] = "Speak with Advisor Sevel .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 140517, 140932 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.793, ["mapID"] = 737, ["npcID"] = 104788 } }, ["ends"] = { { ["x"] = 0.524, ["y"] = 0.793, ["mapID"] = 737, ["npcID"] = 104788 } }, ["coords"] = { ["mapID"] = 737, ["x"] = 0.524, ["y"] = 0.793 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8093 } }, ["questGiverID"] = 104788, ["questTurnInID"] = 104788, ["questType"] = "standard", ["sourceQuests"] = { 41776 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[41905] = { ["id"] = 41905, ["name"] = "Report from Tian Monastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 42191 }, ["description"] = "We have heard from all our temples on Pandaria, except for one. We dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual. Grandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Investigate Tian Monastery.\" Progress: What have you discovered?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 42191 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41907] = { ["id"] = 41907, ["name"] = "Appropriations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "I have come to lend my help to the Order of the Broken Temple. My job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses. Lao Shu is in charge of our supply inventory. Go and speak with him now in the inn.", ["objectivesText"] = "Speak to Lao Shu in The Laughing Crane inn.", ["rewardGold"] = 23870, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questTurnInID"] = 104744, ["questType"] = "standard", ["sourceQuests"] = { 41733 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41909] = { ["id"] = 41909, ["name"] = "Tracking the Tideskorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off. They've tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we're in danger of losing the trail. I suggest that we send our champions immediately to assist with the tracking effort.", ["objectivesText"] = "Use the Scouting Map and complete the \"Tracking the Tideskorn\" missions. Progress: Did we gather enough information about the Legion forces at the Gates of Valor?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["sourceQuests"] = { 41733 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41910] = { ["id"] = 41910, ["name"] = "Freya's Spring", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "First, we need water from Freya's Spring. Once a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool. Some say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew. I suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.", ["objectivesText"] = "Use the Scouting Map and complete five \"Freya's Spring\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 102843 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 102843, ["questType"] = "standard", ["sourceQuests"] = { 41039 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41911] = { ["id"] = 41911, ["name"] = "Amaranthine Hops", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "The hops for our brew must be a very specific, and they will also be hard to acquire. Amaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid. There is one such supplier from whom I receive this item, but she may ask for something in exchange.", ["objectivesText"] = "Speak to Fleuris Asterleaf in Val'sharah and trade 20 Stonehide Leather for 1 bag of Amaranthine Hops . Progress: Did you find Fleuris?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 139033 }, ["starts"] = { { ["npcID"] = 102996 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 102996, ["questType"] = "standard", ["sourceQuests"] = { 41039 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41914] = { ["id"] = 41914, ["name"] = "Clear the Catacombs", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41914 }, ["objectivesText"] = "Defeat the Catacomb Pests", ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defeat the Catacomb Pests", ["amount"] = 1, ["type"] = 11, ["objectID"] = 105323, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest" },
[41915] = { ["id"] = 41915, ["name"] = "The Master's Legacy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["description"] = "You work for a murderer and a thief. That design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret. I had him entombed in a small cave north of the city, for we could not make the trip to Tel'anor. Buried with him is a tome that contains the secrets of the design. Retrieve the design and keep it out of his hands!", ["objectivesText"] = "Investigate the Gemcutter's Tomb. Progress: Where is the master?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135507, 140248, 247917 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104394, ["x"] = 0.416, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103181, ["x"] = 0.416, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41146 }, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41916] = { ["id"] = 41916, ["name"] = "A Better Future", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "We must move quickly, <name>. I must save as many of my people as I can before the attack begins. Word has gotten out in the city that there is a safe haven with us and some no longer fear exile. Venture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.", ["objectivesText"] = "Rescue 8 Shal'dorei Insurgents in the Grand Promenade. Progress: Each shal'dorei rescued is both a potential enemy vanquished and a new hope for our people.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 208067, 208937, 211366 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.408667, ["y"] = 0.525333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40632 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41918] = { ["id"] = 41918, ["name"] = "The Dreamer Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "Arch Druid Greathoof will be expecting word on the success of our mission, but I'm afraid I must ask you to return alone. I can't rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I'll find where he has been taken if I have to search every corner of Azeroth! Our paths will cross again, <name>. Be sure of it.", ["objectivesText"] = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questTurnInID"] = 104535, ["questType"] = "standard", ["sourceQuests"] = { 40647 }, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["db2QuestSortName"] = "Battle Pets" },
[41919] = { ["id"] = 41919, ["name"] = "The Shadows Reveal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil'Jaeden's personal assassins. Every attempt on her life ends the same... she's gone before we even arrive. <Valeera scrawls a few lines on a piece of paper, then hands it to you.> But not this time. We've been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes. Go to each contact and tell them \"The shadows reveal.\" See what they know.", ["objectivesText"] = "Speak to your contacts in Dalaran to acquire intel on Akaari Shadowgore's whereabouts. Progress: Hmm?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136602, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["x"] = 0.408, ["y"] = 0.754, ["mapID"] = 626, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.408, ["y"] = 0.754, ["mapID"] = 626, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.408, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 40840, 44034, 44375 }, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41920] = { ["id"] = 41920, ["name"] = "A Matter of Finesse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "A rune of portals ?! Who does Val'zuun think he is? <Valeera takes a deep breath.> It's worth the price, but those runes aren't exactly easy to come by. Unless... Archmage Celindra , the Kirin Tor's portal master, has a study in the center of town. We rogues aren't particularly welcome there, nor would she simply hand a rune over even if we were... <Valeera smirks.> But who said anything about asking?", ["objectivesText"] = "Borrow a Rune of Portals from Archmage Celindra . Progress: They say the Fangs of the Devourer have no equal. If that's true, they're worth any price.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 17032, 127837, 128476, 128479, 128870, 128872, 136603, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.704, ["mapID"] = 627, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.704, ["mapID"] = 627, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.516, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 41919 }, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[41921] = { ["id"] = 41921, ["name"] = "Closing In", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "The Legerdemain Lounge isn't far from here. We have agents nearby who can secure the area. Come prepared for a fight. Akaari won't go down easily.", ["objectivesText"] = "Confront Akaari Shadowgore in the Legerdemain Lounge. Progress: I can't believe it...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 66933, 66934, 66935, 127837, 128476, 128479, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 195196, 195197 }, ["starts"] = { { ["x"] = 0.679, ["y"] = 0.631, ["mapID"] = 628, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.679, ["y"] = 0.631, ["mapID"] = 628, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.679, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 41920 }, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
