[41945] = { ["id"] = 41945, ["name"] = "Tianji of the Ox", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked. I suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Tianji Needs Help\". Progress: How is the mission proceeding?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.527, ["y"] = 0.596, ["mapID"] = 709, ["npcID"] = 99179 } }, ["ends"] = { { ["x"] = 0.527, ["y"] = 0.596, ["mapID"] = 709, ["npcID"] = 99179 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.527, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 99179, ["questTurnInID"] = 99179, ["questType"] = "standard", ["sourceQuests"] = { 40704, 41115 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[41946] = { ["id"] = 41946, ["name"] = "Building Our Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox. She is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils. Speak to her now and train an initiate of the ox.", ["objectivesText"] = "Speak to Recruiter Tianji and train an Ox Initiate. Progress: How did the training go?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.596, ["mapID"] = 709, ["npcID"] = 99179 } }, ["ends"] = { { ["x"] = 0.528, ["y"] = 0.596, ["mapID"] = 709, ["npcID"] = 99179 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.528, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 99179, ["questTurnInID"] = 99179, ["questType"] = "standard", ["sourceQuests"] = { 41945 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
