[41957] = { ["id"] = 41957, ["name"] = "The Vindicator's Plea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "I've obtained a request from Vindicator Boros in Dalaran asking for our help. He has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T'uure in his delirium! I thought the holy gem was lost! You are strong with the Light, perhaps you can succeed where they can't? If you need it, Brother Larry can provide you with a flight to Dalaran.", ["objectivesText"] = "Meet with Vindicator Boros in front of First to Your Aid in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questTurnInID"] = 101314, ["questType"] = "standard", ["sourceQuests"] = { 40706 }, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
