[41966] = { ["id"] = 41966, ["name"] = "House Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "I thought Barrem was lost to us after the tragedy at Broken Shore, Light knows we lost far too many good soldiers just like him there. I was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser draenei. There is something about those wounds that resists everything we've done to treat them. Please, <class>, as a brother in the Light I ask you to do all that you can to help him to recover.", ["objectivesText"] = "Treat the wounds of Defender Barrem .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 173379 }, ["starts"] = { { ["x"] = 0.377, ["y"] = 0.367, ["mapID"] = 627, ["npcID"] = 105602 } }, ["ends"] = { { ["x"] = 0.377, ["y"] = 0.367, ["mapID"] = 627, ["npcID"] = 105602 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.377, ["y"] = 0.367 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105602, ["questTurnInID"] = 105602, ["questType"] = "standard", ["sourceQuests"] = { 41957 }, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[41967] = { ["id"] = 41967, ["name"] = "Out of the Darkness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "Alora and I were were able to escape through one of the Legion's portals back to Azeroth but that's about as far as our luck got us. The portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora ... she tripped and I watched them drag her back. Rescue her, please! I'll mark where the camp is on your map, just don't let her go through that ordeal again.", ["objectivesText"] = "Travel to Darkstone Isle near the Broken Shore and search for Alora .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 25549, 26010, 26024, 26036, 38734, 39033, 39060, 39098, 42846, 42861, 42870, 42881, 42895, 44018, 44039, 44041, 44042, 44043, 62849, 62850, 62851, 64594, 64604, 64613, 64620, 64625, 64629, 64632, 64634, 65623, 65631, 65632, 65641, 65644, 65645, 65646, 65647, 65648, 65813, 65814, 84060, 84061, 84062, 84063, 84064, 98133, 113169, 113170, 113171, 113172, 113173, 113174, 113175, 113176, 119036, 128825, 128827, 128868, 131271, 131640, 139506, 139757, 139759, 140517, 140930, 151493, 157013, 169905, 171354, 171355, 174288, 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184165, 184378, 184381, 184382, 184383, 184384, 184519, 237890, 237893, 245345, 246951, 257143, 263282, 263461, 265106, 265631 }, ["starts"] = { { ["x"] = 0.375, ["y"] = 0.355, ["mapID"] = 627, ["npcID"] = 105603 } }, ["ends"] = { 