[41989] = { ["id"] = 41989, ["name"] = "Blood of My Blood", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["description"] = "As my darling has demonstrated, Elisande's decision to bring down the shield has sown unrest among the nightborne. Loyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family. I will help Thalyssra stir a new rebellion, but first we must deal with Anarys. I do not wish to spill the blood of my blood - only to help see reason. Anarys is likely brooding over our father's memorial. Bring to me alive.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141947 }, ["starts"] = { { ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788, ["mapID"] = 680 } }, ["ends"] = { { ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788, ["mapID"] = 680 } }, ["coords"] = { ["x"] = 0.434, ["y"] = 0.788, ["source"] = "quest_giver", ["mapID"] = 680 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41834 }, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } } },
