[41993] = { ["id"] = 41993, ["name"] = "Salvation From On High", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T'uure! All my life I've heard stories about how T'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man'ari. We must get it back and restore it to its pure form!", ["objectivesText"] = "Something unexpected has interrupted your discussion, deal with it!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 105684, ["x"] = 0.34, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 106011, ["x"] = 0.330667, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 41967 }, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
