[42000] = { ["id"] = 42000, ["name"] = "Seeker of Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 23, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["series"] = { 42002 }, ["description"] = "You may be familiar with Orik Trueheart . He has devoted his time after the Northrend campaign to learning more about Tyr. Orik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out. Please speak to him immediately.", ["objectivesText"] = "Speak with Orik Trueheart in Dalaran. Progress: I'm glad yer in. We've quite the journey ahead.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 90369, ["questType"] = "standard", ["sourceQuests"] = { 40408, 44063, 44370 }, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42001] = { ["id"] = 42001, ["name"] = "Aluneth, Greatstaff of the Magna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 627, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42003, 42006, 42007, 42008, 42009, 42010, 42011 }, ["description"] = "Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic. When Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken. The dragon Kalec may be our best chance. He now resides on the Council of Six.", ["objectivesText"] = "Meet Kalec at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 136694 }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.381, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.553, ["y"] = 0.381, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.553, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 41085, 43441, 44310 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42002] = { ["id"] = 42002, ["name"] = "To Northrend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 117, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["series"] = { 42000 }, ["description"] = "Naturally I've done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord. Tahu can help locate the grave, and with a short ritual we should have our answers! Meet us at Shield Hill in the Howling Fjord and we'll move on to the next step.", ["objectivesText"] = "Meet Orik Trueheart on Shield Hill in Howling Fjord.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 89125, 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.726, ["y"] = 0.498, ["mapID"] = 627, ["npcID"] = 105689 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 105724, ["x"] = 0.568, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 7502 } }, ["questGiverID"] = 105689, ["questType"] = "standard", ["sourceQuests"] = { 42000 }, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 117 },
[42003] = { ["id"] = 42003, ["name"] = "Kept Secret, Kept Safe", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 42003 }, ["series"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["description"] = "With the scrolls in hand, now you must set to the task of finding the staff. When Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it. The dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.", ["objectivesText"] = "Meet Kalec at the Violet Citadel in Dalaran.", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
