[42005] = { ["id"] = 42005, ["name"] = "The End of the Saga", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["description"] = "Ye should read the saga yerself, it's right here. We're here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak. You should speak with Tahu so we can get started.", ["objectivesText"] = "Get the end of the story from the spirit of the saga hero.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 136710, 139506, 139690, 139693, 139697, 140192, 140517, 140929 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 105724, ["x"] = 0.568, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 105724, ["x"] = 0.568, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questTurnInID"] = 105724, ["questType"] = "standard", ["sourceQuests"] = { 42002 }, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42006] = { ["id"] = 42006, ["name"] = "A New Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 115, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42007, 42008, 42009, 42010, 42011 }, ["description"] = "If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding. During my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos' plans during the Nexus War, whatever is there may explain the current state of the Nexus. Here, take this image crystal. I must remain in Dalaran on Kirin Tor business, so we will speak through it. Good luck.", ["objectivesText"] = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus. Progress: The communication device is inactive.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 128868, 136410 }, ["starts"] = { { ["x"] = 0.286, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["ends"] = { { ["x"] = 0.286, ["y"] = 0.499, ["mapID"] = 627, ["npcID"] = 105081 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.286, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105081, ["questTurnInID"] = 105081, ["questType"] = "standard", ["sourceQuests"] = { 42001 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[42007] = { ["id"] = 42007, ["name"] = "A Forgotten Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42008, 42009, 42010, 42011 }, ["description"] = "The device still hums with power. It must have been abandoned not long ago. The nearby switch appears to activate it.", ["objectivesText"] = "Activate the Ethereal Communication Device at the Azure Dragonshrine.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862 }, ["starts"] = { { ["x"] = 0.567, ["y"] = 0.691, ["mapID"] = 115, ["objectID"] = 248398 } }, ["ends"] = { { ["x"] = 0.567, ["y"] = 0.691, ["mapID"] = 115, ["objectID"] = 248398 } }, ["coords"] = { ["mapID"] = 115, ["x"] = 0.567, ["y"] = 0.691 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard", ["sourceQuests"] = { 42006 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[42008] = { ["id"] = 42008, ["name"] = "Eyes of the Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 114, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42007, 42009, 42010, 42011 }, ["description"] = "You should travel at once to Coldarra in Borean Tundra, <name>. There, I would recommend you scout out a few key locations and report back to me. I know the area well, and should be able to tell you how to proceed. Make haste!", ["objectivesText"] = "Scout out the key locations in Coldarra.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 136410, 173430, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["x"] = 0.566, ["y"] = 0.691, ["mapID"] = 115, ["npcID"] = 105917 } }, ["ends"] = { { ["x"] = 0.566, ["y"] = 0.691, ["mapID"] = 115, ["npcID"] = 105917 } }, ["coords"] = { ["mapID"] = 115, ["x"] = 0.566, ["y"] = 0.691 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105917, ["questTurnInID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 42007 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114 },
[42009] = { ["id"] = 42009, ["name"] = "Harnessing the Arcane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 114, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42007, 42008, 42010, 42011 }, ["description"] = "The energy from Aluneth lashes out from within the weakened Nexus Vault. We may be able to use this raw, chaotic energy to our advantage. If we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", ["objectivesText"] = "Empower yourself with Unstable Arcane Energy by defeating Arcane Aberrants or siphoning from Breaches of Arcane Energy around the foundation of the Nexus.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 136410 }, ["starts"] = { { ["x"] = 0.278, ["y"] = 0.267, ["mapID"] = 114, ["npcID"] = 105917 } }, ["ends"] = { { ["x"] = 0.278, ["y"] = 0.267, ["mapID"] = 114, ["npcID"] = 105917 } }, ["coords"] = { ["mapID"] = 114, ["x"] = 0.278, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105917, ["questTurnInID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 42008 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114 },
[42010] = { ["id"] = 42010, ["name"] = "Arcane Unleashed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["description"] = "You have the power you need to destroy the Surge Needles. At the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above. You must act quickly. The Ethereum won't sit idly by as you lay waste to their machinations.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.278, ["y"] = 0.267, ["mapID"] = 114, ["npcID"] = 105917 } }, ["ends"] = { { ["x"] = 0.278, ["y"] = 0.267, ["mapID"] = 114, ["npcID"] = 105917 } }, ["coords"] = { ["mapID"] = 114, ["x"] = 0.278, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105917, ["questTurnInID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 42009 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } } },
[42011] = { ["id"] = 42011, ["name"] = "The Nexus Vault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42007, 42008, 42009, 42010 }, ["description"] = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. We have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip. With the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, <name>.", ["objectivesText"] = "Defeat Nexus-Prince Bilaal and claim Aluneth, Greatstaff of the Magna.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 113509, 118006, 127834, 127857, 128820, 128862, 136410, 141446 }, ["starts"] = { { ["x"] = 0.278, ["y"] = 0.267, ["mapID"] = 114, ["npcID"] = 105917 } }, ["ends"] = { { ["x"] = 0.278, ["y"] = 0.267, ["mapID"] = 114, ["npcID"] = 105917 } }, ["coords"] = { ["mapID"] = 114, ["x"] = 0.278, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 105917, ["questTurnInID"] = 105917, ["questType"] = "standard", ["sourceQuests"] = { 42010 }, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
