[42032] = { ["id"] = 42032, ["name"] = "Sampling the Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42031, 42033 }, ["description"] = "There is still so much that we don't know about the Nightmare. Before we can fight it, we must understand how it spreads. Let us send our champions to the roots of Shaladrassil in Val'sharah, and ask them to bring back samples to study.", ["objectivesText"] = "Complete the mission, \"Sampling the Nightmare.\"", ["rewardGold"] = 151650, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 42588 }, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42033] = { ["id"] = 42033, ["name"] = "Malorne's Refuge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42031, 42032 }, ["description"] = "I see... it is as we have always feared. The Emerald Nightmare has found our world. We must call upon the ancient god, Malorne. Travel southeast to the shrine at Malorne's Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself. I already sent Broll Bearmantle ahead to give word of your arrival.", ["objectivesText"] = "Speak to Broll Bearmantle at Malorne's Refuge in Val'sharah.", ["rewardGold"] = 9470, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 105903, ["x"] = 0.57, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 42031 }, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42034] = { ["id"] = 42034, ["name"] = "Grip of Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42035 }, ["description"] = "Most of the druids were able to escape, but the shrine is still swarming with enemies. The shrine's leader, Sylendra Gladesong, stayed behind to recover Malorne's Idol. We must go back and help her.", ["objectivesText"] = "Kill 5 Darkfiend Raiders , rescue Sylendra Gladesong , and examine the Altar of Malorne.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 105903, ["x"] = 0.57, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 105948, ["x"] = 0.569333, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42033 }, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42035] = { ["id"] = 42035, ["name"] = "Tracking the Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42034 }, ["description"] = "The Idol may be stolen, but there is still hope. While I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh. With our heightened senses, we may still be able to pick up their trail. We must follow their signs through the forest and recover the Idol!", ["objectivesText"] = "Use your Cat Form to follow the satyr's tracks.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 105948, ["x"] = 0.569333, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 106883, ["x"] = 0.598, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.569333, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42034 }, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42036] = { ["id"] = 42036, ["name"] = "Idol of the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["description"] = "We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere. Surely one of these satyrs will know where it was taken. Get the information out of these satyrs, even if it's the last thing they do.", ["objectivesText"] = "Attack 6 Darkfiend Satyr and extract information about the Idol of the Wilds . Progress: Did you recover the Idol of the Wilds ?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 97919, 136804, 137663, 140517, 140925 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 106883, ["x"] = 0.598, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 106883, ["x"] = 0.598, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 106883, ["questType"] = "standard", ["sourceQuests"] = { 42035 }, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42037] = { ["id"] = 42037, ["name"] = "Gathering the Dreamweavers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Now that you've recovered the Idol of the Wilds, it's time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids. Send your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.", ["objectivesText"] = "Retrieve druids by completing \"Gathering the Dreamweavers\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 42036, 42038, 42039 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
