[42040] = { ["id"] = 42040, ["name"] = "The Way to Nordrassil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "The time has come for us to use the Idol of the Wilds and commune with Malorne. The ritual will require a great deal of power, so we have decided to convene at Nordrassil and draw upon the World Tree's essence. There is no time to waste. The fastest path will be through the Emerald Dreamway. Go ahead, and we will follow.", ["objectivesText"] = "Speak to Archdruid Hamuul Runetotem in the Emerald Dreamway.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.446, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 103832, ["questTurnInID"] = 103832, ["questType"] = "standard", ["sourceQuests"] = { 42037, 43991 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42041] = { ["id"] = 42041, ["name"] = "Enduring the Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "We are under attack here, <name>! Creatures of the Nightmare are spilling into the Dreamway as we speak. Destroy them. They cannot be allowed to linger, or else the Nightmare will take root here, too!", ["objectivesText"] = "Kill 12 aberrations of Nightmare. Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106204 } }, ["ends"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106204 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.434, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 106204, ["questTurnInID"] = 106204, ["questType"] = "standard", ["sourceQuests"] = { 42040 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
[42042] = { ["id"] = 42042, ["name"] = "Teensy Weensies!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Oh <name>, I'm so very very happy to see you! The woodland critters whispered there was trouble in the Dreamway so I came immediately! There are so very many teensy weensy little creatures that live here in the Emerald Dream, and they're out there, all lost and alone! Would you go out there and gather them up? You can use my flute to call them to you. Thank you, brave druid!", ["objectivesText"] = "Use Mylune's Flute to gather 15 Teensy Weensy Fae Dragons . Progress: Ohhh, the teensy weensy fae dragons are so cute! Are they all right?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136840 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.323, ["mapID"] = 715, ["npcID"] = 106136 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.323, ["mapID"] = 715, ["npcID"] = 106136 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.45, ["y"] = 0.323 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 106136, ["questTurnInID"] = 106136, ["questType"] = "standard", ["sourceQuests"] = { 42040 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
[42043] = { ["id"] = 42043, ["name"] = "Cleaning Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "When the Nightmare spreads, it consumes the life force of all that it touches. The more it spreads, the weaker our magic becomes. In its early stages, before the taint has taken hold, we can still cleanse the affected areas. I will bless you with Elune's grace. By channeling her power, you can reverse the Nightmare's spread.", ["objectivesText"] = "Cleanse 100 Nightmare Creep. Progress: Did you restore the Dream?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 37275, 37351, 37443, 37478, 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750, 119001, 155237, 160384, 160387, 160390, 160393 }, ["starts"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106135 } }, ["ends"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106135 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.434, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 106135, ["questTurnInID"] = 106135, ["questType"] = "standard", ["sourceQuests"] = { 42040 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
[42044] = { ["id"] = 42044, ["name"] = "A Dying Dream", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Deep in the heart of the swamp lies an ancient protector of the Dreamway, Witherheart . He was among the first defenders to battle against the Nightmare, but he has fallen to total corruption. It pains me to say it, but we must destroy him.", ["objectivesText"] = "Kill Witherheart . Progress: No one is safe from the Nightmare.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106204 } }, ["ends"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106204 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.434, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 106204, ["questTurnInID"] = 106204, ["questType"] = "standard", ["sourceQuests"] = { 42041, 42042, 42043 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
[42045] = { ["id"] = 42045, ["name"] = "Communing With Malorne", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 198, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Our work here is done, <name>. We have successfully defended the Dreamway. It will be only a matter of time before it is restored to its former state. But we have more important matters at hand. Take the Idol of the Wilds and go onward to Nordrassil. With any luck, they have already gathered. We will meet you there.", ["objectivesText"] = "Speak to Remulos at Nordrassil. Progress: I am glad to see you, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.434, ["y"] = 0.306, ["mapID"] = 715, ["npcID"] = 106204 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 106250, ["x"] = 0.604667, ["y"] = 0.235333 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.235333 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 7979 } }, ["questGiverID"] = 106204, ["questType"] = "standard", ["sourceQuests"] = { 42044 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198 },
[42046] = { ["id"] = 42046, ["name"] = "A New Beginning", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "If Malorne is in danger, then things are even worse than I feared. It truly is up to us now. We have very little time left. Let us reconvene in the Dreamgrove at once.", ["objectivesText"] = "Meet Archdruid Rensar Greathoof at the Dreamgrove in Val'sharah.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 139506, 139730, 141393, 211873 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 106250, ["x"] = 0.604667, ["y"] = 0.235333 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 106250, ["x"] = 0.604667, ["y"] = 0.235333 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.235333 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questTurnInID"] = 106250, ["questType"] = "standard", ["sourceQuests"] = { 42045 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["db2QuestSortName"] = "Engine of Innovation" },
