[42049] = { ["id"] = 42049, ["name"] = "Powering the Portal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "If Malorne is trapped in the Nightmare, we must try to save him. It may sound like a fool's errand, but we cannot sit by idly. There is an abandoned portal within the Emerald Dreamway, one that we druids closed long ago because it leads to the Rift of Aln. To infuse it with energy once again, we will need shards of Nightmare which can be found on satyr lieutenants. Send our champions to hunt and kill these enemies.", ["objectivesText"] = "Collect 10 Shards of Nightmare from \"Powering the Portal\" missions. Progress: How many shards have we collected?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137119, 143742, 153006, 156630 }, ["starts"] = { { ["x"] = 0.449, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["ends"] = { { ["x"] = 0.449, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.449, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 103832, ["questTurnInID"] = 103832, ["questType"] = "standard", ["sourceQuests"] = { 42046, 42047, 42048 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42050] = { ["id"] = 42050, ["name"] = "Defenders of the Dream", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8180, ["mapID"] = 760, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "Never has our order faced such a difficult challenge. To succeed, we must rely on each other's strengths. However, we only have a few defenders to spare for the battle ahead. Broll, Sylendra, Zen'tabra, and Mylune have all volunteered to accompany you into the valley below, but I can only spare one. Which one will you choose to aid you in battle?", ["objectivesText"] = "Choose an ally. Progress: Have you chosen?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.612, ["y"] = 0.652, ["mapID"] = 760, ["npcID"] = 107163 } }, ["ends"] = { { ["x"] = 0.612, ["y"] = 0.652, ["mapID"] = 760, ["npcID"] = 107163 } }, ["coords"] = { ["mapID"] = 760, ["x"] = 0.612, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8180 } }, ["questGiverID"] = 107163, ["questTurnInID"] = 107163, ["questType"] = "standard", ["sourceQuests"] = { 42051 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1608, ["db2PoiUiMapID"] = 760 },
[42051] = { ["id"] = 42051, ["name"] = "Enter Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 760, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "The portal to the nightmare is ready, <name>. Remulos and the others have already gone ahead. There is no telling what horrors await on the other side, <name>. Good luck.", ["objectivesText"] = "Go through the Nightmare Portal in the Emerald Dreamway.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 141548, 141549, 141550, 141551 }, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.447, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 42049, 42365, 43403, 91614 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1608, ["db2PoiUiMapID"] = 760 },
[42052] = { ["id"] = 42052, ["name"] = "The Shade of Xavius", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7673, ["mapID"] = 641, ["storyline"] = { 42052 }, ["description"] = "Brightwing loves nice things - rainbows, unicorns, and flowers! But enemies, Brightwing does not forget. Brightwing remembers for a long, long time those that hurt the grove. Now, we must destroy our enemies... so that the grove can be nice and happy forever! Friend, go to Darkheart Thicket beneath the roots of Shaladrassil. There, find the one named Xavius... the one who started it all. Kill him, and bring me his head.", ["objectivesText"] = "Retrieve the Fragment of Xavius from the Shade of Xavius in Darkheart Thicket.", ["rewardGold"] = 154000, ["rewardXP"] = 200, ["rewardItems"] = { 137268 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7673 } }, ["questType"] = "dungeon" },
[42053] = { ["id"] = 42053, ["name"] = "The War of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8180, ["mapID"] = 760, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "To free Malorne, we must win the War of the Ancients. A millennia ago, this battle took the combined efforts of the greatest defenders of our world. To win now, we must do the same. Go upon the battlefield and defeat Legion foes, rescue and revive our allies, and free the innocent who have been caught in the battle. Every enemy defeated and every ally saved will help turn the tide in our favor!", ["objectivesText"] = "Win the War of the Ancients.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.614, ["y"] = 0.656, ["mapID"] = 760, ["npcID"] = 107132 } }, ["ends"] = { { ["x"] = 0.614, ["y"] = 0.656, ["mapID"] = 760, ["npcID"] = 107132 } }, ["coords"] = { ["mapID"] = 760, ["x"] = 0.614, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8180 } }, ["questGiverID"] = 107132, ["questTurnInID"] = 107132, ["questType"] = "standard", ["sourceQuests"] = { 42050 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1608, ["db2PoiUiMapID"] = 760 },
[42054] = { ["id"] = 42054, ["name"] = "Archimonde, The Defiler", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8180, ["mapID"] = 760, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "We have turned the battle, <name>! The Burning Legion is greatly weakened. Only one task remains. Malorne is locked in battle with Archimonde , the demon that slew him ten thousand years ago. Remember, <name>, we are trapped in Malorne 's nightmare. There is no telling what will manifest here, but we MUST do something. May Elune guide us, <name>.", ["objectivesText"] = "Defeat Archimonde .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.656, ["mapID"] = 760, ["npcID"] = 107132 } }, ["ends"] = { { ["x"] = 0.616, ["y"] = 0.656, ["mapID"] = 760, ["npcID"] = 107132 } }, ["coords"] = { ["mapID"] = 760, ["x"] = 0.616, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8180 } }, ["questGiverID"] = 107132, ["questTurnInID"] = 107132, ["questType"] = "standard", ["sourceQuests"] = { 42053 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1608, ["db2PoiUiMapID"] = 760 },
[42055] = { ["id"] = 42055, ["name"] = "The Demi-God's Return", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8180, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "< Malorne 's voice echoes in your mind.> Mortal you may be, but your valor is worthy of the ancient gods. Nature's spirit lives in you - vibrant, wild, and ferocious. I witness in you the essence of nature's spark - the WILL to survive. Our triumph here will be spoken of for ages to come, <name>. Return to the waking world through this portal. We will speak again when we return to the Dreamgrove.", ["objectivesText"] = "Receive Malorne 's blessing. Progress: Nature's cycle is beautiful, but it can be frail. We must preserve its balance.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 128306, 139506, 139723, 142056, 142057, 142059, 142060, 142062 }, ["rewardChoices"] = { 142056, 142057, 142059, 142060, 142062 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.661, ["y"] = 0.668, ["mapID"] = 760, ["npcID"] = 106905 } }, ["ends"] = { { ["x"] = 0.661, ["y"] = 0.668, ["mapID"] = 760, ["npcID"] = 106905 } }, ["coords"] = { ["mapID"] = 760, ["x"] = 0.661, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8180 } }, ["questGiverID"] = 106905, ["questTurnInID"] = 106905, ["questType"] = "standard", ["sourceQuests"] = { 42054 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
