[42065] = { ["id"] = 42065, ["name"] = "The Twilight Master", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41897, 41898, 41899 }, ["description"] = "There is only one more thing that remains, Farseer <name>. We must confront the leader of the Twilight's Hammer and put an end to their sinister plot once and for all. Without their so-called master, the remaining cultists will be forced to retreat from Deepholm. Only when The Twilight's Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.", ["objectivesText"] = "Defeat the Mistress of Twilight .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["npcID"] = 106001 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questGiverID"] = 106001, ["questType"] = "standard", ["sourceQuests"] = { 41898, 41899 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
