[42068] = { ["id"] = 42068, ["name"] = "The Return of Twilight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41775, 41901, 42200 }, ["description"] = "The Twilight's Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly. I cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it. Go. Uncover the plot that the Twilight's Hammer is hatching and put an end to their scheme!", ["objectivesText"] = "Speak with Muln Earthfury in Deepholm.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 105995, ["x"] = 0.614667, ["y"] = 0.512667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 41775 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
