[42097] = { ["id"] = 42097, ["name"] = "Searching the Archives", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["description"] = "The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. It's reasonable to think that somewhere among the countless scrolls that we'll find something to aid us in our mission to rescue the remaining council members. The search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.", ["objectivesText"] = "Interact with the Dreadscar Battle Plans and complete the mission \"Searching the Archives\". Progress: Have the archives been searched yet?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.656, ["y"] = 0.472, ["mapID"] = 717, ["npcID"] = 104795 } }, ["ends"] = { { ["x"] = 0.656, ["y"] = 0.472, ["mapID"] = 717, ["npcID"] = 104795 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.656, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 104795, ["questTurnInID"] = 104795, ["questType"] = "standard", ["sourceQuests"] = { 42601 }, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[42098] = { ["id"] = 42098, ["name"] = "Black Rook Hold: An Unclaimed Soul", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["description"] = "In order to create the anchor, we'll need to link something of Shinfel's to an unclaimed soul . The soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift. Shinfel's staff should provide us with the link we need, but the soul will be a bit harder to find. Dwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.", ["objectivesText"] = "Collect an Unclaimed Soul from The Amalgam of Souls in the Black Rook Hold dungeon. Progress: Have you recovered the soul yet?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128941, 128942, 128943, 138988, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.552, ["y"] = 0.37, ["mapID"] = 717, ["npcID"] = 105018 } }, ["ends"] = { { ["x"] = 0.552, ["y"] = 0.37, ["mapID"] = 717, ["npcID"] = 105018 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.552, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 105018, ["questTurnInID"] = 105018, ["questType"] = "dungeon", ["sourceQuests"] = { 41752, 41753 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[42100] = { ["id"] = 42100, ["name"] = "Empowering the Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["description"] = "Creating the anchor will require more power than our soul shards will be able to provide. Dreadscar's troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.", ["objectivesText"] = "Collect Empowered Soul Shards by completing class hall missions. Progress: With enough soul shards, we should have the power to create the anchor.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 136834 }, ["starts"] = { { ["x"] = 0.552, ["y"] = 0.37, ["mapID"] = 717, ["npcID"] = 105018 } }, ["ends"] = { { ["x"] = 0.552, ["y"] = 0.37, ["mapID"] = 717, ["npcID"] = 105018 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.552, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 105018, ["questTurnInID"] = 105018, ["questType"] = "standard", ["sourceQuests"] = { 41752, 41753 }, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
