[42103] = { ["id"] = 42103, ["name"] = "Let it Feed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["description"] = "We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we'll need to feed it. The stone grows in power when consuming the blood of demons. Luckily for us, there's no shortage of demons to kill.", ["objectivesText"] = "Kill demons throughout the Broken Isles and collect their blood. Progress: We will need to feed the Bloodstone before it will be strong enough to control the eredar sisters.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 128941, 128942, 128943, 138991, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.541, ["y"] = 0.349, ["mapID"] = 717, ["npcID"] = 104732 } }, ["ends"] = { { ["x"] = 0.541, ["y"] = 0.349, ["mapID"] = 717, ["npcID"] = 104732 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.541, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 104732, ["questTurnInID"] = 104732, ["questType"] = "standard", ["sourceQuests"] = { 41751 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
