[42114] = { ["id"] = 42114, ["name"] = "The Ritual of Tides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 42188 }, ["description"] = "Long ago, the first Farseer of the Earthen Ring was given a vision of the elements. In the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements. <name>, I believe that you are the Farseer of this prophecy, called to lead before you were ever born. The time has come to fulfill your destiny! When you are ready, we will perform the Ritual of Tides and call upon Neptulon , the first of the four great Elemental Lords.", ["objectivesText"] = "Perform the Ritual of Tides in the Maelstrom. Progress: The time has come to fulfill your destiny, Farseer <name>.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.341, ["y"] = 0.314, ["mapID"] = 726, ["npcID"] = 96528 } }, ["ends"] = { { ["x"] = 0.341, ["y"] = 0.314, ["mapID"] = 726, ["npcID"] = 96528 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.341, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96528, ["questTurnInID"] = 96528, ["questType"] = "standard", ["sourceQuests"] = { 42188 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
