[42120] = { ["id"] = 42120, ["name"] = "The Silver Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42120, 42231, 42377 }, ["series"] = { 42377 }, ["description"] = "Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer. Tyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I'm glad we'll have you with us. Take the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I've marked the location on your map.", ["objectivesText"] = "Go to Tyr's Fall in Tirisfal Glades and recover the Silver Hand . Progress: At last it is done.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 173523 }, ["starts"] = { { ["x"] = 0.72, ["y"] = 0.493, ["mapID"] = 627, ["npcID"] = 106337 } }, ["ends"] = { { ["x"] = 0.72, ["y"] = 0.493, ["mapID"] = 627, ["npcID"] = 106337 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.72, ["y"] = 0.493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 106337, ["questTurnInID"] = 106337, ["questType"] = "standard", ["sourceQuests"] = { 42377 }, ["questLines"] = { { ["id"] = 222, ["name"] = "The Silver Hand", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 222, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
