[42125] = { ["id"] = 42125, ["name"] = "Dark Whispers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 717, ["storyline"] = { 42125, 42168 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in! There is a portal that my kind use to haul in treasures, with it you can get in and find the skull!", ["objectivesText"] = "Use Calydus 's portal to enter into Felsoul Hold and recover the Skull of the Man'ari.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.54, ["y"] = 0.47, ["mapID"] = 627, ["npcID"] = 106610 } }, ["ends"] = { { ["x"] = 0.54, ["y"] = 0.47, ["mapID"] = 627, ["npcID"] = 106610 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.54, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 106610, ["questTurnInID"] = 106610, ["questType"] = "standard", ["sourceQuests"] = { 42168 }, ["questLines"] = { { ["id"] = 245, ["name"] = "Skull of the Man'ari", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 245, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[42126] = { ["id"] = 42126, ["name"] = "Archmage Omniara", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42127, 42175, 42663, 42687, 42696, 42703 }, ["description"] = "Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked. Send Archmage Kalecgos to help her. He will be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Omniara Needs Help\" Progress: How is the mission proceeding?", ["rewardGold"] = 74100, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.808, ["y"] = 0.631, ["mapID"] = 734, ["npcID"] = 108515 } }, ["ends"] = { { ["x"] = 0.808, ["y"] = 0.631, ["mapID"] = 734, ["npcID"] = 108515 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.808, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108515, ["questTurnInID"] = 108515, ["questType"] = "standard", ["sourceQuests"] = { 42703 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42127] = { ["id"] = 42127, ["name"] = "Building Our Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42126, 42175, 42663, 42687, 42696, 42703 }, ["description"] = "Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order. She is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us. Speak to her now, and recruit her elementals.", ["objectivesText"] = "Speak to Archmage Omniara and recruit some of her Water Elementals Progress: How did the training go?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.808, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["ends"] = { { ["x"] = 0.808, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.808, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108515, ["questTurnInID"] = 108515, ["questType"] = "standard", ["sourceQuests"] = { 42126 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42128] = { ["id"] = 42128, ["name"] = "Ritual Reagents", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42128 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42168, 42939, 42952, 43181 }, ["description"] = "The Skull of the Man'ari, oh good choice! It's very powerful and it's held by an even more powerful Dreadlord! There is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead! We will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst. Oh, and blood! I sense a beast whose blood should be perfect.", ["objectivesText"] = "Search within Dalaran for Grave Dust , a Can of Overheated Oil , an Aged Snowplum Brandy , and a Stag Blood Sample . Progress: Did you obtain everything, friend?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 136983, 136985, 136986, 136987, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.564, ["y"] = 0.646, ["mapID"] = 628, ["npcID"] = 101097 } }, ["ends"] = { { ["x"] = 0.564, ["y"] = 0.646, ["mapID"] = 628, ["npcID"] = 101097 } }, ["coords"] = { ["mapID"] = 628, ["x"] = 0.564, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101097, ["questTurnInID"] = 101097, ["questType"] = "standard", ["sourceQuests"] = { 40684, 43984, 44089 }, ["questLines"] = { { ["id"] = 245, ["name"] = "Skull of the Man'ari", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 245, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[42129] = { ["id"] = 42129, ["name"] = "The Pendant of Starlight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "To finish my work here, I will need a magical item called the Pendant of Starlight . For centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it! This pendant stores a great amount of arcane power... power I can use to heal the grove. Get it back, and I will be very grateful!", ["objectivesText"] = "Retrieve the Pendant of Starlight from Abyssal Queen Sha'rathra, who patrols along the coast of Val'sharah. Progress: Was there much killing?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 15885, 139374 }, ["starts"] = { { ["x"] = 0.396, ["y"] = 0.455, ["mapID"] = 715, ["npcID"] = 98008 } }, ["ends"] = { { ["x"] = 0.396, ["y"] = 0.455, ["mapID"] = 715, ["npcID"] = 98008 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.396, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 98008, ["questTurnInID"] = 98008, ["questType"] = "standard", ["sourceQuests"] = { 42045 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 17, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
[42131] = { ["id"] = 42131, ["name"] = "Unexpected Visitors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "Brace yourself, <name>. I am detecting a strange magic forming in the chamber. Something is projecting itself in.", ["objectivesText"] = "Listen to your unexpected visitors. Progress: Caria and Varedis Felsoul are like a bad copper piece that keeps coming back.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 140924 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.595, ["y"] = 0.506, ["mapID"] = 720, ["npcID"] = 98632 } }, ["ends"] = { { ["x"] = 0.595, ["y"] = 0.506, ["mapID"] = 720, ["npcID"] = 98632 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.595, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98632, ["questTurnInID"] = 98632, ["questType"] = "standard", ["sourceQuests"] = { 39741, 42665 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42132] = { ["id"] = 42132, ["name"] = "Last, But Not Least", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42809, 42920, 43186 }, ["description"] = "I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions. The two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.", ["objectivesText"] = "Recruit Allari the Souleater and Jace Darkweaver as your champions.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.593, ["mapID"] = 720, ["npcID"] = 108571 } }, ["ends"] = { { ["x"] = 0.585, ["y"] = 0.593, ["mapID"] = 720, ["npcID"] = 108571 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.585, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108571, ["questTurnInID"] = 108571, ["questType"] = "standard", ["sourceQuests"] = { 42809, 42920 }, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42133] = { ["id"] = 42133, ["name"] = "Same Day Delivery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42657, 42658, 42659 }, ["description"] = "I've enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons. While I don't expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.", ["objectivesText"] = "Return to Emmarel Shadewarden at Trueshot Lodge. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 138303 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 641, 739 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42658 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42134] = { ["id"] = 42134, ["name"] = "Recruiting More Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["description"] = "Our champions acquired the talents of Recruiter Sampson , an extraordinary tracker. He has a way with animals, calling them to his side with the utmost ease. In fact, he's already beginning to fill the stables with animals that he has tracked and tamed. Speak to him now.", ["objectivesText"] = "Speak to Recruiter Sampson .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 106446, ["x"] = 0.574, ["y"] = 0.3296 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42395 }, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
