[42139] = { ["id"] = 42139, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42140, 43007, 43013, 43014, 43015 }, ["description"] = "The Uncrowned work behind the scenes, pulling strings here, snipping others there. It's a matter of making the right choices at the right time in the most elegant manner possible. We have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done. Might I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.", ["objectivesText"] = "Recruit Garona Halforcen and Vanessa VanCleef as your first champions.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.413, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 43007 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[42140] = { ["id"] = 42140, ["name"] = "A More Wretched Hive of Scum and Villainy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 43007, 43013, 43014, 43015 }, ["description"] = "Word on the street is that you're lookin' to recruit some more, shall we say, unsavory types? I know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade. Yeah, that Lonika. The one who founded the 'School of Roguery' in Shattrath City. So, let's send Vanessa there out to Outland and have her make Lonika an offer she can't refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"A More Wretched Hive of Scum and Villainy\". Progress: So, what'd Lonika say?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.377, ["y"] = 0.449, ["mapID"] = 626, ["npcID"] = 98092 } }, ["ends"] = { { ["x"] = 0.377, ["y"] = 0.449, ["mapID"] = 626, ["npcID"] = 98092 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.377, ["y"] = 0.449 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98092, ["questTurnInID"] = 98092, ["questType"] = "standard", ["sourceQuests"] = { 42139 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[42141] = { ["id"] = 42141, ["name"] = "Summoner Morn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles. The first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked. I suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Morn Needs Help\". Progress: How is the mission proceeding?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42383 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42142] = { ["id"] = 42142, ["name"] = "Recruiting The Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "Our champions acquired the talents of Summoner Morn, a powerful shaman. He is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause. Speak to him now and train a Lesser Elemental .", ["objectivesText"] = "Speak to Summoner Morn and summon a Lesser Elemental . Progress: How did the training go?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42141 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
