[42158] = { ["id"] = 42158, ["name"] = "The Creator's Workshop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8161, ["mapID"] = 745, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["description"] = "My remote observation relay captured an astonishing amount of data from that tomb. If we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it. Since you're here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you're the capable sort!", ["objectivesText"] = "Assist Mimiron . Progress: Remember, anything is science if you write it down!", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 128808, 128826, 128861 }, ["starts"] = { { ["x"] = 0.449, ["y"] = 0.374, ["mapID"] = 745, ["npcID"] = 106558 } }, ["ends"] = { { ["x"] = 0.449, ["y"] = 0.374, ["mapID"] = 745, ["npcID"] = 106558 } }, ["coords"] = { ["mapID"] = 745, ["x"] = 0.449, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8161 } }, ["questGiverID"] = 106558, ["questTurnInID"] = 106558, ["questType"] = "standard", ["sourceQuests"] = { 41574 }, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1579, ["db2PoiUiMapID"] = 745 },
