[42191] = { ["id"] = 42191, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 41905 }, ["description"] = "Thanks to you, the Order of the Broken Temple is gradually re-assembling. However, there is much more work to do. As our leader, you can determine the trajectory of our order's future. Speak to Number Nine Jia. She will show you the ropes.", ["objectivesText"] = "Speak to Number Nine Jia.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.596, ["mapID"] = 709, ["npcID"] = 99179 } }, ["ends"] = { { ["x"] = 0.528, ["y"] = 0.596, ["mapID"] = 709, ["npcID"] = 99179 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.528, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 99179, ["questTurnInID"] = 99179, ["questType"] = "standard", ["sourceQuests"] = { 42210 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 12, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
