[42193] = { ["id"] = 42193, ["name"] = "The Gjallarhorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["series"] = { 43750 }, ["description"] = "You have proven yourself most thoroughly time and again, <name>. There can be no doubt that you are the one to lead Odyn's armies into the final battle. You must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us. King Svergan Stormcloak was the last known living guardian of the horn. Seek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.", ["objectivesText"] = "Find Svergan Stormcloak .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.559, ["y"] = 0.844, ["mapID"] = 695, ["npcID"] = 107987 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7813 } }, ["questGiverID"] = 107987, ["questType"] = "standard", ["sourceQuests"] = { 43750 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42194] = { ["id"] = 42194, ["name"] = "Stolen Honor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "Safeguarding the Gjallarhorn was my duty, <race>. I will do what is right, but first I must ask for your aid. My family was disavowed by the mystics of our time and this grave was ransacked. I cannot find peace while my family heirlooms are in the hands of the servants of the false God-King. Return them to me and I will aid you in finding the Gjallarhorn!", ["objectivesText"] = "Svergan Stormcloak wants you to obtain the Crown of the Forgotten King , the Stormcloak Signet and the Drakerider's Medallion in the Runewood. Progress: Do you bring back my family's heirlooms, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 137182, 137183, 137184 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42193 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
