[42200] = { ["id"] = 42200, ["name"] = "Mission: Investigating Deepholm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41775, 41901, 42068 }, ["description"] = "In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us. Therazane has been absent from our negotiations with the elements thus far. There have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid. I have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.", ["objectivesText"] = "Successfully complete the \"Investigating Deepholm\" mission.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42984, 42986 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42202] = { ["id"] = 42202, ["name"] = "Revenge, Served Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared. Help me avenge my people and I will aid you in your quest to find Jorhuttam.", ["objectivesText"] = "Slay Dogrub the Cruel, Urgrul Skullcleaver and 8 Frostcrag Drogbar in Highmountain Summit. Progress: You return.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 42110 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42204] = { ["id"] = 42204, ["name"] = "Jorhuttam", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "You upheld your end of your promise. I will do the same. Take these drogbar drums. Then bang on them to call upon Jorhuttam to feast. Find the Great Worm's feeding mound and use the drums to lure her out.", ["objectivesText"] = "Use the Frostcrag Drums near Jorhuttam's Feeding Mound and slay Jorhuttam to obtain the Gjallarhorn . Progress: The Gjallerhorn, <name>. Is it finally in your possession?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 138205, 139501, 140517, 140933 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 106271, ["questType"] = "standard", ["sourceQuests"] = { 42202 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[42206] = { ["id"] = 42206, ["name"] = "The Next Level Has Arrived", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["description"] = "The Empyrean Society is certainly much more dangerous than they appear. It's unimaginable that any mage would study fel magic -- that's for warlocks and the Legion! Since our friend, Ravandwyr, appears to be delayed, it looks like we'll have to deal with this ourselves. We should remove this sect so they can't corrupt anyone else.", ["objectivesText"] = "Kill 10 Empyrean Society members. Progress: Do you think we've reduced their numbers enough?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 137190, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.664, ["y"] = 0.335, ["mapID"] = 630, ["npcID"] = 106656 } }, ["ends"] = { { ["x"] = 0.664, ["y"] = 0.335, ["mapID"] = 630, ["npcID"] = 106656 } }, ["coords"] = { ["mapID"] = 630, ["x"] = 0.664, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questGiverID"] = 106656, ["questTurnInID"] = 106656, ["questType"] = "standard", ["sourceQuests"] = { 42166 }, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42208] = { ["id"] = 42208, ["name"] = "Return to the Firelands", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41772, 41900 }, ["description"] = "The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer. Ragnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression. I have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there. If the mission is successful, we may find the information we need to bring the Firelands into our fold.", ["objectivesText"] = "Complete the \"Return to the Firelands\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41900 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
