[42210] = { ["id"] = 42210, ["name"] = "Scrolls of Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Our troops are ready! It's time to test them out in the field, and I have the perfect assignment. Number Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many of her important scrolls were left behind during the attack on the Peak of Serenity. Send our champions to retrieve these documents at once!", ["objectivesText"] = "Complete the mission, \"Scrolls of Knowledge.\" Progress: How did it go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.597, ["mapID"] = 709, ["npcID"] = 99179 } }, ["ends"] = { { ["x"] = 0.528, ["y"] = 0.597, ["mapID"] = 709, ["npcID"] = 99179 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.528, ["y"] = 0.597 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 99179, ["questTurnInID"] = 99179, ["questType"] = "standard", ["sourceQuests"] = { 41946 }, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
