[42214] = { ["id"] = 42214, ["name"] = "Knocked for a Loop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "While you're focused on murlocs... Many murlocs are known to wear jewelry to attract a mate. I'm willing to bet that we can use some of the same jewels they use. Collect some of their jewelry and bring it back to me. The wetter, the better!", ["objectivesText"] = "Collect 10 Salteye Bangles . Progress: I could see how jewelry on a murloc might make it seem more attractive...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132370, 132467 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40524 }, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
