[42222] = { ["id"] = 42222, ["name"] = "Empyrean Society Report", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42171, 42416, 42423, 42424, 42451, 42508, 42521 }, ["description"] = "I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he's been here... Regardless, we had best return to the Hall of the Guardian and inform Meryl about what we've uncovered here.", ["objectivesText"] = "Return to the Hall of the Guardian.", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 140927 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 106530, ["x"] = 0.648667, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 106530, ["x"] = 0.648667, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.648667, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 106530, ["questType"] = "standard", ["sourceQuests"] = { 42171 }, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42223] = { ["id"] = 42223, ["name"] = "Scouting the Crimson Thicket", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["description"] = "If you are heading east, there is something I would ask of you. While we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long. I would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.", ["objectivesText"] = "Find Lilryia Dawnwind in Dawncleft.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 139791, 140240, 140251, 141941 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41494 }, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42224] = { ["id"] = 42224, ["name"] = "Cloaked in Moonshade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 40324, 40325, 42225 }, ["description"] = "I do not know what Theryn found, but I know where he found it. Moonshade Sanctum, to the west. Beyond the Temple of Fal'adora. Whatever power altered Theryn's arcane essence... Whatever power allowed Kel'danath to create a spell to soothe the withered... Its source rests there. I know this as surely as if I had been there myself.", ["objectivesText"] = "Explore Moonshade Sanctum.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 97140, ["questType"] = "standard", ["sourceQuests"] = { 40325 }, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
