[42365] = { ["id"] = 42365, ["name"] = "Focusing the Energies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln. This rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", ["objectivesText"] = "Collect 3 Blood of Sargeras . Progress: Were you able to find the Blood of Sargeras ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124 }, ["starts"] = { { ["x"] = 0.449, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["ends"] = { { ["x"] = 0.449, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.449, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 103832, ["questTurnInID"] = 103832, ["questType"] = "standard", ["sourceQuests"] = { 42046 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42366] = { ["id"] = 42366, ["name"] = "The Bigger They Are, The Harder They Fel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I have had it with these small fry, assistant. Time to go straight to the top. The tome is the key! The key to unlocking the potential within our people. Do not worry, young one. I have enough power to complete the task at hand. Let us harness fel magic and change the future. Follow me and witness the redemption of the shal'dorei!", ["objectivesText"] = "Assist Kyrtos with his ritual.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141669 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40642, 40713, 40919 }, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42367] = { ["id"] = 42367, ["name"] = "Arkethrax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["description"] = "Within the Ingress is a demon who must die. Arkethrax is a creature of cunning evil. If left unchecked he will be able to use the Ingress as a staging point for targeted assaults that will decimate our forces. I, for one, have no intention of underestimating this opponent and shall join you on the battlefield when you are ready to fight him.", ["objectivesText"] = "Slay Arkethrax .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 121480, 129171, 141404 }, ["rewardChoices"] = { 121480, 129171 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42375 }, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42368] = { ["id"] = 42368, ["name"] = "Quantity Over Quality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["description"] = "The demons of Felblaze Ingress are amassing at an exponential rate. We must cull these invaders before they have enough demons to flank our forces at Illidari Stand. Will you join us in battle?", ["objectivesText"] = "Slay demons in the Felblaze Ingress.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42375 }, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42369] = { ["id"] = 42369, ["name"] = "They're Doing it Wrong", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["series"] = { 42372, 42375 }, ["description"] = "These demon portals are terrible and sloppy. No skill or finesse in it. This physically hurts me and I haven't felt real pain in decades. I \"fixed\" some of the Legion's precious Portal Stabilizer crystals. I want you to take them and \"modify\" their main portal in the Ingress and watch the \"hilarity\" ensue.", ["objectivesText"] = "Place 4 Sabotaged Portal Crystals. Progress: Did you see the look on those demons' faces? Priceless!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42375 }, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42370] = { ["id"] = 42370, ["name"] = "Wanding 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37467, 37468, 37486, 37497, 37518, 37736 }, ["description"] = "We'll start with some wand work. You have your wand with you? Good. I've set up a number of targets around the hall. Use your wand to hit as many as you can. And no point-blank shots! That's cheating.", ["objectivesText"] = "Practice using your wand on 10 Wand Targets . Progress: You'll never learn if you never practice.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.297, ["y"] = 0.425, ["mapID"] = 631, ["npcID"] = 89661 } }, ["ends"] = { { ["x"] = 0.297, ["y"] = 0.425, ["mapID"] = 631, ["npcID"] = 89661 } }, ["coords"] = { ["mapID"] = 631, ["x"] = 0.297, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questGiverID"] = 89661, ["questTurnInID"] = 89661, ["questType"] = "standard", ["sourceQuests"] = { 37518 }, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42371] = { ["id"] = 42371, ["name"] = "Study Hall: Combat Research", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["description"] = "What's this? A new, confused student, desperately trying to win the favor of the headmistress, wandering the halls without anything to do? Perfect! I need help with my research. I'm writing a paper on combat. Grab me some books from the shelf over there.", ["objectivesText"] = "Obtain the books that Sythorne requests, then help him defeat the challenges within. Progress: I agree. Research can be grueling work.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 116456, 122674, 137422, 137423, 137426 }, ["starts"] = { { ["x"] = 0.309, ["y"] = 0.446, ["mapID"] = 631, ["npcID"] = 107334 } }, ["ends"] = { { ["x"] = 0.309, ["y"] = 0.446, ["mapID"] = 631, ["npcID"] = 107334 } }, ["coords"] = { ["mapID"] = 631, ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questGiverID"] = 107334, ["questTurnInID"] = 107334, ["questType"] = "standard", ["sourceQuests"] = { 42370 }, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42372] = { ["id"] = 42372, ["name"] = "Felblaze Ingress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["series"] = { 42369, 42375 }, ["description"] = "It is my mission to cover the rear guard of Illidari Stand. I have employed this warlock... thing, to assist me. However, the two of us are insufficient for a task that needs doing. To the east is a mass of demons at Felblaze Ingress. These creatures have begun to open portals to summon in countless reinforcements. Meet us at Felblaze Ingress and together we can crush this fel insurgency.", ["objectivesText"] = "Meet Tehd Shoemaker at Felblaze Ingress.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 106915, ["x"] = 0.504, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["nextQuests"] = { 42375 }, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
