[42375] = { ["id"] = 42375, ["name"] = "Eye See You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["series"] = { 42369, 42372 }, ["description"] = "There is being blind, and then there is being stupid. This eyeless wonder next to me wants to barrel into Felblaze Ingress without preparation. Bah! I say we scout it first. Here, I will provide you with an extra eye I picked up from a place better left unmentioned. Enter Felblaze Ingress, investigate the area, and try not to get poked in the eye.", ["objectivesText"] = "Use Tehd's Eye of Kilrogg to investigate Felblaze Ingress. Progress: Don't ask where I got the eye. Worst case is I tell you and then it gets all awkward between us.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133753, 137191, 181501, 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181662, 181664, 181665, 181666, 181671, 181672, 181674, 181679, 181680, 181681, 181682, 181686, 181689, 181690, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 244913 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42372 }, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
