[42377] = { ["id"] = 42377, ["name"] = "The Brother's Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["description"] = "We must reclaim the Silver Hand before those with evil intent can seize it. To free it from its wards, we need relics called the Sparks of Tyr. I have one, as does my brother, Galford. He journeyed to Northrend to seek aid from the Tyr's homeland, but has not returned. I must ask you to find him, and his Spark.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.72, ["y"] = 0.493, ["mapID"] = 627, ["npcID"] = 106337 } }, ["ends"] = { { ["x"] = 0.72, ["y"] = 0.493, ["mapID"] = 627, ["npcID"] = 106337 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.72, ["y"] = 0.493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 106337, ["questTurnInID"] = 106337, ["questType"] = "standard", ["sourceQuests"] = { 42231 }, ["questLines"] = { { ["id"] = 222, ["name"] = "The Silver Hand", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 222, ["questLineOrder"] = 7 } } },
