[42416] = { ["id"] = 42416, ["name"] = "The Council is in Session", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 627, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42423, 42424, 42451, 42508, 42521 }, ["description"] = "Archmage Vargoth's involvement with the Empyrean Society is troubling. However, as he has proven his loyalty to the Kirin Tor many times, we must give him the benefit of the doubt for now. Still, I am obligated to share our concerns with the rest of the Council. You had best travel to Dalaran and meet with them in the Violet Citadel. I will remain here to care for our old friend.", ["objectivesText"] = "Speak to the Council of Six in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 118191, 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.717, ["y"] = 0.549, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.717, ["y"] = 0.549, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.717, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "standard", ["sourceQuests"] = { 42222 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
