[42423] = { ["id"] = 42423, ["name"] = "Archmage Vargoth's Retreat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42424, 42451, 42508, 42521 }, ["description"] = "Archmage Vargoth has been absent for a while. You may have a look around his living quarters here in the citadel tower, <name>. Kalec will escort you there. I will hold out hope that our esteemed colleague is merely up to his usual eccentricities.", ["objectivesText"] = "Investigate Archmage Vargoth's quarters. Progress: What have you discovered, <name>?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 43824, 127857, 128820, 128862, 137571, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.284, ["y"] = 0.494, ["mapID"] = 627, ["npcID"] = 90431 } }, ["ends"] = { { ["x"] = 0.284, ["y"] = 0.494, ["mapID"] = 627, ["npcID"] = 90431 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.284, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90431, ["questTurnInID"] = 90431, ["questType"] = "standard", ["sourceQuests"] = { 42416 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42424] = { ["id"] = 42424, ["name"] = "Following In His Footsteps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42451, 42508, 42521 }, ["description"] = "Archmage Vargoth seems to be mixed up in something dangerous, not that that's unusual for an archmage of his caliber and experience! The Arcway Vaults may be where he's headed, but we should investigate all leads in order to get a better idea of what he's up to.", ["objectivesText"] = "Ask your champions to investigate Archmage Vargoth's travels. Progress: Have your champions discovered anything of note about Archmage Vargoth?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.222, ["y"] = 0.551, ["mapID"] = 627, ["npcID"] = 107423 } }, ["ends"] = { { ["x"] = 0.222, ["y"] = 0.551, ["mapID"] = 627, ["npcID"] = 107423 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.222, ["y"] = 0.551 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 107423, ["questTurnInID"] = 107423, ["questType"] = "standard", ["sourceQuests"] = { 42423 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42425] = { ["id"] = 42425, ["name"] = "Going Down, Going Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "Now that we have the necessary worm guts, I was able to fashion them into a special sort of rope. It will allow you to descend from the bridge into the chasm below and recover some of my possessions that were stolen and thrown in by the Deeprock.", ["objectivesText"] = "Use Oren's Rappel Point to descend into the depths and recover his lost possessions. Progress: I have never been particularly fond of heights.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121440, 121441, 121442, 121443, 132936, 137566, 141386, 141605 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 40069 }, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[42428] = { ["id"] = 42428, ["name"] = "The Shrine of Ashamane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42439 }, ["description"] = "The mighty Ancient, Ashamane, fell in battle against the Burning Legion ten thousand years ago. To honor her sacrifice, a group of devoted druids called the Ashen forged Ashamane's fangs into powerful daggers. Take my signet and present it to their leader, Delandros Shimmermoon . He will know that you have my blessing. Our flight master, Danise Stargazer , can see you to the shrine.", ["objectivesText"] = "Speak to Danise Stargazer and travel to Ashamane's Fall in search of Delandros Shimmermoon .", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 40646, 43980, 44431, 44443 }, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42429] = { ["id"] = 42429, ["name"] = "Memories of Ebonchill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 42429 }, ["description"] = "Is that Ebonchill you've got there? Alodi's old staff? My my my... <Cough> In the days of the first guardian, all the members of the Council of Tirisfal granted their powers to the young mage in the hopes that he could overcome the Legion. <Wheeze> None of them are alive today... but that staff of yours remembers. Search the streets of Dalaran below for reflections of the former council members. Their memories may empower you as they once did Alodi. Seek them out and speak with one!", ["objectivesText"] = "Find a Reflection of the Council of Tirisfal in Dalaran City. Speak with one to receive his or her wisdom. Progress: Seek out the memories of the former Council members. None are here in the upper floors of the tower, and none would be in the sewers. <Cough> Check the public squares, the inns, the lower floors of the tower, the streets... A sharp eye is your ally.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 242558, 242582 }, ["starts"] = { { ["x"] = 0.532, ["y"] = 0.415, ["mapID"] = 735, ["npcID"] = 107452 } }, ["ends"] = { { ["x"] = 0.532, ["y"] = 0.415, ["mapID"] = 735, ["npcID"] = 107452 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.532, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107452, ["questTurnInID"] = 107452, ["questType"] = "standard", ["sourceQuests"] = { 42479 } },
[42430] = { ["id"] = 42430, ["name"] = "The Fangs of Ashamane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42440 }, ["description"] = "I have to admit, Verstok was right. The shrine was too easy of a target for the Burning Legion to attack. Still, he's gone and the Fangs are with him. We're going to have to track him down for you to recover the Fangs. I should come with you but I have to stay with my people should we be attacked again. Here, my companion Ebonfang has a sense of smell like no other. He will be able to guide you to wherever Verstok is hiding. Also take this shell, through it we can communicate. May Elune guide you.", ["objectivesText"] = "Mount upon Ebonfang and search for the Fangs of Ashamane. Progress: How goes your search?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 138136 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 107392, ["questType"] = "standard", ["sourceQuests"] = { 42440 }, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42431] = { ["id"] = 42431, ["name"] = "The Brood of Nithogg", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42431 }, ["objectivesText"] = "Cull the Squallhunters", ["rewardGold"] = 391440, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 200 } }, ["starts"] = { { ["x"] = 0.452, ["y"] = 0.368, ["mapID"] = 634 } }, ["ends"] = { { ["x"] = 0.452, ["y"] = 0.368, ["mapID"] = 634 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.452, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cull the Squallhunters", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42432] = { ["id"] = 42432, ["name"] = "The Emerald Nightmare: The Emerald Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "The Lord of Nightmare, Xavius , is still out there. Cenarius is still in grave danger, deep within the Rift of Aln. Summon your greatest allies, <name>. If we are to stare into the face of the Nightmare, we had best be ready. Once you are ready, enter the Emerald Nightmare and defeat all the horrors you find there.", ["objectivesText"] = "Enter the Emerald Nightmare raid on any difficulty and defeat Lord Xavius . Progress: Never has the Nightmare spilled into our world. It is our duty to find the root of this evil, and destroy it.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139484, 246936, 249400, 254267, 254579, 264675 }, ["starts"] = { { ["x"] = 0.326, ["y"] = 0.539, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.326, ["y"] = 0.539, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.326, ["y"] = 0.539 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "raid", ["sourceQuests"] = { 42056 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42433] = { ["id"] = 42433, ["name"] = "Ancient Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42166, 42418, 42434, 42435 }, ["description"] = "Since the Broken Isles is the epicenter of ancient night elven learning, there must be countless magical artifacts secreted away in forgotten vaults and reliquaries. We must secure them so they do not fall into the wrong hands! Perhaps you should send a champion in search of them.", ["objectivesText"] = "Interact with your Scouting Map and complete the mission, \"Ancient Magic.\" Progress: What have you discovered?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.78, ["y"] = 0.585, ["mapID"] = 734, ["npcID"] = 107482 } }, ["ends"] = { { ["x"] = 0.78, ["y"] = 0.585, ["mapID"] = 734, ["npcID"] = 107482 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.78, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107482, ["questTurnInID"] = 107482, ["questType"] = "standard", ["sourceQuests"] = { 42696 }, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42434] = { ["id"] = 42434, ["name"] = "A Covert Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42166, 42418, 42433, 42435 }, ["description"] = "Your champion discovered some sort of powerful magic emanating from the secretive Empyrean Society enclave in Azsuna. Archmage Vargoth asked me to request Meryl's aid in investigating it, but as you can see, Meryl is clearly too ill to travel at the moment. Would you be willing to go in his place? You will need to prove yourself in order to gain entrance. We should be able to find something sufficient in the Hatecoil Warcamp in Azsuna.", ["objectivesText"] = "Meet Ravandwyr in Azsuna.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.618, ["y"] = 0.599, ["mapID"] = 735, ["npcID"] = 107341 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107532, ["x"] = 0.648, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7879 } }, ["questGiverID"] = 107341, ["questType"] = "standard", ["sourceQuests"] = { 42418 }, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42435] = { ["id"] = 42435, ["name"] = "Prepare To Be Assimilated", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["description"] = "The Empyrean Society is a dangerous cult. They claim to study all magic regardless of its source, but in reality they focus mostly on the forbidden. They will welcome you to their enclave if you bring them a magical artifact. The Hatecoil naga have found the perfect gifts - a Pearl of Arcane Wisdom and scrolls from the depths beneath the Nar'thalas Academy. You will have to convince them to part with a few. I will meet you on the road just north of the Empyrean Enclave.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 107532, ["x"] = 0.648, ["y"] = 0.378, ["mapID"] = 630 } }, ["ends"] = { { ["npcID"] = 106530, ["x"] = 0.66, ["y"] = 0.324, ["mapID"] = 630 } }, ["coords"] = { ["x"] = 0.648, ["y"] = 0.378, ["source"] = "quest_giver", ["mapID"] = 630 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42434 }, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } } },
[42436] = { ["id"] = 42436, ["name"] = "Aiding Our Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["description"] = "Our Skyhorn allies could use some assistance. Their ongoing war with the invading harpies has left them low on supplies. Anything we can give them will surely help with their efforts to rid those witches from their village.", ["objectivesText"] = "Deliver supplies to Meliah Grayfeather .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124109, 124119, 133940, 140215, 140224 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42395 }, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42438] = { ["id"] = 42438, ["name"] = "Seeds of Renewal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["description"] = "The Fangs of Ashamane are in danger, <name>. For ten thousand years a powerful magic ward has protected them from any would-be thieves, but the ward has weakened over time and is in danger of failing. My three most trusted Ashen have the Tel'andu seeds we need to perform the ritual of renewal, but the woods are now crawling with demons and I fear they have fallen. No matter what, we cannot allow the Legion to obtain the Fangs! Go and find the Tel'andu seeds , we must hurry before the ward can be broken!", ["objectivesText"] = "Delandros Shimmermoon wants you to search the forests of Mistvale and obtain three Tel'andu Seeds . Progress: Have the Tel'andu seeds ?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 140772 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42428 }, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42439] = { ["id"] = 42439, ["name"] = "Aid for the Ashen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42428 }, ["description"] = "Turn your eyes above and you will see the cause of our misfortune. Ever since that ship appeared the attacks have been relentless. Many of the Ashen have been captured and even now I can hear their screams of torture. Please, go out there and rescue as many of my followers as you can. They do not deserve the fate that awaits them if left in the Legion's grip.", ["objectivesText"] = "Defeat 4 Eredar Soul Lashers and free their captives.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42428 }, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42440] = { ["id"] = 42440, ["name"] = "The Shrine in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42430 }, ["description"] = "You've helped us greatly, champion. Now, it is time that you tell me what brings you here. <You mention to Delandros that Archdruid Greathoof sent you to seek the Fangs of Ashamane.> Hrm... if you had told me this at the outset, I would have told you to take a walk. The Fangs are our greatest treasure, but you've done a great deed for the Ashen today and I am an elf of my word. Very well, let's clear out the rest of these demons and you shall have your weapons.", ["objectivesText"] = "Assist Delandros by removing the last of the attackers. Progress: Did you check on that disturbance?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42438, 42439 }, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
