[42444] = { ["id"] = 42444, ["name"] = "Plight of the Blackfeather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "<The ravenbear frantically gestures and points down the path. It seems he wants you to follow him.>", ["objectivesText"] = "Follow the frightened ravenbear to the Blackfeather chieftain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107499, ["x"] = 0.502, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42445] = { ["id"] = 42445, ["name"] = "Nithogg's Tribute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "It looks like the ravenbears have started gathering materials for some sort of tribute, but the storm drakes are keeping them from finishing what they started. From the looks of it, they're gathering fully intact stag horns and long tail feathers from the greatstags and eagles nearby. It shouldn't take too long to gather the rest of what they need.", ["objectivesText"] = "Collect 8 Intact Greatstag Antlers and 16 Pristine Eagle Tailfeathers in the Stormtorn Foothills. Progress: Ca-caw?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 137610, 137611 }, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.325, ["mapID"] = 634, ["objectID"] = 250536 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42444 }, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42446] = { ["id"] = 42446, ["name"] = "Singed Feathers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "Ca-caw! Caw caw! <The chieftain flaps his wings and points outside where the storm dragons attack the ravenbears of his tribe. It's plain to see that he's seeking your help to save his flock.>", ["objectivesText"] = "Kill 8 Rampaging Squallhunters in the Stormtorn Foothills.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42444 }, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42447] = { ["id"] = 42447, ["name"] = "Dances With Ravenbears", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.> Caw! Caw ca-caw! <It looks like he wants you to follow.>", ["objectivesText"] = "Help the Blackfeather ravenbears perform their tribute ritual.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129246, 129247, 129248, 129249, 129361, 129363, 129364, 129365 }, ["rewardChoices"] = { 129246, 129247, 129248, 129249, 129361, 129363, 129364, 129365 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42445, 42446 }, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42449] = { ["id"] = 42449, ["name"] = "Return of the Four Horsemen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 1, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43539 }, ["description"] = "The voice of the Lich King has spoken, Deathlord, and the Knights of the Ebon Blade will obey your command. The Four Horsemen were no ordinary death knights, they were born of pure, unholy power gifted from the Lich King to Kel'thuzad. This unholy power to raise the dead has now been passed to you, Deathlord. I am sure you will wield it with great conviction. The Four Horsemen will be powerful allies against the Burning Legion... and Nazgrim is a worthy choice as the firstborn.", ["objectivesText"] = "Speak with Thassarian in Durotar.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 107554, ["x"] = 0.472, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 7543 } }, ["questGiverID"] = 93437, ["questType"] = "standard", ["sourceQuests"] = { 39799 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
