[42451] = { ["id"] = 42451, ["name"] = "Kalec's Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42424, 42508, 42521 }, ["description"] = "Your champion was unable to penetrate very far inside the Arcway Vaults due to the heavy legion presence around it. Hopefully you will have better luck following Archmage Vargoth inside. Kalecgos will be waiting for you on the ridge overlooking Felsoul Hold.", ["objectivesText"] = "Meet Kalecgos on the ridge near the Arcway Vaults.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 109076, 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.809, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107465, ["x"] = 0.312, ["y"] = 0.8236 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.8236 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7879 } }, ["questGiverID"] = 108515, ["questType"] = "standard", ["sourceQuests"] = { 42424 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42452] = { ["id"] = 42452, ["name"] = "Finding Ebonchill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["description"] = "Ebonchill bears a lineage of powerful wielders dating back to its maker, Alodi. He passed it on to his favorite apprentice and so on until... the archmage Arrexis, I believe. Arrexis disappeared sometime around the First War. I know nothing of his fate, but the answer may well be somewhere in this library. Start by looking around here. Whatever you find should lead us to Ebonchill.", ["objectivesText"] = "Investigate the forgotten stacks in the Hall of the Guardian for clues to Ebonchill's last known master, Arrexis. Progress: Have we found what we need yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.591, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 41085, 43441, 44310 }, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
