[42454] = { ["id"] = 42454, ["name"] = "The Hammer of Khaz'goroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 39781 }, ["description"] = "<Now that you have defeated Dargrul the Underking and have the Hammer of Khaz'goroth in hand, it is time to place it in Aegwynn's Gallery in the lower chambers of Dalaran .>", ["objectivesText"] = "Use the central teleporter in Dalaran and then place the Hammer of Khaz'goroth in Aegwynn's Gallery.", ["rewardGold"] = 7150, ["rewardXP"] = 1415, ["rewardItems"] = { 137649, 141007, 141008, 141009, 141010 }, ["rewardChoices"] = { 141007, 141008, 141009, 141010 }, ["starts"] = { { ["objectID"] = 250548 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7546 } }, ["questType"] = "standard", ["sourceQuests"] = { 39781 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[42455] = { ["id"] = 42455, ["name"] = "Alodi's Gems", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["description"] = "Arrexis had a cadre of apprentices and subordinates to help him with the ritual, something you are currently lacking. In older times, when magic was less understood and spells required vast amounts of mana to cast, we stored mana in gems for use in complex spells. Lucky for us, I still have a few powerful Mana Gems in my vault, along with some other useful items. You merely need to go to the Bank of Dalaran and gain access.", ["objectivesText"] = "Gain access to Alodi 's personal bank vault in Dalaran and retrieve the Mana Gems. Progress: You found everything in my vault? I hope the defenses weren't a bother.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 141317 }, ["starts"] = { { ["x"] = 0.606, ["y"] = 0.434, ["mapID"] = 735, ["npcID"] = 102846 } }, ["ends"] = { { ["x"] = 0.606, ["y"] = 0.434, ["mapID"] = 735, ["npcID"] = 102846 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.606, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102846, ["questTurnInID"] = 102846, ["questType"] = "standard", ["sourceQuests"] = { 42452 }, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
