[42476] = { ["id"] = 42476, ["name"] = "The Deadwind Site", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["series"] = { 42477, 42479 }, ["description"] = "Your research spoke of an experimental site out near Karazhan. I hope there are still materials on this ritual that will aid us there. You will need to find the site and bring back anything that will help us recreate the ritual. I will dig deeper here as well.", ["objectivesText"] = "Find and retrieve information on the ritual from Arrexis's campsite near Karazhan. Progress: I trust you were successful?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 141327, 141328, 141329, 173698 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.591, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 42452 }, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42477] = { ["id"] = 42477, ["name"] = "Daio the Decrepit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["series"] = { 42476, 42479 }, ["description"] = "That text lists someone named Daio as being instrumental to the demonic ritual. They can't possibly mean Daio the Decrepit! I never knew he was Kirin Tor. I only know him as an elderly warlock who trains young recruits in the infernal arts. This would certainly explain his change of occupation. He most likely holds key information for this to work. Though retired, I believe he is still out in the Tainted Scar in the Blasted Lands. You should seek him out.", ["objectivesText"] = "Fly to the Tainted Scar in the Blasted Lands and get information from Daio the Decrepit. Progress: Well, what did Daio have to say?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 140192, 141330, 173699 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.591, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 42452 }, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42479] = { ["id"] = 42479, ["name"] = "The Mage Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["series"] = { 42476, 42477 }, ["description"] = "And with that, we have what we need to recreate the ritual... however flawed it may be. It must be conducted somewhere highly visible so that word reaches our target swiftly. I've heard reports that the Legion is heavily invested in the Faronaar region of Azsuna. An excellent place to begin a ritual they won't want us to complete. The chances of us dying horribly are exceptionally high.", ["objectivesText"] = "Recreate Arrexis' ritual in Faronaar and defeat Balaadur. Progress: Do you have it?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 127857, 128820, 128862 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.43, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.591, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 42455, 42476, 42477 }, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42483] = { ["id"] = 42483, ["name"] = "Put It All on Red", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "All right, I've got one last beasty to send you after. He's a bit far out, but trust me, it'll be worth it. This one I put a huge wager on! Along the eastern coast swims a great shark the locals call Steelscale. They say his hide is near impenetrable. But you're gonna prove them wrong, aren't ya chum? Bring me his fin, and those tauren will have to fork over a princely sum.", ["objectivesText"] = "Collect Steelscale's Fin from Steelscale in Citrine Bay. Progress: Hmm...", ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138024, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 107674, ["questType"] = "group", ["sourceQuests"] = { 39786, 39792 }, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 5, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42484] = { ["id"] = 42484, ["name"] = "The Firstborn Rises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["description"] = "General Nazgrim was one of the finest warriors our world has known, and his loyalty was unsurpassed... even for an orc. He deserves the peace of death, but this world cries out to be saved. The time for rest is over... Come, Deathlord... let us welcome Nazgrim into the arms of the damned.", ["objectivesText"] = "Raise Nazgrim as a Death Knight. Progress: General Nazgrim will make a fine <class>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 107554, ["x"] = 0.472, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 107554, ["x"] = 0.472, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questTurnInID"] = 107554, ["questType"] = "standard", ["sourceQuests"] = { 42449 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
