[42486] = { ["id"] = 42486, ["name"] = "Little One Lost", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I'm ready to go home now, but there are still scary men outside... Will you stay with me? Make sure they don't take me away? I don't want to go back in the cage...", ["objectivesText"] = "Escort Korine back to her mother Verene at the Waning Crescent.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107712, ["x"] = 0.431, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.411, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42722 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42487] = { ["id"] = 42487, ["name"] = "Friends On the Outside", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "You have done well for us here, but it is time for you to return to Thalyssra. There is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way. Oh, and before you go: < Vanthir hands you a wrapped bottle of Arcwine.> Take this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child. We are grateful beyond measure. Farewell for now.", ["objectivesText"] = "Activate the teleporter pad and bring Vanthir 's gift to Thalyssra. Progress: A gift? For me?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 138389 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42486 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42488] = { ["id"] = 42488, ["name"] = "Thalyssra's Abode", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "While you were busy in the city I reached a roadblock in my withered research. I feel I am close to overcoming this barrier, but I'm afraid I cannot do so without some more advanced tools. I hid among my possessions an item called an Arcane Amplifier . It does precisely what its name entails. It is more than likely that the Magistrix ordered my estate dismantled. If the Amplifier remains, it will be in fragments. Recover the whole, if you can.", ["objectivesText"] = "Search Thalyssra's estate and collect 3 Amplifier Fragments . Combine them into an Arcane Amplifier . Progress: Did you find it?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138391, 138392, 140255, 141677, 141951, 141952, 142054, 246937, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42487 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42489] = { ["id"] = 42489, ["name"] = "Thalyssra's Drawers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "Thalyssra's ransacked estate still contains a number of items important to Thalyssra. Collect them and return them to her.", ["objectivesText"] = "Search Thalyssra's estate and collect her belongings. Progress: What did you find?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138193, 138194, 138195, 140255, 141677, 141951, 141952, 142054, 248009 }, ["starts"] = { { ["x"] = 0.656, ["y"] = 0.627, ["mapID"] = 680, ["objectID"] = 251032 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42488 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42490] = { ["id"] = 42490, ["name"] = "The Arcway: Opening the Arcway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42490 }, ["description"] = "Deep beneath Suramar is a defunct set of tunnels known as the Arcway. They were abandoned when a disaster disrupted the mana collectors operating there. I know not what awaits you down there, but I do know one thing. We are not the only ones interested in this place. Make enough noise and one of the advisors with whom I served under Elisande is sure to appear. His name is Vandros. Slay him, if you can. His death will be our victory, as we deprive Elisande of one more weapon in her arsenal.", ["objectivesText"] = "Slay Advisor Vandros in the Arcway. Progress: Is it done?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 112146, ["x"] = 0.365, ["y"] = 0.468 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 44053 } },
[42491] = { ["id"] = 42491, ["name"] = "The Arcway: Long Buried Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42491 }, ["description"] = "Beneath Suramar City is an ancient network of tunnels known as the Arcway. They were abandoned some time ago as part of the cavern became unstable. Since then, who knows? Regardless of what is currently down there, I believe you will find something essential to our continued success. Long ago my people took a thorough survey of the ley lines in and around Suramar . This they would have stored in the library in the Arcway. Find this map for me.", ["objectivesText"] = "Acquire the Suramar Leyline Map from the Arcway. Progress: Did you find it?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 138394, 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 44053 } },
[42492] = { ["id"] = 42492, ["name"] = "PH: Withered Scenario", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42492 }, ["description"] = "PH See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(42492)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(42492))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "PH", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[42493] = { ["id"] = 42493, ["name"] = "Impending Dooooooom!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 683, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42520, 42707, 42734, 42940 }, ["description"] = "Millhouse attracts trouble, so he's sure to find Archmage Vargoth if he's still here. Oh and if you do find the Nightborne Soulstone, best get it first!", ["objectivesText"] = "Investigate the Nightborne Vault. Progress: What did you discover?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.642, ["y"] = 0.295, ["mapID"] = 683, ["npcID"] = 108085 } }, ["ends"] = { { ["x"] = 0.642, ["y"] = 0.295, ["mapID"] = 683, ["npcID"] = 108085 } }, ["coords"] = { ["mapID"] = 683, ["x"] = 0.642, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questGiverID"] = 108085, ["questTurnInID"] = 108085, ["questType"] = "standard", ["sourceQuests"] = { 42521 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 683 },
[42494] = { ["id"] = 42494, ["name"] = "More Than Just A Food Vendor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["description"] = "Your champions made a good dent in thinning out the enemy's numbers. They also discovered a number of starving prisoners who could use our help. Your Conjured Mana Pudding or Fritters will be useful in getting them up on their feet. You should also dispatch as many of the remaining legion invaders back to the twisting nether as you can!", ["objectivesText"] = "Eradicate 15 demons and give your conjured food to 10 starving prisoners. Progress: Have you been able to help the prisoners?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 80610, 127857, 128820, 128862, 138115, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 111553, ["questType"] = "standard", ["sourceQuests"] = { 42508 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42501] = { ["id"] = 42501, ["name"] = "Finishing the Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568 }, ["series"] = { 42502, 42503, 42539, 42568 }, ["description"] = "Garona set out to assassinate the leaders of a Legion cult some time ago. We haven't heard from her since. To make matters worse, she took the Kingslayers with her. She knows they bring out the worst in her! Your best bet to find Garona is by continuing her work. Our intel points to a warlock by the name of Caden Shadowgaze inducting new recruits at the Altar of Storms in Blasted Lands. See if he has anything useful in his pockets. Once he's dead, I mean.", ["objectivesText"] = "Assassinate Cade Shadowgaze at the Altar of Storms in Blasted Lands and search his body for information.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 137676, 139506, 139739, 139742, 139746, 140517, 140931, 173531 }, ["starts"] = { { ["x"] = 0.423, ["y"] = 0.759, ["mapID"] = 626, ["npcID"] = 94138 } }, ["ends"] = { { ["x"] = 0.423, ["y"] = 0.759, ["mapID"] = 626, ["npcID"] = 94138 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.423, ["y"] = 0.759 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 94138, ["questTurnInID"] = 94138, ["questType"] = "standard", ["sourceQuests"] = { 40840, 44034, 44375 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[42502] = { ["id"] = 42502, ["name"] = "No Sanctuary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568 }, ["series"] = { 42501, 42503, 42539, 42568 }, ["description"] = "We have one other lead that may prove useful. Goes by Felcaller Whitley , another of the cult's elite. He's eluded our agents at every turn. Our latest reconnaissance report puts him somewhere in the village of Raven Hill in Duskwood. He's sure to have information vital to your search. You know what to do.", ["objectivesText"] = "Assassinate Felcaller Whitley at Raven Hill in Duskwood and search his body for information.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 137678, 139506, 139734, 139739, 139742, 139746, 140517, 140931, 173530, 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466, 194549 }, ["starts"] = { { ["x"] = 0.423, ["y"] = 0.759, ["mapID"] = 626, ["npcID"] = 94138 } }, ["ends"] = { { ["x"] = 0.423, ["y"] = 0.759, ["mapID"] = 626, ["npcID"] = 94138 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.423, ["y"] = 0.759 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 94138, ["questTurnInID"] = 94138, ["questType"] = "standard", ["sourceQuests"] = { 40840, 44034, 44375 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[42503] = { ["id"] = 42503, ["name"] = "Codebreaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 626, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568, 42627 }, ["series"] = { 42501, 42502, 42539, 42568 }, ["description"] = "coded message you obtained is protected by powerful magic, rendering it indecipherable by conventional means.>", ["objectivesText"] = "Use the Fel Cipher to decrypt the Coded Message and learn where you can find the cultists next.", ["rewardGold"] = 9470, ["rewardXP"] = 175, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 138102, 139506, 139739, 139742, 139746, 140517, 140931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 42501, 42502 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[42504] = { ["id"] = 42504, ["name"] = "The Unseen Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568 }, ["description"] = "We can't let Stormwind fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own. The two of us need to handle this while there's still time. The entire city is on edge from murmurs of the cult's activities. They're as likely to turn on you as they are the cultists if you aren't careful. The other Shadows spoke highly of your skills. Are you in?", ["objectivesText"] = "Help Garona take out the Veiled Hand cultists in Stormwind.", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["rewardItems"] = { 128479, 128870, 128872, 139178 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questTurnInID"] = 107979, ["questType"] = "standard", ["sourceQuests"] = { 42568 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
