[42508] = { ["id"] = 42508, ["name"] = "Not A Toothless Dragon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42424, 42451, 42521 }, ["description"] = "The Arcway Vaults have been buried and untouched for thousands of years. We have the legion to thank for it being accessible once again, though I would give much for it to remain hidden. I think we are not far behind Archmage Vargoth's heels and he may yet be inside the vaults. We should make haste if we hope to intercept him.", ["objectivesText"] = "Ride with Kalecgos to the Arcway Vaults.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107465, ["x"] = 0.312, ["y"] = 0.8236 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.8236 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42451 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42510] = { ["id"] = 42510, ["name"] = "Immortal Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 37447, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "Illidan's immortal demon soul is lost somewhere in the vastness of the Twisting Nether. Contacting him risks much, the Nether is full of creatures of unimaginable power and appetites. But, it must be done if we are to move forward. The ritual can be performed using the nether crucible. Make the blood offering , <name>.", ["objectivesText"] = "Make the Blood Offering to complete the ritual and contact the soul of Illidan Stormrage. Progress: All that is left is to make the blood offering . Then, we will see what the future holds for the Illidari.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 137690, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.577, ["y"] = 0.517, ["mapID"] = 721, ["npcID"] = 107723 } }, ["ends"] = { { ["x"] = 0.577, ["y"] = 0.517, ["mapID"] = 721, ["npcID"] = 107723 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.577, ["y"] = 0.517 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 107723, ["questTurnInID"] = 107723, ["questType"] = "standard", ["sourceQuests"] = { 37447 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
