[42512] = { ["id"] = 42512, ["name"] = "Highmountain Stands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088 }, ["description"] = "That will have to do. Dargrul has come and we need every able body on the front line. Go, I will be right behind you.", ["objectivesText"] = "Defeat Dargrul.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 42088 }, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[42516] = { ["id"] = 42516, ["name"] = "Growing Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 42583 }, ["description"] = "Archdruid Rensar Greathoof has requested your presence. Our campaign to defend the Broken Isles is getting under way, and we need you at the helm.", ["objectivesText"] = "Speak to Archdruid Rensar Greathoof at the Dreamgrove.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112689 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 112689, ["questType"] = "standard", ["sourceQuests"] = { 40653 }, ["nextQuests"] = { 42583 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42517] = { ["id"] = 42517, ["name"] = "Ritual of Doom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["description"] = "Your research has granted you access to a very powerful ritual, one that will require the aid of a few friends if you wish to successfully summon a demon. The ritual needs to be performed at the summoning platform above. Keep in mind, this sort of power always comes at a price. Not all who participate in the summoning will survive, so be prepared.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["starts"] = { { ["npcID"] = 111740, ["x"] = 0.57, ["y"] = 0.406, ["mapID"] = 717 } }, ["ends"] = { { ["npcID"] = 111740, ["x"] = 0.57, ["y"] = 0.406, ["mapID"] = 717 } }, ["coords"] = { ["x"] = 0.57, ["y"] = 0.406, ["source"] = "quest_giver", ["mapID"] = 717 }, ["mapCandidates"] = { ["npc"] = { 717 }, ["zone"] = { 7875 } }, ["questType"] = "group", ["sourceQuests"] = { 42601 } },
[42519] = { ["id"] = 42519, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["description"] = "As leader of our order, other hunters will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary in the name of the Unseen Path. I know of two within our ranks who are impressed with what they've seen from you so far, and want to help any way they can. Seek them out, and let them ease the burden of leadership.", ["objectivesText"] = "Recruit Emmarel Shadewarden and Loren Stormhoof.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102940, ["x"] = 0.476333, ["y"] = 0.530333 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.476333, ["y"] = 0.530333 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 40959, 44090 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42520] = { ["id"] = 42520, ["name"] = "A Terrible Loss", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 735, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42493, 42707, 42734, 42940 }, ["description"] = "I would say I am surprised by this terrible turn of events, but nothing surprises me of late. It is dark times when even the most upstanding of us can fall... We had best inform Archmage Khadgar of Vargoth's betrayal.", ["objectivesText"] = "Return to the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139506, 139754 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["x"] = 0.42, ["y"] = 0.608, ["mapID"] = 683, ["npcID"] = 108085 } }, ["ends"] = { { ["x"] = 0.42, ["y"] = 0.608, ["mapID"] = 683, ["npcID"] = 108085 } }, ["coords"] = { ["mapID"] = 683, ["x"] = 0.42, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questGiverID"] = 108085, ["questTurnInID"] = 108085, ["questType"] = "standard", ["sourceQuests"] = { 42493, 42494 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42521] = { ["id"] = 42521, ["name"] = "The Enemy of My Enemy...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42424, 42451, 42508 }, ["description"] = "Millhouse Manastorm has been quite vociferous about his intention to acquire the Nightborne Soulstone. If you find him, you may as well make use of him. However, he is unpredictable at best and you should always watch your back around him, <name>. Use my crystal to contact me once you have located him.", ["objectivesText"] = "Find Millhouse Manastorm. Progress: Were you able to locate Millhouse?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 38134, 38135, 38176, 38177, 38178, 38732, 38759, 39030, 39058, 39096, 44987, 45724, 46114, 52879, 52884, 52887, 52902, 52931, 52948, 60260, 65290, 65309, 65328, 65341, 119139, 127857, 128820, 128862, 131828, 131840, 137659, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 158666, 159123, 159147, 159148, 159149, 159150, 160083, 160084, 160085, 160086, 160093, 160094, 160095, 160096, 182077, 198611, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630, 249699, 253178 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 111553, ["questType"] = "standard", ["sourceQuests"] = { 42508 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 10, ["flags"] = 0 } }, [