[42522] = { ["id"] = 42522, ["name"] = "Leader of the Illidari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 37447, 42510, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "Illidan has officially placed you in charge, <name>. The Illidari are now yours. Meet me upstairs. We will let everyone know together.", ["objectivesText"] = "Head upstairs and take your place as the new leader of the Illidari.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.515, ["mapID"] = 721, ["npcID"] = 107723 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.515, ["mapID"] = 721, ["npcID"] = 107723 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.583, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 107723, ["questTurnInID"] = 107723, ["questType"] = "standard", ["sourceQuests"] = { 42510 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[42523] = { ["id"] = 42523, ["name"] = "Making Contact", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42524, 42525, 42526 }, ["description"] = "Now that we have recruited champions for our order, we can use the Scouting Map to complete vital assignments across the Broken Isles. Over the years our scouts have kept a close eye on hunters that might one day be added to our ranks. One such hunter, Lenara, was on her way to Trueshot Lodge when she was attacked. I suggest that we send Loren Stormhoof on a mission to rescue her. He may be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Lenara Needs Help.\" Progress: How is the mission proceeding?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42519 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42524] = { ["id"] = 42524, ["name"] = "Recruiting The Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42523, 42525, 42526 }, ["description"] = "Our champions acquired the talents of Recruiter Lenara, an extraordinary archer. She can hit the smallest of targets at extended ranges. Her arrows never miss. Speak to her now and train a squad of archers .", ["objectivesText"] = "Speak to Recruiter Lenara and train a troop of archers. Progress: How did the training go?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42523 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42525] = { ["id"] = 42525, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42523, 42524, 42526 }, ["description"] = "It's time to send our newly trained archers out into the field. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Troops in the Field.\" Progress: How did it go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42524 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42526] = { ["id"] = 42526, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42523, 42524, 42525 }, ["description"] = "We are very fortunate to have come across Survivalist Bahn. He spent his younger years living off the land in Pandaria, relying on the native flora and fauna to survive. His firsthand experience with building from limited resources could really help shape Trueshot Lodge into something great. Speak to him now and see what he can do for us.", ["objectivesText"] = "Speak to Survivalist Bahn in Trueshot Lodge. Progress: Have you spoken with Survivalist Bahn yet?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42525 }, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42533] = { ["id"] = 42533, ["name"] = "The Ruined Kingdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["series"] = { 42534 }, ["description"] = "So the Lich King has revealed the second of the Four Horsemen... it appears that not even kings may rest as the world burns around them. So be it, Deathlord. I will send Nazgrim and Thassarian to meet you at the fallen kingdom of Stromgarde. Prince Galen Trollbane holds the key to the tomb of his father, a famous sword known as Trol'kalar. In order to raise the king as the second of the Four Horsemen, we will need to gain entrance to the tomb. Do what you must to persuade Galen assist us...", ["objectivesText"] = "Speak with Prince Galen Trollbane in Stromgarde.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 7543 } }, ["questGiverID"] = 93437, ["questType"] = "standard", ["sourceQuests"] = { 43268, 43539 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14 },
[42534] = { ["id"] = 42534, ["name"] = "Our Oldest Enemies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["series"] = { 42533 }, ["description"] = "I will grant the Ebon Blade access to my father's tomb. First though, I must ask a favor. I have taken up the sword and banner of my father. I have reclaimed Stromgarde with its former citizens as my guard. Yet, one task remains. Witherbark invaders have blockaded themselves in the former mage district of the city. My men have suffered heavy losses at their vile hands. Cut them down to the last! Bring me their heads and I shall give you what you seek. You have my word as the King of Stromgarde.", ["objectivesText"] = "Collect 15 Witherbark Troll heads. Progress: Do you have the heads of my enemies? I want to look upon each and every face...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128402, 128403, 138142, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 42533 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14 },
[42535] = { ["id"] = 42535, ["name"] = "Death... and Decay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "My family has fought the Witherbark trolls for generations... their presence in Arathi has always been a curse upon the land. I want to drive them out of Stromgarde for good! Destroy their supplies and we shall give them no incentive to return. Blight their supplies... or whatever it is you death knights do to defile things. I care not. Just make sure that it is done!", ["objectivesText"] = "Blight 10 Witherbark Supplies .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 42533 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14 },
[42536] = { ["id"] = 42536, ["name"] = "Regicide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Galen Trollbane is a fool if he thinks that he can betray the Ebon Blade. I have had enough of his games. The fallen prince wastes our time playing the king of a ruined throne, while heroes sacrifice their lives to save this world. If Galen Trollbane will not open the tomb of his father, then we must take the sword and do it ourselves. If he chooses to resist, so be it.", ["objectivesText"] = "Obtain Trol'kalar from Prince Galen Trollbane. Progress: We need the sword Trol'kalar to open this tomb. Have you found it?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128402, 128403, 138148, 139506, 139673, 139676, 139680, 140517, 140923, 237936, 237937, 237938, 237939 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.2088, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["sourceQuests"] = { 42534, 42535 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14 },
[42537] = { ["id"] = 42537, ["name"] = "The King Rises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "King Thoras was one of the greatest warriors this world has known. His people loved him and his enemies feared him. He only ever spoke truth, often saying the words others were afraid to speak. King Thoras lived a life of war and he certainly deserves the peace of death. But this is not a man who would sleep peacefully while the world around him burns. The time has come, Deathlord, to welcome the last true King of Stromgarde into the arms of the dead and damned.", ["objectivesText"] = "Raise King Thoras Trollbane as a Death Knight. Progress: King Trollbane was a great man. He will be a powerful ally against the threat of the Burning Legion.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.2088, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questTurnInID"] = 108042, ["questType"] = "standard", ["sourceQuests"] = { 42536 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[42539] = { ["id"] = 42539, ["name"] = "Cloak and Dagger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568, 42627 }, ["series"] = { 42501, 42502, 42503, 42568 }, ["description"] = "<The cultists seem to have a base of operations in Darkshire. At least Althea Ebonlocke is a member, but it is likely that the entire Night Watch has been compromised.> <The best course of action for now is to retrieve the dark implements for their ritual and make an attempt on Althea's life. Garona will have to wait.>", ["objectivesText"] = "Retrieve the Skull of the Innocent , the Blood of the Innocent , and make an attempt on Althea Ebonlocke's life in Darkshire.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 2000, 127837, 128476, 128479, 128870, 128872, 136786, 138102, 138112, 138113, 139506, 139739, 139742, 139746, 140517, 140931, 173527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 42503 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
