[42567] = { ["id"] = 42567, ["name"] = "Cursed to Wither", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 42756 }, ["description"] = "So Cedonu said he saw nightfallen going into Leyhollow? I don't like the sound of that. Grandfather seems to be holding his own, but the archmage and I will keep an eye on him. You go investigate our caves.", ["objectivesText"] = "Find the nightfallen that entered Leyhollow.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90738, ["x"] = 0.499, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91131, ["x"] = 0.482, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 38014, 38015 }, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42568] = { ["id"] = 42568, ["name"] = "Preparation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568, 42627 }, ["series"] = { 42501, 42502, 42503, 42539 }, ["description"] = "<With Althea's escape there is only one place to go: Stormwind.> <If Garona is keeping a similar pace on the cult's trail, she's bound to be making preparations to enter the city herself.> <Finding her is paramount before moving into the city.>", ["objectivesText"] = "Find Garona Halforcen outside Stormwind. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128479, 128870, 128872, 173532, 211946 }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 42539 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 37 },
[42583] = { ["id"] = 42583, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 42516 }, ["description"] = "The Legion's defeat cannot be accomplished alone. To win this war, we must work together, just as we did in ancient times. To begin, we must recruit more druids to our aid. Speak to the troll Zen'tabra and the night elf Naralex. Both of them are accomplished druids. They will gladly defend the Dreamgrove.", ["objectivesText"] = "Recruit Zen'tabra and Naralex.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.446, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 42516 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42584] = { ["id"] = 42584, ["name"] = "Sister Lilith", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "We will need more allies on our side before we can be effective, Archdruid. A skilled dryad by the name of Sister Lilith is on her way to the Dreamgrove, but we've received word that she may be in trouble. Send Zen'tabra to her aid.", ["objectivesText"] = "Use the Scouting Map and complete the mission \"Sister Lilith\". Progress: Do not delay. Sister Lilith is in trouble.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 42583 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42585] = { ["id"] = 42585, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "In our champions' travels, they made contact with Sister Lilith, a fearless leader among the Laughing Sisters. She is revered among the dryads as a seasoned warrior and a demanding teacher. She will serve as an excellent recruiter. Speak to her now, and recruit some Treants.", ["objectivesText"] = "Speak to Sister Lilith and recruit some Treants. Progress: Additional troops will be very useful for the missions ahead.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 42584 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42586] = { ["id"] = 42586, ["name"] = "A Glade Defense", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "We have a new mission that needs our attention, Archdruid. Deep in the forests of Val'sharah, a small druidic outpost known as Shal'doren Grove is under attack by satyrs. Send our champions to deal with this threat at once, <name>. We cannot allow these satyr incursions to grow unchecked!", ["objectivesText"] = "Use the Scouting Map and complete the mission,\"A Glade Defense.\" Progress: The satyrs are growing bolder with every day.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 42585 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42588] = { ["id"] = 42588, ["name"] = "Branching Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "Leafbeard is known as the Storied for good reason. It is said that he remembers tales from before the Sundering. After examining the inscribed leaf that our champions recovered, he may be able to provide new knowledge and improvements for the grove. Go take it to him now.", ["objectivesText"] = "Speak to Leafbeard the Storied at the Dreamgrove in Val'sharah. Progress: It is said that Leafbeard never forgets anything.", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["ends"] = { { ["x"] = 0.526, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 98002 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.526, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 98002, ["questTurnInID"] = 98002, ["questType"] = "standard", ["sourceQuests"] = { 42586 }, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[42590] = { ["id"] = 42590, ["name"] = "Moozy's Reunion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39323, 39572, 42590 }, ["description"] = "You will never know how thankful we are to you, <race>. Because of you, Moozy and my husband are safe. I won't let either of them out of my sight! I am sorry to ask one last favor of you, but do you think you could find my mother and bring her here so she can see that her grandchild is safe? Her name is Ethel, and her home is on the northern bluff of Thunder Totem.", ["objectivesText"] = "Find Ethel Waterwise and reunite her with her family at the Hammer's Cradle in Thunder Totem. Progress: Thank you for your kindness. Truly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 245453 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96084, ["x"] = 0.4, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96084, ["x"] = 0.4, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["sourceQuests"] = { 39572 }, ["questLines"] = { { ["id"] = 5914, ["name"] = "Moozy's Family Reunion", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750 },
[42593] = { ["id"] = 42593, ["name"] = "The Arcane Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 627, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42594, 42801 }, ["description"] = "Getting into the Black Temple is going to be tricky. Following the break-in by the Council of the Black Harvest, Akama had his Sha'tari priests erect a holy barrier. It prevents my teleportation. However, I might know a way to bypass those protections and take us directly to the Temple Summit. Long ago, I had a... liaison with a certain high elf wizard named Lan'dalock. He later joined the Kirin Tor. If you were to ask him very nicely, and drop my name, I am certain that he would help.", ["objectivesText"] = "Locate Archmage Lan'dalock at the Violet Citadel in Dalaran.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.487, ["mapID"] = 720, ["npcID"] = 98632 } }, ["ends"] = { { ["x"] = 0.599, ["y"] = 0.487, ["mapID"] = 720, ["npcID"] = 98632 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.599, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98632, ["questTurnInID"] = 98632, ["questType"] = "standard", ["sourceQuests"] = { 42522 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42594] = { ["id"] = 42594, ["name"] = "Move Like No Other", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42593, 42801 }, ["description"] = "Sorry about the holographic projection... I literally need to be in two places at once these days. A holy barrier that protects against fel magic, you say? I have just the thing to bypass it and enable Malevolence's teleport. <The high elf rummages around in his pack, a shocked look quickly coming over his face.> Sneaky! Look there... that imp just made off with it!", ["objectivesText"] = "Chase down the Sneaky Imp and recover the Grimoire of Arcane Ways . Progress: Did Archmage Lan'dalock prove useful, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124125, 127830, 128832, 138111, 138139, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.26, ["y"] = 0.52, ["mapID"] = 627, ["npcID"] = 107968 } }, ["ends"] = { { ["x"] = 0.26, ["y"] = 0.52, ["mapID"] = 627, ["npcID"] = 107968 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.26, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 107968, ["questTurnInID"] = 107968, ["questType"] = "standard", ["sourceQuests"] = { 42593 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42595] = { ["id"] = 42595, ["name"] = "Shaman Shrine - Azsuna Water 01 - DGK", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[42596] = { ["id"] = 42596, ["name"] = "Mountainstrider Round-Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42596, 42622, 42630 }, ["description"] = "Stranger! You are the one I have heard of? When the kerfuffle with the drogbar happened, some of the young moose ran off! I can't chase them down or the others might wander off as well. Could you bring them back here?", ["objectivesText"] = "Find 3 Frightened Mountainstriders and return them to Liza Galestride 's stable. Progress: The moose are already broken. Just hop in the saddle and you can bring them here to me!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.535, ["y"] = 0.457, ["mapID"] = 750, ["npcID"] = 97854 } }, ["ends"] = { { ["x"] = 0.535, ["y"] = 0.457, ["mapID"] = 750, ["npcID"] = 97854 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.535, ["y"] = 0.457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 97854, ["questTurnInID"] = 97854, ["questType"] = "standard", ["sourceQuests"] = { 38909 }, ["questLines"] = { { ["id"] = 5915, ["name"] = "Thunder Totem Troubles", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[42597] = { ["id"] = 42597, ["name"] = "Odyn's Summons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "Odyn would like to speak to you at once, my liege. He is convinced that as you have grown in power you are ready to take direct command of his armies and would like to begin preparations.", ["objectivesText"] = "Speak to Odyn in Skyhold.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112663 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 112663, ["questType"] = "standard", ["sourceQuests"] = { 40585 }, ["nextQuests"] = { 42598 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[42598] = { ["id"] = 42598, ["name"] = "Champions of Skyhold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "You will soon command one of the greatest armies in existence, but before my own Valarjar follow your every command you must prove your ability to lead. Speak to the two vrykul champions who ascended into these halls with you and tell them it is time for you to assume your duties as Odyn 's chosen.", ["objectivesText"] = "Recruit Ragnvald Drakeborn and Finna Bjornsdottir.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.847, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.847, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.847 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 42597 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[42601] = { ["id"] = 42601, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42602, 42603, 42608 }, ["description"] = "We are very fortunate to have come across Archivist Melinda. She is somewhat of an anomaly, as not many from her race choose our path. What makes her even more unique is her meticulous study of our craft. Her knowledge will be unsurpassed. Speak to her now and seek her council. With her help, we can surely strengthen the council.", ["objectivesText"] = "Speak to Archivist Melinda in Dreadscar Rift. Progress: Archivist Melinda's skills will allow us to make certain upgrades to Dreadscar Rift.", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["ends"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.663, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 106199, ["questTurnInID"] = 106199, ["questType"] = "standard", ["sourceQuests"] = { 42602 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[42602] = { ["id"] = 42602, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42601, 42603, 42608 }, ["description"] = "It's time to send our newly trained imps out into the field. Look at the Dreadscar Battle Plans and send your champions and troops on a routine scouting mission.", ["objectivesText"] = "Use the Dreadscar Battle Plans and complete the mission, \"Troops in Training\". Progress: How did it go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["ends"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.663, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 106199, ["questTurnInID"] = 106199, ["questType"] = "standard", ["sourceQuests"] = { 41797 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[42603] = { ["id"] = 42603, ["name"] = "Information at Any Cost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42601, 42602, 42608 }, ["description"] = "Now that you've found other warlocks that are willing to aid your cause, we can use the Dreadscar Battle Plans to complete vital assignments across the Broken Isles. If we wish to rebuild the council, we must start by locating its missing members. Let us send Ritssyn and Calydus to interrogate the Burning Legion's minions. They might have information that will help us locate the missing council members.", ["objectivesText"] = "Use the Dreadscar Battle Plans and complete the mission \"Information at Any Cost\". Progress: How is the mission proceeding?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["ends"] = { { ["x"] = 0.663, ["y"] = 0.462, ["mapID"] = 717, ["npcID"] = 106199 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.663, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 106199, ["questTurnInID"] = 106199, ["questType"] = "standard", ["sourceQuests"] = { 42608 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
