[42622] = { ["id"] = 42622, ["name"] = "Ceremonial Drums", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 750, ["storyline"] = { 42596, 42622, 42630 }, ["description"] = "Those foolish calves! They've made off with our ceremonial drums again, treating them as toys... as... common drums! Can you help me find them? They must be scattered to all corners of Thunder Totem by now, discarded as soon as the fun dries up.", ["objectivesText"] = "Find 4 Large, 4 Medium, and 4 Small Ceremonial Drums in Thunder Totem. Progress: Can you feel the beat?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138197, 138198, 138199, 245405 }, ["starts"] = { { ["x"] = 0.534, ["y"] = 0.78, ["mapID"] = 652, ["npcID"] = 108017 } }, ["ends"] = { { ["x"] = 0.534, ["y"] = 0.78, ["mapID"] = 652, ["npcID"] = 108017 } }, ["coords"] = { ["mapID"] = 652, ["x"] = 0.534, ["y"] = 0.78 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 108017, ["questTurnInID"] = 108017, ["questType"] = "standard", ["sourceQuests"] = { 39992 }, ["questLines"] = { { ["id"] = 5915, ["name"] = "Thunder Totem Troubles", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750 },
