[42627] = { ["id"] = 42627, ["name"] = "The Unseen Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 42503, 42539, 42568, 42627 }, ["description"] = "Stormwind is too important to fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own. The two of us will have to handle this while there's still time. Use extreme caution. The entire city is on edge from murmurs of the cult's activities, and we're already kill on sight. The other Shadows spoke highly of your skills. Are you in?", ["objectivesText"] = "Help Garona take out the Veiled Hand cultists in Stormwind.", ["rewardGold"] = 21450, ["rewardXP"] = 2125, ["rewardItems"] = { 128479, 128870, 128872, 139178 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questTurnInID"] = 107979, ["questType"] = "standard", ["sourceQuests"] = { 42568 }, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42630] = { ["id"] = 42630, ["name"] = "Bolas Bastion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42596, 42622, 42630 }, ["description"] = "I received word that a coven of harpies and their rocs plan to attack in force. They'll be coming from the mountains to the north. Use one of the bolas launchers and I'll man the other. Quick!", ["objectivesText"] = "Slay 42 Coven attackers. Progress: Let's show those harpies why they shouldn't even think about attacking Thunder Totem!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.43, ["y"] = 0.393, ["mapID"] = 750, ["npcID"] = 107660 } }, ["ends"] = { { ["x"] = 0.43, ["y"] = 0.393, ["mapID"] = 750, ["npcID"] = 107660 } }, ["coords"] = { ["mapID"] = 750, ["x"] = 0.43, ["y"] = 0.393 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questGiverID"] = 107660, ["questTurnInID"] = 107660, ["questType"] = "standard", ["sourceQuests"] = { 39387 }, ["questLines"] = { { ["id"] = 5915, ["name"] = "Thunder Totem Troubles", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
