[42634] = { ["id"] = 42634, ["name"] = "Confrontation at the Black Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 39741 }, ["description"] = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers. I will need but a moment to summon a gateway. Stand back, please.", ["objectivesText"] = "Use the Gateway to the Black Temple and confront Akama .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.594, ["y"] = 0.505, ["mapID"] = 720, ["npcID"] = 98632 } }, ["ends"] = { { ["x"] = 0.594, ["y"] = 0.505, ["mapID"] = 720, ["npcID"] = 98632 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.594, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98632, ["questTurnInID"] = 98632, ["questType"] = "dungeon", ["sourceQuests"] = { 42801 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42635] = { ["id"] = 42635, ["name"] = "The Mystery of Dreyrgrot", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["series"] = { 42639, 42641 }, ["description"] = "Well met, good chap! I was on my way to study the local murlocs when I stumbled upon these most peculiar ruins. Those pirates over yonder arrived first, and it appears they've unleashed some ancient evil. I would be remiss to let such an evil run rampant, but we should learn more of it before we proceed, lest we end up like those chaps. I spied the crew bringing back some tablets from the ruins. If you can bring them to me, I may be able to decipher the nature of this evil.", ["objectivesText"] = "Gather 4 Ancient Dreyrgrot tablets from the pirate ships outside of Dreyrgrot. Progress: How goes the hunt for knowledge?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138149 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42636] = { ["id"] = 42636, ["name"] = "WANTED: Arcanist Shal'iman", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42636 }, ["objectivesText"] = "Arcanist Shal'iman slain.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141868 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Arcanist Shal'iman slain.", ["amount"] = 1, ["type"] = 0, ["objectID"] = 107657, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[42639] = { ["id"] = 42639, ["name"] = "A Stone of Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["series"] = { 42635, 42641 }, ["description"] = "Unfortunately, we may have another problem. That mist seeping out of the ruins has affected the looting pirates. It's driven them quite mad. Only one of them seems to be unaffected - a captainly fellow with a very fine hat. He wears a large ruby amulet, which I believe protects him from the mist. You'll need it if you are to enter the tomb. He may not give it up willingly.", ["objectivesText"] = "Collect Broketooth's Ruby Amulet from Captain Broketooth on the ships near Dreyrgrot. Progress: We will need the amulet's protection to proceed.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138150 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42640] = { ["id"] = 42640, ["name"] = "The Value of Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["description"] = "This crate is filled with relics from the nearby ruins. The pirates have discarded them, likely thinking they're of little value. The Explorers' League would probably appreciate if you retrieved these relics for them to study.", ["objectivesText"] = "Gather 7 Crates of Ancient Relics from the waters outside Dreyrgrot. Progress: What's this?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138151 }, ["starts"] = { { ["x"] = 0.755, ["y"] = 0.508, ["mapID"] = 634, ["objectID"] = 250990 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42641] = { ["id"] = 42641, ["name"] = "What the Bonespeakers Buried", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["series"] = { 42635, 42639 }, ["description"] = "Most Fascinating! It would appear that we're dealing with our very own vrykul vampyr! All we have encountered have been of blood elven descent, but it has long been theorized that the vrykul have suffered the curse as well. It's too bad he's awake - I would dearly like a subject to study. Oh well, guess there's nothing for it. Take this stake and put it through the old chap's heart. I'm pretty sure that should do the trick.", ["objectivesText"] = "Use the Sharp Wooden Stake to kill Blood-Thane Lucard in Dreyrgrot.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129329, 129357, 129358, 129359, 129360, 138190 }, ["rewardChoices"] = { 129329, 129357, 129358, 129359, 129360 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42635, 42639 }, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42645] = { ["id"] = 42645, ["name"] = "Spilling Bad Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["description"] = "Ending the evil of the Blood Prince will be a boon to this land, but we can't just allow these crazed corsairs to run amok. I'm afraid there is no choice but to put them to the sword. Carry out this noble deed, my good fellow, and we will celebrate with a nice warm lager.", ["objectivesText"] = "Kill 8 Blood-Crazed Swashbucklers in Dreyrgrot.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42635, 42639 }, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
