[42650] = { ["id"] = 42650, ["name"] = "Break the Bonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "The Bonespeaker mystics used these heirlooms to tie my soul to this world. Under their curse, my soul could not enter the Halls of Valor. Find the soul pyre in Haustvald and throw my belongings into the flames. The fire that bound my soul through their foul magic will be the same fire that undoes this bond!", ["objectivesText"] = "Throw Svergan's Belongings into the Soul Pyre and complete the Ritual of Unbinding. Progress: Is it done yet, CONCUSSED?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 138204 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42194 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42651] = { ["id"] = 42651, ["name"] = "Svergan's Promise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "I thank you for doing this for me. I swore an oath to protect the Gjallarhorn with my life, and so I did. You must tell Hymdall that his Gjallarhorn was devoured by the great worm, Jorhuttam! It devoured an entire army of my men who were swallowed whole trying to fend off the beast. Find Jorhuttam and you will find the horn!", ["objectivesText"] = "Return to Hymdall in Skyhold.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 106720, ["questType"] = "standard", ["sourceQuests"] = { 42650 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
