[42654] = { ["id"] = 42654, ["name"] = "Darkheart Thicket: Nightmare Oak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "Blacksmith Kyriel is no stranger to the Farstriders. He has forged countless arrows for us in the past, using his knowledge of unique materials to help build better, stronger ammo. He's efficient and gifted, making the most of scarce materials. Using a single branch from a corrupted ancient, he can craft thousands of arrows.", ["objectivesText"] = "Collect Nightmare Oak from Oakheart within the dungeon, Darkheart Thicket. Progress: Have you recovered the oak yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 138270 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.45475, ["y"] = 0.22525 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 42405 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42655] = { ["id"] = 42655, ["name"] = "Ore Under the Sea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "If we want to bring the fight to Hakkar, my rangers are going to need arrows and ammo that are capable of piercing the thick, magic-resistant hides of his hounds. There's a versatile smith in Dalaran who does incredible work with both bows and blades alike. He uses azure ore in his creations, which can only be found below sea level. Due to its proximity to leystone, the ore is often overlooked, but in an expert smith's hands, it can be smelted into something nearly indestructible.", ["objectivesText"] = "Mine Azure Ore from deposits found in the water off the coast of Suramar. Progress: Have you mined the ore yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 44050, 109076, 131811, 138273, 141605 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.45475, ["y"] = 0.22525 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42405 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42656] = { ["id"] = 42656, ["name"] = "Azure Weaponry", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "Take the materials to Blacksmith Kyriel in Dalaran, and he'll use them to craft whatever weapons he can. As I mentioned before, he's skilled and efficient, so you shouldn't have to wait long. When his work is complete, speak to Shandris Feathermoon about getting the weapons enchanted.", ["objectivesText"] = "Find Blacksmith Kyriel in Dalaran. Progress: We will need special weapons if we wish to take down Hakkar and his hounds.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 138274 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.45475, ["y"] = 0.22525 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42654, 42655 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42657] = { ["id"] = 42657, ["name"] = "Meeting in Moonclaw Vale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42133, 42658, 42659 }, ["description"] = "Lyana Stardust still lingers in a vale that has been overrun by demons. Despite its current start of upheaval, she refuses to abandon her home. The strength and stubbornness she exhibits in the face of an enemy are also traits that shine through in her enchantments. We want our weapons to be as strong and stubborn as she is. Meet her in Moonclaw Vale, and see if she can work her magic with the weapons that Kyriel has crafted for us.", ["objectivesText"] = "Find Lyana Stardust in Val'sharah.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.466571, ["y"] = 0.345143 }, ["mapCandidates"] = { ["npc"] = { 641, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42408, 42656, 91616 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42658] = { ["id"] = 42658, ["name"] = "Delicate Enchantments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42133, 42657, 42659 }, ["description"] = "As I'm sure you've noticed, demons have taken over the vale. Their arrival has forced many of my fellow druids to flee their homes, but I refuse to go down without a fight. Despite all this, I'm happy to provide enchantments for your weapons, but you should know that it is a delicate process that takes time and concentration, something I have little of lately. If you're willing to shelter me from attackers, I will certainly do my best to enchant your weapons.", ["objectivesText"] = "Protect Lyana Stardust while she enchants the azure weaponry. Progress: Enchanting your weapons will require a great deal of power and concentration.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42657 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42659] = { ["id"] = 42659, ["name"] = "In Defense of Dalaran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42133, 42657, 42658 }, ["description"] = "We have everything we need to set the trap for Hakkar. Archmage Khadgar will summon a portal to the Violet Hold. Once inside, he will begin to channel his essence into the arcane vessel at your command. Our allies will be armed with the weapons you brought them, ready to fight when Hakkar takes the bait.", ["objectivesText"] = "Enter the Violet Hold through Khadgar's portal, and defeat Hakkar the Houndmaster .", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139707, 142056, 142057, 142061, 142062, 142064 }, ["rewardChoices"] = { 142056, 142057, 142061, 142062, 142064 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42133, 43182, 44680 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[42660] = { ["id"] = 42660, ["name"] = "Vault of the Wardens: Matters of the Heart", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["description"] = "I have made considerable progress with the Bloodstone, thanks in part to your extensive testing. The stone feeds on blood to grow in power, but its ability to control a demon comes from consuming a corrupted heart; the more powerful, the better. Within the Vault of the Wardens you'll find someone with such a heart.", ["objectivesText"] = "Collect a Felsworn Heart from Cordana within The Vault of the Wardens dungeon. Progress: The Bloodstone will grow in power after consuming Cordana's heart.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 138989, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.541, ["y"] = 0.349, ["mapID"] = 717, ["npcID"] = 104732 } }, ["ends"] = { { ["x"] = 0.541, ["y"] = 0.349, ["mapID"] = 717, ["npcID"] = 104732 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.541, ["y"] = 0.349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 104732, ["questTurnInID"] = 104732, ["questType"] = "dungeon", ["sourceQuests"] = { 41751 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
