[42663] = { ["id"] = 42663, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42126, 42127, 42175, 42687, 42696, 42703 }, ["description"] = "The Tirisgarde has been defunct for ages. To defeat the Burning Legion, we must first recruit the greatest champions of our class to fight by our side. Two powerful archmages, Archmage Kalec and Archmage Modera, have come to help us succeed. Speak to them and enlist their aid.", ["objectivesText"] = "Recruit Archmage Kalec and Archmage Modera.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.381, ["mapID"] = 735, ["npcID"] = 102700 } }, ["ends"] = { { ["x"] = 0.553, ["y"] = 0.381, ["mapID"] = 735, ["npcID"] = 102700 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.553, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 102700, ["questTurnInID"] = 102700, ["questType"] = "standard", ["sourceQuests"] = { 42175 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
