[42677] = { ["id"] = 42677, ["name"] = "Things Gaardoun Needs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42679, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that. Time to put your new champions to the test. I'm sure it will be a grueling mission.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Things Gaardoun Needs\". Progress: Did they come back already with whatever it is that Gaardoun needs?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.576, ["mapID"] = 720, ["npcID"] = 103761 } }, ["ends"] = { { ["x"] = 0.593, ["y"] = 0.576, ["mapID"] = 720, ["npcID"] = 103761 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.593, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 103761, ["questTurnInID"] = 103761, ["questType"] = "standard", ["sourceQuests"] = { 42695, 42697 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 25, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42678] = { ["id"] = 42678, ["name"] = "Black Rook Hold: Into Black Rook Hold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42680, 43251, 43252 }, ["description"] = "This thing is ancient. Just turning the pages risks them disintegrating in my hands. Here, I have found it. An entry about the Raven's Eye . <Valeera traces her finger from left to right above the page. A look of discovery comes over her features, which is quickly replaced by a frown.> It says here that the last person to have possession of the eye was Lord Ravencrest himself. You are going to have to go into Black Rook Hold and take it from him.", ["objectivesText"] = "Gather a group and enter Black Rook Hold to take the Raven's Eye from Dantalionax. Progress: <name>, were you successful? Do you have the Raven's Eye ?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139319, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 110164, ["questType"] = "dungeon", ["sourceQuests"] = { 43251, 43252 }, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[42679] = { ["id"] = 42679, ["name"] = "Broken Warriors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "It's important that we increase our numbers. Trust me, I know these things. Battlelord Gaardoun and his Ashtongue warriors are our best bet to quickly accomplish such a task. You should speak with him and let him know just what kind of broken you want trained.", ["objectivesText"] = "Speak with Battlelord Gaardoun and train Ashtongue Warriors . Progress: How are the new Ashtongue troops coming along?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.587, ["mapID"] = 720, ["npcID"] = 103761 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.587, ["mapID"] = 720, ["npcID"] = 103761 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.591, ["y"] = 0.587 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 103761, ["questTurnInID"] = 103761, ["questType"] = "standard", ["sourceQuests"] = { 42677 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42680] = { ["id"] = 42680, ["name"] = "Deciphering the Letter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42678, 43251, 43252 }, ["description"] = "We have the Raven's Eye. Use it, <name>. Decipher the SI:7 letter. We must know what secrets it contains!", ["objectivesText"] = "Use the Raven's Eye to decipher the encrypted SI:7 Letter. Progress: Why do you hesitate? Decipher the note.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.755, ["mapID"] = 626, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.409, ["y"] = 0.755, ["mapID"] = 626, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.409, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 42678 }, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[42681] = { ["id"] = 42681, ["name"] = "Loramus, Is That You?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42682, 42683, 44087, 44161 }, ["description"] = "Belath Dawnblade has given us a strange scouting report from the Felblaze Ingress in Azsuna. The dreadlord, Razelikh the Defiler has returned to the world. That's not the odd part, though. Strangely, he's sometimes going around killing the other demons and calling himself, Loramus! Last we knew, our demon hunter brother, Loramus Thalipedes sacrificed himself to defeat Razelikh, whom he'd been possessed by. Your champions and Ashtongue warriors need to go to Azsuna and find out what is going on.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Loramus, Is That You?\". Progress: Odd. That is all I have to say about the situation.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.576, ["mapID"] = 720, ["npcID"] = 103761 } }, ["ends"] = { { ["x"] = 0.593, ["y"] = 0.576, ["mapID"] = 720, ["npcID"] = 103761 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.593, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 103761, ["questTurnInID"] = 103761, ["questType"] = "standard", ["sourceQuests"] = { 42679 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 27, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42682] = { ["id"] = 42682, ["name"] = "Additional Accoutrements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42683, 44087, 44161 }, ["description"] = "I heard a rumor that you are going to attempt to make contact with Illidan's immortal demon soul in the Twisting Nether. You are going to need many magical things. I have taken the luxury of putting together a potential list for you. I do so hope that it proves helpful, <handsome/gorgeous>.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Additional Accoutrements\". Progress: Have they come back yet with everything we need for the ritual?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.599, ["y"] = 0.487, ["mapID"] = 720, ["npcID"] = 98632 } }, ["ends"] = { { ["x"] = 0.599, ["y"] = 0.487, ["mapID"] = 720, ["npcID"] = 98632 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.599, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98632, ["questTurnInID"] = 98632, ["questType"] = "standard", ["sourceQuests"] = { 42683 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 29, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42683] = { ["id"] = 42683, ["name"] = "Demonic Improvements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 44087, 44161 }, ["description"] = "Having Loramus back will work greatly to our advantage, despite the fact that he's trapped inside Razelikh's body... and also that the demon sometimes takes control. Still, he was one of our most powerful demon hunters. And now, he also has the knowledge of a dreadlord at his disposal. I think we should have him share his knowledge and wisdom with us to improve our odds in this war.", ["objectivesText"] = "Listen to Loramus Thalipedes ' story and then upgrade your Class Hall. Progress: What did Loramus the Dreadlord have to say?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.588, ["mapID"] = 720, ["npcID"] = 103761 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.588, ["mapID"] = 720, ["npcID"] = 103761 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.591, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 103761, ["questTurnInID"] = 103761, ["questType"] = "standard", ["sourceQuests"] = { 42681 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 28, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, 