[42684] = { ["id"] = 42684, ["name"] = "Throwing SI:7 Off the Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43249, 43250, 43253, 43468 }, ["description"] = "SI:7 is dogging our heels at every turn. We must make certain that they do not catch wind of what we are up to. To that end, I have some suggestions for you in the form of missions. Send your champions, assign your forces, it matters little to me. The important thing is that we keep them out of Val'sharah and away from Black Rook Hold. At least until we can decipher that damned letter.", ["objectivesText"] = "Use the Scouting Map and complete the \"Throwing SI:7 Off the Trail\" missions.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.408, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 44181 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
