[42687] = { ["id"] = 42687, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42126, 42127, 42175, 42663, 42696, 42703 }, ["description"] = "Our troops are ready! It's time to test them out in the field. We've received word of survivors near the Broken Shore, but the area is still crawling with Legion. Send our troops quickly to help with the rescue!", ["objectivesText"] = "Complete the mission, \"Troops in the Field.\" Progress: How did it go?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.809, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["ends"] = { { ["x"] = 0.809, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.809, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108515, ["questTurnInID"] = 108515, ["questType"] = "standard", ["sourceQuests"] = { 42127 }, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42688] = { ["id"] = 42688, ["name"] = "Mrgls of Endearment", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41143, 42396, 42688, 42728 }, ["series"] = { 42396 }, ["description"] = "Mrmlgr! Mrglr rlmgrg mlrgr! Mrlgmr... <Phin shows you a flaw on the side of the pearl.> Mmlrgmlr rlmgr grlmrmlg mglrmglr. Mlrgmrl rmglr? Mlgrmglr! Gmmlrgmrl mlrgmlr lrglrmgrl lrlgllrlm mglrlr grlm-grlm. <Phin makes a pinching motion with his hand.> Mrlgmlgr mgrlmlgr? Mlrgmlr gmrlmglr Mrgrlilgrl.", ["objectivesText"] = "???? Progress: Mrglmrlg? Mrgmlr. Rmlgrmlrg!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138238, 138239, 138240, 138241, 141935 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107302, ["x"] = 0.155, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107302, ["x"] = 0.155, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.155, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42396 }, ["questLines"] = { { ["id"] = 5815, ["name"] = "Mglrgrs Of Our Grmlgrlr", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42689] = { ["id"] = 42689, ["name"] = "Knowing Our Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42399, 42400, 42401, 42404, 42406, 42691 }, ["description"] = "If we hope to gain the upper hand against Hakkar, we need to find out more about these hounds that he's breeding and pinpoint their weaknesses. I know of a warlock that studies demons extensively. Maybe she has seen some of these hounds, and knows how to defeat them.", ["objectivesText"] = "Speak to Kira Iresoul in Azsuna.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 630, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42404 }, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
