[42691] = { ["id"] = 42691, ["name"] = "Leyworm Lure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42399, 42400, 42401, 42404, 42406, 42689 }, ["description"] = "Felhounds are attracted to magic, young ones especially. They get a whiff and go into a feeding frenzy! You're not quite as enticing as a mage, so you'll need to cover yourself in something that can fool a felhound into thinking you're its next magical meal. Leyworm entrails should do the trick.", ["objectivesText"] = "Collect Leyworm Entrails from worms within Leyhollow in Azsuna. Progress: Leyworm entrails are filled with flecks of magical material that will be irresistible to a fledgling felhound.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138206 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42689 }, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42692] = { ["id"] = 42692, ["name"] = "Children of Nar'thalas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42692, 42693, 42694 }, ["description"] = "Hi! <name>, right? The archmages in Dalaran said we might see you down here. My brother and I are here on a reconnaissance mission. We're looking for our parents. We've lived our entire lives thinking that our family was killed in Azsuna several thousand years ago, but look around! Most of the elves here are ghosts. Olothil's been searching through books for clues as to why, but we could use some help.", ["objectivesText"] = "Find three Ancient Highborne Tomes in the Ruins of Nar'thalas. Progress: We've hit a dead end here. Any luck out there?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89326, ["x"] = 0.532, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89326, ["x"] = 0.532, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5752, ["name"] = "Kirin Tor Reconnaissance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42693] = { ["id"] = 42693, ["name"] = "You Never Know Until You Scry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42692, 42693, 42694 }, ["description"] = "In order to find the spirits of our family, I will need materials to scry their location. The naga carry magical trinkets imbued with ley energy that is better-attuned to this land than anything we have in Dalaran. If I had a few of those, I could do some real scrying.", ["objectivesText"] = "Obtain 3 Hatecoil Glyptics . Progress: I would have brought my own spell foci if SOMEONE hadn't been rushing me...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138296 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 108328, ["x"] = 0.534, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 108328, ["x"] = 0.534, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5752, ["name"] = "Kirin Tor Reconnaissance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42694] = { ["id"] = 42694, ["name"] = "Back from the Dead", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42692, 42693, 42694 }, ["description"] = "<Olothil sighs.> My sister tries my patience sometimes. No matter. I've identified a few locations that our parents might be. I shall search in this area with Kallistia. You've already helped us so much... would you help us look to the east? You can use my scrying orb to see the locations that our ritual has uncovered.", ["objectivesText"] = "Use the Scrying Orb to determine potential locations of night elf spirits, then go rescue them. Progress: Thank you for your aid, <class>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 69777, 138819, 138820, 138821, 138822, 138823, 138824, 138837 }, ["rewardChoices"] = { 138819, 138820, 138821, 138822, 138823, 138824 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 108328, ["x"] = 0.534, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 108328, ["x"] = 0.534, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42692, 42693 }, ["questLines"] = { { ["id"] = 5752, ["name"] = "Kirin Tor Reconnaissance", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
