[42707] = { ["id"] = 42707, ["name"] = "Eye of Azshara: A Magical Affliction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["series"] = { 42493, 42520, 42734, 42940 }, ["description"] = "Archmage Vargoth's betrayal is an unimaginable loss to our cause, <name>. We will have to deal with him, but first Meryl's condition has become dire. Unfortunately it is not an illness at all, but a magical attack of fel origin. It may be his old nemesis Kathra'natir is behind it. We need to buy him time. The Eye of Azshara contains a vast store of arcane energy from Queen Azshara herself. If we could obtain a vial of water from the Wrath of Azshara's body, that will sustain him for a while.", ["objectivesText"] = "Fill a vial with arcane water from the Wrath of Azshara. Progress: Have you obtained a vial of arcane water yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 127857, 128820, 128862, 138271, 138272, 138783, 139506, 139749, 139751, 139754, 140517, 140927 }, ["starts"] = { { ["x"] = 0.717, ["y"] = 0.549, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.717, ["y"] = 0.549, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.717, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "dungeon", ["sourceQuests"] = { 42520 }, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42708] = { ["id"] = 42708, ["name"] = "A Personal Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "If you have a moment, Deathlord... there is a personal matter I would like to speak with you about. Some time ago, a brother of the Ebon Blade was imprisoned beneath the ruins of Lordaeron by the Dark Lady. Sylvanas has refused all attempts to negotiate his release. Now, our world faces destruction and the time for diplomacy has passed. Koltira Deathweaver cannot fight the Burning Legion in chains. So we will break them.", ["objectivesText"] = "Rescue Koltira Deathweaver from Undercity. Progress: The time has come to release Koltira Deathweaver from captivity.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.56, ["y"] = 0.307, ["mapID"] = 648, ["npcID"] = 93456 } }, ["ends"] = { { ["x"] = 0.56, ["y"] = 0.307, ["mapID"] = 648, ["npcID"] = 93456 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.56, ["y"] = 0.307 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93456, ["questTurnInID"] = 93456, ["questType"] = "standard", ["sourceQuests"] = { 42537 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
