[42719] = { ["id"] = 42719, ["name"] = "Eye of Azshara: Cleansing the Dreamway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Brightwing has lots of friends. I like friends! But you know who isn't Brightwing 's friend? Scary monsters from the nightmare! They hurt Brightwing 's allies, and they made the grove all yucky! This place needs to be cleansed, but I'm all out of magic. Can you bring Brightwing some purified water to help? You'll have to go far, far away... to the Eye of Azshara where the naga live.", ["objectivesText"] = "Collect 25 Rarefied Water from the naga in the Eye of Azshara, and defeat the Wrath of Azshara . Progress: Poor, poor flowers...", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138993 }, ["starts"] = { { ["x"] = 0.396, ["y"] = 0.455, ["mapID"] = 715, ["npcID"] = 98008 } }, ["ends"] = { { ["x"] = 0.396, ["y"] = 0.455, ["mapID"] = 715, ["npcID"] = 98008 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.396, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 98008, ["questTurnInID"] = 98008, ["questType"] = "dungeon", ["sourceQuests"] = { 42045 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 15, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
[42722] = { ["id"] = 42722, ["name"] = "Friends in Cages", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "< Korine stomps her foot and refuses to move.> They put my friends in cages! Make the bad men stop hurting them! They take them out the garden and they never come back! < Korine gestures stubbornly toward the door.> I am not going home until they do!", ["objectivesText"] = "Release 3 Nightborne Citizens from their captivity. Progress: Did you let them out?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138301, 140255, 141677, 141951, 141952, 142054 }, ["rewardChoices"] = { 130209 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.411, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40745 }, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42723] = { ["id"] = 42723, ["name"] = "Eye of Azshara: A Tough Shell", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8040, ["mapID"] = 630, ["storyline"] = { 42723 }, ["objectivesText"] = "Jaggen-Ra Wrath of Azshara slain", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8040 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Jaggen-Ra", ["amount"] = 1, ["type"] = 0, ["objectID"] = 101467, ["orderIndex"] = 0 }, { ["text"] = "Wrath of Azshara slain", ["amount"] = 1, ["type"] = 0, ["objectID"] = 96028, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["db2QuestInfoID"] = 137, ["db2QuestInfoName"] = "Dungeon World Quest" },
[42725] = { ["id"] = 42725, ["name"] = "Sharing the Wealth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42725 }, ["description"] = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. I imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine. With the presence of the demons came rationing. There are many who do not have enough to sustain themselves. Bring me as much Arcwine as you can carry. I will see that it gets to the right people.", ["objectivesText"] = "Collect 20 Bottles of Arcwine .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Bottles of Arcwine Delivered to Deline", ["amount"] = 20, ["type"] = 1, ["objectID"] = 137295, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[42728] = { ["id"] = 42728, ["name"] = "A Mlrglrmg For Grlmrgl", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41143, 42396, 42688, 42728 }, ["series"] = { 41143 }, ["description"] = "Mrglm, rmgrlg mrlgmrl. Grmrglmrl mlrmglrgr mlrmlgr! Rglrmgl rmglrgmlr mlmlglr mglgrgrlm - grlgmr, mlgr - lrgmlrgr rmgrmlg mlrg! Mlrgr? Mrlgmrlgmrl rmglrmglr! < Pearlhunter Phin makes a stabbing motion.>", ["objectivesText"] = "????", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107302, ["x"] = 0.155, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108389, ["x"] = 0.152, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.155, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42688 }, ["questLines"] = { { ["id"] = 5815, ["name"] = "Mglrgrs Of Our Grmlgrlr", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42730] = { ["id"] = 42730, ["name"] = "Noggenfogger's Reasonable Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible. Marin's asking for a hefty amount of Aethril . He said something about you recently holding a blade to his throat and that he's simply returning the favor. Of course, if you would rather, I can eliminate him.", ["objectivesText"] = "Collect 20 Aethril . Progress: Heya, <name>, you have those reagents I requested? You scratch my back, and well... I'll pay someone to scratch yours.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 127837 }, ["starts"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.408, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 44181 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[42731] = { ["id"] = 42731, ["name"] = "Working With the Wardens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42131, 42669, 42735, 42736, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "As much as we might not like it, we need the aid of the Wardens if we're to locate the Sargerite Keystone. They took it from you when we were all imprisoned in the vault. With Maiev missing, their current leader is Sira Moonwarden. On your behalf, I have agreed that we will assist them in tracking down some of the more powerful creatures that escaped from the Vault of the Wardens. In return, she will direct us to where we need to go to get the Keystone.", ["objectivesText"] = "Use the Scouting Map and complete the \"Working With the Wardens\" missions. Progress: Is Sira happy with our progress? Not that I care, but we do need her help.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.585, ["y"] = 0.516, ["mapID"] = 720, ["npcID"] = 108782 } }, ["ends"] = { { ["x"] = 0.585, ["y"] = 0.516, ["mapID"] = 720, ["npcID"] = 108782 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.585, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108782, ["questTurnInID"] = 108782, ["questType"] = "standard", ["sourceQuests"] = { 42131 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42733] = { ["id"] = 42733, ["name"] = "A Very Special Kind of Fuel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42754, 42810 }, ["description"] = "All Legion constructs, including the Fel Hammer, are powered by souls. If we are going to take the command center to Niskara, we are going to need some very powerful souls, indeed! You are a very creative person, <name>. I am certain that you will find a way to get what we need from the right sorts of creatures.", ["objectivesText"] = "Collect 15 Sovereign Souls from bosses in Legion dungeons. Progress: <name>, do you have what Allari asked you to harvest for fuel?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 138482 }, ["starts"] = { { ["x"] = 0.556, ["y"] = 0.501, ["mapID"] = 721, ["npcID"] = 98648 } }, ["ends"] = { { ["x"] = 0.556, ["y"] = 0.501, ["mapID"] = 721, ["npcID"] = 98648 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.556, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98648, ["questTurnInID"] = 98648, ["questType"] = "dungeon", ["sourceQuests"] = { 44694 }, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[42734] = { ["id"] = 42734, ["name"] = "Into the Oculus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["series"] = { 42493, 42520, 42707, 42940 }, ["description"] = "I fear Kathra'natir is behind the attack on Meryl. We have little time to act. I suspect Archmage Vargoth's involvement is no coincidence. While it greatly pains me to destroy an archmage of his caliber and worse, someone I once called friend, we cannot permit his betrayal to stand unpunished. It is time to follow him into the Oculus.", ["objectivesText"] = "Talk to Archmage Khadgar when you are ready to travel to the Oculus.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 97919, 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 142056, 142059, 142060 }, ["rewardChoices"] = { 142056, 142059, 142060 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.717, ["y"] = 0.548, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.717, ["y"] = 0.548, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.717, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "standard", ["sourceQuests"] = { 44689 }, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42735] = { ["id"] = 42735, ["name"] = "Malace in Vrykul Land", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42736, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "I did some recon in Stormheim. What I discovered is that the Tideskorn are a tribe of vrykul who have been cut-off from the sea by their kvaldir brethren. Many of the Tideskorn have pledged their services to the Legion and become Felskorn. Malace Shade was last seen heading toward the Felskorn Warcamp. It is likely that she was captured. I have arranged a flight to Stormheim for you. When you are ready, you can use the gateway to travel to Dalaran and speak with Aludane Whitecloud at Krasus' Landing.", ["objectivesText"] = "Grab a flight from Aludane Whitecloud and find Malace Shade in Stormheim.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.576, ["y"] = 0.533, ["mapID"] = 720, ["npcID"] = 108782 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 8022 } }, ["questGiverID"] = 108782, ["questType"] = "standard", ["sourceQuests"] = { 42787 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42736] = { ["id"] = 42736, ["name"] = "Rune Ruination", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "A cage wasn't enough to hold me, so the vrykul ensorcelled these runestones to trap me in here. Each is powered by a different Felskorn rune. Unfortunately, they gave the runes to different guardians, who have all scattered to different places around Stormheim. So, if Sira said that you could have your precious keystone back, you're first going to have to get me out of here. Then, we'll see.", ["objectivesText"] = "Deactivate the three runestones to set Malace free.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138111 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 42735 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
