[42740] = { ["id"] = 42740, ["name"] = "The Battle for Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40517, 40519, 42782, 43806 }, ["description"] = "This is your vessel, <name>. She's a fine ship; been through many a campaign. Speak with the ship's captain when you're ready to depart. Good luck out there. We've received few reports about what's happening at the Broken Shore, but I'd wager King Varian has matters well in hand.", ["objectivesText"] = "Take the third fleet ship to the Broken Shore.", ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292 }, ["rewardChoices"] = { 136586, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107934, ["x"] = 0.368, ["y"] = 0.43 }, { ["mapID"] = 84, ["npcID"] = 108916, ["x"] = 0.19, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100395, ["x"] = 0.202, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 42782 }, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
