[42747] = { ["id"] = 42747, ["name"] = "Where the Wildkin Are", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42748, 42750, 42751, 42786 }, ["description"] = "Owlbeasts are often charged with protecting places of importance to Elune. But if her influence over them wanes or is cut off, the creatures can become dangerous. These wildkin, unfortunately, must be dealt with. The recent disturbances in Val'sharah have driven these creatures to madness. Once an individual is lost, there is only one way to address the problem. I cannot bring myself to kill one of Elune's creations, but I know what must be done.", ["objectivesText"] = "Slay 10 Owlbeasts and 8 Undulating Boneslimes within Lostlight Grotto.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42748] = { ["id"] = 42748, ["name"] = "Emerald Sisters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42747, 42750, 42751, 42786 }, ["description"] = "The owlbeasts here are disconnected from Elune. A contingent of dryads went into their territory to find out what went wrong, but none of them have returned. I fear the worst, and I believe they are in need of rescue. While I try to learn if the owlkin can be saved, I would appreciate your help in freeing any Sisters you find in the grotto.", ["objectivesText"] = "Rescue 6 Sisters of the Moon in Lostlight Grotto.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42749] = { ["id"] = 42749, ["name"] = "Strange Bedfellows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "The reason why I came out here was to capture or kill a fel lord named, Lochaber . I am no longer in a capturing mood. I'll grab my weapon and then head up to the bridge in front of the Gates of Valor. That place is a scary mess full of Felskorn vrykul and demons. How do you think I got caught? So, I'd rather not go back in there. But, I think I know a way to get the demon to come out to us.", ["objectivesText"] = "Meet Malace Shade on the bridge at the Gates of Valor and then slay Lochaber .", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 108576, ["questType"] = "standard", ["sourceQuests"] = { 42737, 42738, 42739 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[42750] = { ["id"] = 42750, ["name"] = "Dreamcatcher", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42747, 42748, 42751, 42786 }, ["description"] = "I cannot hold on for much longer... I brought a dreamcatcher with me. I was to use it to steal the magic from owlbeast totems. It is the only way to break the barrier where they hold Keeper Remulos. Please help where I have failed.", ["objectivesText"] = "Charge the dreamcatcher using owlbeast totems in Lostlight Grotto. Progress: Leirana ? Oh no...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 87399, 109585, 138433 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108358, ["x"] = 0.595, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42748 }, ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42751] = { ["id"] = 42751, ["name"] = "Moon Reaver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42751 }, ["series"] = { 42747, 42748, 42750, 42786 }, ["description"] = "We must not delay! If Keeper Remulos is in danger, he must be protected. With the dreamcatcher, we should be able to enter the lair of the owlbeast Boneflux . It must be defeated so Keeper Remulos can break free!", ["objectivesText"] = "Defeat Boneflux and rescue Keeper Remulos in The Undergorge.", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 245258 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108887, ["x"] = 0.594, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 42747, 42748, 42750 } },
[42752] = { ["id"] = 42752, ["name"] = "Vault of the Wardens: Vault Break-In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42753, 42775, 42776, 42787 }, ["description"] = "Sargerite Keystone awaits.>", ["objectivesText"] = "Retrieve the Sargerite Keystone . Progress: Were you successful, <name>? Have you recovered the Sargerite Keystone ?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 124125, 127830, 128832, 138111, 138397, 139506, 139715, 139718, 139722, 140378, 140517 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 42749 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42753] = { ["id"] = 42753, ["name"] = "Vault of the Wardens: Vault Break-In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42775, 42776, 42787 }, ["description"] = "The Wardens made good on the deal. All that's left is to travel to the Isle of the Watchers off of southwest Azsuna. There, you'll need to break back in to the Vault of the Wardens and descend down into its lowest recesses where we were once imprisoned. Within the so-called Vault of the Betrayer, where the Wardens once held the Master's corpse, you'll find Sargerite Keystone . Good luck, .", ["objectivesText"] = "Retrieve the Sargerite Keystone . Progress: Were you successful, <name>? Have you recovered the Sargerite Keystone ?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 138397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 42749 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42754] = { ["id"] = 42754, ["name"] = "Jump-Capable", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42733, 42810 }, ["description"] = "While it is true that the Fel Hammer is powered, sadly, its jump engines are non-functional. If we are going to invade a demon world, we're going to have to make the command center jump-capable. We need some replacement parts. Luckily for us, the Legion brought a couple of command centers and soul engines along with them to the Broken Isles. You will find them at Faronaar in Azsuna, and at Felsoul Hold in Suramar.", ["objectivesText"] = "Collect a Fel Engine Injector , a Soul Configuration Matrix , a Fel Engine Ignition , and a Vile Spirit Converter . Progress: It's vile the way this thing operates. The whole thing is powered by souls... you do NOT want to know what happens to them.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 127830, 128832, 138111, 138483, 138484, 138485, 139404, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.74, ["mapID"] = 721, ["npcID"] = 98646 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.74, ["mapID"] = 721, ["npcID"] = 98646 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.59, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98646, ["questTurnInID"] = 98646, ["questType"] = "standard", ["sourceQuests"] = { 42733 }, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
