[42756] = { ["id"] = 42756, ["name"] = "Hunger's End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 42567 }, ["description"] = "I am weak. The hunger is devastating, my friend. I understand now why your dragon rests in these pools. <cough, cough> I came to warn you but... it looks like I was too late. I hear him outside now. Ael'Yith ... is... here...", ["objectivesText"] = "Kill Ael'Yith and his construct.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 133006, 133007, 133008, 133009, 133010, 133011, 133012, 133013, 133014, 133016, 133040, 133041, 133042, 133043, 133044, 133045, 133046, 133047, 133048, 133050, 141405, 246937 }, ["rewardChoices"] = { 133006, 133007, 133008, 133009, 133010, 133011, 133012, 133013, 133014, 133016, 133040, 133041, 133042, 133043, 133044, 133045, 133046, 133047, 133048, 133050 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91131, ["x"] = 0.482, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42567 }, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
