[42758] = { ["id"] = 42758, ["name"] = "You're Gonna Need A Bigger Boat!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Pirates' Day", ["expansion"] = 6, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 42758 }, ["description"] = "Sharks. They be the biggest threat to us pirates. Well... after scurvy, ninjas, and the judicial system. Luckily, we only have to deal wit' sharks today. Go pull some teeth out of their ugly faces 'n bring 'em back to me. I needs a new necklace!", ["objectivesText"] = "Tweet #778033680409178112 Pull 33 Razor-Sharp Shark Teeth. Progress: I require thirty-three Razor-Sharp Shark Teeth. Do not try to short me, lad.", ["rewardItems"] = { 138411, 138414 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 28048, ["x"] = 0.410667, ["y"] = 0.797333 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 28048, ["x"] = 0.410667, ["y"] = 0.797333 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.797333 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[42762] = { ["id"] = 42762, ["name"] = "The Wanderer's Companion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42765, 42766, 42767, 42768, 42868, 42957 }, ["description"] = "Fu Zan... a wise choice. If the legends are true, its powers will be essential to our cause. We believe that the staff possessed by the Monkey King could be fabled Fu Zan, yet no one has seen him with the weapon for over a year. the Monkey King was last spotted at Tian Monastery. Be prepared for anything! He is known for being... less than forthcoming with his answers. Tak-Tak , a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", ["objectivesText"] = "Speak to Tak-Tak to fly to Tian Monastery and meet with the Monkey King .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948 }, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 40636, 43973, 44424 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
