[42765] = { ["id"] = 42765, ["name"] = "The Trial at the Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42766, 42767, 42768, 42868, 42957 }, ["description"] = "My staff was strong and mighty without peer, but since I not its master, in time it would soon disappear. The staff was a gift from the Jade Serpent, Yu'lon, but for only a single task. With my work finished, to her again it has passed. Yu'lon be the staff's keeper, holding it for those who are blessed. To her we now go now, to announce your request.", ["objectivesText"] = "Accompany the Monkey King to the Temple of the Jade Serpent and obtain Fu Zan, the Wanderer's Companion.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128937, 128938, 133948 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questTurnInID"] = 109187, ["questType"] = "standard", ["sourceQuests"] = { 42868 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[42766] = { ["id"] = 42766, ["name"] = "The Riddle of the Barrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42767, 42768, 42868, 42957 }, ["description"] = "My weapon is great when in a fight, It's even handy when you sit for a bite. My favorite flask I've tied on it, hanging from a cord, The brews within are some of the best that I've ever scored. If you truly seek my weapon then bring me something nice to put into my belly, A powerful brew is what I want, something strong and smelly.", ["objectivesText"] = "Search for the objects the Monkey King has described in his riddle. Progress: Ah, it returns. Has the wikkit brought what I'm looking for?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 133948, 138624 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questTurnInID"] = 108700, ["questType"] = "standard", ["sourceQuests"] = { 42762 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[42767] = { ["id"] = 42767, ["name"] = "The Riddle of the Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42768, 42868, 42957 }, ["description"] = "My weapon is strong but not for attacking, Protecting the weak is what it's enacting. In the valley are people who till the land from dawn to night, The fruits of their labor, you must show me tonight. Sacks of grain are what I require, Not just any will do, only those kissed by a fire. Bring me what I seek.", ["objectivesText"] = "Search for the objects the Monkey King has described in his riddle. Progress: Ah, it returns. Has the wikkit brought what I'm looking for?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 133948, 138623, 173704 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questTurnInID"] = 108700, ["questType"] = "standard", ["sourceQuests"] = { 42762 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[42768] = { ["id"] = 42768, ["name"] = "The Riddle of Purity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42767, 42868, 42957 }, ["description"] = "Do you seek my weapon? Then you better answer my question. \"I seek something curvy and bendy but with no spine, It rushes and rushes leaving chaos behind. Sometimes it brings life, sometimes it brings death: A little is good, but a lot steals your breath. It's as common as dirt, but this part's obscure: This stuff comes from a pool that's known to be pure.\" Bring me what I seek.", ["objectivesText"] = "Search for the object the Monkey King has described in his riddle. Progress: Ah, it returns. Has the wikkit brought what I'm looking for?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138477, 173703 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questTurnInID"] = 108700, ["questType"] = "standard", ["sourceQuests"] = { 42762 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
