[42770] = { ["id"] = 42770, ["name"] = "Seeking Guidance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "Highlord Tirion may be gone, but the Ashbringer is still out there somewhere. Its power would devastate the Legion. We must find it! I wish it were as simple as returning to where Tirion fell. It could be anywhere on that infernal landscape by now. I believe an old friend can help us find the blade. I ask that you place your faith in me and journey to Uther's tomb in the Plaguelands. We will seek answers there.", ["objectivesText"] = "Meet Lord Maxwell Tyrosus at Uther's Tomb in Western Plaguelands.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 173537 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 22, 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["sourceQuests"] = { 40408, 44063, 44370 }, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22 },
[42771] = { ["id"] = 42771, ["name"] = "Keeping the Peace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "The lost souls roaming the cemetery grounds have been drawn to the realm of the living in the wake of the Light's disturbance. In truth, they merely seek comfort... as we all do in these dark times since Highlord Tirion's passing. However, their unrest threatens the very sanctity of the tomb we have sworn to protect. If we are to restore peace here, then they must be exorcised.", ["objectivesText"] = "Exorcise 9 spirits. Progress: Your aid is greatly appreciated.", ["rewardGold"] = 137400, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108778, ["x"] = 0.514, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108778, ["x"] = 0.514, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["sourceQuests"] = { 42770 }, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22 },
[42772] = { ["id"] = 42772, ["name"] = "Sacred Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "We must ensure that those buried here are never again disturbed. Their spirits' very presence only further perturbs the Light. This cannot continue. I must maintain this barrier to ensure none of the wayward souls enter the Lightbringer's resting place. If you can purify the graves themselves, this madness can finally cease.", ["objectivesText"] = "Purify the graveyards in Sorrow Hill. Progress: Have the graveyards been purified?", ["rewardGold"] = 137400, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108777, ["x"] = 0.514, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108777, ["x"] = 0.514, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["sourceQuests"] = { 42770 }, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22 },
[42773] = { ["id"] = 42773, ["name"] = "The Light Reveals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "We seek aid not from a living friend, but one who passed long ago. Uther the Lightbringer was more attuned to the subtleties of the Light than any paladin I've ever known. If we reach out to him, he may be able to help us find the Ashbringer. The ceremony has been prepared. Approach the tomb when you are ready.", ["objectivesText"] = "Commune with Uther the Lightbringer. Progress: We must do whatever it takes.", ["rewardGold"] = 103050, ["rewardXP"] = 1060, ["rewardItems"] = { 120978, 128823, 128866, 128867, 132204, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.5165, ["y"] = 0.8075 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["sourceQuests"] = { 42771 }, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22 },
