[42775] = { ["id"] = 42775, ["name"] = "The Crux of the Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42776, 42787 }, ["description"] = "We have Akama. Cordana Felsong has been eliminated. And, we have the Sargerite Keystone. Everything is falling into place. The honor is all yours, <name>.", ["objectivesText"] = "Place the Sargerite Keystone above the Scouting Map. Progress: No demon world is beyond our reach now.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.575, ["y"] = 0.533, ["mapID"] = 720, ["npcID"] = 108782 } }, ["ends"] = { { ["x"] = 0.575, ["y"] = 0.533, ["mapID"] = 720, ["npcID"] = 108782 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.575, ["y"] = 0.533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108782, ["questTurnInID"] = 108782, ["questType"] = "standard", ["sourceQuests"] = { 42752, 42753 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42776] = { ["id"] = 42776, ["name"] = "Two Worthies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42775, 42787 }, ["description"] = "As our forces grow, and our reach extends ever outward, you have need of more trusted companions to handle the most important of missions. The time has come for you to elevate two worthies into the ranks of your champions. It's my opinion that you should consider recruiting Belath and Malevolence. They have both proven themselves indispensable.", ["objectivesText"] = "Recruit Belath Dawnblade and Matron Mother Malevolence as your champions.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["x"] = 0.586, ["y"] = 0.588, ["mapID"] = 720, ["npcID"] = 108571 } }, ["ends"] = { { ["x"] = 0.586, ["y"] = 0.588, ["mapID"] = 720, ["npcID"] = 108571 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.586, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108571, ["questTurnInID"] = 108571, ["questType"] = "standard", ["sourceQuests"] = { 42775 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
