[42782] = { ["id"] = 42782, ["name"] = "To Be Prepared", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40517, 40519, 42740, 43806 }, ["description"] = "Allies from across Azeroth have come to Stormwind to support our efforts against the Burning Legion. Before you ship out, you should pay them a visit. Every bit of preparation helps!", ["objectivesText"] = "Visit Alliance forces in Stormwind Harbor. Progress: The Light protects those who protect themselves!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 59679, 59680, 59681, 59682, 59683, 59684, 65872, 65884, 65886, 138385, 138450, 139718, 141294 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107934, ["x"] = 0.368, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 108916, ["x"] = 0.19, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 40519 }, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
