[42787] = { ["id"] = 42787, ["name"] = "Deal With It Personally", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42775, 42776 }, ["description"] = "The way I see it, the Wardens owe us for all of those years we were imprisoned. Unfortunately, their new leader, Sira Moonwarden doesn't agree with my assessment. Even though your champions have already dealt with several of their escaped bounties, she wants more. In fact, as a sign of good faith, she's asking that you deal with it personally. You'll have to extinguish the flames of the kobold candles to summon forth the Devouring Darkness . The other two should be more straightforward.", ["objectivesText"] = "Kill the Devouring Darkness in Highmountain, Hertha Grimdottir in Suramar, and Theryssia in Val'sharah. Progress: How go your efforts to convince the Wardens to tell us where the Sargerite Keystone is located? If she doesn't tell us soon, I think we should consider other options where Sira Moonwarden is concerned.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121737, 124125, 127830, 128832, 130136, 131780, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.575, ["y"] = 0.532, ["mapID"] = 720, ["npcID"] = 108782 } }, ["ends"] = { { ["x"] = 0.575, ["y"] = 0.532, ["mapID"] = 720, ["npcID"] = 108782 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.575, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108782, ["questTurnInID"] = 108782, ["questType"] = "s