[42801] = { ["id"] = 42801, ["name"] = "Back in Black", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42593, 42594 }, ["description"] = "Before you head into the Black Temple, we need more information. The last thing we want is for you to teleport into a trap. We must discern their force structure, patrol schedule, new defenses, and what Akama eats for breakfast. <Belath grins.> I suggest you send our broken warriors to handle this. They can blend in with the rest of Akama's Ashtongue forces inside the temple. We'll get what we need to know from the ones that make it back. A champion handler or two can scout outside the temple.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Back in Black\". Progress: Any word from your troops that we sent to infiltrate the Black Temple?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 204985, 205188 }, ["starts"] = { { ["x"] = 0.575, ["y"] = 0.523, ["mapID"] = 720, ["npcID"] = 108782 } }, ["ends"] = { { ["x"] = 0.575, ["y"] = 0.523, ["mapID"] = 720, ["npcID"] = 108782 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.575, ["y"] = 0.523 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108782, ["questTurnInID"] = 108782, ["questType"] = "standard", ["sourceQuests"] = { 42594 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42802] = { ["id"] = 42802, ["name"] = "Securing Mardum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42808 }, ["description"] = "There has been increased demonic activity below on Mardum. There are still demons leftover down there from when we first invaded. To eliminate any threat to the Fel Hammer, it's time that they were destroyed.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Securing Mardum\".", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140378 }, ["starts"] = { { ["x"] = 0.595, ["y"] = 0.506, ["mapID"] = 720, ["npcID"] = 98632 } }, ["ends"] = { { ["x"] = 0.595, ["y"] = 0.506, ["mapID"] = 720, ["npcID"] = 98632 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.595, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98632, ["questTurnInID"] = 98632, ["questType"] = "standard", ["sourceQuests"] = { 39741, 42665 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
