[42808] = { ["id"] = 42808, ["name"] = "Green Adepts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42802 }, ["description"] = "As much as I would love us to finesse our way to victory, the cold, hard reality is that we need more powerful forces. We are already straining Gaardoun's ability to recruit more broken. But now that we have Ariana Fireheart , she can train new demon hunters for us.", ["objectivesText"] = "Speak with your Illidari recruiter, Ariana Fireheart .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.511, ["mapID"] = 720, ["npcID"] = 108782 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.511, ["mapID"] = 720, ["npcID"] = 108782 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.583, ["y"] = 0.511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108782, ["questTurnInID"] = 108782, ["questType"] = "standard", ["sourceQuests"] = { 42802 }, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42809] = { ["id"] = 42809, ["name"] = "The Invasion of Niskara", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42132, 42920, 43186 }, ["description"] = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready. Caria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara. It's time to begin the invasion and finish this once and for all.", ["objectivesText"] = "Activate the Fel Hammer's control console and complete the scenario, \"The Invasion of Niskara\". Progress: Finally, our plan of taking the fight directly to the demons is coming to fruition. You are making it all happen, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.74, ["mapID"] = 721, ["npcID"] = 98646 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.74, ["mapID"] = 721, ["npcID"] = 98646 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.59, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98646, ["questTurnInID"] = 98646, ["questType"] = "dungeon", ["sourceQuests"] = { 42810 }, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[42810] = { ["id"] = 42810, ["name"] = "A Final Offer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42733, 42754 }, ["description"] = "What was that? Sounds like something's outside. Something big... You'd better get up there, <name>!", ["objectivesText"] = "Investigate whatever is happening outside of the Fel Hammer. Progress: What happened?", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 127830, 128832, 137623, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.74, ["mapID"] = 721, ["npcID"] = 98646 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.74, ["mapID"] = 721, ["npcID"] = 98646 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.59, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98646, ["questTurnInID"] = 98646, ["questType"] = "standard", ["sourceQuests"] = { 42754 }, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[42811] = { ["id"] = 42811, ["name"] = "We Meet at Light's Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7796, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 38933, 39756, 42812 }, ["description"] = "We must put Highlord Tirion to rest. There is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel. Paladins the world over will join us for the ceremony. I know Tirion would want you there most of all.", ["objectivesText"] = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 140192 }, ["starts"] = { { ["x"] = 0.204, ["y"] = 0.614, ["mapID"] = 676, ["npcID"] = 91144 } }, ["ends"] = { { ["x"] = 0.204, ["y"] = 0.614, ["mapID"] = 676, ["npcID"] = 91144 } }, ["coords"] = { ["mapID"] = 676, ["x"] = 0.204, ["y"] = 0.614 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7796 } }, ["questGiverID"] = 91144, ["questTurnInID"] = 91144, ["questType"] = "standard", ["sourceQuests"] = { 38376, 42017, 42120 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42812] = { ["id"] = 42812, ["name"] = "We Meet at Light's Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 38933, 39756, 42811 }, ["description"] = "Before we march on the Broken Isles, <name>, we must put Highlord Tirion to rest. There is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel here. Paladins the world have gathered below for the ceremony. They await your arrival to begin the ceremony.", ["objectivesText"] = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 108956, ["x"] = 0.752, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 108956, ["x"] = 0.752, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questTurnInID"] = 108956, ["questType"] = "standard", ["sourceQuests"] = { 38376, 42017, 42120 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42814] = { ["id"] = 42814, ["name"] = "An Important Mission", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39214, 39654, 40585, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["series"] = { 38904, 39654, 41052, 42815 }, ["description"] = "Champion! I bear an urgent message from Danath Trollbane . He requests that you join him at Krasus' Landing. He has an urgent mission that requires your expertise!", ["objectivesText"] = "Speak with Danath Trollbane at Krasus' Landing in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["npcID"] = 108961 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 108961, ["questType"] = "standard", ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42815] = { ["id"] = 42815, ["name"] = "Return to the Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 695, ["storyline"] = { 39214, 39654, 40585, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["series"] = { 38904, 39654, 41052, 42814 }, ["description"] = "If I'm to assist in this war, I need firsthand information. I will fly to the Broken Shore and see the battlefield for myself. Your record as a proven commander is unquestioned, and you were there. I could use your insight. Will you accompany me to the Broken Shore? I don't anticipate engaging the enemy, but that close to the Fel Storm, one can never be sure.", ["objectivesText"] = "Take Danath's spare mount to the Broken Shore and provide assistance.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128288, 128289, 128908, 128910 }, ["starts"] = { { ["x"] = 0.746, ["y"] = 0.456, ["mapID"] = 627, ["npcID"] = 96183 } }, ["ends"] = { { ["x"] = 0.746, ["y"] = 0.456, ["mapID"] = 627, ["npcID"] = 96183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.746, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 96183, ["questTurnInID"] = 96183, ["questType"] = "standard", ["sourceQuests"] = { 42814 }, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[42818] = { ["id"] = 42818, ["name"] = "The Scarlet Assault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 804, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "The High Inquisitor of the Scarlet Crusade?! You will not find High Inquisitor Whitemane listed in the annals of history alongside the names of fallen heroes. Still... despite her madness and zealotry she held a bond to the Light unmatched by even the greatest paladins. There are few scarlet crusaders left on this world, but Scarlet Monastery is far from abandoned. The monastery now houses the most zealous and crazed crusaders the order has left. Success will require a full blown assault.", ["objectivesText"] = "Speak with Thassarian in Scarlet Monastery.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139538, 139673, 139676, 139680, 140517, 140763, 140923 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.511, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93437, ["questTurnInID"] = 93437, ["questType"] = "standard", ["sourceQuests"] = { 43572, 44082 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 804 },
