[42821] = { ["id"] = 42821, ["name"] = "Raising an Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8285, ["mapID"] = 804, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "We underestimated the number of scarlet crusaders still residing in the monastery. The battle for control of the cathedral is taking too long. It's time to take a more resourceful approach to the battle... Raise the fallen crusaders as ghouls and send them back into the battle against their brothers and sisters. The Scarlet Crusade will not be able to hold back the tide of undeath for long.", ["objectivesText"] = "Raise 12 Festering Ghouls from the corpses of Scarlet Crusaders. Progress: Have you completed your mission?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["npcID"] = 109221 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8285 } }, ["questGiverID"] = 109221, ["questType"] = "standard", ["sourceQuests"] = { 42818 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 804 },
[42823] = { ["id"] = 42823, ["name"] = "The Scarlet Commander", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8285, ["mapID"] = 805, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "There is only one more obstacle standing between us and the tomb of Sally Whitemane. High Commander Goodchilde guards the path to the tomb. Although he is a zealot and a murderer, he is still a hardened knight who has dedicated his life to the eradication of our kind. He should not be underestimated... Slay him and our work here will be nearly done.", ["objectivesText"] = "Slay High Commander Goodchilde . Progress: Has High Commander Goodchilde been slain?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["npcID"] = 109221 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8285 } }, ["questGiverID"] = 109221, ["questType"] = "standard", ["sourceQuests"] = { 42821, 42882 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 805 },
[42824] = { ["id"] = 42824, ["name"] = "The Zealot Rises", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "Sometimes the line between hero and villain is nothing more than perception. As High Inquisitor, Sally Whitemane saw herself as a champion of humanity in the war against the scourge. Yet under her leadership the Scarlet Crusade slew the living along with the undead. Death can bring a silent peace to the soul, but not for Sally Whitemane. Her death is one of regret and unrest. We will offer her the chance to atone for her crimes. The price will be high, but I have little doubt she will pay it.", ["objectivesText"] = "Raise Sally Whitemane as a Death Knight.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["npcID"] = 109221 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 109221, ["questType"] = "standard", ["sourceQuests"] = { 42823 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[42827] = { ["id"] = 42827, ["name"] = "Ancient Mana Chests 01", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[42828] = { ["id"] = 42828, ["name"] = "Moths to a Flame", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "No doubt you have noticed our guests. I have watched them for a time and seen how they are attracted to the tree. I do not know if they are harmful to our sapling, but we cannot take that chance. Collect a handful of the insects and bring them to me. I will examine them and determine if they are to be left alone.", ["objectivesText"] = "Collect 4 Underglow Locusts . Progress: Have you acquired a sufficient sampling?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42488 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42829] = { ["id"] = 42829, ["name"] = "Make an Entrance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "I need you to infiltrate the Twilight Vineyards and bring back something to deal with these insects. To do that, you will need a way to bypass the guards that keep the orchards secure. Ly'leth will be able to help us there. I will arrange to have her meet you near the entrance. Go quickly!", ["objectivesText"] = "Meet with Ly'leth Lunastre outside the Twilight Vineyards. Progress: Can I help you?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 139790, 140255, 140410, 141605, 141678, 141953, 141954, 180731 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42828 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42830] = { ["id"] = 42830, ["name"] = "Pest Management", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42830 }, ["objectivesText"] = "Shadescale Flyeaters collected Tattered Silkwings slain", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Shadescale Flyeaters collected", ["amount"] = 8, ["type"] = 0, ["objectID"] = 109068, ["orderIndex"] = 0 }, { ["text"] = "Tattered Silkwings slain", ["amount"] = 8, ["type"] = 0, ["objectID"] = 109180, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[42832] = { ["id"] = 42832, ["name"] = "The Fruit of Our Efforts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "It is my job to maintain appearances here. < Margaux smiles apologetically.> You will have to endure a little showmanship while I walk with you through the vineyard. It is the only way to avoid suspicion. I will try to help you as I can, but only when it is safe to do so. Come with me- our first stop is the tasting pavilion. There you can sample some of our work.", ["objectivesText"] = "Taste the Honeyed Infusion, Supple Nectar, and Unctuous Draught. Progress: Enjoying yourself?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140187, 140188, 140189, 140255, 140410, 141678, 141953, 141954 }, ["rewardChoices"] = { 140187, 140188, 140189 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42829 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42833] = { ["id"] = 42833, ["name"] = "How It's Made: Arcwine", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "< Margaux speaks in a hushed tone.> While we walk through the Vineyard, we may find time to exchange information. Try not to look alarmed at what you see, hm? < Margaux flashes a vacant, forced smile.> Shall we press on?", ["objectivesText"] = "Follow Margaux through the Vineyard. Exchange information where possible.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42832 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42834] = { ["id"] = 42834, ["name"] = "Intense Concentration", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "This is a rare treat, I hope you know. Not just anyone is allowed to stand on this hallowed ground. < Sylverin adjusts his cuffs in a dignified fashion.> To participate in the demonstration, simply take up an energy vessel and wade into the pool beside us. Catch the delicate dewdrops of Nightwell energy in the bowl as they fall- this is the only way one can safely manage its essence. Once your vessel is full, proceed to our demonstration cask and gently pour the amalgamation into it. Enjoy!", ["objectivesText"] = "Catch 15 drops of Nightwell Essence using an Energy Vessel . Progress: Having trouble?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42833 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42835] = { ["id"] = 42835, ["name"] = "The Old Fashioned Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "While you experienced the raw majesty that is Nightwell Infusion, Margaux was busy preparing another demonstration for you. Head across the bridge and to the left, then again across a bridge and to your right. You will find her on the juicing veranda. Enjoy the remainder of your tour! < Sylverin offers an intensely fake smile.>", ["objectivesText"] = "Participate in a juicing demonstration. Progress: Having fun?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42834 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42836] = { ["id"] = 42836, ["name"] = "Silkwing Sabotage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "Moths. Who ever heard of something so... barbaric! They are eating our crop and the mana wyrms do nothing to deter them. You. You seem capable. Deter these creatures so we can complete our harvest on schedule. Ahem. Please.", ["objectivesText"] = "Slay 8 Tattered Silkwings . Progress: Are you sure you took care of this situation?", ["rewardGold"] = 273848, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 }, { ["mapID"] = 680, ["npcID"] = 112653, ["x"] = 0.612, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42835 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42837] = { ["id"] = 42837, ["name"] = "Balance to Spare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "Our tour is just about over. I will let you loose to 'walk the orchard', as is proper at this stage. While you are there, you will notice a large number of mana wyrms floating about. I am certain the vineyard would not miss a handful of them. Good luck with your insect problem, friend. < Margaux smiles warmly at you.>", ["objectivesText"] = "Collect 8 Shadescale Flyeaters.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["rewardChoices"] = { 139790 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42835 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42838] = { ["id"] = 42838, ["name"] = "Reversal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "< Sylverin regards you uneasily.> I was meant to meet you and Margaux here so I could escort you from the Vineyard. My mistress Margaux is never late. I fear that something terrible may have happened. Please find her and make sure she is well.", ["objectivesText"] = "Locate Margaux . Progress: How did your trip to the Vineyard go?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42836, 42837 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42839] = { ["id"] = 42839, ["name"] = "Seek the Unsavory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "This is just... unspeakable. Margaux risked everything to get these mana wyrms to us. I cannot let it end this way. I need you to find someone who can make this right. Someone who will do whatever it takes to see Overseer Durant slain. Speak with Vanthir . I am certain he will know exactly who we need.", ["objectivesText"] = "Speak to Vanthir .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44084 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42840] = { ["id"] = 42840, ["name"] = "If Words Don't Work...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "Unless you have something worth risking my life for, I will not budge. Vanthir must have told you that my services do not come cheap. Let's say... enough mana to sustain me for a month. < Arluin looks smug, as if you could never agree to this request.>", ["objectivesText"] = "Bribe Arluin with 800 Ancient Mana. Progress: My price will not change. Do we have a deal?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141652, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43969 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42841] = { ["id"] = 42841, ["name"] = "A Big Score", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "I'm not rich in anything but information, but maybe that can be of use to someone with your skills. You helped me, now you can help yourself. The Magistrix receives a daily shipment of arcwine, which travels to the palace with a heavy escort. I can share the location, provided you leave me a cut of the goods. One of my men has infiltrated the group and will hold up the delivery long enough for you to strike.", ["objectivesText"] = "Attack the Magistrix's arcwine shipment and bring Arluin his cut of the stolen goods. Progress: Where's my cut?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42840 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[42842] = { ["id"] = 42842, ["name"] = "Ancient Mana Cap 01 Kel'danath's Flask", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[42844] = { ["id"] = 42844, ["name"] = "Growing Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["description"] = "Lord Maxwell Tyrosus has requested your presence back at the Sanctum of Light. Our campaign to defend the Broken Isles is getting under way, and we need you at the helm.", ["objectivesText"] = "Speak to Maxwell Tyrosus at the Sanctum of Light.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112701 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 112701, ["questType"] = "standard", ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42846] = { ["id"] = 42846, ["name"] = "The Blood Matriarch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42847, 42848, 42849, 42850 }, ["description"] = "I am but the first of many; you must find the holiest of paladins to champion our order. There is one other I believe deserves such an honor - Lady Liadrin, Matriarch of the Blood Knights. Go speak to her now.", ["objectivesText"] = "Enlist Lady Liadrin as a champion of the Order of the Silver Hand.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.724, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.498, ["y"] = 0.724, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.498, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 39696 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42847] = { ["id"] = 42847, ["name"] = "Dark Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42848, 42849, 42850 }, ["description"] = "Greetings, Highlord. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical - the storms above the Tomb of Sargeras are intensifying. We should send our champions to keep an eye on that region, and scour the area for possible survivors.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Dark Storms.\" Progress: How is the mission proceeding?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 31857 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 42846 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42848] = { ["id"] = 42848, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42847, 42849, 42850 }, ["description"] = "Commander Ansela is a grizzled war veteran and seasoned teacher. Many of our most valiant knights once trained under her. Go speak to her now, and recruit a squad of Squires .", ["objectivesText"] = "Speak to Commander Ansela and recruit a squad of Squires . Progress: Additional troops will be very useful for the missions ahead.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 42847 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42849] = { ["id"] = 42849, ["name"] = "Wrath and Justice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42847, 42848, 42850 }, ["description"] = "A new mission requires our attention, Highlord <name>. Hearthglen has come under attack by a small demon army. No doubt, they are testing our strength... and our patience. Strength we have in bounds, but my tolerance wears thin. I suggest we send our champions and troops to deal with this threat.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Wrath and Justice.\" Progress: We will show the enemy who they are dealing with.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 42848 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[42850] = { ["id"] = 42850, ["name"] = "Tech It Up a Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42847, 42848, 42849 }, ["description"] = "Alamande Graythorn is well known among scholars of the Light. He has long since retired from battle, but his mind is sharp as ever. I wouldn't be surprised if he could take a bout or two in a duel, either. Speak to him and see if he has any knowledge to share regarding the improvement of our order hall.", ["objectivesText"] = "Speak to Alamande Graythorn and choose a class hall upgrade. Progress: Did you learn anything?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 42849 }, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24 },
