[42866] = { ["id"] = 42866, ["name"] = "A Sign From The Sky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 627, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 44257 }, ["description"] = "Greetings, Highlord. I have important news to share with you. During my expedition to the Broken Shore, I saw with my own eyes an extraordinarily luminescent object emerge from the Felstorm. It fell down towards the coast of Suramar, cutting a swath through the tempest itself! From it I felt an incredible surge of power, before it vanished beyond the horizon. We need to bring news of this immediately to Archmage Khadgar .", ["objectivesText"] = "Speak to Archmage Khadgar in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.724, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.498, ["y"] = 0.724, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.498, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 42850 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[42867] = { ["id"] = 42867, ["name"] = "Meeting of the Silver Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42919 }, ["description"] = "The Light's Heart will be safe within our order's walls, but it bears dark tidings. We should gather the leaders of our order for a council. Go and speak to Lady Liadrin , Vindicator Boros , Justicar Julia Celeste , Arator the Redeemer, and Aponi Brightmane . We should seek their wisdom for the days ahead.", ["objectivesText"] = "Speak to Lady Liadrin , Vindicator Boros , Justicar Julia Celeste , Arator the Redeemer, and Aponi Brightmane . Progress: Have you gathered the council?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140763, 140929 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 44153 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24 },
[42868] = { ["id"] = 42868, ["name"] = "The Monkey King's Challenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42767, 42768, 42957 }, ["description"] = "You can roll, you can hit, even shoot flaming spit... But can your training you heed? Tasty brew's what I need! The goodies you've gathered are what you must mix, The instructions to follow will come from my lips. Just pass this final brewing lesson, And I will point you to my weapon.", ["objectivesText"] = "Help the Monkey King to complete his brew. Progress: Ah! This brew is grand! It's fit for a King!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 133948, 138477, 138623, 138624 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 42957 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[42869] = { ["id"] = 42869, ["name"] = "Eternal Vigil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<Kor'vas glances at your glaives, her eyes widening.> I'm excited to see what those can do in person! Maybe we can spar a bit before heading out on the next hunt? While you were gone we built a camp just off of this landing to help us watch over the Legion's movements. We should head there right away - Jace needed your help with something. It sounded big!", ["objectivesText"] = "Glide to Illidari Redoubt off of Krasus' Landing.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.743, ["y"] = 0.462, ["mapID"] = 627, ["npcID"] = 102799 } }, ["ends"] = { { ["x"] = 0.743, ["y"] = 0.462, ["mapID"] = 627, ["npcID"] = 102799 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.743, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102799, ["questTurnInID"] = 102799, ["questType"] = "standard", ["sourceQuests"] = { 39247, 40249, 41119, 41863 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
