[42872] = { ["id"] = 42872, ["name"] = "Securing the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "I was able to make contact with our forces on Mardum - they secured the Fel Hammer after our departure all those years ago and have held it ever since! Malevolence has utilized the ship's warp systems to transport the bulk of our forces aboard, but doing so greatly taxes what little power remains. I believe there to be a better way. Your glaives carry a piece of the power of Kil'jaeden - you should be able to use them to open a permanent gateway to the Fel Hammer.", ["objectivesText"] = "Use your glaives to rip open a gateway to the Fel Hammer in Mardum. Progress: Soon our forces will flow freely between the here and the Fel Hammer.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 127830, 128832 }, ["starts"] = { { ["x"] = 0.953, ["y"] = 0.666, ["mapID"] = 627, ["npcID"] = 109196 } }, ["ends"] = { { ["x"] = 0.953, ["y"] = 0.666, ["mapID"] = 627, ["npcID"] = 109196 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.953, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 109196, ["questTurnInID"] = 109196, ["questType"] = "standard", ["sourceQuests"] = { 42869 }, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
