[42882] = { ["id"] = 42882, ["name"] = "The Scarlet Massacre", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8285, ["mapID"] = 804, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "We have a single purpose here, to raise Sally Whitemane as a Death Knight of the Ebon Blade. Such is our goal and we will see it through. However, the Scarlet Crusade has terrorized the people of Azeroth long enough. Therefore, our work here this day will not be done until every crusader has fallen, every stone has crumbled, and every banner burned. Come, Deathlord, let us bring ruin upon the Scarlet Crusade.", ["objectivesText"] = "Slay 16 Scarlet Crusaders. Progress: The Scarlet Crusade shall burn.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["npcID"] = 109221 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8285 } }, ["questGiverID"] = 109221, ["questType"] = "standard", ["sourceQuests"] = { 42818 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 804 },
[42883] = { ["id"] = 42883, ["name"] = "All Grell Broke Loose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42857, 42865, 42883, 42884 }, ["description"] = "The grell are in a frenzy, attacking my brethren and destroying our village! Please, stranger, help us send these wicked miscreants to the soil.", ["objectivesText"] = "Slay 8 Wildeyed Undergrell in Grizzleweald. Progress: The grell can sometimes be a terrible nuisance.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5913, ["name"] = "Grizzleweald", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42884] = { ["id"] = 42884, ["name"] = "Grassroots Effort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42857, 42865, 42883, 42884 }, ["description"] = "When I arrived at my home, the front door was barred by magical roots. I was able to remove them, but few of my tribe possess the necessary ability to do so themselves. Take my staff. Its powers will easily disentangle the obstructing roots.", ["objectivesText"] = "Use Old Grizzelback's Staff to destroy 5 snarled brambles in Grizzleweald. Progress: My old bones need more rest than I would care to admit.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138815 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5913, ["name"] = "Grizzleweald", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[42885] = { ["id"] = 42885, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "Tracking down the dreadlord Balnazzar is our highest priority. Let us send defenders of our order to pinpoint his recent movements.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Nemesis.\" Progress: Were you able to find anything?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.508, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 42919 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24 },
[42886] = { ["id"] = 42886, ["name"] = "To Faronaar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 630, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42887, 42888, 42890, 43462 }, ["description"] = "We are keeping a close eye on Legion movements at Faronaar in Azsuna. Our intel suggests that a high-ranking lieutenant, possibly the dreadlord Balnazzar himself, masterminds the attacks in that region. This may be our chance to strike a blow at the Legion's leadership. Vindicator Boros commands our forces at the front. He would welcome your help, Highlord.", ["objectivesText"] = "Speak to Vindicator Boros along Old Coast Path.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 109356, ["x"] = 0.391333, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 42885, 42966, 42967, 42968 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42887] = { ["id"] = 42887, ["name"] = "This Is Retribution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42886, 42888, 42890, 43462 }, ["description"] = "Anger seethes within me like smoldering coals. One stoke, and that anger will flare into a roaring flame. The Legion's attack on Exodar was just the motivation I needed, Highlord. I've watched my brethren die for the last time. Now, I will be the one who does the killing. I WILL have justice! Help me, Highlord, and slay any demons you encounter in lower Faronaar.", ["objectivesText"] = "Kill 20 demons in lower Faronaar.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 109356, ["x"] = 0.391333, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93273, ["x"] = 0.306, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 42886 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[42888] = { ["id"] = 42888, ["name"] = "Communication Orbs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42886, 42887, 42890, 43462 }, ["description"] = "We have important work at hand, Highlord. Spread out across the legion camp are orbs that are vital to the Legion's planning and strategy. Destroying them will severely damage their efforts. I will go with you, Highlord, to see this through.", ["objectivesText"] = "Destroy 3 Legion Orbs. Progress: Without a means of communicating, our enemy will be crippled.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 109384, ["x"] = 0.306, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 109384, ["x"] = 0.306, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 109384, ["questType"] = "standard", ["sourceQuests"] = { 42887 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
