[42890] = { ["id"] = 42890, ["name"] = "The Codex of Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42886, 42887, 42888, 43462 }, ["description"] = "Boros is in serious trouble. The fel lord, Jarvox, guards the pit to the west. Boros is trapped in there, too. We need to defeat Jarvox, take the Codex of Command that he carries, and rescue Vindicator Boros . I am with you, Highlord!", ["objectivesText"] = "Collect 1 Codex of Command and rescue Vindicator Boros . Progress: Highlord, you have returned.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139388, 139506, 139690, 139693, 139697, 140517, 140929 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["npcID"] = 109384 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questGiverID"] = 109384, ["questType"] = "standard", ["sourceQuests"] = { 42888, 43462 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24 },
