[42931] = { ["id"] = 42931, ["name"] = "Where the Hammer Falls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42932, 42933, 42935, 42937 }, ["description"] = "You saved us all, shaman! Thank you! Thrall wants to dive right into the Maelstrom and retrieve the Doomhammer, but I worry - he was badly wounded in that last fight, and that demon Geth'xun may still be alive down there. We should go with him. Hop on Stormbeak when you're ready and we'll track down that artifact!", ["objectivesText"] = "Use Stormbeak to fly into the Maelstrom with Thrall and Mylra.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.500667, ["y"] = 0.393333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 41335, 43945, 44006 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42932] = { ["id"] = 42932, ["name"] = "What the Stonemother Knows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42933, 42935, 42937 }, ["description"] = "We must split up. I am still badly wounded from my encounter with Geth'xun, and I don't want to appear weak before the Stonemother. This task falls to you. Travel to Therazane 's Throne and speak to Therazane herself. Find out if she has seen the Doomhammer. Help her if she asks. She is dangerous and mercurial, but this is her realm, and without her aid we will find nothing.", ["objectivesText"] = "Travel to Therazane 's Throne and speak with Therazane the Stonemother.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 42931 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42933] = { ["id"] = 42933, ["name"] = "The Troggs that Fel to Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42932, 42935, 42937 }, ["description"] = "\"Demons\" you say? A \"Burning Legion?\" Hrmph! Nothing burns here but for my ire, shaman, and if these monsters think to corrupt my domain, they will be crushed beneath my dainty beautiful feet! I have not seen this hammer of yours, but the stone troggs witnessed everything that fell from the sky. Moreover, they've been running amok in the Pale Roost ever since the green fire landed near their home. Be a dear and lay waste to the Felrock Troggs west of here. Perhaps you can get one of them to talk.", ["objectivesText"] = "Slay 25 Felrock Troggs in the Pale Roost. Progress: Well? Have you given them a solid thrashing?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 42932 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42935] = { ["id"] = 42935, ["name"] = "Stone Drake Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42932, 42933, 42937 }, ["description"] = "When that demon of yours fell into my realm he must have done something to the troggs. They were never a threat to my beloved stone drakes before. Now they're loose all over the Pale Roost, subduing drakes on the ground. Put a stop to this insult at once, and free those drakes! They may be of use to us later.", ["objectivesText"] = "Rescue 6 Stone Drakes in the Pale Roost by defeating the troggs that torment them. Progress: What of my precious little drakes, hm?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 42932 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42936] = { ["id"] = 42936, ["name"] = "Clutch Play", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["description"] = "I confess the stone drake broodmother and I have had a rocky relationship in the past. She supported Deathwing during the Cataclysm, you know. But Aeosera has been put back in her place and it is my responsibility to protect her. The problem is that she refuses to abandon her eggs, even in the midst of a trogg attack. You're a shaman! Use your natural magnetism to reassemble fallen Opalescent Guardians in the Pale Roost. Escort them to Aeosera so they can carry her eggs to safety of my bosom.", ["objectivesText"] = "Escort 5 Opalescent Guardians to Aeosera. Progress: Step to it, <class>! Reassemble those guardians and take them to Aeosera!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 42932 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42937] = { ["id"] = 42937, ["name"] = "Needlerock Beatdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42932, 42933, 42935 }, ["description"] = "The troggs saw where your hammer fell, and I expect those cowards told the Legion where to find it. Hmph! The leader of the stone troggs since the Cataclysm has been \"Borlock,\" a thick-headed little dirt-grubber who's about to get what's coming to him. Find him at Needlerock Spire and beat the information out of him. Take Aeosera with you. Her and her brood have their own score to settle with those belligerent little beasts.", ["objectivesText"] = "Fly with Aeosera to Needlerock Spire and defeat Borlock of the Deeps . Progress: Oh I so love to see Aeosera in action.", ["rewardGold"] = 477360, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 42933, 42935, 42936 }, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42939] = { ["id"] = 42939, ["name"] = "Tracking Down Uthalesh", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 42939 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42952, 43181 }, ["description"] = "The logbook contains the latest information on Uthalesh. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", ["objectivesText"] = "Take the logbook to Calydus in Dreadscar Rift.", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 138830 } },
[42940] = { ["id"] = 42940, ["name"] = "When There's a Will, There's a Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["series"] = { 42493, 42520, 42707, 42734 }, ["description"] = "The Oculus appears to have fallen to the Burning Legion and is heavily shielded. We will need to figure out a way to get you inside. I suspect your champions can help us out quite a bit.", ["objectivesText"] = "Ask your champions to find a way into the Oculus.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["starts"] = { { ["x"] = 0.717, ["y"] = 0.549, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.717, ["y"] = 0.549, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.717, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "standard", ["sourceQuests"] = { 42520 }, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
