[42954] = { ["id"] = 42954, ["name"] = "A Small Favor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42955, 42956, 42959 }, ["description"] = "Meryl's illness is troubling. I have seen something similar before, but I cannot think of its name... Talk to my friend. I call her Ari . She has lived here in the Hall of the Guardian since it was last in use. If a tome on magical afflictions is to be found here, she would know where to look.", ["objectivesText"] = "Talk to Ari .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.714, ["y"] = 0.553, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.714, ["y"] = 0.553, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.714, ["y"] = 0.553 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "standard", ["sourceQuests"] = { 42222 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42955] = { ["id"] = 42955, ["name"] = "The Proper Way of Things", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42954, 42956, 42959 }, ["description"] = "Archmage Khadgar is my friend. That he trusts you means much. I know of the book in which you seek, but it does not want to be found. It is old and angry and thirsts for power. We will have to convince it to emerge from hiding in the proper way. Perhaps if you bring it a gift of nightwell energy from the nightborne elves in Suramar City it will be mollified.", ["objectivesText"] = "Siphon 50 phials of nightwell energy from the nightborne in Suramar City. Progress: Have you found enough nightwell energy yet?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 137299, 138853, 138965 }, ["starts"] = { { ["x"] = 0.37, ["y"] = 0.483, ["mapID"] = 734, ["npcID"] = 109307 } }, ["ends"] = { { ["x"] = 0.37, ["y"] = 0.483, ["mapID"] = 734, ["npcID"] = 109307 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.37, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 109307, ["questTurnInID"] = 109307, ["questType"] = "standard", ["sourceQuests"] = { 42954 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[42956] = { ["id"] = 42956, ["name"] = "Ari's Package", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42954, 42955, 42959 }, ["description"] = "Look! It was right here under our noses. \"Arcanists Guide to Rare Diseases.\" Sheepish thing. Most books just want to be dusted off and read from time to time. We will leave the phials of nightwell energy and it will go with you meekly enough. Here. I have packaged the book up for you to bring to Khadgar. I wrapped it in moth's wings to keep it soothed and light-hearted. And there is a gift for you. Just a small thing, really.", ["objectivesText"] = "Bring Ari 's package to Archmage Khadgar . Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 138866, 141880 }, ["starts"] = { { ["x"] = 0.37, ["y"] = 0.483, ["mapID"] = 734, ["npcID"] = 109307 } }, ["ends"] = { { ["x"] = 0.37, ["y"] = 0.483, ["mapID"] = 734, ["npcID"] = 109307 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.37, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 109307, ["questTurnInID"] = 109307, ["questType"] = "standard", ["sourceQuests"] = { 42955 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[42957] = { ["id"] = 42957, ["name"] = "Journey to the East", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42767, 42768, 42868 }, ["description"] = "My riddles you've solved but your job is not complete. Come, meet me at the Jade Serpent Temple for the answers you seek.", ["objectivesText"] = "Meet with the Monkey King at the Temple of the Jade Serpent within the Jade Forest. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948, 173706 }, ["starts"] = { { ["npcID"] = 109049 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questGiverID"] = 109049, ["questType"] = "standard", ["sourceQuests"] = { 42766, 42767, 42768 }, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[42959] = { ["id"] = 42959, ["name"] = "Three Is a Lucky Number", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42954, 42955, 42956 }, ["description"] = "Ari is much more than she appears, you know. She was once one of the most powerful archmagi on Azeroth and a member of the Council of Tirisfal. Unfortunately her mind was badly damaged and she has not left the Hall of the Guardian since. She must like you very much to have given you a gift. If you bring her something special in return, I suspect she will surprise you. She prefers things in threes.", ["objectivesText"] = "Bring Ari 3 special gifts. These gifts can be found on powerful enemies in dungeons. Progress: Have you found anything special for Ari yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 138968, 138969, 138971 }, ["starts"] = { { ["x"] = 0.717, ["y"] = 0.548, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.717, ["y"] = 0.548, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.717, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "dungeon", ["sourceQuests"] = { 42956 }, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
