[42966] = { ["id"] = 42966, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "Good decision, Highlord. We should be bolstering our forces by increasing recruitment efforts. Let us send our champions to carry out these orders.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Holy Allies.\"", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.508, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 42919 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24 },
[42967] = { ["id"] = 42967, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "Well said, Highlord. The Legion is not one individual enemy - it is a massive beast with many heads. To defeat them, we will need to stay vigilant on all fronts. Let us send our champions to deal with the Legion incursions as they come.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Legion Defense.\"", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.508, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 42919 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24 },
[42968] = { ["id"] = 42968, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "You are right, Highlord. Our military efforts cannot succeed without solid logistics. That means we need a steady supply of weapons, food, medicine, and other provisions. Let us send our champions to establish a supply line.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Procuring Supplies.\"", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.508, ["y"] = 0.709, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.508, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 42919 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24 },
