[42970] = { ["id"] = 42970, ["name"] = "The Diamond King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8161, ["mapID"] = 42, ["storyline"] = { 40717, 40755, 42970 }, ["series"] = { 40755 }, ["description"] = "Me brother Magni, once King o' Ironforge, got changed into a diamond statue by a titan ritual. He's stood frozen in the belly o' the city fer years. But I just got word that he's up and around... sayin' he knows somethin' 'bout how to beat the Legion! Look, <name>, I dunno if Magni's crazy, or if that's even really him. But if there's even a chance he kin help us... I'm told he muttered the name Ulduar . That's where I'm headed! I'd be obliged if you an' Khadgar were ta join me.", ["objectivesText"] = "Go with Brann and Khadgar to Ulduar and hear Magni Bronzebeard's message.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 113655, ["x"] = 0.412, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 101547, ["x"] = 0.47, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 40717, 40718 }, ["questLines"] = { { ["id"] = 241, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 258, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[42971] = { ["id"] = 42971, ["name"] = "Controlling the Elements", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 42971 }, ["description"] = "Come closer, <race>. Ragnaros in the Firelands, Al'Akir in his Throne of the Four Winds, and Neptulon in Throne of the Tides. They have been thorns in my hide since the world was new. Prove to me your strength over the weaker elements, and I shall teach you how to display your power for all to see.", ["objectivesText"] = "Retrieve Remnants of Fire, Water, and Air, and reach Revered status with Therazane . Progress: Prove your mastery over magic and the elements, <race>.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 60816, 65907, 133160, 138792, 138951, 138952, 138953 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[42974] = { ["id"] = 42974, ["name"] = "The Fate of Hodir", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "It is time, <name>. Go to Azsuna and use the captured gateway to travel to Niskara and find Hodir. The Legion will regret they set foot on Azeroth!", ["objectivesText"] = "Join your forces at Felblaze Ingress and Complete the Fate of Hodir scenario. Progress: You've returned, <name>. What news do you bring?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139681, 142057, 142059, 142061, 142063, 142064 }, ["rewardChoices"] = { 142057, 142059, 142061, 142063, 142064 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 43577 }, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[42977] = { ["id"] = 42977, ["name"] = "Servant of the Windseeker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 81, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "The elemental lords must be united, but there has been no Windlord to lead the air elementals since the death of Al'Akir. Once, there was an heir to the Throne of Four winds named Prince Thunderaan, but the prince was defeated in the mortal realm and still awaits rebirth. Only one man holds the knowledge necessary to complete the prince's rebirth. There is a servant of Thunderaan who wanders the sands of Silithus. Find him, and he will show you the way.", ["objectivesText"] = "Speak with Highlord Demitrian in Silithus.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 14347, ["x"] = 0.295, ["y"] = 0.1055 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.1055 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 42184 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81 },
[42978] = { ["id"] = 42978, ["name"] = "A Royal Audience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 42978, 42982 }, ["description"] = "<name>, My father lived by the sword, as you do. He taught me that if we truly want peace for our kingdom then we must be willing to fight to preserve it, as you have fought. You have demonstrated valor of the highest order - bravery unsurpassed in the ranks of the Alliance. Valor that must be recognized. Please join me in Stormwind Keep at once so that you can be properly rewarded for your service. - King Anduin Wrynn", ["objectivesText"] = "Report to King Anduin Wrynn in Stormwind Keep.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 138992 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 109466, ["x"] = 0.855, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 198, ["name"] = "Champion of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84, ["startItems"] = { 138992 } },
[42982] = { ["id"] = 42982, ["name"] = "The Victor's Spoils", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 42978, 42982 }, ["description"] = "It takes a true hero to put their life on the line day after day in defense of their home so that others do not have to. You have dutifully safeguarded the people and interests of the Alliance, never faltering in your courage or devotion. As a small token of our appreciation for your valiance, please turn to the gathered heroes before you, raise your weapon high, and be recognized.", ["objectivesText"] = "Raise your weapon and be recognized in Stormwind Keep. Progress: Thank you, <name>. Thank you for everything.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 109466, ["x"] = 0.855, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 109466, ["x"] = 0.855, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 42978 }, ["questLines"] = { { ["id"] = 198, ["name"] = "Champion of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[42983] = { ["id"] = 42983, ["name"] = "Mistral Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "To restore the Maelstrom Pillar, we will need to infuse it with the essence of air. A large quantity of Mistral Essence will be required to do this. Mistral Essence can be found on many of the elementals in Vortex Pinnacle. If you can return to me with a ready supply of elemental essence, I will be able to continue my restoration work on the Maelstrom Pillar.", ["objectivesText"] = "Collect 100 Mistral Essences from wind elementals in Vortex Pinnacle. Travel to the Vortex Pinnacle through the portal in the Heart of Azeroth. Progress: Were you able to collect the necessary amount?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 138994, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.294, ["y"] = 0.779, ["mapID"] = 726, ["npcID"] = 109464 } }, ["ends"] = { { ["x"] = 0.294, ["y"] = 0.779, ["mapID"] = 726, ["npcID"] = 109464 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.294, ["y"] = 0.779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 109464, ["questTurnInID"] = 109464, ["questType"] = "standard", ["sourceQuests"] = { 42996 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42984] = { ["id"] = 42984, ["name"] = "Eye of Azshara: The Scepter of Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "The element of air can be difficult to contain. We will need a way to magically anchor it to the pillar. Air, no matter how capricious, cannot resist a good storm. In the Eye of Azshara, the naga sorceress known as Lady Hatecoil possesses a powerful relic known as the Scepter of Storms . Retrieve the scepter, and we will use it to bind the elements of air to the Maelstrom Pillar.", ["objectivesText"] = "Collect the Scepter of Storms from Lady Hatecoil in the Eye of Azshara dungeon. Progress: I hope it was easy to convince Lady Hatecoil to part with her scepter.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 138995, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.294, ["y"] = 0.779, ["mapID"] = 726, ["npcID"] = 109464 } }, ["ends"] = { { ["x"] = 0.294, ["y"] = 0.779, ["mapID"] = 726, ["npcID"] = 109464 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.294, ["y"] = 0.779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 109464, ["questTurnInID"] = 109464, ["questType"] = "dungeon", ["sourceQuests"] = { 42983 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42985] = { ["id"] = 42985, ["name"] = "A Royal Audience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 42985, 42987 }, ["description"] = "<name>, Those who do not stand with the Horde stand against it. You, champion, have cut down such enemies in droves. I admire your dedication. It is through you that we will rise up, more powerful than ever, and put the Alliance in their place once and for all. Join me in the Undercity at once. Your victories must be met with due reward. - Warchief Sylvanas Windrunner", ["objectivesText"] = "Report to Warchief Sylvanas Windrunner in the Undercity.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 138996 }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 109471, ["x"] = 0.58, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 199, ["name"] = "Champion of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 90, ["startItems"] = { 138996 } },
[42986] = { ["id"] = 42986, ["name"] = "Enemies of Air", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "Windlord Thunderaan has retaken the Vortex Pinnacle, but not all of his subjects have taken to his leadership kindly. In his kingdom there is still unrest, and it appears there are four viziers who have risen up against him: Mistius, Zeph, Alacris, and Tulmos. We will let Thunderaan focus on the war against the Burning Legion while we send our champions to aid Skywall against its enemies.", ["objectivesText"] = "Complete 4 \"Thunderaan's Enemies\" missions. Progress: How are the missions going?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.604, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.604, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41901 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42987] = { ["id"] = 42987, ["name"] = "The Victor's Spoils", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 42985, 42987 }, ["description"] = "We will never be dominated so long as you stand at the front of our lines. Together we will slaughter anyone who stands in our way. You have sacrificed as much as any in the name of the Horde. I will not let your dedication go unnoticed. Face your fellow champions, <name>. Face them, and be recognized.", ["objectivesText"] = "Raise your weapon and be recognized in the Undercity. Progress: You have pleased me this day.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 109471, ["x"] = 0.58, ["y"] = 0.915 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 109471, ["x"] = 0.58, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["sourceQuests"] = { 42985 }, ["questLines"] = { { ["id"] = 199, ["name"] = "Champion of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 90 },
[42988] = { ["id"] = 42988, ["name"] = "Worldmender", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "The elements have gathered, and though the Firelands have yet to unite with us, we have more strength on our side than ever before. However, the war with the Burning Legion still rages, and for now we must turn our gaze to the Broken Isles. When we have dealt sufficiently with the immediate threats of the war, we will turn our attention to uniting the Firelands to our cause.", ["objectivesText"] = "Complete 10 World Quests. Progress: How does the situation look?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124 }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41900 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42989] = { ["id"] = 42989, ["name"] = "Ma'haat the Indomitable", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 207, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "In order to imbue the Maelstrom Pillar with the essence of earth, we will need one of the rarest fossils found on Azeroth - an egg. The Egg of Gaiath is no ordinary egg; it contains the remnants of an unborn earthen primal, perfectly preserved in stone. There may be a means by which to revive it, but more on that later. First, we must find that egg! The Earthen Ring has heard of an ancient being who possesses such an item, but he will require payment in blood!", ["objectivesText"] = "Speak to Ma'haat the Indomitable in Deepholm to acquire a Fossilized Egg. He will require Blood of Sargeras in trade.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124 }, ["starts"] = { { ["x"] = 0.294, ["y"] = 0.778, ["mapID"] = 726, ["npcID"] = 109464 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.587, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 7745 } }, ["questGiverID"] = 109464, ["questType"] = "standard", ["sourceQuests"] = { 42997 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42990] = { ["id"] = 42990, ["name"] = "Neltharion's Lair: The Earthen Amulet", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "That you were even able to acquire the Egg of Gaiath is an incredible feat in itself, but the next step may well be impossible. Still... it is our only hope. For the ritual to work, we will need to awaken the latent elemental energy resting inside of this egg. There is an item that just may have the ability to do this - a relic known as the Earthen Amulet , rumored to have been created by Loken himself. It was lost many ages ago, and has fallen into the hands of Dargrul the Underking.", ["objectivesText"] = "Retrieve the Earthen Amulet from Dargrul the Underking in Neltharion's Lair. Progress: Neltharion collected many valuable relics. The Earthen Amulet was one of them.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 138999, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.294, ["y"] = 0.778, ["mapID"] = 726, ["npcID"] = 109464 } }, ["ends"] = { { ["x"] = 0.294, ["y"] = 0.778, ["mapID"] = 726, ["npcID"] = 109464 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.294, ["y"] = 0.778 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 109464, ["questTurnInID"] = 109464, ["questType"] = "dungeon", ["sourceQuests"] = { 43003 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
