[42995] = { ["id"] = 42995, ["name"] = "A Taste For Blood", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["objectivesText"] = "Progress: Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep... Such a barter will cost you... greatly. Bring me 5 Blood of Sargeras , and I will give you the egg.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.587, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["sourceQuests"] = { 42989 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207 },
[42996] = { ["id"] = 42996, ["name"] = "The Maelstrom Pillar: Air", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "Elementalist Janai was looking for you earlier, Farseer. It appears that her study of the Maelstrom Pillar has been most enlightening. If you have a moment, you should go and meet with her to discuss her progress.", ["objectivesText"] = "Speak to Elementalist Janai at the Heart of Azeroth.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.604, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.604, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41901 }, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[42997] = { ["id"] = 42997, ["name"] = "The Maelstrom Pillar: Earth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "Elementalist Janai has been hard at work restoring the Maelstrom Pillar. As of late, she has been focusing her research on the element of earth. You should speak with her when you have a chance. I have heard that she is close to a breakthrough.", ["objectivesText"] = "Speak to Elementalist Janai at the Heart of Azeroth.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.603, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41900 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[43002] = { ["id"] = 43002, ["name"] = "Blessed Blade of the Windseeker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "So the Earthen Ring wishes to resurrect my master? < Highlord Demitrian laughs maniacally.> I knew this day would come! At last, humanity understands the power of the Windseeker! When Prince Thunderaan was slain at the hands of treacherous mortals, his soul was trapped within the sacred blade Thunderfury. To resurrect my master you will need to find his sword and return it to Skywall. Last I heard, the betrayer who stole my master's sword traveled to the Broken Isles to fight demons.", ["objectivesText"] = "Locate the lost blade of the Windseeker. Progress: Have you found the key to resurrecting Thunderaan?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 19019, 124124, 128819, 128911, 128935, 137209, 137225, 137374, 139000, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 14347, ["x"] = 0.295, ["y"] = 0.1055 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 14347, ["x"] = 0.295, ["y"] = 0.1055 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.1055 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questTurnInID"] = 14347, ["questType"] = "standard", ["sourceQuests"] = { 42977 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[43003] = { ["id"] = 43003, ["name"] = "Return to Janai", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "< Ma'haat the Indomitable speaks to you with a low, rumbling voice.> Here... is the Egg of Gaiath . It is yours now. Go... in peace.", ["objectivesText"] = "Return to Elementalist Janai at the Heart of Azeroth. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138997 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.587, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questTurnInID"] = 42470, ["questType"] = "standard", ["sourceQuests"] = { 42995, 91621 }, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[43007] = { ["id"] = 43007, ["name"] = "Return to the Chamber of Shadows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43013, 43014, 43015 }, ["description"] = "Lord Jorach Ravenholdt sent me out to find you, <name>. He wants your counsel on some matter of importance. He requests your presence back at the Chamber of Shadows.", ["objectivesText"] = "Speak with Lord Jorach Ravenholdt in the Chamber of Shadows.", ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112679 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 112679, ["questType"] = "standard", ["sourceQuests"] = { 40997 }, ["nextQuests"] = { 42139 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[43013] = { ["id"] = 43013, ["name"] = "The School of Roguery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43007, 43014, 43015 }, ["description"] = "Great! Sounds like she's already settled in. That's good, cuz we already need some fresh meat for the grinder. You should mosey over an' see if she's got any thieves just lying around takin' up space.", ["objectivesText"] = "Speak with Lonika Stillblade and train a Gang of Bandits . Progress: How's the new 'school' comin' along?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.377, ["y"] = 0.449, ["mapID"] = 626, ["npcID"] = 98092 } }, ["ends"] = { { ["x"] = 0.377, ["y"] = 0.449, ["mapID"] = 626, ["npcID"] = 98092 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.377, ["y"] = 0.449 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98092, ["questTurnInID"] = 98092, ["questType"] = "standard", ["sourceQuests"] = { 42140 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[43014] = { ["id"] = 43014, ["name"] = "The Big Bad Wolfe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43007, 43013, 43015 }, ["description"] = "You've heard of Winstone Wolfe , right? Of course you have. Who hasn't? So, while you were off gabbin' with the headmistress, Lord Ravenholdt graced me with his presence. In the flesh. I didn't think he ever came out of that chamber. Anywhoodles, he more than suggested, in that way of his, that we send Garona, Vanessa, and our new merry gang of bandits off to have a little chat with The Wolf at Ravenholdt Manor. Just make sure they're nice and civil, or that's the last we'll see of them.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"The Big Bad Wolfe\". Progress: How'd the trip out to Ravenholdt Manor go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139002 }, ["starts"] = { { ["x"] = 0.378, ["y"] = 0.45, ["mapID"] = 626, ["npcID"] = 98092 } }, ["ends"] = { { ["x"] = 0.378, ["y"] = 0.45, ["mapID"] = 626, ["npcID"] = 98092 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.378, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98092, ["questTurnInID"] = 98092, ["questType"] = "standard", ["sourceQuests"] = { 43013 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[43015] = { ["id"] = 43015, ["name"] = "What Winstone Suggests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43007, 43013, 43014 }, ["description"] = "If anyone can improve the way things run around here, it's Winstone Wolfe. I tell ya, the man is a miracle-worker! Now that he's workin' for us, shall we pick his brain an' see what he suggests?", ["objectivesText"] = "Speak to Winstone Wolfe. Progress: I see that you were able to convince Mr. Wolfe to join us. Of course, that rather sizeable sum of gold we deposited into his bank account didn't hurt either.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.378, ["y"] = 0.449, ["mapID"] = 626, ["npcID"] = 98092 } }, ["ends"] = { { ["x"] = 0.378, ["y"] = 0.449, ["mapID"] = 626, ["npcID"] = 98092 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.378, ["y"] = 0.449 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98092, ["questTurnInID"] = 98092, ["questType"] = "standard", ["sourceQuests"] = { 43014 }, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
