[43062] = { ["id"] = 43062, ["name"] = "Further Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "You may be the Grandmaster, but mastery must be maintained through discipline. To achieve perfect harmony, you must continue your training. I would like to see your form in practice, <name>. Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.", ["objectivesText"] = "Use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike abilities 10 times each. Progress: To achieve mastery, we must hone ourselves tirelessly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124437 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["sourceQuests"] = { 41733 }, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
