[43090] = { ["id"] = 43090, ["name"] = "Ulduar's Oath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42616, 42618, 43090, 43586, 43604 }, ["description"] = "I was once leader of all of the titanforged keepers of Azeroth. We were charged by the Titans themselves to protect the world. Once I gave up on the post of Prime Designate, I gave up any measure of influence over the other keepers. Not even my own son, Thorim, is bound to heed my commands. The Gjallarhorn comes from a time before our falling out, however. A time of an ancient oath of honor. Let us invoke that oath -- I am certain Thorim will answer the call.", ["objectivesText"] = "Ask Hymdall to sound the Gjallarhorn and request Thorim's assistance. Progress: What news do you bring from Ulduar?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139506, 139688 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 43586, 43604, 43975 }, ["questLines"] = { { ["id"] = 5806, ["name"] = "Chronicles of Skyhold II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5806, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
