[43100] = { ["id"] = 43100, ["name"] = "Finding the Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 22, ["storyline"] = { 43100, 43153, 43254 }, ["series"] = { 43153, 43215 }, ["description"] = "Very powerful, but difficult to acquire. Scepter is in the hands of Gul'dan. We must find out his plans, get close. Calydus know Gul'dan planning major operation. He has sent out a call to arms to all Shadow Council to help with big ritual. One such group at Caer Darrow, talking to the necromancers there. You should go, find out about plan.", ["objectivesText"] = "Go to Caer Darrow in Western Plaguelands and find out about the Shadow Council ritual. Progress: This gets complicated, but Calydus have idea!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139035, 139506, 139765, 139767, 139770, 140517, 140922, 173526 }, ["starts"] = { { ["x"] = 0.564, ["y"] = 0.646, ["mapID"] = 628, ["npcID"] = 101097 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 109698, ["x"] = 0.692, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 7875 } }, ["questGiverID"] = 101097, ["questType"] = "standard", ["sourceQuests"] = { 40684, 43984, 44089 }, ["questLines"] = { { ["id"] = 224, ["name"] = "Scepter of Sargeras", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 224, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 22 },
