[43151] = { ["id"] = 43151, ["name"] = "Making A Trade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "Yes I do have Amaranthine Hops , but they took me quite some time to gather. I cannot part with them easily. However, I'd be willing to trade them for Stonehide Leather . If you come upon any, bring it to me and we can make a trade.", ["objectivesText"] = "Obtain 20 Stonehide Leather . Progress: Do you have leather to trade?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124113, 139033 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 109738, ["x"] = 0.562, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109738, ["x"] = 0.562, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41911 }, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
