[43153] = { ["id"] = 43153, ["name"] = "An Eye for a Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 43100, 43153, 43254 }, ["series"] = { 43100, 43215 }, ["description"] = "Sounds simple? Make nice with Shadow Council friend must... for now. Help with ritual enough to gain trust, then turn tables! Council made portal device to Tol Barad here. Go, help Shadow Council find Eye of Dalaran, earn spot in big ritual! Then steal Scepter! Calydus will try to keep eye on friend when possible.", ["objectivesText"] = "Take the portal to Tol Barad and help find the Eye of Dalaran.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 109698, ["x"] = 0.692, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 109698, ["x"] = 0.692, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questTurnInID"] = 109698, ["questType"] = "standard", ["sourceQuests"] = { 43100 }, ["questLines"] = { { ["id"] = 224, ["name"] = "Scepter of Sargeras", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 224, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[43162] = { ["id"] = 43162, ["name"] = "Under the Crooked Tree", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 43162 }, ["description"] = "My three sisters from that tree hung, The crimes accused there was not one, The youngest sister did escape, As the noose looped around their nape, Old Ravencrest is the one to blame, This curse for you to lift our shame.", ["objectivesText"] = "Drink from the hag's cauldron to accept her curse. Then you will be able to defeat her sister's restless spirit. Progress: Steel your heart and drink deep, Return my sister back to sleep.", ["rewardItems"] = { 20411, 33226, 139133, 139134, 139135, 139136, 139137 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 109734, ["x"] = 0.35, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109734, ["x"] = 0.35, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
