[43181] = { ["id"] = 43181, ["name"] = "Tracking Down the Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 43181 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952 }, ["description"] = "The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", ["objectivesText"] = "Take the logbook to Calydus in Dreadscar Rift.", ["rewardGold"] = 31900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[43182] = { ["id"] = 43182, ["name"] = "The Missing Vessel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 680, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "So long as Hakkar roams free, no mage will be safe. Millificent Manastorm created a vessel that siphons the essence of a mage, binding their magic to the object. It was created to be a weapon, but we can use it as bait. If I channel my essence into the vessel, it will become an object of pure magic. Upon capture, Millificent shattered the vessel, allowing it to fall into the hands of our enemies. Find the pieces and return them to me. Together we can set a trap Hakkar won't be able to resist!", ["objectivesText"] = "Interact with the Scouting Map and complete \"The Missing Vessel\" missions to collect Shattered Vessel Fragments. Progress: Have you found the missing pieces yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139041 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42405 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
