[43254] = { ["id"] = 43254, ["name"] = "Ritual Ruination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 717, ["storyline"] = { 43100, 43153, 43254 }, ["description"] = "Time for main event, friend! Gul'dan wants to begin his big ritual, cause end times for this world. Calydus confident getting the Scepter will stop that plan. Take this bat to Tomb of Sargeras, find ritual, steal Scepter. Oh... and get out! Calydus will help when he can! Good luck, friend!", ["objectivesText"] = "Take the Fel Bat to the Tomb of Sargeras and steal the Scepter of Sargeras.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922 }, ["starts"] = { { ["x"] = 0.738, ["y"] = 0.429, ["mapID"] = 627, ["npcID"] = 109838 } }, ["ends"] = { { ["x"] = 0.738, ["y"] = 0.429, ["mapID"] = 627, ["npcID"] = 109838 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.738, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 109838, ["questTurnInID"] = 109838, ["questType"] = "standard", ["sourceQuests"] = { 43153 }, ["questLines"] = { { ["id"] = 224, ["name"] = "Scepter of Sargeras", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 224, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[43259] = { ["id"] = 43259, ["name"] = "Beware of the Crooked Tree", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 43259 }, ["description"] = "<race>, you must be warned. There is great evil in Val'sharah. I've seen it, and I wish I hadn't. If you take my advice, you will stay far away from the crooked tree in Bradensbrook.", ["objectivesText"] = "Investigate the crooked tree in Bradensbrook.", ["rewardGold"] = 312800, ["rewardXP"] = 5465, ["rewardItems"] = { 33226, 139133, 139134, 139135, 139136, 139137 }, ["starts"] = { { ["x"] = 0.474, ["y"] = 0.406, ["mapID"] = 627, ["npcID"] = 109854 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109734, ["x"] = 0.35, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 109854, ["questType"] = "standard" },
