[43264] = { ["id"] = 43264, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43265, 43266, 43267, 43268 }, ["description"] = "Your power is great, Deathlord, but power alone will not be sufficient. If we are to save this world from the onslaught of the Burning Legion, then you will need powerful allies. The Knights of the Ebon Blade are yours to command, it will be wise to make use of them effectively. Go and speak with Nazgrim and Thassarian. They will be of great use to you in the fight against the Burning Legion.", ["objectivesText"] = "Recruit Nazgrim and Thassarian.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.505, ["mapID"] = 648, ["npcID"] = 93437 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.511, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93437, ["questTurnInID"] = 93437, ["questType"] = "standard", ["sourceQuests"] = { 44550 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43265] = { ["id"] = 43265, ["name"] = "Spread the Word", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43264, 43266, 43267, 43268 }, ["description"] = "Now that you have recruited your champions, you can use the Scouting Map to complete vital missions across the Broken Isles. The first mission is critical to the growth and power of our order. Send Nazgrim and Thassarian to seek out new candidates for the Ebon Blade. Our order must grow in strength if we are to defeat the Burning Legion.", ["objectivesText"] = "Use the Scouting map and complete \"Spread the Word.\" Progress: What is the status of the mission?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 63667, 63668, 63669, 63670, 63671, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 239440 }, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 43264 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43266] = { ["id"] = 43266, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43264, 43265, 43267, 43268 }, ["description"] = "A powerful necromancer has joined the cause of the Ebon Blade. Dark Summoner Marogh has come a long way to us from deep within the realm of the Shadowlands. He will be a powerful ally of the Ebon Blade. Speak with Dark Summoner Marogh to begin raising an army of ghouls for the Ebon Blade.", ["objectivesText"] = "Speak with Dark Summoner Marogh to summon ghouls. Progress: Has Dark Summoner Marogh begun his work?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 43265 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43267] = { ["id"] = 43267, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43264, 43265, 43266, 43268 }, ["description"] = "It's time to send our newly summoned ghouls out into the field. Look at the Command Table and send your champions and troops on a routine scouting mission.", ["objectivesText"] = "Use the Command Table and complete the mission, \"Troops in the Field.\" Progress: How did it go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 43266 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43268] = { ["id"] = 43268, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43264, 43265, 43266, 43267 }, ["description"] = "Archivist Zubashi has been doing a great deal of research on the necropolis we call Acherus. Through his studies on the necropolis, he has located a number of potential improvements that can greatly increase the power of the Ebon Hold. Speak with Archivist Zubashi now and he will show you what improvements can be made.", ["objectivesText"] = "Speak with Archivist Zubashi in Acherus. Progress: Greetings, Deathlord. I have been studyin' da true nature of da necropolis. You going to be pleased wit' da results I assure you!", ["rewardGold"] = 31900, ["rewardXP"] = 710, ["rewardItems"] = { 140517 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 43267 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43270] = { ["id"] = 43270, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 43273, 43275 }, ["description"] = "As leader of our order, other priests will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary to bring down the Burning Legion. After your display of power during the cleansing ritual, there will be many who are eager to serve at your side. Seek out those priests, and let them ease the burden of leadership.", ["objectivesText"] = "Recruit Calia Menethil and High Priestess Ishanah.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 300 } }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.511, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 44100 }, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
