[43303] = { ["id"] = 43303, ["name"] = "Time to Rumble!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 43303 }, ["description"] = "Welcome to the Black Rook Rumble! Many combatants have entered to prove their might in the Black Rook Arena, and now it is your time.", ["objectivesText"] = "Speak with David Globerunner and find out how to participate in the Black Rook Rumble.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[43308] = { ["id"] = 43308, ["name"] = "Treasure 071 - Outskirts", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[43309] = { ["id"] = 43309, ["name"] = "The Perfect Opportunity", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "I have heard whispers from Suramar City. Recent unrest in the city has prompted the nobles to seek another advisor to fill Elisande's council. Such positions are rarely offered and hotly contested. This is the perfect opportunity and Ly'leth is the perfect candidate. Fate smiles upon our cause! I know she has historically chosen to avoid such politics and maneuvering, but we must now ask her to join the fray. Seek her out at the Waning Crescent and ensure her victory.", ["objectivesText"] = "Meet Ly'leth Lunastre at the Waning Crescent. Progress: Thalyssra asks much of me.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44052 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43310] = { ["id"] = 43310, ["name"] = "Either With Us", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Thalyssra asks much of me, but our cause is worth the risks. The title of advisor would grant us enormous influence. Information. Access. I could change this rebellion. I could save so many lives. I will need strong endorsement to ascend, though. There are many houses who stand with me by virtue of my family's name. Some are more hesitant. Lady Aurore of House Astravar is the most prominent of these. Seek her out. Offer your aid in my stead. Earn her trust and the rest will follow.", ["objectivesText"] = "Speak to Lady Aurore .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43309 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43311] = { ["id"] = 43311, ["name"] = "Or Against Us", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "If Ly'leth is to achieve the role of advisor to the Grand Magistrix we will need to open a path for her. It is true she will have some supporters but they alone cannot grant her the title. There are other houses that Ly'leth must contend with. Fear and coercion are their tools. None dare stand against them openly, and we cannot win them over with favors and oaths. Seek out Arluin . I trust he will have some ideas of how to proceed.", ["objectivesText"] = "Speak to Arluin . Progress: Yes, I know why you are here. Yes, I can get the jobe done. No, it will not be free.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29333, 29334, 29335, 29336, 52593, 52617, 52640, 52644, 52673, 62210, 62211, 62212, 62213, 131283, 131655, 139786, 140255, 140409, 140421, 140422, 141680, 141955, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43309 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43312] = { ["id"] = 43312, ["name"] = "Thinly Veiled Threats", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "How could I let this happen? < Aurore wrings her hands.> Yesterday Coryn Stelleris approached me about the appointment. He sought my support, but I did not offer it. He said my son's life would continue as normal... if I gave him my vote. This morning my son was gone. I can only think of the terrible things he may be suffering. You know what this family is capable of! You want my support, but I can do nothing while my son is in danger. Nothing. Please... save him!", ["objectivesText"] = "Rescue Ailen Astravar . Progress: Did you find my son?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 69777, 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 43310 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43313] = { ["id"] = 43313, ["name"] = "Rumor Has It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Coryn Stelleris and Ruven Duskmere were close friends, but one always overshadowed the other. Now the Stelleris family stands to gain from lord Ruven's death. Handsomely. House Duskmere will soon learn of their loss. I want you to be the one to redirect their anger and grief. A handful of well placed rumors should do the trick. I won't be lingering in this part of the city for long, and Ly'leth will want to know of your efforts. Return to her when you are finished.", ["objectivesText"] = "Plant rumors among members of House Duskmere.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 109076, 123956, 130899, 131746, 137178, 137401, 140255, 140409, 140421, 140422, 141605, 141680, 141955, 179384, 200738 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 43315 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43314] = { ["id"] = 43314, ["name"] = "Court of Stars: Beware the Fury of a Patient Elf", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8079, ["mapID"] = 680, ["storyline"] = { 43314 }, ["description"] = "An opportunity presents itself, <name>. Ly'leth has arranged to grant you entry into a ball at the Court of Stars . I do not know what we may gain from this venture, but there is one task I must set for you. Advisor Melandrus once called himself my ally. He and I planned Elisande's downfall, but when the moment came I found myself betrayed. The wound his dagger inflicted still aches. I cannot enter Suramar to take my revenge, but you can. Give him a traitor's death, and bring me his spellstone.", ["objectivesText"] = "Enter the Court of Stars dungeon and slay Advisor Melandrus. Collect his Spellstone and return it to Thalyssra. Progress: Is it done?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 140255, 140409, 140421, 140422, 140757, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 112146, ["x"] = 0.365, ["y"] = 0.468 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 44053 } },
[43315] = { ["id"] = 43315, ["name"] = "Death Becomes Him", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "There are two houses that pose a threat to Ly'leth's rise, but we concern ourselves with only one of them now. House Duskmere commands respect through fear and that fear is not unfounded. Few can boast of magical talent equal to that of Ruven Duskmere. Without this charming specimen, however, their house is nothing. I know you may find my methods distasteful. Know that there were demons in Suramar long before the Legion. This one has lived long enough.", ["objectivesText"] = "Slay Ruven Duskmere. Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 17125, 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 43311 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43317] = { ["id"] = 43317, ["name"] = "In the Bag", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Already the city is abuzz with outrage. I will not lie to you- it pleases me greatly that one such as Coryn is made a fool. The other houses have sent their endorsements. It is done, and nothing remains but a formal ceremony to grant me the title of advisor. Meet me there. You deserve to share in this success.", ["objectivesText"] = "Witness Ly'leth Lunastre 's ascension to advisor. Progress: I am prepared. It is nearly time.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 5083, 57540, 140255, 140409, 140421, 140422, 141680, 141955, 181176, 181177, 181180, 181182, 181189, 181197, 181198, 181204, 181217, 181218, 181224, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 184147, 184150, 184777, 185854, 185942, 186201, 204195, 237354 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43313, 44040 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43318] = { ["id"] = 43318, ["name"] = "Ly'leth's Champion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Tal'ashar is an honor duel. If I lose, then I must forfeit my title to Coryn Stelleris. <Ly'leth smiles gently.> That is why you are going to fight for me. I will grant you a more powerful disguise for this task, and together we will put Coryn in his place. Speak to me when you are ready to battle on my behalf.", ["objectivesText"] = "Speak with Ly'leth to begin the encounter. Progress: I know you will defend my honor, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 246937, 247911 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43317 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43319] = { ["id"] = 43319, ["name"] = "The Way of the Tiger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["description"] = "Among the allies who joined us from Tian Monastery is Gin Lai , a monk famed for his experience in the ways of the tiger. With his help, we will be able to train Tiger Initiates, who strike swiftly and precisely on the field of battle. Go speak with him now and request his services.", ["objectivesText"] = "Speak to Recruiter Gin Lai .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 41733 }, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
