[43331] = { ["id"] = 43331, ["name"] = "Time to Collect", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "Hey there, pal. My sources around here say you had a run-in with the Sixtrigger brothers. I'd imagine you're not very happy with them? Let's just say we're not exactly friends either. So I'll tell you what. How about I let you in on some intel about their current location? Maybe they might have an unfortunate accident, you follow? Oh, and bring some friends. They're not exactly the easiest of targets.", ["objectivesText"] = "Collect Sixtrigger's Key from Rax Sixtrigger in Stormheim . Progress: This seems to be where the Sixtrigger brothers keep their most prized spoils.", ["rewardXP"] = 7675, ["rewardItems"] = { 109076, 124121, 127834, 128832, 132203, 132226, 132240, 133563, 133815, 133942, 133983, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135, 139276, 140592, 140593, 140594, 140595, 140596, 140597, 140598, 140599, 140600, 140601 }, ["rewardChoices"] = { 140592, 140593, 140594, 140595, 140596, 140597, 140598, 140599 }, ["starts"] = { { ["x"] = 0.502, ["y"] = 0.23, ["mapID"] = 627, ["npcID"] = 110018 } }, ["ends"] = { { ["x"] = 0.502, ["y"] = 0.23, ["mapID"] = 627, ["npcID"] = 110018 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.502, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 110018, ["questTurnInID"] = 110018, ["questType"] = "group", ["sourceQuests"] = { 42483 }, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 6, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapI