[43334] = { ["id"] = 43334, ["name"] = "The Coming Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 379, ["storyline"] = { 39771, 43334, 43338 }, ["description"] = "You saved us all, my friend! Truly you embody all the elements stand for. If the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power. They were placed in the care of the White Tiger, who will give them only to one who is worthy. Come <name>! Travel with me to Pandaria and we will prove your worth!", ["objectivesText"] = "Travel to Pandaria and speak to the White Tiger at his temple.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["x"] = 0.342, ["y"] = 0.777, ["mapID"] = 725, ["npcID"] = 96541 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 60968, ["x"] = 0.687, ["y"] = 0.47075 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.47075 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 8046 } }, ["questGiverID"] = 96541, ["questType"] = "standard", ["sourceQuests"] = { 41335, 43945, 44006 }, ["questLines"] = { { ["id"] = 266, ["name"] = "The Voice of Thunder", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 266, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[43335] = { ["id"] = 43335, ["name"] = "Survival Skills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42390, 42392 }, ["description"] = "The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct. Show me you have the basic survival skills to live off the land.", ["objectivesText"] = "Show your survival skill by building a campfire from chopped wood , and cooking a steak over an open flame. Progress: You need to eat to survive in the wild. Boar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however. There are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often tell which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat. The best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124119, 137609, 137612 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 42390 }, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[43336] = { ["id"] = 43336, ["name"] = "Purge of the Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 43336 }, ["objectivesText"] = "Cleanse Dreadroot Bloodflower destroyed", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Cleanse Dreadroot", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Bloodflower destroyed", ["amount"] = 13, ["type"] = 2, ["objectID"] = 251766, ["orderIndex"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[43338] = { ["id"] = 43338, ["name"] = "The Codex of Ra", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 39771, 43334, 43338 }, ["description"] = "The Thunder King conquered Pandaria using power stolen from the Titan Keeper Ra, known as \"Ra-den\" in the mogu tongue. If you truly seek to wield the relics of the Highkeeper, seek out his ancient edicts among the ruins in the heart of the mogu empire: The Edict of Stone , The Edict of Fire , and the Edict of the Storm . These pieces of the codex are scattered amongst the Guo-Lai Halls in the Vale of Eternal Blossoms, one in each wing.", ["objectivesText"] = "Enter the Guo Lai Halls in the Vale of Eternal Blossoms and collect the Edict of Stone , the Edict of Fire , and the Edict of the Storm . Cleanse the area by slaying mogu spirits. Progress: I've been asking around. The pandaren locals are terrified of this place. It's been haunted since the end of Hellscream's Pandaren Campaign. Did you find an offering for the White Tiger?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139432, 139433, 139434, 139506, 139698, 139701, 139705, 139879, 140517, 140929, 140932, 187028, 232877, 233014 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 60968, ["x"] = 0.687, ["y"] = 0.47075 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 60968, ["x"] = 0.687, ["y"] = 0.47075 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.47075 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questTurnInID"] = 60968, ["questType"] = "standard", ["sourceQuests"] = { 43334 }, ["questLines"] = { { ["id"] = 266, ["name"] = "The Voice of Thunder", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 266, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 395 },
[43341] = { ["id"] = 43341, ["name"] = "Uniting the Isles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43341, 45727 }, ["description"] = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", ["objectivesText"] = "Earn at least Friendly reputation with the factions of the Broken Isles. Progress: Any luck uniting the factions?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 139390, 141605 }, ["starts"] = { { ["npcID"] = 90417 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questType"] = "standard", ["questLines"] = { { ["id"] = 275, ["name"] = "7.0 World Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
