[43349] = { ["id"] = 43349, ["name"] = "The Aegis of Aggramar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["storyline"] = { 43349 }, ["description"] = "Now that it's out of the hands of the Legion, the Aegis should be brought back to Dalaran for safekeeping while the hunt continues for the rest of the Pillars of Creation . It should be safe in the central portal chamber until the time comes when it is needed.", ["objectivesText"] = "Secure the Aegis of Aggramar in the Chamber of the Guardian in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129989, 129997, 130005, 130016 }, ["rewardChoices"] = { 129989, 129997, 130005, 130016 }, ["starts"] = { { ["objectID"] = 251991 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7672 } }, ["questType"] = "standard", ["sourceQuests"] = { 40072 } },
[43352] = { ["id"] = 43352, ["name"] = "Asset Security", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "With the demons and guards so agitated, I'm running out of safe places to store contraband. The guards have caught on to one of my favorite havens and will be making off with my goods any minute now. Head to my stash and discourage their curiosity. You will need to use a grappling hook to access it- just look for something to latch onto along the ledge. I will make sure there is something in it for you when you are done.", ["objectivesText"] = "Defend Arluin 's stash from the city guards. Progress: Did you deter them yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42840 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43359] = { ["id"] = 43359, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["storyline"] = { 43359 }, ["description"] = "Grand Master, you have saved our order from the brink of destruction. Your deeds have shown us that with effort and determination we can overcome any challenge. In light of your example, we have doubled our efforts and developed a technique that will awaken your weapon to its true potential. Please, stand before the Forge of the Roaring Mountain and raise your weapon high.", ["objectivesText"] = "Approach the indicated location before the Forge of the Roaring Mountain and raise your weapon. Progress: We honor you, Grandmaster.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 41087 } },
[43360] = { ["id"] = 43360, ["name"] = "The Shardmaidens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 684, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "Long have I walked this land and I have seen many forms of corruption. The creatures that wander this hall are twisted by the magics unleashed by the failed arcan'dor. These dryads have lost their way, and cannot be saved. You must destroy them. End their suffering.", ["objectivesText"] = "Slay 6 Shardmaidens in the Shattered Locus.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140255 }, ["starts"] = { { ["x"] = 0.423, ["y"] = 0.148, ["mapID"] = 684, ["npcID"] = 110538 } }, ["ends"] = { { ["x"] = 0.423, ["y"] = 0.148, ["mapID"] = 684, ["npcID"] = 110538 } }, ["coords"] = { ["mapID"] = 684, ["x"] = 0.423, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questGiverID"] = 110538, ["questTurnInID"] = 110538, ["questType"] = "standard", ["sourceQuests"] = { 44152 }, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 684 },
[43361] = { ["id"] = 43361, ["name"] = "Fragments of Disaster", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "In the hall beyond rests the bones of the failed arcan'dor. I will take fragments of the crystallized tree and attempt to read them. We must discover the root cause of this destruction. Only then do we have any hope of preventing this disaster from repeating itself.", ["objectivesText"] = "Collect 5 Crystallized Bark . Progress: Do you have the shards?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139340, 140255 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 107126, ["questType"] = "standard", ["sourceQuests"] = { 44152 }, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 684 },
[43362] = { ["id"] = 43362, ["name"] = "The Stuff of Dreams", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "This arcan'dor is one of an ancient species. They were not bred, but created. In them the arcane and primitive druidic magics merged into something greater than both. The arcane will soon devour it whole. We can restore balance, but it will require wild magic. Magic trapped in another realm. You must enter the Emerald Dreamway and bring back the essence of life itself. Only then can the arcan'dor find stability and begin to thrive once more.", ["objectivesText"] = "Collect Purified Life Essence from the Emerald Dreamway. Progress: Do you have it?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139342, 140255, 140444, 246937, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44156 }, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
