[43365] = { ["id"] = 43365, ["name"] = "The Cycle Continues", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Yay! The grove is regenerating nicely. Our flower friends thank you for helping them. We were able to save most of the grove, but sadly, many living souls were lost as well. Brightwing is so sad! But you can help! Take this bag of Dream Seeds . Plant them onto fresh corpses, and in time, new flowers will grow! Death is beautiful, and from death comes rebirth. This is the cycle that must continue!", ["objectivesText"] = "Plant 100 Dream Seeds on corpses.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 46874, 139380 }, ["starts"] = { { ["x"] = 0.396, ["y"] = 0.455, ["mapID"] = 715, ["npcID"] = 98008 } }, ["ends"] = { { ["x"] = 0.396, ["y"] = 0.455, ["mapID"] = 715, ["npcID"] = 98008 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.396, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 98008, ["questTurnInID"] = 98008, ["questType"] = "standard", ["sourceQuests"] = { 42045 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 16, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715 },
