[43370] = { ["id"] = 43370, ["name"] = "A New Invention", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 43370 }, ["description"] = "I have been experimenting with technology that allows you to alter the structure of beasts, specifically with how they look.", ["objectivesText"] = "I should be able to create an item that allows you to change the appearance of Hati, but the components for such an item are rare. The Squallhunters from Stormheim have a Stormy Gland , and the Stoneblood Harpies near Thas'talah in Val'sharah have Pristine Harpy Feathers that I need. The Hatecoil Naga near the Ruins of Nar'thalas in Azsuna are said to have Reflective Scales , and finally I need an Essence of Pure Spirit from the Seabound Mystics in the Blind Marshlands of Highmountain. Progress: This is my most magnificent invention I have made. In the last 10 minutes.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138393, 139349, 139384, 139385, 139386 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110424, ["x"] = 0.4455, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 110424, ["x"] = 0.4455, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4455, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 41009 } },
[43371] = { ["id"] = 43371, ["name"] = "Relieving the Front Lines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Many within our order have been on the front lines of battle for too long, aiding those who are attempting to thwart the Legion's invasion. It is time we send in some relief, allowing our allies some much needed rest.", ["objectivesText"] = "Interact with the Command Map and complete the mission, \"Relieving the Front Lines\".", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.485, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.485, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.511, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43277 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43372] = { ["id"] = 43372, ["name"] = "Whispers in the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Our priests are resting and recuperating, but one not as well as the others. Gilner Greymoss lingers within the Sanctuary of the Void, laughing to himself. He refuses to leave, but his presence is making the other priests uneasy. Perhaps you should speak to him and see what is wrong?", ["objectivesText"] = "Speak to Gilner Greymoss in the Sanctuary of the Void. Progress: Some wounds are too deep to heal.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.512, ["y"] = 0.487, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.512, ["y"] = 0.487, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.512, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43371 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43373] = { ["id"] = 43373, ["name"] = "The Best and Brightest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "If we wish to see the truth in Gilner's ramblings, I will need to induce a vision. It is not the sort of thing that is typically forced, but we have within our ranks the best and brightest alchemists who can craft an extract that will grant me the sight I need. Seek them out in Azsuna where they are currently aiding those on the front lines.", ["objectivesText"] = "Find Zabra Hexx in Azsuna.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110557 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questGiverID"] = 110557, ["questType"] = "standard", ["sourceQuests"] = { 43372 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43374] = { ["id"] = 43374, ["name"] = "Murloc Mind Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Yalia and I were deliverin' antidotes to da front lines a Faronaar when we were attacked by a herd a murlocs. We dropped our supplies and made a run for it, but Yalia never made it out a da camp. Obviously I didn't fair much better, ma bones still ache from bein' turned to stone. It's possible Yalia's still alive and bein' held captive. Please, ya have to find her!", ["objectivesText"] = "Rescue Yalia Sagewhisper from the murlocs within El'dranil Shallows.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 112487, ["x"] = 0.585, ["y"] = 0.371 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43373 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43375] = { ["id"] = 43375, ["name"] = "An Ample Supply", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Durin' our attempt to flee da murlocs, Yalia and I dropped da supplies we planned to deliver to da demon hunters in Faronaar. Inside each a those crates were vials a salve dat took us countless days and resources to craft. If we don' get those supplies back, I fear our allies on da front lines will suffer.", ["objectivesText"] = "Recover Felbat Toxin Salve from supply crates scattered around El'dranil Shallows. Progress: Do ya have our supplies?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139458, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43374 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43376] = { ["id"] = 43376, ["name"] = "Problem Salver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Forcing a vision isn't easy by any means. Finding the ingredients for the elixir alone will take a considerable amount of time, time we don't have. Too many are suffering on the front lines as we speak, in need of the salve we were meant to deliver. I suppose if we all work together, we can make this work. Zabra and I will find the items needed for Velen's elixir, if you take the salve to Faronaar and cure the demon hunters . Does that sound fair?", ["objectivesText"] = "Use the salve on diseased demon hunters at Faronaar Front in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139463 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 112487, ["x"] = 0.585, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110687, ["x"] = 0.493333, ["y"] = 0.387333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43374, 43375 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43377] = { ["id"] = 43377, ["name"] = "Halls of Valor: The Light Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "We cannot ignore the Prophet's vision, <name>. To do so would mean that everything we know and hold dear will be lost to the Legion. We must focus on what we know, and that is that the Light must walk among us. Within the Halls of Valor you will find an ascending val'kyr by the name of Hyrja. Recover a spark of her Light and release it within our temple.", ["objectivesText"] = "Recover a Spark of Light from Hyrja within the Halls of Valor dungeon.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 139485 }, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.516, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "dungeon", ["sourceQuests"] = { 43379 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43378] = { ["id"] = 43378, ["name"] = "Eye of Azshara: Looking Through the Lens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "We have what we need to create Velen's elixir, but in order for others to be able to witness his vision, we'll need to find something that can be used to project images from the mind. A lens from the nearby naga should work well, but I don't think they're going to be too eager to give it up.", ["objectivesText"] = "Recover the Lens of the Tide from Lady Hatecoil within the Eye of Azshara dungeon. Progress: Gazing through the lens of a powerful naga will allow you to witness my vision.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128825, 128827, 128868, 139464, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110687, ["x"] = 0.493333, ["y"] = 0.387333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110687, ["x"] = 0.493333, ["y"] = 0.387333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.493333, ["y"] = 0.387333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7834 } }, ["questTurnInID"] = 110687, ["questType"] = "dungeon", ["sourceQuests"] = { 42137, 42138 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43379] = { ["id"] = 43379, ["name"] = "Velen's Vision", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "I have everything I need to bring forth a vision, but the question remains: are you ready to witness it? Even the smallest glimpse into the future can weigh heavy on your soul. Once I ingest the elixir, the vision will come quickly. Gazing into the Lens of the Tides will allow you to see what I see. Let me know when you are ready to begin.", ["objectivesText"] = "Use the Lens of the Tides to witness Prophet Velen 's vision. Progress: Even the smallest glimpse into the future can leave a heavy weight on your mind.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 140517, 140930 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["x"] = 0.483, ["y"] = 0.478, ["mapID"] = 702, ["npcID"] = 110557 } }, ["ends"] = { { ["x"] = 0.483, ["y"] = 0.478, ["mapID"] = 702, ["npcID"] = 110557 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.483, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110557, ["questTurnInID"] = 110557, ["questType"] = "standard", ["sourceQuests"] = { 43378 }, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
