[43382] = { ["id"] = 43382, ["name"] = "Champion: Natalie Seline", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["starts"] = { { ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.378, ["mapID"] = 47 } }, ["ends"] = { { ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.378, ["mapID"] = 47 } }, ["coords"] = { ["x"] = 0.242, ["y"] = 0.378, ["source"] = "quest_giver", ["mapID"] = 702 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["sourceQuests"] = { 43392 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 47 },
[43383] = { ["id"] = 43383, ["name"] = "Awakening the Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "This spark will only know its full potential once it's been filled with pure Light, gleaned from the holiest places in our world. Nurture this spark, and it may grow to walk among you.", ["objectivesText"] = "Collect Pure Holy Light by completing Class Hall missions. Progress: <Saa'ra's soothing voice fills your mind.> Nurture the spark with holy Light if you wish it to awaken and walk among you.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 139368 }, ["starts"] = { { ["x"] = 0.757, ["y"] = 0.407, ["mapID"] = 702, ["npcID"] = 110864 } }, ["ends"] = { { ["x"] = 0.757, ["y"] = 0.407, ["mapID"] = 702, ["npcID"] = 110864 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.757, ["y"] = 0.407 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 110864, ["questTurnInID"] = 110864, ["questType"] = "standard", ["sourceQuests"] = { 43377 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43384] = { ["id"] = 43384, ["name"] = "Demonic Runes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "I cannot stand by idly and allow the Legion to destroy our home. I've been studying their language for some time, deciphering any runes I can get my hands on, but my supply is severely limited. If I had more runes to study, it's possible that I may discover something that will help us in locating Balnazzar.", ["objectivesText"] = "Collect Demonic Runestones from demons throughout the Broken Isles. Progress: Were you able to recover the runestones?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128825, 128827, 128868, 138817, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.487, ["mapID"] = 702, ["npcID"] = 110571 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.487, ["mapID"] = 702, ["npcID"] = 110571 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.489, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 110571, ["questTurnInID"] = 110571, ["questType"] = "standard", ["sourceQuests"] = { 43379 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43385] = { ["id"] = 43385, ["name"] = "Infiltrating Our Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "With the Light at our side, we should focus our efforts on figuring out who among our enemies could be a potential ally. Any of your champions should be capable of infiltrating enemy ranks, giving us a better understanding of how to approach this. Even so, it is a delicate task. Proceed with caution.", ["objectivesText"] = "Interact with the Command Map and complete the mission, \"Infiltrating Our Enemies\".", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.515, ["y"] = 0.477, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.515, ["y"] = 0.477, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.515, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43377, 43384 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43386] = { ["id"] = 43386, ["name"] = "Onslaught Envoy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 115, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "A few defectors have been discovered among the Scarlet Onslaught in Northrend. I know it's difficult to think that any within their ranks could be useful to our cause, but we must make an attempt. The prophecy says an old enemy will become an ally, so it's worth it to investigate and see if these defectors can be brought to the Light.", ["objectivesText"] = "Find a new ally among old enemies in New Hearthglen.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.515, ["y"] = 0.477, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43385 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43387] = { ["id"] = 43387, ["name"] = "Scarlet Redemption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The Light shines upon me, <name>! For the first time in my life, I feel it! I was without hope, ready to die for the things I had done in the name of the Scarlet Crusade, but then you appeared! You are my chance at redemption. Please, let me prove to you that I am worthy of a second chance. Let me slay those I used to be loyal to!", ["objectivesText"] = "Help Mariella the Heretic redeem herself by killing members of the Scarlet Onslaught in New Hearthglen. Progress: I will prove myself worthy of being redeemed.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questTurnInID"] = 110683, ["questType"] = "standard", ["sourceQuests"] = { 43386 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[43388] = { ["id"] = 43388, ["name"] = "Apostate Liberation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "There are others like me, you know. Others that have removed the veil that the Scarlet Crusade has kept over our eyes for so long. They've been placed in cages, treated like animals, simply because their beliefs no longer line up with what the Onslaught deems is right and holy. They wish to redeem themselves. We should try to free them, if you think their lives are worth saving.", ["objectivesText"] = "Rescue Onslaught Apostates within New Hearthglen. Progress: All we want is a chance to redeem ourselves.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questTurnInID"] = 110683, ["questType"] = "standard", ["sourceQuests"] = { 43386 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[43389] = { ["id"] = 43389, ["name"] = "Unexpected Guests", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "You helped me escape my fate by freeing me from the gallows, but allowing me to fight the Scarlet Onslaught by your side has truly freed my heart and mind from the guilt I have felt for so long. I want to be a part of something greater than myself, a noble cause that won't distort the meaning of the Light. Let me travel to your temple and beg forgiveness of the Prophet. I may not be a welcome guest, but it's a journey I must make to complete my redemption.", ["objectivesText"] = "Return to Alonsus Faol in Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["npcID"] = 111191 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 111191, ["questType"] = "standard", ["sourceQuests"] = { 43387, 43388 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43390] = { ["id"] = 43390, ["name"] = "Forgotten Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The Light walks among us, as does one of our enemies. You have done well to bring the prophecy to life, but it is not yet complete. The shadows must rise, and to do so, the Cult of Forgotten Shadows must be restored. You will find the few remaining followers at the cemetery in Duskwood. They linger there near the grave of their fallen leader.", ["objectivesText"] = "Head to Duskwood and meet with a member of the Cult of Forgotten Shadows.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.489, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43381 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43391] = { ["id"] = 43391, ["name"] = "Secrets of the Void", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "Our leader was murdered for her beliefs, or so most would believe. Natalie Seline knew her fate, and took steps to protect herself from an inevitable death. The night her attackers came, Natalie sent her spirit to the Void, its location known only to Natalie herself. She penned a spell to retrieve it in one of her many journals, but the tome has since fallen into the hands of those who wished her dead in the first place. Without her journal, we will never be able to recover her spirit.", ["objectivesText"] = "Recover Natalie's Journal from Twilight Lord Urgrok. Progress: We watch over Natalie's body, forever hopeful that her spirit will return.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 139772, 140517, 140930 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 43390 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 47 },
[43392] = { ["id"] = 43392, ["name"] = "Into the Void", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "This is without a doubt Natalie's writing. The entry was scrawled in haste, but the message is clear: The spell within this journal will lead us to Natalie's spirit, but it needs to be incanted at a shadow altar within the catacombs. Odessa and I have a duty to watch over Natalie's body, but with your considerable power, you should be able to perform the spell with ease.", ["objectivesText"] = "Read Natalie's Journal at the catacomb's shadow altar to enter the void and recover her spirit.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["sourceQuests"] = { 43391 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 47 },
[43393] = { ["id"] = 43393, ["name"] = "Rising Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "News of my return will spread fast among those who share my beliefs. Soon Azeroth will see the rise of Shadows, but I imagine this is not news to you. Whatever your plan may be, I hope it continues to see the Cult of Forgotten Shadows as allies.", ["objectivesText"] = "Return to Alonsus Faol at Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7834 } }, ["questTurnInID"] = 110684, ["questType"] = "standard", ["sourceQuests"] = { 43382 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43394] = { ["id"] = 43394, ["name"] = "Crossing Legion Lines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 748, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "I've received word from the Highlord that a group of paladins and priests were captured after a battle broke out at Felblaze Ingress. Your priestess, Delas Moonfang, was among those captured. They've been taken through the demon portal and into the Legion stronghold of Niskara. We will need the assistance of the Conclave if we have any hope of recovering them.", ["objectivesText"] = "Use the demon portal at Felblaze Ingress to enter Niskara and find Aponi Brightmane . Progress: I've never been so happy to see you, <class>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.595, ["mapID"] = 702, ["npcID"] = 111044 } }, ["ends"] = { { ["x"] = 0.498, ["y"] = 0.595, ["mapID"] = 702, ["npcID"] = 111044 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.498, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 111044, ["questTurnInID"] = 111044, ["questType"] = "standard", ["sourceQuests"] = { 43393 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1604, ["db2PoiUiMapID"] = 748 },
[43395] = { ["id"] = 43395, ["name"] = "Allies of the Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies. We cannot leave them, <name>.", ["objectivesText"] = "Looking for Paladin quest? See Allies of the Light . Save Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.636, ["mapID"] = 748, ["npcID"] = 110969 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.636, ["mapID"] = 748, ["npcID"] = 110969 } }, ["coords"] = { ["mapID"] = 748, ["x"] = 0.489, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questGiverID"] = 110969, ["questTurnInID"] = 110969, ["questType"] = "standard", ["sourceQuests"] = { 43394 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43396] = { ["id"] = 43396, ["name"] = "The Mind of the Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly. Let us find whatever information we can about their plans.", ["objectivesText"] = "Find the Legion Intelligence, Star Map, and Image of Velen, then slay Brood Queen Aramis .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.636, ["mapID"] = 748, ["npcID"] = 110969 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.636, ["mapID"] = 748, ["npcID"] = 110969 } }, ["coords"] = { ["mapID"] = 748, ["x"] = 0.489, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questGiverID"] = 110969, ["questTurnInID"] = 110969, ["questType"] = "standard", ["sourceQuests"] = { 43394 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43397] = { ["id"] = 43397, ["name"] = "United As One", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 24, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "You and Delas have had dealings with the paladins before, maybe it's possible they will grant you an audience with their war council. Head to the Sanctum of Light and ask the paladins to help us defend Netherlight Temple from Balnazzar's attack.", ["objectivesText"] = "Make your way to the Sanctum of Light to speak with Lady Liadrin , and hear the council of war. Progress: Now is not the time for interruptions, <name>. The council needs to determine its course of action.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128825, 128827, 128868, 136928, 139506, 139697, 139757, 139759, 140517, 140930, 150745, 150746 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.485, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.485, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.511, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43395, 43396 }, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
