[43399] = { ["id"] = 43399, ["name"] = "Fortifying the Temple", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "We've all worked so hard turning this temple into something all priests can be proud of, it would be a shame to see it fall to the Burning Legion. We must strengthen our defenses in preparation for the attack. With the right resources, we can make the temple a nearly impenetrable fortress.", ["objectivesText"] = "Complete 10 World Quests. Progress: We will need to gather many resources in order to properly fortify the temple.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124105, 124111, 124120, 124124 }, ["starts"] = { { ["x"] = 0.509, ["y"] = 0.468, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.509, ["y"] = 0.468, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.509, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43797 }, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43400] = { ["id"] = 43400, ["name"] = "Lumenstone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "To prepare for the battle, we will need the best armor and weapons we can get. Lumenstone is an enchanted material that can withstand great amounts of fel magic. It is found in rare quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting. We should send our champions to target enemies around the Broken Isles - there should be plenty of Lumenstone to be found in their stockpiles.", ["objectivesText"] = "Collect 50 Lumenstone by sending champions on \" Lumenstone \" missions. Progress: Have you acquired any lumenstone ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140191 }, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.478, ["mapID"] = 702, ["npcID"] = 109776 } }, ["ends"] = { { ["x"] = 0.513, ["y"] = 0.478, ["mapID"] = 702, ["npcID"] = 109776 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.513, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 109776, ["questTurnInID"] = 109776, ["questType"] = "standard", ["sourceQuests"] = { 43797 }, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43401] = { ["id"] = 43401, ["name"] = "A Light in the Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "The Burning Legion has begun their attack! I will remain here and prepare the temple's defenses. You must meet our allies in Dalaran and let them know that the battle has begun! Make haste, <name>. I do not know how long we will be able to keep Balnazzar at bay.", ["objectivesText"] = "United with the paladins, defend Netherlight Temple and slay Lord Balnazzar . Progress: The paladins have always been our allies and friends. Now, we stand united against a common cause.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139448, 139450, 139506, 139757, 139759, 140517, 140930 }, ["starts"] = { { ["x"] = 0.51, ["y"] = 0.484, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.51, ["y"] = 0.484, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.51, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43399, 43400, 43832 }, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43402] = { ["id"] = 43402, ["name"] = "High Priest of Netherlight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "You have fulfilled the prophecy, but more than that, you have united the priests of Azeroth. We should take a moment to recognize all that you have accomplished.", ["objectivesText"] = "Listen as you are honored by the Conclave of priests. Progress: We rejoice in your triumph!", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139759, 142055, 142057, 142062, 142063 }, ["rewardChoices"] = { 142055, 142057, 142062, 142063 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.51, ["y"] = 0.484, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.51, ["y"] = 0.484, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.51, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43398 }, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43403] = { ["id"] = 43403, ["name"] = "Defending the Isles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "As druids, our charge is to defend nature... and in turn, our home, Azeroth. Conflict breaks out all across the Broken Isles. The Burning Legion pushes forward, and numerous allies call out for our aid. We must focus our efforts on defense, before we can mount an offense against the Nightmare. Help our allies across the Broken Isles, then return to me when the situation is under control.", ["objectivesText"] = "Complete 10 World Quests. Progress: Conflict rages across the Broken Isles.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["starts"] = { { ["x"] = 0.448, ["y"] = 0.506, ["mapID"] = 747, ["npcID"] = 103832 } }, ["ends"] = { { ["x"] = 0.448, ["y"] = 0.506, ["mapID"] = 747, ["npcID"] = 103832 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.448, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 103832, ["questTurnInID"] = 103832, ["questType"] = "standard", ["sourceQuests"] = { 42046, 42047, 42048 }, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
