[43424] = { ["id"] = 43424, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 43424 }, ["description"] = "<class>t, you've brought together the Silver Hand like no <class>t has done before. You've shown us that with determination and faith in the holy light we can overcome any challenge. Following in your example our workmen have toiled hard to improve the Altar of Ancient Kings, allowing it to unlock the true potential of your weapon. Their work is now complete! Step forward when you are ready and we shall begin.", ["objectivesText"] = "Approach the indicated location before the Altar of Ancient Kings and raise your weapon. Progress: Well done, Highlord.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["x"] = 0.726, ["y"] = 0.258, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.726, ["y"] = 0.258, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.726, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 43697 } },
