[43461] = { ["id"] = 43461, ["name"] = "A Time to Reflect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 43461 }, ["description"] = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", ["objectivesText"] = "Correctly answer one of Ju'Pa's questions about the history of Azeroth. Progress: Let us speak, then, of events that have already come to pass.", ["rewardGold"] = 1215200, ["rewardXP"] = 2830, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.7445 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 } },
[43462] = { ["id"] = 43462, ["name"] = "Mother Ozram", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42886, 42887, 42888, 42890 }, ["description"] = "The fiendish imps in this region are an incessant pain on our allies defending the camps below. They are the spawn of a wicked imp-mother named Mother Ozram , who has been seen on a hill to the south. Destroy her, and we will end her brood as well.", ["objectivesText"] = "Kill Mother Ozram . Progress: Do not be deceived by the imp-mothers. They are devious and strong.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 109384, ["x"] = 0.306, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 109384, ["x"] = 0.306, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 109384, ["questType"] = "standard", ["sourceQuests"] = { 42887 }, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43468] = { ["id"] = 43468, ["name"] = "Blood for the Wolfe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 42684, 43249, 43250, 43253 }, ["description"] = "We have a request in from Winstone Wolfe. He says that he needs a rather large amount of demon blood. He was not specific what for, and I did not ask. I am inclined to do this for him with all expediency. The Wolf rarely asks for anything, so when he does, we jump. He gets results, one-hundred percent of the time and then some. We should show him the same professional courtesy.", ["objectivesText"] = "Collect 50 Fel Blood . Progress: The clock is ticking, <name>. Do you have the blood?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 137677, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["ends"] = { { ["x"] = 0.408, ["y"] = 0.753, ["mapID"] = 626, ["npcID"] = 98102 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.408, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98102, ["questTurnInID"] = 98102, ["questType"] = "standard", ["sourceQuests"] = { 44181 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[43469] = { ["id"] = 43469, ["name"] = "Where In the World is Mathias?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43470, 43479, 43485 }, ["description"] = "Master Mathias Shaw is the leader of the Alliance intelligence organization known as SI:7. And apparently, he is now a dreadlord. Or rather, a very clever dreadlord has taken his place while he is being held captive somewhere. It is imperative that we reveal this imposter to the new king of Stormwind. If we fail to do so, then the Alliance will surely be eaten alive from within and the Burning Legion will win this war for a certainty.", ["objectivesText"] = "Use the Scouting Map and complete the \"Where In the World is Mathias Shaw?\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["ends"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.406, ["y"] = 0.767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98100, ["questTurnInID"] = 98100, ["questType"] = "standard", ["sourceQuests"] = { 42680 }, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[43470] = { ["id"] = 43470, ["name"] = "Pruning the Garden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43469, 43479, 43485 }, ["description"] = "In a very real sense, the Uncrowned are gardeners. We snip and trim here and there. One clipping of a single branch may seem nonsensical until you step back and look at the garden as a whole. On the greater theater of the Broken Isles, we must act decisively. The forces that arrayed against Azeroth are moving quickly. We need to prune some very ugly flowers to make our garden beautiful again, wouldn't you agree, <name>?", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["starts"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["ends"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.406, ["y"] = 0.767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98100, ["questTurnInID"] = 98100, ["questType"] = "standard", ["sourceQuests"] = { 42680 }, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[43471] = { ["id"] = 43471, ["name"] = "The Historians", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 440, ["mapID"] = 84, ["storyline"] = { 43471 }, ["description"] = "<name>, each year I visit Stormwind to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Stormwind Royal Library and we can speak more.", ["objectivesText"] = "Meet with Historian Llore in the Royal Library of Stormwind.", ["rewardGold"] = 303800, ["rewardXP"] = 200, ["rewardItems"] = { 139409 }, ["starts"] = { { ["x"] = 0.846, ["y"] = 0.25, ["mapID"] = 84 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 110034, ["x"] = 0.845, ["y"] = 0.253 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.845, ["y"] = 0.253 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 139409 } },
