[43479] = { ["id"] = 43479, ["name"] = "The World is Not Enough", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43469, 43470, 43485 }, ["description"] = "Now that we have pruned the garden, it is time to dig up the rotting tree stump in the middle. Put another way, we need to make sure to keep the forces of chaos from overwhelming the Broken Isles. Certainly others are helping in this endeavor. However, I am sure the target you select to eliminate will be the wisest from the standpoint of the Uncrowned.", ["objectivesText"] = "Complete any 1 \"Rare Elite\" World Quest designated by a diamond surrounded by a gold dragon on the area maps. Progress: And have you dug up that tree stump yet, <name>?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["starts"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["ends"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.406, ["y"] = 0.767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98100, ["questTurnInID"] = 98100, ["questType"] = "standard", ["sourceQuests"] = { 43470 }, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
