[43485] = { ["id"] = 43485, ["name"] = "A Burning Distraction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43469, 43470, 43479 }, ["description"] = "We're going to need a distraction if we are to rescue Mathias Shaw from where he's being held captive in Felsoul Hold. A big one. Explosives placed in a few key locations should do nicely. Noggenfogger is playing nice and has donated some bombs to the cause. He might be trying to smooth over relations due to his earlier extortion. I can have someone go ahead and mark the best locations. You want to do the honors?", ["objectivesText"] = "Place the Noggenfogger Boom Bombs on your way through Felsoul Hold and then trigger the Detonator to set them off. Progress: As soon as you set all of the explosives and push the button, we will proceed.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["x"] = 0.406, ["y"] = 0.767, ["mapID"] = 626, ["npcID"] = 98100 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110714, ["x"] = 0.298, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questGiverID"] = 98100, ["questType"] = "standard", ["sourceQuests"] = { 43469, 43479 }, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43486] = { ["id"] = 43486, ["name"] = "Cracking the Codex", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43487, 49812 }, ["description"] = "I have been studying the Codex of Command that you recovered from Faronaar. It is important to Balnazzar, but WHY? What does it say? I'm sure we could gain valuable knowledge if we could just crack this code. I have a friend who might be able to help us: a priestess named Delas Moonfang . She has been studying Eredun, the language of the demons. Take the sigil to her in Dalaran. Tell her I sent you.", ["objectivesText"] = "Speak to Delas Moonfang in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.484, ["y"] = 0.728, ["mapID"] = 24, ["npcID"] = 90251 } }, ["ends"] = { { ["x"] = 0.484, ["y"] = 0.728, ["mapID"] = 24, ["npcID"] = 90251 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.484, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90251, ["questTurnInID"] = 90251, ["questType"] = "standard", ["sourceQuests"] = { 42851, 42852 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[43487] = { ["id"] = 43487, ["name"] = "Assault on Violet Hold: The Fel Lexicon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43486, 49812 }, ["description"] = "I have been studying the language of the demons, but it has been difficult to get my hands on written material. I have heard rumor of a book called the Fel Lexicon , written by an ancient scholar who spoke both eredun and draenei. If I could just get my hands on that book, I could learn so much! I heard that this book might be in the hands of a powerful prisoner inside the Violet Hold. Bring me this book, and my work here will go much faster.", ["objectivesText"] = "Collect a Fel Lexicon from a powerful prisoner inside Violet Hold. Progress: I am fairly adept in twelve different languages, and I hope to add more to the list.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139445, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.231, ["mapID"] = 627, ["npcID"] = 110571 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.231, ["mapID"] = 627, ["npcID"] = 110571 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.446, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110571, ["questTurnInID"] = 110571, ["questType"] = "dungeon", ["sourceQuests"] = { 43486 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[43488] = { ["id"] = 43488, ["name"] = "Blood of Our Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "I have seen demonic artifacts before, <name>. Legion sigils will only reveal themselves in the presence of demon blood. I sense that time is of the essence. Bring me a large quantity of demon blood, so that I may translate the book as soon as you retrieve it.", ["objectivesText"] = "Send your champions on \"Blood of Our Enemy\" missions against the Burning Legion and collect 5 Flasks of Demon Blood . Progress: The last time, I tried to use a living demon. It ended rather poorly... for the demon.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139465 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.231, ["mapID"] = 627, ["npcID"] = 110571 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.231, ["mapID"] = 627, ["npcID"] = 110571 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.446, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110571, ["questTurnInID"] = 110571, ["questType"] = "standard", ["sourceQuests"] = { 43486 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[43489] = { ["id"] = 43489, ["name"] = "To Felblaze Ingress", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 630, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43493 }, ["description"] = "I have sobering news, Highlord. We have had no word from Chieftain Aponi Brightmane, young Arator, or priestess Delas Moonfang since they departed for Felblaze Ingress. We need to know what happened to them. We fear the worst.", ["objectivesText"] = "Find Aponi Brightmane at Felblaze Ingress in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43493 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43490] = { ["id"] = 43490, ["name"] = "Aponi's Trail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 748, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "<The book is missing several pages. Nearby, you can see signs of a struggle.> <If you can seek the missing pages on the nearby demons, perhaps you could learn what fate befell your allies.>", ["objectivesText"] = "Find 8 pages of Aponi's journal, then use them to track her down. Progress: I've never been so happy to see you, Highlord.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139540, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.662, ["y"] = 0.261, ["mapID"] = 630, ["objectID"] = 252232 } }, ["ends"] = { { ["x"] = 0.662, ["y"] = 0.261, ["mapID"] = 630, ["objectID"] = 252232 } }, ["coords"] = { ["mapID"] = 630, ["x"] = 0.662, ["y"] = 0.261 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43489 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1604, ["db2PoiUiMapID"] = 748 },
[43491] = { ["id"] = 43491, ["name"] = "Allies of the Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies. We cannot leave them, <name>.", ["objectivesText"] = "Looking for Priest quest? See Allies of the Light . Save 5 Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.637, ["mapID"] = 748, ["npcID"] = 110749 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.637, ["mapID"] = 748, ["npcID"] = 110749 } }, ["coords"] = { ["mapID"] = 748, ["x"] = 0.489, ["y"] = 0.637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questGiverID"] = 110749, ["questTurnInID"] = 110749, ["questType"] = "standard", ["sourceQuests"] = { 43490 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
