[43493] = { ["id"] = 43493, ["name"] = "Black Rook Hold: Lord Ravencrest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43489 }, ["description"] = "Highlord, news has reached us of a Legion presence at Black Rook Hold. It is rumored that the night elf commander, Kur'talos Ravencrest, amasses an enormous army behind the fortress walls. Take a group of your most powerful allies, Highlord, and investigate these stories. Lord Ravencrest was a formidable general during Azshara's reign, and if the reports are true, then we must know more.", ["objectivesText"] = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold. Progress: It is vital that we stay on top of the Legion's movements. At any moment, they could attack.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "dungeon", ["sourceQuests"] = { 43535 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
[43494] = { ["id"] = 43494, ["name"] = "Silver Hand Knights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 43494 }, ["description"] = "Good news, Highlord! We have recruited a paladin trainer named Commander Born . He is a hard teacher, but has trained some of the greatest paladin knights in recent times. We are lucky to have his services. Go speak to him, and train a squad of Silver Hand Knights.", ["objectivesText"] = "Speak to Commander Born .", ["rewardGold"] = 238680, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 42890 } },
[43496] = { ["id"] = 43496, ["name"] = "The Power Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 739, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "My apologies for the unannounced intrusion, <name>. Do you have a moment? The power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely! The very thought demands we find out for sure. You are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", ["objectivesText"] = "Meet Archmage Kalec at Azurewing Repose in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 132471, 139631, 139671, 139672, 139706, 139780, 140196, 140197, 140198, 140199 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110768, ["x"] = 0.484286, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.484286, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 630, 739 }, ["zone"] = { 8022 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
