[43501] = { ["id"] = 43501, ["name"] = "The Power Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 739, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "My apologies for the unannounced intrusion, <name>. Do you have a moment? The power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely! The very thought demands we find out for sure. The ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", ["objectivesText"] = "Complete the \"Defending Azurewing Repose\" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110768, ["x"] = 0.484286, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.484286, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 630, 739 }, ["zone"] = { 8022 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43502] = { ["id"] = 43502, ["name"] = "A Change of Seasons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43562, 43563 }, ["description"] = "It is time. The arcan'dor is preparing to mature. With a final burst of growth, this gift will be fully realized. We must make ready the leyline feed.", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43362 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
