[43506] = { ["id"] = 43506, ["name"] = "Black Rook Hold: Greater Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "The raw power of the runestones will allow Hymdall to temporarily open a tear into demonic worlds, but it's not enough. The Legion hides its presence in far away worlds with dark magic. Bring a greater runestone so that Hymdall can hone in on our enemies across the cosmos.", ["objectivesText"] = "Defeat Lord Kur'talos Ravencrest and retrieve a Greater Demonic Runestone from Dantalionax in the Black Rook Hold Dungeon. Progress: Do you bring the runestone we require, <name>?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139453 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "dungeon", ["sourceQuests"] = { 42918, 44667 }, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[43508] = { ["id"] = 43508, ["name"] = "The Captive Spymaster", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 37448, 37494, 37666 }, ["description"] = "We must move swiftly while the distraction is working. Mathias Shaw is being held in the lower levels of the Halls of the Eclipse directly to the south. Quickly, <name>, we must go!", ["objectivesText"] = "Follow Taoshi into the Halls of the Eclipse to where Mathias Shaw is being held captive.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110714, ["x"] = 0.298, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110793, ["x"] = 0.27, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43485 }, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43509] = { ["id"] = 43509, ["name"] = "Halls of Valor: Odyn's Challenge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 739, ["storyline"] = { 43509 }, ["description"] = "Odyn himself sends a message. He and his warriors await worthy contenders within the Halls of Valor . Defeat the champions of the Halls of Valor , and claim glory.", ["objectivesText"] = "Defeat Odyn in the Halls of Valor .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139457, 141175 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "dungeon", ["startItems"] = { 139457 } },
