[43513] = { ["id"] = 43513, ["name"] = "Na'zak the Fiend", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43513 }, ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141415, 141417, 141421, 141425, 141488, 141515, 141534, 142121 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 110321 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 112, ["db2QuestInfoName"] = "Epic Elite World Quest" },
[43514] = { ["id"] = 43514, ["name"] = "A Vainglorious Past", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Heart's magic is attuned to Azshara's elite through powerful warding spells. If we tried to tap into its power now we would be met only with our own demise. However, there may be a way we can bypass the wards. Prince Farondis and his court were once a part of Azshara's empire, and still hold on to keepsakes of their sordid past. Among these is sure to be a Vainglorious Draught , said to further bind the queen's followers to her will. See if you can convince the court to part with a bottle.", ["objectivesText"] = "Obtain a Vainglorious Draught from Veridis Fallon. Progress: It may take some effort to convince Farondis' people to part with the draught; some among them still cling desperately to their past lives.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40668 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43517] = { ["id"] = 43517, ["name"] = "Darkheart Thicket: Fallen Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Once we have the proper implements we can use the Heart to infuse great power into your artifact. We need only a source. Deep within the Darkheart Thicket lies the ancient Oakheart, once a great and mighty protector of Shaladrassil. He has regrettably fallen to the nightmare like so many of his kin. As the darkness within him has taken root, an essence of the corruption has manifested. I ask that you recover the essence so that we may draw from its power, and put noble Oakheart to rest.", ["objectivesText"] = "Recover a Corrupted Essence from Oakheart and defeat the Shade of Xavius in Darkheart Thicket on Mythic difficulty. Progress: You have the essence?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139633 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40668 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43518] = { ["id"] = 43518, ["name"] = "Tempering Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "I do not doubt Senegos' plan, but I do have some concerns about the Heart's volatility, especially when combined with nightmare energy. Despite its name, Blood of Sargeras is often used as a tempering agent by master craftsmen. I believe it would work for our ritual as well. You should keep an eye out for it during your travels - we'll need a substantial amount to ensure that everything goes smoothly.", ["objectivesText"] = "Obtain 5 Blood of Sargeras . Progress: It can be difficult to extract properly, but I do not wish to leave anything to chance.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 132471, 139631 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 40668 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43519] = { ["id"] = 43519, ["name"] = "Lucid Strength", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We have everything we need, <name>. Once you are ready, raise your artifact and channel its energy upon the Heart of Zin-Azshari to safely absorb the power stored within the nightmare essence. I will use the blood you provided to make sure the ritual stays safely contained.", ["objectivesText"] = "Absorb the power from the Corrupted Essence using the Heart of Zin-Azshari. Progress: This is but the first step in unlocking the true potential hidden away deep within your artifact, but it is an exciting milestone nonetheless.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 140304 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43514, 43517, 43518 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43520] = { ["id"] = 43520, ["name"] = "The Emerald Nightmare: In Nightmares", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We must do what we can to ensure that the Nightmare never again festers within the Emerald Dream. The aberration known as Il'gynoth lies at the heart of the corruption - a living, writhing manifestation of the horrors you will encounter at every turn of your journey. I ask that you ensure its destruction, along with the Nightmare Lord himself... Xavius. Once the deeds have been done, bring a small piece of each to me. We can study them to figure out just how the Nightmare grew so quickly.", ["objectivesText"] = "Obtain a Deathglare Iris and the Horn of the Nightmare Lord from the Emerald Nightmare on Normal difficulty or higher. Progress: Is the deed done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139671, 139672 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "raid", ["sourceQuests"] = { 43519, 43581 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43521] = { ["id"] = 43521, ["name"] = "The Emerald Nightmare: Essence of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Now that we have a better understanding on the Heart's capabilities, it is time we tap into its true potential. In the Emerald Nightmare you will find creatures that should not be; monsters that defy all that the Dream stands for. All that the green flight itself stands for. Each of these fiends carry within them corrupted essence , as Oakheart did, but far more potent. Gather all that you can, and we will turn their corruption against them.", ["objectivesText"] = "Collect 10 Corrupted Essence from the Emerald Nightmare on Normal difficulty or higher. Progress: The task before you is not simple, but I have faith in your abilities.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139771, 139780, 140198, 140199 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "raid", ["sourceQuests"] = { 43519, 43581 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43522] = { ["id"] = 43522, ["name"] = "Essential Consumption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "As before, <name>, once you are ready raise your artifact and channel its energy upon the Heart of Zin-Azshari and we will unleash the power of the essence you gathered. Do not worry - we still have enough of the blood you gathered to ensure the ritual remains stable.", ["objectivesText"] = "Absorb the combined power of the Corrupted Essences using the Heart of Zin-Azshari. Progress: After all you have done for my flight, this is but a small favor in return.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 140305 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43520 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43523] = { ["id"] = 43523, ["name"] = "Repaid Debt", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Moon Guard fought against the Legion many years ago, during the War of the Ancients. Their intimate knowledge of our enemies would be invaluable to our cause. They have remained in Shal'Aran since you saved Thalrenus and his kin. Shall we pay them a visit and see what they can do?", ["objectivesText"] = "Meet Archmage Kalec inside Shal'Aran in Suramar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43522 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43524] = { ["id"] = 43524, ["name"] = "Court of Stars: Literary Perfection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Out of all the books, why that one?! Oh, Mother Moon, I am but a trusting fool. I apologize, you have no idea what I'm going on about. I lent my first edition copy of \" Wards, Sigils, and the Nightborne Way \" to a dear friend - well, former friend, I should say - just before the betrayal. As fate would have it, there is an incantation in that book that I will need for my part of the ritual. Please retrieve it if you can, but be careful - it is quite valuable!", ["objectivesText"] = "Find Lothrius' first edition copy of \" Wards, Sigils, and the Nightborne Way \" in the Court of Stars on Mythic difficulty. Progress: Did you find it? Oh, please tell me you found it!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139782 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101082, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101082, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40673 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43525] = { ["id"] = 43525, ["name"] = "Vault of the Wardens: Borrowing Without Asking", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The elusive Wardens run an immense secret prison facility deep underneath the mountains of Azsuna housing all manner of terrible creatures. Perhaps... 'used to run' is more accurate. This presents us with a unique opportunity. The wardens used powerful containment crystals to encase each prisoner in their cell. If any of them still remain intact, we could use one to safely contain the Heart's power. They certainly won't be needing them.", ["objectivesText"] = "Recover a Containment Crystal from the Vault of the Wardens on Mythic difficulty. Progress: Any luck?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139788 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 40673 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43526] = { ["id"] = 43526, ["name"] = "A True Test", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Vizuul's runebindings are more potent than I had anticipated. Not a bad thing - more power is certainly welcome - but there's certainly more potential for catastrophe if the spell matrix somehow becomes unstable. We should be able to safely contain the fel energy within the containment field using the eon winder you recovered... but keep an eye open just in case.", ["objectivesText"] = "Absorb the power from the Twisted Runebindings using the Heart of Zin-Azshari. Progress: I'm sure we'll be able to keep everything stable.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40678 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43527] = { ["id"] = 43527, ["name"] = "Saving the Guard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Moon Guard were once among the most powerful sorcerers on Azeroth. Most assumed their ranks demolished after the War of the Ancients, but it seems they have managed to survive in their ancient stronghold in Suramar! I believe they could be valuable allies in our quest if they still oppose the Legion. <name>, if you can save what remains of the Guard, I will work to convince the Council of Six to lend us additional aid.", ["objectivesText"] = "Complete the \"Moon Guard Stronghold\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43522 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43528] = { ["id"] = 43528, ["name"] = "Planning the Assault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself. We just need a way inside. I am working fervently with the rest of the Council of Six to secure an entrance. Once we have, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills.", ["objectivesText"] = "Await the opening of the Nighthold, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 111814, ["x"] = 0.625, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 634, 680 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 43898 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 30, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43530] = { ["id"] = 43530, ["name"] = "The Nighthold: Delusions of Grandeur", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Grand Magistrix Elisande and her cohorts have lost their minds - they truly believe that allying themselves with the Legion will end in anything but their own demise! They are too far gone to save, I'm afraid, but they still have powerful items that we can use to help us infuse the Heart of Zin-Azshari with their power. In your assault on the Nighthold, ensure you recover the mad construct Trilliax's power core, as well as the spellbook of the Grand Magistrix herself. Good luck.", ["objectivesText"] = "Collect the core of Trilliax and Grand Magistrix Elisande's Millennia Tome in the Nighthold on Normal difficulty or higher. Progress: I ask more of you than I wish, but there is no other way.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140196, 140197, 140198, 140199 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "raid", ["sourceQuests"] = { 43528, 43898 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 31, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43531] = { ["id"] = 43531, ["name"] = "The Nighthold: Into the Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Our work is very nearly complete. Now that the Heart can safely absorb power from fel magic, we need the strongest sources of it that we can get our hands on. Gul'dan has called the nightborne's elite back to the Nighthold to aid him. The storm of fel energy above the palace has seeped into the very fabric of their being, even making its way into the crystallized pieces of the Nightwell that many carry with them. Those shards are exactly what we need, <name>. Save as many as you can in your assault.", ["objectivesText"] = "Collect 8 Nightshards from the Nighthold on Normal difficulty or higher. Progress: How many Nightshards were you able to retrieve?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 137575, 139631, 139706, 139780, 140198, 140199, 140200 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "raid", ["sourceQuests"] = { 43898 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 32, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43532] = { ["id"] = 43532, ["name"] = "The Nighthold: Darkness Calls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Before we perform the ritual there is one last thing I must ask of you, <name>. You must finally bring Gul'dan to justice. No more of his lies, his deceits, or his trickery. None of it can save him now. Take one of his conjured eyes when you're done. Using his power for good will be a fitting end.", ["objectivesText"] = "Bring one of Gul'dan's eyes to Archmage Kalec on Normal difficulty or higher. Progress: Is the deed done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 32483, 132471, 139631, 139706, 139780, 140198, 140199 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "raid", ["sourceQuests"] = { 43898 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 33, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43533] = { ["id"] = 43533, ["name"] = "Balance of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "At long last, it is time to reap the fruits of your labors. Lothrius tells of a place deep in the former Moonguard Stronghold used to infuse new Guards with immense power. It will be the perfect place to tap into and augment the power of the Nightshards you gathered. Gather your effects and meet me there when you are ready, and we will use the Heart to finally reveal the great power within your artifact.", ["objectivesText"] = "Absorb the combined power of the Nightshards and the Eye of Gul'dan using the Heart of Zin-Azshari at the Lunar Crucible. Progress: This is a truly momentous occasion.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199, 140307, 141652 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43530, 43531, 43532 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 34, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43534] = { ["id"] = 43534, ["name"] = "Blood of Sargeras", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras . We will need a plentiful quantity. Bring me whatever you can muster.", ["objectivesText"] = "Collect 3 Blood of Sargeras . Progress: Have you acquired any Blood of Sargeras ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43492, 43933 }, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24 },
[43535] = { ["id"] = 43535, ["name"] = "Translation: Danger!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "<Delas smears fel blood across the lexicon's pages. Alien sigils blaze forth above the paper. She scribbles them down furiously.> My goodness... these are detailed records of the Legion invasion force at Felblaze Ingress. They are planning to open a portal directly to their demon world of Niskara! This is quite serious - we need to alert your allies at once. If you are going back to Light's Hope Chapel, could I accompany you? I would like to offer my services.", ["objectivesText"] = "Speak to Aponi Brightmane at the Sanctum of Light. Progress: Did you bring back the translation?", ["rewardGold"] = 29700, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.231, ["mapID"] = 627, ["npcID"] = 110571 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.231, ["mapID"] = 627, ["npcID"] = 110571 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.446, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110571, ["questTurnInID"] = 110571, ["questType"] = "standard", ["sourceQuests"] = { 43487, 43488 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
[43539] = { ["id"] = 43539, ["name"] = "Salanar the Horseman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 42449 }, ["description"] = "The Four Horsemen will need perfect steeds. This is no simple task. For the next step of our campaign, I have organized a mission to the Realm of Shadows. The goal of the mission is to find Salanar the Horseman, leader of the Dark Riders, and summon him to Acherus. The mission is currently waiting your assignment.", ["objectivesText"] = "Complete the \"Salanar the Horsemen\" mission.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 43267 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43540] = { ["id"] = 43540, ["name"] = "The Mind of the Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly. Let us find whatever information we can about their plans.", ["objectivesText"] = "Find the Legion Intelligence, the Star Map, the Image of Velen, then slay Brood Queen Aramis .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929 }, ["starts"] = { { ["x"] = 0.489, ["y"] = 0.637, ["mapID"] = 748, ["npcID"] = 110969 } }, ["ends"] = { { ["x"] = 0.489, ["y"] = 0.637, ["mapID"] = 748, ["npcID"] = 110969 } }, ["coords"] = { ["mapID"] = 748, ["x"] = 0.489, ["y"] = 0.637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questGiverID"] = 110969, ["questTurnInID"] = 110969, ["questType"] = "standard", ["sourceQuests"] = { 43490 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
[43541] = { ["id"] = 43541, ["name"] = "United As One", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "I am glad you returned safely, Highlord. Delas Moonfang has also arrived with representatives of the Conclave. The priests have come to discuss Netherlight Temple, their seat of power, hidden deep within the Twisting Nether. As you have both discovered, the Legion has been searching for them for quite some time, and now... they have found them. The Silver Hand has agreed to hear their words. Would you join them now, Highlord?", ["objectivesText"] = "Speak to Delas Moonfang and hear the council of war. Progress: Delas has come on behalf of the Conclave.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139506, 139697 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1500 } }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43491, 43540 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
[43545] = { ["id"] = 43545, ["name"] = "Black Rook Hold: The Lord of Black Rook Hold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7805, ["mapID"] = 739, ["storyline"] = { 43545 }, ["description"] = "While investigating the remains of Black Rook Hold , our Champions were ambushed! The Lord of the Rook appears to have allied himself with the Legion. We need your assistance to defeat his growing army, and bring him down.", ["objectivesText"] = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139471, 141176, 141203, 141204 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "dungeon", ["startItems"] = { 139471 } },
[43546] = { ["id"] = 43546, ["name"] = "The Emerald Nightmare: Il'gynoth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8026, ["mapID"] = 739, ["storyline"] = { 43546 }, ["description"] = "Our Champions have discovered the source of the corruption. The Emerald Dream has been infested by the Legion and if we don't put our efforts towards stopping them, this will be only the beginning of the corruption. It must be stopped here.", ["objectivesText"] = "Defeat Il'gynoth in the Emerald Nightmare . Progress: How are you finding the challenges of the Emerald Nightmare ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139480, 139484, 139487 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 8026 } }, ["questType"] = "raid", ["startItems"] = { 139480 } },
[43547] = { ["id"] = 43547, ["name"] = "The Emerald Nightmare: Il'gynoth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8026, ["mapID"] = 739, ["storyline"] = { 43547 }, ["description"] = "Our Champions have discovered the source of the corruption. The Emerald Dream has been infested by the Legion and if we don't put our efforts towards stopping them, this will be only the beginning of the corruption. It must be stopped here.", ["objectivesText"] = "Defeat Il'gynoth in the Emerald Nightmare . Progress: How are you finding the challenges of the Emerald Nightmare ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139232, 139480, 139481, 139484, 139486, 139487 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 8026 } }, ["questType"] = "raid", ["startItems"] = { 139481 } },
