[43550] = { ["id"] = 43550, ["name"] = "Court of Stars: Into the Court of Stars", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8079, ["mapID"] = 680, ["storyline"] = { 43550 }, ["description"] = "The weather is perfect for a party, isn't it? Travel to the Court of Stars , where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.", ["objectivesText"] = "Defeat Advisor Melandrus in Court of Stars .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139457, 139471, 139472, 139473, 139474, 139475, 139476, 139477, 139478, 139479, 139480, 140147, 140163, 140164, 140171, 140172, 140177, 142340, 143328, 143479, 147501, 147505, 147509 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8079 } }, ["questType"] = "dungeon", ["startItems"] = { 139472 } },
[43551] = { ["id"] = 43551, ["name"] = "Darkheart Thicket: Into Darkheart Thicket", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7673, ["mapID"] = 739, ["storyline"] = { 43551 }, ["description"] = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. Not only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", ["objectivesText"] = "Defeat the Shade of Xavius in Darkheart Thicket . Progress: How are you finding the Darkheart Thicket ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139473 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "dungeon", ["startItems"] = { 139473 } },
[43552] = { ["id"] = 43552, ["name"] = "Eye of Azshara: Into the Eye of Azshara", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43552 }, ["description"] = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles. Travel to the Eye of Azshara , and put a stop to the ritual.", ["objectivesText"] = "Defeat the Wrath of Azshara in Eye of Azshara .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139474, 141179 }, ["ends"] = { { ["npcID"] = 99179, ["x"] = 0.528, ["y"] = 0.596, ["mapID"] = 709 }, { ["npcID"] = 106199, ["x"] = 0.666, ["y"] = 0.46, ["mapID"] = 717 } }, ["mapCandidates"] = { ["npc"] = { 709, 717 }, ["zone"] = { 7834 } }, ["questType"] = "dungeon", ["startItems"] = { 139474 } },
[43553] = { ["id"] = 43553, ["name"] = "Maw of Souls: Into the Maw of Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7812, ["mapID"] = 739, ["storyline"] = { 43553 }, ["description"] = "Our scouts report that the vrykul damned are forced to sail aboard the Naglfar, a ship built of death. Travel to the Maw of Souls and confront Helya, before she collects any more poor, unfortunate souls.", ["objectivesText"] = "Defeat Helya in Maw of Souls .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139475, 141194 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7745 } }, ["questType"] = "dungeon", ["startItems"] = { 139475 } },
[43554] = { ["id"] = 43554, ["name"] = "Neltharion's Lair: Into Neltharion's Lair", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7546, ["mapID"] = 739, ["storyline"] = { 43554 }, ["description"] = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld. Delve underground and stop the Underking before he can unleash the might of his drogbar army.", ["objectivesText"] = "Defeat Dargrul in Neltharion's Lair .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139476, 141181 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7745 } }, ["questType"] = "dungeon", ["startItems"] = { 139476 } },
[43555] = { ["id"] = 43555, ["name"] = "The Arcway: Into the Arcway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7855, ["mapID"] = 680, ["storyline"] = { 43555 }, ["description"] = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground. Enter The Arcway and clear out any, and all enemies.", ["objectivesText"] = "Defeat Advisor Vandros in The Arcway .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139477, 141182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7855 } }, ["questType"] = "dungeon", ["startItems"] = { 139477 } },
[43556] = { ["id"] = 43556, ["name"] = "Vault of the Wardens: Into the Vault of the Wardens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7787, ["mapID"] = 739, ["storyline"] = { 43556 }, ["description"] = "It's worse than we thought within the Vault of the Wardens . The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there. Enter the Vault of the Wardens and cleanse the place of evil.", ["objectivesText"] = "Defeat Cordana Felsong in Vault of the Wardens .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139478, 141163 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["startItems"] = { 139478 } },
[43557] = { ["id"] = 43557, ["name"] = "Assault on Violet Hold: Into the Violet Hold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 43557 }, ["description"] = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", ["objectivesText"] = "Defeat the leader of the Assault on Violet Hold .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139479, 141184 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["startItems"] = { 139479 } },
[43558] = { ["id"] = 43558, ["name"] = "Bindings of the Windlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 43558 }, ["series"] = { 43560, 43796, 44093, 44094, 44095, 44096, 44097, 94932 }, ["description"] = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own. Return to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", ["objectivesText"] = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone . Progress: Yes, <race>?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 124444, 139466, 139468, 139536 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 39652 } },
[43560] = { ["id"] = 43560, ["name"] = "Audience with the Windlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 43560 }, ["series"] = { 43558, 43796, 44093, 44094, 44095, 44096, 44097, 94932 }, ["description"] = "I have kept my promise. Thunderaan the Windlord awaits. Know that if betrayal is in your heart, the Windlord will not be deceived. Be silent, and perhaps your audience shall be a fortunate one.", ["objectivesText"] = "Witness Thunderaan .", ["rewardItems"] = { 139536 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 110990, ["x"] = 0.41, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 43558, 94932 } },
[43561] = { ["id"] = 43561, ["name"] = "I Believe I Can Fly!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 43561 }, ["description"] = "Let's not bother explaining how this happened, just know that I have the plan of all plans to escape this... this... This place stinks! But you can help! These feathers here will help craft my escape plan. If you wouldn't mind, I'm sure there's enough for the both of us!", ["objectivesText"] = "Collect 6 Molted Feathers for Snicarus Dungleflight.", ["rewardItems"] = { 139500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard" },
[43562] = { ["id"] = 43562, ["name"] = "Giving It All We've Got", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43502, 43563 }, ["description"] = "The arcan'dor is drawing incredible amounts of energy. Even with the leyline feed at full capacity, we may not have the power. Let us first ensure that all potential leyline conduits connecting to Shal'Aran are active. Then I can attempt to amplify the output and hopefully satisfy this insufferable plant.", ["objectivesText"] = "Activate all of the leyline feeds in Suramar , then speak with Valtrois. Progress: We must activate all of the leyline feeds in Suramar before attempting the spell.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 140328, 141652, 141655, 141682 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43502 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43563] = { ["id"] = 43563, ["name"] = "Ephemeral Manastorm Projector", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43502, 43562 }, ["description"] = "Oculeth's theory is sound. Reckless, but sound. A small warp-field could trap and excite ambient mana in the conduit, thus creating a manastorm similar to when the arcan'dor fell out of balance. I can build a device to generate the warp-field, but I need materials. Specifically, warp-resistant alloys - such as the armor plating of high-end security constructs in the noble district. Those constructs are deadly. If anyone owes you a favor, now is the time to call it in.", ["objectivesText"] = "Collect 4 Warp-Resistant Plating from Chronarch Defenders. Progress: Without those plates, the E.M.P. would rip itself apart in seconds.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131811, 133755, 139689, 141253, 141605, 141683, 142401 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 43562 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43564] = { ["id"] = 43564, ["name"] = "Flow Control", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["description"] = "If all goes as planned, the manastorm will cause the leyline to flare up, sending a great surge of energy through the arcway. In order for the surge to reach Shal'Aran, we must seal off any outlets along the way. If we miss even one, the mission fails - and hundreds of people will be vaporized by the energy blow off. Thalyssra had better be sure about this tree.", ["objectivesText"] = "Seal off the Arcway Outlets in Lunastre Lane, The Parade Grounds, and the Midnight Court.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140255 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43562 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43565] = { ["id"] = 43565, ["name"] = "Bring Home the Beacon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["description"] = "The conduit we need is in the Arcway, and security in the Arcway has doubled since your last visit. Our only reasonable option is to teleport your strike team directly in. This is a long-range teleport to a non-anchored destination. In other words, it will be hard. Take this beacon and survey the commons in Suramar City, then return the beacon to me so I can analyze the results. This will help me teleport you as close as possible to the conduit!", ["objectivesText"] = "Use the Advanced Telemancy Beacon to survey Evermoon Commons, Evermoon Bazaar, and Siren's Vigil in Suramar City. Progress: Imagine firing an arrow at the sky in hopes of hitting an acorn at the far end of the forest. This teleport will be a little harder, but I think I can do it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131811, 140255, 140257, 141605 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3664, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43562 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43566] = { ["id"] = 43566, ["name"] = "Withered Progress", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[43567] = { ["id"] = 43567, ["name"] = "All In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43568 }, ["description"] = "It is time to put our plan into action. Oculeth will send you, Arluin and myself into the Arcway, where we shall trigger a manastorm in the Nightflow Conduit. Valtrois will stay here and prepare Shal'Aran for a massive jolt of arcane power - hopefully enough to satisfy the arcan'dor. $p... We have a saying... \"To lead is to stand alone.\" It means only those who bear the weight of leadership can truly appreciate it. Thank you for standing beside me. In truth, I do not feel alone.", ["objectivesText"] = "Complete the \"All In\" scenario. Chief Telemancer Oculeth can begin the scenario.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141684, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43563, 43564, 43565 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43568] = { ["id"] = 43568, ["name"] = "Arcan'dor, Gift of the Ancient Magi", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43567 }, ["description"] = "Thousands of years ago, as the Quel'dorei were just beginning to unravel the mysteries of the arcane, a small enclave of druids met with the first of the elven magi. In the pale moonlight, they formed an order that would seek to bring the arcane into balance - using nature itself as a vessel. Thus the arcan'dor were created. My masters who belonged to this order have long since faded away. Yet their legacy remains. Their gift will mend the spirit of the shal'dorei. Let them eat, and be made whole.", ["objectivesText"] = "Pick the Fruit of the Arcan'dor and share it with Chief Telemancer Oculeth , Arcanist Valtrois , and First Arcanist Thalyssra . Progress: The shal'dorei must eat the fruit of the arcan'dor . It is the only way to free them.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140315, 140445, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 112146, ["x"] = 0.365, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43567 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43569] = { ["id"] = 43569, ["name"] = "Arluin's Request", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["description"] = "I never thought I would need to read this... < Vanthir hefts a scroll in his hand.> Arluin made... plans... in the event he fell. It is not much, but I would like to honor his last request. < Vanthir hands you the scroll.> Go to the location marked on this map. Take this Arcan'dor Fruit and give it to a woman named Arluelle", ["objectivesText"] = "Locate Arluelle and give her a piece of the Arcan'dor Fruit. Progress: Where is Arluin?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140255 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110698, ["x"] = 0.482, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43567 }, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43571] = { ["id"] = 43571, ["name"] = "Neltharion's Lair: Braid of the Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Greetings, Deathlord. Years have passed since we first met, but for me it has been mere days. The unholy bond between Horseman and steed must not be taken lightly. Power begets power, Deathlord. Never forget this fact! I can forge an inseparable bond between rider and steed, but components of great power are required. The first item I require is the Braid of the Underking , a dark shamanic adornment passed down for generations. Currently, it is possessed by Dargrul the Underking.", ["objectivesText"] = "Retrieve the Braid of the Underking from Neltharion's Lair. Progress: Have you acquired the Braid of the Underking ?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139537, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["x"] = 0.362, ["y"] = 0.561, ["mapID"] = 647, ["npcID"] = 111480 } }, ["ends"] = { { ["x"] = 0.362, ["y"] = 0.561, ["mapID"] = 647, ["npcID"] = 111480 } }, ["coords"] = { ["mapID"] = 647, ["x"] = 0.362, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 111480, ["questTurnInID"] = 111480, ["questType"] = "dungeon", ["sourceQuests"] = { 42708 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
[43572] = { ["id"] = 43572, ["name"] = "Darkheart Thicket: The Nightmare Lash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "The dark steeds of the apocalypse are indomitable creatures of anguish and cruelty. They can never be tamed... only subjugated. The next component of power we require is one born of hatred, fashioned within the Emerald Nightmare. It is known as the Nightmare Lash . The Nightmare Lash has the power to suffocate all hope... all light... from within a living soul. The Shade of Xavius himself carries the lash. Defeat him and bring the lash to me! I will use it to dominate the steeds of the damned!", ["objectivesText"] = "Retrieve the Nightmare Lash from Darkheart Thicket. Progress: Do you have the Nightmare Lash ?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139538, 139673, 139676, 139680, 140517, 140923 }, ["starts"] = { { ["x"] = 0.362, ["y"] = 0.561, ["mapID"] = 647, ["npcID"] = 111480 } }, ["ends"] = { { ["x"] = 0.362, ["y"] = 0.561, ["mapID"] = 647, ["npcID"] = 111480 } }, ["coords"] = { ["mapID"] = 647, ["x"] = 0.362, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 111480, ["questTurnInID"] = 111480, ["questType"] = "dungeon", ["sourceQuests"] = { 43571 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
[43573] = { ["id"] = 43573, ["name"] = "Advancing the War Effort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "The quest for the Four Horsemen is of the utmost importance, however we must turn our attention to the warfront. Our continued success on the field of battle has shaken the Burning Legion and as a result, they have increased the frequency and intensity of their assaults. We must meet the increased aggression with continued resistance! Only then will we be able to turn our attention back to the Four Horsemen.", ["objectivesText"] = "Complete 10 World Quests. Progress: How goes the war effort?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 42824 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43574] = { ["id"] = 43574, ["name"] = "Maw of Souls: Maul of the Dead", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "All of the necessary components have been gathered together. Soon, the unholy steeds of the damned will trample the armies of the Burning Legion. However, our work is not quite done. One item yet remains beyond our grasp... Lurking within the depths of Helheim, the fallen queen Helya rules over the dead. In her possession is a maul, infused with the souls of countless fallen warriors. Bring to me the Maul of the Dead and with it, I will forge barding so impenetrable... no demon shall break it!", ["objectivesText"] = "Retrieve the Maul of the Dead from Helheim. Progress: Have you brought me the Maul of the Dead ?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140162, 140517, 140923 }, ["starts"] = { { ["x"] = 0.362, ["y"] = 0.561, ["mapID"] = 647, ["npcID"] = 111480 } }, ["ends"] = { { ["x"] = 0.362, ["y"] = 0.561, ["mapID"] = 647, ["npcID"] = 111480 } }, ["coords"] = { ["mapID"] = 647, ["x"] = 0.362, ["y"] = 0.561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 111480, ["questTurnInID"] = 111480, ["questType"] = "dungeon", ["sourceQuests"] = { 43572, 43573 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
[43576] = { ["id"] = 43576, ["name"] = "Regroup at the Refuge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "I cannot think clearly in this place. Even though the moonwell is still pure, the corrupting influence of the Nightmare remains. Come, we will return to the refuge and gather our wits. Then we will continue the hunt for my husband.", ["objectivesText"] = "Return to Starsong Refuge.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104885, ["x"] = 0.668, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 41708, 41890 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[43577] = { ["id"] = 43577, ["name"] = "Capturing the Gateway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "The time has come to make our move against the Legion. The Legion has multiple portals across the Broken Isles. Should your armies succeed in securing one while it's still active, Hymdall can use the runestones you gathered to direct it to whatever hellish world Hodir is trapped in.", ["objectivesText"] = "Complete the missions: Investigate Felsoul Hold, Preparing Our Arrival and Capturing the Gateway.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 43506 }, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[43581] = { ["id"] = 43581, ["name"] = "The Wisdom of Patience", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The horrors you braved in the thicket are only the beginning. Within the Emerald Nightmare you will face the very heart of the corruption that threatens the stability of all life on Azeroth. But not just yet. We have not yet managed to permeate the magic protecting Xavius' sinister realm. Once we have, however, you should return here; there is still much to be done.", ["objectivesText"] = "Await the opening of the Emerald Nightmare, then report back to Senegos in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43519 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[43582] = { ["id"] = 43582, ["name"] = "Shalassic Park", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 41231 }, ["description"] = "We have a Devilsaur. I think she sees you as the pack leader now. She should obey your commands. She looks hungry. Why don't you let her off the leash a little bit?", ["objectivesText"] = "Ride Su'esh and defeat 50 adversaries.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140026, 140034, 141679 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110987, ["x"] = 0.506, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41231 }, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43583] = { ["id"] = 43583, ["name"] = "Life Finds a Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43583 }, ["objectivesText"] = "Release Su'esh Escape the Menagerie Court of Stars assaulted", ["rewardGold"] = 283700, ["rewardXP"] = 6140, ["rewardItems"] = { 140026 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Release Su'esh", ["amount"] = 1, ["type"] = 0, ["objectID"] = 111062, ["orderIndex"] = 0 }, { ["text"] = "Escape the Menagerie", ["amount"] = 1, ["type"] = 0, ["objectID"] = 113701, ["orderIndex"] = 1 }, { ["text"] = "Court of Stars assaulted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[43585] = { ["id"] = 43585, ["name"] = "Preparing For War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "We would do well to bolster our own forces before calling upon our allies to join us in the final conflict against the Legion. There still remains much to do in the Broken Isles and victories there will give us the momentum we need to crush the enemy.", ["objectivesText"] = "Complete \"Aiding the Valkyra,\" \"Lost at Sea\" and \"Enslaved by Sea Giants\" missions. Progress: Any news, <name>?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.847, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.847, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.847 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 42204 }, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[43586] = { ["id"] = 43586, ["name"] = "Maw of Souls: Message to Helya", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42616, 42618, 43090, 43586, 43604 }, ["description"] = "We cannot fight on two fronts and succeed. If we're to give ourselves the room we need to fight off the Legion we need to deliver a decisive victory against Helya. Not her armies, not her lieutenants, but the mother of the underworld herself. Go to the Maw of Souls and defeat Helya, <name>.", ["objectivesText"] = "Defeat Helya inside the Maw of Souls dungeon. Progress: Is it done?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "dungeon", ["sourceQuests"] = { 42204 }, ["questLines"] = { { ["id"] = 5806, ["name"] = "Chronicles of Skyhold II", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5806, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[43587] = { ["id"] = 43587, ["name"] = "Leyline Feed: Elor'shan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43587 }, ["description"] = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", ["objectivesText"] = "Infuse the leyline feed with Ancient Mana . Progress: <The leyline feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652 }, ["starts"] = { { ["x"] = 0.659, ["y"] = 0.42, ["mapID"] = 680, ["objectID"] = 252258 } }, ["ends"] = { { ["x"] = 0.659, ["y"] = 0.42, ["mapID"] = 680, ["objectID"] = 252258 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.659, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41138 } },
[43588] = { ["id"] = 43588, ["name"] = "Leyline Feed: Kel'balor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43588 }, ["description"] = "<This feed appears to draw power from the leyline in order to become fully operational. You should be able to imbue it with mana, but it will take a few minutes to draw enough leyline energy to accept the infusion. Beware, for creatures may notice the surge of arcane energy...>", ["objectivesText"] = "Defend the Leyline Feed and infuse it with Ancient Mana . Progress: <The leyline feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652 }, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.429, ["mapID"] = 680, ["objectID"] = 252259 } }, ["ends"] = { { ["x"] = 0.593, ["y"] = 0.429, ["mapID"] = 680, ["objectID"] = 252259 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.593, ["y"] = 0.429 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41138 } },
