[43590] = { ["id"] = 43590, ["name"] = "Leyline Feed: Ley Station Moonfall", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43590 }, ["description"] = "<This leyline feed appears to be damaged. The large collector at the top is broken. The broken piece must be around here somewhere. There are rough scuff marks on the floor that appear to be made by something larger than the creatures inside. Much, much larger.>", ["objectivesText"] = "Find the Broken Leydar Dish and repair the leyline feed . Progress: <The feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 140847, 141652 }, ["starts"] = { { ["x"] = 0.357, ["y"] = 0.242, ["mapID"] = 680, ["objectID"] = 252260 } }, ["ends"] = { { ["x"] = 0.357, ["y"] = 0.242, ["mapID"] = 680, ["objectID"] = 252260 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.357, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 41138 }, ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } } },
[43591] = { ["id"] = 43591, ["name"] = "Leyline Feed: Ley Station Aethenar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43591 }, ["description"] = "<This leyline appears to be damaged and needs repair. Several large chunks of the main column are missing and arcane energy is crackling in the gaps. The elementals nearby seem to pick up debris and absorb it into their bodies as they move around. Maybe they have the missing pieces...>", ["objectivesText"] = "Collect 6 Leyline Feed Fragments and infuse the feed with ancient mana . Progress: <The leyline feed crackles as wild energy escapes the gaps in the column.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652 }, ["starts"] = { { ["x"] = 0.242, ["y"] = 0.193, ["mapID"] = 680, ["objectID"] = 252261 } }, ["ends"] = { { ["x"] = 0.242, ["y"] = 0.193, ["mapID"] = 680, ["objectID"] = 252261 } }, ["coords"] = { ["mapID"] = 680, ["x"] = 0.242, ["y"] = 0.193 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41138 } },
