[43643] = { ["id"] = 43643, ["name"] = "Secrets of the Axes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["storyline"] = { 43643 }, ["description"] = "Battlelord, I have a request. Find me inspiration! An axe whose form has seen a truly astounding amount of battle, wielded by one of the world's most powerful warriors. Both weapon and owner forged together in the crucible of war. Find this hero and their weapon, and convince them to come here.", ["objectivesText"] = "Search the Broken Isles for the greatest axe wielding warrior you know. Progress: You've found them?", ["rewardItems"] = { 139578, 140133, 140161 }, ["starts"] = { { ["x"] = 0.41, ["y"] = 0.371, ["mapID"] = 695, ["npcID"] = 96586 } }, ["ends"] = { { ["x"] = 0.41, ["y"] = 0.371, ["mapID"] = 695, ["npcID"] = 96586 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.41, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96586, ["questTurnInID"] = 96586, ["questType"] = "standard" },
[43644] = { ["id"] = 43644, ["name"] = "To the Deeps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 205, ["storyline"] = { 40341, 43644, 43645 }, ["description"] = "I assure you the legends are true: Sharas'dal, the Scepter of Tides, was forged around living waters of the Well of Eternity. It gave Azshara dominion over life itself. I have sent shaman throughout the world looking for it, but the only one to ever find it has gone missing. Wavespeaker Adelee said she had tracked the scepter to the Ruins of Vashj'ir, but we haven't heard from her since. <name>! Come with me to the ocean depths. Let's track down our missing shaman and get that artifact!", ["objectivesText"] = "Travel to the Ruins of Vashj'ir with Erunak. Progress: I can transport us to the depths. Step into the bubble here... It's mostly safe.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 54465, 63542, 63543, 63544, 63545, 63546, 63547, 63548, 63549, 128819, 128911, 128935, 131432, 131433, 169354, 218343, 225245, 226146, 227792 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["sourceQuests"] = { 41335, 43945, 44006 }, ["questLines"] = { { ["id"] = 267, ["name"] = "Azshara's Power", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 267, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 205 },
[43645] = { ["id"] = 43645, ["name"] = "Wavespeaker's Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 40341, 43644, 43645 }, ["series"] = { 40341 }, ["description"] = "The shaman we seek is Wavespeaker Adelee. Her research brought her down to these ancient ruins, where she reported naga armies amassing prior to the Legion invasion. The last I had heard, she had located Sharas'dal, the Scepter of Tides - and then she went silent. <name>, Search for clues to her whereabouts among the lower level of the ruins. Beware the naga patrols!", ["objectivesText"] = "Locate three clues to the whereabouts of Wavespeaker Adelee within the Ruins of Vashj'ir. Progress: How goes the search?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 54465, 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard", ["sourceQuests"] = { 43644 }, ["questLines"] = { { ["id"] = 267, ["name"] = "Azshara's Power", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 267, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 205 },
[43686] = { ["id"] = 43686, ["name"] = "The Fourth Horseman", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 43686, 44248 }, ["description"] = "The Lich King demands too much! Tirion Fordring deserves more than a life of anguish and undeath! Know this, Deathlord... I will obey your will, but there will be no redemption for what we are about to do. The Silver Hand will never hand Tirion to us. The path to the Fourth Horseman will be soaked in righteous blood! Blood that will stain our hands forever. Your will be done, Deathlord. I will begin the preparations to invade Light's Hope. If this is what it takes to save our world, so be it!", ["objectivesText"] = "Obtain the Fourth Horseman .", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 97919, 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 142057, 142059, 142060, 142061, 142063 }, ["rewardChoices"] = { 142057, 142059, 142060, 142061, 142063 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.516, ["y"] = 0.5, ["mapID"] = 648, ["npcID"] = 93437 } }, ["ends"] = { { ["x"] = 0.516, ["y"] = 0.5, ["mapID"] = 648, ["npcID"] = 93437 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.516, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93437, ["questTurnInID"] = 93437, ["questType"] = "standard", ["sourceQuests"] = { 43574, 44282, 44286, 44690, 91615 }, ["questLines"] = { { ["id"] = 5895, ["name"] = "The Four Horsemen III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5895, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43687] = { ["id"] = 43687, ["name"] = "Walking in Shadows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 43687 }, ["description"] = "If we are to infuse the shard's power into the Ashbringer we will need help. We cannot wield such dark magic; however, I know who can... The Knights of the Ebon Blade. I will commission a flight for you to Acherus at once and meet you there - find Aludane Whitecloud in Dalaran when you are ready.", ["objectivesText"] = "Seek the aid of the Knights of the Ebon Blade in Acherus above the Broken Isles. Progress: Darion owes us this much after all his kind have done.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 18229, 18365, 22691, 139566, 139624 }, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.722, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.498, ["y"] = 0.722, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.498, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 43688 } },
[43697] = { ["id"] = 43697, ["name"] = "Warriors of Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["series"] = { 43700 }, ["description"] = "We have gathered to celebrate our victory over the Burning Legion this day. Highlord, please join us.", ["objectivesText"] = "Listen as you are honored by the Order of the Silver Hand. Progress: We rejoice in our triumph!", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139690, 142055, 142056, 142059, 142061, 142062 }, ["rewardChoices"] = { 142055, 142056, 142059, 142061, 142062 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 5000 } }, ["starts"] = { { ["x"] = 0.726, ["y"] = 0.258, ["mapID"] = 24, ["npcID"] = 90259 } }, ["ends"] = { { ["x"] = 0.726, ["y"] = 0.258, ["mapID"] = 24, ["npcID"] = 90259 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.726, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90259, ["questTurnInID"] = 90259, ["questType"] = "standard", ["sourceQuests"] = { 43700 }, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24 },
[43698] = { ["id"] = 43698, ["name"] = "Lumenstone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "To prepare for the battle ahead, we will need armor and weapons. We have learned of lumenstone , a rare metal that can negate magic... even fel magic. It is found in small quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting. We should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", ["objectivesText"] = "Collect 50 Lumenstone by sending champions on \" Lumenstone \" missions. Progress: Have you acquired any lumenstone ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139634 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43492, 43933 }, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24 },
[43699] = { ["id"] = 43699, ["name"] = "Defenders of the World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "Requests are pouring in from across the Broken Isles for our aid, Highlord. I know that we are working to aid the priests at Netherlight Temple, but there are many others who need our help. We cannot turn our backs on those who need our aid.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43492, 43933 }, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24 },
[43700] = { ["id"] = 43700, ["name"] = "A Light in the Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["series"] = { 43697 }, ["description"] = "Highlord, thank goodness you've arrived! The invasion of Netherlight Temple has begun. Our forces are already waiting on the other side of the portal. Join them, and we will close the trap around Lord Balnazzar .", ["objectivesText"] = "Go to Netherlight Temple using the priest's portal in Dalaran, then defend Netherlight Temple and slay Lord Balnazzar . Progress: The priests have always been our allies and friends. Now, we stand united against a common cause.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 257143, 265106, 265631 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 43534, 43698, 43699, 91619 }, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24 },
