[43702] = { ["id"] = 43702, ["name"] = "Softening the Target", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "The Archdruid's end draws near. His memory will live on in the hearts of all who knew him. Elothir's desperate efforts revealed that Malfurion is being held in Shala'nir, amidst the roots of Shaladrassil. My love. So near, yet so far.... Shala'nir is infested with Nightmare creatures. To rush in would be suicide. I subdued one of Xavius' creatures. Use it against him, <name> and clear us a path.", ["objectivesText"] = "Slay 50 Nightmare Creatures in Shala'nir riding the Subdued Nightwing . Progress: Have you managed to thin their numbers?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.427333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38684, 41749, 41893 }, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
