[43892] = { ["id"] = 43892, ["name"] = "Sealing Fate: Order Resources", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43892 }, ["objectivesText"] = "Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end? Will you ever stop risking others lives just to satisfy your greedy nature? You can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["rewardCurrencies"] = { { ["id"] = 1273, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.675, ["mapID"] = 627, ["npcID"] = 111243 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.675, ["mapID"] = 627, ["npcID"] = 111243 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.572, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 111243, ["questTurnInID"] = 111243, ["questType"] = "standard" },
[43893] = { ["id"] = 43893, ["name"] = "Sealing Fate: Stashed Order Resources", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43893 }, ["objectivesText"] = "Progress: Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you? I leave the choice up to you. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["rewardCurrencies"] = { { ["id"] = 1273, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.675, ["mapID"] = 627, ["npcID"] = 111243 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.675, ["mapID"] = 627, ["npcID"] = 111243 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.572, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 111243, ["questTurnInID"] = 111243, ["questType"] = "standard" },
[43894] = { ["id"] = 43894, ["name"] = "Sealing Fate: Extraneous Order Resources", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43894 }, ["objectivesText"] = "Progress: Four times the cost of the first for only one seal. Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["rewardCurrencies"] = { { ["id"] = 1273, ["amount"] = 1 } }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.675, ["mapID"] = 627, ["npcID"] = 111243 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.675, ["mapID"] = 627, ["npcID"] = 111243 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.572, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 111243, ["questTurnInID"] = 111243, ["questType"] = "standard" },
