[43898] = { ["id"] = 43898, ["name"] = "Preparing to Move", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself. Before we move on the hold, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills, and I would wager that they have unfinished business with their former brothers and sisters.", ["objectivesText"] = "Meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 111814, ["x"] = 0.625, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 634, 680 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 40615 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 29, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43899] = { ["id"] = 43899, ["name"] = "Steeds of the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen. Salanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items. Use the mission table to assign your chosen champions to the task.", ["objectivesText"] = "Complete 5 \"Fallen Steeds\" missions. Progress: Have you completed the necessary missions for Salanar the Horseman?", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 42708 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[43902] = { ["id"] = 43902, ["name"] = "The Emerald Nightmare: Fall of Cenarius", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8026, ["mapID"] = 739, ["storyline"] = { 43902 }, ["description"] = "While we know that the Nightmare bends the boundary between reality and dream, there is no doubt of the threat upon us. Our own allies have fallen into darkness.", ["objectivesText"] = "Defeat Cenarius in the Emerald Nightmare . Progress: How are you finding the challenges of the Emerald Nightmare ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139484, 140163 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 8026 } }, ["questType"] = "raid", ["startItems"] = { 140163 } },
