[43934] = { ["id"] = 43934, ["name"] = "A New Path", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "Highlord <name>, if I could have a moment of your time? Long have I followed the path of the Light, and for many years I studied under the Priestesses of the Moon. Yet, I have always felt my education incomplete, and a yearning to know more. When I walked into these halls, I finally felt a spark of what was missing. I believe that a new path lies before me. I wish to become a paladin of the Silver Hand. Will you allow me to join you?", ["objectivesText"] = "Speak to Delas Moonfang . Progress: What do you think?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 181743 }, ["starts"] = { { ["x"] = 0.485, ["y"] = 0.713, ["mapID"] = 24, ["npcID"] = 110866 } }, ["ends"] = { { ["x"] = 0.485, ["y"] = 0.713, ["mapID"] = 24, ["npcID"] = 110866 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.485, ["y"] = 0.713 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 110866, ["questTurnInID"] = 110866, ["questType"] = "standard", ["sourceQuests"] = { 43541 }, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24 },
[43935] = { ["id"] = 43935, ["name"] = "A Second Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43935, 44407 }, ["description"] = "Perhaps it's time to consider improving your flexibility when it comes to powerful artifacts. There are still others that I think are worth pursuing if you are interested. Let me show you what your options are and you can choose one.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.482, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.511, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 40706 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5833, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5833, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[43937] = { ["id"] = 43937, ["name"] = "Seeking Refuge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell. I believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar. If you can convince the Nightfallen to aid us, they may be able to offer the Moon Guard and us both refuge right under the Legion's nose.", ["objectivesText"] = "Complete the \"Nightfall\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[43938] = { ["id"] = 43938, ["name"] = "Focusing Our Efforts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell. I believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar. Afterward, seek out the Moon Guard in the northern reaches of Suramar. They, too, could be valuable allies in our cause... if they still oppose the Legion as they once did many years ago.", ["objectivesText"] = "Complete the \"Nightfall\" and \"Moon Guard Stronghold\" storylines in Suramar, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 43522 }, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
