[43945] = { ["id"] = 43945, ["name"] = "Expanding Your Horizons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 43945, 44006 }, ["series"] = { 44406 }, ["description"] = "You are a fast study, <class>t <name>. The elements speak through you - it is rare to have such a connection to the world. A true shaman must walk many paths. For every role, one must have the right tools at hand. Only the most powerful weapons can lead us to victory against the Legion. Perhaps it is time to seek out another? Speak with me and let us discuss your options.", ["objectivesText"] = "Speak with Aggra to choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.361, ["y"] = 0.8, ["mapID"] = 726, ["npcID"] = 99531 } }, ["ends"] = { { ["x"] = 0.361, ["y"] = 0.8, ["mapID"] = 726, ["npcID"] = 99531 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.361, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 99531, ["questTurnInID"] = 99531, ["questType"] = "standard", ["sourceQuests"] = { 41335 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5834, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5834, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
