[43969] = { ["id"] = 43969, ["name"] = "Hired Help", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "I was fond of Margaux. News of her death weighs heavily on many of us. < Vanthir shakes his head sadly.> If we are to carry on, we need to send a strong message. We need those like Durant to know that we are watching, and we will hold them accountable. I know someone who could help us. His name is Arluin . To call him a reluctant ally would be generously overstating it. He is cautious, and will not risk himself without compensation. You can find him in the alleys north of the Evermoon Bazaar.", ["objectivesText"] = "Locate Arluin and persuade him to help you. Progress: Best not to lurk if you aren't doing business.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42839 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
