[43980] = { ["id"] = 43980, ["name"] = "Another Weapon of Old", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 43980, 44431, 44443 }, ["description"] = "You have done well but our foes are powerful and cunning. It would be wise to be prepared for whatever they may unleash upon us. You would be wise to consider obtaining another of the weapons of old to aid in our conflict. Let me know how you'd like to proceed.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.447, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 40653 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5838, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5838, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
