[43991] = { ["id"] = 43991, ["name"] = "The Protectors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "To fully unlock the powers of the Idol, we will need four manifestations of the wilds - an essence of ferocity, essence of regrowth, essence of balance, and essence of tenacity. To find these essences, we must consult the protectors of the forest. Go to the Emerald Dreamway and call upon the powers of the ancient druidic stones. The protectors will only show themselves to those who can prove their connection to the wilds.", ["objectivesText"] = "Use your druidic powers to commune with protectors at the Feral Stone, the Guardian Stone, the Restoration Stone, and the Balance Stone.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.5, ["mapID"] = 747, ["npcID"] = 103832 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.446, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 103832, ["questTurnInID"] = 103832, ["questType"] = "standard", ["sourceQuests"] = { 42036 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
