[44004] = { ["id"] = 44004, ["name"] = "Bringer of the Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44153 }, ["description"] = "Turalyon lives! For ages I had thought that my old friend had perished on some desolate Legion world. But to know that he yet lives and is in danger is too much to bear. We must hurry, <name>. We must uncover the object's sacred purpose. The prophet of whom Turalyon spoke of is undoubtedly the leader of the draenei, Velen. Take the object and journey to the Exodar. It is there that you will find Prophet Velen. I will open a portal for you now. Take my beacon and use it when you are ready to return.", ["objectivesText"] = "Discover the purpose of the Mysterious Lightbound Object. Progress: Have you discovered anything about the object?", ["rewardGold"] = 808800, ["rewardXP"] = 1415, ["rewardItems"] = { 140319, 140533, 140574, 140610, 140611, 140612, 140613, 140614, 140615, 140616, 140617, 140763, 251480 }, ["rewardChoices"] = { 140610, 140611, 140612, 140613, 140614, 140615, 140616, 140617 }, ["starts"] = { { ["x"] = 0.275, ["y"] = 0.358, ["mapID"] = 629, ["npcID"] = 112130 } }, ["ends"] = { { ["x"] = 0.275, ["y"] = 0.358, ["mapID"] = 629, ["npcID"] = 112130 } }, ["coords"] = { ["mapID"] = 629, ["x"] = 0.275, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 112130, ["questTurnInID"] = 112130, ["questType"] = "dungeon", ["sourceQuests"] = { 44009, 44257 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"