[44006] = { ["id"] = 44006, ["name"] = "Your Fullest Potential", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 43945, 44006 }, ["description"] = "I see that you walk many paths, as a true shaman should. Two mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle. Speak with me, and together we will unlock your fullest potential.", ["objectivesText"] = "Speak with Aggra to choose a third artifact to pursue. Progress: Where are the spirits guiding you, Farseer?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.361, ["y"] = 0.8, ["mapID"] = 726, ["npcID"] = 99531 } }, ["ends"] = { { ["x"] = 0.361, ["y"] = 0.8, ["mapID"] = 726, ["npcID"] = 99531 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.361, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 99531, ["questTurnInID"] = 99531, ["questType"] = "standard", ["sourceQuests"] = { 43945 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5834, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5834, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[44009] = { ["id"] = 44009, ["name"] = "A Falling Star", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "<class>t <name>, thank you for coming. I have a matter of some urgency that requires your unique talents. The Order of the Silver Hand have reported that an extraordinarily luminescent object has emerged from the Felstorm and is currently falling towards the coast of Suramar. What I find most curious about this occurrence is that the object was reported as having \"cut a swath\" through the Felstorm itself. Will you investigate? There is a gryphon awaiting your arrival at Krasus' Landing.", ["objectivesText"] = "Find the Mysterious Lightbound Object . Progress: Show me what you've found.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 140192, 140319, 140533, 140574, 140763 }, ["starts"] = { { ["x"] = 0.289, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.289, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.289, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
