[44034] = { ["id"] = 44034, ["name"] = "Another Worthy Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 44034, 44375 }, ["description"] = "We still have plans prepared to obtain other weapons of incredible power - tools that you may find useful to have on hand as you continue your work. I would be happy to go over the remaining options with you so that you may make an informed decision.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.413, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 40997 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5832, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5832, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
