[44040] = { ["id"] = 44040, ["name"] = "Vote of Confidence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "I will endeavor to protect my son until the votes are cast. Coryn Stelleris is a predator even among the nobility. It does not surprise me that he should stoop to such depths to ensure his own success. Tell Ly'leth that she has my support. Unequivocally. You may also choose to tell her that Coryn Stelleris will hurt her, if she gives him a chance. Be careful.", ["objectivesText"] = "Return to Ly'leth at the Waning Crescent.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43312 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44041] = { ["id"] = 44041, ["name"] = "The Bloody Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43829, 43958 }, ["description"] = "We need to find out who is behind the assassination of Amber Kearnen. It won't be long before SI:7 realizes that their agent is MIA and comes sniffing around The Hall of Shadows. Here, take these stylish spy glasses and set them to scan for traces of hemoglobin. I've taken the liberty of calibrating them specifically for Amber Kearnen's blood. Follow the blood trail back to the culprits, but make sure to stay out of sight! Report back to us when you've got the information we need.", ["objectivesText"] = "Discover the truth behind the hit on the SI:7 agent. Progress: Were you able to find out who's behind the assassination attempt?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140395, 140517, 140931 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.413, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questTurnInID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 43829 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[44043] = { ["id"] = 44043, ["name"] = "Continuing the Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["description"] = "There are still two paths you may walk - two powerful weapons you might yet obtain to aid you in the fight against the Legion. I will help you recall your remaining options, of course.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 40618 }, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5831, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5831, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
