[44051] = { ["id"] = 44051, ["name"] = "Wasted Potential", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44051 }, ["description"] = "You have done well for us here, but it is time for you to return to Thalyssra. There is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way. Oh, and before you go: <Vanthir hands you a wrapped bottle of Arcwine.> Take this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child. We are grateful beyond measure. Farewell for now.", ["objectivesText"] = "Activate the teleporter pad and bring Vanthir's gift to Thalyssra.", ["starts"] = { { ["x"] = 0.479, ["y"] = 0.815, ["mapID"] = 680, ["npcID"] = 111900 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111900, ["x"] = 0.442, ["y"] = 0.703333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.703333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questGiverID"] = 111900, ["questType"] = "standard", ["sourceQuests"] = { 42486 } },
[44052] = { ["id"] = 44052, ["name"] = "And They Will Tremble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "There will be consequences for what has transpired this day. For now, you should return to Thalyssra. Tell her that we have avenged Margaux and that the Dusk Lily has announced itself to all of Suramar . There will be many more deaths before this is over, rest assured, but this is a death that will teach others like Durant to tread more carefully in the future.", ["objectivesText"] = "Return to Thalyssra", ["rewardGold"] = 8955, ["rewardXP"] = 770, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 246937, 247914, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42792 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44053] = { ["id"] = 44053, ["name"] = "Friends With Benefits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "The Lunastre Attendant , silent as ever, offers you a wax-sealed scroll. It reads: \"Dearest <name>, I asked my attendant to catch you, should things go in my favor. The role of Advisor will keep me away from the estate for some time and I settled on a gift for Thalyssra. I have sent a detachment of attendants to Shal'Aran with some comfort items. Treat them well- they need someone to wait on and I could think of none better! Give the others my thanks, and my love, Advisor Ly'leth Lunastre\"", ["objectivesText"] = "Return to Thalyssra.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111903, ["x"] = 0.383429, ["y"] = 0.519714 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.383429, ["y"] = 0.519714 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43318 }, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44054] = { ["id"] = 44054, ["name"] = "Demonicide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44054 }, ["objectivesText"] = "Purge demons. 8", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Purge demons.", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "8", ["amount"] = 100, ["type"] = 0, ["objectID"] = 112449, ["orderIndex"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[44055] = { ["id"] = 44055, ["name"] = "They Have A Pitlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 44055 }, ["description"] = "The Feltotem are not the first to embrace the temptations of the Burning Legion. And they will not be the last. But in their arrogance, they have conjured a pit lord. Will you join us in battle against this beast? The power of your artifact and skill could prove invaluable against such a creature.", ["objectivesText"] = "Defeat Kuglaroth .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140721, 140722, 140723, 140724, 140725, 140726, 140727, 140728 }, ["rewardChoices"] = { 140721, 140722, 140723, 140724, 140725, 140726, 140727, 140728 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 108504, ["x"] = 0.298, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 108504, ["x"] = 0.298, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[44057] = { ["id"] = 44057, ["name"] = "A \"Noble\" Event", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 739, ["storyline"] = { 44057 }, ["series"] = { 44058 }, ["description"] = "The invitation appears to be for an exclusive fox hunt. They plan to hunt Volpin, a rare, elusive fox somewhere in the Broken Isles. Perhaps we can take advantage of this? We need to gather more information about this hunt, but we should do so without alerting the Nightborne to your plans. Your champions can act in your stead and further investigate where the hunt will be.", ["objectivesText"] = "Send champions on missions to investigate the hunt. Progress: Have your champions discovered anything about the fox hunt?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121751, 124124, 137564, 137573, 140226, 140495, 140496, 140561, 140562, 140563, 141639, 147416, 147418, 249714 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 140495 } },
[44058] = { ["id"] = 44058, ["name"] = "Volpin the Elusive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 739, ["storyline"] = { 44058 }, ["series"] = { 44057 }, ["description"] = "According to the map, the fox hunt will start at the Feathermane Hunting Grounds in Suramar . If the Nightborne succeed, they will kill Volpin, a fox that is the last of his kind in the Broken Isles. Travel to the Hunting Grounds, and interrupt the hunt.", ["objectivesText"] = "Interrupt the fox hunt.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137564, 137573, 140495, 140496, 140561, 140562, 140563 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7834 } }, ["questTurnInID"] = 103023, ["questType"] = "standard", ["sourceQuests"] = { 44057 } },
