[44074] = { ["id"] = 44074, ["name"] = "Neltharion's Lair: Essence of Tenacity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Greetings, Archdruid. I hear that you seek the essence of tenacity . There is none more unyielding and unbreakable than a creature of stone. In Neltharion's Lair is a monster known as Rokmora. Slay him, and draw from him the essence that you need.", ["objectivesText"] = "Collect 1 Essence of Tenacity from Rokmora in Neltharion's Lair, then slay Dar'grul the Underking. Progress: Stand firm, <class>.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 140311 }, ["starts"] = { { ["x"] = 0.347, ["y"] = 0.625, ["mapID"] = 715, ["npcID"] = 112546 } }, ["ends"] = { { ["x"] = 0.347, ["y"] = 0.625, ["mapID"] = 715, ["npcID"] = 112546 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.347, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 112546, ["questTurnInID"] = 112546, ["questType"] = "dungeon", ["sourceQuests"] = { 43991 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 2, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44075] = { ["id"] = 44075, ["name"] = "Halls of Valor: Essence of Ferocity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "To find the essence of ferocity , you must seek a creature who has slain thousands, and is revered by even the gods. I speak of none other than the wolf, Fenryr, whom you can find hunting in the eternal forests of the Halls of Valor.", ["objectivesText"] = "Collect 1 Essence of Ferocity from Fenryr in the Halls of Valor, then prove your worth to Odyn . Progress: It takes a ferocious beast to take down another ferocious beast.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 139469 }, ["starts"] = { { ["x"] = 0.311, ["y"] = 0.365, ["mapID"] = 715, ["npcID"] = 112544 } }, ["ends"] = { { ["x"] = 0.311, ["y"] = 0.365, ["mapID"] = 715, ["npcID"] = 112544 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.311, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 112544, ["questTurnInID"] = 112544, ["questType"] = "dungeon", ["sourceQuests"] = { 43991 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 3, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44076] = { ["id"] = 44076, ["name"] = "Darkheart Thicket: Essence of Regrowth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "My child, I can think of only one place to capture the essence of regrowth . Deep within Darkheart Thicket is Oakheart, a loyal ancient defender of the grove. He has recently fallen to the Nightmare's corruption, but deep within his heart, he still fights. Gather the essence of this great tree, so that his everliving soul may be used to fuel new life.", ["objectivesText"] = "Collect 1 Essence of Regrowth from Oakheart in Darkheart Thicket, then defeat the Shade of Xavius . Progress: My heart aches for those fallen to the Nightmare.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 140313 }, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.59, ["mapID"] = 715, ["npcID"] = 112549 } }, ["ends"] = { { ["x"] = 0.409, ["y"] = 0.59, ["mapID"] = 715, ["npcID"] = 112549 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.409, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 112549, ["questTurnInID"] = 112549, ["questType"] = "dungeon", ["sourceQuests"] = { 43991 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 4, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44077] = { ["id"] = 44077, ["name"] = "Eye of Azshara: Essence of Balance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Within the Eye of Azshara in Azsuna, a powerful being known as the Wrath of Azshara grows in strength. It is a blasphemy of nature - an infusion of stolen arcane power, and cannot be allowed to exist. Slay it. In its aftermath, you may find the essence of balance that you seek.", ["objectivesText"] = "Collect 1 Essence of Balance from the Wrath of Azshara. Progress: We follow Elune's path.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 140312 }, ["starts"] = { { ["x"] = 0.307, ["y"] = 0.508, ["mapID"] = 715, ["npcID"] = 112548 } }, ["ends"] = { { ["x"] = 0.307, ["y"] = 0.508, ["mapID"] = 715, ["npcID"] = 112548 } }, ["coords"] = { ["mapID"] = 715, ["x"] = 0.307, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questGiverID"] = 112548, ["questTurnInID"] = 112548, ["questType"] = "dungeon", ["sourceQuests"] = { 43991 }, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 5, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
