[44082] = { ["id"] = 44082, ["name"] = "Knights of the Ebon Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Korgaz Deadaxe has arrived at Acherus to aid us in recruiting additional death knights. He has an eye for potential. I cannot emphasize enough that it is of the utmost importance that we replenish our numbers during the battle with the Burning Legion. The demon armies are nearly endless and we are few. Speak with Korgaz when you are ready to recruit additional death knights.", ["objectivesText"] = "Speak to Korgaz Deadaxe .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["ends"] = { { ["x"] = 0.497, ["y"] = 0.513, ["mapID"] = 648, ["npcID"] = 93568 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.497, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93568, ["questTurnInID"] = 93568, ["questType"] = "standard", ["sourceQuests"] = { 42708 }, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
[44083] = { ["id"] = 44083, ["name"] = "The Grimoire of the First Necrolyte", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["description"] = "This ancient tome appears to be the spellbook of Sataiel, the first necrolyte. Within its pages of curses and cantrips, you discover instructions for a ritual that Sataiel was concocting to empower Ulthalesh, the Deadwind Harvester. She calls this ritual, \"The Rite of the Executioner.\" The site was chosen and prepared, but Sataiel met her unfortunate end before she could proceed. Perhaps you can pick up where she left off? First, you'll need some skulls.", ["ends"] = { { ["npcID"] = 254007, ["x"] = 0.386, ["y"] = 0.74, ["mapID"] = 42 } }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard" },
[44084] = { ["id"] = 44084, ["name"] = "Vengeance for Margaux", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "< Sylverin sputters, pale-faced with rage.> How could they? Margaux did everything they asked of her and more! The arcwine never stopped flowing despite everything they did to us! To her! Such injustice cannot stand. We must take vengeance for Margaux.", ["objectivesText"] = "Slay 8 Vineyard Enforcers or Wardens.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141678 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42838 }, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44087] = { ["id"] = 44087, ["name"] = "Return to the Fel Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44161 }, ["description"] = "<name>, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with. He requests your presence back on the Fel Hammer as soon as possible.", ["objectivesText"] = "Speak with Battlelord Gaardoun on the Fel Hammer.", ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112666 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 112666, ["questType"] = "standard", ["sourceQuests"] = { 41069 }, ["nextQuests"] = { 42671 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 17, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
