[44098] = { ["id"] = 44098, ["name"] = "Recruiting Apprentices", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["description"] = "Grand Conjuror Mimic has arrived to aid us in bolstering our numbers. She seeks out the most promising apprentices and trains them very quickly. Her former students are some of the most powerful conjurors in the land! Speak to her and recruit some of her apprentices to add to our roster.", ["objectivesText"] = "Speak to Grand Conjuror Mimic.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.808, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["ends"] = { { ["x"] = 0.808, ["y"] = 0.63, ["mapID"] = 734, ["npcID"] = 108515 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.808, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108515, ["questTurnInID"] = 108515, ["questType"] = "standard", ["sourceQuests"] = { 42171 }, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[44099] = { ["id"] = 44099, ["name"] = "A Mutual Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["description"] = "It's good to see you are well. I've been sent by our mutual friend, Calydus . He is eager to speak with you. Please return to Dreadscar Rift at your earliest convenience.", ["objectivesText"] = "Return to Calydus within Dreadscar Rift.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112693 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 112693, ["questType"] = "standard", ["sourceQuests"] = { 40824 }, ["nextQuests"] = { 42608 }, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 6, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[44100] = { ["id"] = 44100, ["name"] = "Proper Introductions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["description"] = "I'm glad I found you. I have a message from Alonsus Faol . He says introductions are in order, and requests your presence within Netherlight Temple at your earliest convenience.", ["objectivesText"] = "Return to Alonsus Faol within Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 112695 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 112695, ["questType"] = "standard", ["sourceQuests"] = { 41019 }, ["nextQuests"] = { 43270 }, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 7, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
