[44106] = { ["id"] = 44106, ["name"] = "Archdruid of Lore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38225, 38235, 38381, 44106 }, ["description"] = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore. Seek him out and tell him that he is desperately needed here.", ["objectivesText"] = "Seek out Elothir in Thas'talah.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94179, ["x"] = 0.544, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 38384 }, ["questLines"] = { { ["id"] = 187, ["name"] = "Archdruid of Lore", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 187, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[44112] = { ["id"] = 44112, ["name"] = "Trading for Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 44112 }, ["series"] = { 39337, 39338, 39431 }, ["description"] = "From the look of you, I take it you're an alchemist, yes? I'd be willing to trade my services with you for a price that I deem is fair. I have been away from Suramar for some time now. I long for an Ysera's Dream Draught . To concoct it, you'll need some dreamleaf as well as the leaves of a Dreamer's Tear. One grows not to far from here in the clearing of some ruins. Take my flask, make this drink for me, and I'll do as you ask.", ["objectivesText"] = "Use the Nightborne Flask to craft an Ysera's Dream Draught . Progress: < Leyweaver Erenyi seems lost in thought.>", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136827, 136835, 136836 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.704667, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 39431 } },
