[44115] = { ["id"] = 44115, ["name"] = "Welcome to Legion!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44115 }, ["description"] = "Welcome to World of Warcraft: Legion! We hope you enjoy all of the new experiences that await you in the Broken Isles, and want to make sure you're well-armed to take on the Burning Legion. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(44115)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(44115))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[44116] = { ["id"] = 44116, ["name"] = "Mystery at Citrine Bay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "The Burning Legion invades Azeroth, and SI:7 is wasting valuable resources hunting down and assassinating one of their top agents? Something isn't adding up... We need to find out how deep this goes. Why was Amber Kearnen being hunted by her own organization? The encrypted letter she was carrying may hold the clues... but we need more information. The SI:7 assassins you tailed in Dalaran mentioned Citrine Bay... search Citrine Bay for clues and we'll see about getting this letter decrypted.", ["objectivesText"] = "Speak with Fleet Admiral Tethys at Citrine Bay in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.781, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 44041 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[44117] = { ["id"] = 44117, ["name"] = "Time Flies When Yer Havin' Rum!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Thar be few pirates ye want to cross swords wit' less than th' Red Blade! They be salty dogs, indeed! That being said... they does have a way wit' rum! I'll level wit' ye, <name>... thar be few rums as jolly as that 'o th' Red Blade. Seein' as ye be headin' off in search 'o clues, ye might as well brin' back a few bottles while ye be at it! Brin' me back as many bottles as ye can find, and I'll reward ye handsomely! Pirates honor, <name>!", ["objectivesText"] = "Collect 10 bottles of Red Blade Rum . Progress: Have ye got th' spiced rum, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140729, 140931 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 44116 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
