[44120] = { ["id"] = 44120, ["name"] = "Illidari Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "At first I was unsure whether it was wise to allow the Illidari inside the city. But they may have just saved all our lives. I gave the demon hunters leave to establish a temporary camp in the Mage Quarter. I'd like you to be my personal envoy to them. Thank the Illidari for their assistance and see how they can aid our cause. Just... keep your eyes open. They have harnessed a terrible power, and we must be ready should they be consumed by the darkness within.", ["objectivesText"] = "Meet with the Illidari representative in the Mage Quarter of Stormwind.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 40593 }, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
