[44137] = { ["id"] = 44137, ["name"] = "Into the Fray", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely. Come, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", ["objectivesText"] = "Speak with the lead demon hunter at Illidari Stand.", ["rewardGold"] = 309800, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93337, ["x"] = 0.45, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 }, { ["mapID"] = 630, ["npcID"] = 101927, ["x"] = 0.435, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 41220 }, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
