[44140] = { ["id"] = 44140, ["name"] = "From Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within. I haven't heard from them in a while. It would be best if you could find and lead them to success. Agreed?", ["objectivesText"] = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90255, ["x"] = 0.412, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 37660 }, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[44152] = { ["id"] = 44152, ["name"] = "A Growing Crisis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "The Arcan'dor is failing. This energy was once bound in its boughs and fueled its growth. There was balance, between life and arcane. Now that energy is breaking free. When the heart can no longer hold it, this tree will kill every living thing in this hall. I have seen this happen before and I must find a way to stop it from happening again. We must go to the tree that came before. Its bones can guide us. Meet me at the temple of Fal'adora. We will descend together.", ["objectivesText"] = "Meet Valewalker Farodin at the Temple of Fala'dora. You can travel there using the Portal to Falanaar in Shal'aran.", ["rewardXP"] = 770, ["rewardItems"] = { 140255 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 107126, ["questType"] = "standard", ["sourceQuests"] = { 43318 }, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 684 },
[44153] = { ["id"] = 44153, ["name"] = "Light's Charge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44004 }, ["description"] = "\"You did not ask for this burden, but it is what fate has deemed.\" Turalyon's haunting last words still echo in my mind. I worry about the fate of the draenei... about the fate of my friend, Velen; but we must remain vigilant, <name>! For now, Light's Heart remains under your watchful eye. There is one place on Azeroth that I would trust with the safekeeping of the object: your order hall. Take it there, <name>. I will remain in Dalaran and continue looking for answers. There must be another way!", ["objectivesText"] = "Place Light's Heart in your Order Hall. Progress: This is where you must place Light's Heart .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140319, 140533, 140574, 140763 }, ["starts"] = { { ["x"] = 0.287, ["y"] = 0.485, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.287, ["y"] = 0.485, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.287, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 44004 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44154] = { ["id"] = 44154, ["name"] = "The Rite of the Executioner", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["storyline"] = { 44154 }, ["description"] = "The skulls have been gathered and the ritual area is prepared. All that is left is to perform the incantation, and Ulthalesh will become imbued with the essence of the Executioner.", ["objectivesText"] = "Interact with the Pile of Skulls and complete the Rite of the Executioner in the crypt near Morgan's Plot in Deadwind Pass.", ["starts"] = { { ["x"] = 0.387, ["y"] = 0.739, ["mapID"] = 42, ["objectID"] = 254007 } }, ["ends"] = { { ["x"] = 0.387, ["y"] = 0.739, ["mapID"] = 42, ["objectID"] = 254007 } }, ["coords"] = { ["mapID"] = 42, ["x"] = 0.387, ["y"] = 0.739 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 44083 }, ["db2QuestSortName"] = "Day of the Dead" },
[44155] = { ["id"] = 44155, ["name"] = "Searching For Clues", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "It be no coincidence that we be in Citrine Bay investigatin' a murder, and we find th' band 'o pirates known as th' Red Blade here as well! Aye, this be no coincidence at all, <name>... but we be needin' proof! Ye go on ahead and look fer clues and I'll find some scallywags to interrogate. Aye <name>, we'll get t' 'th bottom o' this t' be sure! Thar be no doubt!", ["objectivesText"] = "Find proof of SI:7 working with The Red Blade. Progress: Have ye found evidence 'o th' murder from th' pirates 'o th' Red Blade?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140730, 140931 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 44116 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
