[44161] = { ["id"] = 44161, ["name"] = "Things Gaardoun Needs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087 }, ["description"] = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that. Time to put your new champions to the test. I'm sure it will be a grueling mission.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Things Gaardoun Needs\". Progress: Did they come back already with whatever it is that Gaardoun needs?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.593, ["y"] = 0.576, ["mapID"] = 720, ["npcID"] = 103761 } }, ["ends"] = { { ["x"] = 0.593, ["y"] = 0.576, ["mapID"] = 720, ["npcID"] = 103761 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.593, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 103761, ["questTurnInID"] = 103761, ["questType"] = "standard", ["sourceQuests"] = { 42690, 42697 }, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 24, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[44174] = { ["id"] = 44174, ["name"] = "The Very Best", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44174 }, ["description"] = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets. Progress: I foresee that you will travel across the land, searching far and wide. It's your destiny.", ["rewardItems"] = { 122457 }, ["rewardChoices"] = { 122457 }, ["starts"] = { { ["x"] = 0.636, ["y"] = 0.556, ["mapID"] = 627, ["npcID"] = 111246 } }, ["ends"] = { { ["x"] = 0.636, ["y"] = 0.556, ["mapID"] = 627, ["npcID"] = 111246 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.636, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 111246, ["questTurnInID"] = 111246, ["questType"] = "standard" },
