[44177] = { ["id"] = 44177, ["name"] = "Dark Secrets and Shady Deals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Whatever Amber Kearnen knew, Mathias Shaw didn't want it gettin' out... Aye, this be dirty business indeed, hiring th' Red Blade at such a price... just to hunt down and kill one of their own! Ye best get back to th' Hall 'o Shadows, and let Lord Ravenholdt know what we found here in Citrine Bay. Whatever SI:7 be up to, it be goin' deeper than we first imagined...", ["objectivesText"] = "Speak with Lord Ravenholdt.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140517, 140931 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 112959, ["questType"] = "standard", ["sourceQuests"] = { 44117, 44155 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[44178] = { ["id"] = 44178, ["name"] = "A Particularly Potent Potion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "I've got a proposition for ya, <name>! Word has it that Trade Prince Gallywix recently acquired a priceless, one-of-a-kind love potion. There's only one goblin who can replicate it and you're looking at him! Get me that potion and I can make us both richer than kings! The pleasure palace is located in Azshara and it has been on high alert since the war started. Gallywix isn't letting anybody in except his personal staff, but I know a girl on the inside! Find her and she'll get you to the safe!", ["objectivesText"] = "Steal Love Potion #6 from Gallywix's personal safe. Progress: Do you have the goods?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140811, 140814, 140931 }, ["starts"] = { { ["x"] = 0.305, ["y"] = 0.704, ["mapID"] = 626, ["npcID"] = 102594 } }, ["ends"] = { { ["x"] = 0.305, ["y"] = 0.704, ["mapID"] = 626, ["npcID"] = 102594 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.305, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102594, ["questTurnInID"] = 102594, ["questType"] = "standard", ["sourceQuests"] = { 42730, 91620 }, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44179] = { ["id"] = 44179, ["name"] = "Treasure", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44179 }, ["description"] = "There is a strange energy in the air. I feel as if a force is growing, pressing down on us. It is worrisome. Valtrois works most closely with the sources of power in this room. Speak to her. Ask if there is anything to be concerned with. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(44179)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(44179))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Speak with Valtrois.", ["rewardGold"] = 561800, ["rewardXP"] = 4150, ["rewardItems"] = { 2842, 3342, 3343, 39336, 39380, 39433, 39454, 57549, 57571, 57572, 57574, 59198, 59199, 59200, 62958, 62959, 62960, 62961, 65924, 65949, 65973, 65994, 86428, 131459, 131474, 156948, 157007 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
