[44182] = { ["id"] = 44182, ["name"] = "City Under Siege", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7886, ["mapID"] = 42, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44184, 44421, 44500 }, ["description"] = "<Khadgar's voice erupts from the elemental once again.> Obtaining information on the Pillars of Creation before the Legion could stop us was a considerable victory. It won't bring back those we lost on the Broken Shore, but I believe it will help us avenge them. Dalaran has become a focal point of the Legion's assault. Your presence here is crucial. If the demons are putting this much effort into attacking the city, it means Dalaran will play a pivotal role in the struggle to save Azeroth.", ["objectivesText"] = "Meet Khadgar at the Chamber of the Guardian in Dalaran.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 44934 }, ["starts"] = { { ["npcID"] = 114561 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 12 } }, ["questGiverID"] = 114561, ["questType"] = "standard", ["sourceQuests"] = { 40755 }, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 42 },
