[44204] = { ["id"] = 44204, ["name"] = "Seal their Fates", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44204 }, ["description"] = "Ever feel like luck just isn't on your side? Well maybe I can help you with that. There are some interesting items I've come across in my travels which can be used to swing the dice in your favor, or at least give you another shot at it. It takes some time, and supplies are hard to come by, but I can get you one of them... for a price?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.506, ["mapID"] = 626, ["npcID"] = 110820 } }, ["ends"] = { { ["x"] = 0.616, ["y"] = 0.506, ["mapID"] = 626, ["npcID"] = 110820 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.616, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 110820, ["questTurnInID"] = 110820, ["questType"] = "standard", ["sourceQuests"] = { 43015 } },
[44205] = { ["id"] = 44205, ["name"] = "Shape Your Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["storyline"] = { 44205 }, ["description"] = "The whims of the spirits can be guided, I have seen it. There were whispers of an item, a way to change the path of destiny. I heard dem, and I went looking. For many years I listened to those whispers on the wind until one day they showed me the way. This is what I offer you. It will take some time, and some valuable resources, but I can perform the ritual to allow you to control this power. Well? Are you ready?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate. Progress: Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.311, ["y"] = 0.351, ["mapID"] = 726, ["npcID"] = 112299 } }, ["ends"] = { { ["x"] = 0.311, ["y"] = 0.351, ["mapID"] = 726, ["npcID"] = 112299 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.311, ["y"] = 0.351 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 112299, ["questTurnInID"] = 112299, ["questType"] = "standard", ["sourceQuests"] = { 41740 } },
[44206] = { ["id"] = 44206, ["name"] = "The Ascended", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["storyline"] = { 44206 }, ["description"] = "These shaman have spent their lives dedicated to the path of Air, Water or Fire. On your request, we will beseech the elements to Ascend them, becoming a powerful, if short lived, force to deploy in this war against the Legion. The ritual of ascension is not to be requested lightly.", ["objectivesText"] = "Place a request to recruit Ascendants.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 174293, 177054, 178157, 179944, 180647 }, ["starts"] = { { ["x"] = 0.316, ["y"] = 0.516, ["mapID"] = 726, ["npcID"] = 109829 } }, ["ends"] = { { ["x"] = 0.316, ["y"] = 0.516, ["mapID"] = 726, ["npcID"] = 109829 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.316, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 109829, ["questTurnInID"] = 109829, ["questType"] = "standard", ["sourceQuests"] = { 41740 } },
[44207] = { ["id"] = 44207, ["name"] = "Portal Full of Shiny Things", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 44207 }, ["description"] = "When I heard the Hall of the Guardian was open again, I said to myself \" Minuette , this is your chance!\" I rushed over here thinking I'd be hurled into the front lines. Imagine it, me, little old me, assaulting Demons with missiles, blinking away from Fel Meteors. That would be brilliant! Instead, they send me over here and say \"Hey, open up some portals so we can throw things through, would you?\" At least I get to charge something for it.", ["objectivesText"] = "Place a work order for Champion armaments and equipment.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.829, ["y"] = 0.567, ["mapID"] = 734, ["npcID"] = 110427 } }, ["ends"] = { { ["x"] = 0.829, ["y"] = 0.567, ["mapID"] = 734, ["npcID"] = 110427 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.829, ["y"] = 0.567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 110427, ["questTurnInID"] = 110427, ["questType"] = "standard", ["sourceQuests"] = { 42696 } },
[44208] = { ["id"] = 44208, ["name"] = "Fate and Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 44208 }, ["description"] = "For years we wondered, we conjectured, that it was possible to control the twisting, slipping, streaming threads of fate and destiny. These books tell of powerful mages who embraced the manipulation of time. No no, not like Time Warp, they would laugh at us, think us silly amateurs. No, they were true Chronomancers. The only spell we've been able to determine is a conjuration. It calls forth what they termed a \"Seal of Fate\". This allowed them to repeat their actions. Let us try it out shall we?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.419, ["y"] = 0.213, ["mapID"] = 734, ["npcID"] = 112982 } }, ["ends"] = { { ["x"] = 0.419, ["y"] = 0.213, ["mapID"] = 734, ["npcID"] = 112982 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.419, ["y"] = 0.213 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 112982, ["questTurnInID"] = 112982, ["questType"] = "standard", ["sourceQuests"] = { 42696 } },
[44210] = { ["id"] = 44210, ["name"] = "The Might of Dalaran pt2", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44210 }, ["description"] = "Yes, now once the crystal has been empowered, collect it here, and use it to unleash the power of our mages on a world quest. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(44210)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(44210))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Collect the Focusing Crystal and use it to complete a world quest.", ["rewardItems"] = { 140038 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
