[44278] = { ["id"] = 44278, ["name"] = "Illidari Freedom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "< Arduen Soulblade is bleeding from several ghastly wounds. It appears he was left here to die.> Within the prison are three of our... <cough>... comrades. We were taken by surprise while scouting the area. I am not long for this world, <name>, but please... you can still save them.", ["objectivesText"] = "Free Sirius Ebonwing , Cassiel Nightthorn , and Asha Ravensong .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.423, ["y"] = 0.817, ["mapID"] = 642, ["npcID"] = 93029 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95028, ["x"] = 0.39, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questGiverID"] = 93029, ["questType"] = "standard", ["sourceQuests"] = { 38717 }, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
