[44281] = { ["id"] = 44281, ["name"] = "To Be Prepared", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Our allies have made the journey to Orgrimmar to support our war efforts. Stop and visit with them, <name>. Their assistance will secure our victory today.", ["objectivesText"] = "Visit Horde forces in Dranosh'ar Blockade. Progress: Blood and thunder, friend.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 59679, 59680, 59681, 59682, 59683, 59684, 65872, 65884, 65886, 138450, 139718, 141294, 141295 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 4311, ["x"] = 0.46, ["y"] = 0.134 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 113547, ["x"] = 0.555, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.134 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 43926 }, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[44282] = { ["id"] = 44282, ["name"] = "Eye of Azshara: The Frozen Soul", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["series"] = { 44247 }, ["description"] = "Ah, Deathlord. It is good to see you. I happen to have a fascinating task for you, should you be in the mood for adventure. I recently came across an obscure reference to an ancient amulet that was created by Queen Azshara herself! It is called the Frozen Soul Pendant and it offers tremendous power to those who channel the power of frost. I have reason to believe that it may be found somewhere within the Eye of Azshara. Retrieve the pendant for me, and it will prove most useful in my studies.", ["objectivesText"] = "Retrieve the Frozen Soul Pendant from the Wrath of Azshara. Progress: Have you retrieved the pendant?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 141302 }, ["starts"] = { { ["x"] = 0.581, ["y"] = 0.311, ["mapID"] = 648, ["npcID"] = 93555 } }, ["ends"] = { { ["x"] = 0.581, ["y"] = 0.311, ["mapID"] = 648, ["npcID"] = 93555 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.581, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93555, ["questTurnInID"] = 93555, ["questType"] = "dungeon", ["sourceQuests"] = { 43928 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[44283] = { ["id"] = 44283, ["name"] = "The Emerald Nightmare: Piercing the Veil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8026, ["storyline"] = { 44283 }, ["description"] = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", ["objectivesText"] = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Normal difficulty. Progress: If only Cenarius were with us, we could confront Xavius at once.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 141303 }, ["starts"] = { { ["npcID"] = 106482 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8026 } }, ["questGiverID"] = 106482, ["questType"] = "raid" },
