[44286] = { ["id"] = 44286, ["name"] = "Vault of the Wardens: A Masterpiece of Flesh", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7695, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "Ah, Deathlord! What a pleasant surprise! It is not often that you visit my workshop of blood and flesh. Actually, I have something quite special to show you. I have been developing a new type of abomination that mixes the flesh of demons with that of humans. My first prototype, Rottgut, is nearly complete! However I am still missing some of the more difficult-to-find body items. The prisoners in the Vault of the Wardens should make fine donors for the parts I require.", ["objectivesText"] = "Retrieve the Beating Fel-Heart and Demonic Entrails from Vault of the Wardens. Progress: Have you retrieved the parts?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 141307, 141308, 141309 }, ["starts"] = { { ["x"] = 0.631, ["y"] = 0.694, ["mapID"] = 648, ["npcID"] = 93491 } }, ["ends"] = { { ["x"] = 0.631, ["y"] = 0.694, ["mapID"] = 648, ["npcID"] = 93491 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.631, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7695 } }, ["questGiverID"] = 93491, ["questTurnInID"] = 93491, ["questType"] = "dungeon", ["sourceQuests"] = { 42824 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
