[44337] = { ["id"] = 44337, ["name"] = "Goddess Watch Over You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44338, 44448 }, ["description"] = "I may have found a \"key\" to unlock Light's Heart, <name>. I was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow. If Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart. It's a long shot, but we've got nothing left to lose. Meet me in Dalaran. I will ready the Tears of Elune for you.", ["objectivesText"] = "Meet Archmage Khadgar in Dalaran.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 113686 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 113686, ["questType"] = "standard", ["sourceQuests"] = { 44153 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
