[44400] = { ["id"] = 44400, ["name"] = "Assault on Violet Hold: Purple Pain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44400 }, ["description"] = "Again! It happened again! Sure, it's the Legion that staged the prison breakout this time, but I *told* them it was a bad idea to keep some of the most dangerous beings on Azeroth in a prison inside our city! We can talk about relocating later, I suppose. Right now, we've got some... pacification to tend to. Can you help?", ["objectivesText"] = "Repel the Assault on Violet Hold. Progress: Oh, no. Don't tell me something ELSE has gone wrong?!", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 141356, 141357, 141358, 141359 }, ["rewardChoices"] = { 141356, 141357, 141358, 141359 }, ["starts"] = { { ["x"] = 0.663, ["y"] = 0.679, ["mapID"] = 627, ["npcID"] = 113813 } }, ["ends"] = { { ["x"] = 0.663, ["y"] = 0.679, ["mapID"] = 627, ["npcID"] = 113813 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.663, ["y"] = 0.679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7996 } }, ["questGiverID"] = 113813, ["questTurnInID"] = 113813, ["questType"] = "dungeon" },
