[44406] = { ["id"] = 44406, ["name"] = "Aggra's Guidance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["storyline"] = { 44406 }, ["series"] = { 43945 }, ["description"] = "<class>t, have you met the shaman Aggra ? Born of a shattered world, she learned the ways of the elements among the Mag'har orcs of Outland. On the eve of the Cataclysm she took it upon herself to complete Thrall's shamanistic training. Our younger initiates are fortunate to have her among us to guide them. If you wish to seek out a second artifact, Aggra can assist you. She is training new recruits above us on the Storm's Eye Overlook.", ["objectivesText"] = "Seek out Aggra at the Storm's Eye Overlook within the Heart of Azeroth.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.303, ["y"] = 0.516, ["mapID"] = 726, ["npcID"] = 96528 } }, ["ends"] = { { ["x"] = 0.303, ["y"] = 0.516, ["mapID"] = 726, ["npcID"] = 96528 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.303, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96528, ["questTurnInID"] = 96528, ["questType"] = "standard", ["sourceQuests"] = { 41510 } },
[44407] = { ["id"] = 44407, ["name"] = "The Third Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43935, 44407 }, ["description"] = "You have not one but TWO powerful artifacts to use against the Legion. But can you imagine a world where you have three? Think of what you could do in such a world! Shall we look at the possibilities?", ["objectivesText"] = "Speak with Alonsus Faol to pursue a third artifact.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.515, ["y"] = 0.476, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["x"] = 0.515, ["y"] = 0.476, ["mapID"] = 702, ["npcID"] = 110564 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.515, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questTurnInID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43935 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5833, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5833, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[44411] = { ["id"] = 44411, ["name"] = "Strange Humming Crystal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44411 }, ["description"] = "<You place the crystal to your ear and hear the disharmonious din of hundreds of voices speaking at once. Perhaps Khadgar might know more about this strange gem.>", ["objectivesText"] = "Take the Strange Humming Crystal to Khadgar in Dalaran .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141349, 141350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 141349 } },
[44412] = { ["id"] = 44412, ["name"] = "Enemies Everywhere", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44412 }, ["description"] = "Hold a moment, <name>. While I look into this orb of yours, why don't you look into something for me? I have long suspected an infiltration of Dalaran but after an embarrassing encounter with a local florist I've withheld my accusations until I'm absolutely certain. Have you noticed citizens among us that seem just too mundane? Almost inhumanly so? Spies, serving dark masters, watch and wait until our backs are turned. Root them out, but try and keep it quiet.", ["objectivesText"] = "Defeat the hidden infiltrators in Dalaran . Progress: Have you disposed of our friends?", ["rewardItems"] = { 71153, 140394, 140808, 141348, 141349, 141350 }, ["starts"] = { { ["x"] = 0.285, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 44411 } },
[44414] = { ["id"] = 44414, ["name"] = "Felspawns of Lothros", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8406, ["mapID"] = 793, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44415, 44416 }, ["description"] = "These Felspawns are endless! I can't cut them down quickly enough to get to the dreadlord within the mausoleum. Master Illidan, will you come with me so we can take down Lothros together?", ["objectivesText"] = "Defeat Lothros . Progress: A dreadlord poses little danger to you, eh?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.387, ["y"] = 0.531, ["mapID"] = 793, ["npcID"] = 113361 } }, ["ends"] = { { ["x"] = 0.387, ["y"] = 0.531, ["mapID"] = 793, ["npcID"] = 113361 } }, ["coords"] = { ["mapID"] = 793, ["x"] = 0.387, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8406 } }, ["questGiverID"] = 113361, ["questTurnInID"] = 113361, ["questType"] = "standard", ["sourceQuests"] = { 44479 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 13, ["flags"] = 1 } }, ["db2PoiMapID"] = 1646, ["db2PoiUiMapID"] = 793 },
[44415] = { ["id"] = 44415, ["name"] = "The Red Axe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8406, ["mapID"] = 793, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44414, 44416 }, ["description"] = "Broxigar the Red is cornered on the bridge. I am not sure he would ever admit that he needs our help, but I feel it only proper to lend him our aid. If you wish to assist our ally, I would be humbled to accompany you in this endeavor.", ["objectivesText"] = "Close the Unstable Portals and make your way to Broxigar the Red . Progress: Our allies are strong, but our enemy is Legion!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.404, ["y"] = 0.53, ["mapID"] = 793, ["npcID"] = 113361 } }, ["ends"] = { { ["x"] = 0.404, ["y"] = 0.53, ["mapID"] = 793, ["npcID"] = 113361 } }, ["coords"] = { ["mapID"] = 793, ["x"] = 0.404, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8406 } }, ["questGiverID"] = 113361, ["questTurnInID"] = 113361, ["questType"] = "standard", ["sourceQuests"] = { 44414 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 14, ["flags"] = 1 } }, ["db2PoiMapID"] = 1646, ["db2PoiUiMapID"] = 793 },
[44416] = { ["id"] = 44416, ["name"] = "Hunter of Night", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8406, ["mapID"] = 793, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44414, 44415 }, ["description"] = "A glorious battle indeed! If I am correct, we can expect something a bit more deadly at any moment. The Legion often uses fodder such as these to prepare the way for a more worthy foe. My axe is sharp and ready.", ["objectivesText"] = "Defeat Malvingeroth Progress: Are you sure you are a night elf? You wage battle with the ferocity of an orc!", ["rewardGold"] = 238680, ["rewardXP"] = 1415, ["rewardItems"] = { 121802, 139902, 139932, 139962, 140002 }, ["rewardChoices"] = { 121802, 139902, 139932, 139962, 140002 }, ["starts"] = { { ["x"] = 0.438, ["y"] = 0.503, ["mapID"] = 793, ["npcID"] = 113355 } }, ["ends"] = { { ["x"] = 0.438, ["y"] = 0.503, ["mapID"] = 793, ["npcID"] = 113355 } }, ["coords"] = { ["mapID"] = 793, ["x"] = 0.438, ["y"] = 0.503 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8406 } }, ["questGiverID"] = 113355, ["questTurnInID"] = 113355, ["questType"] = "standard", ["sourceQuests"] = { 44415 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 15, ["flags"] = 1 } }, ["db2PoiMapID"] = 1646, ["db2PoiUiMapID"] = 793 },
[44417] = { ["id"] = 44417, ["name"] = "One More Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 43949, 44417 }, ["description"] = "Two is good, but three would be better. You should pursue another artifact to add to your armory. What say you?", ["objectivesText"] = "Speak with Odyn to pursue another artifact.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 43949 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5825, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5825, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[44421] = { ["id"] = 44421, ["name"] = "Anomalous Anomalies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7886, ["mapID"] = 42, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44182, 44184, 44500 }, ["description"] = "Dalaran's move to this location was intended to be a temporary measure, but we may need to depart sooner than expected. Blinking a city across the world is no mean feat. The magnitude of energies involved can lead to... unexpected side effects. Arcane anomalies are causing mischief throughout the city. Their presence could destabilize any attempt to blink again. We don't have time to let them dissipate on their own, <name>. I have a device that will help speed things along.", ["objectivesText"] = "Use Khadgar's crystal to neutralize anomalies in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141411 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 44182 }, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead" },
[44424] = { ["id"] = 44424, ["name"] = "Three Paths, Three Weapons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 43973, 44424 }, ["description"] = "We've searched and found a lead upon another artifact that you might find helpful. Here, let me show you what I've found. If it interests you then simply let me know.", ["objectivesText"] = "Choose a third artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.484, ["mapID"] = 709, ["npcID"] = 100438 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 100438, ["questTurnInID"] = 100438, ["questType"] = "standard", ["sourceQuests"] = { 43973 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5837, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5837, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[44431] = { ["id"] = 44431, ["name"] = "More Weapons of Old", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 43980, 44431, 44443 }, ["description"] = "You've had great success against our foes, but you should be ready for any challenge they send your way. You would be wise to consider obtaining yet another of the weapons of old to aid in our conflict. Let me know how you'd like to proceed.", ["objectivesText"] = "Choose a third artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.447, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 43980 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5838, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5838, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44443] = { ["id"] = 44443, ["name"] = "Weapons of the Ancients", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 43980, 44431, 44443 }, ["description"] = "You've proven yourself to be a druid without equal, but if we are to succeed in our battles against the Burning Legion you need you to take advantage of every opportunity to stay ahead of our foes. You should consider obtaining one final weapon of the Ancients. Its powers will maximize your ability to adapt to whatever the Legion can throw our way. Let me know how you'd like to proceed.", ["objectivesText"] = "Choose a fourth artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["x"] = 0.447, ["y"] = 0.52, ["mapID"] = 747, ["npcID"] = 101195 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.447, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questTurnInID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 44431 }, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5838, ["name"] = "Weapons of Legend", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5838, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44448] = { ["id"] = 44448, ["name"] = "In the House of Light and Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44337, 44338 }, ["description"] = "The Tears of Elune are ready for you, <name>. I am uncertain what to do from here. Take the relic back to your order hall and try to use it on Light's Heart. Maybe make them touch? Honestly your guess is as good as mine. Let's hope this works!", ["objectivesText"] = "Take the Tears of Elune to Light's Heart in your Order Hall. Progress: Any news?", ["rewardGold"] = 606600, ["rewardXP"] = 1415, ["rewardItems"] = { 141351 }, ["starts"] = { { ["x"] = 0.289, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.289, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.289, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 40890, 44337, 44338 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44449] = { ["id"] = 44449, ["name"] = "Advanced Quenching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729 }, ["description"] = "Now that we have a frost mage at our disposal, testing this method out should be a cinch. Here are the plans for what I'd like you to make. Get to work and give me the armguards when you're finished.", ["objectivesText"] = "Craft a pair of Hard Leystone Armguards for Alard. Progress: How's that technique coming along?", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124393, 124394, 124395, 124396, 124397, 124436, 124462, 137680 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.286, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.446, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "standard", ["sourceQuests"] = { 38564 }, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 41, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44455] = { ["id"] = 44455, ["name"] = "Downfall Tracking", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44457] = { ["id"] = 44457, ["name"] = "Brotherly Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "Maiev will be somewhere in the prison. I found her discarded armor on my way here. I know the two of you have a history. I trust that will not be a problem. Let's split up to search the cells more quickly. We must find her.", ["objectivesText"] = "Find Maiev Shadowsong in Black Rook Prison. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139353 }, ["starts"] = { { ["x"] = 0.423, ["y"] = 0.817, ["mapID"] = 642, ["npcID"] = 92850 } }, ["ends"] = { { ["x"] = 0.423, ["y"] = 0.817, ["mapID"] = 642, ["npcID"] = 92850 } }, ["coords"] = { ["mapID"] = 642, ["x"] = 0.423, ["y"] = 0.817 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 92850, ["questTurnInID"] = 92850, ["questType"] = "standard", ["sourceQuests"] = { 38717 }, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[44463] = { ["id"] = 44463, ["name"] = "Demons Among Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It is just as we suspected, <name>! The demons thought they could take us by surprise. Quickly, to arms! Warn the King!", ["objectivesText"] = "Protect the King. Progress: Now is not a good time.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104 }, ["rewardChoices"] = { 128959 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8445, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 44471 }, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[44464] = { ["id"] = 44464, ["name"] = "Awakenings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Light's Heart is to serve as the vessel for Illidan Stormrage's rebirth: my last act of service to the Light. But Illidan is dead and his soul is lost in the Nether. Before we may attempt to recover his soul, we must prepare the vessel for his return. Across two worlds exist echoes of Illidan's past. You must venture out and find the echoes. Start where all life begins, <name>: birth. Find Illidan's birthplace in Val'sharah. Awaken the memory.", ["objectivesText"] = "Witness the Awakening of Illidan Stormrage in Val'sharah. Progress: When our work is complete, I will be lost to the Great Dark.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 141351 }, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 44448 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44465] = { ["id"] = 44465, ["name"] = "Recruiting Earthcallers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "Felinda Frye has recently joined us at the Heart of Azeroth. She oversees the recruitment and training of our Earthcallers. I recommend that you speak with her at your soonest convenience, Farseer <name>. The Earthcallers are powerful shaman and will greatly bolster our ranks.", ["objectivesText"] = "Speak to Felinda Frye .", ["rewardGold"] = 23870, ["rewardXP"] = 175, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.604, ["mapID"] = 726, ["npcID"] = 96746 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.604, ["mapID"] = 726, ["npcID"] = 96746 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.33, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 96746, ["questTurnInID"] = 96746, ["questType"] = "standard", ["sourceQuests"] = { 41901 }, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[44466] = { ["id"] = 44466, ["name"] = "An Unclear Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44479 }, ["description"] = "Much of Illidan's formative years were spent in Val'sharah, alongside his twin brother, Malfurion. As young night elves, the twins vied for the affection of the young priestess, Tyrande, as they underwent the trials of the demi-god, Cenarius. We must travel to the Dreamgrove now, where Illidan's true path would be forged.", ["objectivesText"] = "Witness Illidan's Resilience at the Dreamgrove in Val'sharah. Progress: You mustn't lose hope.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 44464 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44471] = { ["id"] = 44471, ["name"] = "Second Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44473, 44543, 44663, 95215 }, ["description"] = "Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness. Even now, I sense something amiss, <name>. I fear that not all is as it seems. Quickly, use your Spectral Sight. We must know if there are foes among us!", ["objectivesText"] = "Use your Spectral Sight. Progress: Time is precious.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8445, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 39691 }, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[44473] = { ["id"] = 44473, ["name"] = "A Weapon of the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44543, 44663, 95215 }, ["description"] = "At first I was unsure whether it was wise to allow the Illidari inside the city. But you may have just saved all our lives. You may establish a camp in the Mage Quarter. The Alliance will have need of your skills if we are to face the Legion. Make no mistake though. Should your kind give in to the fel energies you toy with, we will treat you like the demons you are becoming.", ["objectivesText"] = "Meet with the Illidari in the Mage Quarter of Stormwind.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 44463 }, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[44480] = { ["id"] = 44480, ["name"] = "In My Father's House", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Most mortals cannot comprehend the truth of the Legion. Those that recognize it, often refuse to accept its meaning. Such knowledge carries a weight that the mortal frame cannot bear. To sacrifice that much of ones self changes the soul. Among your greatest heroes, a rare few understood that type of sacrifice. Let us witness it through Illidan's eyes. We must go to Azshara, on the continent of Kalimdor.", ["objectivesText"] = "Witness Illidan's Sacrifice in Azshara on the continent of Kalimdor. Progress: The vessel is nearly ready to take on the soul.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 249230 }, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 44479 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44481] = { ["id"] = 44481, ["name"] = "Destiny Unfulfilled", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus. Yet, in a strange twist of fate, it was not the Burning Legion who came for him in the end. We must travel to Outland to experience Illidan's last memory.", ["objectivesText"] = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland. Progress: When the vessel is prepared, we will seek out his soul.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 32757, 121745, 137015, 139909, 139946, 140005, 151016, 249229 }, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 44480 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44482] = { ["id"] = 44482, ["name"] = "Recruiting Ebon Knights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 726, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Korgaz Deadaxe has been hard at work training a new generation of death knights. He has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade. Korgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience. New death knights will bolster our ranks and aid is in the war against the Burning Legion.", ["objectivesText"] = "Speak to Korgaz Deadaxe.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 11, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[44486] = { ["id"] = 44486, ["name"] = "Fel-Ravaged Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44486 }, ["description"] = "Much of the elven writing in the tome has been singed by fel fire. The head of the curators in Dalaran is renowned for his restoration skills. Perhaps he can treat the tome to bring it back to legibility.", ["objectivesText"] = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran . Progress: Oh, what's this one now?", ["rewardXP"] = 6140, ["rewardItems"] = { 141360 }, ["starts"] = { { ["objectID"] = 258979, ["x"] = 0.5463, ["y"] = 0.3548, ["mapID"] = 712 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7787 } }, ["questType"] = "standard" },
[44487] = { ["id"] = 44487, ["name"] = "Waterlogged Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44487 }, ["description"] = "In spite of its magical nature, the book has been damaged by water. The head of the curators in Dalaran is renowned for his abilities. Perhaps he can restore it.", ["objectivesText"] = "Bring the Waterlogged Tome to Robert Newhearth in Dalaran . Progress: What have we here?", ["rewardXP"] = 6140, ["rewardItems"] = { 141355 }, ["starts"] = { { ["x"] = 0.391, ["y"] = 0.737, ["mapID"] = 45, ["objectID"] = 258978 } }, ["ends"] = { { ["x"] = 0.391, ["y"] = 0.737, ["mapID"] = 45, ["objectID"] = 258978 } }, ["coords"] = { ["mapID"] = 45, ["x"] = 0.391, ["y"] = 0.737 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Day of the Dead" },
[44488] = { ["id"] = 44488, ["name"] = "Cursed Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44488 }, ["description"] = "Much of the elven writing in the tome has been singed by fel fire. The head of the curators in Dalaran is renowned for his restoration skills. Perhaps he can treat the tome to bring it back to legibility.", ["objectivesText"] = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran . Progress: Oh, what's this one now?", ["rewardXP"] = 6140, ["rewardItems"] = { 141361 }, ["starts"] = { { ["x"] = 0.376, ["y"] = 0.593, ["mapID"] = 539, ["objectID"] = 258980 } }, ["ends"] = { { ["x"] = 0.376, ["y"] = 0.593, ["mapID"] = 539, ["objectID"] = 258980 } }, ["coords"] = { ["mapID"] = 539, ["x"] = 0.376, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[44489] = { ["id"] = 44489, ["name"] = "Lyana Darksorrow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "<Your fellow Illidari, Lyana Darksorrow , floats captive in stasis in front of you; her soul slowly draining into the harvester crystal.> <In order to release her from stasis, you will need to destroy the soul harvester.>", ["objectivesText"] = "Destroy the Soul Harvester.", ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98801, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42230 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44490] = { ["id"] = 44490, ["name"] = "Grimwing the Devourer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "You have my thanks for rescuing me from captivity, <name>. However, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion. Before we can get to him, there is another that must be destroyed. Grimwing the Devourer is the strongest of the felbats. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears. Then, return to me with her head. My thirst for vengeance must be quenched.", ["objectivesText"] = "Slay Grimwing the Devourer. Progress: What news do you bring of Grimwing the Devourer?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 133756, 134065, 140239, 141936, 141938, 141939 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40307, 40898 }, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44491] = { ["id"] = 44491, ["name"] = "7.0 Suramar Collapse Scenario - Run Once", ["level"] = 0, ["requiredLevel"] = 0, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44492] = { ["id"] = 44492, ["name"] = "Leyline Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44492 }, ["description"] = "Good work finding those additional leyline feeds. You seem rather competent - for an outlander. Allow me to share with you a few secrets about the power of the leylines. This should help you in scavenging more ancient mana from the creatures around Suramar . A grisly task, I know - which is why I leave it to you!", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44493] = { ["id"] = 44493, ["name"] = "Leyline Proficiency", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44493 }, ["description"] = "Our leyline feed grows stronger. The more powerful our feed becomes, the more I learn about ancient mana itself. Of course, as my apprentice, you may reap the benefits of my discoveries. Listen well, and I will teach you how to extract power from your enemies more reliably.", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44495] = { ["id"] = 44495, ["name"] = "Leyline Master", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44495 }, ["description"] = "You surprise me, outlander. During our first lesson about the ancient leylines, I half-expected you to be lost in daydreams of adventure, or treasure or... some such nonsense. But you have proven an apt student. Our leyline feed has grown extremely powerful. Watching it grow has taught me a great deal about the arcane, and the nature of mana. I have one final lesson that will help you find even more ancient mana.", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 41028, 43587, 43588, 43590, 43591, 43592, 43593, 43594 } },
[44496] = { ["id"] = 44496, ["name"] = "Destiny Unfulfilled", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus. Yet, in a strange twist of fate, it was not the Burning Legion who came for him in the end. We must travel to Outland to experience Illidan's last memory.", ["objectivesText"] = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland. Progress: When the vessel is prepared, we will seek out his soul.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 121745, 139909, 139946, 140005, 249229 }, ["starts"] = { { ["npcID"] = 112952, ["mapID"] = 1479 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 112952, ["questType"] = "standard", ["sourceQuests"] = { 44480 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44497] = { ["id"] = 44497, ["name"] = "Destiny Unfulfilled", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus. Yet, in a strange twist of fate, it was not the Burning Legion who came for him in the end. We must travel to Outland to experience Illidan's last memory.", ["objectivesText"] = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland. Progress: When the vessel is prepared, we will seek out his soul.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 32757, 121745, 139909, 139946, 140005, 249229 }, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 44480 }, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44498] = { ["id"] = 44498, ["name"] = "Winterhoof Cleansing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 44498 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24523, 24524, 24540, 24550 }, ["description"] = "I have crafted the totem to cleanse the Winterhoof Water Well. Now, you must take it to the well and perform a cleansing ritual. The well is to the southeast, but be warned: whoever did this may still be there, laying in wait. This may prove very dangerous, . Be careful...but do not let the defilers of our well escape.", ["objectivesText"] = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", ["rewardXP"] = 200, ["rewardItems"] = { 5411, 57205, 57221 }, ["rewardChoices"] = { 57221, 57205 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 215 } }, ["questType"] = "standard" },
[44500] = { ["id"] = 44500, ["name"] = "Author! Author!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7886, ["mapID"] = 42, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44182, 44184, 44421 }, ["description"] = "We've reviewed the tome recovered from Karazhan. Though we found references to the Pillars of Creation, one piece of crucial information was omitted from the book... where to find the artifacts. Fortunately, we have access to an expert on the subject. The author, Alodi, was the first Guardian of Tirisfal. His spirit is forever bound to the Forge of the Guardian, which has been hidden in our safekeeping. I think the time has come to call him forth.", ["objectivesText"] = "Tell Khadgar to begin the ritual to summon the spirit of Alodi, the first Guardian. Progress: Alodi's knowledge of the Pillars of Creation is crucial to our campaign against the Legion.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128862 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 44421 }, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead" },
[44543] = { ["id"] = 44543, ["name"] = "The Battle for Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40522, 40605, 40607, 40760, 44092, 44543 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44663, 95215 }, ["description"] = "This wind rider will take you to Broken Shore, <name>. May your weapon bring you many kills today. The Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", ["objectivesText"] = "Take the wind rider to the Broken Shore.", ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292 }, ["rewardChoices"] = { 136587, 136589, 136590, 139292 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100453, ["x"] = 0.572, ["y"] = 0.105 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.105 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1 },
[44544] = { ["id"] = 44544, ["name"] = "Call of the Earthen Ring", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "At last, I've found you! I have a message from Advisor Sevel . The Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.", ["objectivesText"] = "Speak with Advisor Sevel .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 114274 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 114274, ["questType"] = "standard", ["sourceQuests"] = { 41510 }, ["nextQuests"] = { 42188 }, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[44545] = { ["id"] = 44545, ["name"] = "Pressing the Assault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44545 }, ["description"] = "<With this Pillar of Creation safely secured, it is time to take advantage of your momentum and continue onward after the next.> <You recall that your order has gathered information that would aid you in your journey - looking it over once more before setting off would be wise.>", ["objectivesText"] = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 40890, 42213, 42454, 43349, 45420 } },
[44547] = { ["id"] = 44547, ["name"] = "Isle Hopping", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44547 }, ["description"] = "<Victory in hand, you know there are still Pillars of Creation that must be recovered if the Legion is to be defeated once and for all.> <Your order has identified uncharted regions of the Broken Isles that still house the remaining Pillars - looking over the information would help focus your next effort.>", ["objectivesText"] = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 40890, 42213, 42454, 43349, 45420 } },
[44548] = { ["id"] = 44548, ["name"] = "Scouring What Remains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44548 }, ["description"] = "<Looking around the chamber, you know you are well on your way to gathering all of the Pillars of Creation, but your work is not yet complete.> <Your order has continued to scour the isles below for anything that might be useful - best to check in with them before embarking once more.>", ["objectivesText"] = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 40890, 42213, 42454, 43349, 45420 } },
[44549] = { ["id"] = 44549, ["name"] = "Master of the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44549 }, ["description"] = "<Only one region remains from your order's carefully laid plan to assault the Broken Isles and gather the Pillars of Creation.> <Victory feels close, but studying your order's intelligence one last time couldn't hurt.>", ["objectivesText"] = "Review your remaining assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 40890, 42213, 42454, 43349, 45420 } },
[44550] = { ["id"] = 44550, ["name"] = "Called to Acherus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 680, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["description"] = "Deathlord, your presence has been requested on Acherus. The war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders. Please return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.", ["objectivesText"] = "Speak with Siouxsie the Banshee at Acherus: The Ebon Hold. You can use Death Gate to return there.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["starts"] = { { ["npcID"] = 114282 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 114282, ["questType"] = "standard", ["sourceQuests"] = { 42484 }, ["nextQuests"] = { 43264 }, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44555] = { ["id"] = 44555, ["name"] = "Khadgar's Discovery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40008, 40009, 40123 }, ["description"] = "Champion! Please come to the Violet Citadel immediately. I have made a discovery that I would like to share with you before the Council of Six.", ["objectivesText"] = "Speak with Archmage Khadgar in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 121804, 140234, 141667, 142054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["nextQuests"] = { 39986 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 1, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 32, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44557] = { ["id"] = 44557, ["name"] = "Finite Numbers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["description"] = "It seems not all the protections I put in place have been defeated. The Legion isn't able to open portals inside or near the tower... at least, not yet. They appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass . Disable them and you just might buy us the time we need to drive them out of Karazhan.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.47, ["y"] = 0.752, ["mapID"] = 42, ["npcID"] = 114310 } }, ["ends"] = { { ["x"] = 0.47, ["y"] = 0.752, ["mapID"] = 42, ["npcID"] = 114310 } }, ["coords"] = { ["mapID"] = 42, ["x"] = 0.47, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 41 } }, ["questGiverID"] = 114310, ["questTurnInID"] = 114310, ["questType"] = "group", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44561] = { ["id"] = 44561, ["name"] = "Seed of Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44561 }, ["description"] = "Thalyssra was wise to send you in search of the arcan'dor, though she underestimates its power. She will learn - as will the others. But it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.", ["objectivesText"] = "Reach Honored with The Nightfallen . Progress: The arcan'dor needs time.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 141681, 141685 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42230 } },
[44562] = { ["id"] = 44562, ["name"] = "Growing Strong", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44562 }, ["description"] = "Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us. The shal'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony. But I sense potential among the Nightfallen . Losing everything has humbled them. It has made them stronger. Stay the course, $p. Help the Nightfallen rise up.", ["objectivesText"] = "Reach Revered with The Nightfallen . Progress: Have you felt it? Change is on the wind.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 141681, 141685 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44561 } },
[44563] = { ["id"] = 44563, ["name"] = "Redemption for the Fallen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44563 }, ["description"] = "Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate. You have given them hope, and set them on the path to redemption. They need you now more than ever. We all do.", ["objectivesText"] = "Reach Exalted with The Nightfallen . Progress: There is much to be done.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 141685 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44562 } },
[44569] = { ["id"] = 44569, ["name"] = "Inquisitor Volitix", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["starts"] = { { ["x"] = 0.248, ["y"] = 0.498, ["mapID"] = 680, ["npcID"] = 103841 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
