[44636] = { ["id"] = 44636, ["name"] = "Building an Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44636 }, ["description"] = "We must keep our eyes on the future. There will come a time when we will need an army. We've proven that the withered are not completely beyond redemption. They can be taught, and molded. I want you to be their combat trainer, <name>. Come with me. We can use the nearby ruins as an arena to hone their abilities.", ["objectivesText"] = "Speak with Thalyssra when you are ready to lead the withered in their first combat training mission.", ["rewardItems"] = { 93730, 124124, 127834, 127847, 127848, 127849, 127850, 136269, 136914, 137573, 139010, 139011, 139017, 139018, 139019, 139027, 139028, 139546, 139563, 139565, 139786, 139890, 140218, 140226, 140260, 140326, 140327, 140328, 140329, 140447, 140448, 140449, 140450, 140451, 140495, 140778, 141296, 141593, 141652, 141870 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 97140, ["questType"] = "standard", ["sourceQuests"] = { 42230 } },
[44663] = { ["id"] = 44663, ["name"] = "In the Blink of an Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7886, ["mapID"] = 85, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 95215 }, ["description"] = "<The entity speaks with the familiar voice of Archmage Khadgar.> Azeroth needs you, <name>! After scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation. To find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid. The Legion is assaulting our current position over Deadwind Pass. Hurry!", ["objectivesText"] = "Witness the teleportation of Dalaran to the Broken Isles.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 140192, 143785 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 }, { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.525667, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 84, 85 }, ["zone"] = { 1519 } }, ["questTurnInID"] = 95234, ["questType"] = "standard", ["sourceQuests"] = { 40605, 41002, 44120, 44473 }, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 619 },
[44667] = { ["id"] = 44667, ["name"] = "Will of the Valarjar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "As we prepare to launch an attack on the Legion's own world, it is important to not give reprieve to our enemies in this one. As your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.", ["objectivesText"] = "Complete 10 World Quests. Progress: You've returned, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 43090 }, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
