[44672] = { ["id"] = 44672, ["name"] = "Ancient Mana", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["description"] = "Without the Nightwell to feed upon, my comrades and I will have to live off the land itself. Ancient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems. <Thalyssra picks up a small stone and, whispering words of power, traces a rune upon it with her fingertip.> This stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.", ["objectivesText"] = "Gather from 3 Ancient Mana nodes. Progress: We need all the ancient mana we can get. Make sure you know how to find it!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42229 }, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
