[44680] = { ["id"] = 44680, ["name"] = "Leading by Example", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "We cannot let our current situation overshadow the Unseen Path's mission to protect the people of Azeroth. There are many in this world who could use our help. As our leader, you can set the example by aiding those in need.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 42405 }, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[44682] = { ["id"] = 44682, ["name"] = "Unparalleled Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["description"] = "Power is all around us, <name>, waiting to be harnessed. You must venture out into the world and claim it for the council! With our First wielding such unparalleled power, our enemies won't stand a chance.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.67, ["y"] = 0.464, ["mapID"] = 717, ["npcID"] = 106199 } }, ["ends"] = { { ["x"] = 0.67, ["y"] = 0.464, ["mapID"] = 717, ["npcID"] = 106199 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.67, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 106199, ["questTurnInID"] = 106199, ["questType"] = "standard", ["sourceQuests"] = { 41751, 41754 }, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[44683] = { ["id"] = 44683, ["name"] = "Holding the Lines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "Karazhan sits upon a confluence of ley lines. It's why this location was chosen for the tower in the first place... a fact that has not escaped the Legion's notice. If the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we're to have a chance of retaking the tower, <name>.", ["objectivesText"] = "Secure the Eastern Ley Line and Western Ley Line beneath Karazhan.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142450 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 6, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[44684] = { ["id"] = 44684, ["name"] = "Corruption Runs Deep", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan. This vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we'll be closer to unraveling their scheme.", ["objectivesText"] = "Recover an Essence of Corrupted Soil and an Essence of Corrupted Water from the caverns beneath Deadwind Pass . Progress: What have we here?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141878, 142449 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 7, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[44685] = { ["id"] = 44685, ["name"] = "Reclaiming the Ramparts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "With the ley lines protected we must move to secure the tower's perimeter. Around the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards. With the progress we've made so far, bolstering our defenses should keep the remaining Legion's forces at bay just long enough for us to discover who's behind their efforts.", ["objectivesText"] = "Plant the Wards at the Eastern, Southern and Northern locations around the tower in Deadwind Pass . Progress: Has the tower been secured?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142213, 142451 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["sourceQuests"] = { 44557, 44683, 44684 }, ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 8, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead" },
[44686] = { ["id"] = 44686, ["name"] = "Thought Collection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they've captured one of the demons. Go, interrogate it. Find out anything you can. And hurry! I'm afraid time is no longer an ally.", ["objectivesText"] = "Interrogate the Captured Wyrmtongue in the structure just north of the tower in Deadwind Pass . Progress: Has it been handled, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 44557, 44683, 44684 }, ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead" },
[44689] = { ["id"] = 44689, ["name"] = "The Might of the Tirisgarde", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["description"] = "The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.", ["objectivesText"] = "Complete 10 World Quests. Progress: Azeroth will burn without our help.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 250 } }, ["starts"] = { { ["x"] = 0.717, ["y"] = 0.548, ["mapID"] = 735, ["npcID"] = 107351 } }, ["ends"] = { { ["x"] = 0.717, ["y"] = 0.548, ["mapID"] = 735, ["npcID"] = 107351 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.717, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 107351, ["questTurnInID"] = 107351, ["questType"] = "standard", ["sourceQuests"] = { 42520 }, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[44690] = { ["id"] = 44690, ["name"] = "A Thirst For Blood", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["objectivesText"] = "Progress: Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best. If my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124 }, ["starts"] = { { ["x"] = 0.631, ["y"] = 0.694, ["mapID"] = 648, ["npcID"] = 93491 } }, ["ends"] = { { ["x"] = 0.631, ["y"] = 0.694, ["mapID"] = 648, ["npcID"] = 93491 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.631, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 93491, ["questTurnInID"] = 93491, ["questType"] = "standard", ["sourceQuests"] = { 43573 }, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
[44691] = { ["id"] = 44691, ["name"] = "Hungry Work", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "We must get Chief Telemancer Oculeth back on his feet as soon as possible. Find ancient mana, any way you can, and feed it to him.", ["objectivesText"] = "Use Ancient Mana to feed Chief Telemancer Oculeth .", ["rewardGold"] = 283700, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 141652, 141933, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40830 }, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44694] = { ["id"] = 44694, ["name"] = "One Battle at a Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["description"] = "Before I became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use. One thing I can still manage is the occasional glimpse into faraway places. You've seen me use the nether crucible to do this. I'm afraid that things don't look too good. The forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["starts"] = { { ["x"] = 0.59, ["y"] = 0.738, ["mapID"] = 721, ["npcID"] = 98646 } }, ["ends"] = { { ["x"] = 0.59, ["y"] = 0.738, ["mapID"] = 721, ["npcID"] = 98646 } }, ["coords"] = { ["mapID"] = 721, ["x"] = 0.59, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 98646, ["questTurnInID"] = 98646, ["questType"] = "standard", ["sourceQuests"] = { 42776 }, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[44700] = { ["id"] = 44700, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38035, 38206, 39800, 44700 }, ["series"] = { 38035, 38052, 38206, 39735, 39800 }, ["description"] = "It is good we found you, <name>! Sky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel. Make haste!", ["objectivesText"] = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", ["rewardGold"] = 715, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107460, ["x"] = 0.302, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 96644, ["x"] = 0.185538, ["y"] = 0.462154 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 84, 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 131, ["name"] = "Greymane's Gambit", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 131, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44701] = { ["id"] = 44701, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38307, 39698, 39801, 44701 }, ["series"] = { 38307, 39864 }, ["description"] = "It is good we found you, <name>! Nathanos Blightcaller , Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel. Make haste!", ["objectivesText"] = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107460, ["x"] = 0.302, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 96683, ["x"] = 0.612, ["y"] = 0.088 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1, 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 130, ["name"] = "Greymane's Gambit", ["orderIndex"] = 0, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 130, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44719] = { ["id"] = 44719, ["name"] = "Breaching the Sanctum", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44719, 44964, 45269 }, ["series"] = { 45417, 45420 }, ["description"] = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area. Take these telemancy orbs . If you find you need support, use them to summon Withered. We must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", ["objectivesText"] = "Speak with Oculeth to start the assault. Progress: We've done it! Despite the initial failures, we are still in position to enter the Breach and free our comrades.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142118, 142401, 143747, 146669, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115367, ["x"] = 0.433, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44964 }, ["questLines"] = { { ["id"] = 292, ["name"] = "Breaking the Nighthold", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 292, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44720] = { ["id"] = 44720, ["name"] = "A Call to Action", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 646, ["storyline"] = { 44720, 44721, 44729, 44771 }, ["series"] = { 44721, 44729, 44771, 44868 }, ["description"] = "<As the raven stares into your eyes, a familiar voice fills your mind.> Champion, I require your aid. It seems Helya has shown her hand. Steel yourself then come to me.", ["objectivesText"] = "Find Havi at Valdisdall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119531, ["x"] = 0.446, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 634, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 280, ["name"] = "Deemed Worthy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[44721] = { ["id"] = 44721, ["name"] = "Helya's Conquest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44720, 44721, 44729, 44771 }, ["series"] = { 44720, 44729, 44771, 44868 }, ["description"] = "If Helya is making an advance on the Broken Isles, we will need to answer in turn. Go to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.", ["objectivesText"] = "Search Tideskorn Harbor for evidence of Helya's forces. Progress: What is Helya planning?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142535 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 44771 }, ["questLines"] = { { ["id"] = 280, ["name"] = "Deemed Worthy", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[44722] = { ["id"] = 44722, ["name"] = "Disillusioned Defector", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "The atmosphere in the city has improved little, but we may find this to our advantage today. Silgryn asks for you at the Terrace. It seems even Elisande's forces are fleeing before her insanity. A defector has risen from the ranks and seeks to join our cause. See that this individual is well received, <name>. We need all the friends we can get during these dark times.", ["objectivesText"] = "Meet Silgryn at Evermoon Terrace.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45261 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44723] = { ["id"] = 44723, ["name"] = "More Like Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Greetings, Outlander. I am Victoire . I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good. The massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself. There are others who feel as I do. They simply need proof that there is another way. The Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.", ["objectivesText"] = "Use the Dusk Lily Sigil on Duskwatch Subjugators to identify 5 Deserters. Progress: Did you find more like me?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142065, 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114956, ["x"] = 0.52, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114956, ["x"] = 0.52, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44722 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44724] = { ["id"] = 44724, ["name"] = "Missing Persons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Our new friend brings us some disturbing information. She claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor. Those taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons. I need you to find out where these people went. Infiltrate the harbor and gather any information you can. Start with the Legion filth- their corpses may point us in the right direction.", ["objectivesText"] = "Acquire a Legion Communicator from demons in Astravar Harbor. Progress: Have you learned where the captives have been taken?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44722 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44725] = { ["id"] = 44725, ["name"] = "Hostage Situation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Our own people, sacrificed to the Legion! We need to intercept a transport if we intend to put an end to this trade. I'm afraid this does mean you will be playing the part of a captive, my friend. Before voicing your concerns, try to have a little faith. We will follow behind in one of Deline's boats and break you out once we know where they are going. Go to the harbor and find a group of captives. Stand among them. Allow yourself to be taken. We will not be far.", ["objectivesText"] = "Go to Astravar Harbor and join a group of captives being taken to Felsoul Hold. Progress: Please try to trust me. We will allow no harm to come to you.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44723, 44724 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[44726] = { ["id"] = 44726, ["name"] = "In the Business of Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "We will hold our position here while you find and slay the demon responsible for this camp. Ending Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people. Go quickly. He is somewhere atop this ridge.", ["objectivesText"] = "Slay Aargoss in Felsoul Advance. Progress: Have you dealt with Aargoss ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143739 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44725 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[44727] = { ["id"] = 44727, ["name"] = "Smuggled!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Please get me out of here! The bars are brittle but I am so weak... The others! There are so many others! Please help us!", ["objectivesText"] = "Release Maribeth and 5 captives in Felsoul Advance.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115002, ["x"] = 0.258, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115376, ["x"] = 0.248, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44725 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
