[44738] = { ["id"] = 44738, ["name"] = "Full Might of the Elves", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44739, 44740, 45266, 45281 }, ["description"] = "Thalyssra managed to get all 3 to agree to the same thing? I am impressed with her skills of negotiation. Alright hero, Liadrin is already marching on Suramar . Join her forces. Tyrande will flank the city defenders and meet you deeper in. The Nightborne will bring up the rear and hold the territory for us. Oculeth and I will move the Kirin Tor forces to Astravar Harbor. With luck, we shall see you on the other side.", ["objectivesText"] = "Lead the elven army to Astravar Harbor. Progress: All this running is exhausting.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140040, 140069, 140071, 140072, 140073, 140074, 140075, 140076, 140077, 140078, 143749 }, ["rewardChoices"] = { 140040, 140069, 140071, 140072, 140073, 140074, 140075, 140076, 140077, 140078 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.5235 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44739 }, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44739] = { ["id"] = 44739, ["name"] = "Ready for Battle", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44738, 44740, 45266, 45281 }, ["description"] = "Thanks to your efforts and a lot of effort on the part of our new army, the Nightfallen are prepared for battle. What is more, we have managed to evacuate nearly all of the civilians between here and Astravar Harbor. I have drafted plans that can lead our combined forces through the city and take the harbor. Can you deliver these plans to Vereesa, Tyrande and Liadrin?", ["objectivesText"] = "Deliver plans to Vereesa Windrunner , Lady Liadrin and Tyrande Whisperwind . Progress: So many different types of elves. Each of us changed in some way by the magic we wield. It is very, enlightening.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45266 }, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44740] = { ["id"] = 44740, ["name"] = "Staging Point", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44738, 44739, 45266, 45281 }, ["description"] = "That is quite a corridor you and our allies have punched through the city. It will be difficult to hold but it will cut a wedge in Elisande's forces. Oculeth has been busy redirecting a telemancy beacon to this location but wanted to give you the honor of activating it.", ["objectivesText"] = "Activate the Astravar Beacon. Progress: Has the beacon been activated.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.692667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44738 }, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44741] = { ["id"] = 44741, ["name"] = "Return to Karazhan: The Big Bag Theory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 680, ["storyline"] = { 44741 }, ["description"] = "I'm sure you've heard, <name>, that a bigger bag is always better. I disagree. I believe it's the quality of the bag that makes all the difference. Just look at those tattered things around your person. They make you look... well, quite plain. I'll prove it to you. Allegedly there are some bags in Karazhan that hold an almost infinite amount of items, but the materials required to make such bags are... well, you'll see.", ["objectivesText"] = "Recover a Bag of a Thousand Pockets and a Fel Sinew Bag from Karazhan. Progress: After this lesson, I trust I won't have to prove anything further to you.", ["rewardItems"] = { 114821, 137557, 142122, 143548 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8443 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 276, ["name"] = "Legion Tailoring", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44742] = { ["id"] = 44742, ["name"] = "Tavernkeeper's Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["series"] = { 45262 }, ["description"] = "I have finished unraveling Ly'leth's message. I want you to come with me to her estate. It is long past time I returned to the city.", ["objectivesText"] = "Follow Thalyssra to the Lunastre Estate and learn of Vanthir's fate. Progress: Dire news like this cannot wait.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115247, ["x"] = 0.432, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45262 }, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44743] = { ["id"] = 44743, ["name"] = "Tyrande's Command", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44861, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44827, 44858, 44859, 44860, 44861, 44862 }, ["description"] = "Shal'aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered. And in all of this, Tyrande has a battery of requests I simply do not have the time to deal with. Will you go to her? Her growing army is hard to miss in Meredil.", ["objectivesText"] = "Speak with Tyrande Whisperwind in Meredil.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45265 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
