[44752] = { ["id"] = 44752, ["name"] = "Essence Triangulation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "Vanthir... an example! That certainly explains why Elisande chose to hold him this long. We need to move quickly. I can track him, but I will need to find places where his Arcane Essence is strongest. This will not be an easy feat, not in a city this old, but with any luck there are a few places important enough to him that he left a little bit of himself behind. We should start in the promenade- he often visited it for business.", ["objectivesText"] = "Help Thalyssra collect 3 of Vanthir's Arcane Essences. Progress: Did you find them?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115248, ["x"] = 0.476, ["y"] = 0.789 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115248, ["x"] = 0.476, ["y"] = 0.789 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.789 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44742 }, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44753] = { ["id"] = 44753, ["name"] = "On Public Display", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "Now that I have identified Vanthir's essence from the multitude of Suramar 's citizens, it may be that I can find his exact location. I believe you'll recall a similar ritual with our friend Theryn. Do not worry- there will be less screaming this time. Hopefully. Come. Let us find our missing tavernkeeper.", ["objectivesText"] = "Help Thalyssra complete the Scrying Ritual. Progress: I need to maintain complete focus.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115248, ["x"] = 0.476, ["y"] = 0.789 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115557, ["x"] = 0.522, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.789 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44752 }, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44754] = { ["id"] = 44754, ["name"] = "Waxing Crescent", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "His captor is familiar to me. He is one of Aluriel's lieutenants and a skilled spell-fencer at that. You will need Silgryn's help to retrieve the key to Vanthir 's prison. Our friend's life hangs in the balance. Even if we manage to wrestle him from the executioner's grasp, he may well Wither before we can act. I need you to take an Arcan'dor fruit to him. They are precious, and few, but for Vanthir this is the only chance he has. Go quickly, and good luck.", ["objectivesText"] = "Rescue Vanthir and give him an Arcan'dor fruit. Progress: < Vanthir shudders violently and stares blankly ahead. He does not seem to be aware of your presence.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142261, 142281 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115557, ["x"] = 0.522, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115604, ["x"] = 0.488, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44753 }, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44756] = { ["id"] = 44756, ["name"] = "Sign of the Dusk Lily", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "Simply... astounding. I have not felt this clear of mind in so long. I am still weak... I need to rest. But first... < Vanthir gestures to the top of his cage with a trembling hand.> Show them that the Dusk Lily triumphs this day.", ["objectivesText"] = "Place a Dusk Lily Sigil above Vanthir 's Cage.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143487, 247842, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115604, ["x"] = 0.488, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44754 }, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44758] = { ["id"] = 44758, ["name"] = "What's the Cache?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 45833, 46322 }, ["description"] = "We're here for a cache of gunpowder. It seems to have been infused with some sort of fel power... it's extremely reactive. One of the leaders of the pirate forces here currently has it. Master Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", ["objectivesText"] = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache . Progress: Did you get the gunpowder?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142116 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 45833 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
