[44764] = { ["id"] = 44764, ["name"] = "Demon in Disguise", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["series"] = { 44733 }, ["description"] = "While you were... working your magic on that demon, I was able to make headway in distilling the corrupted essences down to a simpler, more manageable form. I've asked Khadgar to provide you with the concoction once he's had a look, but I must remind you - these essences are quite potent, often dangerous if not handled with the utmost of care. Speak with Khadgar when you are ready to begin.", ["objectivesText"] = "Speak with Archmage Khadgar in Deadwind Pass .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["sourceQuests"] = { 44686 }, ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 10, ["flags"] = 0 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead" },
