[44766] = { ["id"] = 44766, ["name"] = "Backup Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45207, 45437, 46335, 46338, 46705 }, ["description"] = "Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage. It is imperative to come up with an interim plan, and quickly! Archmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?", ["objectivesText"] = "Speak with Archmage Kalec .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.722, ["y"] = 0.629, ["mapID"] = 735, ["npcID"] = 118242 } }, ["ends"] = { { ["x"] = 0.722, ["y"] = 0.629, ["mapID"] = 735, ["npcID"] = 118242 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.722, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 118242, ["questTurnInID"] = 118242, ["questType"] = "standard", ["sourceQuests"] = { 45437 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[44767] = { ["id"] = 44767, ["name"] = "A Celestial Invitation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 44767 }, ["description"] = "Greetings, mortal. For many years I have continued my observation of this planet. The halls of Ulduar have been hollow and silent, save for the occasional clattering whisper from the darkness. I grew so very bored of it! Thus, I have taken up this \"pet battling\" you seem so fond of. Truly, an amusing pastime that will sustain my mind for many centuries! I have been amassing my collection, scouring the stars for tiny beings of cosmic power. Come, let us do battle once more!", ["objectivesText"] = "Defeat Algalon the Observer in a pet battle. Progress: Greetings, mortal. Do you wish to engage in a battle of the tiny minions?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 142100, 142210 }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 115307, ["x"] = 0.414667, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.414667, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["startItems"] = { 142210 } },
[44768] = { ["id"] = 44768, ["name"] = "Nyell's Workshop", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 691, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 46339, 46345 }, ["description"] = "From what I've overheard, this is Master Artificer Nyell 's workshop. His skills in construct creation are unparalleled! What a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice. If you are lucky, he might even have a spare shield generator sitting around.", ["objectivesText"] = "Kill Master Artificer Nyell . Progress: Were you successful?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142212 }, ["starts"] = { { ["x"] = 0.471, ["y"] = 0.235, ["mapID"] = 691, ["npcID"] = 116321 } }, ["ends"] = { { ["x"] = 0.471, ["y"] = 0.235, ["mapID"] = 691, ["npcID"] = 116321 } }, ["coords"] = { ["mapID"] = 691, ["x"] = 0.471, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questGiverID"] = 116321, ["questTurnInID"] = 116321, ["questType"] = "standard", ["sourceQuests"] = { 46345 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 691 },
