[44770] = { ["id"] = 44770, ["name"] = "Secrets of the Shal'dorei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 691, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 46351 }, ["description"] = "This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? Perhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind... Please gather whatever you can.", ["objectivesText"] = "Gather 8 Ancient Shal'dorei Scrolls . Progress: Have you found some scrolls?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142211 }, ["starts"] = { { ["x"] = 0.471, ["y"] = 0.235, ["mapID"] = 691, ["npcID"] = 116321 } }, ["ends"] = { { ["x"] = 0.471, ["y"] = 0.235, ["mapID"] = 691, ["npcID"] = 116321 } }, ["coords"] = { ["mapID"] = 691, ["x"] = 0.471, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questGiverID"] = 116321, ["questTurnInID"] = 116321, ["questType"] = "standard", ["sourceQuests"] = { 46345 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 691 },
[44771] = { ["id"] = 44771, ["name"] = "A Threat Rises", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44720, 44721, 44729, 44771 }, ["series"] = { 44720, 44721, 44729, 44868 }, ["description"] = "It is time I told you another tale. While you listen, would you be so kind as to pour me some grog? I've grown a terrible thirst. The keg is very old and the tap is a bit slow.", ["objectivesText"] = "Pour Havi some grog. Progress: I've told you my tale, but did you bring the grog?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 44720 }, ["questLines"] = { { ["id"] = 280, ["name"] = "Deemed Worthy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[44775] = { ["id"] = 44775, ["name"] = "The Peak of Bones", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 634, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 44783 }, ["description"] = "While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers. I sent Minerva to Thorim's Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets. Speak to Grimwing for a flight to the mountain, then Minerva will fill you in.", ["objectivesText"] = "Speak to Grimwing for a flight to Thorim's Peak, then meet Minerva.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.27, ["y"] = 0.289, ["mapID"] = 647, ["npcID"] = 113695 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 115360, ["x"] = 0.512, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7543 } }, ["questGiverID"] = 113695, ["questType"] = "standard", ["sourceQuests"] = { 45331 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
