[44781] = { ["id"] = 44781, ["name"] = "The Council's Call", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44781 }, ["series"] = { 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "<The Council of Six has sought your aid against a 'great threat'.> <If they have turned their focus on something outside of the demon hordes pouring out of the Tomb of Sargeras, it must be truly dangerous.> <But how does the object you found on the Broken Shore fit into all of this? You know only that the Council awaits at the Violet Citadel.>", ["objectivesText"] = "Seek out the Council of Six in the Violet Citadel.", ["rewardGold"] = 19400, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44782] = { ["id"] = 44782, ["name"] = "Away From Prying Eyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44782, 44821, 46765, 47000 }, ["series"] = { 44781, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "Wars are not won solely with armies charging bravely across the battlefield, <class>t. Sometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - <Khadgar furrows his brow slightly.> We should really discuss this somewhere a tad more private. Let's move up to the Purple Parlor, shall we?", ["objectivesText"] = "Join the Council of Six in the Purple Parlor above the Violet Citadel. Progress: We should discuss this matter further in the Purple Parlor just above us.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.288, ["y"] = 0.484, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.288, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 47000 }, ["questLines"] = { { ["id"] = 278, ["name"] = "The Council's Challenge", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44783] = { ["id"] = 44783, ["name"] = "From Bones They Rise", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 634, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 44775 }, ["description"] = "Alright, the job is to get the broodmother under our control. But hear me out. A few more drakes would be a boon, right? While we're here, why don't we use our awesome power over undeath to raise some of her brood as well? Although the peak has claimed their corpses for the ice, I'm sure the embrace of undeath will be much more welcoming. We must find their frozen corpses and breathe your will into them.", ["objectivesText"] = "Revive 4 Deceased Thorignir in Thorim's Peak. Progress: Have you granted the drakes their unbirth?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.843, ["mapID"] = 634, ["npcID"] = 116737 } }, ["ends"] = { { ["x"] = 0.513, ["y"] = 0.843, ["mapID"] = 634, ["npcID"] = 116737 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.513, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 116737, ["questTurnInID"] = 116737, ["questType"] = "standard", ["sourceQuests"] = { 44775 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
