[44787] = { ["id"] = 44787, ["name"] = "The Bonemother", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 647, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 46305 }, ["description"] = "It's time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first. Remember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.", ["objectivesText"] = "Light Thorim's Beacon at Thorim's Peak to raise Daumyr . Defeat her and raise her from death.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 116737 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 116737, ["questType"] = "standard", ["sourceQuests"] = { 44783, 46305 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
