[44803] = { ["id"] = 44803, ["name"] = "Return to Karazhan: Master of the House", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 44803 }, ["series"] = { 44865 }, ["description"] = "Inside the pocket watch is a worn note. \"The next affair will take place in Morgan's Plot, it will cause quite a stir! The following guests will be in attendance: Lord Ference, his preferred vintage is red. Baroness Millstipe, she will only attend on the promise of cheese. Strange woman. Baron Dreuger, a ravenous soul, any well spiced meat should keep him happy. As always, I shall ring the bell should I need you. - Medivh\"", ["objectivesText"] = "Collect the listed items and bring them to the cemetery outside Karazhan. Progress: What do you have there?", ["rewardGold"] = 50550, ["rewardXP"] = 1535, ["rewardItems"] = { 133564, 142209, 142246, 142248, 142249, 142275 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 115551, ["x"] = 0.398, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 8443 } }, ["questType"] = "standard", ["startItems"] = { 142246 } },
