[44821] = { ["id"] = 44821, ["name"] = "In Dire Need", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44782, 44821, 46765, 47000 }, ["series"] = { 44781, 44782, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "The ill tidings you bear only increase the concerns the Council has been having. I know you have your hands full with the Tomb of Sargeras. Make no mistake, the battle for the tomb remains our top priority--but we must not think the Legion foolish enough to rely on brute force alone. They are far more cunning than that. Please, hear us out.", ["objectivesText"] = "Hear out the Council of Six in the Purple Parlor.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.225, ["y"] = 0.392, ["mapID"] = 627, ["npcID"] = 115465 } }, ["ends"] = { { ["x"] = 0.225, ["y"] = 0.392, ["mapID"] = 627, ["npcID"] = 115465 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.225, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 115465, ["questTurnInID"] = 115465, ["questType"] = "standard", ["sourceQuests"] = { 44782 }, ["questLines"] = { { ["id"] = 278, ["name"] = "The Council's Challenge", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[44822] = { ["id"] = 44822, ["name"] = "Temporal Investigations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["description"] = "I knew the shal'dorei dabbled in time magic, but this is simply incredible... Elisande stopped time on our entire army! Come, let us investigate. Perhaps there is a way to break the spell - or at least discover how it is being maintained.", ["objectivesText"] = "Investigate Elisande's time spell with Khadgar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.692667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44736 }, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
