[44825] = { ["id"] = 44825, ["name"] = "Wisp in the Willows", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 44825 }, ["description"] = "Wisps are the spirits of our Night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life. You should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.", ["objectivesText"] = "Guide the Wisp through the Hidden Pools to grow 8 trees.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["rewardItems"] = { 130127 }, ["starts"] = { { ["x"] = 0.543, ["y"] = 0.683, ["mapID"] = 641, ["npcID"] = 95202 } }, ["ends"] = { { ["x"] = 0.543, ["y"] = 0.683, ["mapID"] = 641, ["npcID"] = 95202 } }, ["coords"] = { ["mapID"] = 641, ["x"] = 0.543, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 95202, ["questTurnInID"] = 95202, ["questType"] = "standard", ["sourceQuests"] = { 38384 } },
[44827] = { ["id"] = 44827, ["name"] = "Citizens' Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44858, 44859, 44860, 44861, 44862 }, ["description"] = "I can barely get these civilians to stand in a straight line. They are untrained, undisciplined, and underarmed. Still, they need to be ready for the real battle. Khadgar suggested we try some field training at the ruins of Black Rook Hold in Val'sharah. The risen forces of Lord Ravencrest apparently remember how to fight. Go, hero, and I will send some trainees to support you.", ["objectivesText"] = "Defeat 20 of Ravencrest's forces at Black Rook Hold in Val'sharah.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140192, 141605 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["sourceQuests"] = { 44861, 44862 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44829] = { ["id"] = 44829, ["name"] = "We Need Weapons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["description"] = "So many of the rebels want to help in the coming battle. Our people have the will, they lack only the means. They need weapons. From what Khadgar has told me, the fortress of Black Rook has plenty of munitions we could use. Travel to the fortress and place these beacons on some weapon caches there. Once placed, I can teleport them back.", ["objectivesText"] = "Recover 3 Weapon Caches at Black Rook Hold in Val'sharah. Progress: How goes the search?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140192, 141605, 143744 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115342, ["x"] = 0.475333, ["y"] = 0.620667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115342, ["x"] = 0.475333, ["y"] = 0.620667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.620667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44861, 44862 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44830] = { ["id"] = 44830, ["name"] = "Learning From the Dead", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44790 }, ["description"] = "I heard you were traveling to Black Rook Hold. It was once home to the legendary Lord Ravencrest, a brilliant tactician. His knowledge may be exactly what we need to give us an edge against the Duskwatch. While you are at the Rook, keep your eyes peeled for any books that might have survived the ages that outline the Ravencrest's strategems.", ["objectivesText"] = "Recover 5 Books of Tactics from Black Rook Hold in Val'sharah. Progress: How goes the search?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140192, 141605, 142258, 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115499, ["x"] = 0.398, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115499, ["x"] = 0.398, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44861, 44862 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44831] = { ["id"] = 44831, ["name"] = "Taking a Promenade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "These people are foreign to us, despite our common heritage. They have changed much in the years they have been cloistered away. We need to learn more about them, what they are capable of. We dispatched one of our scouts to infiltrate the Promenade and assess the defenses. The blood elves did the same, although I doubt their ability to be discreet. Both are long past due for reporting back to us. Find them and make sure they are safe or at least did not die in vain.", ["objectivesText"] = "Locate the scouts in the Promenade.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114963, ["x"] = 0.4525, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114963, ["x"] = 0.4525, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40391 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44832] = { ["id"] = 44832, ["name"] = "Scouting the Breach", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44833, 45209 }, ["description"] = "If Ly'leth's information is accurate, there is a breach in the Sanctum of Order that could be our only way into the Nighthold. No doubt they have magically sealed it - take Valtrois and protect her while she examines the seal. She is an exceptional talent, and I have total faith in her ability to break whatever enchantment they have cooked up. Valtrois has her own methods of getting into the city and will meet you inside the Sanctum of Order.", ["objectivesText"] = "Aid Valtrois underneath the Sanctum of Order in Suramar City.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115524, ["x"] = 0.433, ["y"] = 0.603 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45209 }, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44833] = { ["id"] = 44833, ["name"] = "The Seal's Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44832, 45209 }, ["description"] = "The Nightwell is so overloaded that they could not spare anything for this seal. Instead, they are borrowing power from the ley lines. I have traced one of their power sources to Kel'balor. We should head there immediately so I can determine how best to disable this barrier. Yes of course I said \"we.\" Surely you do not expect me to go without my bodyguard, do you? I shall meet you there!", ["objectivesText"] = "Investigate the ley line device at Kel'balor in the Crimson Thicket. Progress: Have you and Valtrois learned anything about the barrier?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143745, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115524, ["x"] = 0.433, ["y"] = 0.603 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.433, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44832 }, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44834] = { ["id"] = 44834, ["name"] = "Nullified", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["series"] = { 44842 }, ["description"] = "The magus in charge of the defenses here is powerful. Perhaps too strong, even for the both of us. Fortunately, the sin'dorei know a thing or two about magic. The mage's barrier is strong, but we are clever. He has somehow channeled enough energy into his staff to power another set of defense portals, but he has left it out of his sight. Bring me the staff and an energy source from one of those constructs. I should be able to create just the thing we need to take that shield out.", ["objectivesText"] = "Obtain the Charged Arcshaper Staff and a Volatile Construct Core for Sendath. Progress: It is really child's play when you consider the magical weaves. I can see the flaws with just a few minutes of study.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142244, 142245 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40391, 40632 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44842] = { ["id"] = 44842, ["name"] = "Shield, Meet Spell", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["series"] = { 44834 }, ["description"] = "There you have it, one arcane nullifier ! Using their weapon and magical signatures to cloak the spell, it should tear apart the shield as good as any spellbreaker would. Go teach that amateur spellslinger what it means to wage war against the sin'dorei!", ["objectivesText"] = "Use the Arcane Nullifier to defeat Arcshaper Thorendis . Progress: The nullifier should do most of the work for you. Just watch out for his offensive magic!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142260, 143486 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44834 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44843] = { ["id"] = 44843, ["name"] = "Crystal Clearing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "This portal is a problem. With it they can summon countless reserves. The crystals nearby seem to be powering the gate. If we destroy those, we can set them back significantly.", ["objectivesText"] = "Destroy 4 Portal Crystals .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40391, 40632 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44844] = { ["id"] = 44844, ["name"] = "Powering Down the Portal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "Destroying the crystals will stop them temporarily, but it will be meaningless if we do not deal with the person controlling the portal itself. I heard their overseer, Ingra, shouting orders for more power so that she could bring the stronger Legion lieutenants through the gate. We must stop her to truly seal the portal for good.", ["objectivesText"] = "Slay Overseer Ingra .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143742 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40391, 40632 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44845] = { ["id"] = 44845, ["name"] = "Break An Arm", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "The insurgents you marshaled gave me some bad news, <name>. The arcanists loyal to Elisande have reactivated the Arm of the Magistrix . The most powerful construct ever attempted, it raged out of control and decimated an entire district before it was disabled. Truly they must be desperate to turn it against us. The scouts have spotted it in the Crimson Thicket to the north. We cannot allow it to reach full power if we are to succeed.", ["objectivesText"] = "Defeat the Arm of the Magistrix . Progress: We must destroy the Arm!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143498 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.408667, ["y"] = 0.525333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["sourceQuests"] = { 41607, 41916, 43810, 43812, 44831 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
