[44849] = { ["id"] = 44849, ["name"] = "Recruitment Drive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 45834, 46173 }, ["description"] = "Helya's kvaldir have been raiding Azeroth's coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. Now that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us! Go to Helheim with Aerylia . I assure you she will bring you back safely.", ["objectivesText"] = "Ask Aerylia to escort you to Helheim.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 46173 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[44850] = { ["id"] = 44850, ["name"] = "Arming the Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["description"] = "The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. The kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. Confiscate whatever you can!", ["objectivesText"] = "Search stolen crates for 10 stolen blades and 10 stolen shields. Progress: Did you find any supplies we can use in Helheim <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142285, 142312 }, ["starts"] = { { ["x"] = 0.343, ["y"] = 0.285, ["mapID"] = 649, ["npcID"] = 116193 } }, ["ends"] = { { ["x"] = 0.343, ["y"] = 0.285, ["mapID"] = 649, ["npcID"] = 116193 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.343, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 116193, ["questTurnInID"] = 116193, ["questType"] = "standard", ["sourceQuests"] = { 44849 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
