[44858] = { ["id"] = 44858, ["name"] = "Trolling Them", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44861, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44859, 44860, 44861, 44862 }, ["description"] = "My army is disciplined, and they will follow my order not to engage the Sin'dorei in combat unless I give the command. However, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults. Please, $p, we need someone both armies respect to collect these items before fighting breaks out.", ["objectivesText"] = "Remove insulting items from the elven war camps. Progress: We elves are long lived, but not as long lived as our prejudices it would seem.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["sourceQuests"] = { 44743 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44859] = { ["id"] = 44859, ["name"] = "Liadrin's Command", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44790, 44827, 44829, 44830, 44859, 44860, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44860, 44861, 44862 }, ["description"] = "Shal'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered. And in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with. Will you go to her? Her growing army is hard to miss in Meredil.", ["objectivesText"] = "Speak with Lady Liadrin in Meredil.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45265 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44860] = { ["id"] = 44860, ["name"] = "Trolling Them", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44790, 44827, 44829, 44830, 44859, 44860, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44859, 44861, 44862 }, ["description"] = "My army is disciplined, and they will follow my order not to engage the kaldorei in combat unless I give the command. However, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults. Please, $p, we need someone both armies respect to collect these items before fighting breaks out.", ["objectivesText"] = "Remove insulting items from the elven war camps.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.452667, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["sourceQuests"] = { 44859 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44861] = { ["id"] = 44861, ["name"] = "Arming the Rebels", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44861, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44859, 44860, 44862 }, ["description"] = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages. Victoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand. Go to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.", ["objectivesText"] = "Speak with Victoire in Meredil.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["sourceQuests"] = { 44858, 44928 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44862] = { ["id"] = 44862, ["name"] = "Arming the Rebels", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44790, 44827, 44829, 44830, 44859, 44860, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44859, 44860, 44861 }, ["description"] = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages. Victoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand. Go to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.", ["objectivesText"] = "Speak with Victoire in Meredil.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.452667, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["sourceQuests"] = { 44860, 44928 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44863] = { ["id"] = 44863, ["name"] = "Clearing the Air", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 44863 }, ["description"] = "Ancient weapons require ancient offerings to regain the knowledge on how to construct them. If you wish to learn how weapons forged from air are crafted, then you must first battle with beings born from it. Bring me their cores and I will gift you the knowledge you seek.", ["objectivesText"] = "Recover a Cardinal Sky Core , a Cardinal Storm Core , and a Cardinal Wind Core for Lunelli . Bring them back to her in Shattrath when you have all three. Progress: Be mindful of their attacks, for with air, you never know it's there until you feel it move across your skin.", ["rewardXP"] = 345, ["rewardItems"] = { 65891, 134021, 142267, 142268, 142269, 142270, 142271, 142272, 142279, 142282, 142283 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 115546, ["x"] = 0.64, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 115546, ["x"] = 0.64, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
