[44869] = { ["id"] = 44869, ["name"] = "Talon Terror", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand. I cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.", ["objectivesText"] = "Use the portal in the Dreamway to meet Thisalee at the Shrine of Aviana in Mount Hyjal.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.443, ["y"] = 0.515, ["mapID"] = 747, ["npcID"] = 106299 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 7846 } }, ["questGiverID"] = 106299, ["questType"] = "standard", ["sourceQuests"] = { 43409, 47137 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[44870] = { ["id"] = 44870, ["name"] = "Mouths to Feed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44873 }, ["description"] = "We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem. The arcan'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over. Valtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.", ["objectivesText"] = "Speak with Arcanist Valtrois in Shal'Aran.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45265 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44873] = { ["id"] = 44873, ["name"] = "Oculeth Ex Machina", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44870 }, ["description"] = "I have a plan to feed Shal'Aran. Now that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal'Aran. Oculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?", ["objectivesText"] = "Speak with Oculeth and teleport to Azsuna.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44870 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[44874] = { ["id"] = 44874, ["name"] = "Unbeleyvable", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44875 }, ["description"] = "Back to the task at hand! Take these ley line taps . We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where. Your friend has agreed to... \"supervise\" us. Let us hope she just stays out of the way while the professionals take care of this.", ["objectivesText"] = "Assist Arcanist Valtrois with placing ley line taps . Progress: This ley line energy will not move itself. We must give it encouragement.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.142 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 44873 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[44875] = { ["id"] = 44875, ["name"] = "The Art of Flow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44874 }, ["description"] = "All done, <name>! We have but one more step and Shal'Aran will have all the mana it needs. Now that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy. I must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process. Speak to me when you are ready.", ["objectivesText"] = "Protect Arcanist Valtrois while she completes the ritual. Progress: This ritual will shake the pool of energy loose, allowing it to flow through the ley line unimpeded.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143743 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.142 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 44874 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[44876] = { ["id"] = 44876, ["name"] = "A Dance With Dragons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["description"] = "I must say I am impressed, <name>. You and your friend were able to fix a ley line, and you are not even dragons! You both seem exhausted by this ordeal. Allow me to help you get back home.", ["objectivesText"] = "Speak with Stellagosa to ride back to Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115701, ["x"] = 0.596, ["y"] = 0.134667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.134667 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 44875 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44877] = { ["id"] = 44877, ["name"] = "Attack on the Roost", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "Skylord Shadegrove has been leading the defense of the shrine, but I think he's starting to lose hope. Clearly he needs some more firepower behind him! Let's take out these demons and fend off the attack. They'll never see it coming!", ["objectivesText"] = "Kill 15 Legion invaders. Progress: I love the feeling of my knife in a demon's back!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questTurnInID"] = 115802, ["questType"] = "standard", ["sourceQuests"] = { 44869 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
