[44885] = { ["id"] = 44885, ["name"] = "Shipwrecked Survivors", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 44885 }, ["description"] = "It appears that we have allies here on the Broken Shore. A small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks. Make your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.", ["objectivesText"] = "Speak with First Sergeant Steelfang.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44888] = { ["id"] = 44888, ["name"] = "Aviana's Grace", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she's got eyes everywhere. Let's go ask her. We should be able to contact her in the back room.", ["objectivesText"] = "Contact Aviana in the Shrine of Aviana .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.409, ["y"] = 0.426, ["mapID"] = 198, ["npcID"] = 115802 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 115749, ["x"] = 0.442, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questGiverID"] = 115802, ["questType"] = "standard", ["sourceQuests"] = { 44877, 45532 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[44889] = { ["id"] = 44889, ["name"] = "Resource Management", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 45118, 45128, 45634 }, ["description"] = "Now that you possess Helya's Horn, the kvaldir are yours to command. We may as well put them to good use for a change. I've dispatched my Val'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated. Aerylia will send you there when you are ready to leave.", ["objectivesText"] = "Talk to Aerylia to travel to the Path of Suffering on the Broken Shore.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questType"] = "standard", ["sourceQuests"] = { 45128 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
