[44914] = { ["id"] = 44914, ["name"] = "Arms: The Thieving Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177 }, ["series"] = { 47032 }, ["description"] = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him. Fortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem. I'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to. Specialization: Arms Warrior", ["objectivesText"] = "Travel to Xylem's Tower within Bear's Head in Azshara.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.23, ["y"] = 0.406, ["mapID"] = 627, ["npcID"] = 105081 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 7502 } }, ["questGiverID"] = 105081, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47032 }, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76 },
[44915] = { ["id"] = 44915, ["name"] = "Professionally Good Looking", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["description"] = "The archmage has recently locked himself away in his tower. If you wish to enter, you'll need help from some of his apprentices. I'm afraid you won't get it dressed like that. Xylem has a thing for... outfits, and his apprentices use them to show rank. If you wish his apprentices to help you, you'll need to appear their superior. Such is their desire to impress the archmage, many of his apprentices will battle each other for the best pieces. I think you know where this is going.", ["objectivesText"] = "Collect the Fanciful Hat , Well-Tailored Robes , and Magnificent Mantle from Raethas Dawnseer , Lobos and Phloem in Azshara. Progress: Feeling stylish?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142365, 142372, 142374 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["sourceQuests"] = { 44914, 47043, 47046, 47047, 47048 }, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76 },
[44917] = { ["id"] = 44917, ["name"] = "Return to Karazhan: The Tower of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 739, ["storyline"] = { 44917 }, ["description"] = "Your champions discovered that the area surrounding Karazhan is under an invasion from the Legion. This does not bode well. Climb the tower, and defeat all in your path.", ["objectivesText"] = "Defeat Viz'aduum the Watcher in Karazhan. Progress: How are you finding the challenges of Karazhan?", ["rewardItems"] = { 142340, 142342 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 142340 } },
[44918] = { ["id"] = 44918, ["name"] = "A Message From Our Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 44919, 45268, 45285 }, ["description"] = "<name>! The messages from Ly'leth we traced throughout the Terrace - we could not have known at the time, but somebody was watching. This crystal was delivered by a courier early this morning. <Pointing to the crystal by her side.> I am afraid the message contained within is not for the faint of heart. It has not been shown to anyone else, but you deserve to see it for all you have done for us.", ["objectivesText"] = "Listen to Andaris's Message in Shal'Aran. Progress: We have no time to waste.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45268 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44919] = { ["id"] = 44919, ["name"] = "A Challenge From Our Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 44918, 45268, 45285 }, ["description"] = "Make no mistake. This message cannot be taken lightly. Any threat made against our people will be dealt with swiftly. We must travel to the estate at once to discover what has become of Ly'leth.", ["objectivesText"] = "Meet Andaris at the Lunastre Estate in Suramar City.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44918 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44920] = { ["id"] = 44920, ["name"] = "Order of Incantations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["series"] = { 44924 }, ["description"] = "The barrier shielding the tower can only be opened by activating the imbued gems in the correct order. The order is only known to Xylem and his inner circle of apprentices. No others have yet been able to decipher the code, and mistakes are met with deadly consequences. The aspiring apprentices spend a lot of their time around the tower. Some may have seen or heard something that might point to a solution. Let us hope, for your sake, their information proves valuable.", ["objectivesText"] = "Speak with Xylem's apprentices in Bear's Head to decipher the code to open the barrier to his tower.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questTurnInID"] = 115791, ["questType"] = "standard", ["sourceQuests"] = { 44915 }, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76 },
[44921] = { ["id"] = 44921, ["name"] = "Lone Wolf", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "My eyes and ears fly across Azeroth, bringing me back news of many things. My ally Goldrinn took to the barrows of Moonglade in mourning upon the death of Varian Wrynn. He has been untouched in the dream... until now. Demons have been seen invading the very same barrows, killing many more of our mortal druids in the process. You must go. Save Goldrinn, avenge our people! Take my hatchling Thisalee with you. Her tenacity and bloodlust is welcome in my clutch. You shall have my aid.", ["objectivesText"] = "Meet Thisalee Crow in Moonglade.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146708 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 115749, ["x"] = 0.442, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 80, 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 44888 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["db2QuestSortName"] = "Engine of Innovation" },
[44922] = { ["id"] = 44922, ["name"] = "Inside the Winter Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44922 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44940 }, ["description"] = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top. According to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", ["objectivesText"] = "Grapple across from the tower and climb to the top of the mountain path.", ["rewardGold"] = 283700, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
