[44924] = { ["id"] = 44924, ["name"] = "The Archmage Accosted", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["series"] = { 44920 }, ["description"] = "With the barrier dispelled, Archmage Xylem is finally within reach! Hopefully he'll be cooperative in returning the Iris...", ["objectivesText"] = "Confront Archmage Xylem.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 116048, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["sourceQuests"] = { 44920 }, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76 },
[44925] = { ["id"] = 44925, ["name"] = "Closing the Eye", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44925 }, ["description"] = "We have received reports from the apprentices at Xylem's Tower that they've been able to use the remant of Xylem's portal to pinpoint his location. We have orders from the Council of Six to open a portal directly to him, though whatever magic he's channeling on the other end is powerful enough to allow us to only keep it open for a brief window. The apprentice, Joanna asked I give you this message before you proceed. Speak to me when you're ready.", ["objectivesText"] = "Closing the Eye (Archmage Xylem) is a Mage Tower DPS Challenge, available during Legion Timewalking. The following specs can complete this challenge: Havoc Demon Hunters, Frost Death Knights, Arms Warriors, Survival Hunters, and Subtlety Rogues. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our Closing the Eye Mage Tower Strategy guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Speak with War Councilor Victoria to be teleported to Archmage Xylem 's location and defeat him.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 120257, 127848, 127849, 132366, 132376, 132444, 132452, 132458, 132466, 133572, 133576, 133976, 136975, 137014, 137021, 137038, 137052, 137060, 137061, 137064, 137069, 137077, 137087, 137090, 137101, 137107, 137459, 140587, 140796, 140797, 140806, 140808, 141446, 142117, 142406, 142502, 142508, 143728, 144236, 144259, 144279, 144361, 153023 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 117252, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 76, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[44926] = { ["id"] = 44926, ["name"] = "A Familiar Axe to Grind", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 44926 }, ["series"] = { 44927 }, ["description"] = "The construction of this blade feels familiar, but you can't quite recall where you may have seen something like it before. Perhaps someone at Chiselgrip might know more about its construction.", ["objectivesText"] = "Show the axe blade to Hoddruc Bladebender at Chiselgrip. Provided item:", ["rewardGold"] = 31500, ["rewardXP"] = 260, ["rewardItems"] = { 142344 }, ["starts"] = { { ["x"] = 0.468, ["y"] = 0.446, ["mapID"] = 36, ["npcID"] = 115805 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 115805, ["x"] = 0.468, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questGiverID"] = 115805, ["questType"] = "standard", ["startItems"] = { 142344 } },
[44927] = { ["id"] = 44927, ["name"] = "Worth Its Weight in Steel", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 44927 }, ["series"] = { 44926 }, ["description"] = "Listen, ye seem like one who may be interested in getting a copy of those axe plans. Could probably make a pretty penny at the auction house on it. But I can't just hand 'em over to ya, <lad/lass>. Not fer free. That axe blade ye brought me, I could use more of those. Good steel in those blades. Don't worry, <lad/lass>, I just need a few... What do ye say?", ["objectivesText"] = "Gather 30 Axe Blades from orcs and ogres around the Burning Steppes. Return them to Hoddruc in Chiselgrip when you've collected them all. Progress: You see, I've got a shipment ta fill and it's been slim pickin' round these parts for good metal. Those blades are just what I'm lookin' for.", ["rewardXP"] = 260, ["rewardItems"] = { 142344, 142345, 142346 }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 115805, ["x"] = 0.468, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 115805, ["x"] = 0.468, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["sourceQuests"] = { 44926 } },
[44928] = { ["id"] = 44928, ["name"] = "Something's Not Quite Right...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["description"] = "Something is troubling me, champion. Beyond these simple japes, the Kirin Tor has had to break up a few fights between the elves. I am worried something - or someone - might be influencing them. Your disguise was made by the nightborne, yes? It is not unreasonable to assume they can do something similar. Fortunately, Thalyssra has told me much about how the illusion works, and I believe this crystal can remove their disguise. Why don't you check the camps, just to be safe?", ["objectivesText"] = "Remove the disguise of 5 Nightborne Infiltrators. Progress: Were you able to find the instigators?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142375, 143499 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.5235 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44743, 44859 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44930] = { ["id"] = 44930, ["name"] = "Deadmines: Sea'in Red", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1581, ["storyline"] = { 44930 }, ["description"] = "Arr, finally! I been stuck up here f'years with naught company but me own thoughts. Tis good to clap me eyes on another swashbuckling soul. Are ye up for a plot of revenge and skullduggery? These meddlin' Defias thugs murdered me and me crew years ago before they took over this cave. I propose a series of counter-murders to bring about balance! Bring me proof ye've dealt with enough of the thieves to clog a bilge pump!", ["objectivesText"] = "Collect 100 Bloodied Defias Bandanas for Captain Bramblebeard . Progress: Revenge is worth waitin' for. Not that I have much in the way of choice.", ["rewardItems"] = { 8492, 10399, 10400, 10401, 10402, 10403, 142273, 142349 }, ["starts"] = { { ["npcID"] = 115818 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questGiverID"] = 115818, ["questType"] = "standard" },
