[44948] = { ["id"] = 44948, ["name"] = "Raising Your Snowfeather", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44948 }, ["description"] = "<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>", ["objectivesText"] = "Raise your Snowfeather Hatchling to level 25. Progress: Erk?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 128763, 128837, 128839, 128843, 137577, 137578, 137579, 137580 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard" },
[44949] = { ["id"] = 44949, ["name"] = "The Smell of Humans", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44949 }, ["description"] = "<You've noticed that your snowfeather hatchling shakes whenever humans are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of humans, so that it can get used to the smell.>", ["objectivesText"] = "Take your Snowfeather Hatchling to the Gilded Rose in Stormwind. Progress: <Your snowfeather hatchling looks at you uncertainly.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44948 } },
[44950] = { ["id"] = 44950, ["name"] = "Hunting Lesson: Northern Hawk Owls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44950 }, ["description"] = "<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> <It seems you will need to take your falcosaur out hunting.>", ["objectivesText"] = "Defeat 3 Northern Hawk Owls in Highmountain with your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks ready for some exercise.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44949, 44971 } },
[44952] = { ["id"] = 44952, ["name"] = "Blackrock Depths: Jewel of the Depths", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 44952 }, ["description"] = "Welcome to Everlook. Could I interest you in a new weapon of sorts? You know, I'm not just into selling weapons of mass dismemberment here at the shop. I like rare jewels as well. Perhaps you and I can come to an arrangement of sorts in procuring a jewel I've had my eye on getting for quite some time. I have some great blacksmithing plans here you might be interested in, you know, in trade for your services. Now, onto the details...", ["objectivesText"] = "Travel to Blackrock Depths and obtain a Core of Bael'Gar , Core of Roccor , Essence of Incendius , and Essence of Magmus . Once you have all four items, combine them at the Black Forge near the entrance to Molten Core at the bottom of Blackrock Depths and bring the Blackrock Ruby back to Wixxrak in Everlook. Progress: This ain't no easy task. It's why the jewel's so rare, you see?", ["rewardXP"] = 2765, ["rewardItems"] = { 12821, 142351, 142352, 142353, 142354, 142355, 142357 }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 11184, ["x"] = 0.602, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 11184, ["x"] = 0.602, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Suffusion Camps" },
[44953] = { ["id"] = 44953, ["name"] = "Allies in Highmountain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44953 }, ["description"] = "<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> <The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.> <Show your falcosaur that you and it can work alongside the Highmountain Tribes.>", ["objectivesText"] = "Complete 5 World Quests in Highmountain with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling isn't at all sure about this.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44950 } },
[44954] = { ["id"] = 44954, ["name"] = "Snowfeather Team Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44954 }, ["description"] = "<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!> <To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests in Broken Isles with your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks ready for your commands!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44953 } },
[44955] = { ["id"] = 44955, ["name"] = "Visitor in Shal'Aran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["description"] = "Someone came to Shal'Aran while you were in the City. She asked for you specifically. I did not recognize her face, nor her voice, but she seemed trustworthy and earnest. She is just outside the cavern. Meet with her and determine her purpose for coming here.", ["objectivesText"] = "Meet the stranger outside Shal'Aran. Progress: What have you learned?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143738, 245558, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 42889 }, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44956] = { ["id"] = 44956, ["name"] = "Deadly Prey", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44956 }, ["description"] = "<After working together on recent pet battles, your snowfeather falcosaur seems much more interested in your combat abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", ["objectivesText"] = "Complete 1 Rare Elite World Quest with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling looks ready to learn!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44954 } },
[44957] = { ["id"] = 44957, ["name"] = "Hunting Lesson: Spiketail Beaver", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44957 }, ["description"] = "<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>", ["objectivesText"] = "Defeat 3 Spiketail Beavers in Highmountain with your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks ready to hunt.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44956 } },
[44958] = { ["id"] = 44958, ["name"] = "The Unfriendly Faction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44958 }, ["description"] = "<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", ["objectivesText"] = "Complete 3 PvP World Quests with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling seems to like the other faction a bit too much.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44957 } },
[44959] = { ["id"] = 44959, ["name"] = "Snowfeather Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44959 }, ["description"] = "<Your snowfeather hatchling keeps getting into your pack and making a mess. It squawks loudly whenever you remove it, and rams you with its head. Maybe you can distract it with a tiny pack of its own?>", ["objectivesText"] = "Buy a Tiny Pack from Susana Averoy in Dalaran for your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks at you inquisitively.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578, 142497, 142501 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44958 } },
[44960] = { ["id"] = 44960, ["name"] = "Hunting Lesson: Mudshell Conch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44960 }, ["description"] = "<Your snowfeather hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the snails of Highmountain.>", ["objectivesText"] = "Defeat 3 Mudshell Conches in Highmountain with your Snowfeather Hatchling and 2 Flying pets. Progress: <Your snowfeather hatchling preens.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44959 } },
[44961] = { ["id"] = 44961, ["name"] = "Teamwork Lesson: Naraxas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44961 }, ["description"] = "<While victorious, your snowfeather hatchling squawked and pecked at its allies during some of those last fights. Showing it a good example of teamwork might help.>", ["objectivesText"] = "Defeat Naraxas in Neltharion's Lair in Highmountain with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling looks to you for guidance.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 89906, 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44960 } },
[44962] = { ["id"] = 44962, ["name"] = "Hunting Lesson: Coralback Fiddler", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44962 }, ["description"] = "<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", ["objectivesText"] = "Defeat 3 Coralback Fiddlers in Highmountain with your Snowfeather Hatchling and 2 Elemental pets. Progress: <Your snowfeather hatchling looks wary of your elemental pets.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44961 } },
[44964] = { ["id"] = 44964, ["name"] = "I'll Just Leave This Here", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44719, 44964, 45269 }, ["description"] = "Valtrois has a plan for the Sanctum's energy barrier. Several key Arcway locations throughout Suramar harness the power necessary for it. These Energy Disruptors she made will remotely break the links simultaneously on activation, causing the barrier to fall. Take these devices and install them at the leylines, then return here for the surprise assault on the Sanctum.", ["objectivesText"] = "Place Energy Disruptors at the energy sources in Teloth'aran, Kel'balor and Elor'shan in Suramar .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143540 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115372, ["x"] = 0.366, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45269 }, ["questLines"] = { { ["id"] = 292, ["name"] = "Breaking the Nighthold", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 292, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[44967] = { ["id"] = 44967, ["name"] = "Teamwork Lesson: Ursoc", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44967 }, ["description"] = "<Your snowfeather hatchling continues to fight with other pets when threatened. It must learn to remain calm under pressure, even when facing great beasts. Showing it an epic example of teamwork against a great beast might help.>", ["objectivesText"] = "Defeat Ursoc in the Emerald Nightmare with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling looks to you for guidance.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44962 } },
[44968] = { ["id"] = 44968, ["name"] = "Snowfeather Team Rumble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44968 }, ["description"] = "<Your snowfeather hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests with your Snowfeather Hatchling and 2 Undead pets. Progress: <Your snowfeather hatchling is ready to go!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 60955, 116804, 137578 }, ["starts"] = { { ["npcID"] = 115784 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115784, ["questType"] = "standard", ["sourceQuests"] = { 44967 } },
