[44976] = { ["id"] = 44976, ["name"] = "Hunting Lesson: Rose Taipan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44976 }, ["description"] = "<Your direbeak hatchling seems to get agitated when you are near other critters, none more so than the rose taipans of Stormheim. It squawks loudly and slams its beak into the dirt whenever one is nearby. It appears to have a primal need for predation.> <It seems you will need to take your falcosaur out hunting.>", ["objectivesText"] = "Defeat 3 Rose Taipans in Stormheim with your Direbeak Hatchling . Progress: <Your direbeak hatchling looks ready for some exercise.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44974, 44975 } },
[44977] = { ["id"] = 44977, ["name"] = "Allies in Stormheim", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44977 }, ["description"] = "<Your direbeak hatchling scratches the ground and stares down a member of the Valarjar more than ten times its size.> <The Valarjar must have seen the falcosaurs as an excellent new source of meat, and begun hunting them immediately. Though a new species to the Broken Isles, it already fears the inhabitants of Stormheim.> <Show your falcosaur that you and it can work alongside the Valarjar.>", ["objectivesText"] = "Complete 5 World Quests in Stormheim with your Direbeak Hatchling out. Progress: <Your direbeak hatchling isn't at all sure about this.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44976 } },
[44978] = { ["id"] = 44978, ["name"] = "Direbeak Team Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44978 }, ["description"] = "<Your direbeak hatchling bites you. It appears to want to do something together as a team!> <To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests in Broken Isles with your Direbeak Hatchling . Progress: <Your direbeak hatchling looks ready for your commands!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44977 } },
[44979] = { ["id"] = 44979, ["name"] = "Dire Prey", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44979 }, ["description"] = "<Your direbeak falcosaur nearly trips you the next time you enter combat. It is eager to learn more about how to defeat deadly creatures. It might learn a thing or two from watching you do battle with a powerful opponent.>", ["objectivesText"] = "Complete 1 Rare Elite World Quest with your Direbeak Hatchling out. Progress: <Your direbeak hatchling looks ready to learn!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44978 } },
[44980] = { ["id"] = 44980, ["name"] = "Hunting Lesson: Tiny Apparition", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44980 }, ["description"] = "<Your direbeak hatchling seems to see prey that you cannot, sometimes staring at a wall for hours at a time. It must have found a new species to prey upon, or gotten into some mead.>", ["objectivesText"] = "Defeat 3 Tiny Apparitions in Stormheim with your Direbeak Hatchling . Progress: <Your direbeak hatchling looks ready to hunt.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44979 } },
[44981] = { ["id"] = 44981, ["name"] = "The Unkindly Faction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44981 }, ["description"] = "<When passing the other faction recently, your direbeak squawked at them for food. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", ["objectivesText"] = "Complete 3 PvP World Quests with your Direbeak Hatchling out. Progress: <Your direbeak hatchling seems to like the other faction a bit too much.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147832 }, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44980 } },
[44982] = { ["id"] = 44982, ["name"] = "Direbeak Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44982 }, ["description"] = "<Your direbeak hatchling puffs up its feathers and growls at you in a display of dominance. It seems unhappy with the results, as you are not cowering in fear. It might like to dress up like a grown-up falcosaur and try again.>", ["objectivesText"] = "Buy a pair of Fake Teeth from Clockwork Assistant in Dalaran for your Direbeak Hatchling . Progress: <Your direbeak hatchling looks at you inquisitively.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142495, 142499 }, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44981 } },
[44983] = { ["id"] = 44983, ["name"] = "Hunting Lesson: Golden Eaglet", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44983 }, ["description"] = "<Your direbeak hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the eagles of Stormheim.>", ["objectivesText"] = "Defeat 3 Golden Eaglets in Stormheim with your Direbeak Hatchling and 2 Flying pets. Progress: <Your direbeak hatchling preens.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44982 } },
[44984] = { ["id"] = 44984, ["name"] = "Teamwork Lesson: Fenryr", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44984 }, ["description"] = "<Your direbeak hatchling timidly avoided the other flying pets during their last battles together. Showing it a good example of teamwork might help.>", ["objectivesText"] = "Defeat Fenryr in Halls of Valor in Stormheim with your Direbeak Hatchling out. Progress: <Your direbeak hatchling looks to you for guidance.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44983 } },
[44985] = { ["id"] = 44985, ["name"] = "Hunting Lesson: Stormstruck Beaver", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44985 }, ["description"] = "<Your direbeak hatchling looks warily at any loud piece of machinery you pass. You begin to wonder if something transpired between it and a mechanical pet at one point. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", ["objectivesText"] = "Defeat 3 Stormstruck Beavers in Stormheim with your Direbeak Hatchling and 2 Mechanical pets. Progress: <Your direbeak hatchling looks wary of your mechanical pets.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44984 } },
[44986] = { ["id"] = 44986, ["name"] = "Teamwork Lesson: Krosus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44986 }, ["description"] = "<Your direbeak hatchling squawks loudly and panics when very large creatures are nearby, even if they are friendly. It must learn to remain calm under pressure, even when facing creatures many times its size. Showing it an epic example of teamwork against a monster the size of a mountain might help.>", ["objectivesText"] = "Defeat Krosus in the Nighthold with your Direbeak Hatchling out. Progress: <Your direbeak hatchling looks to you for guidance.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 137579 }, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44985 } },
[44987] = { ["id"] = 44987, ["name"] = "Direbeak Team Rumble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44987 }, ["description"] = "<Your direbeak hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests with your Direbeak Hatchling and 2 Humanoid pets.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 93040, 106244, 127868 }, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44986 } },
[44988] = { ["id"] = 44988, ["name"] = "Direbeak Reunion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["storyline"] = { 44988 }, ["description"] = "<Your direbeak hatchling won't stop emitting soft, melancholy squawks. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", ["objectivesText"] = "Return the Direbeak Hatchling to Gull Rock in Stormheim.", ["rewardGold"] = 262100, ["rewardXP"] = 6140, ["rewardItems"] = { 137579 }, ["starts"] = { { ["npcID"] = 115785 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 115785, ["questType"] = "standard", ["sourceQuests"] = { 44987 } },
[44989] = { ["id"] = 44989, ["name"] = "Raising Your Sharptalon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44989 }, ["description"] = "<Your sharptalon hatchling continues to shiver as it settles in at your side. It looks up at you with wide, unblinking eyes. It appears to be looking to you to help it survive and grow.>", ["objectivesText"] = "Raise your Sharptalon Hatchling to level 25. Progress: Baroo!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 116415, 116429, 122457, 128763, 128837, 128839, 128843, 137577, 137578, 137579, 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard" },
