[44997] = { ["id"] = 44997, ["name"] = "Allies in Val'sharah", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44997 }, ["description"] = "<Your sharptalon hatchling stubbornly refuses to enter Val'sharah when you approach.> <Though they revere nature, the Dreamweavers also must maintain the balance of nature, and began an aggressive campaign against the falcosaurs once their invasiveness was noted. It has likely seen the druids of Val'sharah slaughter some members of its flock.> <Show your falcosaur that you and it can work alongside the Dreamweavers.>", ["objectivesText"] = "Complete 5 World Quests in Val'sharah with your Sharptalon Hatchling out. Progress: <Your sharptalon hatchling isn't at all sure about this.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 44995 } },
