[45002] = { ["id"] = 45002, ["name"] = "Dangerous Prey", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45002 }, ["description"] = "<Your bloodgazer falcosaur continues to tremble timidly whenever a powerful creature is nearby. It would help to build its confidence to see you defeat such a creature.>", ["objectivesText"] = "Complete 1 Rare Elite World Quest with your Bloodgazer Hatchling out. Progress: <Your bloodgazer hatchling looks ready to learn!>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45000 } },
[45003] = { ["id"] = 45003, ["name"] = "Hunting Lesson: Terror Larva", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45003 }, ["description"] = "<Your sharptalon hatchling has been desperately rooting for worms in Val'sharah recently. It must have found a new species to prey upon.>", ["objectivesText"] = "Defeat 3 Terror Larvae in Val'sharah with your Sharptalon Hatchling . Progress: <Your sharptalon hatchling looks ready to hunt.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45001 } },
[45004] = { ["id"] = 45004, ["name"] = "Hunting Lesson: Fledgling Kingfeather", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45004 }, ["description"] = "<Your bloodgazer hatchling has been flapping its wings excitedly and rubbing its beak on the trunks of trees in Azsuna. It must have found a new species to prey upon.>", ["objectivesText"] = "Defeat 3 Fledgling Kingfeathers in Azsuna with your Bloodgazer Hatchling . Progress: <Your bloodgazer hatchling looks ready to hunt.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45002 } },
[45005] = { ["id"] = 45005, ["name"] = "The Uncongenial Faction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45005 }, ["description"] = "<When passing the other faction recently, your sharptalon attempted to play with their pet. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", ["objectivesText"] = "Complete 3 PvP World Quests with your Sharptalon Hatchling out. Progress: <Your sharptalon hatchling seems to like the other faction a bit too much.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45003 } },
[45006] = { ["id"] = 45006, ["name"] = "The Unfavorable Faction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45006 }, ["description"] = "<When passing the other faction recently, your bloodgazer sniffed curiously at their pack. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", ["objectivesText"] = "Complete 3 PvP World Quests with your Bloodgazer Hatchling out. Progress: <Your bloodgazer hatchling seems to like the other faction a bit too much.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45004 } },
[45007] = { ["id"] = 45007, ["name"] = "Sharptalon Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45007 }, ["description"] = "<Your sharptalon hatchling will instinctively run into the kitchen of any inn you enter and make a mess of the pots and pans. It has a tendency to get into any dishes that are laying about, especially the dirty ones. You may be able to curb this behavior by finding it some silverware of its very own.>", ["objectivesText"] = "Buy a Dirty Spoon from Mel Lynchen in Dalaran for your Sharptalon Hatchling . Progress: <Your sharptalon hatchling looks at you inquisitively.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137580, 142496, 142500 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45005 } },
[45008] = { ["id"] = 45008, ["name"] = "Bloodgazer Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45008 }, ["description"] = "<Your bloodgazer hatchling seems to love rolling around in flowers. You surmise that an affinity to flowering plants has probably helped the flock locate fruits to consume in the past. It would probably be quite excited to have a special flower of its own!>", ["objectivesText"] = "Buy a Purple Blossom from Aerith Primrose in Dalaran for your Bloodgazer Hatchling . Progress: <Your bloodgazer hatchling looks at you inquisitively.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142494, 142498 }, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45006 } },
[45009] = { ["id"] = 45009, ["name"] = "Hunting Lesson: Auburn Ringtail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45009 }, ["description"] = "<Your sharptalon hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the raccoons of Val'sharah.>", ["objectivesText"] = "Defeat 3 Auburn Ringtails in Val'sharah with your Sharptalon Hatchling and 2 Flying pets. Progress: <Your sharptalon hatchling preens.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45007 } },
[45010] = { ["id"] = 45010, ["name"] = "Hunting Lesson: Juvenile Scuttleback", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45010 }, ["description"] = "<Your bloodgazer hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the crabs of Azsuna.>", ["objectivesText"] = "Defeat 3 Juvenile Scuttlebacks in Azsuna with your Bloodgazer Hatchling and 2 Flying pets. Progress: <Your bloodgazer hatchling preens.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143679 }, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45008 } },
[45011] = { ["id"] = 45011, ["name"] = "Teamwork Lesson: Dresaron", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45011 }, ["description"] = "<Your sharptalon hatchling does not seem particularly interested in your other pets, and largely ignores them during combat. Showing it a good example of teamwork might help.>", ["objectivesText"] = "Defeat Dresaron in Darkheart Thicket in Val'sharah with your Sharptalon Hatchling out. Progress: <Your sharptalon hatchling looks to you for guidance.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45009 } },
[45012] = { ["id"] = 45012, ["name"] = "Teamwork Lesson: Serpentrix", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45012 }, ["description"] = "<While victorious, your bloodgazer hatchling distracted your other pets during crucial moments in combat. Showing it a good example of teamwork might help.>", ["objectivesText"] = "Defeat Serpentrix in Eye of Azshara in Azsuna with your Bloodgazer Hatchling out. Progress: <Your bloodgazer hatchling looks to you for guidance.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45010 } },
[45013] = { ["id"] = 45013, ["name"] = "Hunting Lesson: Vale Flitter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45013 }, ["description"] = "<Your sharptalon hatchling adamantly refuses to go anywhere near a body of water, squawking and scratching the ground whenever you wade in yourself. Perhaps working with some aquatic pets would help it get over this fear. Hunting together against the new prey it has begun stalking may just do the trick.>", ["objectivesText"] = "Defeat 3 Vale Flitters in Val'sharah with your Sharptalon Hatchling and 2 Aquatic pets. Progress: <Your sharptalon hatchling looks wary of your aquatic pets.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45011 } },
[45014] = { ["id"] = 45014, ["name"] = "Hunting Lesson: Felspider", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45014 }, ["description"] = "<Whenever you retire to an inn, your hatchling climbs the furniture and refuses to touch the ground. It will hop unsteadily from object to object, often causing a large mess. You recall that this may be due to a bad experience with fleas. Hunting together with some critter pets against new prey might help it get over this fear.>", ["objectivesText"] = "Defeat 3 Felspiders in Azsuna with your Bloodgazer Hatchling and 2 Critter pets. Progress: <Your bloodgazer hatchling looks wary of your critter pets.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45012 } },
[45015] = { ["id"] = 45015, ["name"] = "Teamwork Lesson: Xavius", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45015 }, ["description"] = "<Your sharptalon hatchling has taken to hiding in your pack when you approach very powerful creatures in the world. It must learn to remain calm under pressure, even when facing the darkest of nightmares. Showing it an epic example of teamwork against a fearsome foe might help.>", ["objectivesText"] = "Defeat Xavius in the Emerald Nightmare with your Sharptalon Hatchling out. Progress: <Your sharptalon hatchling looks to you for guidance.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45013 } },
[45016] = { ["id"] = 45016, ["name"] = "Teamwork Lesson: Skorpyron", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 4, 10, 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45016 }, ["description"] = "<Your bloodgazer hatchling growls and hisses at large beasts, seemingly without concern for its own safety. It will need to learn to rely on numbers to keep it safe. Showing it an epic example of teamwork against a great beast might help.>", ["objectivesText"] = "Defeat Skorpyron in the Nighthold with your Bloodgazer Hatchling out. Progress: <Your bloodgazer hatchling looks to you for guidance.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 122457 }, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45014 } },
[45017] = { ["id"] = 45017, ["name"] = "Sharptalon Team Rumble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45017 }, ["description"] = "<Your sharptalon hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests with your Sharptalon Hatchling and 2 Magic pets. Progress: <Your sharptalon hatchling is ready to go!>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 119170, 137580, 140672 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45015 } },
[45018] = { ["id"] = 45018, ["name"] = "Bloodgazer Team Rumble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45018 }, ["description"] = "<Your bloodgazer hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests with your Bloodgazer Hatchling and 2 Beast pets. Progress: <Your bloodgazer hatchling is ready to go!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 70908, 94573 }, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45016 } },
[45019] = { ["id"] = 45019, ["name"] = "Sharptalon Reunion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 45019 }, ["description"] = "<Your sharptalon hatchling has not been eating recently. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", ["objectivesText"] = "Return the Sharptalon Hatchling to the Verdant Cliffs in Val'sharah.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["starts"] = { { ["npcID"] = 115786 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 115786, ["questType"] = "standard", ["sourceQuests"] = { 45017 } },
[45020] = { ["id"] = 45020, ["name"] = "Bloodgazer Reunion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["storyline"] = { 45020 }, ["description"] = "<Your bloodgazer hatchling refuses to drink. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", ["objectivesText"] = "Return the Bloodgazer Hatchling to Alluvanon's Delta in Azsuna.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137577 }, ["starts"] = { { ["npcID"] = 115787 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questGiverID"] = 115787, ["questType"] = "standard", ["sourceQuests"] = { 45018 } },
[45021] = { ["id"] = 45021, ["name"] = "Answers Unknown", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45024 }, ["description"] = "Have you noticed a change in Jubeka's demeanor? I know she's not the warmest of warlocks, but I fear she's been more withdrawn than usual. I imagine her mind lingers on Kanrethad, the council's one-time leader. Jubeka was steadfast in her commitment to keeping him banished, until the Burning Legion took her as their prisoner. His fate is unknown, and it's clearly troubling our friend. The last thing she said to me, was that she felt his presence in Azsuna. Don't let her travel this path alone.", ["objectivesText"] = "Find Jubeka Shadowbreaker within Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.574, ["y"] = 0.38, ["mapID"] = 717, ["npcID"] = 105926 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7875 } }, ["questGiverID"] = 105926, ["questType"] = "standard", ["sourceQuests"] = { 43414, 47137 }, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45024] = { ["id"] = 45024, ["name"] = "Cult Culling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45021 }, ["description"] = "The lure of Kanrethad is strong. Even when not in this world, there are those who wish to be near him at any cost, hoping to share in his power. A group of these fanatics are here in Faronaar, working tirelessly to bring Kanrethad back, I've learned as much from my prisoner. We cannot let them succeed, <name>. Find their compound and kill as many of them as you can. I will remain here and see what else I can learn about their intentions.", ["objectivesText"] = "Head into Felfire Cavern and kill members of the Cult of the Green Flame.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 97919, 137663 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 45021 }, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45025] = { ["id"] = 45025, ["name"] = "Stealing the Source of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["description"] = "My prisoner is a chatty one, <name>. He tells me that the Cult of the Green Flame is harnessing fel energy to fuel their efforts of bringing Kanrethad back from banishment. Within their compound they are powering fel crystals that can hold a great amount of fel magic. Without the proper power to perform their ritual, the occultists will have a tough time succeeding in their task. Steal their fel crystals , but don't destroy them. We can always find a use for something so powerful.", ["objectivesText"] = "Collect 5 Fel Crystals . Progress: Have you obtained the fel crystals ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142393 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45021 }, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45026] = { ["id"] = 45026, ["name"] = "Expending Fel Energy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45027, 45794 }, ["description"] = "Soon Kanrethad's banishment will fade, and he will return to our world. We must keep him, and his power, out of the Legion's hands at any cost. If my old friend is still in there somewhere, perhaps we can bring him back. The crystals you recovered feed on fel energy. We can use the ravenous crystals to siphon away the magic that consumes Kanrethad. But first, their power must be depleted. To do so, you will need to harness the power of the crystals and use their energy to kill demons.", ["objectivesText"] = "Harness the power of the Fel Crystals and expend their energy by killing demons within Faronaar. Progress: Have the crystals been depleted?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144255, 144256 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45024, 45025 }, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45027] = { ["id"] = 45027, ["name"] = "To the Broken Shore", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45026, 45794 }, ["description"] = "It would seem that Kanrethad's twisted followers have begun their ritual on the Broken Shore. We must act quickly. The Burning Legion cannot be allowed to use Kanrethad as their weapon. We have acolytes on standby, ready to perform a ritual of summoning on the Broken Shore when you're ready.", ["objectivesText"] = "Head to the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292 }, ["starts"] = { { ["x"] = 0.574, ["y"] = 0.38, ["mapID"] = 717, ["npcID"] = 105926 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7875 } }, ["questGiverID"] = 105926, ["questType"] = "standard", ["sourceQuests"] = { 45794 }, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45028] = { ["id"] = 45028, ["name"] = "The Fate of Kanrethad", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["description"] = "I can feel his presence, Netherlord! Kanrethad is here! His followers have set up camp in the nearby pass, and are performing the ritual to bring him back as we speak. Quickly, take the fel crystals. Arrange them in a circle around Kanrethad. If placed correctly, the crystals should link together and begin to siphon the fel energy. Now go, before it's too late!", ["objectivesText"] = "Use the Fel Crystals to siphon fel energy from Kanrethad. Progress: We cannot allow the Burning Legion to take control of Kanrethad.", ["rewardGold"] = 477360, ["rewardXP"] = 7675, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45027 }, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
