[45050] = { ["id"] = 45050, ["name"] = "Infiltration Plans", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45050 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "While the text is hard to follow and covered in demonic runes, it appears to be plans to infiltrate Dalaran. The Council of the Six will want to see this. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45050)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45050))\");", ["objectivesText"] = "Take the plans to the Council of the Six in Dalaran.", ["rewardItems"] = { 142382 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142382 } },
[45051] = { ["id"] = 45051, ["name"] = "Reverse Blacksmithing", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 490, ["mapID"] = 78, ["storyline"] = { 45051 }, ["series"] = { 45044, 45055, 45057 }, ["description"] = "And 'ere I thought I'd never see dis ting again! Although, it don't look like it used to. Aw mon, I'm gonna be in big trouble if I show up wit dis in my hand. Do ya tink you could help me fix it? I don't have da plans for it, cause you see, da first night I spent here, da creatures came up and stole all me tings. But whadd'ya say? Help a bruddah out? I tink if you can figure out what it's made from, den you can fix it and I can write down da details on how it's made.", ["objectivesText"] = "Deconstruct the Broken Darkspear . Progress: You're a life saver, bruddah! I'll be forever in your debt after dis.", ["rewardGold"] = 10500, ["rewardXP"] = 260, ["rewardItems"] = { 142389 }, ["starts"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 78, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 78 }, ["zone"] = { 490 } }, ["questType"] = "standard", ["sourceQuests"] = { 45044 } },
[45052] = { ["id"] = 45052, ["name"] = "Depleted Nether Crystal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45052 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "This crystal looks like something used in rituals of dark magic. Given that its energy is depleted, whoever this belongs to must have been successful in whatever ritual they were performing. The mages of the Kirin Tor would likely be interested in investigating this. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45052)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45052))\");", ["objectivesText"] = "Take the crystal to the Council of Six in Dalaran.", ["rewardItems"] = { 142384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142384 } },
[45053] = { ["id"] = 45053, ["name"] = "Thief's Instructions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45053 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "The hastily scrawled note reads: \"I require the Focusing Iris for one of my spells. Show that you are truly the greatest of my apprentici and fetch it for me. Oh, and make sure you don't leave this note lying around for some adventurer to find!\" If someone is looking to steal the Focusing Iris, the Kirin Tor will likely want to know. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45053)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45053))\");", ["objectivesText"] = "Take the instructions to the Council of Six in Dalaran.", ["rewardItems"] = { 142392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142392 } },
[45054] = { ["id"] = 45054, ["name"] = "\"Ancient\" Elven War Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45054 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "These orders look official and bear the Ravencrest sigil, but they are far too new. There is also a hint of fel magic glimmering around the sides. The Council of Six would be interested in seeing this. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45054)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45054))\");", ["objectivesText"] = "Take the forged orders to the Council of the Six in Dalaran.", ["rewardItems"] = { 142394 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142394 } },
[45055] = { ["id"] = 45055, ["name"] = "A Taste of Their Own Medicine", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 490, ["mapID"] = 78, ["storyline"] = { 45055 }, ["series"] = { 45044, 45051, 45057 }, ["description"] = "I been at dis camp for some time now, an' I know for a fact dat dose materials can be found right here in Un'Goro. Time ta give da creatures here some payback. Take from dem just like dey took from me! At least, you could do dat for me, right bruddah? I'll just wait here for ya to return wit' all da stuff.", ["objectivesText"] = "Kill creatures around Un'Goro Crater and retrieve 5 Stolen Enchanted Thorium Bars , 5 Mostly Powerful Mojos , 2 Calcified Diemetradon Scales , and 2 Bleached Stegodon Spikes . Bring them to Ko'Zan when you're done. Progress: Thieving worms gonna get what dey deserve!", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 142385, 142386, 142387, 142388 }, ["starts"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 78, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 78 }, ["zone"] = { 490 } }, ["questType"] = "standard", ["sourceQuests"] = { 45051 } },
[45056] = { ["id"] = 45056, ["name"] = "Noressa", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45056 }, ["description"] = "She is still in there, <name>. Noressa , my wife. She is in the Promenade while we wait outside, preparing to strike. Who knows what has happened to her? Please, friend, I fear the worst. Tell her there is hope outside. We had a small house in the south of the Grand Promenade, by the water gardens. She will probably be there during this madness.", ["objectivesText"] = "Rescue Noressa . Progress: You must find her!", ["rewardItems"] = { 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101848, ["x"] = 0.3675, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101848, ["x"] = 0.3675, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 40798 } },
[45057] = { ["id"] = 45057, ["name"] = "Saving My Head", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 490, ["mapID"] = 78, ["storyline"] = { 45057 }, ["series"] = { 45044, 45051, 45055 }, ["description"] = "Seeing as how you're a blacksmith, I figured it'd be best if ya made da spear. You can use dis forge here to do what ya need to to do. I'll start writin' down what ya do and den we'll have us both da spear and da recipe!", ["objectivesText"] = "Use the forge near Ko'Zan to recreate the Darkspear. Progress: Dis is probably da luckiest day of me life.", ["rewardXP"] = 260, ["rewardItems"] = { 142377, 142383 }, ["starts"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 78, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 78 }, ["zone"] = { 490 } }, ["questType"] = "standard", ["sourceQuests"] = { 45055 } },
