[45059] = { ["id"] = 45059, ["name"] = "Fel Infused Totem Fragment", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45059 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45060, 45061, 46765, 47000 }, ["description"] = "This appears to be a fragment of a relic or totem from Highmountain. It glows eerily with fel power. This should be brought to the Council of Six in Dalaran at once! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45059)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45059))\");", ["objectivesText"] = "Take the totem fragment to the Council of the Six in Dalaran.", ["rewardItems"] = { 142395 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142395 } },
[45060] = { ["id"] = 45060, ["name"] = "Damaged Kirin Tor Insignia", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45060 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45061, 46765, 47000 }, ["description"] = "Whether it was lost or stolen, it is odd that a demon would possess an insignia of the Kirin Tor. The Council of Six would no doubt be interested in this finding. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45060)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45060))\");", ["objectivesText"] = "Take the insignia to the Council of the Six in Dalaran.", ["rewardItems"] = { 142396 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142396 } },
[45061] = { ["id"] = 45061, ["name"] = "Scrolls of the Faldrottin", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45061 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 46765, 47000 }, ["description"] = "While it is definitely odd that a demon would carry a scroll of vrykul writings, what is even more interesting are the contents. The writings appear to reference a vrykul prophesy of one who would unite the Tideskorn against the Burning Legion. This information should be brought to the Council of Six immediately. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45061)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45061))\");", ["objectivesText"] = "Take the scrolls to the Council of the Six in Dalaran.", ["rewardItems"] = { 142397, 144457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142397 } },
[45062] = { ["id"] = 45062, ["name"] = "Resisting Arrest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 45063 }, ["description"] = "Your findings do not disappoint, <name>. Make your way to the soul engine and use our newly acquired weapons to dismantle the power source.", ["objectivesText"] = "Use the withered to dismantle the Power Source inside the Soul Engine at Felsoul Hold. Progress: There is much to be done.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 142400, 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45063 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45063] = { ["id"] = 45063, ["name"] = "The Felsoul Experiments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 45062 }, ["description"] = "Andaris's control over the withered poses a real threat. If we are to increase the withered's resistance against these effects, we must do so in an environment built from this very magic. Head for Felsoul Hold at once. When you arrive, I will send withered to aide in your efforts. It is of the utmost importance you do not leave until you are certain the experiments yield the appropriate results.", ["objectivesText"] = "Test the withered's resistance against fel magic at Felsoul Hold. Progress: Making progress I assume?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142399, 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44919 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45064] = { ["id"] = 45064, ["name"] = "Felborne No More", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "The Felborne have begun to expand their grasp beyond the city's reach. A camp to the east in the Crimson Thicket is of a particular interest to us. Their outpost leader, Valthis Ama'ran , serves Andaris directly. Now is the time to put our withered training and Oculeth's device to the test. We cannot allow them to advance any further, <name>. Head for the camp and use the orb to sever the head of the beast. The time has come to begin our advance.", ["objectivesText"] = "Slay 8 Felborne and their leader, Valthis Ama'ran , at the Felborne Outpost in Crimson Thicket. Progress: Has the threat been removed?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142491, 143746, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45062, 45065, 45066 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45065] = { ["id"] = 45065, ["name"] = "Survey the City", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "Never a dull moment! Well... perhaps this is not entirely true. I'm afraid I must ask you once more to return to the city to gather information. But this is not just any information - this is information extraction! I require specific coordinates to allow me to focus my teleportations with extreme accuracy. It will, unfortunately, take a bit of time to dig through the information once retrieved, but no matter. We have plenty else to do in the meantime.", ["objectivesText"] = "Use the Advanced Telemancy Beacon to survey the Terrace of Order in Suramar City. Progress: Let's hope this is survey is our last. I grow quite tired watching you run around all day.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142405, 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45067 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45066] = { ["id"] = 45066, ["name"] = "Experimental Instability", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "In order to advance our studies I must ask you to recover a few particular items from my long-forgotten chambers. I assure you it is... mostly safe there, aside from a few unstable elements. Make your way to my workshop and locate the teleporter. I'll disable its cloaking device when you arrive.", ["objectivesText"] = "Gather the Telemancy Notes and 4 Discarded Orbs from Oculeth's Test Chamber. Progress: Scavenging going well? Not too dangerous I hope.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143538 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45065 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45067] = { ["id"] = 45067, ["name"] = "Telemantic Expanse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "Understanding fel magic alone may not be enough, <name>. Speak with Oculeth about diversifying our efforts. I hear he's got something... unique planned for us.", ["objectivesText"] = "Speak with Oculeth in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44919 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
