[45073] = { ["id"] = 45073, ["name"] = "Loot and Plunder!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45576, 45628, 45629, 45833, 45835, 45836, 45848, 46260, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "I'm bein' honest here matey, I've got me own motives fer bein' here. Last time there was a bit of a debacle. Some drinkin', some gamblin', and a bit too much rum if ye catch me meanin'. Some words were said, some fists were thrown and... honestly it was quite a haze. I'm not the most welcome pirate here after that. But they took me stuff! These lyin', dirty ol'... ahem. Could ye just take this torch and... burn their belongin's? I'd be grateful.", ["objectivesText"] = "Burn 8 Blacksail Booty .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 118125, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 118125, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 45833, 46322 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
