[45083] = { ["id"] = 45083, ["name"] = "Crysa's Flyers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 45083 }, ["description"] = "I have obtained some of the most exotic species of carrion bird ever seen on Azeroth. Do you think you can stand up to them?", ["objectivesText"] = "Defeat Crysa in a pet battle. Progress: The carrion birds are circling you!", ["rewardGold"] = 250380, ["rewardXP"] = 200, ["rewardItems"] = { 142447, 142448 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 115286, ["x"] = 0.635, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 115286, ["x"] = 0.635, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[45088] = { ["id"] = 45088, ["name"] = "Trial of Valor: The Lost Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8440, ["storyline"] = { 45088 }, ["description"] = "While Helya's defeat is your primary objective, I require more of your aid. Helya has gained the ability to steal and corrupt the souls of my Valarjar. Her minions hold these souls, corrupting them. I am certain Helya herself hordes the greatest Valarjar souls to herself. You must recover these lost souls, then return them to me. Do this and I will reward you with blessed guard from the hall's armory.", ["objectivesText"] = "Gather 1000 Valarjar Soul Fragments within the Trial of Valor Raid. Progress: Bring me the souls of my lost Valarjar. Only then will I reward you with the blessed armor you desire.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142487, 143506, 143510, 143514, 143518, 143521, 241599 }, ["rewardChoices"] = { 143506, 143510, 143514, 143518 }, ["starts"] = { { ["npcID"] = 114263 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8440 } }, ["questGiverID"] = 114263, ["questType"] = "raid" },
[45102] = { ["id"] = 45102, ["name"] = "Begin the Assault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8581, ["storyline"] = { 45102 }, ["description"] = "The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn. Now we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. Our first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, . The assault on the Broken Shore begins now.", ["objectivesText"] = "Begin the assault on the Broken Shore.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8581 } }, ["questType"] = "standard" },
[45103] = { ["id"] = 45103, ["name"] = "We Ride!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "The time has come, Deathlord! Our scouts have marked a large amassing of demons not far from here. Lead us to victory, and show these demons the power of undeath!", ["objectivesText"] = "Lead the Four Horsemen in the battle against the Burning Legion.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 31451, 31452, 31453, 31454, 31455, 43873, 43875, 43877, 43896, 43897, 43898, 43899, 43904, 43937, 43939, 43940, 43948, 52919, 52964, 54465, 55962, 55963, 55964, 57518, 147457, 158228, 158238, 158239, 158240, 158241, 175161, 175162, 175163, 175164, 175165, 175166, 175167, 175168, 175169, 175170, 175171, 175172, 175173, 175174, 197607, 199826, 199827, 199828, 199829 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116128, ["x"] = 0.515333, ["y"] = 0.216 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116128, ["x"] = 0.515333, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.515333, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 116128, ["questType"] = "standard", ["sourceQuests"] = { 45243 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45104] = { ["id"] = 45104, ["name"] = "Your Next Assignment...", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 45104 }, ["description"] = "Congratulations on making it through the Intern Expo! However, we're not through with you yet! You still have some time left, so what better use of your time than to make treasures and vignettes on the Broken Shore! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45104)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45104))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Create interesting treasures and vignettes for patch 7.2!", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45105] = { ["id"] = 45105, ["name"] = "Lord Raz'gor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45105 }, ["description"] = "The pit lord, Raz'gor, oversees this bulwark. If you wish to break the Broken Shore, Raz'gor must be defeated. Fight you way past the demon blockade and find Lord Raz'gor. Slay the demon and you will strike a heavy blow to the Burning Legion's plans on the Broken Shore. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45105)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45105))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Defeat Lord Raz'gor on the Broken Shore.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45111] = { ["id"] = 45111, ["name"] = "Everyone Loves a Good Fight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45111 }, ["description"] = "The note reads: \"You shouldn't have blabbed about the brawlers, especially to those champions. Now that you have though, I suppose it's ok that they fight here on occasion, but you better prove yourself a true brawler first!\"", ["objectivesText"] = "Compete in 5 Brawls. Progress: Compete in the Brawlers Guild to allow your champions to participate.", ["rewardItems"] = { 93195, 93228, 142319, 142522, 142553, 142554, 143561, 143590, 143899 }, ["rewardCurrencies"] = { { ["id"] = 1299, ["amount"] = 100 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 49889, ["x"] = 0.556, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 142522 } },
[45112] = { ["id"] = 45112, ["name"] = "Signs of Madness", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 71, ["storyline"] = { 45112 }, ["description"] = "<Whoever this buyer is, they seem to have left in a hurry. Acrid fumes sit heavy in the air around you, and a campfire in the center of the area smolders.> <Perhaps something here can point you in the right direction?>", ["objectivesText"] = "Search the Deserted Workshop for information that might lead you to the buyer.", ["rewardItems"] = { 142527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 291, ["name"] = "Suspicious Munitions", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71 },
