[45118] = { ["id"] = 45118, ["name"] = "Helya's Horn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44889, 45128, 45634 }, ["description"] = "<name>, we need to bolster our army by any means necessary. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are eternally bound to obey Helya even through her death. If we can call them using her voice, they will follow us instead! We recovered Helya's Horn from her corpse. Empower it so you can call the kvaldir when we have need of them.", ["objectivesText"] = "Kill enemies in Helheim to empower Helya's Horn .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144071 }, ["starts"] = { { ["x"] = 0.343, ["y"] = 0.285, ["mapID"] = 649, ["npcID"] = 116193 } }, ["ends"] = { { ["x"] = 0.343, ["y"] = 0.285, ["mapID"] = 649, ["npcID"] = 116193 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.343, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 116193, ["questTurnInID"] = 116193, ["questType"] = "standard", ["sourceQuests"] = { 44849 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[45123] = { ["id"] = 45123, ["name"] = "Elemental: The Folly of Levia Laurence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327 }, ["description"] = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Elemental Shaman", ["objectivesText"] = "Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questTurnInID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47035 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45125] = { ["id"] = 45125, ["name"] = "Dabbling in the Demonic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45126 }, ["description"] = "Levia must have used these runes to aid her ritual. Even if she is as powerful as Modera says, she was a novice in demonic magic, so the runes must have helped stabilize the portal. I'll need you to find out what runes need to be activated to recreate her ritual. There are several books on runic magic in this room, which she no doubt studied for her ritual. Once you have activated the runes, I will complete the spell.", ["objectivesText"] = "Activate the correct three runes to help Rittsyn Flamescowl complete the spell to stabilize the portal. Progress: Quit fooling around and help me with this ritual!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.579, ["y"] = 0.726, ["mapID"] = 629, ["npcID"] = 116714 } }, ["ends"] = { { ["x"] = 0.579, ["y"] = 0.726, ["mapID"] = 629, ["npcID"] = 116714 } }, ["coords"] = { ["mapID"] = 629, ["x"] = 0.579, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 116714, ["questTurnInID"] = 116714, ["questType"] = "standard", ["sourceQuests"] = { 45916 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[45126] = { ["id"] = 45126, ["name"] = "Unlikely Seduction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45125 }, ["description"] = "Mo... Modera sent you? No... you must... leave! Agatha will be back any moment! Save... yourself...", ["objectivesText"] = "Defeat Agatha . Progress: Save... yourself...", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 45917 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45127] = { ["id"] = 45127, ["name"] = "Fel-Crossed Lovers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45861 }, ["description"] = "That vile imp mother! If I wasn't so weakened I would dive down that pool and give her a piece of my mind! <Levia takes a deep breath to regain her composure.> It's only a matter of time until Agatha can make use of the power she stole from me. We had best not be here when she does.", ["objectivesText"] = "Return to Archmage Modera in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 116189, ["questType"] = "standard", ["sourceQuests"] = { 45126 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
