[45143] = { ["id"] = 45143, ["name"] = "Judgment Awaits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["description"] = "Our ongoing offensive within the Broken Shore has drawn the interest of many paladins who wish to fight under your leadership. Some are more worthy than others, but only you can be the judge of that. The new recruits are lingering in the camp just outside the chapel, awaiting your judgment.", ["objectivesText"] = "Use Highlord's Judgment to determine the worth of Silver Hand Recruits. Progress: Not all are worthy of joining the Silver Hand.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.503, ["y"] = 0.741, ["mapID"] = 24, ["npcID"] = 90249 } }, ["ends"] = { { ["x"] = 0.503, ["y"] = 0.741, ["mapID"] = 24, ["npcID"] = 90249 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.503, ["y"] = 0.741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90249, ["questTurnInID"] = 90249, ["questType"] = "standard", ["sourceQuests"] = { 43424, 47137 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24 },
[45145] = { ["id"] = 45145, ["name"] = "Moonfang Family Relics", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["series"] = { 45890, 46259 }, ["description"] = "As promised, here is the crescent key that will open my family's lockboxes, though nothing of value remains. I trust whatever you find you'll deliver to Delas? Our ancestor's things, whatever their worth, should remain in our family.", ["objectivesText"] = "Recover Moonfang family relics from within Shadowfen.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143330, 143331, 143332 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 119209, ["questType"] = "standard", ["sourceQuests"] = { 46259 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24 },
[45146] = { ["id"] = 45146, ["name"] = "Runic Reading", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["series"] = { 45147, 45148 }, ["description"] = "There is something curious about this scroll. It appears to be an empty page to the untrained eye, but I can see a shimmer of runes appear briefly when I hold it up to the light. As with most demonic runes, I will need fel blood to undo the magic that's been used to conceal whatever message is within this scroll.", ["objectivesText"] = "Collect 10 Fel Blood from demons throughout the Broken Isles. Progress: I will need to submerge the scroll in demon blood in order for the runes to reveal themselves.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 137677 }, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.326, ["mapID"] = 24, ["npcID"] = 109102 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.326, ["mapID"] = 24, ["npcID"] = 109102 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.591, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 109102, ["questTurnInID"] = 109102, ["questType"] = "standard", ["sourceQuests"] = { 45145 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24 },
[45147] = { ["id"] = 45147, ["name"] = "Felstone Destruction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45147, 45890, 46259 }, ["series"] = { 45146, 45148 }, ["description"] = "<Delas' mouth drops open as the scroll falls from her hands and onto the floor.> This cannot be... the runes... they detail a pact between the Burning Legion and my ancestors. A dark deal that would grant my ancestors protection from demons in this life, but in return, their spirits would belong to the Legion. This fel pendant is an embodiment of the pact, and cannot be removed once worn. Quickly, <name>. You must use your artifact to destroy that cursed piece of jewelry!", ["objectivesText"] = "Destroy the Felstone Pendant.", ["rewardGold"] = 119340, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.326, ["mapID"] = 24, ["npcID"] = 109102 } }, ["ends"] = { { ["x"] = 0.591, ["y"] = 0.326, ["mapID"] = 24, ["npcID"] = 109102 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.591, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 109102, ["questTurnInID"] = 109102, ["questType"] = "standard", ["sourceQuests"] = { 45146 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24 },
[45148] = { ["id"] = 45148, ["name"] = "Oath Breaker", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["series"] = { 45146, 45147 }, ["description"] = "Many years ago I made a pact with a man I thought not to be unlike myself. His promise of protection seemed too good to be true, but it was a deal I was desperate to make. It wasn't until I had signed in blood that the dreadlord Zorak revealed himself. As long as he lives, my ancestors will remain bound to the Burning Legion, allowing our enemies to amass an army of unwilling soldiers. Head to the Broken Shore and slay Oathbinder Zorak . His death will break the hold he has over my ancestors.", ["objectivesText"] = "Head to the Broken Shore and slay Oathbinder Zorak .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 147469 }, ["starts"] = { { ["x"] = 0.589, ["y"] = 0.319, ["mapID"] = 24, ["npcID"] = 119545 } }, ["ends"] = { { ["x"] = 0.589, ["y"] = 0.319, ["mapID"] = 24, ["npcID"] = 119545 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.589, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 119545, ["questTurnInID"] = 119545, ["questType"] = "standard", ["sourceQuests"] = { 45147 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24 },
[45149] = { ["id"] = 45149, ["name"] = "Ending the Crescent Curse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["description"] = "We must do whatever we can to break the curse that befalls my ancestors. The Burning Legion have set up camp within the ruins that house our dead, ready to make good on the dreadful pact that was drafted so long ago. Each of my ancestor's is burdened with a pendant that binds them to their demonic overlords. It cannot be removed, but as you have shown, with enough power it can be destroyed. End the curse that plagues my ancestors and set their spirits free!", ["objectivesText"] = "Free Felbound Spirits in Crescent Ruins by destroying their fel pendants. Progress: You are the only one powerful enough to destroy the fel pendants that bind my ancestor's spirits to the Legion.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["starts"] = { { ["x"] = 0.589, ["y"] = 0.319, ["mapID"] = 24, ["npcID"] = 119545 } }, ["ends"] = { { ["x"] = 0.589, ["y"] = 0.319, ["mapID"] = 24, ["npcID"] = 119545 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.589, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 119545, ["questTurnInID"] = 119545, ["questType"] = "standard", ["sourceQuests"] = { 45147 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24 },
[45159] = { ["id"] = 45159, ["name"] = "Cubic Conundrum", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45159 }, ["series"] = { 45160, 45238, 45239 }, ["description"] = "mysterious cube . Its design is unfamiliar, but unmistakably ancient. The cube's surface is inlaid with magical runes. Though inert, its properties may be worth investigating. Perhaps if you show it to Dariness the Learned in Dalaran , she could tell you more about it.>", ["objectivesText"] = "Take the Mysterious Cube to Dariness the Learned in Dalaran . Provided item:", ["rewardItems"] = { 142536, 142559 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 142559 } },
[45160] = { ["id"] = 45160, ["name"] = "Cubic Currents", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 45160 }, ["series"] = { 45159, 45238, 45239 }, ["description"] = "To determine this cube's purpose, we need to power it up. Hmm, I have an idea... The Nightborne covet a substance you are no doubt familiar with called ancient mana. Should be just the thing for a relic this old. Gather a sufficient quantity and we'll attempt to get it working. Be careful in Suramar ! It would be a shame if this curious cube were lost and became a memory once more.", ["objectivesText"] = "Obtain 300 Ancient Mana from Suramar", ["rewardItems"] = { 142536 }, ["starts"] = { { ["x"] = 0.41, ["y"] = 0.262, ["mapID"] = 627, ["npcID"] = 93538 } }, ["ends"] = { { ["x"] = 0.41, ["y"] = 0.262, ["mapID"] = 627, ["npcID"] = 93538 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.41, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questTurnInID"] = 93538, ["questType"] = "standard", ["sourceQuests"] = { 45159 } },
