[45163] = { ["id"] = 45163, ["name"] = "Cleaning Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45163 }, ["description"] = "Your champions return successful. They tell a grand tale of how they really cleaned up against Bill the Janitor.", ["objectivesText"] = "Return the Broken Broom Handle to the Brawler's Guild.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 37275, 37351, 37443, 37478, 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750, 93195, 93228, 119001, 142522, 142553, 142554, 143561, 143590, 143899, 155237, 160384, 160387, 160390, 160393 }, ["rewardCurrencies"] = { { ["id"] = 1299, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 49889, ["x"] = 0.556, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 142554 } },
[45167] = { ["id"] = 45167, ["name"] = "REUSE ME", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 45167 }, ["description"] = ", we will need to bolster our army by any means necessary to have any hope of driving back the legion. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are bound to obey whomever posesses Helya's Horn . You must obtain it. Her so-called helarjar were tasked with guarding it. You will have to take it from them.", ["objectivesText"] = "Find Helya's Horn .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142315, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard" },
[45172] = { ["id"] = 45172, ["name"] = "To Battle!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 739, ["storyline"] = { 45172 }, ["description"] = "Your champions have returned from exploring the battleground with a report detailing wild adventures and death-defying feats of strength and honor. In these ever shifting battles of conquest, more assistance is always required. Will you answer the call?", ["objectivesText"] = "Join and win in any battleground. Progress: How are you faring in the battleground?", ["rewardGold"] = 842700, ["rewardXP"] = 2090, ["rewardItems"] = { 7979, 31380, 31381, 31382, 31383, 31404, 31405, 33447, 33448, 35814, 35815, 35816, 35817, 44382, 44383, 44384, 44385, 45724, 46114, 63760, 63761, 63762, 65852, 65853, 65854, 89125, 91086, 116415, 126923, 126924, 139457, 139471, 139472, 139473, 139474, 139475, 139476, 139477, 139478, 139479, 139480, 140147, 140163, 140164, 140171, 140172, 140177, 142001, 142002, 142003, 142004, 142340, 143328, 143479, 143606, 147501, 147505, 147509, 155413, 155414, 155415, 155416, 158174, 158179, 159980, 159981, 159982, 159983, 160335, 160338, 160341, 160344, 160373, 160376, 160379, 160382, 162140, 162141, 162142, 162143, 163036, 163526, 163533, 163534, 163536, 163537, 163538, 163539, 163540, 163541, 163542 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 143328 } },
[45173] = { ["id"] = 45173, ["name"] = "Desperate Times", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 739, ["storyline"] = { 45173 }, ["description"] = "The conflict continues. As always, your assistance is needed in the great battlegrounds. Join the fray, defeat your enemies, and win glory for your faction.", ["objectivesText"] = "Join and win in any battleground.", ["rewardItems"] = { 143329, 143607 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 143329 } },
[45174] = { ["id"] = 45174, ["name"] = "The Hunt for Illidan Stormrage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["series"] = { 45175, 45176 }, ["description"] = "Allari the Souleater , an oracle of the Illidari, has been on the hunt for Illidan's soul for quite some time. She now believes that she has discovered its location and requires your assistance in its recovery. Find Allari at Illidari Stand in Azsuna and aid her in any way possible. If Sargeras truly plans to use Illidan's body as a vessel for his own return then returning Illidan's soul to his body is integral in preventing the dark titan from returning to our world!", ["objectivesText"] = "Seek out Allari the Souleater at Illidari Stand in Azsuna.", ["rewardXP"] = 770, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 44481, 44496, 44497 }, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45175] = { ["id"] = 45175, ["name"] = "Soul Prism of the Illidari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["series"] = { 45174, 45176 }, ["description"] = "Alas, I will not burden you with the location of the master's soul just yet, <name>. First we must craft a soul prism powerful enough to hold the master's boundless chaotic energies. To do this I require lingering soul fragments from powerful beings found across this world. Bring me enough and I will craft a soul prism capable of holding the soul of the master - at least long enough to transfer into the naaru.", ["objectivesText"] = "Claim 5 Lingering Soul Fragments from the final bosses of Legion dungeons. Higher difficulty dungeons provide a greater chance and quantity of Lingering Soul Fragments.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139900, 139921, 139930, 139933, 139960, 139978, 140000, 140014 }, ["rewardChoices"] = { 139900, 139921, 139930, 139933, 139960, 139978, 140000, 140014 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 45174 }, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45176] = { ["id"] = 45176, ["name"] = "Trial of Valor: The Once and Future Lord of Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["series"] = { 45174, 45175 }, ["description"] = "While tracking the master's physical body proved challenging, we were able to locate it in the Nighthold of Suramar. Our intelligence reports that Gul'dan is making final preparations to the Nightwell in order to use its power to usher the soul of Sargeras into Illidan's body. The only way to stop that from happening is to put Illidan's own immortal soul back. Take the Soul Prism of the Illidari and venture to Helheim. Defeat Helya and use the prism on Illidan's soul! Return it to Light's Heart .", ["objectivesText"] = "Defeat Helya in the Trials of Valor raid and then use the Soul Prism of the Illidari to claim Illidan's Soul.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021, 143661 }, ["rewardChoices"] = { 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 89398, ["questType"] = "raid", ["sourceQuests"] = { 45175 }, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[45177] = { ["id"] = 45177, ["name"] = "The Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["description"] = "Illidan's soul rests safely within Light's Heart . Take this vessel and deliver it to Khadgar with the following instructions: When Gul'dan attempts to tear the sky asunder and bring the dark titan into our world, call forth the power of this vessel and release Illidan's soul into his body. Go now, <name>. We do not have much time. The dark ritual will begin soon.", ["objectivesText"] = "Deliver Light's Heart to Khadgar at the Violet Citadel in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 770, ["rewardItems"] = { 140148, 140763, 141324, 141325, 141326, 143757, 246936, 249400, 254267, 254579 }, ["starts"] = { { ["npcID"] = 113857, ["x"] = 0.4979, ["y"] = 0.2612, ["mapID"] = 702 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 113857, ["questType"] = "standard", ["sourceQuests"] = { 45176 }, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
