[45179] = { ["id"] = 45179, ["name"] = "Win the Crowd", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["description"] = "The letter invites you to fight in one of the greatest events in the history of Azeroth. The grand arena battles, where fighters win glory and honor, and everyone will remember their names. Or at least until the next season.", ["rewardItems"] = { 143607 }, ["ends"] = { { ["npcID"] = 96746, ["x"] = 0.33, ["y"] = 0.6, ["mapID"] = 726 }, { ["npcID"] = 98002, ["x"] = 0.528, ["y"] = 0.514, ["mapID"] = 747 }, { ["npcID"] = 99179, ["x"] = 0.528, ["y"] = 0.596, ["mapID"] = 709 }, { ["npcID"] = 103023, ["x"] = 0.43, ["y"] = 0.468, ["mapID"] = 739 }, { ["npcID"] = 106199, ["x"] = 0.666, ["y"] = 0.46, ["mapID"] = 717 } }, ["mapCandidates"] = { ["npc"] = { 709, 717, 726, 739, 747 }, ["zone"] = { 7834 } }, ["questType"] = "standard" },
[45182] = { ["id"] = 45182, ["name"] = "Frost: The Twisted Twin", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["description"] = "I have a request from an old friend, Karam Magespear , to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him. Originally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order. Find Karam in the Legerdemain Lounge and see if you can lend a hand. Specialization: Frost Mage", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.229, ["y"] = 0.381, ["mapID"] = 635, ["npcID"] = 90463 } }, ["ends"] = { { ["npcID"] = 116175, ["x"] = 0.564, ["y"] = 0.272, ["mapID"] = 646 } }, ["coords"] = { ["mapID"] = 635, ["x"] = 0.229, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questGiverID"] = 90463, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47034 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45185] = { ["id"] = 45185, ["name"] = "Message from the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "I know my brother has been misguided in the past, but I fear that he may have fallen in with an unthinkable evil. He recently began meeting in secret with a dark cult, hidden amongst the people of Dalaran. I travelled here to try to convince him of the error in his ways, but he would not be shaken from his course. Now, he has disappeared. When I last saw him, Raest was staying in a room upstairs. I was unable to find any clues there, but you might fare better.", ["objectivesText"] = "Search the upper room in the Legerdemain Lounge for a clue to Raest Magespear's location. Progress: Have you found something?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143494 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45182, 47037, 47039, 47041, 47042 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45187] = { ["id"] = 45187, ["name"] = "Secrets in the Underbelly", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "So my brother has gone off to perform some ritual with these cultists? That explains why he left, but still not to where... Wait! This letter mentions some of these \"Nethersworn\" cultists seeking reagents in the Underbelly. Perhaps we still may be able to find them if we hurry!", ["objectivesText"] = "Question the Underbelly Lowlifes in the Underbelly to find more information about Raest Magespear's location. Progress: Any leads, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143496 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 116175, ["questType"] = "standard", ["sourceQuests"] = { 45185 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628 },
[45188] = { ["id"] = 45188, ["name"] = "The Wisdom of the Council", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "I'm sorry, <name>, but I can't make heads nor tails of this. Riddles have never exactly been my strength. We should take this cultist's writings to the archmage. Perhaps he could shed some light on this.", ["objectivesText"] = "Bring the Nethersworn Manifesto to Archmage Karlain in the Violet Citadel in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143496 }, ["starts"] = { { ["x"] = 0.496, ["y"] = 0.394, ["mapID"] = 627, ["npcID"] = 116308 } }, ["ends"] = { { ["x"] = 0.496, ["y"] = 0.394, ["mapID"] = 627, ["npcID"] = 116308 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.496, ["y"] = 0.394 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 116308, ["questTurnInID"] = 116308, ["questType"] = "standard", ["sourceQuests"] = { 45187 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45190] = { ["id"] = 45190, ["name"] = "Where it's Thinnest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "Though I have never heard of this \"Nethersworn\" cult, what this manifesto speaks of can't be good. I do have a theory, however. The writing speaks of \"the place its skin is thinnest.\" I think they might be referring to the place where the veil between Azeroth and the Twisting Nether is weakest - the Tomb of Sargeras. With our forces having established a foothold at the Broken Shore, this would be an opportune time for Raest and his cultist allies to reach the tomb. I would suggest you stop them.", ["objectivesText"] = "Meet Karam Magespear at Felbreach Hollow in the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 1535, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.486, ["mapID"] = 627, ["npcID"] = 90463 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90463, ["questType"] = "standard", ["sourceQuests"] = { 45188 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45192] = { ["id"] = 45192, ["name"] = "Runes of Rending", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "My brother and his cultists are engaged in some kind of ritual at the far end of the cave. I tried to intervene, but my brother has left magical wards to block the way. If you can find a way past them, we may be able to stop him in time!", ["objectivesText"] = "Bypass the wards in Felbreach Hollow and confront Raest Magespear. Progress: We must not hesitate!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139773, 140336 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 116175, ["questType"] = "standard", ["sourceQuests"] = { 45190 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45193] = { ["id"] = 45193, ["name"] = "One Step Behind", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "It looks like Raest is out of our reach, but at least his cultists should prove less of a threat. We should return to the Kirin Tor. They should be able to help us plan our next move.", ["objectivesText"] = "Return to Khadgar in the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 116175, ["questType"] = "standard", ["sourceQuests"] = { 45192 }, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45203] = { ["id"] = 45203, ["name"] = "Battle for the Ruins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45203 }, ["objectivesText"] = "Legion Forces repelled", ["rewardGold"] = 468000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Legion Forces repelled", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["db2QuestInfoID"] = 139, ["db2QuestInfoName"] = "Legion Invasion World Quest" },
[45207] = { ["id"] = 45207, ["name"] = "The Nightborne Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 680, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45437, 46335, 46338, 46705 }, ["description"] = "I would be happy to introduce you to my new apprentice if you do not mind traveling a bit. She is currently in the field keeping an eye on an enclave of Felborne resistance fighters who have sworn loyalty to the Legion. As the first nightborne to join the Tirisgarde, I am sure she is eager to prove her skills!", ["objectivesText"] = "Meet Arcanist Ryanna in the Crimson Thicket.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.722, ["y"] = 0.629, ["mapID"] = 735, ["npcID"] = 118242 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 121357, ["x"] = 0.558, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7879 } }, ["questGiverID"] = 118242, ["questType"] = "standard", ["sourceQuests"] = { 46338 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45209] = { ["id"] = 45209, ["name"] = "Those Scrying Eyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44832, 44833 }, ["description"] = "Until recently, Ly'leth was sending magical messages to us regularly from within the Nighthold. She took care to hide these messages - only the most vigilant scryers could have detected them. They could not be within the palace... too much interference from the Nightwell... Of course! The Terrace of Enlightenment! The Duskwatch must have set up a listening post there. Check the scrying orbs for traces of Ly'leth's messages. We must learn what she was trying to tell us!", ["objectivesText"] = "Inspect 4 Duskwatch Scrying Orbs in the Terrace of Enlightenment.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140030, 143536 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115506, ["x"] = 0.548, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44822 }, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45238] = { ["id"] = 45238, ["name"] = "Return to Karazhan: Cubic Cynosure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 45238 }, ["series"] = { 45159, 45160, 45239 }, ["description"] = "Drat! The ancient mana doesn't seem to be working. I need to think the problem through, focus and... Wait, that's it! Focus! We need to focus the energy of the ancient mana to activate the cube. I've heard tell of a mana wyrm in Karazhan with the means to focus its powers. Might be just what we need! Watch out, though. My sources tell me this wyrm is humongous!", ["objectivesText"] = "Obtain a Mana Focus from the Mana Devourer within Karazhan", ["rewardItems"] = { 142536, 143537 }, ["starts"] = { { ["npcID"] = 93538, ["x"] = 0.4124, ["y"] = 0.263, ["mapID"] = 627 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["sourceQuests"] = { 45160 } },
[45239] = { ["id"] = 45239, ["name"] = "Cubic Coalescing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 45239 }, ["series"] = { 45159, 45160, 45238 }, ["description"] = "Success! The cube's magic has been restored! I'm excited to see what it does! Since you did all the legwork, you should have the honor of activating it. Care to give it a try?", ["objectivesText"] = "Activate the Mysterious Cube", ["rewardItems"] = { 142536, 142559 }, ["starts"] = { { ["npcID"] = 93538, ["x"] = 0.4124, ["y"] = 0.263, ["mapID"] = 627 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 93538, ["questType"] = "standard", ["sourceQuests"] = { 45238 } },
[45240] = { ["id"] = 45240, ["name"] = "Making Preparations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "Deathlord, we have uncovered an heirloom of great significance and power. Rimefang's harness has appeared in Icecrown Citadel. We must obtain it, rather than let it fall into the hands of others. I assume you'd like to retrieve the harness personally? We've sent one of our own, Minerva Ravensorrow , ahead to scout. You've met her before, yes? She has impressed us greatly, and we believe she can become quite powerful under your tutelage. I will open a death gate for you. It is best you meet her there.", ["objectivesText"] = "Take the Death Gate near Highlord Darion Mograine , then meet Minerva Ravensorrow .", ["rewardGold"] = 20220, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.27, ["y"] = 0.289, ["mapID"] = 647, ["npcID"] = 113695 } }, ["ends"] = { { ["x"] = 0.27, ["y"] = 0.289, ["mapID"] = 647, ["npcID"] = 113695 } }, ["coords"] = { ["mapID"] = 647, ["x"] = 0.27, ["y"] = 0.289 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 113695, ["questTurnInID"] = 113695, ["questType"] = "standard", ["sourceQuests"] = { 43407, 47137 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
[45243] = { ["id"] = 45243, ["name"] = "On Daumyr's Wings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "The time is nigh, $p. With these new dragons in our army, we are prepared for our assault on the Broken Shore. A large detachment of demons have appeared near one of our camps, and there are far too many of them for any of our allies to overcome. Who better to defeat these demons than those without fear of death? Those with quite the large secret weapon? Take Daumyr . We will meet you there.", ["objectivesText"] = "Ride Daumyr to the Broken Shore.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.27, ["y"] = 0.289, ["mapID"] = 647, ["npcID"] = 113695 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116128, ["x"] = 0.515333, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.515333, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questGiverID"] = 113695, ["questType"] = "standard", ["sourceQuests"] = { 44787 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45251] = { ["id"] = 45251, ["name"] = "Redundancy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 646, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45614 }, ["description"] = "A construct progenitor? What a creative solution to our problem! We probably could channel Kathra'natir's power without releasing him now, but I want to add another layer of protection before we try, just in case. I will not have anyone accusing me of subterfuge! Meet me on the Broken Shore when you are ready.", ["objectivesText"] = "Meet Aethas on the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.723, ["y"] = 0.629, ["mapID"] = 735, ["npcID"] = 118242 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7879 } }, ["questGiverID"] = 118242, ["questType"] = "standard", ["sourceQuests"] = { 46351 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45260] = { ["id"] = 45260, ["name"] = "One Day at a Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38649, 38695, 45271 }, ["description"] = "Thank you for coming, outlander. It is good to see you again. I have a situation in the city that needs your attention, but first... Let us talk of hope. <Thalyssra gestures toward the arcan'dor.> The fruit of the arcan'dor can truly free my people from the Nightwell. However, it only grows so fast. It will take time to distribute this cure. I think it only right that you help me pass out the fruit as it is ready. Please take this, and give it to anyone.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: In time, all of the shal'dorei will be free.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 43568, 43569, 45271 }, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45261] = { ["id"] = 45261, ["name"] = "Continuing the Cure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["series"] = { 45272 }, ["description"] = "Given the events at the Waning Crescent, the refugees here are more eager than ever to receive the gift of the arcan'dor and be free of the Nightwell forever. Fortunately, the tree has borne more fruit. Again, I ask that you honor us by giving this fruit to anyone here in Shal'Aran. When you are finished, we shall discuss further developments within the city. Silgryn reports that Arluelle has proven a fine student, and the two are making progress in evacuating citizens.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: No matter what crises come up, we must stay the course and free my people from their addiction. We take it one day at a time.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44955, 45272 }, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45262] = { ["id"] = 45262, ["name"] = "A Message From Ly'leth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["series"] = { 44742 }, ["description"] = "The arcan'dor bears fruit once again. Just in time, too - Ly'leth has sent us a message, and it seems she may have a lead on Vanthir. He is long overdue for this gift, assuming we manage to find him. Give a fruit to another citizen here in Shal'Aran while I finish decrypting Ly'leth's message.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143487, 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44814, 45277 }, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45263] = { ["id"] = 45263, ["name"] = "Eating Before the Meeting", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["series"] = { 45278 }, ["description"] = "Having Vanthir around has done much to lift the spirits of the people here. I dare say some have begun to relish their newfound freedom, even if they miss their beloved city. I will not rest until I can give it back to them. You and I have an important meeting to attend. Before we go, let us distribute more of the arcan'dor's fruit. I want people to know that although I must leave for now, I have not abandoned them.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45278, 45316 }, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45265] = { ["id"] = 45265, ["name"] = "Feeding the Rebellion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 45280 }, ["description"] = "More nightborne flee Suramar every day to join our cause. Our ranks are swelling, and with the aid of great heroes like yourself and the armies of the Horde and Alliance, our chances have never been better. Help me hand out more fruit of the arcan'dor - each one is a life free from slavish dependence on the Nightwell! Afterwards, we shall speak on how best to assist our new allies in their siege.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44845, 45280 }, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45266] = { ["id"] = 45266, ["name"] = "A United Front", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44738, 44739, 44740, 45281 }, ["description"] = "Our rebel fighters have been armed and morale is high - even the Alliance and Horde elves have ceased their squabbling. We are nearly ready to march on the city. Hand out this week's fruit, and then we can begin preparations.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44790, 45281 }, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45267] = { ["id"] = 45267, ["name"] = "Before the Siege", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44736, 45282 }, ["description"] = "So many years of my life spent studying within the Nighthold... Never had I considered that I would one day have to fight my way back in. Time is short. The battle will be upon us soon. Please, continue our tradition and feed another refugee the fruit of the arcan'dor .", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44740, 45282, 45317 }, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45268] = { ["id"] = 45268, ["name"] = "The Advisor and the Arcanist", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 44918, 44919, 45285 }, ["description"] = "This new First Arcanist appointed by Elisande. This... Andaris. If she is as dangerous as I have heard, then Ly'leth may well be lost. I am sorry, I should not entertain such thoughts. It is just that we have received a troubling message. Help me distribute the latest batch of the arcan'dor fruit, then we will discuss the message.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: Are you ready?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 44833, 45285 }, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45269] = { ["id"] = 45269, ["name"] = "A Taste of Freedom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44719, 44964, 45269 }, ["series"] = { 45287 }, ["description"] = "We are as ready as we will ever be. Once we put Valtrois' plan into action, we can attack the Sanctum of Order and put an end to Andaris. She will never expect us to have trained our withered against fel magic, and her hubris will be her downfall. Come, let us feed the people one last time.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: Even if our failure means their doom, they deserve a taste of freedom, no matter how fleeting.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45064, 45287 }, ["questLines"] = { { ["id"] = 292, ["name"] = "Breaking the Nighthold", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 292, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45271] = { ["id"] = 45271, ["name"] = "Insurrection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45271 }, ["series"] = { 38649, 38695, 45260 }, ["description"] = "First Arcanist Thalyssra has received dark tidings regarding the Nightfallen rebellion and requires your assistance. Journey to Shal'Aran in Suramar and meet with her.", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 63889, 63890 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45260 } },
[45272] = { ["id"] = 45272, ["name"] = "Insurrection: Missing Persons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45272 }, ["series"] = { 45261 }, ["description"] = "First Arcanist Thalyssra has requested your aid in searching for her missing people. She has a lead from a very unexpected ally. Meet with her at Shal'Aran in Suramar .", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45261 } },
[45277] = { ["id"] = 45277, ["name"] = "Insurrection: Waxing Crescent", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45277 }, ["description"] = "First Arcanist Thalyssra has sent word: there has been communication from Ly'leth. Your help is needed. Journey to Shal'Aran in Suramar and lend what aid you can.", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45262 } },
[45278] = { ["id"] = 45278, ["name"] = "Insurrection: An Elven Problem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45278 }, ["series"] = { 45263 }, ["description"] = "The Alliance and Horde have arrived in Suramar . First Arcanist Thalyssra needs your help in providing an introduction. Meet with Thalyssra in Shal'Aran.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45263 } },
[45280] = { ["id"] = 45280, ["name"] = "Insurrection: Crafting War", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45280 }, ["series"] = { 45265 }, ["description"] = "Refugees are flooding in to Shal'Aran, and many are willing to fight for Thalyssra's rebel army. They need weapons, training and help from anyone who can provide it. Go to Shal'Aran and lend your assistance.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45265 } },
[45281] = { ["id"] = 45281, ["name"] = "Insurrection: March on Suramar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45281 }, ["series"] = { 44738, 44739, 44740, 45266 }, ["description"] = "First Arcanist Thalyssra has sent word: the time has come to launch our assault on Suramar . The elven armies of the Horde, Alliance, Kirin Tor and Nightfallen are assembled. They only await your arrival to begin their assault. Report to Shal'Aran and meet with First Arcanist Thalyssra and prepare for battle.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45266 } },
[45282] = { ["id"] = 45282, ["name"] = "Insurrection: Elisande's Retort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45282 }, ["series"] = { 44736, 45267 }, ["description"] = "The combined forces of the elves stand ready to begin their siege on the gates of the Nighthold. Report to First Arcanist Thalyssra in Shal'Aran to begin the siege.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45267 } },
[45285] = { ["id"] = 45285, ["name"] = "Insurrection: As Strong As Our Will", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45285 }, ["series"] = { 44918, 44919, 45268 }, ["description"] = "In the wake of Elisande's attack, the need is stronger than ever to add to the ranks of the Nightfallen rebellion. Plans are in motion that may help with this in an unconventional way. Report to First Arcanist Thalyssra in Shal'Aran for more details.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45268 } },
[45287] = { ["id"] = 45287, ["name"] = "Insurrection: Breaking the Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45287 }, ["series"] = { 45269 }, ["description"] = "First Arcanist Thalyssra sends word that her forces are ready. It is time for you to lead the attack against the Nighthold. Report to Shal'Aran in Suramar for details.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["nextQuests"] = { 45269 } },
[45291] = { ["id"] = 45291, ["name"] = "Return to Karazhan: Book Wyrms", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45291 }, ["series"] = { 45292, 45293, 45294, 45295 }, ["description"] = "My incorporeal condition has allowed me to enter the tower safely for the first time. I must say, it's a bit of a shambles in there! I could use some help tackling my cleaning checklist. We should start with the library. All those musty tomes are bound to attract mana wyrms! Please shelve any books that have fallen to the floor, or worse, taken flight. And if you find mana wyrms nibbling at the pages... step on them!", ["objectivesText"] = "Clean up the Karazhan Library. Progress: How did it go?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 143551, 143552, 143555, 143556 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 44734, 44735 }, ["db2QuestSortName"] = "Day of the Dead" },
[45292] = { ["id"] = 45292, ["name"] = "Return to Karazhan: Rebooting the Cleaner", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45292 }, ["series"] = { 45291, 45293, 45294, 45295 }, ["description"] = "The Guardian Medivh created the Curator to watch over Karazhan, but I fear the unit is behaving erratically. Prolonged periods of operation may have caused a malfunction. Please go up to the Menagerie and disable the Curator . Also, search the area for a box of spare motivator crystals and return to me. Even with my basic knowledge I should be able to replace its motivator, and we can enlist the Curator 's help in cleaning up the tower.", ["objectivesText"] = "Disable the Curator and find the Box of Spare Motivator Crystals. Progress: Did you find the box of spares?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 142460, 142461, 143549, 143551, 143552, 143555, 143556 }, ["rewardChoices"] = { 142461 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 45291 }, ["db2QuestSortName"] = "Day of the Dead" },
[45293] = { ["id"] = 45293, ["name"] = "Return to Karazhan: New Shoes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45293 }, ["series"] = { 45291, 45292, 45294, 45295 }, ["description"] = "Thus far my Karazhan cleanup project hasn't exactly been a rousing success. Time to try something new. New, as in new shoes... horseshoes , that is! A box of horseshoes was left outside the tower. It's a problem finding a delivery person willing to set foot inside... mortality rates being what they are. If you would, grab the crate and take it to Koren in the stables. Just be careful passing Attumen. The huntsman doesn't take kindly to outsiders.", ["objectivesText"] = "Deliver the Box of 'New' Horseshoes to Koren the Blacksmith in Karazhan. Progress: How did it go?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 143550, 143551, 143552, 143555, 143556 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 45292 }, ["db2QuestSortName"] = "Day of the Dead" },
[45294] = { ["id"] = 45294, ["name"] = "Return to Karazhan: High Stress Hiatus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45294 }, ["series"] = { 45291, 45292, 45293, 45295 }, ["description"] = "The new plays in the opera house have been well received by everyone... except cast members of the older shows. Egos are bruised and tensions are running high! Romulo and Julianne are ready to poison each other. Tinhead is rusting with tears over his lack of adoration. Little Red's cape was stolen by a disgruntled understudy, who ran off to play chess of all things. Actors, am I right? We need them ready to perform in case the audience demands a revival. Please, help me calm their nerves!", ["objectivesText"] = "Help Darius soothe the old casts egos by finding a Positive Review amongst the audience members to simmer tensions between Romulo and Julianne, stealing a Bouquet of Roses from one of the new acts for Tinhead's vanity and finding where the understudy stashed Little Red's cape in the Chess room. Progress: How did it go?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 142461, 142468, 143551, 143552, 143555, 143556 }, ["rewardChoices"] = { 142468 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 45293 }, ["db2QuestSortName"] = "Day of the Dead" },
[45295] = { ["id"] = 45295, ["name"] = "Return to Karazhan: Clearing Out the Cobwebs", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45295 }, ["series"] = { 45291, 45292, 45293, 45294 }, ["description"] = "I admit it... even as a spirit, I am deathly afraid of spiders. All those legs! Dripping fangs! Sticky webs coming out of their... <Darius does a squirming sort of shimmy that is uncomfortable to watch.> I'm sure a world-saving hero like you doesn't mind them, though. Which is good, since a whole brood of spiders has taken over the Servant's Quarters. You'll handle this, right? If you don't get them all, they'll keep multiplying.", ["objectivesText"] = "Clean out spiders from the Servant's Quarters.", ["rewardGold"] = 1180000, ["rewardXP"] = 12280, ["rewardItems"] = { 122451, 132444, 132466, 142469, 142552, 143551, 143552, 143555, 143556 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 8443 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 45294 } },
[45296] = { ["id"] = 45296, ["name"] = "No Bones About It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45296 }, ["description"] = "The Charred Bone Fragments still smolder with ancient power. Darius would be extremely interested in examining them and hearing of your defeat of Nightbane.", ["objectivesText"] = "Take the Charred Bone Fragments to Darius.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 142468, 142469, 143556 }, ["rewardChoices"] = { 142469 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["sourceQuests"] = { 45295 }, ["db2QuestSortName"] = "Day of the Dead", ["startItems"] = { 143556 } },
