[45331] = { ["id"] = 45331, ["name"] = "Return to Acherus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8529, ["mapID"] = 647, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "You've grown a lot since we last met, <name>. Now that we have the harness, let's see if Mograine has a plan to use it.", ["objectivesText"] = "Return to Highlord Darion Mograine in Acherus.", ["rewardGold"] = 33800, ["rewardXP"] = 770, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.192, ["mapID"] = 823, ["npcID"] = 119539 } }, ["ends"] = { { ["x"] = 0.478, ["y"] = 0.192, ["mapID"] = 823, ["npcID"] = 119539 } }, ["coords"] = { ["mapID"] = 823, ["x"] = 0.478, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8529 } }, ["questGiverID"] = 119539, ["questTurnInID"] = 119539, ["questType"] = "standard", ["sourceQuests"] = { 45398, 45399 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647 },
