[45339] = { ["id"] = 45339, ["name"] = "Defense of the Fel Hammer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["description"] = "We need to get back to the Fel Hammer ASAP!", ["objectivesText"] = "Use the Illidari Gateway to return to the Fel Hammer.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["x"] = 0.742, ["y"] = 0.417, ["mapID"] = 719, ["npcID"] = 116448 } }, ["ends"] = { { ["x"] = 0.742, ["y"] = 0.417, ["mapID"] = 719, ["npcID"] = 116448 } }, ["coords"] = { ["mapID"] = 719, ["x"] = 0.742, ["y"] = 0.417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 116448, ["questTurnInID"] = 116448, ["questType"] = "standard", ["sourceQuests"] = { 45329, 45330 }, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[45342] = { ["id"] = 45342, ["name"] = "Administering Aid", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 650, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "Unfortunately, it would seem many of your allies have already taken to fighting on these fel corrupted shores. They will never be able to gain the upper hand in battle while so many are suffering from the contagion. Take the counteragent and use it to administer aid to your allies. Roland and I will handle the injuries here.", ["objectivesText"] = "Apply the Contagion Counteragent to sickly Legionfall Fighters .", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 143773 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 118528, ["x"] = 0.298, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 646, 650 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45349 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45343] = { ["id"] = 45343, ["name"] = "A Curious Contagion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["series"] = { 45344 }, ["description"] = "It has been brought to my attention that a rather curious contagion is spreading through a small coastal region within Highmountain. The local tribes have abandoned the area for fear of catching this ailment that currently has no known cure. One of our own was traveling through the area when her companion fell ill. She has requested the Conclave's assistance. Seek her out, High Priest, and do whatever you can to stop this sickness from spreading.", ["objectivesText"] = "Find Aelthalyste in Highmountain.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.51, ["y"] = 0.484, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 43420, 47137 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[45344] = { ["id"] = 45344, ["name"] = "Sampling the Source", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["series"] = { 45343 }, ["description"] = "My companion has fallen terribly ill, as you can see. He must have caught whatever these taurens had. Their entire camp has been wiped out! It appears to be fel in origin, and impervious to all known treatments. I've been working tirelessly to find a cure, but I don't think Roland here has much time left. I could use an extra hand. Some samples from the source should speed things up. Just be sure to avoid direct contact with the contagion. Levitate should be helpful.", ["objectivesText"] = "Collect Contaminated Specimens from pools of Gaseous Fel around the western coast of Highmountain. Progress: Do you have the samples I've requested?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143654 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45343 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[45345] = { ["id"] = 45345, ["name"] = "Mischievous Sprites", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "It's a little-known secret that the dust sprites use for their various tricks has restorative properties. Some within the alchemy community balk at this claim, but they only refute it because they've never been able to get their hands on the rare ingredient. Sprites often shroud themselves in illusions to avoid detection. The nearby goats have a curious shimmer about them that suggests they may be sprites in disguise. Dispel whatever magic surrounds them to reveal their true form.", ["objectivesText"] = "Use Dispel Magic on Soothoof Hillstriders to reveal Mischievous Sprites and collect their Shimmering Dust . Progress: Have you acquired the Shimmering Dust I so desperately need?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143678 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45343 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[45346] = { ["id"] = 45346, ["name"] = "Shambling Specimens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "This fel contagion appears to have three stages. The first is marked by a persistent, phlegmy cough. The second shows the skin turning a sickly shade of green. The third involves a complete transformation where the victim turns into a mindless corpse. It is within this stage that I believe the most information about the sickness can be gathered. I have a contraption that can safely store the specimens, but they will need to be shackled before they can be collected.", ["objectivesText"] = "Use Shackle Undead on Shambling Corpses in order to collect specimens with the Corpse Collector .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143718 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45343 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[45347] = { ["id"] = 45347, ["name"] = "Crafting a Cure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "I used what you gathered for me to craft what I hope will be a reliable cure. The only thing that's missing is some powerful magic, which I hope you'll be able to provide. The concoction is there on my alchemy table. Please hurry, <name>. Roland grows weaker by the minute.", ["objectivesText"] = "Infuse the Untested Cure with magic before administering it to Roland Abernathy . Progress: I will do whatever it takes to find a cure for this contagion.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45344, 45345, 45346 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[45348] = { ["id"] = 45348, ["name"] = "Safekeeping", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "It would seem that a delicate balance of holy and shadow magic is the key to curing this contagion. Obviously the remedy will need a bit of work to reduce undesired side effects, like dying. In the meantime, take the counteragent back to Netherlight Temple and keep it safe. I will work diligently on discovering the source of this contagion.", ["objectivesText"] = "Take the Contagion Counteragent to Alonsus Faol in Netherlight Temple. Progress: What do we have here?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 87370, 87371, 87372, 87373, 87374, 87375, 87376, 87377, 87378, 143736 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 118528, ["questType"] = "standard", ["sourceQuests"] = { 45347 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[45349] = { ["id"] = 45349, ["name"] = "To the Broken Shore", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["series"] = { 45350 }, ["description"] = "We've received word from those fighting on the Broken Shore. It seems the source of the contagion can be pinpointed to a specific island off the western coast. Many of our allies have already been infected. We must work quickly to ensure that the contagion doesn't spread.", ["objectivesText"] = "Head to the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292 }, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.485, ["mapID"] = 702, ["npcID"] = 110564 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7834 } }, ["questGiverID"] = 110564, ["questType"] = "standard", ["sourceQuests"] = { 45348 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45350] = { ["id"] = 45350, ["name"] = "Countering the Contagion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["series"] = { 45349 }, ["description"] = "I have tracked the source of the contagion to these very shores. The Burning Legion are using fel spreaders to pump out infectious fel creep, causing anyone who comes into contact with it to become sick. Take out Ozzuk the Corrupter and his fel spreaders so that the contagion can be contained.", ["objectivesText"] = "Counter the contagion by killing Ozzuk the Corrupter and destroying his fel spreaders .", ["rewardGold"] = 477360, ["rewardXP"] = 7675, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45349 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45354] = { ["id"] = 45354, ["name"] = "Dispersion of the Discs", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "These discs are radiating with power! It must be their proximity to one another. We must take them from here should they resonate further and cause a catastrophe in these sacred halls. I'll send them to the one place I know where we can reign their energies in, preventing any sort of explosion. I'm speaking of the Eye of Eternity. There we will be able to safely finish what Antonidas was unable to complete. Speak with me again when you're ready to leave.", ["objectivesText"] = "Complete the trial to purge the excess energy from within the disc fragments.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 2880, 2901, 3466, 3857, 5956, 18567, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143633, 143634, 143635, 143636, 143638, 143639, 143640, 143641, 143642 }, ["starts"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.563, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108247, ["questTurnInID"] = 108247, ["questType"] = "dungeon", ["sourceQuests"] = { 45845, 45846, 45847 }, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
