[45372] = { ["id"] = 45372, ["name"] = "Fate of the Nightborne", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45372 }, ["description"] = "Shortly after your victorious return from the Nighthold, urgent business took Thalyssra back to the palace. She has requested that you meet her there. Speak to me when you are prepared to join her.", ["objectivesText"] = "Speak to Oculeth and meet Thalyssra in the Nighthold. Progress: Thank you for coming.", ["rewardItems"] = { 142436, 156487 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45420 } },
