[45381] = { ["id"] = 45381, ["name"] = "The Nighthold: Talisman of the Shal'dorei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8025, ["storyline"] = { 45381 }, ["description"] = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", ["objectivesText"] = "Collect 4 Echoes of Time from Elisande in The Nighthold on Normal Difficulty. Progress: Without the talisman we must fight through the city proper.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 141324, 141325, 141326, 143656 }, ["starts"] = { { ["npcID"] = 110791 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8025 } }, ["questGiverID"] = 110791, ["questType"] = "raid" },
