[45385] = { ["id"] = 45385, ["name"] = "We Must be Prepared!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 45764 }, ["description"] = "The Legion ships are gone, for now. It's only a matter of time before they attack again, and we must be prepared. We need to get going on repairs immediately! Lady S'theno took the lead on the search for parts. That one will do anything to remain on solid ground, ha! She is waiting for you on the Broken Shore.", ["objectivesText"] = "Talk to Lady S'theno at the Illidari Camp on the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.596, ["y"] = 0.588, ["mapID"] = 720, ["npcID"] = 108311 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 8022 } }, ["questGiverID"] = 108311, ["questType"] = "standard", ["sourceQuests"] = { 45339 }, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
