[45392] = { ["id"] = 45392, ["name"] = "Dark Memento", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 45392 }, ["description"] = "The flowers were... a nice gesture. <Velonara sniffs one of the black roses.> I have a spare hood. Nothing fancy, but perhaps Moorgoth would like to have it. Just don't let him get his hopes up or anything. I'm merely repaying a kindness. I would appreciate it if you kept all this between us. Giving presents to admirers falls a bit outside the dark ranger rules of conduct.", ["objectivesText"] = "Bring Velonara's spare hood to Death Hunter Moorgoth .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 3420, 143663 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 105099, ["x"] = 0.483143, ["y"] = 0.456905 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 100633, ["x"] = 0.522, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.483143, ["y"] = 0.456905 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
[45397] = { ["id"] = 45397, ["name"] = "Fire the Cannons!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45397 }, ["description"] = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me. Ughh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete! See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45397)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45397))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Slay 14 demons.", ["rewardItems"] = { 142390 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45398] = { ["id"] = 45398, ["name"] = "Harnessing Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8529, ["mapID"] = 823, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "These fools are using the power of Rimefang's harness to subjugate the frost wyrms. Their leader, Andjor, sits inside on the back of the broodmother and mocks us. He should breathe no longer.", ["objectivesText"] = "Kill Andjor Dragontamer and retrieve Rimefang's Harness . Progress: This harness will bring us great power!", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 143676 }, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.192, ["mapID"] = 823, ["npcID"] = 119539 } }, ["ends"] = { { ["x"] = 0.478, ["y"] = 0.192, ["mapID"] = 823, ["npcID"] = 119539 } }, ["coords"] = { ["mapID"] = 823, ["x"] = 0.478, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8529 } }, ["questGiverID"] = 119539, ["questTurnInID"] = 119539, ["questType"] = "standard", ["sourceQuests"] = { 45240 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1692, ["db2PoiUiMapID"] = 823 },
[45399] = { ["id"] = 45399, ["name"] = "Severing the Sveldrek", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8529, ["mapID"] = 823, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "So here's the order of things, as far as I've been told. Mortal walks into Icecrown. Mortal is brutally defeated. Mortal gets raised as Scourge. These fools can't expect to trounce in here, do whatever they want, and leave without any consequence. Time to make them truly as mindless as they act.", ["objectivesText"] = "Kill and raise 8 Sveldrek vrykul.", ["rewardGold"] = 163320, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.478, ["y"] = 0.192, ["mapID"] = 823, ["npcID"] = 119539 } }, ["ends"] = { { ["x"] = 0.478, ["y"] = 0.192, ["mapID"] = 823, ["npcID"] = 119539 } }, ["coords"] = { ["mapID"] = 823, ["x"] = 0.478, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8529 } }, ["questGiverID"] = 119539, ["questTurnInID"] = 119539, ["questType"] = "standard", ["sourceQuests"] = { 45240 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1692, ["db2PoiUiMapID"] = 823 },
[45404] = { ["id"] = 45404, ["name"] = "Panic at the Brewery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45459, 45574 }, ["description"] = "We were not prepared for a surprise attack. I fear Brewmaster Blanche has been captured, or worse... Please help me, Grandmaster!", ["objectivesText"] = "Help Almai find Brewmaster Blanche and defend Stormstout Brewery.", ["rewardXP"] = 7675, ["rewardItems"] = { 143731 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 116900 } }, ["ends"] = { { ["x"] = 0.513, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 116900 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.513, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 116900, ["questTurnInID"] = 116900, ["questType"] = "standard", ["sourceQuests"] = { 45440 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[45405] = { ["id"] = 45405, ["name"] = "Breaching the Sanctum", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45405 }, ["description"] = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area. Take these telemancy orbs . If you find you need support, use them to summon Withered. We must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(45405)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(45405))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Speak with Oculeth to start the assault.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142118, 143747, 249783, 254267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45406] = { ["id"] = 45406, ["name"] = "The Storm's Fury", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45406, 45839, 46110 }, ["series"] = { 45839 }, ["description"] = "No longer do we have time to prepare, the moment of action is upon us! Come with me, little one. With you guiding my aim we shall cleanse this isle by thunder and lightning!", ["objectivesText"] = "Destroy the Burning Legion forces within Shield's Rest.", ["rewardGold"] = 309800, ["rewardXP"] = 1060, ["rewardItems"] = { 190454, 197921 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116868, ["x"] = 0.9, ["y"] = 0.11 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 118778, ["x"] = 0.816, ["y"] = 0.072 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.9, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 45839 }, ["questLines"] = { { ["id"] = 305, ["name"] = "Legion Assault - Stormheim", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[45412] = { ["id"] = 45412, ["name"] = "Protection: Aid of the Illidari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863 }, ["series"] = { 45413, 45414, 45415, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city. Kor'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks. I do not entirely trust these 'demon hunters', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more. Specialization: Protection Warrior", ["objectivesText"] = "Find Kor'vas Bloodthorn in the streets of Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.228, ["y"] = 0.402, ["mapID"] = 627, ["npcID"] = 90431 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90431, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47030 }, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45413] = { ["id"] = 45413, ["name"] = "Gathering Information", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["series"] = { 45412, 45414, 45415, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "The Legion has sent one demon after another to try to break into the Kirin Tor vaults in the city, but we don't know what they're after. Looks like they finally made it in. We need to find out what was taken, and quickly, before they get a chance to put whatever it is to use. Probe any survivors for information - I'll use my spectral sight to make sure there aren't still any straggling demons lurking about.", ["objectivesText"] = "Question citizens in the Bank of Dalaran to find out what was stolen. Progress: We can't risk another attack until we get to the bottom of this.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 30383, 30384, 30386, 30397 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["sourceQuests"] = { 45412, 46314, 47022, 47023, 47024, 47025 }, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45414] = { ["id"] = 45414, ["name"] = "Confirming Suspicions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["series"] = { 45412, 45413, 45415, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "That heart is the last remaining piece of Highlord Kruul - once one of the Legion's best warlords. Many years ago Kruul's armies nearly descended upon the Dark Portal to crush the Azerothian assault on Outland. We Illidari intercepted before he could strike. I fear that the Legion aims to use the heart to hasten Kruul's resurrection in the nether. We must find the Prophet Velen at once - only he can tell us for sure.", ["objectivesText"] = "Find Prophet Velen in Dalaran. Progress: This is deeply concerning.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 116880, ["questType"] = "standard", ["sourceQuests"] = { 45413 }, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45415] = { ["id"] = 45415, ["name"] = "Between Worlds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["series"] = { 45412, 45413, 45414, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "Kruul boasts damnation, but his power has not yet fully manifested. His minions have taken his heart to hasten his rebirth in the nether. We do not have much time. Go to the place of Kruul's fall at the Stair of Destiny in desolate Outland, where the link to his soul is strongest. There you must pry open the way to his realm. I must prepare for the battle to come. Good luck, champion.", ["objectivesText"] = "Establish a portal to the Twisting Nether at the Stair of Destiny in Outland. Progress: Lord Illidan led us into glorious battle against Kruul long ago. Now you must do the same.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 137677 }, ["starts"] = { { ["x"] = 0.748, ["y"] = 0.456, ["mapID"] = 627, ["npcID"] = 117042 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questGiverID"] = 117042, ["questType"] = "standard", ["sourceQuests"] = { 45414 }, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 100 },
[45416] = { ["id"] = 45416, ["name"] = "The Highlord's Return", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45416 }, ["series"] = { 45905 }, ["description"] = "I have a missive for you from Kor'vas, as well as instructions for getting you there. I can teleport you to them to begin the fight, but you will need some Nethershards to force your way into the Twisting Nether. When you have enough, speak with me and you can begin.", ["objectivesText"] = "The Highlord's Return is the Mage Tower Tank Challenge, available during Legion Timewalking. The following specs can complete this challenge: Blood Death Knight, Vengeance Demon Hunter, Guardian Druid, Brewmaster Monk, Protection Paladin, and Protection Warrior. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our Mage Tower Tank Challenge Guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Defeat Highlord Kruul in the Twisting Nether. Speak with War Councilor Victoria to get there.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 109076, 120257, 127844, 127849, 132367, 132376, 132443, 132444, 132452, 133571, 133576, 133644, 137015, 137016, 137017, 137025, 137056, 137070, 137079, 137089, 137107, 137108, 137312, 137315, 137419, 138949, 139324, 140587, 140789, 140790, 140799, 142117, 142406, 142508, 147278, 151636, 151795, 151976, 152626 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117871, ["questType"] = "standard" },
[45417] = { ["id"] = 45417, ["name"] = "The Nighthold: Lord of the Shadow Council", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 45417 }, ["series"] = { 44719, 45420 }, ["description"] = "As we speak, Gul'dan is using the Nightwell's power to pull Sargeras into our world. Gather your companions and fight your way to the top of The Nighthold . I will prepare Light's Heart and join you when the time is right. Together, we will put an end to Gul'dan once and for all.", ["objectivesText"] = "Defeat Gul'dan in The Nighthold .", ["rewardItems"] = { 142436, 143757 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115367, ["x"] = 0.433, ["y"] = 0.607 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115367, ["x"] = 0.433, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.433, ["y"] = 0.607 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questTurnInID"] = 115367, ["questType"] = "raid", ["sourceQuests"] = { 44719 } },
[45420] = { ["id"] = 45420, ["name"] = "The Nighthold: The Eye of Aman'Thul", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["storyline"] = { 45420 }, ["series"] = { 44719, 45417 }, ["description"] = "The battle is won, but the war is far from over. In order to stem the tide of demons flooding into Azeroth, we must use the Pillars of Creation to seal the Tomb of Sargeras. <Khadgar peers down at the Eye of Aman'Thul.> That... might be difficult to carry. Perhaps I can use the power of the Eye itself to teleport it to Dalaran. I suppose there is only one way to find out!", ["objectivesText"] = "Aid Khadgar in transporting the Eye of Aman'Thul.", ["rewardItems"] = { 142436 }, ["starts"] = { { ["npcID"] = 106522 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8025 } }, ["questGiverID"] = 106522, ["questType"] = "raid", ["sourceQuests"] = { 45417 } },
[45423] = { ["id"] = 45423, ["name"] = "Wailing Critters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["storyline"] = { 45423 }, ["series"] = { 45540 }, ["description"] = "I'm glad you're here, <name>. Tiny wails have been heard in the caverns for some time since Naralex was awakened. At first, we suspected that some deviate critters had survived. Upon further investigation, we found them to be growing and multiplying beyond our wildest expectations. The corpse of Verdan the Everliving may have something to do with it, we're not sure. That's why we're sending you in. I've also seen suspicious footprints leading into the caverns recently. We may not be alone, be careful.", ["objectivesText"] = "Defeat the Budding Everliving Spore in Wailing Caverns. Progress: Have you completed your investigation the Wailing Caverns?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 86143, 117354, 122457, 143753 }, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.682, ["mapID"] = 10, ["npcID"] = 116781 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.682, ["mapID"] = 10, ["npcID"] = 116781 } }, ["coords"] = { ["mapID"] = 10, ["x"] = 0.388, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17 } }, ["questGiverID"] = 116781, ["questTurnInID"] = 116781, ["questType"] = "standard", ["sourceQuests"] = { 45540 } },
[45425] = { ["id"] = 45425, ["name"] = "Grovebound", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 46675, 46677 }, ["description"] = "Now THAT was some good stuff right there. Now that we've taken out the commander, the druids and the ancients should be safe for a while. Revenge was an added bonus. We should get back to Rensar and tell him what we accomplished.", ["objectivesText"] = "Return to Rensar Greathoof in the Dreamgrove.", ["rewardGold"] = 119340, ["rewardXP"] = 3070, ["rewardItems"] = { 147461 }, ["starts"] = { { ["npcID"] = 120070 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 120070, ["questType"] = "standard", ["sourceQuests"] = { 46677 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[45426] = { ["id"] = 45426, ["name"] = "Nature's Advance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45498, 45528, 46674, 46924 }, ["description"] = "<name>, you must return to the Dreamgrove and bring the news of my attack. Tell the other druids that aggressions such as this will continue against us unless we find a way to stop the Legion. I thank you for the aid. I feel the fel energies leaving my veins, though it may take some time.", ["objectivesText"] = "Return to Rensar Greathoof in the Dreamgrove.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 115750, ["x"] = 0.687, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 115750, ["x"] = 0.687, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questTurnInID"] = 115750, ["questType"] = "standard", ["sourceQuests"] = { 46924 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
