[45437] = { ["id"] = 45437, ["name"] = "An Urgent Situation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 46335, 46338, 46705 }, ["description"] = "Archmage, ! We have an important guest. Please meet me in my chamber when you have a moment.", ["objectivesText"] = "Find Meryl's visitor in the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["sourceQuests"] = { 43415, 47137 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
