[45440] = { ["id"] = 45440, ["name"] = "A Brewing Situation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "Greetings, Grandmaster. I'm an expert at producing tricky brews, and Almai and I have been working with Stormstout Brewery to craft Storm Brew for the order. In fact, we have already begun production! That calls for a party, don't you think? We brought enough of my prized Celebration Brew for everyone!", ["objectivesText"] = "Direct the Stormstout Brewers to distribute Celebration Brew to the temple balcony, in front of the Laughing Crane, and near the troop training grounds. Progress: Whew. Celebration brew is..*hic* shtronger than I remembered it to be. *urp*", ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.514, ["y"] = 0.486, ["mapID"] = 709, ["npcID"] = 116929 } }, ["ends"] = { { ["x"] = 0.514, ["y"] = 0.486, ["mapID"] = 709, ["npcID"] = 116929 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.514, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 116929, ["questTurnInID"] = 116929, ["questType"] = "standard", ["sourceQuests"] = { 43359, 47137 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[45441] = { ["id"] = 45441, ["name"] = "Adacic Grubs - REWORK", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45441 }, ["description"] = "Your request to harvest wood does not seem unreasonable, . There is something you can do for me, too. There is a species of moth whose grubs feed on trees. Normally their numbers are too low to cause damage, but once a century they reproduce in overwhelming numbers. They have just begun their mass emergence. All of my keepers are fighting the nightmare and cannot be spared. I fear I am unable to protect the forest giants on my own. Will you stomp the grubs out?", ["objectivesText"] = "Stomp out 50 Adacic Grubs", ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45442] = { ["id"] = 45442, ["name"] = "Not Felling Well", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 46320 }, ["description"] = "Let's see... Yseralline Seed for healing, Bruiseweed for curing poison, and Elemental Earth for disease resistance. Oh and just a touch of ground Felwort for attunement. Yes, I think this will counteract the Legion's poison. It will probably taste terrible, but what medicine doesn't? Hurry, Grandmaster <name>. Our most stricken friends don't have much time left.", ["objectivesText"] = "Use Blanche's Still and then give the Curative Brew to 8 Fel-Poisoned Initiates. Progress: Did our Curative Brew work?", ["rewardXP"] = 6140, ["rewardItems"] = { 146401 }, ["starts"] = { { ["x"] = 0.505, ["y"] = 0.578, ["mapID"] = 709, ["npcID"] = 119765 } }, ["ends"] = { { ["x"] = 0.505, ["y"] = 0.578, ["mapID"] = 709, ["npcID"] = 119765 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.505, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 119765, ["questTurnInID"] = 119765, ["questType"] = "standard", ["sourceQuests"] = { 46320 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[45449] = { ["id"] = 45449, ["name"] = "Alchemist Korlya", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "The zealots within the Garrison of the Fel are led by Alchemist Korlya . It seems likely that's the Felskorn Brewmaster Blanche observed poisoning our brew. Please kill her.", ["objectivesText"] = "Kill Alchemist Korlya .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45459 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45459] = { ["id"] = 45459, ["name"] = "Storming the Legion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45404, 45574 }, ["description"] = "I did my best to fight the demons off, but there were too many even for my skill... As I lay dying, I overheard the dreadlord commanding a Felskorn alchemist to contaminate my brew and then return to the Broken Shore. If you could acquire some of the poison, I'm sure we can concoct an antidote!", ["objectivesText"] = "Talk to Tak-tak to travel to the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.515, ["y"] = 0.485, ["mapID"] = 709, ["npcID"] = 119765 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7902 } }, ["questGiverID"] = 119765, ["questType"] = "standard", ["sourceQuests"] = { 45404 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 2, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
