[45482] = { ["id"] = 45482, ["name"] = "Arcane: Fate of the Tideskorn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340 }, ["series"] = { 47033, 47034 }, ["description"] = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion. It complicates matters that this vrykul may in fact be Skovald's heir. Take the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start. Specialization: Arcane Mage", ["objectivesText"] = "Search Jandvik for the vrykul mentioned in the scrolls.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 144457 }, ["starts"] = { { ["x"] = 0.226, ["y"] = 0.392, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47033 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45486] = { ["id"] = 45486, ["name"] = "The Reluctant Queen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "Wait, how is it you know about my parentage? Be careful what you say around here, there are those who would hunt me down if they knew my bloodline. I don't know who you are, nor do I believe I'm part of any prophecy. However, if you seek to undo the damage my father has wrought on the Tideskorn, then I feel obliged to assist you. Meet me in Valdisdall, <class>. From there we can make our way to Skold-Ashil and request an audience with Eyir . Perhaps she can shed some light on this prophecy.", ["objectivesText"] = "Bring Sigryn before Eyir in Skold-Ashil.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 116568, ["questType"] = "standard", ["sourceQuests"] = { 45482, 47049, 47050, 47051, 47052 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 640 },
[45498] = { ["id"] = 45498, ["name"] = "Let Sleeping Dogs Lie", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45528, 46674, 46924 }, ["description"] = "You see those big eredar guys? That's the barrow that Goldrinn is in! I don't know what the Legion is doing to him in there, but I'm sure we don't want them to succeed. Let's get in there and save Goldrinn !", ["objectivesText"] = "Save Goldrinn from the Stormrage Barrow Dens. Progress: Who knows what the Legion could be doing to Goldrinn !", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questTurnInID"] = 120032, ["questType"] = "standard", ["sourceQuests"] = { 44921 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80 },
[45520] = { ["id"] = 45520, ["name"] = "Behind Enemy Portals", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45520 }, ["objectivesText"] = "Demonic Portal entered Demon commander assassinated", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 253178 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Demonic Portal entered", ["amount"] = 1, ["type"] = 0, ["objectID"] = 117100, ["orderIndex"] = 0 }, { ["text"] = "Demon commander assassinated", ["amount"] = 1, ["type"] = 0, ["objectID"] = 117092, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[45522] = { ["id"] = 45522, ["name"] = "To Silence the Bonespeakers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "Sigryn's claim to the throne will be challenged by two rivals - Runeseer Faljar of the Bonespeakers and Jarl Velbrand of the Drekirjar. I would begin in Haustvald with the Runeseer. He was a close ally of Skovald and is a powerful mystic. With the Bonespeakers at his charge, he would prove a staunch opponent if he cannot be made to yield. Go now, and claim your destiny in the name of the Valkyra!", ["objectivesText"] = "Defeat Runeseer Faljar in Haustvald.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.65, ["y"] = 0.68, ["mapID"] = 634, ["npcID"] = 93628 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 117199, ["x"] = 0.73, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questGiverID"] = 93628, ["questType"] = "standard", ["sourceQuests"] = { 45486 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[45523] = { ["id"] = 45523, ["name"] = "To Tame the Drekirjar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "The Bonespeaker's words trouble me, outsider. The darkness he speaks of, Skovald's fel curse, could he have passed it onto me somehow? No, it cannot be so. The Runeseer must be mistaken... Come, the next challenger awaits. I will no doubt need your assistance bringing him to heel as well.", ["objectivesText"] = "Defeat Jarl Velbrand in Hrydshal.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 117227, ["x"] = 0.412, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 45522 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[45524] = { ["id"] = 45524, ["name"] = "The Forgotten Heir", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "My brother... lives? The last time I saw him, the assassins were closing in on him. I can't imagine how he defeated them... We should travel to Vrekt. I would look upon my brother with my own eyes.", ["objectivesText"] = "Find Torvald in Vrekt. Progress: Let us go to Vrekt.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141605, 142487 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["sourceQuests"] = { 45523 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[45525] = { ["id"] = 45525, ["name"] = "Unanswered Questions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "What is done, is done. There are none left to challenge the throne of the Tideskorn. My brother's words still haunt me, though. If Eyir knows who ordered my family killed, I deserve to know it. Come, let us return.", ["objectivesText"] = "Join Sigryn at the Vault of Eyir in Skold-Ashil.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questTurnInID"] = 116568, ["questType"] = "standard", ["sourceQuests"] = { 45524 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 640 },
[45526] = { ["id"] = 45526, ["name"] = "The God-Queen's Fury", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45526 }, ["description"] = "<class>t, the Kirin Tor have found a way to get you into the Halls of Valor to pursue the God-King's heir. Archmage Khadgar has asked me to stress upon you the importance of stopping Sigryn , as the prophecies hint that she may still be the key to uniting the Tideskorn against the Legion. It will require an incredible amount of energy to teleport you directly to the Halls, so be sure that you are prepared. It may be some time before we can send you again. Speak to me when you are ready to proceed.", ["objectivesText"] = "The God-Queen's Fury (Sigryn) is a Mage Tower DPS Challenge available during Legion Timewalking. The following specs can complete this challenge: Arcane Mage, Retribution Paladin, Assassination Rogue, Enhancement Shaman, and Demonology Warlock. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our God-Queen's Fury Mage Tower Strategy guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Speak with War Councilor Victoria to be teleported to Sigryn 's location and defeat her.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 25321, 120257, 127849, 132442, 132443, 132444, 132451, 132452, 132466, 133977, 136715, 137020, 137021, 137030, 137048, 137049, 137050, 137069, 137086, 137419, 140790, 140794, 140796, 140801, 140806, 140809, 140846, 142167, 144274, 146666 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 947, ["npcID"] = 116484, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 646, 947 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45527] = { ["id"] = 45527, ["name"] = "Eyir's Forgiveness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14979, ["mapID"] = 947, ["storyline"] = { 45527 }, ["description"] = "I'm sorry for everything I've put you through, outsider. After my actions here, I fear all of this may have been in vain. Come with me back to Skold-Ashil. There I will accept whatever judgment Eyir deems fit of me.", ["objectivesText"] = "Witness Eyir's judgment of Sigryn in the Vault of Eyir in Skold-Ashil.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 947, ["npcID"] = 116484, ["x"] = 0, ["y"] = 0 } }, ["ends"] = { { ["mapID"] = 947, ["npcID"] = 116484, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 947, ["source"] = "quest_giver", ["x"] = 0, ["y"] = 0 }, ["mapCandidates"] = { ["npc"] = { 947 }, ["zone"] = { 14979 } }, ["questTurnInID"] = 116484, ["questType"] = "standard" },
[45528] = { ["id"] = 45528, ["name"] = "The Befouled Barrows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45498, 46674, 46924 }, ["description"] = "You were taking too long, so I took the liberty to scout out the barrows in advance. The Legion has set up portals, pulling more and more demons through them by the second. We need to shut them down so we can save Goldrinn! I'm not sure my usual methods are going to do much to take them down, but I think you can do it! I think some nice vine-work is in order.", ["objectivesText"] = "Close 3 Legion Portals in the Stormrage Barrow Dens. Progress: If we call up some vines to close the portals, then the Legion can't come through.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questTurnInID"] = 120032, ["questType"] = "standard", ["sourceQuests"] = { 44921 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80 },
