[45532] = { ["id"] = 45532, ["name"] = "Mother's Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "That big ugly thing looks like it's leading the attack here. Let's take her down!", ["objectivesText"] = "Kill Mother Mirenda .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questTurnInID"] = 115802, ["questType"] = "standard", ["sourceQuests"] = { 44869 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation" },
[45534] = { ["id"] = 45534, ["name"] = "A Common Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45534 }, ["description"] = "I have one more request to ask of you, outsider. Return to your leaders and report to them what transpired here. Though your people may never truly be allies with the Tideskorn, know that we have a common enemy - one which my people will fight to the last vrykul. When the time comes, I hope to see you on the battlefield.", ["objectivesText"] = "Return to Khadgar in the Violet Citadel.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[45539] = { ["id"] = 45539, ["name"] = "Pet Battle Challenge: Wailing Caverns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["storyline"] = { 45539 }, ["description"] = "The deviate critters of the Wailing Caverns continue to flourish in the damp darkness, but I've been doing my best to keep their numbers down. I've found a few pets and supplies while clearing out the caverns, I might be willing to part with a sack of supplies if you can beat my best run. You'll have to clear out the cavern without healing or reviving any of your pets to best me. Good luck!", ["objectivesText"] = "Defeat the Budding Everliving Spore in Wailing Caverns. Progress: How is the battle for Wailing Caverns going?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 86143, 143753, 147543 }, ["starts"] = { { ["x"] = 0.388, ["y"] = 0.682, ["mapID"] = 10, ["npcID"] = 116781 } }, ["ends"] = { { ["x"] = 0.388, ["y"] = 0.682, ["mapID"] = 10, ["npcID"] = 116781 } }, ["coords"] = { ["mapID"] = 10, ["x"] = 0.388, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17 } }, ["questGiverID"] = 116781, ["questTurnInID"] = 116781, ["questType"] = "standard", ["sourceQuests"] = { 45423 } },
[45540] = { ["id"] = 45540, ["name"] = "A Call from the Caverns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45540 }, ["series"] = { 45423 }, ["description"] = "Oh, good, I'm glad you stopped by. We've heard disturbing rumors of corruption continuing to flourish in the Wailing Caverns. You seem like just the right person to investigate. Since Naralex's awakening, one of his disciples has been watching over the area to ensure that deviate creatures remain in check. She is the one that has been sending us these dire warnings. Meet up with her in the eye of the skull-shaped rock above Wailing Caverns and see if you can help her handle this situation.", ["objectivesText"] = "Find Muyani in the skull-shaped rock above Wailing Caverns.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143753 }, ["starts"] = { { ["x"] = 0.584, ["y"] = 0.38, ["mapID"] = 627, ["npcID"] = 98725 } }, ["ends"] = { { ["x"] = 0.584, ["y"] = 0.38, ["mapID"] = 627, ["npcID"] = 98725 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.584, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98725, ["questTurnInID"] = 98725, ["questType"] = "standard" },
