[45545] = { ["id"] = 45545, ["name"] = "Barrel Toss", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "The Legion is defending the Felskorn lair with fel emitters. Fortunately we have Storm Brew to spare, so there should be plenty available with which to destroy them. Take this barrel, throw it at the spreaders, and watch them go BOOM!", ["objectivesText"] = "Use Storm Brew to destroy 5 Fel Brew Spreaders .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146308 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45459 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
