[45551] = { ["id"] = 45551, ["name"] = "Devastating Effects", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "The Burning Legion will not rest until they have destroyed everything and everyone. Their presence here has had a devastating effect on our lands, and now it seems our wildlife as well. I have heard numerous reports of sickly animals in the thicket that surrounds the demon-infested city of Suramar. Make your way there and see if the rumors are true.", ["objectivesText"] = "Investigate Suramar.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.466571, ["y"] = 0.345143 }, ["mapCandidates"] = { ["npc"] = { 680, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["sourceQuests"] = { 43423, 47137 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45552] = { ["id"] = 45552, ["name"] = "Soothing Wounds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "< D'Bynn 's injuries prevent him from moving.> Perhaps you can forage something nearby that will soothe the manasaber's wounds?", ["objectivesText"] = "Use Manaroot that is foraged from leylines within the Crimson Thicket to soothe D'Bynn 's wounds.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143788 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.551333, ["y"] = 0.452667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45551 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45553] = { ["id"] = 45553, ["name"] = "The Nighthuntress Beckons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "< D'Bynn becomes alert at the sound of his master's voice. Using his muzzle, he nudges your hand with a sense of urgency, inviting you to hop on his back.>", ["objectivesText"] = "Ride D'Bynn and let him lead you to Nighthuntress Syrene's location.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.551333, ["y"] = 0.452667 }, ["mapCandidates"] = { ["npc"] = { 646, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45552 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45554] = { ["id"] = 45554, ["name"] = "Taking Control", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "I've been withering away in this cage, prisoner to a wretch called Reyln. He leads a group of nightborne that are using fel magic to corrupt and control the native wildlife. The Burning Legion's reach has already spread too far for my liking. Kill him and recover his control orb, so I can be released from this arcane prison!", ["objectivesText"] = "Kill Torturer Relyn and use his Control Orb to free Nighthuntress Syrene. Progress: Relyn's control orb is the only thing that can break this magical barrier.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143830 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45553 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45555] = { ["id"] = 45555, ["name"] = "Felbound Beasts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "So Reyln is taking orders from Lexera? Why am I not surprised. She seemed far too comfortable with the demons who infested our city. We cannot let her succeed in corrupting Suramar's wildlife. I swore to protect the city of Suramar from all enemies, even those within its walls. If you can deal with her trappers, I will do my best to track Nighthuntress Lexera down.", ["objectivesText"] = "Kill Nightborne Trappers and free Felbound beasts.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45554 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[45556] = { ["id"] = 45556, ["name"] = "Ready to Strike", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["series"] = { 45557 }, ["description"] = "I followed one of the trappers, who unknowingly led me to the Broken Shore. Lexera was there, surrounded by an army of demons and loyal nightborne. I wasn't able to get close, but from what I could tell, she and her army of trappers are taming the fel-corrupted beasts. It is an abomination of nature, and she must be stopped! Meet me on the Broken Shore and be ready to strike. I will gather additional manaroot. I have a feeling we'll need it.", ["objectivesText"] = "Meet Nighthuntress Syrenne on the Broken Shore.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45555 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45557] = { ["id"] = 45557, ["name"] = "Unnatural Consequences", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["series"] = { 45556 }, ["description"] = "Lexera and her trappers have taken over the valley. She is stronger than she looks, <name>, and she fights with the strength of a dreadlord. Do not go in unprepared. I can handle these demons. Go, find Lexera, and make her feel the consequences of her unnatural endeavors.", ["objectivesText"] = "Kill Nighthuntress Lexera . Progress: Lexera and her trappers must be stopped.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45556 }, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45559] = { ["id"] = 45559, ["name"] = "Behind Enemy Portals", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45559 }, ["objectivesText"] = "Demonic Portal entered", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 253178 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Demonic Portal entered", ["amount"] = 1, ["type"] = 0, ["objectID"] = 117100, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[45560] = { ["id"] = 45560, ["name"] = "Destruction: Rumblings Near Feltotem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842 }, ["series"] = { 45564, 45575, 45587, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Destruction Warlock", ["objectivesText"] = "Find Navarrogg at the Misty Coast in Highmountain.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.228, ["y"] = 0.394, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117225, ["x"] = 0.356, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47031 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[45561] = { ["id"] = 45561, ["name"] = "Seek Me Out", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45561 }, ["description"] = "The letter from Maximillian is written on something which looks to be torn off a ship's sail. Included are directions to the beach in northern Highmountain .", ["objectivesText"] = "Look for Maximillian of Northshire in Highmountain . Progress: Look for Maximillian of Northshire in Highmountain .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 7083, 90313, 90314, 90315, 90316, 90317, 90318, 90319, 90320, 90321, 143900, 152668, 162372, 165785, 166245, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 185954, 186201, 186205, 186206, 187328, 187334, 187336, 187466, 190742, 190745, 190748, 190751, 224784, 229354, 239118, 244865, 248038, 248039, 248040, 248041 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 24707, 46045 }, ["startItems"] = { 143900 } },
[45562] = { ["id"] = 45562, ["name"] = "Kneel and Be Squired!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45562 }, ["description"] = "You must kneel before me if we are to begin our journey together once more. Kneel, squire, and be squired!", ["objectivesText"] = "Kneel before Maximillian.", ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45561 } },
[45563] = { ["id"] = 45563, ["name"] = "The Shrouded Coin", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 45563 }, ["description"] = "A swirling mist envelops the coin and it begins to float above your hand. The mist briefly parts to reveal a shiny new coin, yet in the next instant the coin appears worn from years of exchange. As the coin settles back in to your hand, visions of jungles and mist shrouded peaks waft into your mind, and through the vision you recognize the four Celestials gathered in the courtyard of an island.", ["objectivesText"] = "Bring the Shrouded Timewarped Coin to Mistweaver Xia on the Timeless Isle .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 71638, 71952, 103678, 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 118828, ["x"] = 0.43, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["startItems"] = { 143776 } },
[45564] = { ["id"] = 45564, ["name"] = "The Burning Birds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45575, 45587, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "The Feltotem are experimenting on these falcosaurs! They didn't get the results that they wanted and have carelessly left their experiments lying around to further poison the animals. We should collect their leftover totems to prevent further corruption and to find out what they were doing.", ["objectivesText"] = "Collect Fel Infusing totems . Progress: These animals are unable to be infused with fel magic, but I doubt the Feltotem stopped here.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117225, ["x"] = 0.356, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45560, 47018, 47019, 47020 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[45565] = { ["id"] = 45565, ["name"] = "Further Training", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45565 }, ["description"] = "The journey here was perilous, Squire. It was fraught with danger. Storms, demons, storm demons... I shudder at the memory. Of course, I overcame all such dangers at great loss to my person. This is where I need your assistance. You must venture forth--nay, sally forth--and recover my armor, my weapon, and of course my grand steed. Once you have successfully completed these tasks three, will you be promoted to Squire, First Class!", ["objectivesText"] = "Complete Maximillian's quests and slay \"demons\" to earn the rank of Squire First Class.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118010, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45562 } },
[45566] = { ["id"] = 45566, ["name"] = "A Knight's Belongings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45566 }, ["description"] = "Amidst the squalls and the crashing waves, my mighty ship swayed and tumbled. Lesser knights would have trembled in terror, frozen stiff. Not me! Nay! Heroically, I stripped my armor off my back and stored it safely in my sack. Why did I strip down to these simple undergarments, you ask? Only an ignorant squire would. I was wary of sinking to the bottom should my ship fall foul of course! Ha ha! Unfortunately, the sacks of armor were thrown overboard by the waves.", ["objectivesText"] = "Fetch Maximillian's armor. Progress: Fetch Maximillians armor.", ["rewardItems"] = { 143777, 143782, 143889, 143890, 143891 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118010, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45562 } },
[45567] = { ["id"] = 45567, ["name"] = "My Kingdom for a Horse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45567 }, ["description"] = "Oh, woe is me! Soon after making landfall I began exploring, riding my trusty steed Pimento into the heart of a demon infested village to the north. While performing my investigations, I tied Pimento up to go further on foot, only to return and discover a powerful demon had captured her! There he was, riding her like she was his own. Please find her and send her back to me.", ["objectivesText"] = "Return Pimento .", ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 117760, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118010, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45562 } },
[45568] = { ["id"] = 45568, ["name"] = "They Stole Excaliberto!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45568 }, ["description"] = "I was scouting the nearby demon village when I was attacked. They took my artifact! Of course, if I leave here, the shore will be undefended. The nearby demons have it. Go, slay them and bring it back to me!", ["objectivesText"] = "Find Excaliberto and return it to Maximillian. Progress: Find Maximillians \"Artifact\" weapon, Excaliberto", ["rewardItems"] = { 143840 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 117760, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 117760, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45562 } },
[45570] = { ["id"] = 45570, ["name"] = "In Safer Hands", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45570 }, ["description"] = "There is still the matter of the Focusing Iris . Please return it to your Kirin Tor friends, with my apologies. As for myself, I think I'm done chasing artifacts for a while. One possession by immortal shadowy evil is enough for me, thank you.", ["objectivesText"] = "Bring the Focusing Iris to Archmage Kalec in Dalaran. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143779 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 117252, ["x"] = 0.252, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 117252, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questTurnInID"] = 117252, ["questType"] = "standard", ["sourceQuests"] = { 44925 } },
[45571] = { ["id"] = 45571, ["name"] = "A Bit of Espionage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45576, 45628, 45629, 45833, 45835, 45836, 45848, 46260, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "With the gunpowder in tow, it's time to move on to our next plan. Meet us on the Broken Shore. You can get a flight directly to our next location from Krasus' Landing. We will meet you there, <class>t.", ["objectivesText"] = "Speak to Aludane Whitecloud in Krasus' Landing for a flight to Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.414, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 45836, 46326 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45572] = { ["id"] = 45572, ["name"] = "Holding Our Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45572, 45840, 46182 }, ["description"] = "Though we anticipated a strong Legion presence, our attacks on their camps have angered their forces even further than anticipated. Our forces rally on both land and in the skies above Thunder Totem in an attempt to regain our footing. Do what you can to reduce their forces. Once we've secured Thunder Totem we'll begin our plan for a final attack.", ["objectivesText"] = "Repel the Legion threat from Thunder Totem.", ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 119944, ["x"] = 0.442, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 119676, ["x"] = 0.502, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45840 }, ["questLines"] = { { ["id"] = 307, ["name"] = "Legion Assault - Highmountain", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750 },
[45573] = { ["id"] = 45573, ["name"] = "Rise Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["description"] = "Here we are, <class>t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it. There's no time to explain the plan in full right now, but Tess has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", ["objectivesText"] = "Kill 8 demons, then reach the top of the ramp.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 17900, 17905, 19019, 37971, 38014, 38057, 38118, 44998, 45022, 56652, 56653, 56654, 57281, 57282, 57283, 58927, 58928, 58929, 58930, 58931, 59607, 59608, 59609, 59610, 59666, 59667, 59668, 59669, 59670, 59671, 59672, 63237, 63238, 63239, 63240, 65912, 65938, 65962, 65986, 66012, 66021, 66030, 66039, 123975, 131298, 131713, 131714, 139506, 156934, 156936, 207105, 220128, 220129, 220131, 220132, 239135, 239136, 246936, 249400, 251329, 254267, 254579 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117262, ["x"] = 0.725, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45571 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 122