[45574] = { ["id"] = 45574, ["name"] = "Fel Ingredients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45404, 45459 }, ["description"] = "Our scouts have located a Felskorn encampment within the Garrison of the Fel. We will need as many samples of fel poison as we can find if we are to concoct a cure for our stricken monks. Take samples of anything that looks remotely useful!", ["objectivesText"] = "Acquire 5 Vials of Liquid Felflame , 3 Flasks of Fel Blood , and 3 pinches of Demonic Ash . Progress: Did you find any samples we can use?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146310, 146311, 146312 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45459 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45575] = { ["id"] = 45575, ["name"] = "Village of the Corruptors", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45587, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "The Feltotem continue to create these totems for further \"experiments\". Let us deal with these infusers in the traditional manner. Their deaths will right a great wrong and provide clues as to their ultimate goal.", ["objectivesText"] = "Kill Feltotem Infusers in Feltotem. Progress: These Feltotem need to be dealt with.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 117249, ["questType"] = "standard", ["sourceQuests"] = { 45726 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
