[45586] = { ["id"] = 45586, ["name"] = "Shield Amplification", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 46000, 46290 }, ["description"] = "It will not hurt to reinforce the Nightborne Soulstone 's shield just a bit more, and to do that we must infuse it with energy. Ryanna has assured me that fel essence will work beautifully for our needs. Yes - this method IS rather distasteful. However as the sin'dorei well know, desperate times call for desperate measures. It is as simple as this: we have an urgent need for magical energy, and our enemies possess it in abundance. Do what must be done.", ["objectivesText"] = "Use the Nightborne Soulstone on defeated Felborne within the Weeping Terrace.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143795 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117331, ["questType"] = "standard", ["sourceQuests"] = { 45251 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45587] = { ["id"] = 45587, ["name"] = "The Feltotem Menace", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45575, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "If I had known Tugar was alive and behind this I would've alerted you sooner! He is a hateful creature, and an easy recruit to the Legion's cause. If he is truly successful with his fel experiments we need to stop him now. He is taunting us from up there. Let's go!", ["objectivesText"] = "Find and deal with Tugar Bloodtotem.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863 }, ["starts"] = { { ["npcID"] = 117292 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questGiverID"] = 117292, ["questType"] = "standard", ["sourceQuests"] = { 45575 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[45614] = { ["id"] = 45614, ["name"] = "Lady Remor'za", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45251 }, ["description"] = "Our allies reported a coven of extremely powerful Felborne abjurers occupying the Weeping Terrace. Their leader, Lady Remor'za , and her followers are specialists in ancient nightborne magic and can become nearly invincible to attacks. However, as mages, we should be able to defeat them using Spellsteal. Let us show them the power of the Tirisgarde!", ["objectivesText"] = "Kill Lady Remor'za .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117331, ["questType"] = "standard", ["sourceQuests"] = { 45251 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45615] = { ["id"] = 45615, ["name"] = "Finders Keepers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "Would you look at this place? It's a mess! Everywhere you look there's just pile after pile of arcane dust ! <Akazamzarak smiles broadly.> These poor saps don't realize what that stuff's worth! I tell ya what, if you help me summon up some brooms to collect this powdered gold, I'll split the profits with you 80/20.", ["objectivesText"] = "Sweep up 8 piles of Arcane Dust in the Hall of the Guardian. Progress: Say, how's that dust coming along?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 147838, 178065, 178066, 178067, 178068, 178069, 178070, 178071, 178072 }, ["starts"] = { { ["x"] = 0.815, ["y"] = 0.603, ["mapID"] = 734, ["npcID"] = 103092 } }, ["ends"] = { { ["x"] = 0.815, ["y"] = 0.603, ["mapID"] = 734, ["npcID"] = 103092 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.815, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 103092, ["questTurnInID"] = 103092, ["questType"] = "standard", ["sourceQuests"] = { 45354 }, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[45626] = { ["id"] = 45626, ["name"] = "Set You Up the Bomb!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45626 }, ["objectivesText"] = "Burn all of the things Nests burned", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 49655 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Burn all of the things", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Nests burned", ["amount"] = 10, ["type"] = 0, ["objectID"] = 117446, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[45627] = { ["id"] = 45627, ["name"] = "Feltotem's Fall", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["description"] = "Our Highmountain contact, Navarrogg, reports that Tugar Bloodtotem has finally resurfaced. He's sent a message crystal along with some instructions for me. I can teleport you to Navarrogg and he will take you to Tugar's location, but there is one problem. Navarrogg requires additional magical power to fend off Tugar's fel magicks. You will need some Nethershards before you go.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["starts"] = { { ["npcID"] = 117871, ["x"] = 0.456, ["y"] = 0.622, ["mapID"] = 646 } }, ["ends"] = { { ["npcID"] = 117871, ["x"] = 0.456, ["y"] = 0.622, ["mapID"] = 646 } }, ["coords"] = { ["x"] = 0.456, ["y"] = 0.622, ["source"] = "quest_giver", ["mapID"] = 627 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 117871, ["questType"] = "standard" },
[45628] = { ["id"] = 45628, ["name"] = "This Time, Leave a Trail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 45629, 46260 }, ["description"] = "Are you ready, <class>t? I will walk you through every step of the plan. You'll be perfectly safe! First thing's first: You see that rappel point behind me? That's your way down into the cave. Good luck!", ["objectivesText"] = "Rappel down into the cave, then follow Tess's instructions.", ["rewardGold"] = 477360, ["rewardXP"] = 7675, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117262, ["x"] = 0.725, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45573 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45629] = { ["id"] = 45629, ["name"] = "This Time, Leave a Trail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["series"] = { 45628, 46260 }, ["description"] = "Here goes nothing, <class>t. If anybody can pull this off, you can! ...Probably. Just use the rappel point behind me to get into the cave. What? Don't make that face. I'll give you more instructions once you're in the cave.", ["objectivesText"] = "Rappel down into the cave, then follow Lilian's instructions.", ["rewardGold"] = 477360, ["rewardXP"] = 7675, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117263, ["x"] = 0.725, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45576 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45630] = { ["id"] = 45630, ["name"] = "Servant to No One", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "I like workin' with ya, <name>. How's about we keep this gold train a-rollin'? Archmage Khadgar spends an inordinate amount of time sending his servants off to do who knows what. What if an enterprising duo such as ourselves found a cheaper alternative? <Akazamzarak hands you a small crystal.> This bad boy will form a servant right out of thin air - and a few pounds of the dust you swept up. Why not take it into town and try her out? See for yourself!", ["objectivesText"] = "Test Akazamzarak's Servants on 5 people in Dalaran. Progress: Good stuff, am I right?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.815, ["y"] = 0.603, ["mapID"] = 734, ["npcID"] = 103092 } }, ["ends"] = { { ["x"] = 0.815, ["y"] = 0.603, ["mapID"] = 734, ["npcID"] = 103092 } }, ["coords"] = { ["mapID"] = 734, ["x"] = 0.815, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 103092, ["questTurnInID"] = 103092, ["questType"] = "standard", ["sourceQuests"] = { 45615 }, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734 },
[45631] = { ["id"] = 45631, ["name"] = "Avocation of Antonidas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 45631 }, ["description"] = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish. It was a sort of flying disc that could attune itself to the rider's magical attunement. But I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", ["objectivesText"] = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane . Speak with Khadgar about the Tri-Disc of Fire . And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost .", ["rewardGold"] = 7150, ["rewardXP"] = 6140, ["rewardItems"] = { 143836, 143837, 143838 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 267 } }, ["questType"] = "standard" },
[45632] = { ["id"] = 45632, ["name"] = "Missing in Action: Eitrigg", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45834, 45873, 46267 }, ["series"] = { 45647 }, ["description"] = "Are you familiar with Eitrigg ? He is the worthy orc warrior who was leading our forces against the Felrage naga nearby. Unfortunately the naga captured many of our soldiers during a recent skirmish. Eitrigg went after them and has not returned. I fear something terrible has happened to him. Please try to find him!", ["objectivesText"] = "Find Eitrigg .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 116858, ["questType"] = "standard", ["sourceQuests"] = { 44889 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45633] = { ["id"] = 45633, ["name"] = "Operation Felrage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45834, 45873, 46267 }, ["description"] = "I do not like to see naga aligned with the Burning Legion. That is something new and cannot be ignored. The naga warlord, Kaz'jatar, and his skrog toady, Felbeard , are responsible for the Felrage's attacks on our forces. We must teach them that it does not pay to consort with demons!", ["objectivesText"] = "Kill Warlord Kaz'jatar and Felbeard . Progress: Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.737, ["y"] = 0.312, ["mapID"] = 646, ["npcID"] = 117471 } }, ["ends"] = { { ["x"] = 0.737, ["y"] = 0.312, ["mapID"] = 646, ["npcID"] = 117471 } }, ["coords"] = { ["mapID"] = 646, ["x"] = 0.737, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 117471, ["questTurnInID"] = 117471, ["questType"] = "standard", ["sourceQuests"] = { 45632 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45634] = { ["id"] = 45634, ["name"] = "Kvaldir on Call", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44889, 45118, 45128 }, ["description"] = "You empowered Helya's Horn in Helheim, and now is the time to use it. I have located three Legion portals we should eliminate. Seek out the vrykul shipwreck on Felrage Strand. Call the kvaldir and have them do what they do best: destroy!", ["objectivesText"] = "Blow Helya's Horn and direct the kvaldir to destroy the three Legion portals. Progress: Did the kvaldir answer your call, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 44889 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45637] = { ["id"] = 45637, ["name"] = "Sandworm Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45637 }, ["objectivesText"] = "Progress: Gettin' de colossi to wake up takes a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind da taste.", ["rewardXP"] = 25, ["rewardItems"] = { 20424 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45638] = { ["id"] = 45638, ["name"] = "Crunchy Spider Legs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45638 }, ["objectivesText"] = "Progress: We need meat - any kind of meat - to feed de colossi. And there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", ["rewardXP"] = 25, ["rewardItems"] = { 22644 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45639] = { ["id"] = 45639, ["name"] = "Chilled Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45639 }, ["objectivesText"] = "Progress: De beasts of Northrend are big, heavy, and full of meat. Go find sometin' we can feed to the colossi.", ["rewardXP"] = 25, ["rewardItems"] = { 43013 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45640] = { ["id"] = 45640, ["name"] = "Crocolisk Tails", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45640 }, ["objectivesText"] = "Progress: De crocolisks of Uldum are known for bein' bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", ["rewardXP"] = 25, ["rewardItems"] = { 62784 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45641] = { ["id"] = 45641, ["name"] = "Raw Tiger Steaks", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45641 }, ["objectivesText"] = "Progress: Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", ["rewardXP"] = 25, ["rewardItems"] = { 74833 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45642] = { ["id"] = 45642, ["name"] = "Raw Clefthoof Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45642 }, ["objectivesText"] = "Progress: Gorchuk tells me that the old <race> clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", ["rewardXP"] = 25, ["rewardItems"] = { 109131 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45643] = { ["id"] = 45643, ["name"] = "Lean Shanks", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45643 }, ["objectivesText"] = "Progress: We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in de Broken Isles.", ["rewardXP"] = 25, ["rewardItems"] = { 124117 }, ["rewardCurrencies"] = { { ["id"] = 1324, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45644] = { ["id"] = 45644, ["name"] = "Oh Doloria, My Sweet Doloria", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 45644 }, ["description"] = "What ho! We are quite the dashing pair of adventurers, aren't we? Now that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria . Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky! It must be Dalaran . Quickly, squire! Mount up and meet me at Dalaran 's famous inn. Make haste!", ["objectivesText"] = "Seek out Doloria in the Legerdermain Lounge in Dalaran .", ["starts"] = { { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 118009, ["questType"] = "standard", ["sourceQuests"] = { 45565, 45566, 45567, 45568 } },
[45645] = { ["id"] = 45645, ["name"] = "A Fool's Errand", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["storyline"] = { 45645 }, ["description"] = "Oh yea sure, I'm, um, held here against my, you know, will, or something. Look bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don't have it in me to upset him with the truth. I've got an idea. Why don't you go kill some of those really big two headed \"Hill Bandits\" for me. Let's say they stole some jewelery from me, and you can use it to buy my freedom. Take your time, don't get hurt. Much.", ["objectivesText"] = "Kill \"Hill Bandits\" to find Doloria 's stolen \"Jewelry\" and buy her \"release\". Progress: Kill \"Hill Bandits\" to find Dolorias stolen \"Jewelry\" and buy her \"release\"", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 65929, 65954, 65978, 65999, 143845 }, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.41, ["mapID"] = 627, ["npcID"] = 117438 } }, ["ends"] = { { ["x"] = 0.482, ["y"] = 0.41, ["mapID"] = 627, ["npcID"] = 117438 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.482, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 117438, ["questTurnInID"] = 117438, ["questType"] = "standard", ["sourceQuests"] = { 45644 } },
[45647] = { ["id"] = 45647, ["name"] = "Mission: Search and Rescue", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45834, 45873, 46267 }, ["series"] = { 45632 }, ["description"] = "I will make these naga pay for their audacity. They and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor! We must rescue our fallen soldiers before they are sold as slaves, or worse...", ["objectivesText"] = "Rescue 8 squads of Captured Warriors . Progress: Have we found them all?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.737, ["y"] = 0.312, ["mapID"] = 646, ["npcID"] = 117471 } }, ["ends"] = { { ["x"] = 0.737, ["y"] = 0.312, ["mapID"] = 646, ["npcID"] = 117471 } }, ["coords"] = { ["mapID"] = 646, ["x"] = 0.737, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 117471, ["questTurnInID"] = 117471, ["questType"] = "standard", ["sourceQuests"] = { 45632 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45648] = { ["id"] = 45648, ["name"] = "Missing in Action: Lord Darius Crowley", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45634, 45648, 45649, 45650, 45834, 45876, 46267 }, ["series"] = { 45649 }, ["description"] = "Are you familiar with Lord Darius Crowley ? He is the worthy Gilnean warrior who was leading our forces against the Felrage naga nearby. Unfortunately the naga captured many of our soldiers during a recent skirmish. Lord Darius went after them and has not returned. I fear something terrible has happened to him. Please try to find him!", ["objectivesText"] = "Search for Lord Darius Crowley .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 116858, ["questType"] = "standard", ["sourceQuests"] = { 44889 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
