[45650] = { ["id"] = 45650, ["name"] = "Operation Felrage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45634, 45648, 45649, 45650, 45834, 45876, 46267 }, ["description"] = "I am very concerned to discover naga aligned with the Burning Legion. That is something new and cannot be ignored. The naga warlord, Kaz'jatar, and his skrog toady, Felbeard , are responsible for the Felrage's attacks on our forces. We must teach them that it does not pay to consort with demons!", ["objectivesText"] = "Kill Warlord Kaz'jatar and Felbeard . Progress: Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.737, ["y"] = 0.312, ["mapID"] = 646, ["npcID"] = 117475 } }, ["ends"] = { { ["x"] = 0.737, ["y"] = 0.312, ["mapID"] = 646, ["npcID"] = 117475 } }, ["coords"] = { ["mapID"] = 646, ["x"] = 0.737, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 117475, ["questTurnInID"] = 117475, ["questType"] = "standard", ["sourceQuests"] = { 45648 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
