[45706] = { ["id"] = 45706, ["name"] = "The Power of Thousands", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 44800, 45652, 45724 }, ["description"] = "I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition. The Legion is attacking my home. I've lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.", ["objectivesText"] = "Take Magatha's portal and meet her in Thousand Needles.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.354, ["y"] = 0.76, ["mapID"] = 726, ["npcID"] = 117482 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 7745 } }, ["questGiverID"] = 117482, ["questType"] = "standard", ["sourceQuests"] = { 45652 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64 },
[45723] = { ["id"] = 45723, ["name"] = "The Crone's Wrath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["description"] = "These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.", ["objectivesText"] = "Defeat 15 demons on Darkcloud Pinnacle.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["sourceQuests"] = { 45706 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds" },
[45724] = { ["id"] = 45724, ["name"] = "Snakes and Stones", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 44800, 45652, 45706 }, ["description"] = "When the demons attacked, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone . While death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone ... such an artifact of power belongs in my hands, not theirs. We must split up to find them. For the world's sake, do be careful. I don't need you clumsily destroying everything.", ["objectivesText"] = "Find either the Doomstone or Arikara on Darkcloud Pinnacle. Progress: Greetings, Farseer. What have you found?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143860 }, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["sourceQuests"] = { 45706 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds" },
[45725] = { ["id"] = 45725, ["name"] = "Breaking Chains", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["description"] = "The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.", ["objectivesText"] = "Free 8 Captured Grimtotem from Prison Cages.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["sourceQuests"] = { 45706 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds" },
[45726] = { ["id"] = 45726, ["name"] = "The Tainted Marsh", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45575, 45587, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "I wasn't able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic! I will rework this fel totem to draw out the fel energies they infused in those spirits. Please, cure what spirits you can, perhaps it will even give them some peace. If you want, I can even send you there!", ["objectivesText"] = "Drain the fel energies from the spirits of the Blind Marshlands. Progress: I'm tired of these monsters abusing everything around them!", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45564 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[45727] = { ["id"] = 45727, ["name"] = "Uniting the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43341, 45727 }, ["description"] = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", ["objectivesText"] = "Speak to Archmage Khadgar in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140192, 141605 }, ["starts"] = { { ["x"] = 0.285, ["y"] = 0.483, ["mapID"] = 627, ["npcID"] = 90417 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.483, ["mapID"] = 627, ["npcID"] = 90417 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90417, ["questTurnInID"] = 90417, ["questType"] = "standard", ["questLines"] = { { ["id"] = 275, ["name"] = "7.0 World Quests", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45729] = { ["id"] = 45729, ["name"] = "Sandworm Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45729 }, ["objectivesText"] = "Progress: Convincing the giant colossi of Silithus to wake up requires a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind the taste too much!", ["rewardXP"] = 25, ["rewardItems"] = { 20424 }, ["rewardCurrencies"] = { { ["id"] = 1325, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117434, ["x"] = 0.34, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117434, ["x"] = 0.34, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45730] = { ["id"] = 45730, ["name"] = "Crunchy Spider Legs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45730 }, ["objectivesText"] = "Progress: We need meat - any kind of meat - to feed the colossi... and there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", ["rewardXP"] = 25, ["rewardItems"] = { 22644 }, ["rewardCurrencies"] = { { ["id"] = 1325, ["amount"] = 20 } }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117434, ["x"] = 0.34, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117434, ["x"] = 0.34, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
