[45763] = { ["id"] = 45763, ["name"] = "Demonic Disruption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45767, 45971 }, ["description"] = "While scouting on the Broken Shore, we have stumbled upon something quite unsettling. The Legion is attempting to harness the powers of Azeroth's elements. What is more, they are succeeding. We must stop them at all costs. I can open a portal for you to meet Therazane at the Garrison of the Fel. She will update you on the situation.", ["objectivesText"] = "Speak to Farseer Nobundo to go to the Broken Shore, then meet Therazane at the Garrison of the Fel.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.304, ["y"] = 0.518, ["mapID"] = 726, ["npcID"] = 106519 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7745 } }, ["questGiverID"] = 106519, ["questType"] = "standard", ["sourceQuests"] = { 44800 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45764] = { ["id"] = 45764, ["name"] = "Restoring Equilibrium", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 45385 }, ["description"] = "Kor'vass sent a report on the status of the Fel Hammer. It suffered major damage, and is now even uglier than before if that'ss even possible... It hass also begun listing to one side - rather comically, I might add. For some reason, Kor'vass doesn't find this nearly as entertaining as she should. Anyway, there are stabilizer crystalss around the Tomb of Sargerass she could use for repairss. Say the word and I will direct a squadron of illidari batriderss to accompany you. I'd come too, but...", ["objectivesText"] = "Obtain 3 Stabilizing Crystals . Progress: Have you secured the materialss for repairing the Fel Hammer, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143918 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45385 }, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45765] = { ["id"] = 45765, ["name"] = "Brothers and Sisters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["description"] = "Your people were trying to stop the Legion before you arrived, but flesh is weak and they accumulated too many wounds. Without your aid, they will surely perish at the hands of the demons. Go, help them.", ["objectivesText"] = "Heal 8 Injured Shaman in Garrison of the Fel. Progress: Rock may chip, but it does not bleed as flesh does.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45763 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
