[45767] = { ["id"] = 45767, ["name"] = "Elemental Cores", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45763, 45971 }, ["description"] = "The eredar here are abusing the power of all of Azeroth's elements, forcing them to their command using their fel magics. They succeed to do this through curiosities the Legion has developed, cores of power that correspond to each element. Do not allow the Legion to continue abusing our world. Kill them and take the sources of their power.", ["objectivesText"] = "Collect 3 Fire Power Cores , 3 Water Power Cores , 3 Earth Power Cores , and 3 Air Power Cores . Progress: Nobody should force the elements to bend to their will. Show the Legion that their understanding is flawed.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146888, 146889, 146890, 146891, 163476 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45763 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45769] = { ["id"] = 45769, ["name"] = "Conflagration", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45883, 46258 }, ["description"] = "That fiend! Up on the hill, a demon who calls himself \"The Flameripper\" is using the power of my realm. Your shaman die as he draws power from the Firelands, mixing the fire of our world with the unholy flame of his. He is extremely powerful, Farseer. You must take him down, whatever the cost!", ["objectivesText"] = "Kill Barastagax the Flameripper.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 115492, ["x"] = 0.545333, ["y"] = 0.524667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 115492, ["x"] = 0.545333, ["y"] = 0.524667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.545333, ["y"] = 0.524667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 115492, ["questType"] = "standard", ["sourceQuests"] = { 45883 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[45770] = { ["id"] = 45770, ["name"] = "Stirring in the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 46069, 46070, 46071, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "We must now purify the barding by both material and immaterial means. For the material, we need to travel to Stratholme. When it thrived, before the plague, it produced holy water capable of cleansing even the darkest of magics. There still may be caches of it lying untouched there that we can use. Then it's just a matter of imbuing enough holy power into the barding to make sure it overcomes the will of Rivendare's mount, Shadowmane. Travel to the service gate of Stratholme when you're ready.", ["objectivesText"] = "Meetup with Lord Grayson Shadowbreaker in Stratholme. Once inside, locate the remains of Lord Rivendare and his mount and perform the ritual to claim it as your own. Progress: Your mount is within our reach, Highlord. I only pray Stratholme still has an ample supply of holy water.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 44177, 46109, 123918, 124113, 131746, 143503, 143504, 143505, 144294, 147768, 151623, 168056, 229348 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "dungeon", ["sourceQuests"] = { 46074 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24 },
[45771] = { ["id"] = 45771, ["name"] = "A Time for Everything", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "Our order is recovering thanks to your quick actions, Grandmaster. There is just one more monk we need to attend to before it is too late!", ["objectivesText"] = "Give the Curative Brew to Iron-Body Ponshu .", ["rewardXP"] = 7675, ["rewardItems"] = { 146401, 147467 }, ["starts"] = { { ["x"] = 0.505, ["y"] = 0.578, ["mapID"] = 709, ["npcID"] = 119765 } }, ["ends"] = { { ["x"] = 0.505, ["y"] = 0.578, ["mapID"] = 709, ["npcID"] = 119765 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.505, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 119765, ["questTurnInID"] = 119765, ["questType"] = "standard", ["sourceQuests"] = { 45442 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
