[45788] = { ["id"] = 45788, ["name"] = "The Speaker Awaits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45788, 45789 }, ["description"] = "High Priest, we've received word from Netherlight Temple of a most curious visitor: Magni Bronzebeard, the very Speaker himself! What could he want from our order? You'd best head back to Netherlight, we'll hold down the front here.", ["objectivesText"] = "Speak with Betild Deepanvil in Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118536, ["x"] = 0.444667, ["y"] = 0.634667 }, { ["mapID"] = 646, ["npcID"] = 118537, ["x"] = 0.444667, ["y"] = 0.635333 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118536, ["x"] = 0.444667, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.444667, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 118536, ["questType"] = "standard", ["sourceQuests"] = { 46034 }, ["questLines"] = { { ["id"] = 789, ["name"] = "Class Mount: Priest", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 789, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[45789] = { ["id"] = 45789, ["name"] = "The Sunken Vault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 45788, 45789 }, ["description"] = "'Ello, High Priest. The Speaker has just been telling us of a calling of sorts, coming from deep in the core of Azeroth. The voice is telling 'im there's a lost Titan vault out there, near the Maelstrom. We dun know what's inside, but he's got tha feelin' it's got somethin' ta do with the Light, and you! Brann's got a vessel waitin' for ye, off the coast of Azsuna. Of course, I'll be accompanying ye as well, for cataloguing purposes. Can't go and let a chance like this go to waste!", ["objectivesText"] = "Take Brann's vessel in Azsuna to the Sunken Vault. Progress: Ta be one o' tha first to step foot in a lost Titan vault, it gives me tha chills!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.48, ["y"] = 0.219, ["mapID"] = 702, ["npcID"] = 102709 } }, ["ends"] = { { ["x"] = 0.48, ["y"] = 0.219, ["mapID"] = 702, ["npcID"] = 102709 } }, ["coords"] = { ["mapID"] = 702, ["x"] = 0.48, ["y"] = 0.219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questGiverID"] = 102709, ["questTurnInID"] = 102709, ["questType"] = "standard", ["sourceQuests"] = { 45788 }, ["questLines"] = { { ["id"] = 789, ["name"] = "Class Mount: Priest", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 789, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
