[45796] = { ["id"] = 45796, ["name"] = "Destroying the Nest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45575, 45587, 45726, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "We have to put an end to Tugar's plot. These abominations must be destroyed, as well as their source! I think I know where. A group of neutral drogbar had a settlement nearby, but were pushed out by concerted demon and fel tauren attacks. That must be the place. Go there and stop their fel monster production at its source!", ["objectivesText"] = "Enter the Feltotem Caverns and ruin Tugar's plot. Progress: A tough fight to be sure, have you prevailed?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 143778, 143863 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["sourceQuests"] = { 45587 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
