[45801] = { ["id"] = 45801, ["name"] = "Avocation of Antonidas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 45801 }, ["description"] = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish. It was a sort of flying disc that could attune itself to the rider's magical attunement. But I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", ["objectivesText"] = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane . Speak with Khadgar about the Tri-Disc of Fire . And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost .", ["rewardGold"] = 276200, ["rewardXP"] = 6140, ["rewardItems"] = { 143836, 143837, 143838 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 267 } }, ["questType"] = "standard" },
