[45833] = { ["id"] = 45833, ["name"] = "The Pirate's Bay", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 44758, 46322 }, ["description"] = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned. We've received word of a large cave off the main island, where powerful demons meet to plot our downfall. Tess and Tethys have formulated a plan, but they need your help to see it through.They are waiting for you at Dead Man's Bay in Azsuna.", ["objectivesText"] = "Meet up with Tess Greymane and Tethys at Dead Man's Bay in Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 43422, 47137 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45834] = { ["id"] = 45834, ["name"] = "Stolen Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44849, 46173 }, ["description"] = "Odyn's worthy are held captive by soul fonts scattered around the Eternal Battlefield. They were destined to become Valarjar before their futures were stolen. Now, you can restore them to their rightful places. Destroy the soul fonts to release them!", ["objectivesText"] = "Free 15 stolen souls.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.343, ["y"] = 0.285, ["mapID"] = 649, ["npcID"] = 116193 } }, ["ends"] = { { ["x"] = 0.343, ["y"] = 0.285, ["mapID"] = 649, ["npcID"] = 116193 } }, ["coords"] = { ["mapID"] = 649, ["x"] = 0.343, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questGiverID"] = 116193, ["questTurnInID"] = 116193, ["questType"] = "standard", ["sourceQuests"] = { 44849 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649 },
[45835] = { ["id"] = 45835, ["name"] = "False Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["description"] = "As soon as you take down Prix, word will spread like wildfire amongst the crew in the area. I had Tethys forge some orders in her handwriting that should send them away and buy us some more time. Plant the orders in the marked locations. You should see the results rather quickly.", ["objectivesText"] = "Plant the False Orders in the marked locations.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 45833 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
