[45838] = { ["id"] = 45838, ["name"] = "Assault on Azsuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45795, 45838, 46199, 46205 }, ["description"] = "The demons strike at the heart of our existence, posing a threat to all who inhabit our lands. Remove the threat before it is too late.", ["objectivesText"] = "Repel the Burning Legion forces throughout Azsuna .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 138762, 139155, 139156, 139157, 139158, 139159, 139160, 139161, 139162, 139163, 139164, 139165, 139166, 238727 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 118942, ["x"] = 0.56, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 306, ["name"] = "Legion Assault - Azsuna", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45839] = { ["id"] = 45839, ["name"] = "Assault on Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45406, 45839, 46110 }, ["series"] = { 45406 }, ["description"] = "The eternal foe of our world, the Burning Legion, dare to attack the land of Stormheim ! Champion, now is your call to valor! Find the forces of the Legion and eradicate them!", ["objectivesText"] = "Repel the Burning Legion forces throughout Stormheim .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 138762, 139155, 139156, 139157, 139158, 139159, 139160, 139161, 139162, 139163, 139164, 139165, 139166 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116868, ["x"] = 0.9, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.9, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 305, ["name"] = "Legion Assault - Stormheim", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[45840] = { ["id"] = 45840, ["name"] = "Assault on Highmountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45572, 45840, 46182 }, ["description"] = "In my years I have seen disturbances and threats come and go, but never before have I seen such brazen disregard for life. The demons may scorch our lands and cause suffering amongst our kin, but we must not stand idly by while they threaten what we have fought so hard to create. Rise to the occasion, <name>. The time has come to stand against the Burning Legion!", ["objectivesText"] = "Repel the Burning Legion forces throughout Highmountain .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 138762, 139155, 139156, 139157, 139158, 139159, 139160, 139161, 139162, 139163, 139164, 139165, 139166 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 119944, ["x"] = 0.442, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 307, ["name"] = "Legion Assault - Highmountain", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[45841] = { ["id"] = 45841, ["name"] = "A Triumphant Report", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["description"] = "You should return to your Kirin Tor. I have no doubt they will want to hear the good news!", ["objectivesText"] = "Speak with Archmage Modera in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143778, 143863 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questTurnInID"] = 117361, ["questType"] = "standard", ["sourceQuests"] = { 45796 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45842] = { ["id"] = 45842, ["name"] = "A Gift From the Six", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["description"] = "<name>, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war. Such a deed merits more than mere recognition. If you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", ["objectivesText"] = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel. Progress: Are you ready?", ["starts"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questTurnInID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 45841 }, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45843] = { ["id"] = 45843, ["name"] = "Dark Omens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["description"] = "We won't be able to defeat Kruul alone. Once the portal has stabilized I will send word so we can bring the Highlord to justice. In the meantime, you should inform the Kirin Tor of Vazuun's death - and Kruul's return.", ["objectivesText"] = "Speak with Archmage Modera in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questTurnInID"] = 116880, ["questType"] = "standard", ["sourceQuests"] = { 45415 }, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[45844] = { ["id"] = 45844, ["name"] = "Avocation of Antonidas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "Archmage Kalec has requested your presence back in the Hall of the Guardian. He's discovered something he wishes to urgently speak with you about. Please see him at your earliest convenience.", ["objectivesText"] = "Speak with Archmage Kalec in the Hall of the Guardian.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117770, ["x"] = 0.452, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117770, ["x"] = 0.452, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117770, ["questType"] = "standard", ["sourceQuests"] = { 46043 }, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[45845] = { ["id"] = 45845, ["name"] = "Burning Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "The first piece he spoke of was that of fire. He imbued it while investigating the entrance to the Molten Core. However, the power surging through it was too great to control, so he asked Khadgar to take it to Karazhan and see if there were any books on the subject of controlling fire. Perhaps you should speak with Khadgar and find out what became of the disc.", ["objectivesText"] = "Speak with Khadgar about the Tri-Disc of Fire . Follow his instructions after you speak with him. Progress: Was Khadgar able to remember what he did with the piece?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 143836 }, ["starts"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.563, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108247, ["questTurnInID"] = 108247, ["questType"] = "standard", ["sourceQuests"] = { 45844 }, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[45846] = { ["id"] = 45846, ["name"] = "Chilled to the Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 267, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "The next piece Antonidas made was imbued with frost magic. He wrote about a ritual to channel frost energy into the disc with his fellow Archmage, Cedric, but their combined strengths forced too much energy into the disc. If I recall, Cedric is helping oversee the reconstruction of Dalaran near the crater where Dalaran once resided. Hopefully he knows where to find the disc.", ["objectivesText"] = "Speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost . Progress: After the devastation that befell Dalaran's original home, who knows where that disc may be.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 143837 }, ["starts"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.563, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 267 } }, ["questGiverID"] = 108247, ["questTurnInID"] = 108247, ["questType"] = "standard", ["sourceQuests"] = { 45844 }, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[45847] = { ["id"] = 45847, ["name"] = "Close to Home", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "The third piece of the disc was infused with Antonidas' own arcane magic. He did this at the height of his power, but like the other two discs, was unable to finish his work on it. He wrote that he gave the piece to Archmage Celindra ... Isn't she the portal trainer here in Dalaran? She must know where the piece is! Quickly, go speak with her.", ["objectivesText"] = "Speak to Archmage Celindra about the Tri-Disc of the Arcane here in Dalaran. Progress: Did she have it?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 142223, 143838 }, ["starts"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["ends"] = { { ["x"] = 0.563, ["y"] = 0.38, ["mapID"] = 735, ["npcID"] = 108247 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.563, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108247, ["questTurnInID"] = 108247, ["questType"] = "standard", ["sourceQuests"] = { 45844 }, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[45848] = { ["id"] = 45848, ["name"] = "Fit For a Pirate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45576, 45628, 45629, 45833, 45835, 45836, 45848, 46260, 46322, 46323, 46324, 46326, 46827 }, ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143679 }, ["starts"] = { { ["npcID"] = 118126, ["x"] = 0.576, ["y"] = 0.634, ["mapID"] = 630 } }, ["ends"] = { { ["npcID"] = 118126, ["x"] = 0.576, ["y"] = 0.634, ["mapID"] = 630 } }, ["coords"] = { ["x"] = 0.576, ["y"] = 0.634, ["source"] = "quest_giver", ["mapID"] = 630 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 44758, 45073, 45835, 46323, 46324 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[45856] = { ["id"] = 45856, ["name"] = "Battle for Val'sharah", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 44789, 45812, 45856 }, ["description"] = "From the very start of these attacks I've felt as though the demons knew our plans, as if they anticipated our every move. If we are to put an end to this we must focus our attacks at the heart of the beast. Your efforts have shown these battles are not won by bravery alone, but willingness and sacrifice. I ask that you stand on the battlefield once more among allies to bring this madness to an end.", ["objectivesText"] = "Defeat Dread Vizier Gra'tork in Val'sharah .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 109076, 139773, 142001 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118250, ["x"] = 0.44, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118440, ["x"] = 0.548, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 44789 }, ["questLines"] = { { ["id"] = 308, ["name"] = "Legion Assault - Val'sharah", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[45861] = { ["id"] = 45861, ["name"] = "A Gift From the Six", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45127 }, ["description"] = "<name>, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war. Such a deed merits more than mere recognition. If you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", ["objectivesText"] = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel. Progress: Are you ready?", ["starts"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questTurnInID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 45127 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
