[45883] = { ["id"] = 45883, ["name"] = "The Firelord's Offense", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45769, 46258 }, ["description"] = "Smolderon calls from across the battlefield, shaman. Now it is his realm being violated. It seems urgent. I will clean up here.", ["objectivesText"] = "Report to Firelord Smolderon in Cinder Run.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 115492, ["x"] = 0.545333, ["y"] = 0.524667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45765, 45767, 45971 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45890] = { ["id"] = 45890, ["name"] = "Ancestors and Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 641, ["storyline"] = { 45147, 45890, 46259 }, ["series"] = { 45145, 46259 }, ["description"] = "I want nothing more than to prove myself by joining our offensive on the Broken Shore, but I'm beginning to doubt my worthiness. You see, I found my family's sigil among the demonic runes I've been deciphering. Why the Moonfang crest would be known to the Legion is a mystery to me, but I trust you'll be able to find what connection lies between my ancestors and my enemies. What's left of their village can be found in Val'sharah.", ["objectivesText"] = "Head to Delas' ancestral home in Val'sharah and recover relics from her past.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.591, ["y"] = 0.326, ["mapID"] = 24, ["npcID"] = 109102 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 139 } }, ["questGiverID"] = 109102, ["questType"] = "standard", ["sourceQuests"] = { 45143 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[45902] = { ["id"] = 45902, ["name"] = "The Imp Mother's Gift", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45902 }, ["series"] = { 46065 }, ["description"] = "While we have already given you what power we can, we would like to present to you a... cosmetic... upgrade to your artifact. On behalf of the Council of Six, Dalaran, and Azeroth, we thank you again, <name>.", ["objectivesText"] = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel.", ["starts"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questTurnInID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 46065 } },
