[45915] = { ["id"] = 45915, ["name"] = "The Folly of Levia Laurance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 45915 }, ["description"] = "Levia Laurance was once a member of the Kirin Tor, long ago, and a good friend. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous for all of us if her knowledge fell into their hands. She was last seen at the Militant Mystic. Ask around there and see if you can pick up her trail.", ["objectivesText"] = "Ask around the city for information on Levia Laurance.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45916] = { ["id"] = 45916, ["name"] = "The Acolyte Imperiled", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["description"] = "Truthfully, the Council knows little of Agatha, but she is more than just your average succubus. She has many allies within the sayaad, and is known to command armies of imps that swarm and overwhelm her foes. To seek her out is folly, but Ritssyn Flamescowl repays his debts. Come, let us examine what manner of fel powers this little mage of yours was stumbling her way through...", ["objectivesText"] = "Help Ritssyn investigate Levia's ritual. Progress: Keep these imps off me!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.527, ["y"] = 0.592, ["mapID"] = 629, ["npcID"] = 116714 } }, ["ends"] = { { ["x"] = 0.527, ["y"] = 0.592, ["mapID"] = 629, ["npcID"] = 116714 } }, ["coords"] = { ["mapID"] = 629, ["x"] = 0.527, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 116714, ["questTurnInID"] = 116714, ["questType"] = "standard", ["sourceQuests"] = { 46327 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[45917] = { ["id"] = 45917, ["name"] = "Following the Scent", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["description"] = "You will have to continue through the portal without me, <class>. I have assisted you in locating your mage's whereabouts, so I consider my debt to Modera paid. However, I will lend you one of my felhounds to help track this mage down. If she is as powerful as Modera says, then it would be in everyone's best interest that Agatha not be allowed to keep her. Best of luck, <class>, and try to bring Fhambar back in one piece.", ["objectivesText"] = "Follow Fhambar to Levia's location.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.579, ["y"] = 0.726, ["mapID"] = 629, ["npcID"] = 116714 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 116714, ["questType"] = "standard", ["sourceQuests"] = { 45125 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
