[45971] = { ["id"] = 45971, ["name"] = "Infernal Phenomena", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45763, 45767 }, ["description"] = "Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion's will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will. How dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth's stone - MY stone! Now they try to bring these new infernals to life. Sabotage their foolish rituals. Crush them! Show them Azeroth's true power!", ["objectivesText"] = "Interrupt 3 Infernal Rituals. Progress: The earth is my domain, NOT the Legion's!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 45763 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[45972] = { ["id"] = 45972, ["name"] = "The Accursed Thicket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 45972 }, ["description"] = "There is one last task for you and the Doomstone. Thunderaan will explain all.", ["objectivesText"] = "Speak to Thunderaan.", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["sourceQuests"] = { 47428 }, ["db2Objectives"] = { { ["text"] = "Purge the woods", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
