[46069] = { ["id"] = 46069, ["name"] = "Worthy of the Title", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46070, 46071, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "Highlord, Lord Grayson Shadowbreaker wishes to speak with you about an important matter. Please seek him out at Light's Hope Chapel in your order hall at your earliest convenience.", ["objectivesText"] = "Speak with Lord Grayson Shadowbreaker in your order hall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 129979, 131746, 136600, 136970, 143503, 143504, 143505, 144294, 147768 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118376, ["x"] = 0.438, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118376, ["x"] = 0.438, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 118376, ["questType"] = "standard", ["sourceQuests"] = { 46045 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24 },
[46070] = { ["id"] = 46070, ["name"] = "Preparations Underway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46071, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "As you may or may not recall, I once helped young paladins obtain their first armored mount. It was a tedious task that involved months of obtaining materials and sending them all over Azeroth. Thankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord. In order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", ["objectivesText"] = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker. Progress: How goes the search for the barding? Find anything suitable yet?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 129979, 131746, 136600, 136970, 143503, 143504, 143505, 144294, 147768 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 46069 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24 },
[46071] = { ["id"] = 46071, ["name"] = "The Hammer of Dalaran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "Should we wish to make this barding worthy of the steed who will bear it, we'll need to upgrade it. Right now it's just good for not getting you kicked off your mount. Speak with Alard Schmied in Dalaran. He's a fine smith and will know how to modify this barding into something more befitting our needs.", ["objectivesText"] = "Speak with Alard Schmied in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 131746, 143503, 143504, 143505, 144294, 147768 }, ["starts"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["ends"] = { { ["x"] = 0.523, ["y"] = 0.781, ["mapID"] = 24, ["npcID"] = 90250 } }, ["coords"] = { ["mapID"] = 24, ["x"] = 0.523, ["y"] = 0.781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90250, ["questTurnInID"] = 90250, ["questType"] = "standard", ["sourceQuests"] = { 46070, 94847 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
