[46074] = { ["id"] = 46074, ["name"] = "Leather to Legendary", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 24, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46081, 46083, 91618, 94847 }, ["description"] = "Let's begin, shall we? I mean, I'll be doing all the work, but you get to watch! <Alard grins a wide smile at you and begins working.>", ["objectivesText"] = "Have Alard upgrade the barding and return with it to Lord Grayson Shadowbreaker at your order hall. Progress: How'd it go? Was Alard able to upgrade the barding?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 131746, 143503, 143504, 143505, 144294, 147768 }, ["starts"] = { { ["x"] = 0.445, ["y"] = 0.287, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.445, ["y"] = 0.287, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.445, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "standard", ["sourceQuests"] = { 46083, 91618 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24 },
