[46078] = { ["id"] = 46078, ["name"] = "Holy: The Bradensbrook Investigation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200 }, ["series"] = { 46079, 46080, 46082, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook! Is it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid. Specialization: Holy Priest", ["objectivesText"] = "Go to Bradensbrook in Val'sharah.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47027 }, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[46079] = { ["id"] = 46079, ["name"] = "Aid on the Front Lines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46078, 46080, 46082, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "When we settled here, that Hold was just a quiet creepy place that we avoided. Then the elves came back from the dead. With your help we thought it was mostly handled. But now it feels like an army is attacking us! We could use more healing at our defense lines. More undead arrive and we have less and less protectors each wave. Any aid to our wounded would be welcomed!", ["objectivesText"] = "Give aid to the wounded on the east, west, and south defense lines of Bradensbrook. Progress: We can't take anymore losses.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 46078, 47003, 47004, 47005, 47006 }, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[46080] = { ["id"] = 46080, ["name"] = "Quieting the Spirits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46078, 46079, 46082, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "An overwhelming attack on Bradensbrook is imminent. Together I believe we can blunt the spear before it is cast. While we are dealing with the commanders, we should put down as many unquiet spirits as we can. With their leaders down and their numbers culled, that should give us time to find Erdris Thorn.", ["objectivesText"] = "Slay risen elves and spirits near Bradensbrook. Progress: I can see you've brought a lot of \"peace\" in your day, <class>.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.391, ["y"] = 0.581, ["mapID"] = 641, ["npcID"] = 118947 } }, ["ends"] = { { ["x"] = 0.391, ["y"] = 0.581, ["mapID"] = 641, ["npcID"] = 118947 } }, ["coords"] = { ["mapID"] = 641, ["x"] = 0.391, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 118947, ["questTurnInID"] = 118947, ["questType"] = "standard", ["sourceQuests"] = { 46082 }, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[46081] = { ["id"] = 46081, ["name"] = "Leather to Legendary", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 46081 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["description"] = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's a probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I hear saber's eyes are especially sparkly. Why don't you grab one of those for this as well. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(46081)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(46081))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Obtain 50 Leystone Ore and 1 Saber's Eye .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 130245, 144294 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[46082] = { ["id"] = 46082, ["name"] = "Shadowsong's Return", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46078, 46079, 46080, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "Well our lines are doing a lot better, thanks to you. A good thing too, because we need the rest! That being said, we noticed a big group of bigger, meaner risen coming from the farmstead. They would've given us a hard time, but that Shadowsong fellow has returned and killed them all. He's holding off reinforcements coming from the hold. I'm guessing he could use a hand. We can hold here until you and Shadowsong sort this out.", ["objectivesText"] = "Find Jarod Shadowsong outside Bradensbrook in Val'sharah.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118947, ["x"] = 0.39, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 46079 }, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[46083] = { ["id"] = 46083, ["name"] = "A Few Things First", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46081, 91618, 94847 }, ["description"] = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's a probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", ["objectivesText"] = "Obtain 25 Leystone Ore and a Suramarian Sapphire . Progress: I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 129979, 131746, 136269, 136600, 136970, 140325, 140326, 142436, 143503, 143504, 143505, 144294, 147768 }, ["starts"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["ends"] = { { ["x"] = 0.45, ["y"] = 0.296, ["mapID"] = 627, ["npcID"] = 92183 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.45, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 92183, ["questTurnInID"] = 92183, ["questType"] = "standard", ["sourceQuests"] = { 46071 }, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[46089] = { ["id"] = 46089, ["name"] = "Hiding In Plain Sight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 46089, 46103 }, ["description"] = "Greetings, Shadowblade. I hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead. Yes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord. And there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", ["objectivesText"] = "Assassinate the infiltrating homunculi. Progress: Your blade is not yet bloody enough.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 63206, 139590, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 144259, 144296, 160251 }, ["starts"] = { { ["x"] = 0.2, ["y"] = 0.214, ["mapID"] = 626, ["npcID"] = 98099 } }, ["ends"] = { { ["x"] = 0.2, ["y"] = 0.214, ["mapID"] = 626, ["npcID"] = 98099 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.2, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98099, ["questTurnInID"] = 98099, ["questType"] = "standard", ["sourceQuests"] = { 46103 }, ["questLines"] = { { ["id"] = 792, ["name"] = "Class Mount: Rogue", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 792, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
