[46103] = { ["id"] = 46103, ["name"] = "Dread Infiltrators", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46089, 46103, 46178 }, ["description"] = "Shadowblade, we have received a raven with most troubling news. One of our own, an ally that walked our very Hall of Shadows, is not who they seem. I believe Lilian has already begun dissecting their corpse. You'd best hurry.", ["objectivesText"] = "Speak with Lilian Voss in the Hall of Shadows.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 143490, 143491, 143492 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119259, ["x"] = 0.45, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119259, ["x"] = 0.45, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 119259, ["questType"] = "standard", ["sourceQuests"] = { 46058, 46059 }, ["questLines"] = { { ["id"] = 792, ["name"] = "Class Mount: Rogue", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 792, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
