[46106] = { ["id"] = 46106, ["name"] = "Cutting off the Heads", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46107 }, ["description"] = "Erdris Thorn was a key commander of Ravencrest's forces. To hear him confusing us for the Legion fills me with a great sadness. He will be a difficult foe to defeat. We must stop his squad leaders from forming up for a focused assault on Bradensbrook. Defeating them should delay his forces long enough for us to find and deal with him. Let us begin our grim task.", ["objectivesText"] = "Slay the risen squad leaders in Bradensbrook. Progress: It is difficult to bring peace to old friends.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118947, ["x"] = 0.39, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118947, ["x"] = 0.39, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questTurnInID"] = 118947, ["questType"] = "standard", ["sourceQuests"] = { 46082 }, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[46107] = { ["id"] = 46107, ["name"] = "Source of the Corruption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46106 }, ["description"] = "There was something wrong with those three, they had a fel taint about them that was... unsettling. I believe they were somehow woken later than the other risen. Curse the Legion and their meddling! The reinforcements are streaming out of Black Rook Hold from Heroes' Rest. We must make our way there and see if we can stop the source of these new troops.", ["objectivesText"] = "Find the source of the corruption at Heroes' Rest and end it. Progress: We must end this corruption.", ["rewardGold"] = 8955, ["rewardXP"] = 770, ["rewardItems"] = { 25913, 25914, 25915, 52595, 52621, 52633, 131282, 245616 }, ["starts"] = { { ["npcID"] = 118954 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 118954, ["questType"] = "standard", ["sourceQuests"] = { 46080, 46106 }, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
