[46125] = { ["id"] = 46125, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "We have learned so much already about these artifacts it is incredible. Our researchers have been busy preparing notes for you and with a few more resources I am sure they can be used as a crash course in gaining more artifact knowledge. This is only the first step, with more resources we should have additional courses to help you catch up on your studies.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. The Legion must fall!", ["rewardItems"] = { 146745 }, ["starts"] = { { ["x"] = 0.498, ["y"] = 0.562, ["mapID"] = 648, ["npcID"] = 97111 } }, ["ends"] = { { ["x"] = 0.498, ["y"] = 0.562, ["mapID"] = 648, ["npcID"] = 97111 } }, ["coords"] = { ["mapID"] = 648, ["x"] = 0.498, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 97111, ["questTurnInID"] = 97111, ["questType"] = "standard", ["sourceQuests"] = { 46108 }, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 36, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648 },
