[46145] = { ["id"] = 46145, ["name"] = "Sterile Surroundings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "With the threat of infection dismissed, your allies should be able to press their assault here on the Broken Shore and gain an advantage over the Burning Legion. Let's leave this place and speak somewhere more... sterile. I hear your order occupies an impressive temple.", ["objectivesText"] = "Return to Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 147471 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 118528, ["questType"] = "standard", ["sourceQuests"] = { 45342, 45350 }, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702 },
[46146] = { ["id"] = 46146, ["name"] = "The Burning Shores", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 46146 }, ["objectivesText"] = "Demons slain", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Demons slain", ["amount"] = 6, ["type"] = 0, ["objectID"] = 118831, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["db2QuestInfoID"] = 139, ["db2QuestInfoName"] = "Legion Invasion World Quest" },
[46148] = { ["id"] = 46148, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "We've got the skinny on a bit of the artifact power already and I am working an angle to capitalize on it. We've been extorting a group of scribes to put together notes for you, yet they are holding out for a few more resources before they deliver. The good news is that we can squeeze them for a few more courses, but after that it will be back to doing our own research.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: Hey, you know what? If you slip me even more order resources , I can put together more notes about your artifact weapon's history and potential. You need to power up your weapon, and I can pass along the knowledge to get it done. Bring me those resources as soon as you can. We've got a business to run here!", ["rewardItems"] = { 146745 }, ["starts"] = { { ["x"] = 0.398, ["y"] = 0.702, ["mapID"] = 626, ["npcID"] = 102641 } }, ["ends"] = { { ["x"] = 0.398, ["y"] = 0.702, ["mapID"] = 626, ["npcID"] = 102641 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.398, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 102641, ["questTurnInID"] = 102641, ["questType"] = "standard", ["sourceQuests"] = { 43885 }, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 37, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
[46149] = { ["id"] = 46149, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "I am amazed by what we have learned so far. I believe I can prepare for you some notes based on our initial research to get you caught up quickly. It will take just a few more resources to prepare the notes properly. These steps we take now should provide a boost to our knowledge and we can delve even deeper into the hidden potential of these weapons.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. The Legion must fall!", ["rewardItems"] = { 146745 }, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.55, ["mapID"] = 739, ["npcID"] = 98737 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 98737, ["x"] = 0.527667, ["y"] = 0.548667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.527667, ["y"] = 0.548667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questGiverID"] = 98737, ["questType"] = "standard", ["sourceQuests"] = { 46130 }, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 38, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[46150] = { ["id"] = 46150, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "The amount of power in these artifacts is incredible and we have only scratched the surface. Our researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. This is only the first step, with more resources we should be able to help you catch up even more.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with irresistible power. Bring me those resources as soon as you can. Our victory awaits!", ["rewardItems"] = { 146745 }, ["starts"] = { { ["x"] = 0.576, ["y"] = 0.406, ["mapID"] = 717, ["npcID"] = 111740 } }, ["ends"] = { { ["x"] = 0.576, ["y"] = 0.406, ["mapID"] = 717, ["npcID"] = 111740 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.576, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 111740, ["questTurnInID"] = 111740, ["questType"] = "standard", ["sourceQuests"] = { 46131 }, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 39, ["flags"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46151] = { ["id"] = 46151, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "I am surprised and awed each day I delve deeper into the history of these weapons. Our researcher has been going extremely well and we have been busy preparing notes for you. With a few more resources I am sure we can prepare something to boost your artifact knowledge a little. Remember though, this is only a first step. These weapons have been around longer than most recorded history so much deeper knowledge will take time.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I kin scribe further notes 'bout yer artifact weapon's hist'ry an' potential. This knowledge'll be crucial fer infusing yer weapon with additional pow'r. Bring me tha resources as soon as ye can. The Legion must fall!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 40, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 24 },
[46152] = { ["id"] = 46152, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "Through pain and blood we have cut through the initial layers of research. We have been busy preparing notes for you and with a few more resources we can get you something to boost your artifact knowledge. This is only the first step, more resources will be required to catch you up further.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. The Legion will cry out in agony as they die!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 41, ["flags"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
