[46176] = { ["id"] = 46176, ["name"] = "The Archmage Accosted", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 46176 }, ["description"] = "With the barrier dispelled, Archmage Xylem is finally within reach! Hopefully he'll be cooperative in returning the Iris...", ["objectivesText"] = "Confront Archmage Xylem.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16 } }, ["questType"] = "standard" },
[46177] = { ["id"] = 46177, ["name"] = "A Portal Away", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["description"] = "Xylem may have escaped, but a trace of his portal remains. Now that you have freed his apprentices from his corruption, I will set them to work trying to find a way to reach him. Once I find something, I will alert the Kirin Tor. I only ask that when you do confront the Archmage, that you try to spare his life. I believe that the good man he once was still exists beneath the shadow that has taken him. Farewell, <name>.", ["objectivesText"] = "Return to Archmage Kalec in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 116048, ["x"] = 0.252, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 116048, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questTurnInID"] = 116048, ["questType"] = "standard", ["sourceQuests"] = { 44924 }, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[46178] = { ["id"] = 46178, ["name"] = "Hiding In Plain Sight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 46103, 46178 }, ["description"] = "Greetings, Shadowblade. I hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead. Yes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord. And there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", ["objectivesText"] = "Assassinate the infiltrating homunculi. Progress: Your blade is not yet bloody enough.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29571, 133636, 143490, 143491, 143492, 144259, 144357 }, ["starts"] = { { ["x"] = 0.2, ["y"] = 0.214, ["mapID"] = 626, ["npcID"] = 98099 } }, ["ends"] = { { ["x"] = 0.2, ["y"] = 0.214, ["mapID"] = 626, ["npcID"] = 98099 } }, ["coords"] = { ["mapID"] = 626, ["x"] = 0.2, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 98099, ["questTurnInID"] = 98099, ["questType"] = "standard", ["sourceQuests"] = { 46103 }, ["questLines"] = { { ["id"] = 792, ["name"] = "Class Mount: Rogue", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 792, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626 },
