[46207] = { ["id"] = 46207, ["name"] = "The Trial of Rage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 46207, 46208 }, ["description"] = "I wish to extend to you a prestigious invitation. Every year I hold a trial for my finest warrior to prove that I command the strongest in this land. I have chosen you to be my champion in this trial. Should you succeed in completing the trial, I have a prize that will be worthy of your accomplishments awaiting you at the end. Take what time you need to prepare yourself. Come back and speak with me when you're ready to begin.", ["objectivesText"] = "Speak with Odyn to begin the Trial of Rage scenario. Complete the scenario and claim your prize. Progress: I have no doubt that you will be victorious in this trial. I look forward to watching it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127849, 133569, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 144396, 144397 }, ["starts"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["ends"] = { { ["x"] = 0.583, ["y"] = 0.846, ["mapID"] = 695, ["npcID"] = 96469 } }, ["coords"] = { ["mapID"] = 695, ["x"] = 0.583, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questGiverID"] = 96469, ["questTurnInID"] = 96469, ["questType"] = "dungeon", ["sourceQuests"] = { 46208 }, ["questLines"] = { { ["id"] = 303, ["name"] = "Class Mount: Warrior", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 303, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
