[46237] = { ["id"] = 46237, ["name"] = "Bloodbringer's Missive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "Warlock! We have news from Dreadscar Rift. A message arrived by raven from Mor'zul Bloodbringer , with instructions that you meet him in Dreadscar Rift immediately!", ["objectivesText"] = "Speak with Mor'zul Bloodbringer in Dreadscar Rift. Progress: Will you not hear me out, <class>?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 137663 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117622, ["x"] = 0.438, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117622, ["x"] = 0.438, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117622, ["questType"] = "standard", ["sourceQuests"] = { 46047, 46316 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46238] = { ["id"] = 46238, ["name"] = "If You Build It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground. I will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. Here's the list of what you'll need.", ["objectivesText"] = "Collect 5 Felslate , 3 Chaotic Spinel and an Unbending Potion . These can be gathered and crafted using profession skills or purchased on the Auction House. Progress: Have you the necessary materials?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29784, 29785, 29786, 30398, 33226, 63227, 63228, 63229, 123919, 124124, 127845, 130175, 144328, 156937, 157009, 157010, 158611, 158612, 158613, 158614, 160189, 160190, 160191, 160192, 167649, 178061, 183830 }, ["starts"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["ends"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.353, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 119166, ["questTurnInID"] = 119166, ["questType"] = "standard", ["sourceQuests"] = { 46237 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46239] = { ["id"] = 46239, ["name"] = "Fel to the Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "While it has become relatively easy for a warlock to open a brief window into the realms of the Legion, a sustained portal requires significantly more power. For this, we will need a power source brimming with fel energy. I know that the commanders of the Legion use powerful fel cores to control their warships. If you can defeat the commander of one of these ships, you should be able to take their core.", ["objectivesText"] = "Collect an Overcharged Fel Core from the commander of a Legion Assault on the Broken Isles. Progress: Do you have the core?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144443 }, ["starts"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["ends"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.353, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 119166, ["questTurnInID"] = 119166, ["questType"] = "standard", ["sourceQuests"] = { 46237 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46240] = { ["id"] = 46240, ["name"] = "Give Me Fuel, Give Me Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "A powerful core will not alone be able to power the portal. Like any powerful engine, it will require fuel - though an engine of fel energy must burn life force to thrive. We will need blood potent in magical energy to keep our fel core running and sustain our connection to Xoroth. Fortunately, I have experience in these matters, and I know just the place where we can get some. You'll need a jar or something.", ["objectivesText"] = "Collect 50 Owlbeast Blood from Owlbeasts within Lostlight Grotto in Val'sharah. Progress: Have you bled the owlkin dry?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144444 }, ["starts"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["ends"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.353, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questGiverID"] = 119166, ["questTurnInID"] = 119166, ["questType"] = "standard", ["sourceQuests"] = { 46237 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46241] = { ["id"] = 46241, ["name"] = "The Minions of Hel'nurath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 646, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["series"] = { 46242 }, ["description"] = "The dreadlord Hel'nurath gifts his lieutenants with calling stones to call and bind the dreadsteeds of Xoroth to their service. I believe one such stone will help us draw out the Wrathsteed. Some Xorothian cultists have been spotted helping the Legion's efforts on the Broken Shore. It would be safe to assume their leader has one of Hel'nurath's stones. Your succubus should be able to entice the truth out of the cultists. Find one who knows of their leader's whereabouts.", ["objectivesText"] = "Use your Succubus' Seduction to question Xorothian Cultists within the Dark Stockades in the Broken Shore.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["ends"] = { { ["x"] = 0.353, ["y"] = 0.385, ["mapID"] = 717, ["npcID"] = 119166 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.353, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 119166, ["questTurnInID"] = 119166, ["questType"] = "standard", ["sourceQuests"] = { 46238, 46239, 46240, 94850 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46242] = { ["id"] = 46242, ["name"] = "The Dreadlord's Calling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["series"] = { 46241 }, ["description"] = "According to the cultist, the leader you seek should be in her tower overseeing the operations in the Dark Stockades.", ["objectivesText"] = "Collect a Xorothian Calling Stone from Zuriwa the Hexxer within the Dark Stockades in the Broken Shore. Progress: I trust you found the stone?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144445 }, ["ends"] = { { ["npcID"] = 119166, ["x"] = 0.354, ["y"] = 0.382, ["mapID"] = 717 } }, ["mapCandidates"] = { ["npc"] = { 717 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46241 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46243] = { ["id"] = 46243, ["name"] = "The Wrathsteed of Xoroth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "The time has come and the preparations have been made. When you are ready, we will tear a hole into Xoroth, and force the Arax'ath and the Wrathsteed out of hiding. Follow me to the summoning platform. From there we will initiate the ritual. Prepare yourself, <name>. This will not be an easy undertaking.", ["objectivesText"] = "Complete the ritual on the Summoning Platform in Dreadscar Rift to enslave the Wrathsteed.", ["rewardGold"] = 202200, ["rewardXP"] = 7675, ["rewardItems"] = { 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638 }, ["starts"] = { { ["x"] = 0.356, ["y"] = 0.384, ["mapID"] = 717, ["npcID"] = 119166 } }, ["ends"] = { { ["x"] = 0.356, ["y"] = 0.384, ["mapID"] = 717, ["npcID"] = 119166 } }, ["coords"] = { ["mapID"] = 717, ["x"] = 0.356, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questGiverID"] = 119166, ["questTurnInID"] = 119166, ["questType"] = "standard", ["sourceQuests"] = { 46242 }, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717 },
[46244] = { ["id"] = 46244, ["name"] = "Cathedral of Eternal Night: Altar of the Aegis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8527, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "Champion, we are ready to assault the Tomb of Sargeras. I studied the writings of Aegwynn, the Guardian who defeated the Dark Titan's avatar. She said that if her wards were compromised, a failsafe could be triggered by placing the Aegis of Aggramar upon an altar in the Cathedral of Eternal Night . You are the hero who acquired the Pillars of Creation, <name>. Gather your allies and enter the Cathedral. Be warned: Mephistroth will use all his power to stop you from placing the Aegis. You must prevail!", ["objectivesText"] = "Defeat Lord Mephistroth and place the Aegis of Aggramar upon the Altar of Eternal Night. Progress: There is little time. Mephistroth must be defeated, and the Cathedral of the Eternal Night secured.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146925, 146926, 146927, 146928, 146929, 146930, 146931, 146932, 146933, 146934 }, ["rewardChoices"] = { 146925, 146926, 146927, 146928, 146929, 146930, 146931, 146932, 146933, 146934 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 46286 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46245] = { ["id"] = 46245, ["name"] = "Begin Construction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "We've got the supplies. Now someone needs to decide what to do with 'em. Hmm. Looks like it's your call, being the <class>t and all! Time to pick a building to focus on.", ["objectivesText"] = "Use the Construction Table to donate Legionfall War Supplies to the construction of the Mage Tower, Nether Disruptor, or Command Center. Progress: Oi! Which building should we work on? I've got deadlines to meet, mate!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46286 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46246] = { ["id"] = 46246, ["name"] = "Strike Them Down", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "The Felstorm continues to rain demon scum upon these shores. Kil'jaeden believes his army infinite, his resources inexhaustible. We will show him how wrong he is. Cut a swath of retribution through their ranks, <class>t. Strike down demon after demon, until your weapons are bathed in their blood. And when they cry out for mercy, send them screaming back into the Nether.", ["objectivesText"] = "Slay 100 demons on the Broken Shore. Progress: Did they plead for their lives? Did they whimper as they bled away to nothingness?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardCurrencies"] = { { ["id"] = 1226, ["amount"] = 5000 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46249 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46247] = { ["id"] = 46247, ["name"] = "Defending Broken Isles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "In our zeal to reclaim the Broken Shore from the Legion, we cannot allow the rest of this land to fall into the demons' foul grip. Kil'jaeden has dispatched his forces across the Broken Isles, threatening the homelands of the allies you have made. You must answer their call in this hour of need. Turn back these demon assaults with haste, <class>t. The Armies of Legionfall will see that the Broken Shore remains secured.", ["objectivesText"] = "Defeat a Legion Assault in the Broken Isles.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46286 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46248] = { ["id"] = 46248, ["name"] = "Self-Fulfilling Prophecy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "In my life, I have witnessed many visions. Some filled me with hope... others, with despair. Victory over Kil'jaeden lies within our grasp. I have foreseen it. But visions only show us where our path might lead. They require effort to become reality. That effort falls upon your shoulders, <name>. You have done much, but more is needed. Fight on the battlefields of the Broken Shore and forge a destiny free from the Legion's grasp!", ["objectivesText"] = "Complete World Quests on the Broken Shore. Progress: How go your efforts on the warfront?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 147842 }, ["rewardCurrencies"] = { { ["id"] = 1342, ["amount"] = 50 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120372, ["x"] = 0.445, ["y"] = 0.633 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120372, ["x"] = 0.445, ["y"] = 0.633 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.633 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 47139 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46249] = { ["id"] = 46249, ["name"] = "Championing Our Cause", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "Important work has been done by your order, <class>t. Your champions have succeeded time and again in undermining the Legion's invasion. As we make preparations for our assault on the Tomb of Sargeras, we need to keep the demons off balance. By pressuring them at every turn, we will expose vulnerabilities that can be exploited to our advantage. Send out your order's champions, <name>. Their missions are vital to the success of our campaign... especially as our confrontation with Kil'jaeden draws closer.", ["objectivesText"] = "Successfully complete a Legionfall mission at your Class Order Hall.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 146949, 146950, 147500, 147905, 153005 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 15000 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46250 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46250] = { ["id"] = 46250, ["name"] = "Take Out the Head...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "The Broken Shore swims with Legion filth, each demon deserving of a swift and merciless end. But some are more insidious than the rest. Powerful combatants rallying others to their perfidious cause. Strike down these demon champions and you will fill the hearts of their kin with fear and doubt. Break the Legion's spirit and we will break its back.", ["objectivesText"] = "Slay Rare Elite Demon Commanders on the Broken Shore. Progress: Are they dead yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 147775 }, ["rewardCurrencies"] = { { ["id"] = 1226, ["amount"] = 3000 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46769 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46251] = { ["id"] = 46251, ["name"] = "Shard Times", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "As you have surely noticed, a slain demon leaves behind Nethershards , solidified residual energy from the Twisting Nether. I require a significant quantity of them for an experiment I'm conducting... $1oa shards, to be precise. Why are you looking at me like that? We've had this conversation before. I did the math. I need exactly $1oa shards. Fewer would be inadequate. More would be absurd. Don't question my methods. Go!", ["objectivesText"] = "Collect 2500 Nethershards on the Broken Shore. Progress: Do you have the shards? I hope you kept an accurate count. If you counted wrong, I simply can't be held responsible for the consequences.", ["rewardXP"] = 7675, ["rewardItems"] = { 69777 }, ["rewardCurrencies"] = { { ["id"] = 1226, ["amount"] = 2499 } }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 47137 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46252] = { ["id"] = 46252, ["name"] = "Intolerable Infestation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["description"] = "While we purge Legion filth from the Broken Shore, the fiends maintain their hold on nearby lands. Their presence can no longer be tolerated. The fetid strongholds of Faronaar and Felsoul Hold infest Azsuna and Suramar. Choose an attack point and cut a swath through their insidious ranks. Return to me with demon blood on your hands, then we can resume our campaign to drive Kil'jaeden from the Tomb.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardCurrencies"] = { { ["id"] = 1226, ["amount"] = 2000 } }, ["starts"] = { { ["npcID"] = 116576, ["x"] = 0.446, ["y"] = 0.634, ["mapID"] = 646 } }, ["ends"] = { { ["npcID"] = 116576, ["x"] = 0.446, ["y"] = 0.634, ["mapID"] = 646 } }, ["coords"] = { ["x"] = 0.446, ["y"] = 0.634, ["source"] = "quest_giver", ["mapID"] = 646 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46248 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } } },
[46253] = { ["id"] = 46253, ["name"] = "Pillars of Creation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46253 }, ["description"] = "Our campaign on the Broken Shore has reached a turning point. The Armies of Legionfall stand ready to breach the Tomb of Sargeras and seal the Legion's gateway to our world. The time to strike is now, <name>. The Aegis of Aggramar has been secured in the Cathedral. The echo of Magna Aegwynn said that the other Pillars of Creation are needed to seal the tomb. It is fitting that you have the honor of locking those ancient relics in place and closing down the Felstorm once and for all.", ["objectivesText"] = "Use the Pillars of Creation to seal the Tomb of Sargeras. Progress: The Legion's invasion must be ended.", ["rewardItems"] = { 5816, 152504 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 }, { ["mapID"] = 619, ["npcID"] = 122799, ["x"] = 0, ["y"] = 0 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 }, { ["mapID"] = 619, ["npcID"] = 122799, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 619, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46734 } },
