[46258] = { ["id"] = 46258, ["name"] = "The Calm After the Storm", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45769, 45883 }, ["description"] = "You have saved the elements from the Legion's control, and for that we thank you. However, it came at a great cost to both your health and your fellow shaman. Many came back to us wounded, dragged along by their fellow shaman. We have seen the havoc the Doomstone can wreak. It does not belong in the hands of any being, mortal or otherwise. While you were asleep, the elemental lords and I discussed its fate. Bring it to Neptulon . He will explain.", ["objectivesText"] = "Bring the Doomstone to Neptulon in the Maelstrom. Progress: We must watch over the Doomstone. Its power is too great.", ["rewardGold"] = 300800, ["rewardXP"] = 6140, ["rewardItems"] = { 147475 }, ["starts"] = { { ["x"] = 0.304, ["y"] = 0.518, ["mapID"] = 726, ["npcID"] = 106519 } }, ["ends"] = { { ["x"] = 0.304, ["y"] = 0.518, ["mapID"] = 726, ["npcID"] = 106519 } }, ["coords"] = { ["mapID"] = 726, ["x"] = 0.304, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questGiverID"] = 106519, ["questTurnInID"] = 106519, ["questType"] = "standard", ["sourceQuests"] = { 45769 }, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726 },
[46259] = { ["id"] = 46259, ["name"] = "Darkbinder Dilemma", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45147, 45890, 46259 }, ["series"] = { 45145, 45890 }, ["description"] = "Ah, Delas sent you. I see. It's good she didn't come herself. It would break her heart to see what is happening to our family. A demon is defiling our dead in the ruins nearby. She's using her fel magic on our ancestors, turning them into mindless horrors that do the bidding of the Burning Legion. I can't deal with the harpies and this demon, but maybe you could help? Get rid of the darkbinder that torments our dead, and I will grant you access to whatever's left of the Moonfang family relics.", ["objectivesText"] = "Kill Darkbinder Elissath . Progress: Our dead will never know peace until Darkbinder Elissath is killed.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["sourceQuests"] = { 45890 }, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[46260] = { ["id"] = 46260, ["name"] = "Meld Into the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 45628, 45629 }, ["description"] = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", ["objectivesText"] = "Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147474 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117259, ["questType"] = "standard", ["sourceQuests"] = { 45628 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
