[46266] = { ["id"] = 46266, ["name"] = "Return of the Slayer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 45798 }, ["description"] = "If you're anything like me, I'm sure you'd prefer to remain here on solid ground. Unfortunately, it is probably best to return to the Fel Hammer right away so Kor'vass can finish the repairss.", ["objectivesText"] = "Return to Kor'vas aboard the Fel Hammer.", ["rewardXP"] = 7675, ["rewardItems"] = { 147458 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117709, ["questType"] = "standard", ["sourceQuests"] = { 45764, 45798, 46725 }, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720 },
[46267] = { ["id"] = 46267, ["name"] = "Return of the Battlelord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["description"] = "Battlelord <name>, Odyn will want to hear the tale of your glorious victories here! I will assist you in returning to Skyhold when you are ready.", ["objectivesText"] = "Talk to Odyn in Skyhold.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 147481 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 116858, ["questType"] = "standard", ["sourceQuests"] = { 45633, 45634, 45647, 45649, 45650 }, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695 },
[46268] = { ["id"] = 46268, ["name"] = "A Found Memento", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["description"] = "<The trinket's fine brass exterior is inlaid with intricate filigree, though much of the detail has been battered by rocks and waves. Clearing away the grime and salt encrusting the clasp, you manage to open it. It is a compass--or was, at least. The glass face is shattered, the needle bent, unmoving. Set into the lid is a portrait. The paint is faded and waterlogged, but the subject is unmistakable: the face of a young Anduin Wrynn .>", ["objectivesText"] = "Bring the compass to King Anduin Wrynn in Stormwind Keep. Progress: Well met, <name>. What brings you to Stormwind this day?", ["rewardXP"] = 4605, ["rewardItems"] = { 146408, 147441, 147442, 147444 }, ["starts"] = { { ["x"] = 0.535, ["y"] = 0.805, ["mapID"] = 646, ["objectID"] = 268478 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84, ["startItems"] = { 146407 } },
