[46272] = { ["id"] = 46272, ["name"] = "Summons to the Keep", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46274, 46275, 46282 }, ["description"] = "Greetings, <name>. Your presence has been requested in the royal court. The crown has urgent need of you! Please return to Stormwind at your earliest convenience. King Greymane is anticipating your swift arrival.", ["objectivesText"] = "Meet with Genn Greymane at Stormwind Keep.", ["rewardGold"] = 151650, ["rewardXP"] = 4605, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120281, ["x"] = 0.415, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 119338, ["x"] = 0.8612, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 84, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46268 }, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[46273] = { ["id"] = 46273, ["name"] = "The Giver of Quests", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 46273 }, ["description"] = "asdf See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(46273)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(46273))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "asdf", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[46274] = { ["id"] = 46274, ["name"] = "Consoling the King", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46272, 46275, 46282 }, ["description"] = "Anduin hasn't been the same since you brought him his father's compass. He has become listless... distracted. We attempted to console him, to no avail. Yesterday morning, he left the keep without so much as a word. I ordered the guards to follow him, of course. He went to pray at the cathedral, where he's remained ever since. You brought this melancholy upon him! You must convince the boy to resume his duties. There's a war to be won!", ["objectivesText"] = "Look for King Anduin Wrynn inside Stormwind Cathedral.", ["rewardGold"] = 151650, ["rewardXP"] = 4605, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 119338, ["x"] = 0.8612, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 119357, ["x"] = 0.499, ["y"] = 0.453 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8612, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 46272 }, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[46275] = { ["id"] = 46275, ["name"] = "A Kingdom's Heart", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46272, 46274, 46282 }, ["description"] = "My father was a legend. He oversaw the rebuilding of Stormwind, stood toe-to-toe with dragons, led the Alliance to numerous victories. Then, one day, he was just... gone. I wear his crown, I hold his title. But I've done nothing to earn them... or the faith of my people. I've spent the war sequestered in the keep, surrounded by guards and advisors. I need to walk the streets of Stormwind, to know whether it is hope or fear that beats in the hearts of my people. I welcome your company.", ["objectivesText"] = "Accompany King Anduin on his walk through Stormwind.", ["rewardXP"] = 6140, ["rewardItems"] = { 93168, 147442 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 119357, ["x"] = 0.499, ["y"] = 0.453 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 120268, ["x"] = 0.854, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.453 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 46274 }, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[46277] = { ["id"] = 46277, ["name"] = "Contribute to Mage Tower", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 46277 }, ["rewardItems"] = { 152654 }, ["rewardCurrencies"] = { { ["id"] = 1226, ["amount"] = 75 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[46278] = { ["id"] = 46278, ["name"] = "Return to Sender", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 46278 }, ["description"] = "You've arrived just in time! Unlike the mail as of late, I'm afraid. We are severely understaffed, and demand is at an all-time high. We simply can't keep up! I'd love to chat, but I need help catching up before I can rest for even a moment. First thing's first. Several parcels of rejected mail have broken loose again; will you help me round them all up and return them to their senders?", ["objectivesText"] = "Return 9 Rejected Letters.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 134859, 156721, 156833 }, ["starts"] = { { ["x"] = 0.33, ["y"] = 0.317, ["mapID"] = 627, ["npcID"] = 103976 } }, ["ends"] = { { ["x"] = 0.33, ["y"] = 0.317, ["mapID"] = 627, ["npcID"] = 103976 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.33, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 103976, ["questTurnInID"] = 103976, ["questType"] = "standard", ["sourceQuests"] = { 41368, 41411 } },
