[46282] = { ["id"] = 46282, ["name"] = "The King's Path", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46272, 46274, 46275 }, ["description"] = "Now that I have seen the Broken Shore and the terror of the Burning Legion first hand, my eyes have been opened to the truth. I speak not of the unfathomable evil of the enemy, but of the bravery and sacrifice that such evil brings about in the hearts of our people. My father once told me that every king must carry the weight of his own crown. Mine has never felt heavier than it does at this very moment... Please take me to the place where my father died, so that I may honor his sacrifice.", ["objectivesText"] = "Accompany King Anduin to the Tomb of Sargeras.", ["rewardXP"] = 6140, ["rewardItems"] = { 147444 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 121237, ["x"] = 0.590333, ["y"] = 0.262333 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120288, ["x"] = 0.604, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.590333, ["y"] = 0.262333 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 47112 }, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46286] = { ["id"] = 46286, ["name"] = "Legionfall Supplies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "If we don't build up some respectable fortifications, we'll lose our foothold on the Broken Shore. That ain't gonna happen on my watch, mate! We started construction on three key structures: the Mage Tower, the Nether Disruptor, and the Command Center. Each will play a key role in helping us pound the tar out of the Burning Legion. To make progress, we need Legionfall War Supplies... and I mean lots of 'em! You bring 'em to me, and I'll handle distribution. Got it?", ["objectivesText"] = "Complete World Quests or slay Rare Elites on the Broken Shore to earn Legionfall War Supplies. Progress: Crikey! Did you bring me Legionfall War Supplies?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46734 }, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
