[46290] = { ["id"] = 46290, ["name"] = "Return of the Archmage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45586, 46000 }, ["description"] = "With Dalaran protected once again, we can all breathe a little easier. It is time for us to return to the Hall of the Guardian. I'm sure Meryl is anxiously awaiting word of our success.", ["objectivesText"] = "Speak to Meryl in the Hall of the Guardian.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 147464 }, ["starts"] = { { ["x"] = 0.273, ["y"] = 0.515, ["mapID"] = 627, ["npcID"] = 118242 } }, ["ends"] = { { ["x"] = 0.273, ["y"] = 0.515, ["mapID"] = 627, ["npcID"] = 118242 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.273, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 118242, ["questTurnInID"] = 118242, ["questType"] = "standard", ["sourceQuests"] = { 46000 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[46291] = { ["id"] = 46291, ["name"] = "The Deadmines Strike Back", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8630, ["mapID"] = 52, ["storyline"] = { 46291 }, ["series"] = { 46293 }, ["description"] = "Breanni sent you? For her, info is always free. Just don't call me a snitch. I've been hangin' around the Deadmines for years. For the most part, it's a pretty easy livin'. But a few days ago, I started hearing noises of all sorts comin' from the mines. If you want to get in unnoticed, I'll grab us a mine cart and we can get most of the way down without so much as an awkward glace in our direction. Just let me know when you're ready to head in.", ["objectivesText"] = "Defeat Cookies' Leftovers in the Deadmines. Progress: I can sneak you in. Getting out might be more of a challenge.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 122457 }, ["starts"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 8630 } }, ["questType"] = "standard", ["sourceQuests"] = { 46293 } },
[46292] = { ["id"] = 46292, ["name"] = "Pet Battle Challenge: Deadmines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8630, ["mapID"] = 52, ["storyline"] = { 46292 }, ["description"] = "The Deadmines could still use some cleaning up, seems you didn't clear the place out last time. We'll use the ol' mine cart trick again. Cept, we're going to put some flair into it. How do you feel about fire? No? Okay, fine. Just let me know when you're ready.", ["objectivesText"] = "Defeat Cookies' Leftovers in the Deadmines. Progress: I can sneak you in. Getting out might be more of a challenge.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 86143, 90173, 151191 }, ["starts"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 8630 } }, ["questType"] = "standard", ["sourceQuests"] = { 46291 } },
[46293] = { ["id"] = 46293, ["name"] = "Deadmines, Part Three?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 52, ["storyline"] = { 46293 }, ["series"] = { 46291 }, ["description"] = "I've heard suspicious rumors of movement in the Deadmines. After everything you pulled off in the Wailing Caverns, you'd be the perfect person to look into this! I have a friend in Westfall. He may not look like much, but he's quick as a whip and may have more information on what is happening in Westfall. We've already dealt with the Van Cleefs... twice. So what could be making that sort of ruckus down there?", ["objectivesText"] = "Find Marcus \"Bagman\" Brown outside the Deadmines in Westfall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 122457 }, ["starts"] = { { ["x"] = 0.582, ["y"] = 0.394, ["mapID"] = 627, ["npcID"] = 96479 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 7502 } }, ["questGiverID"] = 96479, ["questType"] = "standard" },
[46297] = { ["id"] = 46297, ["name"] = "Overwhelming Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "We will find no sanctuary on this world. Even now the full might of the Burning Legion rises to defend Argus. The siege camp below overflows with demon filth that stand between us and the weapon trained on the Vindicaar. They must be dealt with before it can fully charge, or Argus will be our grave.", ["objectivesText"] = "Kill 12 demons. Progress: Is the way to the weapon clear?", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 152690, 152691, 152692, 152693, 152694, 152695, 152696, 152697, 152715, 153421, 256763 }, ["rewardChoices"] = { 152690, 152691, 152692, 152693, 152694, 152695, 152697, 152715, 153421 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119535, ["x"] = 0.575, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 123148, ["x"] = 0.542, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["sourceQuests"] = { 46938 }, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830 },
