[46305] = { ["id"] = 46305, ["name"] = "Thorim's Flame", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 44787 }, ["description"] = "Not too long ago, the Drekirjar and the Thorignir respected each other. This only changed when Skovald came into power. An ancient Drekirjar spirit watches over this peak, which seems to be a sacred graveyard of some sort. He is the keeper of the ceremonial flame, which happens to be exactly what we need to call down the broodmother. Why don't we go convince him to let us take the flame? I'm sure he'll be nothing but... amiable.", ["objectivesText"] = "Convince the Drekirjar Shrine-Keeper to let you take Thorim's Flame. Progress: Although the spirit might stand unconvinced that raising the bodies of his deceased allies for our own bidding is necessary, we could always slaughter him to get our way. Seems normal for us.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.513, ["y"] = 0.843, ["mapID"] = 634, ["npcID"] = 116737 } }, ["ends"] = { { ["x"] = 0.513, ["y"] = 0.843, ["mapID"] = 634, ["npcID"] = 116737 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.513, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 116737, ["questTurnInID"] = 116737, ["questType"] = "standard", ["sourceQuests"] = { 44775 }, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
