[46314] = { ["id"] = 46314, ["name"] = "Vengeance: Seeking Kor'vas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45413, 45414, 45415, 45843, 45863, 46314 }, ["series"] = { 45412, 45413, 45414, 45415, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city. One of your Illidari, Kor'vas Bloodthorn , has taken to patrolling the city streets on her own to find the source behind the recent attacks. I do not entirely trust your kind, but I will concede that you have at least proved adept at your namesake. I suggest you find Kor'vas and see what she has uncovered before the Legion strikes once more. Specialization: Vengeance Demon Hunter", ["objectivesText"] = "Find Kor'vas Bloodthorn in the streets of Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.225, ["y"] = 0.406, ["mapID"] = 627, ["npcID"] = 90431 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questGiverID"] = 90431, ["questType"] = "standard", ["sourceQuests"] = { 44821, 47030 }, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
