[46317] = { ["id"] = 46317, ["name"] = "Talon's Call", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46317, 46318, 46319 }, ["description"] = "The Legion is launching a renewed assault against the Shrine of Aviana in Hyjal! Thisalee Crow is organizing a counter-offensive, she requests your presence in the Dreamgrove at once. We will handle the offensive here. Good luck, Archdruid!", ["objectivesText"] = "Speak with Thisalee Crow in the Dreamgrove.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140394 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118105, ["x"] = 0.438, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118105, ["x"] = 0.438, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 118105, ["questType"] = "standard", ["sourceQuests"] = { 46044 }, ["questLines"] = { { ["id"] = 790, ["name"] = "Class Mount: Druid", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 790, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[46318] = { ["id"] = 46318, ["name"] = "Defense of Aviana", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 46317, 46318, 46319 }, ["description"] = "The situation is dire. The Legion is attacking the Shrine of Aviana in Hyjal, AGAIN! They must be after something specific, but I'm not sure what. Us Druids of the Talon are skilled scouts and infiltrators, but are lacking in... durability. They won't be able to hold out for long! We must go to help!", ["objectivesText"] = "Assist Thisalee in the defense of the Shrine of Aviana in Hyjal, then return to her in the Dreamgrove. Progress: What are you waiting for?! Get to the Shrine of Aviana in Hyjal!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140394, 143638 }, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 106299 } }, ["ends"] = { { ["x"] = 0.446, ["y"] = 0.514, ["mapID"] = 747, ["npcID"] = 106299 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.446, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 106299, ["questTurnInID"] = 106299, ["questType"] = "standard", ["sourceQuests"] = { 46317 }, ["questLines"] = { { ["id"] = 790, ["name"] = "Class Mount: Druid", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 790, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[46319] = { ["id"] = 46319, ["name"] = "You Can't Take the Sky from Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 46317, 46318, 46319 }, ["description"] = "The Shrine of Aviana has fallen to the demons, and the Idol of Aviana has been stolen. That idol acts as a link between the Druids of the Talon and the powers of flight granted to us by Aviana. The Druids of the Talon have decided to rebuild a new shrine in a more secure location: here in the Dreamgrove. Meanwhile, I'm going to get our idol back. Meet me in Azsuna, near where we've tracked Infazzar to, if you want to help.", ["objectivesText"] = "Deal with Infazzar the Shade, and retrieve the Idol of Aviana. Progress: <Place the Corrupted Idol of Aviana on the pedestal.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140394, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 146798 }, ["starts"] = { { ["x"] = 0.311, ["y"] = 0.042, ["mapID"] = 747, ["npcID"] = 106299 } }, ["ends"] = { { ["x"] = 0.311, ["y"] = 0.042, ["mapID"] = 747, ["npcID"] = 106299 } }, ["coords"] = { ["mapID"] = 747, ["x"] = 0.311, ["y"] = 0.042 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questGiverID"] = 106299, ["questTurnInID"] = 106299, ["questType"] = "standard", ["sourceQuests"] = { 46318 }, ["questLines"] = { { ["id"] = 790, ["name"] = "Class Mount: Druid", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 790, ["questLineOrder"] = 10 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747 },
[46320] = { ["id"] = 46320, ["name"] = "Hope For a Cure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45442 }, ["description"] = "Hopefully you found enough fel poison samples with which to brew a cure. Let's meet back to the Temple of Five Dawns!", ["objectivesText"] = "Return to the Spirit of Brewmaster Blanche in the Temple of Five Dawns.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117305, ["questType"] = "standard", ["sourceQuests"] = { 45449, 45545, 45574 }, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 6, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[46322] = { ["id"] = 46322, ["name"] = "The Pirate's Bay", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["series"] = { 44758, 45833 }, ["description"] = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned. We've received word of a large cave off the main island, where powerful demons meet to plot our downfall. One of our rogues, Lilian Voss , has formulated a plan with Tethys to take care of them, but they require your aid. They are waiting for you at Dead Man's Bay in Azsuna.", ["objectivesText"] = "Meet up with Lilian Voss and Tethys at Dead Man's Bay in Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 143679 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.78, ["mapID"] = 626, ["npcID"] = 101513 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questGiverID"] = 101513, ["questType"] = "standard", ["sourceQuests"] = { 43422, 47137 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[46323] = { ["id"] = 46323, ["name"] = "What's the Cache?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "Our goal is to retrieve a cache of gunpowder which has been infused with some sort of fel power. I don't know how the pirates here acquired it, but it is more dangerous than they know. I assure you that it will be more... effective in our hands. Master Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", ["objectivesText"] = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache . Progress: Did you get it?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142116 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 46322 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[46324] = { ["id"] = 46324, ["name"] = "False Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "We must take some precautions. As soon as you assassinate the gunner, the crew will be looking for you. I had Tethys forge some orders in her handwriting that should buy us some time. Plant the orders in the marked locations. That will take care of the danger.", ["objectivesText"] = "Plant the False Orders in the marked locations.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["sourceQuests"] = { 46322 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
