[46326] = { ["id"] = 46326, ["name"] = "Jorach's Calling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "And with that, the first phase of my machination is complete. Let's return to Jorach and tell him it is time to continue.", ["objectivesText"] = "Return to Lord Jorach Ravenholdt in the Hall of Shadows.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questTurnInID"] = 119822, ["questType"] = "standard", ["sourceQuests"] = { 45848 }, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[46327] = { ["id"] = 46327, ["name"] = "Bargaining with Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["description"] = "From the clues you've been able to piece together, it appears that Levia was looking to conduct a ritual in the libraries beneath Dalaran - most likely to summon this \"Agatha\" she has become so infatuated with. I'm afraid this is a little out of my area of expertise, so I'm going to have to call in a favor. I'll send for assistance from the Council of the Black Harvest. One of their warlocks will meet you in the Chamber of the Guardian to assist with your investigation. I hope we're not too late.", ["objectivesText"] = "Meet Ritssyn Flamescowl in the Chamber of the Guardian beneath Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["ends"] = { { ["x"] = 0.285, ["y"] = 0.489, ["mapID"] = 627, ["npcID"] = 90418 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.285, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 90418, ["questTurnInID"] = 90418, ["questType"] = "standard", ["sourceQuests"] = { 45123, 47055, 47056, 47057, 47058, 47059 }, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[46333] = { ["id"] = 46333, ["name"] = "Livin' on the Ledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46333, 46334 }, ["description"] = "Slayer $p, Matron Mother Malevolence requests an audience with you back at the Fel Hammer. Please see her at your earliest convenience.", ["objectivesText"] = "Return to the Fel Hammer and speak with Matron Mother Malevolence .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118306, ["x"] = 0.43625, ["y"] = 0.61975 }, { ["mapID"] = 646, ["npcID"] = 118307, ["x"] = 0.4375, ["y"] = 0.622 }, { ["mapID"] = 646, ["npcID"] = 118314, ["x"] = 0.434571, ["y"] = 0.614286 }, { ["mapID"] = 646, ["npcID"] = 118316, ["x"] = 0.436857, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118306, ["x"] = 0.43625, ["y"] = 0.61975 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.43625, ["y"] = 0.61975 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 118306, ["questType"] = "standard", ["sourceQuests"] = { 45391 }, ["questLines"] = { { ["id"] = 787, ["name"] = "Class Mount: Demon Hunter", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 787, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[46334] = { ["id"] = 46334, ["name"] = "To Fel and Back", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 46333, 46334 }, ["description"] = "Mardum has its fair share of secrets, one of which we found not too long after we took control of the Fel Hammer. It's a breeding ground of sorts, festering with fel bats. We've been capturing the pups and trying to train them up for our efforts against the Legion. But the other day, we caught an even greater prize, something worthy of your position, Slayer. Speak with Kyra and she'll provide you a ride to the ledge.", ["objectivesText"] = "Speak with Kyra Lightblade to secure a ride to Felwing Ledge. Then complete the Felwing Ledge scenario.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 147537 }, ["starts"] = { { ["x"] = 0.601, ["y"] = 0.508, ["mapID"] = 720, ["npcID"] = 108784 } }, ["ends"] = { { ["x"] = 0.601, ["y"] = 0.508, ["mapID"] = 720, ["npcID"] = 108784 } }, ["coords"] = { ["mapID"] = 720, ["x"] = 0.601, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questGiverID"] = 108784, ["questTurnInID"] = 108784, ["questType"] = "dungeon", ["sourceQuests"] = { 46333 }, ["questLines"] = { { ["id"] = 787, ["name"] = "Class Mount: Demon Hunter", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 787, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721 },
[46335] = { ["id"] = 46335, ["name"] = "The Vault of the Tirisgarde", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 45437, 46338, 46705 }, ["description"] = "Dalaran's weapons are arcane in origin, but that doesn't mean we can't try something different. Our order's vaults contain a vast store of magical devices... Why don't you take a look around and see if there's anything we can use?", ["objectivesText"] = "Find 5 Ancient Artifacts within the Hall of the Guardian. Progress: Have you found anything promising?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146402, 146403, 146404, 146405, 146409 }, ["starts"] = { { ["x"] = 0.562, ["y"] = 0.379, ["mapID"] = 735, ["npcID"] = 108247 } }, ["ends"] = { { ["x"] = 0.562, ["y"] = 0.379, ["mapID"] = 735, ["npcID"] = 108247 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.562, ["y"] = 0.379 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108247, ["questTurnInID"] = 108247, ["questType"] = "standard", ["sourceQuests"] = { 44766 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[46336] = { ["id"] = 46336, ["name"] = "A Golden Ticket", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46336, 46337 }, ["description"] = "Huntmaster, we've gotten word from the Lodge that there is a letter wrought from golden light sitting on one of the tables, and it's got your name on it. No one is sure how it got there, and someone's wolf may have tried to open it and gotten a mouth full of singed fur. Seems like it's meant only for you. We'll hold down the fort here while you investigate.", ["objectivesText"] = "Read the Golden Letter in Trueshot Lodge.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["rewardItems"] = { 142226, 142228, 147580 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117810, ["x"] = 0.438, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117810, ["x"] = 0.438, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 117810, ["questType"] = "standard", ["sourceQuests"] = { 46048 }, ["questLines"] = { { ["id"] = 791, ["name"] = "Class Mount: Hunter", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 791, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[46337] = { ["id"] = 46337, ["name"] = "Night of the Wilds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8641, ["mapID"] = 739, ["storyline"] = { 46336, 46337 }, ["description"] = "<The letter is written in a flowing, golden script. You can practically hear Odyn's booming voice speak the words as you read it.> The Night of the Wilds is upon us. Tonight, we will feast in honor of the beasts of legend, and they will rise once more in the Fields of the Eternal Hunt. One among us will set out into the fields to put their spirits to rest once more. My herald awaits you, hunter, if you will join us.", ["objectivesText"] = "Ask the Herald of Odyn to take you to the Fields of the Eternal Hunt.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 142224, 142225, 142226, 142227, 142228, 142231, 142232, 143489, 143493, 143502, 143638, 147580 }, ["starts"] = { { ["x"] = 0.429, ["y"] = 0.457, ["mapID"] = 739, ["npcID"] = 119943 } }, ["ends"] = { { ["x"] = 0.429, ["y"] = 0.457, ["mapID"] = 739, ["npcID"] = 119943 } }, ["coords"] = { ["mapID"] = 739, ["x"] = 0.429, ["y"] = 0.457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8641 } }, ["questGiverID"] = 119943, ["questTurnInID"] = 119943, ["questType"] = "standard", ["sourceQuests"] = { 46336 }, ["questLines"] = { { ["id"] = 791, ["name"] = "Class Mount: Hunter", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 791, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739 },
[46338] = { ["id"] = 46338, ["name"] = "A Creative Solution", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 45437, 46335, 46705 }, ["description"] = "The Nightborne Soulstone may be our best hope if we can come up with a way to safely use it without Kathra'natir escaping. If he were to get loose in Dalaran... We should consult with our friend, Ari. She will know what modifications need to be done.", ["objectivesText"] = "Talk to Ari. Progress: Well? What did Ari think?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.562, ["y"] = 0.378, ["mapID"] = 735, ["npcID"] = 108247 } }, ["ends"] = { { ["x"] = 0.562, ["y"] = 0.378, ["mapID"] = 735, ["npcID"] = 108247 } }, ["coords"] = { ["mapID"] = 735, ["x"] = 0.562, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 108247, ["questTurnInID"] = 108247, ["questType"] = "standard", ["sourceQuests"] = { 46335 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
[46339] = { ["id"] = 46339, ["name"] = "Keymaster Orlis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44768, 46345 }, ["description"] = "The Felborne insurgents appear to be guarding a teleporter pad within the glade ahead. I wonder where it leads? It is probably safe to assume that we'll need to kill Keymaster Orlis in order to gain access.", ["objectivesText"] = "Kill Keymaster Orlis and search his body. Progress: Did you find anything?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142241 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 121357, ["x"] = 0.558, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 121358, ["x"] = 0.545, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["sourceQuests"] = { 45207 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[46340] = { ["id"] = 46340, ["name"] = "The Gates Are Closed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 627, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "Sigryn must be reached before she can confront Odyn, but our path is blocked. Odyn will close the Gates of Valor as soon as he becomes aware of Sigryn's assault. You will have to find another way into the Halls. I have no talent with portals, but your friends at the Kirin Tor seem to be very adept. Go now to them, and find a way through. I thank you for what you've done to help Sigryn this far, <class>. I only hope we can save her from herself.", ["objectivesText"] = "Return to Archmage Khadgar at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.65, ["y"] = 0.68, ["mapID"] = 634, ["npcID"] = 93628 } }, ["ends"] = { { ["x"] = 0.65, ["y"] = 0.68, ["mapID"] = 634, ["npcID"] = 93628 } }, ["coords"] = { ["mapID"] = 634, ["x"] = 0.65, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questGiverID"] = 93628, ["questTurnInID"] = 93628, ["questType"] = "standard", ["sourceQuests"] = { 45525 }, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627 },
[46341] = { ["id"] = 46341, ["name"] = "The Tale of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46342, 46343, 46353 }, ["description"] = "Oh, hello, you must be the new Grandmaster. < Master Bu squints at you and sniffs.> You young ones have no patience these days, always running off to fight your great battles. No time for stories, even good ones, eh? Why don't you put your fists down for a moment and allow an old man to tell you a tale. Maybe buy an old man a drink while you are at it?", ["objectivesText"] = "Listen to Master Bu 's story.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["x"] = 0.323, ["y"] = 0.433, ["mapID"] = 709, ["npcID"] = 120758 } }, ["ends"] = { { ["x"] = 0.323, ["y"] = 0.433, ["mapID"] = 709, ["npcID"] = 120758 } }, ["coords"] = { ["mapID"] = 709, ["x"] = 0.323, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questGiverID"] = 120758, ["questTurnInID"] = 120758, ["questType"] = "standard", ["sourceQuests"] = { 46353 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[46342] = { ["id"] = 46342, ["name"] = "Return to the Broken Peak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46341, 46343, 46353 }, ["description"] = "Of course, this is no mere story. Ban-Lu served as the personal mount of each of the previous Grandmasters, accompanying them through their travels as a faithful and trusted companion. But... he has not revealed himself since you have become Grandmaster. This is troubling. The last time he was seen was at the Peak of Serenity, after the fall of Grandmaster Hight. It is there that we must begin our search for him.", ["objectivesText"] = "Meet Master Bu at the Peak of Serenity.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["x"] = 0.323, ["y"] = 0.433, ["mapID"] = 709, ["npcID"] = 120758 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 7902 } }, ["questGiverID"] = 120758, ["questType"] = "standard", ["sourceQuests"] = { 46341 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[46343] = { ["id"] = 46343, ["name"] = "The Trail of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46341, 46342, 46353 }, ["description"] = "It seems a lifetime ago that Grandmaster Hight was walking these grounds. While Ban-Lu has served every previous Grandmaster, he and Hight were the greatest of friends. For many years they traveled the land, connecting with its people and maintaining our fragile peace. I cannot imagine how deeply Ban-Lu must have been affected by his passing. There must be some clues to his whereabouts around here. Look sharply.", ["objectivesText"] = "Follow the trail of Ban-Lu. Progress: Have you found any more clues, Grandmaster?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 46342 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[46344] = { ["id"] = 46344, ["name"] = "Smelly's Luckydo", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["description"] = "You! Please help! Stupid hozen stole Smelly's luckydo ! Now, Smelly always unlucky. Just turned around and look, pack is on fire. Not going to put fire out because then something ELSE unlucky happen. Maybe something worse! You beat up hozen, yes? Get back luckydo? Smelly will help you, any way he can!", ["objectivesText"] = "Collect 3 parts of Smelly's Luckydo . Progress: Find my luckydo yet? Getting kind of hot here.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147314, 147315 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120744, ["x"] = 0.48, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120744, ["x"] = 0.48, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 46343 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
