[46346] = { ["id"] = 46346, ["name"] = "The Shadow of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46347, 46348, 46349 }, ["description"] = "That was good of you to assist Smelly Mountaintop, Grandmaster, and we have learned more about the fate of Ban-lu. I won't bother you with escorting me to Shado-Pan Monastery. I can manage on my own. Meet me there and we'll continue our search.", ["objectivesText"] = "Meet Master Bu at the Shado-Pan Monastery.", ["rewardGold"] = 23870, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 46344 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[46347] = { ["id"] = 46347, ["name"] = "Clean-up on Aisle Sha", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46346, 46348, 46349 }, ["description"] = "I've spoken with the Shado-pan and they are willing to give us information if we can assist them with a task of their own. Speak with Commander Shen-Li . While you're assisting them, I shall continue to meditate.", ["objectivesText"] = "Help Commander Shen-Li with the remaining Sha. Progress: Ooohhmmmm... Ooooohhhhmmmm...", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 46346 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[46348] = { ["id"] = 46348, ["name"] = "The River to Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46346, 46347, 46349 }, ["description"] = "We still do not know where Ban-Lu has gone to, but I do know who might. To the southeast lives a jinyu, Waterspeaker Ryuli . Perhaps he has seen Ban-Lu, or can ask him to inquire with the river about where Ban-Lu has been seen recently? All this travel has done a number on my old joints, Grandmaster. I shall rest here a bit longer, and then catch up with you later on.", ["objectivesText"] = "Meet with Waterspeaker Ryuli to the southeast.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 46347 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390 },
[46349] = { ["id"] = 46349, ["name"] = "Lilies for Ryuli", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46346, 46347, 46348 }, ["description"] = "I have not seen Ban-Lu, but the waters will surely know where he is. There is a flower that grows in the lakes of the mountain slopes near the Temple of the White Tiger, that only blooms in the presence of someone pure of heart. Bring me six of these Moon Lilies and I shall use them to speak to the river.", ["objectivesText"] = "Collect 6 Moon Lilies for Waterspeaker Ryuli . Progress: How goes the Moon Lily collection, Grandmaster?", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 147313 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["sourceQuests"] = { 46348 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379 },
[46350] = { ["id"] = 46350, ["name"] = "The Trial of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["description"] = "Ah, the ripples I feel in the water are strong! The droplet does not fall far from our location. Ban-Lu is quite close. <Ryuli closes his eyes and releases the lilies into the water. They drift slowly to the east.> He waits for you now, at the bottom of the waterfall to the east.", ["objectivesText"] = "Find Ban-Lu at the bottom of the waterfall.", ["rewardGold"] = 238680, ["rewardXP"] = 6140, ["rewardItems"] = { 147542 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questTurnInID"] = 120726, ["questType"] = "standard", ["sourceQuests"] = { 46349 }, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709 },
[46351] = { ["id"] = 46351, ["name"] = "Keep it Secret, Keep it Safe", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44770 }, ["description"] = "The shield generator you found is much more than it appears. I do not think my elders would approve of such advanced technology being shared with outlanders... And yet... We owe you our lives and our freedom. You may use it, with my blessing. Just... please be discreet about its existence, Archmage <name>.", ["objectivesText"] = "Return to Ari in the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 37383, 37434, 37512, 37559 }, ["rewardCurrencies"] = { { ["id"] = 1220, ["amount"] = 2000 } }, ["starts"] = { { ["x"] = 0.471, ["y"] = 0.235, ["mapID"] = 691, ["npcID"] = 116321 } }, ["ends"] = { { ["x"] = 0.471, ["y"] = 0.235, ["mapID"] = 691, ["npcID"] = 116321 } }, ["coords"] = { ["mapID"] = 691, ["x"] = 0.471, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questGiverID"] = 116321, ["questTurnInID"] = 116321, ["questType"] = "standard", ["sourceQuests"] = { 44768, 44770 }, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735 },
