[46509] = { ["id"] = 46509, ["name"] = "Tomb Raidering", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I said to myself over and over, \"Don't go near the citadel. Don't go near the citadel.\" But what did I do? I went to the citadel. Almost had my hands on that sweet treasure chest before I got chased off by a bunch of crazy demons. I made it out of there with just my helmet and my life!", ["objectivesText"] = "Look for the rumored treasure outside the Tomb of Sargeras. Progress: I'm always lookin' for more treasure!", ["rewardXP"] = 6140, ["rewardItems"] = { 141605, 146653, 146662, 146955, 146956, 146957, 146958 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46501 }, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46510] = { ["id"] = 46510, ["name"] = "Ship Graveyard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I haven't told you that I was part of the original landing party when we lost almost everything. I don't care what treasure is left there, I'll never go back to that beach. Never.", ["objectivesText"] = "Look for the rumored treasure deep in the Forlorn Depths. Progress: I'm always lookin' for more treasure!", ["rewardXP"] = 6140, ["rewardItems"] = { 141605, 146653, 146663, 146955, 146956, 146957, 146958 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46509 }, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46511] = { ["id"] = 46511, ["name"] = "We're Treasure Hunters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I have a feeling you're just using me for tips on where all the best treasure is. From now on I'm naga tell you anything. Did I say, \"naga\" just then? I meant to say, I'm not gonna to tell you naga. I mean nada! Darn it! Okay. Seems you got me on this one. I'll tell you what, fetch me whatever is in that chest near those naga freaks and I'll make it worth your while.", ["objectivesText"] = "Look for the rumored treasure on the Felrage Strand. Progress: You fetch that treasure yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146653, 146955, 146956, 146957, 146958, 147484 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46510 }, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46666] = { ["id"] = 46666, ["name"] = "The Motherlode", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "Pst... Come 'ere! I just got a tip about a cave on this island that is a treasure trove of loot! This could be my biggest score yet. Problem is, I uhh... sprained my ankle. Yeah, I would be right there with you battling those demons to get this treasure, but I shouldn't be putting any weight on this leg of mine. Shucks. How about you go check on this cave and report back to me. I'll mark your map where the cave entrance is. I've been told it's pretty hidden, so you've got to look around.", ["objectivesText"] = "Investigate the cave that Excavator Karla told you about. Progress: You find anything?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29813, 29814, 29815, 142452, 143559, 146653, 146953, 146955, 146956, 146957, 146958, 147717, 147867, 147869, 147870 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46511 }, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46674] = { ["id"] = 46674, ["name"] = "The Preservation of Nature", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45498, 45528, 46924 }, ["description"] = "I fear this attack on Goldrinn is only the beginning, <name>. Whoever is ordering these attacks must be found and defeated. Wasn't Thisalee with you? She never returned... brash child. I assume she is already on the Broken Shore, trying to track down this commander. Please, find her. Do not let her take this on alone.", ["objectivesText"] = "Find Thisalee Crow near Deliverance Point on Broken Shore.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["starts"] = { { ["x"] = 0.446, ["y"] = 0.518, ["mapID"] = 747, ["npcID"] = 101195 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7846 } }, ["questGiverID"] = 101195, ["questType"] = "standard", ["sourceQuests"] = { 45426 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46675] = { ["id"] = 46675, ["name"] = "To Track a Demon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45425, 46677 }, ["description"] = "I took the initiative to scout around before I grabbed that wyrmtongue. It seems like their forces are holed up in a camp in Impsorrow Approach. What I've struggled to figure out, however, is who their commander is and if he's nearby. If he's leading from elsewhere, the troops need to have some commands on them. Let's go see if we can find any... on their dead bodies!", ["objectivesText"] = "Collect 3 Impsorrow Missives from demons in Impsorrow Approach. Progress: Collecting some missives should allow me to figure out the commander's position.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147282 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 120070, ["questType"] = "standard", ["sourceQuests"] = { 46674 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46676] = { ["id"] = 46676, ["name"] = "Nature's Touch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "Apparently we're not the only druids that have run into these demons. The Legion took a ton of captives and brought them back to their camp. Our brothers and sisters lay wounded and hurting... You can heal! Let's go save them!", ["objectivesText"] = "Heal 5 Injured Druids in Impsorrow Approach. Progress: We can't let the other druids suffer any longer!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questTurnInID"] = 120070, ["questType"] = "standard", ["sourceQuests"] = { 46674 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46677] = { ["id"] = 46677, ["name"] = "Prick of a Thistle", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45425, 46675 }, ["description"] = "Their commander's name is Katith'rax. He's the one who organized these attacks, and now the one who leads them. Luckily, it doesn't seem as though he's far off. Right off the coast is a small island. Seems as though he hides there, barking orders without getting his hands dirty. I, on the other hand, enjoy getting my hands a little dirty. Don't you?", ["objectivesText"] = "Kill Commander Katith'rax on Darkstone Isle. Progress: This guy is going to pay for what he's done!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["npcID"] = 120070 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questGiverID"] = 120070, ["questType"] = "standard", ["sourceQuests"] = { 46675, 46676 }, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646 },
[46678] = { ["id"] = 46678, ["name"] = "The Legend of the Threads", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46678 }, ["description"] = "Tailoring is the noblest of professions because clothing is universal. Most dress with nary a thought. If you analyze the legends, some races stand out from all others. The Nightborne are masters of style! Much of the brilliance is in their materials--in particular their thread and their looms. We will take advantage of both. Before you gather materials, I need to confirm my list. Find the fashion treatise I brought with me. Perhaps I dropped it by the flight master?", ["objectivesText"] = "Bring Eliezer his lost copy of Nights with the Nightborne Progress: I need a copy of Nights with the Nightborne so we can focus our efforts. I probably left it on my flight over.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 147281, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46804 } },
[46679] = { ["id"] = 46679, ["name"] = "The Thread of Shadow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46679 }, ["series"] = { 46680, 46682, 46683 }, ["description"] = "Vandros of the Nightborne. There is an elf who knows how to dress. Ever since he was a young noble in the Court of Farondis, Vandros has been known for snappy, fashion forward outfits. I've never been able to see his garments up close but my research tells me that his tailor's technique is not so much in the fabric as it is in the thread. It appears to be spun of the very shadows themselves. You have your methods to obtain it, I'm sure. Get his robes and get the thread.", ["objectivesText"] = "Defeat Advisor Vandros in the Arcway in Mythic difficulty and extract Shadow Thread from his robes. Progress: Vandros maybe be difficult to defeat but we really need that shadow thread from his robes.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146678, 146679 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46678 } },
[46680] = { ["id"] = 46680, ["name"] = "The Thread of Starlight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46680 }, ["series"] = { 46679, 46682, 46683 }, ["description"] = "Melandrus of the Nightborne is First Blade of Elisande. Perhaps you've heard of him? He is a great hero to the Nightborne but, to be absolutely honest, he is a mess with regards to style. His accoutrements are somewhat better and a particular pair or bracers are rather nice. In fact, the thead that binds them will be absolutely perfect for your pending outfits. Why don't you get that for me and we will talk further.", ["objectivesText"] = "Defeat Advisor Melandrus in the Court of Stars and extract Starlight Thread from his bracers. Progress: Did you get the thread from Melandrus' Star-Touched Bracers ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146680, 146681 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46678 } },
[46681] = { ["id"] = 46681, ["name"] = "The Thread of Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46681 }, ["description"] = "Have you ever had a chance to lay eyes on Elisande, Grand Magistrix of the Nightborne? Stunning! Fashion-forward! Nice posture! You'd do well to take a page from her book! In fact, you'd tell well to take the thread from her Suramari Soul Wraps! These hold great symbolic value to her people so it's doubtful she will give them willingly. So be it, take her out and get that thread.", ["objectivesText"] = "Defeat Grand Magistrix Elisande in the Nighthold and extract Soul Thread from her wraps. Progress: Grand Magistrix Elisande's Soul Wraps have the most beautiful thread! I don't meant to be pushy but... I'm waiting.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146682, 146683 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46678 } },
[46682] = { ["id"] = 46682, ["name"] = "Drapings of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46682 }, ["series"] = { 46679, 46680, 46683 }, ["description"] = "<name>, we are going to need a high quality cloth to work with. Thankfully, the weaving quality of nightborne craftspeople from long ago was very good. It is a lost art to some degree but I feel like you can take their masterworks and do even more with it. Some of the hostiles in these parts still wear Ancient Imbued Silkweave Armor . Start to unstitch the silkweave cloth from any of that armor that you find on Broken Shore.", ["objectivesText"] = "Obtain 100 Ancient Imbued Silkweave from humanoids in Broken Shore. Progress: Keep your eye out for Ancient Imbued Silkweave . We need a lot of it to start making fabulous things.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146666, 146684, 146685 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46678 } },
[46683] = { ["id"] = 46683, ["name"] = "Starweave and Shadowcloth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46683 }, ["series"] = { 46679, 46680, 46682 }, ["description"] = "At last, you are ready for true tailoring knowledge. I truly think you've earned it. I've fashioned the materials you've gathered into a satchel of Legendary Tailor's Materials . Go to the Queen's Grace Loom and weave two bolts of cloth. With my careful research of fashion, heroes, and legends. I believe the new cloth you will make will echo through the ages. Hurry!", ["objectivesText"] = "Make a bolt of Starweave and a bolt of Shadowcloth . Progress: Please make a bolt of Starweave and a bolt of Shadowcloth at the loom as soon as you can and bring it back to me for final inspection.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146659, 146666, 146710, 146711, 146952, 147437, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46679, 46680, 46681, 46682 } },
[46684] = { ["id"] = 46684, ["name"] = "The Legend of the Elderhide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46684 }, ["description"] = "Leatherworking is one of the oldest forms of craftsmanship in the world. Hides of animals were the first clothing. Legends tell of a particular form of leather curing that has been lost to us in modern times. Combining magic of the earth with some of the finest leathers ever found, this technique has been recreated by yours truly through careful analysis and my understanding of style. To begin, you must capture some ancient wisps to channel the exact nature magic for the curing process.", ["objectivesText"] = "Capture Ancient Wisps in Val'sharah. Progress: Have you found an Ancient Wisp ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124124, 146659, 146669, 146712 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46804 } },
[46685] = { ["id"] = 46685, ["name"] = "The Wisp and the Shadow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46685 }, ["series"] = { 46686, 46687, 46688, 46689 }, ["description"] = "<name>, have you heard of the nightmare lord, Xavius, whose shade haunts Darkheart Thicket? I have heard that this shade is sometimes seen wearing a colorless shroud. This shroud is steeped in powerful magic and the wisp will draw it out for you. If you can fight the shade, take the shroud, and use your skills to dye it, I will show you how to work wonders!", ["objectivesText"] = "Defeat the Shade of Xavius in Darkheart Thicket on Mythic Difficulty and dye his shroud. Progress: Have you obtained and dyed the shroud yet? Make your way to Darkheart Thicket and get it done.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146686, 146687 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46684 } },
[46686] = { ["id"] = 46686, ["name"] = "The Wisp and the Sea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46686 }, ["series"] = { 46685, 46687, 46688, 46689 }, ["description"] = "Queen Azshara and her handmaidens are the subjects of many a tragic tale. Her power and her hubris lead her badly astray but, even so, her handmaidens are loyal to her to this day. There is power in such a thing. The Wrath of Azshara is an abomination but, truthfully, it is actually one of her handmaidens who willingly gave her life to protect her queen. Few know this. The Ancient Wisp knows this truth and if you take it to battle the Wrath of Azshara, you may find the handmaiden's gloves. Restore them.", ["objectivesText"] = "Retrieve the Waterlogged Handmaiden's Gloves from the Wrath of Azshara on Mythic Difficulty, then treat them. Progress: You need to battle the Wrath of Azshara and find and restore a pair of handmaiden's gloves.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146688, 146689 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46684 } },
[46687] = { ["id"] = 46687, ["name"] = "The Wisp and the Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46687 }, ["series"] = { 46685, 46686, 46688, 46689 }, ["description"] = "Xavius, the Nightmare Lord in Val'Sharah, derives some of his power from his spellsash. It is enchanted and tied to the world beneath his feet and cannot be removed from his body. However, with the ancient wisp's help, the spellsash can be removed if you can but defeat Xavius in combat. Trivial for one of your skill, I'm sure. Take the wisp to the Emerald Nightmare, take the spellsash, and use your skills to repair any damage you've caused in the battle.", ["objectivesText"] = "Get the spellsash from Xavius in the Emerald Nightmare and repair it. Progress: <name>, defeat Xavius and obtain his spellsash for me. Make sure that it is repaired to perfect condition!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146690, 146691 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46684 } },
[46688] = { ["id"] = 46688, ["name"] = "Leather of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46688 }, ["series"] = { 46685, 46686, 46687, 46689 }, ["description"] = "<name>, we are going to need high quality leather to work with. Ancient Dreadleather is the best hereabouts and local tanning techniques were exceptional in the past. To the untrained eye, it may look like normal dreadleather. That is where the wisp comes in. Many of your enemies across Broken Shore will have some amount of Ancient Dreadleather . As you defeat them, you will start to recognize armor made from it and you can harvest the leather for our purposes.", ["objectivesText"] = "Obtain 100 pieces of Ancient Dreadleather from humanoids in Broken Shore. Progress: Keep your eye out for ancient dreadleather . We will need a good amount for our purposes.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146692, 146693, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46684 } },
[46689] = { ["id"] = 46689, ["name"] = "Wisp-Touched Elderhide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46689 }, ["series"] = { 46685, 46686, 46687, 46688 }, ["description"] = "Dreadleather, with knowledge carefully reverse-engineered from ancient texts, can be worked into elderhide. It is partly a matter of advanced craftsmanship and partly a simple magic of the earth. With the ancient wisps you caught and the materials you've captured and the research I have done, I have put together a Legendary Tanner's Kit for you. Take it to the heirloom hides of Hrul Sharptooth in Thunder Totem. The wisp will help you use the kit there to create Elderhide.", ["objectivesText"] = "Use the Legendary Tanner's Kit in Hrul Sharptooth's dwelling in Thunder Totem. Progress: Hrul Sharptooth has hides in his dwelling in Thunder Totem. When you approach them, you will be able to use your kit. Bring it back to me for final inspection.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146712, 146977, 147438 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46685, 46686, 46687, 46688 } },
[46690] = { ["id"] = 46690, ["name"] = "The Legend of the Wardenscale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46690 }, ["description"] = "One of my favorite legends is of the Father of Owls on Isle of the Watchers. It is said that his spirit comes to comfort his creatures during times of trouble. With the Legion's arrival on the Isle of Watchers, many of the owls are being slain so you can find him there. We need to \"borrow\" him for a short time as he has seen many of the battles where famous warriors and villains have worn armor made of Wardenscale. With his spirit, you can identify items we can extract it from and use it for style!", ["objectivesText"] = "Capture the Father of Owls on the Isle of the Watchers. Progress: Have you captured the Father of Owls yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147075, 147116 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46804 } },
[46691] = { ["id"] = 46691, ["name"] = "The Owl and the Traitor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46691 }, ["series"] = { 46692, 46693, 46694, 46695 }, ["description"] = "I've scoured the tales and legends for armor that might have Wardenscale components and one Cordana Felsong is a name that caught my attention. Evidently she has a family mantle that has what we need. Kill her and find it on her traitor's corpse. The owl will make sure that you spot it. It is likely chipped from years of hard use so restore it to prime condition and bring it back to me.", ["objectivesText"] = "Find and repair Cordana Felsong's Mantle in the Vault of the Wardens in Mythic difficulty. Progress: Have you gotten Cordana's mantle and restored it yet? Rumor has it she is in the Vault of the Wardens.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146694, 146695 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46690 } },
[46692] = { ["id"] = 46692, ["name"] = "The Owl and the Dreadlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46692 }, ["series"] = { 46691, 46693, 46694, 46695 }, ["description"] = "The demon Mephistroth is one of the most powerful of the Nathrezim--the dreadlords. I can see in your eyes that you know what I am going to ask you to do. But it is for your own good! You can't keep wandering the lands looking like you do. Most recently, Mephistroth has been dispatched by the Legion to the Cathedral of Eternal Night. No doubt, he will be wearing some legplates that I believe contain Wardenscale. Take them, shine them up, and bring them to me.", ["objectivesText"] = "Find and restore the Legplates of Mephistroth by defeating him in the Cathedral of Eternal Night in Mythic Difficulty. Progress: Have you defeated Mephistroth and added some shine to his legplates?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146696, 146697 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46690 } },
[46693] = { ["id"] = 46693, ["name"] = "The Owl and the Observer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46693 }, ["series"] = { 46691, 46692, 46694, 46695 }, ["description"] = "I've researched some foul creatures in my time but Viz'aduum the Watcher may top the list. I mean, he is a giant, disgusting, dangerous eyeball! Currently he haunts Karazhan--do you know the place? In Medivh's time, much of our common knowledge was stored there. Alas, the time has passed... I digress. Viz'aduum is in possession of armor from the First War--bracers to be specific--and they are incredibly valuable. It pains me but take them, repair them, and then we must use their wardenscale.", ["objectivesText"] = "Kill Viz'aduum in the Return to Karazhan dungeon on Mythic difficulty, and retrieve and repair the Bracers of the First War. Progress: Have you killed that horrible beast and brought me the Bracers of the First War?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146698, 146699 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46690 } },
[46694] = { ["id"] = 46694, ["name"] = "Mail of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46694 }, ["series"] = { 46691, 46692, 46693, 46695 }, ["description"] = "There is some wardenscale scattered here and there in the Broken Isles. Various enemies and local monsters seeking to ape the superior races like ourselves will have picked it up and worn it. The kind we need is amongst the oldest ever made. It is ancient gravenscale . Keep all that you find and and bring it to me. We will harvest what useful bits we can from it.", ["objectivesText"] = "Obtain 100 Ancient Gravenscale from humanoids in Broken Shore. Progress: Do you have the Ancient Gravenscale that we need?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146700, 146701 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46690 } },
[46695] = { ["id"] = 46695, ["name"] = "Prime Wardenscale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46695 }, ["series"] = { 46691, 46692, 46693, 46694 }, ["description"] = "I feel like it is finally time for use to create something truly remarkable. To create the armor that will set you apart from the rest, we need to make the best wardenscale. Find the nightelf, Celea, in Azsuna. She has attuned and sanctified the ground where she waits to focus the magic of our world and only there can you make what we need. Go with speed, <name>.", ["objectivesText"] = "Find Celea in Azsuna and create the Wardenscale where the magic aligns. Progress: Have you found Celea in Azsuna and prepared the Wardenscale beside her? It will only work at that spot. Bring it back to me when you have finished.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146713, 147209, 147439 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46691, 46692, 46693, 46694 } },
[46696] = { ["id"] = 46696, ["name"] = "The Legend of the Four Hammers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46696 }, ["description"] = "<name>, we should be honest with each other before we begin. You are a blacksmith by trade and this a noble profession. Yet I value style and fashion. Heavy armor and weapons create a certain bulkiness in a hero's profile that I think does no service whatsoever to the cut of one's clothes. Fret not--I can at least teach you something about taste in finer materials. Go to Dalaran and find a book translated by my brother about 3 forgotten heroes. We will find the finest metals ever forged!", ["objectivesText"] = "Go to Dalaran and find the Legend of the Four Hammers. Progress: Did you find that dusty old tome of Fafnir's? I have to admit that he may have found something interesting in it.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 147197 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46804 } },
[46697] = { ["id"] = 46697, ["name"] = "The Godfighter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46697 }, ["series"] = { 46698, 46699, 46700, 46701 }, ["description"] = "The Godfighter championed the mortals against what he saw as oppression and abuse by immortal beings. The legends say the gods feared him but he did fall in time. My research shows that the gods he fought were the gods of Stormheim. Odyn, in particular. The Godfighter's shield took so much damage from lightning bolts that it became lightningsteel. After the Godfighter died, Odyn took the shield and melted it down as a trophy. Get that lightningsteel from him and forge a hammer from it.", ["objectivesText"] = "Take White Lightningsteel from Odyn in the Halls of Valor in Mythic difficulty and forge it into a hammer. Progress: Have you taken the white lightningsteel from Odyn and forged it into a hammer?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 87216, 146667, 146702, 146703 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46696 } },
[46698] = { ["id"] = 46698, ["name"] = "The Dragonhunter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46698 }, ["series"] = { 46697, 46699, 46700, 46701 }, ["description"] = "The Dragonhunter lived in a time before history was written and her tale was passed down orally to us. It seems that dragons tormented her people and after her village temple was destroyed, she rallied the local tribes, became a queen and killed all of the dragons. She was then banished for some reason and wandered until her death, alone. What proves the story is a piece of draconic slag from left over from a metal idol in her birth village. Dargul the Underking has it now. Forge a hammer from it.", ["objectivesText"] = "Defeat Dargul in Neltharion's Lair in Mythic difficulty and create a hammer from his Red-Hot Draconic Slag Progress: Did you find the draconic slag from the Dragonhunter's birth village temple? When you do, forge a hammer from it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146704, 146705 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46696 } },
[46699] = { ["id"] = 46699, ["name"] = "The Hellslayer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46699 }, ["series"] = { 46697, 46698, 46700, 46701 }, ["description"] = "The Hellslayer's tale is a classic story of revenge. Odyn wished to take the souls of the bravest as champions but Helya sent her kvaldir to take the souls first. The people of Stormheim suffered as their pawns. The kvaldir came to the Hellslayer's ship at night and killed her son and took his soul to serve Helya for eternity. The Hellslayer took up her axe and the spear of her son and sought vengeance. Finish her quest. Defeat Helya and forge a hammer from the Frostveined Shale .", ["objectivesText"] = "Defeat Helya and forge a hammer from the Frostveined Shale in the Trial of Valor. Progress: The Frostveined Shale is what remains of the Hellslayer's weapons after they were destroyed on Helya's cold forge. It is powerful stuff and we need it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146706, 146707 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["sourceQuests"] = { 46696 } },
})
